INSERT INTO characters (char, data) VALUES ('錣', '{"9000": "8021.0", "Chữ Trung Quốc": "錣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錣 | chuyết | tượng hình | đầu sắt của roi ngựa | 錣 có bộ 金 (kim — kim loại), nghĩa là đầu sắt gắn ở cuối roi ngựa. Không có chú thích cấu tạo chi tiết. Chữ thuộc nhóm từ ngựa và trang bị kỵ sĩ cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyết\": bộ 金 (sắt) — đầu sắt nhọn gắn cuối roi da, dùng thúc ngựa trong kỵ binh cổ đại. | Gương Hán-Việt | \"chuyết\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 錣 giúp đọc văn bản kỵ binh và trang bị chiến tranh cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 錣 là ''đầu sắt ở cuối roi ngựa'' (iron tip at the end of a horse whip). Bộ 金 (kim) chỉ vật làm bằng sắt/kim loại. Phát âm zhuì hoặc chuò. Chữ thuộc từ vựng kỵ binh và trang bị ngựa cổ đại. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dùi sắt (ở cán roi ngựa để thúc ngựa.)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錣", "Unihan_Traditional (Chữ Phồn thể)": "錣", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ cái dùi sắt nhọn gắn ở đầu roi thúc ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑢', '{"9000": "8022.0", "Chữ Trung Quốc": "鑢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 23 | nét | 金 | kim | biểu nghĩa | kim loại | 慮 | lự | biểu âm | biểu âm | 鑢 = 金 (kim, biểu nghĩa: kim loại) + 慮 (lự, biểu âm). Wiktionary ghi ls=psc (hình thanh). Nghĩa: cái dũa/giũa (file/rasp — công cụ mài nhẵn). Đây là chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lự\": 金 (kim loại) + 慮 (lự — suy nghĩ kỹ) — cái dũa đòi hỏi kiên nhẫn và cẩn thận, ''lự'' như người thợ giũa tỉ mỉ. | Gương Hán-Việt | \"lự\" — không thông dụng trong tiếng Việt; cái dũa thường dùng từ thuần Việt. | Mở khoá kiến thức | Biết chữ 鑢 giúp đọc văn bản thủ công nghiệp và luyện kim cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, 鑢 là chữ hình thanh: 金 (kim — kim loại) biểu nghĩa, 慮 (lự) biểu âm. Nghĩa: dũa — công cụ kim loại dùng để mài nhẵn, giũa vật liệu. Âm Hán-Việt ''lự'' từ 慮. Trong tiếng Mân Nam: lù (literary, nghĩa dũa) và lòe/lè (nghĩa khác). Chữ dùng trong văn bản thủ công nghiệp cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giũa; mài giũa; tu tỉnh", "Hạng Tần Suất (Jun Da)": "8022.0", "Tần Suất % (Jun Da)": "99.9993628039", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 慮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金慮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "慮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑢", "Unihan_Traditional (Chữ Phồn thể)": "鑢", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "lự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dụng cụ giũa sắt hoặc động từ chỉ việc mài giũa, tu sửa bản thân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钑', '{"9000": "8023.0", "Chữ Trung Quốc": "钑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钑 | táp | tượng hình | khắc chạm trên kim loại | 钑 có bộ 金 (kim — kim loại), nghĩa liên quan đến khắc chạm hoặc trang trí trên bề mặt kim loại. Wiktionary ghi rfdef (chưa có định nghĩa rõ ràng). Xuất hiện trong 鈒鏤 (khắc chạm tinh xảo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táp\": bộ 金 (kim loại) — chữ dùng trong 鈒鏤, chỉ nghệ thuật khắc chạm tinh xảo trên bề mặt kim loại. | Gương Hán-Việt | \"táp\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 钑 giúp đọc văn bản thủ công mỹ nghệ và luyện kim cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi {{rfdef|zh}} — chưa có định nghĩa chính thức, nhưng chữ xuất hiện trong tổ hợp 鈒鏤 (sà lòu — khắc chạm tinh xảo trên kim loại). Bộ 金 (kim) chỉ liên quan kim loại. Âm sà, sè, xì hoặc jí tùy ngữ cảnh. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gecmani (cũ)", "Hạng Tần Suất (Jun Da)": "8023.0", "Tần Suất % (Jun Da)": "99.9993638375", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钑", "Unihan_Traditional (Chữ Phồn thể)": "鈒", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loại thương ngắn hoặc động từ chỉ việc chạm khắc hoa văn trên kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饟', '{"9000": "8024.0", "Chữ Trung Quốc": "饟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 25 | nét | 食 | thực | biểu nghĩa | ăn, lương thực | 襄 | tương | biểu âm | biểu âm | 饟 = 食 (thực, biểu nghĩa: ăn/lương thực) + 襄 (tương, biểu âm). Wiktionary ghi ls=psc (hình thanh). Nghĩa: lương thực, quân lương. Đây là chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": 食 (lương thực) + 襄 (tương — giúp đỡ) — quân lương được chuyển đến giúp quân đội tiến lên. | Gương Hán-Việt | \"tương\" trong nghĩa quân lương — không thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 饟 giúp đọc văn bản quân sự và hậu cần cổ đại Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 饟 là chữ hình thanh: 食 (thực — lương thực) biểu nghĩa, 襄 (tương) biểu âm. Có hai âm đọc: shāng và xiǎng (lương thực cung cấp cho quân đội). Tiểu triện có hình. Chữ thuộc nhóm từ quân sự liên quan đến lương thực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tỷ giá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饟", "Unihan_Traditional (Chữ Phồn thể)": "饟", "Pinyin_Xie": "xiǎng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ lương thực hoặc động từ chỉ hành động mang cơm nước cho người làm ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯅', '{"9000": "8025.0", "Chữ Trung Quốc": "鯅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鯅 | đình | tượng hình | mắm cá, bột cá | 鯅 có bộ 魚 (ngư — cá), nghĩa là mắm cá hoặc bột cá. Không có chú thích cấu tạo chi tiết. Chưa có dữ liệu ls code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\": bộ 魚 (cá) — mắm cá cổ đại, loại gia vị lên men quan trọng trong ẩm thực Trung Hoa cổ. | Gương Hán-Việt | \"đình\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 鯅 giúp đọc văn bản ẩm thực học và bảo quản thực phẩm cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 鯅 nghĩa là ''fish paste'' (mắm cá), phát âm tíng. Bộ 魚 (ngư) chỉ liên quan đến cá. Chữ thuộc nhóm từ ẩm thực và thực phẩm cổ đại. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯅", "Unihan_Traditional (Chữ Phồn thể)": "鯅", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thư tịch cổ để chỉ một loài cá nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼊', '{"9000": "8026.0", "Chữ Trung Quốc": "鼊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 26 | nét | 鼊 | bích | tượng hình | loài rùa cổ đại | 鼊 là chữ độc lập, không có chú thích cấu tạo chi tiết. Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Âm bì. Liên quan đến loài rùa hoặc bò sát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": chữ cổ đại, có thể chỉ loài rùa; âm ''bích'' gần với ''bích hổ'' (tắc kè) trong tiếng Việt. | Gương Hán-Việt | \"bích\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 鼊 giúp nhận diện tên loài bò sát trong văn bản động vật học cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi {{rfdef|zh}} cho 鼊 — chưa có định nghĩa chính thức. Phát âm bì. Theo một số nguồn học thuật, 鼊 chỉ một loài rùa cổ đại. Chưa có nguồn học thuật xác định cấu trúc; chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 黽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鼊", "Unihan_Traditional (Chữ Phồn thể)": "鼊", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ Đại để tạo thành danh từ ghép chỉ loài rùa biển đồi mồi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粛', '{"9000": "8028.0", "Chữ Trung Quốc": "粛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 11 | nét | 粛 | túc | tượng hình | dị thể của 肅 (túc — nghiêm trang, kính cẩn) | 粛 là dị thể của 肅 (túc), xuất hiện trong kim văn. Không có chú thích cấu tạo riêng trong Wiktionary. Kim văn có nhiều hình dạng. Nghĩa: nghiêm trang, kính cẩn, trang nghiêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\": dị thể cổ của 肅 — nghiêm túc, kính cẩn; âm ''túc'' như ''túc trực'' (canh gác nghiêm trang). | Gương Hán-Việt | \"túc\" trong ''túc trực'', ''túc nghiêm'', ''thanh túc'' — từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết chữ 粛/肅 mở khoá: túc trực, túc nghiêm, thanh túc, tự túc trong nhiều văn cảnh chính thức.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 粛 là dị thể/variant của 肅 (túc — nghiêm trang). Kim văn có nhiều hình biến thể (3 bản bronze, 1 seal, 2 liushutong). Nghĩa gốc của 肅: trang nghiêm, kính trọng, dọn dẹp. Chữ quan trọng trong văn bản lễ nghi. Chưa có nguồn học thuật chi tiết về sự phân kỳ dạng viết 粛 vs 肅. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粛", "Hạng Tần Suất (Jun Da)": "8028.0", "Tần Suất % (Jun Da)": "99.9993700389", "GavinGrover_Once (Chiết tự trực tiếp)": "⺺ + 𫃢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺺𫃢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𫃢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺺", "Unihan_Simplified (Chữ Giản thể)": "粛", "Unihan_Traditional (Chữ Phồn thể)": "粛", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả trạng thái nghiêm trang, cung kính hoặc bầu không khí yên lặng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粻', '{"9000": "8029.0", "Chữ Trung Quốc": "粻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粻 | chương | tượng hình | lương thực, thức ăn dự trữ | 粻 có bộ 米 (mễ — gạo/ngũ cốc), nghĩa là lương thực hoặc thức ăn dự trữ. Không có chú thích cấu tạo chi tiết. Chưa có dữ liệu ls code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": bộ 米 (gạo) — lương thực dự trữ, âm ''chương'' gần với ''chương trình lương thực'' trong tư duy. | Gương Hán-Việt | \"chương\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 粻 giúp đọc văn bản nông nghiệp và hậu cần cổ đại Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 粻 nghĩa là ''provisions/food'' (lương thực), phát âm zhāng. Bộ 米 (mễ — gạo) biểu nghĩa liên quan đến lương thực. Chữ thuộc nhóm từ nông nghiệp và hậu cần cổ đại. Chưa có nguồn học thuật chi tiết về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ăn; cơm trắng nấu chín", "Hạng Tần Suất (Jun Da)": "8029.0", "Tần Suất % (Jun Da)": "99.9993710725", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 長", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米長", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "長", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粻", "Unihan_Traditional (Chữ Phồn thể)": "粻", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "trương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lương thực hoặc cơm gạo, thường dùng trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞂', '{"9000": "8030.0", "Chữ Trung Quốc": "瞂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 瞂 | phạt | tượng hình | tấm khiên nhỏ (vũ khí phòng thủ) | 瞂 có bộ 目 (mục — mắt) hoặc bộ tương tự. Wiktionary ghi nghĩa ''small shield'' (khiên nhỏ). Không có chú thích cấu tạo chi tiết. Chữ thuộc nhóm vũ khí và trang bị chiến tranh cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạt\": chữ chỉ tấm khiên nhỏ trong vũ trang cổ đại — dùng để che đỡ khi tấn công. | Gương Hán-Việt | \"phạt\" — trong tiếng Việt ''phạt'' thường có nghĩa ''trừng phạt'', không liên quan trực tiếp đến nghĩa chữ này. | Mở khoá kiến thức | Biết chữ 瞂 giúp đọc văn bản quân sự và khảo cổ học về vũ khí cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 瞂 nghĩa là ''khiên nhỏ'' (small shield), phát âm fá hoặc fā. Chữ thuộc lĩnh vực vũ khí/trang bị quân sự cổ đại. Chưa có chú thích cấu tạo chi tiết; chưa có nguồn học thuật xác định ls code. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Trốn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "盾 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰盾犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "盾", "Unihan_Simplified (Chữ Giản thể)": "瞂", "Unihan_Traditional (Chữ Phồn thể)": "瞂", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "phạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ cái khiên dùng để che chắn trong chiến trận thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靮', '{"9000": "8031.0", "Chữ Trung Quốc": "靮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 12 | nét | 靮 | đích | tượng hình | dây cương, dây buộc ngựa | 靮 có bộ 革 (cách — da thuộc), nghĩa là dây cương hoặc dây buộc ngựa. Không có chú thích cấu tạo chi tiết. Chữ thuộc nhóm từ ngựa và kỵ sĩ cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đích\": bộ 革 (da thuộc) — dây cương da buộc vào miệng ngựa để điều khiển, âm ''đích'' như ''đích thực'' tay nghề kỵ sĩ. | Gương Hán-Việt | \"đích\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 靮 giúp đọc văn bản kỵ binh và trang bị ngựa cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 靮 nghĩa là ''cương ngựa/dây buộc'' (reins, bridle), phát âm dí, dùng trong văn cổ. Bộ 革 (cách — da thuộc) biểu nghĩa vật làm bằng da. Tiểu triện có hình. Chữ thuộc từ vựng cưỡi ngựa và kỵ binh cổ đại. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương ngựa", "Hạng Tần Suất (Jun Da)": "8031.0", "Tần Suất % (Jun Da)": "99.9993762403", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靮", "Unihan_Traditional (Chữ Phồn thể)": "靮", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "đích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ sợi dây cương dùng để điều khiển ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盨', '{"9000": "8032.0", "Chữ Trung Quốc": "盨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 17 | nét | 須 | tua | biểu âm | biểu âm | 皿 | mãnh | biểu nghĩa | đồ đựng, bình chứa | 盨 = 須 (tua, biểu âm) + 皿 (mãnh, biểu nghĩa: đồ đựng). Wiktionary ghi ls=psc (hình thanh). Nghĩa: 盨 (xu) — một loại bình/hộp đồng thanh dùng đựng thức ăn trong nghi lễ thời Tây Chu. Đây là chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": 皿 (đồ đựng) + 須 (tua) — bình 盨 đồng thanh hình bầu dục, dùng trong tế lễ Tây Chu. | Gương Hán-Việt | \"tu\" trong 盨 — dùng trong khảo cổ học; không thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 盨 giúp đọc văn bản khảo cổ học và nghiên cứu đồ đồng thau Tây Chu.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 盨 là chữ hình thanh: 皿 (mãnh — đồ đựng) biểu nghĩa, 須 (tua) biểu âm. Nghĩa: xu — loại bình đồng thanh hình bầu dục dùng trong lễ nghi thời Tây Chu (khoảng 1046-771 TCN). Bình 盨 thường đi theo bộ, dùng đựng ngũ cốc dâng tế. Tiểu triện và kim văn có hình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liễn đồng; liễn (có chân)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "須 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱須皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "須", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盨", "Unihan_Traditional (Chữ Phồn thể)": "盨", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "hủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại đồ đựng thức ăn bằng đồng có nắp và tai thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('県', '{"9000": "8033.0", "Chữ Trung Quốc": "県", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 県 | huyện | tượng hình | dị thể Nhật-Trung cổ của 縣 (huyện — đơn vị hành chính) | 県 là dạng chữ dùng trong tiếng Nhật và một số dạng cổ tiếng Trung, tương đương với 縣 (huyện). Không có chú thích cấu tạo riêng trong Wiktionary tiếng Trung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyện\": dạng viết tắt của 縣 — đơn vị hành chính ''huyện'' quen thuộc trong địa danh Việt Nam. | Gương Hán-Việt | \"huyện\" — rất thông dụng trong tiếng Việt: huyện Hoàn Kiếm, huyện Đống Đa... | Mở khoá kiến thức | Biết chữ 県/縣 mở khoá từ Hán-Việt ''huyện'' — đơn vị hành chính phổ biến ở Việt Nam và Trung Quốc.", "Tự nguyên_Xie": "県 là dạng rút gọn hoặc Nhật hoá của 縣 (xuàn/xiàn — huyện, đơn vị hành chính địa phương). Trong tiếng Nhật, 県 (ken) là đơn vị hành chính cấp tỉnh. Trong tiếng Trung cổ, 縣 gốc có nghĩa ''treo lơ lửng'' sau chuyển nghĩa thành đơn vị địa phương. Không có nguồn học thuật tiếng Trung riêng về 県. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "903.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (121) Tiểu (060)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mục (số 121 - con mắt), nét gập vuông (乚) và bộ Tiểu (số 060 - nhỏ). Giống hình cái đầu của tội nhân bị treo ngược, tóc tai xõa xuống. Giải thích sự chuyển ý: Đây là chữ Tượng hình (hoặc Hội ý). Huyền là buộc, trói buộc, treo ngược.", "Nghĩa Tiếng Việt_Xie": "tỉnh", "Hạng Tần Suất (Jun Da)": "8033.0", "Tần Suất % (Jun Da)": "99.9993783075", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 小", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱小", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "県", "Unihan_Traditional (Chữ Phồn thể)": "県", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "huyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đơn vị hành chính cấp huyện ở Trung Quốc hoặc cấp tỉnh ở Nhật Bản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箥', '{"9000": "8034.0", "Chữ Trung Quốc": "箥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箥 | bá | tượng hình | rổ tre, dụng cụ đan bằng tre | 箥 có bộ 竹 (trúc — tre), nghĩa là rổ hoặc sàng làm bằng tre. Không có chú thích cấu tạo chi tiết trong Wiktionary. Chữ thuộc nhóm đồ dùng gia đình truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": bộ 竹 (tre) — rổ tre đan tay thủ công, vật dụng quen thuộc trong cuộc sống nông thôn cổ đại. | Gương Hán-Việt | \"bá\" — không có từ Hán-Việt thông dụng dùng chữ này trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết chữ 箥 giúp đọc văn bản thủ công mỹ nghệ và đồ dùng gia đình cổ đại.", "Tự nguyên_Xie": "Không có giải thích cấu tạo trong Wiktionary cho 箥. Bộ 竹 (trúc — tre) biểu nghĩa chỉ đây là đồ vật làm từ tre. Nghĩa: rổ tre hoặc dụng cụ đan bằng tre. Chữ thuộc nhóm từ đồ dùng gia đình và nông nghiệp truyền thống. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 波", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮波", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "波", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箥", "Unihan_Traditional (Chữ Phồn thể)": "箥", "Pinyin_Xie": "bǒ", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong từ ghép để chỉ dụng cụ tre dùng sàng sảy lương thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簕', '{"9000": "8035.0", "Chữ Trung Quốc": "簕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 勒 | lặc | biểu âm | 簕 = 竹 (Trúc, biểu nghĩa: tre trúc) + 勒 (Lặc, biểu âm); chữ hình thanh — bộ trúc chỉ loại thực vật, 勒 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lặc\": cây tre (竹) bị \"siết lại\" (勒) bởi những chiếc gai nhọn — đó là簕, loài tre gai đặc trưng vùng Hoa Nam. | Gương Hán-Việt | lặc — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 簕 giúp nhận ra các tên thực vật phương ngữ Quảng Đông liên quan gai nhọn.", "Tự nguyên_Xie": "Wiktionary ghi chú {{Han etym|勒}}, cho thấy 簕 dùng 竹 (tre) làm bộ nghĩa và 勒 làm phần biểu âm. Chữ chỉ loại tre có gai, thường dùng trong tiếng Quảng Đông (lak). Không có giáp cốt hay kim văn ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簕", "Hạng Tần Suất (Jun Da)": "8035.0", "Tần Suất % (Jun Da)": "99.9993803746", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 勒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮勒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簕", "Unihan_Traditional (Chữ Phồn thể)": "簕", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại tre có gai hoặc phần gai của cây tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臖', '{"9000": "8036.0", "Chữ Trung Quốc": "臖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 20 | nét | 臖 | hạnh | tượng hình | sưng tấy, nổi u | 臖 là chữ độc thể, bộ 肉 (nhục) cho thấy liên quan đến thân thể. Không có nguồn phân tích thành phần rõ ràng; Wiktionary chỉ ghi {{Han etym}} mà không có chi tiết cấu trúc. Chữ chỉ trạng thái sưng tấy của cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạnh\": phần thịt (肉) của cơ thể bỗng \"hạnh\" — nổi lên, sưng phù như một khối u nhỏ dưới da. | Gương Hán-Việt | hạnh — ít gặp trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết bộ 肉 (nhục) giúp nhận ra các chữ liên quan đến cơ thể và bệnh lý.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} nhưng không cung cấp phân tích glyph cụ thể. Chữ thuộc bộ 肉 (nhục/thịt), nghĩa là sưng tấy. Có trung cổ âm và thượng cổ âm ghi nhận, cho thấy chữ khá cổ, nhưng nguồn học thuật chi tiết chưa rõ. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sưng tấy; sưng lên", "Hạng Tần Suất (Jun Da)": "8036.0", "Tần Suất % (Jun Da)": "99.9993814082", "GavinGrover_Once (Chiết tự trực tiếp)": "興 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱興月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "興", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臖", "Unihan_Traditional (Chữ Phồn thể)": "臖", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ hoặc tính từ miêu tả trạng thái da thịt bị sưng tấy lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盿', '{"9000": "8037.0", "Chữ Trung Quốc": "盿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 盿 | mẫn | tượng hình | nhìn chằm chằm, mắt nhìn | 盿 thuộc bộ 目 (mục, mắt). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc. Chữ có trung cổ âm và thượng cổ âm, liên quan đến hành động nhìn. Coi là chữ độc thể thuộc bộ 目.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": đôi mắt (目) \"mẫn cảm\" — nhìn chăm chú, tinh tường, như ánh mắt của người quan sát sắc sảo. | Gương Hán-Việt | mẫn — ít dùng, chủ yếu trong văn bản học thuật | Mở khoá kiến thức | Bộ 目 (mục) nối 盿 với các chữ về thị giác: 眼, 瞳, 睛, 盲.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} không có phân tích glyph. Bộ 目 (mắt) gợi ý liên quan đến hành động thị giác. Chữ hiếm gặp, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "盿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盿", "Unihan_Traditional (Chữ Phồn thể)": "盿", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng như một động từ chỉ hành động nhìn hoặc quan sát trong văn ngôn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔊', '{"9000": "8038.0", "Chữ Trung Quốc": "蔊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔊 | hản | tượng hình | cây rau hản, một loại rau dùng làm thuốc | 蔊 thuộc bộ 艹 (thảo, cỏ cây). Wiktionary ghi {{Han etym}} nhưng không phân tích cụ thể thành phần. Chữ chỉ dùng trong 蔊菜 (một loại rau dại). Coi là chữ chuyên biệt cho cây này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hản\": loại cỏ (艹) mọc ở vùng \"hản\" — thấp ẩm, dùng làm thuốc — đó là 蔊, cây rau dại họ cải. | Gương Hán-Việt | hản — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 蔊 giúp đọc văn bản y học cổ truyền và thực vật học Hán ngữ.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ dùng trong tên 蔊菜 (Cardamine/Rorippa — loại rau dại họ cải). Không có phân tích glyph rõ. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại rau, thân không có lông, hoa vàng, dùng làm thuốc)", "Hạng Tần Suất (Jun Da)": "8038.0", "Tần Suất % (Jun Da)": "99.9993876096", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 焊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹焊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔊", "Unihan_Traditional (Chữ Phồn thể)": "蔊", "Pinyin_Xie": "hǎn", "Âm Hán Việt_Xie": "hản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong y học cổ truyền hoặc thực vật học để chỉ loài rau cải đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶸', '{"9000": "8039.0", "Chữ Trung Quốc": "鶸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鶸 | nhược | tượng hình | chim siskin, màu vàng lục nhạt | 鶸 thuộc bộ 鳥 (điểu, chim). Không có phân tích thành phần từ Wiktionary. Chữ chỉ loài chim siskin (họ sẻ) có màu vàng lục nhạt đặc trưng. Coi là chữ độc thể trong bộ 鳥.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": con chim (鳥) \"nhược\" — nhỏ bé, màu vàng lục nhạt như chiếc lá non — đó là 鶸, chim siskin xinh xắn. | Gương Hán-Việt | nhược — ít dùng độc lập trong từ Hán-Việt | Mở khoá kiến thức | Bộ 鳥 liên kết 鶸 với các chữ tên chim: 鵲, 鶯, 燕, 雀.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph cho 鶸. Bộ 鳥 (điểu) xác nhận đây là chữ chỉ loài chim. 鶸 còn dùng làm tính từ chỉ màu vàng lục nhạt (màu lông chim siskin). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "siskin", "Hạng Tần Suất (Jun Da)": "8039.0", "Tần Suất % (Jun Da)": "99.9993917439", "GavinGrover_Once (Chiết tự trực tiếp)": "弱 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弱鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶸", "Unihan_Traditional (Chữ Phồn thể)": "鶸", "Pinyin_Xie": "ruò", "Âm Hán Việt_Xie": "nhược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong danh pháp điểu học để chỉ một loài chim nhỏ thuộc họ sẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窎', '{"9000": "8040.0", "Chữ Trung Quốc": "窎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 窎 | điểu | tượng hình | sâu xa, xa xôi hẻo lánh | 窎 thuộc bộ 穴 (huyệt, hang hốc). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc cụ thể. Bộ 穴 gợi ý sự sâu thẳm, ẩn kín. Có kim văn và tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điểu\": cái hang (穴) sâu thẳm, xa tít — đó là 窎, cảnh sắc xa xôi hẻo lánh trong thơ văn cổ. | Gương Hán-Việt | điểu — ít gặp trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 穴 liên kết 窎 với không gian ẩn sâu: 空, 窗, 窝, 窟.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary ghi {{Han etym}} có kim văn và tiểu triện. Bộ 穴 (hang hốc) gợi ý nghĩa sâu xa, hẻo lánh. Chữ dùng trong văn học chỉ nơi xa xôi, sâu thẳm (窵遠 diào yuǎn). Có trung cổ âm và thượng cổ âm ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu xa", "Hạng Tần Suất (Jun Da)": "8040.0", "Tần Suất % (Jun Da)": "99.999393811", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鸟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窎", "Unihan_Traditional (Chữ Phồn thể)": "窵", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để tả không gian sâu thẳm hoặc xa xôi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉔', '{"9000": "8041.0", "Chữ Trung Quốc": "鉔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鉔 | trách | tượng hình | tiếng rắc, tiếng xước | 鉔 thuộc bộ 金 (kim, kim loại). Không có phân tích thành phần từ Wiktionary. Bộ 金 gợi ý tiếng kim loại cọ xát hoặc cắt. Chữ mô phỏng âm thanh rắc rắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": kim loại (金) phát ra tiếng \"trách\" — cọ xát, cào lên bề mặt cứng — đó là 鉔. | Gương Hán-Việt | trách — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Bộ 金 liên kết 鉔 với nhóm chữ công cụ kim loại và âm thanh.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph cho 鉔. Bộ 金 (kim loại) kết hợp với nghĩa tượng thanh — tiếng rắc, tiếng xước của dụng cụ kim loại. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng rắc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 匝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金匝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉔", "Unihan_Traditional (Chữ Phồn thể)": "鉔", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này thường dùng làm từ tượng thanh để mô tả âm thanh gõ hoặc va chạm của kim loại. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏱', '{"9000": "8042.0", "Chữ Trung Quốc": "鏱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏱 | chương | tượng hình | tên một loại dụng cụ kim loại | 鏱 thuộc bộ 金 (kim, kim loại). Không có phân tích thành phần từ Wiktionary và không có âm đọc chuẩn rõ ràng (Wiktionary ghi ''zhang''). Bộ 金 xác nhận liên quan đến đồ kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": một vật bằng kim (金) có \"chương\" — hình dáng hay đặc điểm riêng biệt — đó là 鏱, dụng cụ kim loại cổ hiếm gặp. | Gương Hán-Việt | chương — ít gặp trong từ Hán-Việt | Mở khoá kiến thức | Bộ 金 liên kết 鏱 với nhóm chữ dụng cụ kim loại.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph hay âm đọc cụ thể cho 鏱. Bộ 金 (kim loại) xác nhận liên quan đến dụng cụ kim loại. Chữ rất hiếm, không có ghi nhận học thuật rõ ràng. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鏱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏱", "Unihan_Traditional (Chữ Phồn thể)": "鏱", "Pinyin_Xie": "zhang", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ chỉ các loại đồ dùng hoặc nhạc khí làm bằng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隺', '{"9000": "8043.0", "Chữ Trung Quốc": "隺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 10 | nét | 隺 | hộc | tượng hình | chim bay cao, chí hướng cao xa | 隺 thuộc bộ 隹 (chuy, chim đuôi ngắn). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ chim bay cao vút, từ đó ẩn dụ chí hướng cao xa. Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộc\": con chim (隹) \"hộc\" lên — bay vút lên trời cao — đó là 隺, hình ảnh chim hạc soải cánh vươn tầm. | Gương Hán-Việt | hộc — ít dùng; chính dạng phổ biến là 鶴 (hạc) | Mở khoá kiến thức | Biết 隺 giúp đọc văn học cổ về chí hướng và hình ảnh chim hạc trong thơ phú.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} với tiểu triện. Bộ 隹 (chim đuôi ngắn) cho thấy chữ thuộc nhóm chim. 隺 nghĩa là chim bay rất cao, cực kỳ cao; cũng dùng nghĩa bóng về chí hướng cao xa, tham vọng lớn. Là dị thể cổ của 鶴 (hạc). Chữ có hai âm đọc: hú/hè và què. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱巾隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "隺", "Unihan_Traditional (Chữ Phồn thể)": "隺", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ loài chim hộc hoặc động từ chỉ hành động bay cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荘', '{"9000": "8044.0", "Chữ Trung Quốc": "荘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荘 | trang | tượng hình | trang trại, làng xã, nghiêm trang | 荘 thuộc bộ 艹 (thảo). Wiktionary không cung cấp phân tích glyph. Đây là dị thể Nhật Bản/phồn thể đặc biệt của 莊 (trang). Có kim văn và tiểu triện ghi nhận qua chữ gốc 莊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trang\": cỏ (艹) mọc phủ kín \"trang\" trại — đó là 荘/莊, khu đất rộng lớn của điền trang, gia trang. | Gương Hán-Việt | trang — dùng trong \"trang trại\", \"trang nghiêm\", \"trang tử\" (triết gia) | Mở khoá kiến thức | Biết 荘/莊 mở khóa: 莊嚴 (trang nghiêm), 農莊 (nông trang), 莊子 (Trang Tử), 山莊 (sơn trang).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 荘 là dị thể của 莊 (trang), dùng trong tiếng Nhật và một số văn bản phồn thể đặc biệt. Chữ gốc 莊 có kim văn và tiểu triện. Nghĩa: trang trại, gia trang, làng xã; cũng có nghĩa nghiêm trang, đứng đắn. Họ Trang (Zhuāng) nổi tiếng qua triết gia Trang Tử (莊子). Chưa có phân tích glyph riêng cho dị thể 荘. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trang trại, gia trang; họ Trang", "Hạng Tần Suất (Jun Da)": "8044.0", "Tần Suất % (Jun Da)": "99.9994000125", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 壮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹壮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荘", "Unihan_Traditional (Chữ Phồn thể)": "荘", "Pinyin_Xie": "zhuāng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ nơi thôn dã hoặc tính từ mô tả dáng vẻ nghiêm túc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒻', '{"9000": "8045.0", "Chữ Trung Quốc": "蒻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒻 | nhược | tượng hình | chồi non của cây hương bồ, đọt tre non | 蒻 thuộc bộ 艹 (thảo). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ chồi non mềm mại của cây hương bồ (cattail) hay đọt tre. Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": cây cỏ (艹) còn \"nhược\" — mềm mại, non tơ như chồi hương bồ mới nhú — đó là 蒻. | Gương Hán-Việt | nhược — xuất hiện trong \"蒟蒻\" (konjac/khoai nưa) | Mở khoá kiến thức | Biết 蒻 giúp nhận ra 蒟蒻 (konjac) — nguyên liệu thạch đặc biệt trong ẩm thực Đông Á.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} có tiểu triện. Chữ chỉ \"young cattail\" — chồi non của cây hương bồ, thân mềm mại ven nước. Cũng dùng trong 蒟蒻 (konjac — cây khoai nưa). Chữ có thượng cổ âm ghi nhận, xuất hiện từ thời cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ nhược, cỏ hương bồ", "Hạng Tần Suất (Jun Da)": "8045.0", "Tần Suất % (Jun Da)": "99.999401046", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 弱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹弱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒻", "Unihan_Traditional (Chữ Phồn thể)": "蒻", "Pinyin_Xie": "ruò", "Âm Hán Việt_Xie": "nhược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ mềm hoặc cây nưa trong thực vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔴', '{"9000": "8046.0", "Chữ Trung Quốc": "蔴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔴 | ma | tượng hình | cây gai dầu, cây lanh | 蔴 thuộc bộ 艹 (thảo). Wiktionary không cung cấp phân tích glyph. Đây là dị thể của 麻 (ma), dùng bộ 艹 thay vì 广+林. Chữ chỉ cây gai (hemp, flax) dùng lấy sợi dệt vải.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ma\": loại cỏ (艹) đặc biệt gọi là \"ma\" — cây gai dầu, sợi dệt quần áo của người nghèo xưa. | Gương Hán-Việt | ma — dùng trong \"ma túy\", \"mê man\", \"gai ma\" (cây gai) | Mở khoá kiến thức | Biết 蔴/麻 mở khóa: 麻布 (vải lanh), 芝麻 (vừng mè), 麻木 (tê liệt), 胡麻 (mè/hồ ma).", "Tự nguyên_Xie": "蔴 là dị thể của 麻 (ma, cây gai dầu). Chữ gốc 麻 có giáp cốt văn ghi nhận, mô tả sợi gai phơi dưới mái nhà (广+林). 蔴 dùng bộ 艹 nhấn mạnh đây là cây cỏ. Nghĩa: cây gai, vải gai. Không có phân tích glyph riêng cho dị thể 蔴. chưa có nguồn học thuật đầy đủ cho dị thể này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây gai", "Hạng Tần Suất (Jun Da)": "1106.0", "Tần Suất % (Jun Da)": "90.7138935999", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 麻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹麻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "麻", "Unihan_Traditional (Chữ Phồn thể)": "蔴", "Pinyin_Xie": "má", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại cây lấy sợi như cây gai hoặc cây vừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裛', '{"9000": "8047.0", "Chữ Trung Quốc": "裛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裛 | ấp | tượng hình | bọc, buộc; ẩm ướt; túi đựng sách | 裛 thuộc bộ 衣 (y, áo). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Bộ 衣 liên quan đến vải vóc, bọc lót. Có tiểu triện và lục thư thông ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấp\": vải áo (衣) được \"ấp\" vào, quấn bọc chặt — đó là 裛, hành động bọc và buộc lại cẩn thận. | Gương Hán-Việt | ấp — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 衣 liên kết 裛 với nhóm chữ vải áo: 袋, 裁, 補, 褥.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi {{Han etym}} có tiểu triện và lục thư thông. Bộ 衣 (áo, vải) cho thấy chữ liên quan đến hành động bọc, quấn, buộc. Nghĩa: bọc và buộc lại; ẩm ướt; túi đựng sách. Chữ cổ, ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo kép lót hoa; buộc, thắt; thấm", "Hạng Tần Suất (Jun Da)": "8047.0", "Tần Suất % (Jun Da)": "99.9994031132", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 𧘇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𧘇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "裛", "Unihan_Traditional (Chữ Phồn thể)": "裛", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ trang phục hoặc động từ chỉ sự thấm ướt, tỏa hương thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈙', '{"9000": "8048.0", "Chữ Trung Quốc": "鈙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu âm | kim loại | 攴 | phác | biểu nghĩa | đánh nhẹ, gõ | 鈙 = 金 (Kim, biểu âm — lưu ý vai trò đặc biệt) + 攴 (Phác, biểu nghĩa: đánh nhẹ, gõ); chữ hình thanh. Bộ 攴 gợi ý hành động dùng dụng cụ gõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chày\": dụng cụ kim loại (金) dùng để \"chày\" — gõ nhẹ, cạy mở — đó là 鈙, cái chìa bằng kim loại. | Gương Hán-Việt | chày — trong tiếng Việt Hán \"chày\" chỉ dụng cụ gõ/cạy | Mở khoá kiến thức | Biết 鈙 giúp đọc từ điển Hán-Việt cổ về dụng cụ: \"chìa khoá\", \"chìa vôi\" trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary: {{Han compound|金|攴|c1=p|c2=s|t2=to hit lightly|ls=psc}} — 金 biểu âm, 攴 biểu nghĩa (gõ nhẹ). Nghĩa tiếng Việt Hán: chìa (như chìa khoá, chìa vôi). Chữ chỉ dụng cụ kim loại dùng để gõ, cạy, hay mở. Bộ Từ Điển An Nam ghi nghĩa \"chìa\". | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chìa; như \"chìa khoá; chìa vôi\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 攴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金攴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈙", "Unihan_Traditional (Chữ Phồn thể)": "鈙", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại dụng cụ kim loại nhỏ như chìa khóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎋', '{"9000": "8049.0", "Chữ Trung Quốc": "鎋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎋 | hạt | tượng hình | chốt bánh xe, quản lý | 鎋 thuộc bộ 金 (kim, kim loại). Wiktionary ghi {{Han etym}} nhưng không phân tích cấu trúc. Bộ 金 xác nhận đây là dụng cụ kim loại. Nghĩa: chốt bánh xe (linch-pin), cũng có nghĩa quản lý, kiểm soát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": chốt kim loại (金) \"hạt\" chặt — giữ bánh xe không rời trục — đó là 鎋, mắt xích then chốt kiểm soát toàn bộ. | Gương Hán-Việt | hạt — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 金 liên kết 鎋 với nhóm dụng cụ cơ khí cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}}. Bộ 金 (kim loại) + ý nghĩa chốt bánh xe. 鎋 nghĩa gốc là cái chốt kim loại giữ bánh xe không rời — từ đó nghĩa bóng là quản lý, cai quản. Chữ ít dùng trong tiếng Trung hiện đại. chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chốt cho bánh xe không rời ra; cai quản", "Hạng Tần Suất (Jun Da)": "8049.0", "Tần Suất % (Jun Da)": "99.9994051803", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 害", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金害", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "害", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎋", "Unihan_Traditional (Chữ Phồn thể)": "鎋", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ chốt bánh xe hoặc động từ với nghĩa cai quản, kiểm soát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑀', '{"9000": "8050.0", "Chữ Trung Quốc": "鑀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鑀 | ái | tượng hình | einsteinium (nguyên tố hóa học 99) | 鑀 thuộc bộ 金 (kim, kim loại). Đây là chữ Hán dùng để phiên âm tên nguyên tố einsteinium (Es, số nguyên tử 99). Không có phân tích cấu trúc từ Wiktionary. Chữ tạo muộn dùng trong thuật ngữ khoa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": kim loại (金) quý hiếm mang tên \"ái\" — einsteinium, được đặt theo tên nhà khoa học Einstein. | Gương Hán-Việt | ái — dùng trong thuật ngữ hóa học: 鑀 = einsteinium | Mở khoá kiến thức | Biết 鑀 giúp đọc bảng tuần hoàn Hán ngữ: nhóm nguyên tố siêu uranium.", "Tự nguyên_Xie": "鑀 là chữ tạo muộn trong thời hiện đại để phiên âm tên nguyên tố einsteinium (Es, số hiệu 99, đặt theo tên Einstein). Bộ 金 (kim loại) cho thấy đây là kim loại trong bảng tuần hoàn. Cũng từng dùng cho \"ionium\" (tên cũ của thorium-230). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "einsteinium (hóa học) (Tw); ionium (tên cũ của thorium)", "Hạng Tần Suất (Jun Da)": "8050.0", "Tần Suất % (Jun Da)": "99.9994062139", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 愛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金愛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "愛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑀", "Unihan_Traditional (Chữ Phồn thể)": "鑀", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chuyên ngành hóa học để chỉ nguyên tố Einsteinium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髴', '{"9000": "8051.0", "Chữ Trung Quốc": "髴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 15 | nét | 髴 | phất | tượng hình | tóc bù xù; mơ hồ, giống như | 髴 thuộc bộ 髟 (tiêu/bưu, tóc dài). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ trạng thái tóc rối, bù xù; cũng dùng trong 髣髴 (phảng phất, mơ hồ giống như). Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": mái tóc (髟) \"phất phơ\" — xõa buông, bù xù — đó là 髴, dùng trong \"phảng phất\" (mơ hồ giống). | Gương Hán-Việt | phất — dùng trong \"phảng phất\" (髣髴), \"phất phất\" (tóc bay) | Mở khoá kiến thức | Biết 髴 giúp đọc văn học cổ: \"髣髴\" = phảng phất, mơ hồ thoáng thấy.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} với tiểu triện. Bộ 髟 (tóc dài buông) cho thấy chữ liên quan đến tóc. Nghĩa gốc: tóc bù xù, tóc xõa. Dùng chủ yếu trong 髣髴 (phảng phất — mơ hồ trông giống như). Là dị thể của 彿 trong 髣髴. Có hai âm: fú và fèi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phảng phất 髣髴)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髴", "Unihan_Traditional (Chữ Phồn thể)": "髴", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường kết hợp với chữ phảng để tạo thành từ láy phảng phất chỉ sự mơ hồ, gần giống. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴓', '{"9000": "8052.0", "Chữ Trung Quốc": "鴓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴓 | miệt | tượng hình | chim crowned warbler phương đông | 鴓 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ loài chim warbler đội mão (eastern crowned warbler). Không có phân tích thành phần từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miệt\": con chim (鳥) \"miệt\" nhỏ — chim warbler đội mão nhỏ xinh, ca hót trên cành — đó là 鴓. | Gương Hán-Việt | miệt — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 鳥 liên kết 鴓 với các tên chim trong văn học tự nhiên Hán ngữ.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Bộ 鳥 xác nhận đây là tên chim. 鴓 chỉ loài 冕柳鶯 (eastern crowned warbler — loài chim hót nhỏ). Chữ nay ít dùng, bị thay bởi tên khoa học. chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "铓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "必 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰必鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴓", "Unihan_Traditional (Chữ Phồn thể)": "鴓", "Pinyin_Xie": "miè", "Âm Hán Việt_Xie": "miệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ một loài chim hoặc phần mũi nhọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸴', '{"9000": "8053.0", "Chữ Trung Quốc": "鸴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 鸴 | học | tượng hình | chim bullfinch phương đông, chim dệt | 鸴 thuộc bộ 鳥 (điểu, chim). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ chim 鷽 — oriental bullfinch (phân loài) hay weaverbird. Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"học\": con chim (鳥) \"học\" theo — chim dệt bắt chước dệt tổ công phu — đó là 鸴, chim bullfinch khéo léo. | Gương Hán-Việt | học — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鸴 giúp đọc 鷽鳩笑鵬 — thành ngữ Trang Tử về tầm nhìn hạn hẹp.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} có tiểu triện. Bộ 鳥 xác nhận tên chim. 鸴 chỉ chim bullfinch châu Á (Pyrrhula) hay weaverbird. Thành ngữ 鷽鳩笑鵬 (chim nhỏ cười chim rừng Bắc) từ Trang Tử — hình ảnh kẻ nhỏ chế nhạo người có tầm nhìn lớn. Chữ có trung cổ âm và thượng cổ âm ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim khách rừng, bồ cắt rừng", "Hạng Tần Suất (Jun Da)": "8053.0", "Tần Suất % (Jun Da)": "99.9994093146", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鸴", "Unihan_Traditional (Chữ Phồn thể)": "鷽", "Pinyin_Xie": "xué", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nhỏ thuộc họ nhà sẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秹', '{"9000": "8054.0", "Chữ Trung Quốc": "秹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秹 | nhẫn | tượng hình | một loại lúa, cây thóc | 秹 thuộc bộ 禾 (hòa, lúa). Không có phân tích thành phần từ Wiktionary. Bộ 禾 xác nhận liên quan đến cây lúa. Chữ rất hiếm, không có thông tin học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": cây lúa (禾) cần \"nhẫn nại\" — đứng thẳng chịu gió mưa — đó là 秹, một giống lúa trong văn bản cổ. | Gương Hán-Việt | nhẫn — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 禾 liên kết 秹 với nhóm chữ nông nghiệp: 稻, 粟, 黍, 稷.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph cho 秹. Bộ 禾 (lúa) xác nhận đây là chữ liên quan đến cây trồng. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 任", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾任", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秹", "Unihan_Traditional (Chữ Phồn thể)": "秹", "Pinyin_Xie": "rěn", "Âm Hán Việt_Xie": "nhẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong nông nghiệp cổ để chỉ cây mạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茢', '{"9000": "8055.0", "Chữ Trung Quốc": "茢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茢 | liệt | tượng hình | cây sậy, chổi lau | 茢 thuộc bộ 艹 (thảo). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ loại cỏ sậy dùng làm chổi. Không có phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liệt\": loại cỏ (艹) \"liệt\" — cứng thẳng như nan chổi, dùng quét sạch — đó là 茢, cây sậy dùng làm chổi. | Gương Hán-Việt | liệt — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 艹 liên kết 茢 với nhóm cây làm vật dụng: 芒 (sậy), 蒲 (bồ), 蘆 (lau).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Bộ 艹 xác nhận là cây cỏ. 茢 chỉ cây sậy, cỏ bấc, dùng làm chổi hoặc chiếu đan. Chữ xuất hiện trong văn bản lễ nghi cổ. chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chổi lau; một loại cỏ", "Hạng Tần Suất (Jun Da)": "8055.0", "Tần Suất % (Jun Da)": "99.9994124153", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 列", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹列", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "列", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茢", "Unihan_Traditional (Chữ Phồn thể)": "茢", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại chổi làm từ cỏ lau dùng trong nghi lễ quét dọn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘁', '{"9000": "8056.0", "Chữ Trung Quốc": "蘁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 艹 | thảo | biểu nghĩa | cỏ cây | 噩 | ngạc | biểu âm | 蘁 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 噩 (Ngạc, biểu âm); chữ hình thanh. Bộ 艹 chỉ thực vật, 噩 cho âm wù/ngào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": cây cỏ (艹) mọc \"ngạc nhiên\" — ngược chiều, không tuân theo — đó là 蘁, hành động phản kháng trong văn Trang Tử. | Gương Hán-Việt | ngạc — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 蘁 giúp đọc Trang Tử và văn triết học Tiên Tần về sự phục tùng và phản kháng.", "Tự nguyên_Xie": "Wiktionary: {{Han compound|艸|噩|alt1=艹|c1=s|c2=p|ls=psc|t1=grass}} — 艹 biểu nghĩa (cỏ), 噩 biểu âm. Nghĩa: phản kháng, chống đối. Dùng trong văn Trang Tử: \"không dám 蘁立\" (không dám đứng đối lập). Là chữ văn ngôn hiếm mang nghĩa nổi loạn, chống đối. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蘁", "Hạng Tần Suất (Jun Da)": "8056.0", "Tần Suất % (Jun Da)": "99.9994134489", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 噩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹噩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "噩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘁", "Unihan_Traditional (Chữ Phồn thể)": "蘁", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ hoặc tính từ để chỉ trạng thái giật mình tỉnh giấc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚑', '{"9000": "8057.0", "Chữ Trung Quốc": "蚑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚑 | kỳ | tượng hình | sâu bò ngoằn ngoèo, đi nhón chân | 蚑 thuộc bộ 虫 (trùng, sâu bọ). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ con sâu bò từ từ, hoặc hành động nhón chân đi. Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": con sâu bọ (虫) bò \"kỳ quặc\" — ngoằn ngoèo, nhón từng bước — đó là 蚑, hình ảnh con sâu trườn chậm. | Gương Hán-Việt | kỳ — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 虫 liên kết 蚑 với nhóm chữ côn trùng: 蛇, 蜈, 螟, 蠕.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} có tiểu triện. Bộ 虫 (sâu bọ) xác nhận liên quan đến côn trùng. 蚑 chỉ con sâu bò uốn éo; cũng nghĩa là đi bằng ngón chân (tip-toe). Dùng trong 蚑行 — hành động bò trườn, di chuyển chậm. chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con sâu bò ngoằn ngoèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚑", "Unihan_Traditional (Chữ Phồn thể)": "蚑", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ côn trùng hoặc động từ mô tả hành động bò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏻', '{"9000": "8058.0", "Chữ Trung Quốc": "鏻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鏻 | lân | tượng hình | phosphonium (hóa học) | 鏻 thuộc bộ 金 (kim, kim loại). Không có phân tích thành phần từ Wiktionary. Chữ dùng trong thuật ngữ hóa học để chỉ ion phosphonium (PH₄⁺). Chữ tạo muộn trong thời hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": kim loại (金) thuộc nhóm \"lân\" — phosphonium, ion phospho mang điện dương trong hóa học. | Gương Hán-Việt | lân — dùng trong thuật ngữ hóa học: 鏻 = phosphonium | Mở khoá kiến thức | Biết 鏻 giúp đọc danh pháp hóa học Hán ngữ về các nhóm phospho.", "Tự nguyên_Xie": "鏻 là chữ tạo muộn dùng trong hóa học hiện đại để phiên âm ''phosphonium''. Bộ 金 (kim loại) kết hợp với ý nghĩa ion kim loại trong hóa học. Đây là chữ khoa học, không có giáp cốt hay kim văn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phosphonium", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬭸", "Unihan_Traditional (Chữ Phồn thể)": "鏻", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ ion hoặc hợp chất phốt-pho-ni. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霤', '{"9000": "8059.0", "Chữ Trung Quốc": "霤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 18 | nét | 霤 | lưu | tượng hình | giọt mưa rỉ từ mái, máng nước | 霤 thuộc bộ 雨 (vũ, mưa). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ giọt mưa nhỏ từ mái nhà, máng thu nước mưa. Không có phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": mưa (雨) \"lưu\" xuống từ mái — chảy theo máng, rỉ từng giọt — đó là 霤, máng thu nước mưa hiên nhà. | Gương Hán-Việt | lưu — dùng trong \"trung lưu\" (khoảng giữa mái nhà) | Mở khoá kiến thức | Biết 霤 giúp đọc văn học cổ về kiến trúc nhà cửa và nghi lễ đối với vị thần mái nhà.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Bộ 雨 (mưa) xác nhận liên quan đến nước mưa. 霤 nghĩa là máng hứng nước mưa từ mái nhà (eavesdrop/eaves gutter); cũng nghĩa là giọt nước rỉ xuống. Dùng trong 中霤 (trung lưu — khoảng giữa mái nhà). chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giọt nước rỏ từ mái nhà", "Hạng Tần Suất (Jun Da)": "8059.0", "Tần Suất % (Jun Da)": "99.9994165496", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霤", "Unihan_Traditional (Chữ Phồn thể)": "霤", "Pinyin_Xie": "liù", "Âm Hán Việt_Xie": "lựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ giọt nước mưa rơi từ mái nhà hoặc máng hứng nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霩', '{"9000": "8060.0", "Chữ Trung Quốc": "霩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 18 | nét | 霩 | khoách | tượng hình | mưa tạnh, mây tan; rộng lớn | 霩 thuộc bộ 雨 (vũ, mưa). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ là dị thể văn ngôn của 廓 (khoách, rộng lớn), cũng mang nghĩa mưa tạnh mây tan. Có tiểu triện ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoách\": sau mưa (雨), bầu trời \"khoách\" ra — mây tan, không gian mở rộng vô tận — đó là 霩, cảnh trời quang sau bão. | Gương Hán-Việt | khoách — dùng trong nghĩa rộng lớn, tương đương 廓 | Mở khoá kiến thức | Biết 霩 giúp đọc thơ cổ về thời tiết và không gian: 霩然 (trời quang đãng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi {{Han etym}} có tiểu triện. 霩 là dị thể của 廓 trong nghĩa rộng lớn, khoảng khoát. Cũng mang nghĩa riêng: mưa ngừng và mây tan, bầu trời mở rộng. Bộ 雨 nhấn mạnh yếu tố khí tượng. Chữ văn ngôn ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trống; mở ra; biến thể của 廓, lớn", "Hạng Tần Suất (Jun Da)": "8060.0", "Tần Suất % (Jun Da)": "99.9994175832", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 郭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨郭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霩", "Unihan_Traditional (Chữ Phồn thể)": "霩", "Pinyin_Xie": "kuò", "Âm Hán Việt_Xie": "khuếch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái bầu trời quang đãng, không mây. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頺', '{"9000": "8061.0", "Chữ Trung Quốc": "頺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 頺 | đồi | tượng hình | suy đồi, đổ vỡ, tàn tạ | 頺 thuộc bộ 頁 (hiệt, đầu/trang). Wiktionary không cung cấp phân tích glyph. Đây là dị thể của 頹 (đồi) — chữ chỉ sự suy tàn, đổ vỡ, tàn tạ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồi\": cái đầu (頁) cúi xuống \"đồi\" — suy tàn, rũ xuống như cành cây khô — đó là 頺, sự sụp đổ không thể cứu vãn. | Gương Hán-Việt | đồi — dùng trong \"đồi bại\", \"đồi truỵ\", \"suy đồi\" | Mở khoá kiến thức | Biết 頺/頹 mở khóa: đồi bại (suy đồi), đồi phế (bỏ bê), đồi nhiên (sụp xuống).", "Tự nguyên_Xie": "頺 là dị thể của 頹 (đồi). Chữ gốc 頹 thuộc bộ 頁 (đầu), với thành phần 禿 (tốc, đầu trọc) gợi ý sự tàn lụi, sụp đổ. Nghĩa: suy đồi, sa sút, sụp đổ. Dùng trong: 頹廢 (đồi phế), 頹喪 (sầu não), 頹然 (rũ xuống). Không có phân tích glyph riêng cho dị thể 頺. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồi; như \"đồi bại; đồi truỵ; suy đồi\" sồi; như \"vải sồi\" tồi; như \"tồi tàn\" tòi; như \"tòi lên\" \nMột dạng của chữ đồi 頹.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "秀 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰秀頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "頺", "Unihan_Traditional (Chữ Phồn thể)": "頺", "Pinyin_Xie": "tuí", "Âm Hán Việt_Xie": "đồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ hoặc động từ trong các từ ghép chỉ sự suy thoái, sụp đổ của sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餚', '{"9000": "8062.0", "Chữ Trung Quốc": "餚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 16 | nét | 餚 | hào | tượng hình | món thịt chế biến, thức ăn ngon | 餚 thuộc bộ 食 (thực, ăn). Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Chữ chỉ món thịt đã chế biến, thức ăn ngon. Không có phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": thức ăn (食) \"hào\" hứng người ta — thịt chế biến thơm ngon, đặt lên mâm cỗ — đó là 餚, các món thịt đặc sản. | Gương Hán-Việt | hào — dùng trong \"giai hào\" (món ngon), \"trân hào\" (đặc sản quý) | Mở khoá kiến thức | Biết 餚 mở khóa: 佳餚 (giai hào), 菜餚 (các món ăn), 珍饈佳餚 (sơn hào hải vị).", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} có trung cổ âm và thượng cổ âm. Bộ 食 (ăn) xác nhận liên quan đến thức ăn. 餚 nghĩa là thịt đã chế biến thành món ăn, cỗ bàn ngon. Dùng trong: 佳餚 (giai hào, món ngon), 珍餚 (trân hào, đặc sản), 菜餚 (thái hào, các món ăn). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Đĩa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 肴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠肴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餚", "Unihan_Traditional (Chữ Phồn thể)": "餚", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng trong các tổ hợp từ chỉ cỗ bàn, món ăn ngon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯂', '{"9000": "8063.0", "Chữ Trung Quốc": "鯂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鯂 | tố | tượng hình | tên một loài cá | 鯂 thuộc bộ 魚 (ngư, cá). Không có phân tích thành phần từ Wiktionary. Bộ 魚 xác nhận đây là tên loài cá. Chữ rất hiếm, không có thông tin học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tố\": con cá (魚) \"tố\" — trắng nhạt, hiếm gặp — đó là 鯂, loài cá chuyên biệt trong văn bản cổ. | Gương Hán-Việt | tố — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Bộ 魚 liên kết 鯂 với nhóm chữ tên cá: 鯉, 鯊, 鰻, 鱸.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph cho 鯂. Bộ 魚 (cá) xác nhận đây là tên loài cá. Chưa có nguồn học thuật chi tiết về loài cá cụ thể mà chữ này chỉ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鯂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 酉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯂", "Unihan_Traditional (Chữ Phồn thể)": "鯂", "Pinyin_Xie": "su", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ chỉ một loài cá cổ hoặc động từ với nghĩa sống lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籔', '{"9000": "8064.0", "Chữ Trung Quốc": "籔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 21 | nét | 籔 | tẩu | tượng hình | giỏ tre đan dùng để vo gạo | 籔 là chữ độc thể, bộ thủ 竹 (trúc) gợi liên hệ với tre, nhưng cấu trúc nội bộ chưa được phân tích rõ trong nguồn học thuật. Chưa xác định được rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấu\": hình ảnh chiếc giỏ tre (竹) to lớn dùng để vo gạo — nhớ qua âm \"sấu\" gần giống \"sàu\" (sàng lọc). | Gương Hán-Việt | Chữ 籔 hiếm, ít xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | Biết 籔 giúp nhận diện nhóm chữ chỉ đồ vật đan bằng tre trong văn bản cổ.", "Tự nguyên_Xie": "Chữ 籔 (đọc sǒu) chỉ loại giỏ tre dùng để vo gạo hoặc lọc nước. Wiktionary không cung cấp phân tích tự nguyên cho chữ này. Dựa trên bộ thủ 竹 (trúc), có thể suy đoán đây là đồ vật làm từ tre. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "甔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 數", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮數", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "數", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "䉤", "Unihan_Traditional (Chữ Phồn thể)": "籔", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ cái sọt tre hoặc làm lượng từ đo lường thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘘', '{"9000": "8065.0", "Chữ Trung Quốc": "蘘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 20 | nét | 蘘 | nhương | tượng hình | loài gừng dại (myoga) | 蘘 là chữ chưa được phân tích cấu trúc hình thanh/hội ý rõ ràng trong nguồn Wiktionary. Bộ thủ 艹 (thảo) gợi đây là thực vật. Cũng là dạng dị thể của 穣.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": cây gừng dại mọc hoang — âm \"nhương\" gần với \"nhượng\" (nhường), như loài cây lặng lẽ nhường chỗ cho người hái. | Gương Hán-Việt | 蘘 xuất hiện trong 蘘荷 (nhương hà — cây gừng dại myoga) trong thực vật học cổ điển. | Mở khoá kiến thức | Biết 蘘 giúp đọc hiểu tên thực vật trong bản thảo dược học cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ 蘘 (đọc ráng) chỉ loài gừng dại (myoga, Zingiber mioga), dùng trong 蘘荷. Wiktionary ghi nhận đây là dị thể của 穣. Không có phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhương hà 蘘荷)", "Hạng Tần Suất (Jun Da)": "8065.0", "Tần Suất % (Jun Da)": "99.9994237846", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘘", "Unihan_Traditional (Chữ Phồn thể)": "蘘", "Pinyin_Xie": "ráng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loại cây thuộc họ gừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雑', '{"9000": "8066.0", "Chữ Trung Quốc": "雑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 14 | nét | 雑 | tạp | tượng hình | dị thể Nhật Bản của 雜 (tạp — lẫn lộn) | 雑 là dạng cải cách (shinjitai) của chữ Nhật Bản, tương đương 雜 (tạp) trong chữ Hán truyền thống. Không có phân tích hình thanh/hội ý riêng biệt vì đây là biến thể hình thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": chữ cải cách Nhật của 雜 — nhớ \"tạp\" như \"tạp nham\", \"tạp chí\" — mọi thứ trộn lẫn vào nhau. | Gương Hán-Việt | \"Tạp\" trong tiếng Việt: tạp chí (雑誌), tạp nham, hỗn tạp — đều từ gốc 雜/雑. | Mở khoá kiến thức | Biết 雑 giúp đọc văn bản Nhật-Hán và nhận ra ngay các từ \"tạp\" trong tạp chí, tạp văn.", "Tự nguyên_Xie": "雑 là dạng shinjitai (chữ cải cách Nhật Bản) của 雜. Wiktionary ghi: \"Unorthodox variant of 雜. The modern Japanese usage is of reform (shinjitai) nature.\" Chữ 雜 gốc gồm 隹 (chim) và các thành phần biểu ý về sự pha trộn. 雑 rút gọn hình thức nhưng giữ nguyên nghĩa: lẫn lộn, hỗn tạp. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Biến thể tiếng Nhật của 雜", "Hạng Tần Suất (Jun Da)": "8066.0", "Tần Suất % (Jun Da)": "99.9994248181", "GavinGrover_Once (Chiết tự trực tiếp)": "杂 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰杂隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雑", "Unihan_Traditional (Chữ Phồn thể)": "雑", "Pinyin_Xie": "zá", "Âm Hán Việt_Xie": "tạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ đứng trước danh từ để chỉ sự hỗn tạp hoặc không thuần nhất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬶', '{"9000": "8067.0", "Chữ Trung Quốc": "鬶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬲 | Số nét | 18 | nét | 鬶 | quỹ | tượng hình | loại bình đất nung ba chân dùng nấu ăn thời cổ | 鬶 chưa được phân tích cấu trúc nội bộ rõ ràng trong Wiktionary. Bộ thủ 鬲 (lịch — đỉnh ba chân) gợi liên quan đến đồ nấu ăn cổ đại. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quy\": chiếc bình đất (鬲) ba chân hình dáng kỳ lạ — \"quy\" như \"quỳ\" xuống ba chân để đứng vững khi nấu. | Gương Hán-Việt | 鬶 là chữ chuyên dùng trong khảo cổ, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鬶 giúp đọc văn bản khảo cổ học và nhận diện tên đồ gốm cổ đại Trung Quốc.", "Tự nguyên_Xie": "Chữ 鬶 (đọc guī) chỉ loại bình đất nung ba chân (guī) dùng để đun nấu trong thời tiền sử Trung Quốc. Đây là hiện vật khảo cổ đặc trưng của văn hóa Long Sơn. Wiktionary không cung cấp phân tích tự nguyên chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái (nồi đất có ba chân rỗng thời xưa)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "规 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱规鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "规", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬲", "Unihan_Simplified (Chữ Giản thể)": "鬶", "Unihan_Traditional (Chữ Phồn thể)": "鬶", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại bình gốm ba chân thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯵', '{"9000": "8068.0", "Chữ Trung Quốc": "鯵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯵 | sâm | tượng hình | tên một loài cá | 鯵 thuộc bộ 魚 (ngư — cá), cho biết đây là tên loài cá. Cấu trúc nội bộ chưa được phân tích trong Wiktionary. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": loài cá (魚) với âm \"sâm\" — nhớ như cá nhân sâm, quý hiếm và ít gặp. | Gương Hán-Việt | 鯵 là chữ chuyên dùng cho tên loài cá, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鯵 giúp nhận diện tên loài cá trong văn bản sinh học hoặc ngư nghiệp cổ điển.", "Tự nguyên_Xie": "Chữ 鯵 (đọc shēn) là tên một loài cá. Không có phân tích tự nguyên trong Wiktionary. Bộ thủ 魚 xác định đây là từ chỉ cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鵵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯵", "Unihan_Traditional (Chữ Phồn thể)": "鯵", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cá sòng trong các văn bản ẩm thực hoặc sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰧', '{"9000": "8069.0", "Chữ Trung Quốc": "鰧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰧 | đằng | tượng hình | tên một loài cá | 鰧 thuộc bộ 魚 (ngư — cá). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Có thể là hình thanh với 騰/滕 làm phần biểu âm, nhưng chưa có xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": loài cá (魚) với âm \"đằng\" — nhớ như \"đằng\" trong \"đằng vân\" (bay lên), tưởng tượng con cá nhảy khỏi mặt nước. | Gương Hán-Việt | 鰧 là chữ chuyên dùng, ít xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | Biết 鰧 giúp nhận diện tên loài cá trong từ điển sinh học Hán-Việt.", "Tự nguyên_Xie": "Chữ 鰧 (đọc téng) là tên một loài cá. Wiktionary ghi nhận phát âm nhưng không giải thích nghĩa hay tự nguyên. Bộ 魚 xác định thuộc nhóm cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 鮝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月鮝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鮝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "鰧", "Unihan_Traditional (Chữ Phồn thể)": "鰧", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá biển có hình thù đặc biệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱂', '{"9000": "8070.0", "Chữ Trung Quốc": "鱂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鱂 | giang | tượng hình | tên một loài cá | 鱂 thuộc bộ 魚 (ngư — cá). Phần bên phải có thể là biểu âm gần âm jiāng, nhưng cấu trúc chi tiết chưa được xác nhận trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giang\": loài cá (魚) mang âm \"giang\" — như cá sông (江 giang), tưởng tượng loài cá sống trên sông lớn. | Gương Hán-Việt | 鱂 là chữ chuyên dùng tên cá, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鱂 giúp nhận diện tên loài cá trong tài liệu ngư nghiệp hoặc sinh học cổ điển.", "Tự nguyên_Xie": "Chữ 鱂 (đọc jiāng) là tên một loài cá. Wiktionary chỉ ghi phát âm không có nghĩa cụ thể. Bộ 魚 xác định thuộc nhóm cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá killi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 將", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚將", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "將", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱂", "Unihan_Traditional (Chữ Phồn thể)": "鱂", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "giang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài cá nhỏ thuộc bộ cá chép răng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳂', '{"9000": "8071.0", "Chữ Trung Quốc": "鳂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳂 | uy | tượng hình | tên một loài cá | 鳂 thuộc bộ 魚 (ngư — cá). Phần bên phải có thể là biểu âm gần wēi, nhưng cấu trúc chi tiết chưa được xác nhận trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": loài cá (魚) với âm nhẹ \"vi\" — như \"vi\" trong \"vi cá\" (vi mang cá), tưởng tượng loài cá nhỏ bé. | Gương Hán-Việt | 鳂 là chữ chuyên dùng tên cá, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鳂 giúp nhận diện tên loài cá trong tài liệu sinh học hoặc ngư nghiệp cổ.", "Tự nguyên_Xie": "Chữ 鳂 (đọc wēi) là tên một loài cá. Wiktionary chỉ ghi phát âm không có nghĩa cụ thể. Bộ 魚 xác định thuộc nhóm cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá hồng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳂", "Unihan_Traditional (Chữ Phồn thể)": "鳂", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "uy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài cá biển có vảy cứng màu đỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵟', '{"9000": "8072.0", "Chữ Trung Quốc": "鵟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鵟 | cuồng | tượng hình | chim ưng đuôi đỏ (buzzard) | 鵟 thuộc bộ 鳥 (điểu — chim). Wiktionary dẫn chiếu đến 狂 (cuồng) như là nguồn tự nguyên, gợi ý đây có thể là chữ hình thanh với phần âm liên quan 狂. Cấu trúc chi tiết chưa được xác nhận đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cuồng\": con chim ưng (鳥) hung hãn \"cuồng\" — như kẻ điên cuồng lao xuống săn mồi, đó là buzzard 鵟. | Gương Hán-Việt | 鵟 là chữ chuyên dùng tên chim, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鵟 giúp nhận diện tên loài chim săn mồi trong văn bản tự nhiên học cổ điển.", "Tự nguyên_Xie": "Chữ 鵟 (đọc kuáng) chỉ loài chim ưng buzzard. Wiktionary dẫn tự nguyên từ 狂 (cuồng), cho thấy âm đọc liên quan. Đây có thể là chữ hình thanh: bộ 鳥 biểu nghĩa (chim), phần còn lại biểu âm gần kuáng. Chưa có phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim ó", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "狂 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱狂鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "狂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "𫛭", "Unihan_Traditional (Chữ Phồn thể)": "鵟", "Pinyin_Xie": "kuáng", "Âm Hán Việt_Xie": "cuồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài chim săn mồi thuộc họ Ưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盠', '{"9000": "8073.0", "Chữ Trung Quốc": "盠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 14 | nét | 彖 | đoán | biểu âm | cho âm đọc | 皿 | mãnh | biểu nghĩa | đồ đựng, bình chén | 盠 = 彖 (Đoán, biểu âm) + 皿 (Mãnh, biểu nghĩa: đồ đựng); chữ hình thanh. Bộ 皿 xác định đây là một loại đồ đựng hoặc bình chén; 彖 cung cấp âm đọc gần lí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": chiếc bình 皿 với âm từ 彖 (đoán) — nhớ \"lệ\" như \"lễ\" (nghi lễ), loại đồ đựng dùng trong nghi thức. | Gương Hán-Việt | 盠 là chữ cổ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | Biết 盠 giúp nhận diện tên đồ đựng trong văn bản kim văn và khảo cổ học.", "Tự nguyên_Xie": "Theo Wiktionary, 盠 là chữ hình thanh: 皿 (đồ đựng) biểu nghĩa, 彖 biểu âm. Chữ chỉ một loại đồ đựng, chi tiết nghĩa không còn rõ. Chưa có thêm nguồn học thuật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "砠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "彖 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彖皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盠", "Unihan_Traditional (Chữ Phồn thể)": "盠", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ các khí cụ bằng đồng thời Tây Chu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盳', '{"9000": "8074.0", "Chữ Trung Quốc": "盳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 8 | nét | 盳 | vọng | tượng hình | chữ hiếm, nghĩa chưa rõ | 盳 có bộ thủ liên quan đến nhóm 目 (mục — mắt) theo khung phân loại Kangxi. Cấu trúc nội bộ và loại chữ (hình thanh/hội ý) chưa được xác nhận trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vọng\": chữ hiếm với âm \"vọng\" — nhớ như \"vọng\" trong \"trông vọng\", nhìn xa xăm. | Gương Hán-Việt | 盳 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 盳 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 盳 (đọc wàng) là chữ cực hiếm, nghĩa và tự nguyên không được ghi lại trong Wiktionary. Không có nguồn học thuật đáng tin cậy. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "盳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 亡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目亡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盳", "Unihan_Traditional (Chữ Phồn thể)": "盳", "Pinyin_Xie": "wàng", "Âm Hán Việt_Xie": "vọng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hành vi liếc mắt hoặc nhìn nghiêng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盽', '{"9000": "8075.0", "Chữ Trung Quốc": "盽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 盽 | phong | tượng hình | chữ hiếm, nghĩa chưa rõ | 盽 có bộ thủ liên quan đến nhóm 目 (mục — mắt) theo phân loại Kangxi. Cấu trúc và loại chữ chưa được xác nhận. Âm fēng gợi liên hệ với 風/封 nhưng chưa có xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": chữ hiếm với âm \"phong\" — nhớ như \"phong\" trong \"phong trào\", mạnh mẽ nhưng khó nắm bắt. | Gương Hán-Việt | 盽 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 盽 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 盽 (đọc fēng) là chữ cực hiếm, nghĩa và tự nguyên không được ghi lại trong Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "罽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 丰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目丰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "盽", "Unihan_Traditional (Chữ Phồn thể)": "盽", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ ranh giới hoặc bờ ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眃', '{"9000": "8076.0", "Chữ Trung Quốc": "眃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眃 | vân | tượng hình | chữ hiếm, nghĩa ghi là ''phòng bên'' | 眃 có bộ thủ liên quan đến nhóm 目 (mục — mắt) theo phân loại Kangxi, nhưng nghĩa được ghi là ''side room'' (phòng bên). Cấu trúc chi tiết chưa được xác nhận trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": chữ hiếm với âm \"vân\" — nhớ như \"vân\" trong \"vân du\" (mây trôi), căn phòng khuất lấp như đám mây. | Gương Hán-Việt | 眃 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 眃 giúp nhận diện ký tự trong từ điển chữ Hán hiếm và văn bản kiến trúc cổ.", "Tự nguyên_Xie": "Chữ 眃 (đọc yún) được ghi nghĩa là ''phòng bên'' trong một số từ điển. Không có phân tích tự nguyên trong Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phòng bên", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眃", "Unihan_Traditional (Chữ Phồn thể)": "眃", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ miêu tả trạng thái mắt bị hoa, nhìn không rõ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眏', '{"9000": "8077.0", "Chữ Trung Quốc": "眏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眏 | ương | tượng hình | chữ hiếm, nghĩa chưa rõ | 眏 thuộc nhóm bộ 目 (mục — mắt) theo phân loại Kangxi. Cấu trúc và loại chữ chưa được xác nhận trong Wiktionary. Nghĩa cụ thể không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": chữ trong nhóm mắt (目) với âm \"ương\" — nhớ như \"ương\" trong \"ương ngạnh\", cái nhìn cứng đầu. | Gương Hán-Việt | 眏 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 眏 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 眏 (đọc yāng) là chữ cực hiếm. Wiktionary chỉ ghi phát âm, không cung cấp nghĩa hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "珏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眏", "Unihan_Traditional (Chữ Phồn thể)": "眏", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hành động liếc nhìn hoặc nhìn trộm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睧', '{"9000": "8078.0", "Chữ Trung Quốc": "睧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睧 | hôn | tượng hình | thị lực mờ nhạt, mắt không rõ | 睧 thuộc bộ 目 (mục — mắt). Nghĩa là ''thị lực mờ''. Cấu trúc nội bộ chưa được phân tích trong Wiktionary. Phần 昏 (hôn — tối tăm) có thể là biểu âm, nhưng chưa xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hôn\": mắt (目) mờ nhạt \"hôn\" — như \"hôn mê\" (mờ tối), nhìn không rõ như trong bóng tối. | Gương Hán-Việt | 睧 là chữ hiếm; \"hôn\" xuất hiện phổ biến hơn trong 昏 (hôn mê, hoàng hôn). | Mở khoá kiến thức | Biết 睧 giúp nhận diện từ ngữ liên quan đến thị lực trong văn bản y học cổ điển.", "Tự nguyên_Xie": "Chữ 睧 (đọc hūn) nghĩa là thị lực mờ nhạt, mắt không thấy rõ. Có thể liên quan đến 昏 (hôn — tối tăm, mờ). Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn vào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 昏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目昏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睧", "Unihan_Traditional (Chữ Phồn thể)": "睧", "Pinyin_Xie": "hūn", "Âm Hán Việt_Xie": "hôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ miêu tả mắt bị mờ hoặc trạng thái tối tăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硄', '{"9000": "8079.0", "Chữ Trung Quốc": "硄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硄 | khoảng | tượng hình | chữ hiếm, nghĩa chưa rõ | 硄 thuộc bộ 石 (thạch — đá). Cấu trúc và loại chữ chưa được xác nhận trong Wiktionary. Âm kuāng gợi liên hệ với tiếng vang đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoảng\": chữ đá (石) với âm \"khoảng\" — như tiếng đá rơi vang xuống khoảng không. | Gương Hán-Việt | 硄 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 硄 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 硄 (đọc kuāng) thuộc nhóm chữ đá (bộ 石). Wiktionary không cung cấp nghĩa hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "焄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硄", "Unihan_Traditional (Chữ Phồn thể)": "硄", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khoảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này dùng làm từ tượng thanh mô tả âm thanh đá va chạm vào nhau. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碔', '{"9000": "8080.0", "Chữ Trung Quốc": "碔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碔 | vũ | tượng hình | đá quý giả, hoặc phần nửa viên đá | 碔 thuộc bộ 石 (thạch — đá). Wiktionary ghi phát âm nhưng không phân tích cấu trúc. Nghĩa ghi là ''1/2 viên đá''. Loại chữ chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": mảnh đá (石) với âm \"vũ\" — như \"vũ khí\" đá, nửa viên đá được dùng làm công cụ. | Gương Hán-Việt | 碔 là chữ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng tiếng Việt. | Mở khoá kiến thức | Biết 碔 giúp nhận diện tên đá và khoáng vật trong văn bản địa chất cổ điển.", "Tự nguyên_Xie": "Chữ 碔 (đọc wǔ) thuộc nhóm chữ đá. Wiktionary ghi phát âm nhưng không cung cấp nghĩa rõ hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vũ phu 珷玞,碔砆)", "Hạng Tần Suất (Jun Da)": "8080.0", "Tần Suất % (Jun Da)": "99.9994351538", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 武", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石武", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "武", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碔", "Unihan_Traditional (Chữ Phồn thể)": "碔", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại đá đẹp có vân giống ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碦', '{"9000": "8081.0", "Chữ Trung Quốc": "碦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碦 | khắc | tượng hình | chữ hiếm, nghĩa chưa rõ | 碦 thuộc bộ 石 (thạch — đá). Cấu trúc nội bộ chưa được phân tích trong Wiktionary. Âm kè gần với 克 (khắc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khắc\": đá (石) với âm \"khắc\" — như khắc đá, chạm trổ vào đá. | Gương Hán-Việt | 碦 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 碦 giúp nhận diện ký tự trong từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 碦 (đọc kè) là chữ hiếm thuộc bộ 石 (đá). Wiktionary không cung cấp nghĩa hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 客", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石客", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "客", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碦", "Unihan_Traditional (Chữ Phồn thể)": "碦", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ đá cứng hoặc dùng trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碸', '{"9000": "8082.0", "Chữ Trung Quốc": "碸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碸 | phong | tượng hình | hợp chất hữu cơ (sulfone) | 碸 thuộc bộ 石 (thạch — đá/khoáng). Nghĩa là một hợp chất hữu cơ. Cấu trúc chi tiết chưa được phân tích. Đây có thể là chữ tạo muộn để phiên âm hoặc dịch thuật ngữ hóa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": khoáng chất (石) với âm \"phong\" — như \"phong\" trong sulfone, hợp chất đá khoáng. | Gương Hán-Việt | 碸 là chữ thuật ngữ hóa học hiện đại, ít xuất hiện trong từ Hán-Việt truyền thống. | Mở khoá kiến thức | Biết 碸 giúp đọc thuật ngữ hóa học trong tài liệu khoa học Trung-Việt.", "Tự nguyên_Xie": "Chữ 碸 (đọc fēng) chỉ một loại hợp chất hữu cơ, có thể là sulfone. Đây là chữ tạo muộn dùng trong thuật ngữ hóa học hiện đại. Chưa có phân tích tự nguyên truyền thống. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "碢", "Hạng Tần Suất (Jun Da)": "5907.0", "Tần Suất % (Jun Da)": "99.9786826132", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 風", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石風", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "風", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砜", "Unihan_Traditional (Chữ Phồn thể)": "碸", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong hóa học để chỉ hợp chất sunphon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磃', '{"9000": "8083.0", "Chữ Trung Quốc": "磃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磃 | tư | tượng hình | chữ dùng trong tên địa danh 磃氏館 | 磃 thuộc bộ 石 (thạch — đá). Dùng trong 磃氏館 (tên địa danh). Cấu trúc chi tiết chưa được phân tích. Âm sī gần với 斯/司/思.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": đá (石) với âm \"tư\" — như địa danh cổ 磃氏館, nơi đá đứng tên. | Gương Hán-Việt | 磃 là chữ chuyên dùng địa danh, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 磃 giúp nhận diện địa danh trong văn bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "Chữ 磃 (đọc sī) chỉ được ghi nhận qua cụm từ 磃氏館 (tên địa danh cổ). Wiktionary cung cấp phát âm nhưng không phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "烃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 虒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石虒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磃", "Unihan_Traditional (Chữ Phồn thể)": "磃", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ đá mài hoặc đá phẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礘', '{"9000": "8084.0", "Chữ Trung Quốc": "礘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 19 | nét | 礘 | ngạc | tượng hình | chữ hiếm, nghĩa chưa rõ | 礘 thuộc bộ 石 (thạch — đá). Wiktionary chỉ ghi phát âm (è/qì), không phân tích cấu trúc hay nghĩa. Loại chữ chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": đá (石) với âm \"ngạc\" — như \"ngạc nhiên\" trước tảng đá kỳ lạ. | Gương Hán-Việt | 礘 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 礘 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 礘 (đọc è hoặc qì) là chữ hiếm bộ 石. Wiktionary chỉ ghi phát âm không có nghĩa hay tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 㬎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石㬎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㬎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礘", "Unihan_Traditional (Chữ Phồn thể)": "礘", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ miêu tả địa hình đá gập ghềnh, hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礮', '{"9000": "8085.0", "Chữ Trung Quốc": "礮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 21 | nét | 礮 | pháo | tượng hình | máy bắn đá cổ đại, máy bắn đạn; dạng cổ của 炮 | 礮 là dạng cổ của 炮 (pháo — pháo, súng). Bộ 石 (thạch) nhấn mạnh phương tiện bắn đá thô sơ ban đầu. Wiktionary ghi: \"{{zh-see|炮|v}}\" — dạng xem (variant).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"pháo\": dạng cổ của 炮 — bộ 石 (đá) vì pháo thủa xưa là máy ném đá; sau dùng lửa 火 nên đổi thành 炮. | Gương Hán-Việt | \"Pháo\" trong tiếng Việt: pháo hoa, pháo thủ, đại pháo — đều từ gốc 礮/炮. | Mở khoá kiến thức | Biết 礮 giúp đọc văn bản lịch sử quân sự cổ điển và hiểu sự chuyển đổi bộ thủ của chữ 炮.", "Tự nguyên_Xie": "Chữ 礮 (đọc pào) là dạng cổ của 炮 (pháo). Theo Wiktionary: \"ancient ballista for throwing heavy stones, a cannon, a gun\". Bộ 石 gợi nguồn gốc từ máy bắn đá (投石機) trước khi thuốc súng ra đời. Sau đó chữ đổi bộ sang 火 (hỏa) thành 炮 khi dùng để chỉ súng đạn dùng lửa. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1266.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thạch (110) Bác (1265)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thạch (số 110 - đá/chỉ ý) ở bên trái chữ Bác (số 1265 - chống lại/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Bác chỉ âm, bộ Thạch chỉ ý. Pháo vốn là máy bắn đá dùng trong quân sự thời xưa (súng pháo). Sau này khi có thuốc súng mới dùng chữ 炮 (Pháo).", "Nghĩa Tiếng Việt_Xie": "máy bắn đá; pháo; mìn", "Hạng Tần Suất (Jun Da)": "8085.0", "Tần Suất % (Jun Da)": "99.9994377378", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 駮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石駮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "駮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礮", "Unihan_Traditional (Chữ Phồn thể)": "礮", "Pinyin_Xie": "pào", "Âm Hán Việt_Xie": "pháo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ các loại máy bắn đá hoặc súng thần công thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祘', '{"9000": "8086.0", "Chữ Trung Quốc": "祘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祘 | toán | tượng hình | tính đếm; có thể là dạng rút gọn của 蒜 | 祘 là chữ hội ý hoặc tượng hình cổ chỉ hành động tính đếm. Wiktionary ghi: \"Likely a clipping of 蒜\" (rút gọn từ 蒜 — tỏi). Bộ 示 gợi liên quan đến lễ nghi hoặc dấu hiệu. Chưa xác định rõ loại chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toán\": âm \"toán\" gần 算 (toán học) — người xưa có thể dùng củ tỏi (蒜) để đếm, 祘 là chữ ghi lại hành động đó. | Gương Hán-Việt | \"Toán\" trong tiếng Việt: toán học, phép toán — liên hệ với nhóm chữ 算/筭/祘. | Mở khoá kiến thức | Biết 祘 giúp hiểu nguồn gốc từ nhóm \"tính toán\" trong chữ Hán cổ và mối liên hệ với 算.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (dẫn Guo, 2010b và Su, 2012), 祘 có thể là dạng rút gọn của 蒜 (tỏi) — dùng củ tỏi làm công cụ đếm. Âm suàn giống với 算 (tính toán). Mối liên hệ giữa tỏi và phép tính phản ánh cách đếm bằng vật thể cụ thể trong thời cổ đại. Có hình tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tính toán", "Hạng Tần Suất (Jun Da)": "8086.0", "Tần Suất % (Jun Da)": "99.9994382546", "GavinGrover_Once (Chiết tự trực tiếp)": "示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "祘", "Unihan_Traditional (Chữ Phồn thể)": "祘", "Pinyin_Xie": "suàn", "Âm Hán Việt_Xie": "toán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị hành vi tính toán hoặc làm danh từ chỉ bàn tính thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禤', '{"9000": "8087.0", "Chữ Trung Quốc": "禤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 15 | nét | 禤 | tuyên | tượng hình | họ Tuyên (họ người Trung Quốc) | 禤 thuộc bộ 示 (thị — thần linh, lễ thức). Dùng chủ yếu làm họ người. Cấu trúc nội bộ chưa được phân tích trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyên\": bộ 示 (thần/lễ) kết hợp với âm \"tuyên\" — như họ người mang danh nghĩa tuyên bố thiêng liêng. | Gương Hán-Việt | 禤 chủ yếu dùng làm họ người; \"tuyên\" xuất hiện trong nhiều từ Hán-Việt như tuyên bố, tuyên truyền. | Mở khoá kiến thức | Biết 禤 giúp nhận ra họ người trong tài liệu lịch sử và danh bạ Trung Quốc.", "Tự nguyên_Xie": "Chữ 禤 (đọc xuān) là một họ người Trung Quốc (surname Xuan). Không có phân tích tự nguyên trong Wiktionary. Bộ 示 gợi liên hệ với lễ nghi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Huyên", "Hạng Tần Suất (Jun Da)": "8087.0", "Tần Suất % (Jun Da)": "99.9994387713", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禤", "Unihan_Traditional (Chữ Phồn thể)": "禤", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秌', '{"9000": "8088.0", "Chữ Trung Quốc": "秌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 秌 | thu | tượng hình | dị thể cổ của 秋 (thu — mùa thu) | 秌 là dạng cổ của 秋 (thu). Giáp cốt văn cho thấy hình ảnh con dế hoặc châu chấu với lửa — biểu trưng mùa thu khi côn trùng chết đi. Không phân chia hình thanh/hội ý rõ ràng ở dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": dạng cổ của 秋 — giáp cốt vẽ con dế mùa thu trên đồng lúa 禾; âm \"thu\" trong \"mùa thu\" tiếng Việt chính là từ chữ này. | Gương Hán-Việt | \"Thu\" trong tiếng Việt: mùa thu, thu hoạch, thu phân — đều từ gốc 秌/秋. | Mở khoá kiến thức | Biết 秌 giúp hiểu nguồn gốc chữ 秋 qua giáp cốt văn và nhận diện dạng cổ trong văn bản khảo cổ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | 秌 là dạng cổ của 秋 (mùa thu). Có nhiều hình giáp cốt văn: hình con châu chấu/dế (秋) — côn trùng mùa thu đồng. Sau thêm bộ 禾 (lúa) biểu ý thu hoạch, và 火 (lửa) có thể ám chỉ đốt đồng sau vụ gặt. Đây là chữ với giáp cốt văn phong phú, phản ánh nền nông nghiệp cổ đại. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thu; như \"mùa thu; thu hoạch\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "秌", "Unihan_Traditional (Chữ Phồn thể)": "秌", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ chỉ mùa thu hoặc thời gian gặt hái trong năm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秙', '{"9000": "8089.0", "Chữ Trung Quốc": "秙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 秙 | khô | tượng hình | chữ hiếm, liên quan đến cây lúa khô hoặc tàn lụi | 秙 thuộc bộ 禾 (hòa — lúa). Nghĩa ghi là liên quan đến lúa/cây cỏ. Cấu trúc chi tiết chưa được phân tích trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khô\": cây lúa (禾) với âm \"khô\" — như cây lúa khô héo sau khi thu hoạch. | Gương Hán-Việt | 秙 là chữ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 秙 giúp nhận diện tên trạng thái cây trồng trong văn bản nông nghiệp cổ điển.", "Tự nguyên_Xie": "Chữ 秙 (đọc kù) thuộc bộ 禾 (lúa), có thể chỉ tình trạng lúa khô hoặc tàn. Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秙", "Unihan_Traditional (Chữ Phồn thể)": "秙", "Pinyin_Xie": "kù", "Âm Hán Việt_Xie": "khô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ cây mạ non hoặc tính từ chỉ sự khô héo của cây lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秢', '{"9000": "8090.0", "Chữ Trung Quốc": "秢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 秢 | linh | tượng hình | chữ hiếm, bộ 禾 | 秢 thuộc bộ 禾 (hòa — lúa). Wiktionary chỉ ghi phát âm líng, không cung cấp nghĩa hay cấu trúc. Có thể là hình thanh với 令/零 làm phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": cây lúa (禾) với âm \"linh\" — nhớ như \"linh\" trong \"linh hoạt\", cây lúa uốn mình theo gió. | Gương Hán-Việt | 秢 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 秢 giúp nhận diện ký tự trong từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 秢 (đọc líng) thuộc bộ 禾. Wiktionary chỉ ghi phát âm, không cung cấp nghĩa hay tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秢", "Unihan_Traditional (Chữ Phồn thể)": "秢", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ tuổi thọ hoặc chu kỳ sinh trưởng của cây lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稧', '{"9000": "8091.0", "Chữ Trung Quốc": "稧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 14 | nét | 禾 | hòa | biểu nghĩa | lúa — gợi liên kết với nghi lễ nông nghiệp | 契 | khế | biểu âm | khế ước — cho âm đọc xì/khế | 稧 = 禾 (Hòa, biểu nghĩa: lúa) + 契 (Khế, biểu âm); chữ hình thanh. Là dạng thay thế của 禊 (tế lễ thanh tẩy). Bộ 禾 thay bộ 示 gợi ý nghi lễ gắn với nông nghiệp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khể\": lúa (禾) + khế (契) — dạng cổ của nghi lễ 禊 thanh tẩy, liên kết tập tục nông nghiệp với lễ nghi thiêng liêng. | Gương Hán-Việt | 稧 là dạng cổ của 禊; \"khể\" ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 稧 giúp đọc văn bản nghi lễ và thơ ca cổ điển Trung Quốc liên quan đến tết Thượng Tị.", "Tự nguyên_Xie": "Theo Wiktionary, 稧 là chữ hình thanh: 禾 (lúa) biểu nghĩa, 契 biểu âm. Đây là dạng thay thế (alt form) của 禊 — nghi lễ thanh tẩy trong văn hóa Trung Quốc cổ, thường thực hiện bên bờ sông vào tiết Thượng Tị (早春). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稧", "Unihan_Traditional (Chữ Phồn thể)": "稧", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "khể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ cây mạ non hoặc nghi lễ cúng tế xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稬', '{"9000": "8092.0", "Chữ Trung Quốc": "稬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 14 | nét | 稬 | nhu | tượng hình | dị thể của 糯 (nhu — gạo nếp) | 稬 là dạng cổ của 糯 (nhu — gạo nếp). Wiktionary ghi: \"{{zh-see|糯|v}}\". Bộ 禾 xác định liên quan đến lúa gạo. Không phân chia hình thanh/hội ý riêng biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": bộ 禾 (lúa) với nghĩa dẻo dính — \"nhu\" như \"nhu mì\" (mềm mại), gạo nếp 稬 dẻo mềm và dính. | Gương Hán-Việt | \"Nhu\" trong nhu mì, nhu hòa — cùng gốc Hán-Việt với 稬/糯 (mềm dẻo). | Mở khoá kiến thức | Biết 稬 giúp nhận ra dạng cổ của 糯 trong văn bản nông nghiệp và ẩm thực cổ điển.", "Tự nguyên_Xie": "Kim văn | Chữ 稬 (đọc nuò) là dạng dị thể của 糯 (gạo nếp, dẻo). Wiktionary ghi nhận đây là variant. Có hình kim văn cho thấy chữ được dùng từ thời cổ đại. Đặc tính dẻo dính của gạo nếp phản ánh trong nghĩa \"glutinous, sticky\". | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo nếp để cất rượu", "Hạng Tần Suất (Jun Da)": "4195.0", "Tần Suất % (Jun Da)": "99.7973897369", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 耎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾耎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "糯", "Unihan_Traditional (Chữ Phồn thể)": "稬", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "noạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ gạo nếp hoặc làm tính từ bổ nghĩa cho các loại ngũ cốc có tính dẻo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稲', '{"9000": "8093.0", "Chữ Trung Quốc": "稲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 14 | nét | 稲 | đạo | tượng hình | dị thể Nhật của 稻 (đạo — cây lúa) | 稲 là dạng shinjitai (chữ cải cách Nhật Bản) của 稻 (đạo — cây lúa). Wiktionary ghi: \"Variant of 稻. The component 旧 is a variant of 臼.\" Bộ 禾 xác định là cây lúa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": dạng Nhật của 稻 — bộ 禾 (lúa) với cối giã 臼; \"đạo\" như \"gạo\" trong cách phát âm Nam Bộ. | Gương Hán-Việt | \"Đạo\" ít dùng trong tiếng Việt hiện đại; từ gốc thấy trong 稻田 (đạo điền — ruộng lúa). | Mở khoá kiến thức | Biết 稲 giúp đọc văn bản Nhật-Hán về nông nghiệp và nhận ra mối liên hệ với 稻 truyền thống.", "Tự nguyên_Xie": "Chữ 稲 (đọc dào) là dạng cải cách Nhật Bản (shinjitai) của 稻 (lúa nước). Theo Wiktionary, thành phần 旧 trong 稲 là biến thể của 臼 (cối xay). Chữ 稻 gốc gồm 禾 (lúa) và 臼 (cối) — hình ảnh giã lúa sau thu hoạch. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm", "Hạng Tần Suất (Jun Da)": "8093.0", "Tần Suất % (Jun Da)": "99.9994418721", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "稲", "Unihan_Traditional (Chữ Phồn thể)": "稲", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc kết hợp để chỉ cây lúa và các sản phẩm từ lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稸', '{"9000": "8094.0", "Chữ Trung Quốc": "稸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 稸 | súc | tượng hình | chữ hiếm, bộ 禾, nghĩa chưa rõ | 稸 thuộc bộ 禾 (hòa — lúa). Cấu trúc chi tiết và loại chữ chưa được xác nhận trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": bộ lúa (禾) với âm \"súc\" — như \"tích súc\" (tích lũy), tưởng tượng lúa được tích trữ. | Gương Hán-Việt | 稸 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 稸 giúp nhận diện ký tự trong từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 稸 (đọc xù) thuộc bộ 禾. Wiktionary không cung cấp nghĩa hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 畜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾畜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稸", "Unihan_Traditional (Chữ Phồn thể)": "稸", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động thu gom và tích trữ của cải hoặc lương thực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穜', '{"9000": "8095.0", "Chữ Trung Quốc": "穜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 禾 | hòa | biểu nghĩa | lúa — xác định thuộc nhóm ngũ cốc | 童 | đồng | biểu âm | đứa trẻ — cho âm đọc zhǒng/đồng | 穜 = 禾 (Hòa, biểu nghĩa: lúa) + 童 (Đồng, biểu âm); chữ hình thanh. Bộ 禾 xác định là ngũ cốc; 童 cung cấp âm đọc gần zhǒng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": lúa (禾) với âm từ đồng (童) — như đứa trẻ 童 chăm sóc ruộng lúa 禾. | Gương Hán-Việt | 穜 là chữ cổ hiếm; \"đồng\" phổ biến hơn trong 童 (đồng tử, đồng nhi). | Mở khoá kiến thức | Biết 穜 giúp phân biệt các chữ lúa gạo trong văn bản nông nghiệp và thực vật học cổ.", "Tự nguyên_Xie": "Đại triện | Theo Wiktionary, 穜 là chữ hình thanh: 禾 (lúa) biểu nghĩa, 童 biểu âm. Chữ chỉ một loại lúa gạo. Có hình đại triện cho thấy chữ được dùng từ thời Chu. Phân biệt với 種/种 (giống, trồng) dù âm đọc gần giống. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trồng trước chín sau", "Hạng Tần Suất (Jun Da)": "8095.0", "Tần Suất % (Jun Da)": "99.9994429056", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穜", "Unihan_Traditional (Chữ Phồn thể)": "穜", "Pinyin_Xie": "zhǒng", "Âm Hán Việt_Xie": "chúng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc gieo trồng ngũ cốc hoặc làm danh từ chỉ hạt giống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竒', '{"9000": "8096.0", "Chữ Trung Quốc": "竒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 9 | nét | 竒 | kỳ | tượng hình | dị thể của 奇 (kỳ — kỳ lạ, bất thường) | 竒 là dạng dị thể của 奇 (kỳ). Wiktionary ghi: \"Variant of 奇\". IDS: ⿳亠丷可 — cấu trúc gồm 亠 (nắp), 丷 (hai nét), và 可 (có thể). Không phân tích riêng hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": dạng cổ của 奇 — âm \"kỳ\" trong \"kỳ lạ\", \"kỳ diệu\" — điều gì đó bất thường và ấn tượng. | Gương Hán-Việt | \"Kỳ\" trong tiếng Việt: kỳ lạ, kỳ diệu, kỳ quan — đều từ gốc 奇/竒. | Mở khoá kiến thức | Biết 竒 giúp nhận ra dạng biến thể của 奇 trong văn bản cổ và tên địa danh Nhật Bản.", "Tự nguyên_Xie": "Chữ 竒 là dạng dị thể của 奇 (kỳ — kỳ lạ, số lẻ). Được dùng trong một số ký tự phái sinh như 﨑 (dạng tên địa danh Nhật). Wiktionary ghi là variant không chính thức. Nghĩa giống 奇: kỳ lạ, bất thường, số lẻ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竒", "Unihan_Traditional (Chữ Phồn thể)": "竒", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả sự việc kỳ lạ hoặc làm danh từ chỉ số lẻ trong toán học. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筶', '{"9000": "8097.0", "Chữ Trung Quốc": "筶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre — vật liệu làm đồ vật | 告 | cáo | biểu âm | báo cáo — cho âm đọc gào | 筶 = 竹 (Trúc, biểu nghĩa: tre) + 告 (Cáo, biểu âm); chữ hình thanh. Là dạng thay thế của 珓 (bói toán). Bộ 竹 xác định làm từ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": tre (竹) + cáo (告) — thanh bói toán bằng tre được \"cáo\" (báo) thiên ý cho người hỏi thần. | Gương Hán-Việt | 筶 là chữ chuyên dùng, \"cáo\" phổ biến hơn trong 告 (cáo trạng, báo cáo). | Mở khoá kiến thức | Biết 筶 giúp đọc văn bản về tín ngưỡng dân gian và tên địa danh Phúc Kiến.", "Tự nguyên_Xie": "Theo Wiktionary, 筶 là chữ hình thanh: 竹 (tre) biểu nghĩa, 告 biểu âm. Là dạng thay thế của 珓 — thanh bói toán làm bằng tre hoặc sừng, dùng tại các đền miếu. Cũng dùng trong tên địa danh (đảo Đông Cáo Bôi, Phúc Kiến). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "筶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筶", "Unihan_Traditional (Chữ Phồn thể)": "筶", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dụng cụ bằng tre dùng để xin keo, bói toán trong đền chùa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篬', '{"9000": "8098.0", "Chữ Trung Quốc": "篬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篬 | thương | tượng hình | giỏ tre | 篬 thuộc bộ 竹 (trúc — tre). Cấu trúc nội bộ chưa được phân tích trong Wiktionary. Âm qiāng gợi liên hệ với 蔣/槍.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": giỏ tre (竹) với âm \"thương\" — như chiếc giỏ thương lái dùng để chở hàng. | Gương Hán-Việt | 篬 là chữ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 篬 giúp nhận diện tên đồ vật bằng tre trong văn bản thủ công nghệ cổ điển.", "Tự nguyên_Xie": "Chữ 篬 (đọc qiāng) nghĩa là giỏ tre (bamboo basket). Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏ tre", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 倉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篬", "Unihan_Traditional (Chữ Phồn thể)": "篬", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đan bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籒', '{"9000": "8099.0", "Chữ Trung Quốc": "籒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 21 | nét | 籒 | trụ | tượng hình | chữ hiếm, liên quan đến chữ viết cổ (trụ văn) | 籒 thuộc bộ 竹 (trúc). Cấu trúc chi tiết chưa được phân tích trong Wiktionary. Có liên quan đến 籀 (chữ đại triện, kiểu chữ của Thái Sử Trụ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": bộ 竹 với âm \"trụ\" — như \"cột trụ\" của chữ viết cổ đại, kiểu chữ đại triện. | Gương Hán-Việt | 籒 liên quan đến 籀文 (trụ văn — kiểu chữ đại triện); \"trụ\" trong \"cột trụ\" tiếng Việt. | Mở khoá kiến thức | Biết 籒 giúp nhận diện thuật ngữ cổ văn tự học trong nghiên cứu chữ Hán.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 籒 (đọc zhòu) có thể là dị thể của 籀 — chỉ kiểu chữ đại triện (大篆) được gán cho Thái Sử Trụ thời Chu. Có hình tiểu triện và Lục thư thông. Wiktionary không cung cấp phân tích tự nguyên. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "璱", "Hạng Tần Suất (Jun Da)": "8099.0", "Tần Suất % (Jun Da)": "99.9994449728", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 㩅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮㩅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㩅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籒", "Unihan_Traditional (Chữ Phồn thể)": "籒", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "trụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng để chỉ lối chữ Trụ văn trong thư pháp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籞', '{"9000": "8100.0", "Chữ Trung Quốc": "籞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 23 | nét | 籞 | ngự | tượng hình | hàng rào, vườn ngự cấm | 籞 thuộc bộ 竹 (trúc — tre). Nghĩa là hàng rào (a fence). Cấu trúc chi tiết chưa được phân tích. Có thể là hình thanh với âm gần yù/ngự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngự\": hàng rào tre (竹) của vua — \"ngự\" như \"ngự lâm quân\", khu vực ngự cấm được rào chắn bằng tre. | Gương Hán-Việt | \"Ngự\" trong tiếng Việt: ngự lâm, ngự uyển — đều chỉ nơi chốn hoàng gia, liên quan đến 籞. | Mở khoá kiến thức | Biết 籞 giúp đọc văn bản cung đình và kiến trúc vườn ngự thời phong kiến.", "Tự nguyên_Xie": "Chữ 籞 (đọc yù) nghĩa là hàng rào, đặc biệt là vườn hoặc khu vực cấm được rào bằng tre (ngự uyển). Wiktionary không cung cấp phân tích tự nguyên. Bộ 竹 xác định vật liệu là tre. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lý", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 禦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮禦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籞", "Unihan_Traditional (Chữ Phồn thể)": "籞", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ngự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ khu vực rào chắn hoặc vườn nuôi thú của vua chúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籶', '{"9000": "8101.0", "Chữ Trung Quốc": "籶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 8 | nét | 籶 | thân | tượng hình | chữ hiếm, bộ 竹 | 籶 thuộc bộ 竹 (trúc — tre). Cấu trúc chi tiết và nghĩa chưa được xác nhận trong Wiktionary. Âm shēn gần với 身/深/申.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": bộ tre (竹) với âm \"thân\" — như cây tre thân thẳng tắp. | Gương Hán-Việt | 籶 là chữ cực hiếm, không xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 籶 giúp nhận diện ký tự trong danh sách Unicode hoặc từ điển chữ Hán hiếm.", "Tự nguyên_Xie": "Chữ 籶 (đọc shēn) thuộc bộ 竹. Wiktionary không cung cấp nghĩa hay phân tích tự nguyên. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "籶", "Unihan_Traditional (Chữ Phồn thể)": "籶", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại hạt ngũ cốc trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糂', '{"9000": "8102.0", "Chữ Trung Quốc": "糂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 糂 | sám | tượng hình | dạng dị thể của 糝 (sám), chỉ hạt gạo rắc vào | 糂 là dị thể của 糝 (sám). Không có cấu trúc hình thanh/hội ý độc lập; chữ tạo muộn. Tiểu triện còn lưu dấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sám\": hình ảnh hạt gạo (米) vương vãi — liên tưởng \"sám hối\" bằng cách rắc gạo cúng tế xưa. | Gương Hán-Việt | sám — ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn cổ chỉ cơm/gạo trộn. | Mở khoá kiến thức | Biết 糂 (sám) giúp nhận ra nhóm 糝/糂 — các chữ chỉ ngũ cốc trộn lẫn trong ẩm thực cổ.", "Tự nguyên_Xie": "Tiểu triện | 糂 là dị thể (variant) của 糝 (sám). Theo Wiktionary, mục từ chỉ dẫn xem 糝. Nghĩa gốc: hạt gạo/ngũ cốc trộn lẫn vào canh. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn chính thống; chưa có nguồn học thuật phân tích cấu trúc riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Bing", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糂", "Unihan_Traditional (Chữ Phồn thể)": "糂", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "sám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại thức ăn chế biến từ gạo và thịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糉', '{"9000": "8103.0", "Chữ Trung Quốc": "糉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 15 | nét | 米 | mễ | biểu nghĩa | gạo — chỉ nguyên liệu làm bánh | 㚇 | biểu âm | cho âm zòng | 糉 = 米 (Mễ, biểu nghĩa: gạo) + 㚇 (biểu âm, cho âm zòng); chữ hình thanh. Là dị thể của 粽.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tống\": 米 (gạo) + âm tống — bánh gạo nếp (粽/糉) gói lá tre, ăn tết Đoan Ngọ. | Gương Hán-Việt | tống — xuất hiện trong \"bánh tống\" (bánh chưng kiểu Trung Hoa), lễ Đoan Ngọ. | Mở khoá kiến thức | Biết 糉/粽 (tống) mở khoá từ 粽子 (bánh ú nếp), nhóm bánh truyền thống lễ Đoan Ngọ.", "Tự nguyên_Xie": "Theo Wiktionary, 糉 là chữ hình thanh (psc): 米 (mễ) biểu nghĩa chỉ gạo nếp, 㚇 biểu âm. Nghĩa: bánh gạo nếp gói lá, tức bánh chưng/bánh ú của Trung Hoa. Đây là dị thể của 粽 (tống) — cùng âm, cùng nghĩa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh gạo nếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "糉", "Unihan_Traditional (Chữ Phồn thể)": "糉", "Pinyin_Xie": "zòng", "Âm Hán Việt_Xie": "tống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại bánh làm từ gạo nếp gói trong lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綡', '{"9000": "8104.0", "Chữ Trung Quốc": "綡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 綡 | lương | tượng hình | dải lụa buộc mũ — chữ độc thể, cấu trúc nội bộ chưa rõ | 綡 không có phân tích hình thanh/hội ý được ghi nhận trong Wiktionary. Bộ thủ 糸 (mịch) gợi liên quan đến lụa/sợi. Chữ độc thể từ góc nhìn nguồn gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lương\": dải lụa (糸) mảnh — giống dải \"lương bổng\" buộc quanh mũ quan. | Gương Hán-Việt | lương — hiếm gặp trong tiếng Việt; liên quan đến văn phong cổ về trang phục lễ. | Mở khoá kiến thức | Biết 綡 (lương) giúp đọc văn bản lễ phục cổ Trung Hoa, phân biệt với 綾 (lăng — lụa hoa).", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc và nghĩa: 綡 (liáng) là dải lụa dùng để buộc mũ theo lễ phục cổ đại Trung Hoa. Không có phân tích cấu trúc hợp thể. Chưa có nguồn học thuật xác nhận cấu tạo chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綡", "Unihan_Traditional (Chữ Phồn thể)": "綡", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại chất liệu vải vóc cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綶', '{"9000": "8105.0", "Chữ Trung Quốc": "綶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 綶 | qua | tượng hình | chữ hiếm thuộc bộ 糸; nghĩa chưa rõ | 綶 không có nguồn phân tích cấu trúc. Bộ 糸 (mịch) gợi liên quan đến lụa/sợi. Chữ cực hiếm, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": chữ lụa (糸) hiếm — nhớ qua bộ thủ 糸 như các chữ vải vóc. | Gương Hán-Việt | qua — không dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết bộ 糸 nhận ra nhóm chữ liên quan đến lụa, sợi, dệt trong văn bản cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 綶 trong Wiktionary hay các từ điển chính. Bộ 糸 cho thấy liên quan đến lụa hoặc sợi dệt. Chưa có nguồn học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綶", "Unihan_Traditional (Chữ Phồn thể)": "綶", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể dùng làm danh từ chỉ sợi dây hoặc động từ chỉ hành động buộc lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緼', '{"9000": "8106.0", "Chữ Trung Quốc": "緼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緼 | uẩn | tượng hình | dị thể của 縕 — sợi gai rối, nghĩa bóng: mờ nhạt, rối ren | 緼 là dạng dị thể không chính thức của 縕 (uẩn), ghi nhận trong từ điển triều Minh 《重訂直音篇》. Phần 𥁕 trong 縕 được thay bằng 昷 tạo thành 緼. Không phân tích hình thanh/hội ý riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": lụa (糸) rối loạn — nhớ \"uẩn khúc\" (điều ẩn giấu, rối ren bên trong). | Gương Hán-Việt | uẩn — gặp trong \"uẩn khúc\" (điều ẩn giấu), \"uẩn súc\" (hàm chứa sâu xa). | Mở khoá kiến thức | Biết 緼/縕 (uẩn) mở khoá từ Hán-Việt \"uẩn khúc\", \"uẩn chứa\" — ý nghĩa ẩn chứa, sâu xa.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 緼 là dạng dị thể không chính thống của 縕, xuất hiện trong từ điển Minh triều 《重訂直音篇》. Nghĩa: sợi gai rối (tangled hemp), lụa tơ tả rối, hoặc theo nghĩa bóng: mơ hồ, lộn xộn. Bộ 糸 gợi liên quan đến sợi vải. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Miêu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緼", "Unihan_Traditional (Chữ Phồn thể)": "緼", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại sợi tơ hoặc bông đã cũ và rối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縁', '{"9000": "8107.0", "Chữ Trung Quốc": "縁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 縁 | duyên | tượng hình | viền vải, đường viền — truyền thống tự của 缘 | 縁 là dạng truyền thống của 缘 (duyên). Bộ 糸 (mịch) biểu nghĩa liên quan đến sợi/vải. Không có phân tích hợp thể trong nguồn. Nghĩa: viền vải, mép vải; rộng hơn: duyên phận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duyên\": viền lụa (糸) kết nối — nhớ \"duyên phận\", \"nhân duyên\" trong Phật giáo. | Gương Hán-Việt | duyên — rất phổ biến trong tiếng Việt: \"duyên số\", \"duyên phận\", \"nhân duyên\". | Mở khoá kiến thức | Biết 縁/缘 (duyên) mở khoá: 缘故 (duyên cớ, lý do), 缘分 (duyên phận), 无缘 (vô duyên).", "Tự nguyên_Xie": "縁 là truyền thống tự của 缘 (duyên). Không tìm thấy phân tích cấu trúc hình thanh/hội ý rõ ràng trong Wiktionary. Nghĩa gốc: mép/viền vải; mở rộng thành duyên phận, nguyên nhân. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縁", "Hạng Tần Suất (Jun Da)": "8107.0", "Tần Suất % (Jun Da)": "99.9994506574", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "縁", "Unihan_Traditional (Chữ Phồn thể)": "縁", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "duyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mối liên hệ giữa người với người hoặc mép của đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繤', '{"9000": "8108.0", "Chữ Trung Quốc": "繤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繤 | toản | tượng hình | dị thể của 纂 (toản) — biên soạn, biên tập | 繤 là dị thể của 纂 (toản). Không có phân tích hình thanh/hội ý riêng. Bộ 糸 (mịch) gợi liên quan đến sợi/kết nối — ý nghĩa bóng: kết tập văn bản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": xâu chuỗi (糸) văn bản lại — nhớ \"toản\" như \"toản tập\" (biên tập, tổng hợp). | Gương Hán-Việt | toản — hiếm trong tiếng Việt; liên quan đến \"toản\" trong \"biên toản\" (biên soạn). | Mở khoá kiến thức | Biết 繤/纂 (toản) giúp đọc tên sách cổ có chữ 纂: 纂修 (biên soạn), 纂辑 (tổng hợp).", "Tự nguyên_Xie": "Theo Wiktionary, 繤 là dị thể của 纂 (toản), nghĩa: biên soạn, biên tập sách vở. Bộ 糸 gợi ý kết nối, xâu chuỗi văn bản lại. Không có phân tích cấu trúc riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "繤", "Unihan_Traditional (Chữ Phồn thể)": "繤", "Pinyin_Xie": "zuǎn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Diễn tả hành động kết nối các sợi hoặc các phần lại với nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繧', '{"9000": "8109.0", "Chữ Trung Quốc": "繧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繧 | uẩn | tượng hình | chữ hiếm thuộc bộ 糸; liên quan đến kỹ thuật nhuộm màu dần | 繧 thuộc bộ 糸 (mịch). Không có phân tích cấu trúc hình thanh/hội ý trong nguồn. Chữ hiếm, chủ yếu xuất hiện trong văn cảnh Nhật Bản (繧繝 — kỹ thuật nhuộm/dệt màu dần).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": lụa (糸) ẩn chứa — nhớ cùng nhóm với 縕/緼 (uẩn = ẩn chứa, rối ren). | Gương Hán-Việt | uẩn — không dùng trong tiếng Việt thông dụng. | Mở khoá kiến thức | Biết bộ 糸 nhận ra nhóm chữ vải lụa; 繧 chủ yếu gặp trong thuật ngữ nghệ thuật cổ.", "Tự nguyên_Xie": "繧 không có phân tích nguồn gốc rõ ràng trong Wiktionary. Bộ 糸 gợi liên quan đến sợi/vải. Chữ này chủ yếu được biết qua tiếng Nhật trong thuật ngữ 繧繝 (ukon — kỹ thuật dệt màu chuyển dần). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 雲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹雲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繧", "Unihan_Traditional (Chữ Phồn thể)": "繧", "Pinyin_Xie": "yun", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng để mô tả các hoa văn trang trí hoặc hình vân mây trên vải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繬', '{"9000": "8110.0", "Chữ Trung Quốc": "繬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 19 | nét | 繬 | sắc | tượng hình | chữ hiếm thuộc bộ 糸; nghĩa chưa rõ | 繬 thuộc bộ 糸 (mịch). Wiktionary ghi âm sè nhưng không cung cấp phân tích cấu trúc hay nghĩa cụ thể. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": lụa (糸) màu sắc — nhớ \"sắc\" như \"sắc nét\", bộ 糸 liên quan đến vải. | Gương Hán-Việt | sắc — không dùng trong tiếng Việt hiện đại với nghĩa này. | Mở khoá kiến thức | Biết bộ 糸 nhận ra nhóm chữ lụa vải trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm đọc sè (Quảng: sik1) nhưng không có định nghĩa hay phân tích cấu trúc. Bộ 糸 gợi liên quan đến lụa/sợi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bọ cạp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 嗇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹嗇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嗇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繬", "Unihan_Traditional (Chữ Phồn thể)": "繬", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ các loại túi hoặc bao dùng để chứa đựng đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纃', '{"9000": "8111.0", "Chữ Trung Quốc": "纃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 纃 | tề | tượng hình | mượn từ tiếng Nhật; chỉ dùng trong 纃縗 (áo tang dài) | 纃 là chữ mượn từ tiếng Nhật (obor: ja). Chỉ dùng trong tổ hợp 纃縗 chỉ loại áo tang dài. Không có phân tích hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\": lụa (糸) chỉ tang phục — nhớ \"tề\" như \"chỉnh tề\" trong lễ nghi tang lễ. | Gương Hán-Việt | tề — không dùng trong tiếng Việt hiện đại với nghĩa này. | Mở khoá kiến thức | Biết 纃 (tề) giúp nhận diện thuật ngữ tang lễ cổ đại: 纃縗 (áo tang dài).", "Tự nguyên_Xie": "Theo Wiktionary, 纃 là chữ mượn từ tiếng Nhật ({{obor|zh|ja|纃}}). Trong tiếng Trung chỉ xuất hiện trong tổ hợp 纃縗 — loại áo tang dài. Âm đọc theo spelling pronunciation dựa trên 齊. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "纃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 齊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹齊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纃", "Unihan_Traditional (Chữ Phồn thể)": "纃", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chỉ loại vải có chất lượng thấp hoặc được dệt một cách thô sơ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纒', '{"9000": "8112.0", "Chữ Trung Quốc": "纒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 22 | nét | 纒 | triền | tượng hình | dị thể của 纏 (triền) — quấn, cuộn xung quanh | 纒 là dạng truyền thống/dị thể của 纏 (triền). Bộ 糸 (mịch) biểu nghĩa sợi/cuộn. Nghĩa: quấn, cuốn, ràng buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triền\": dây (糸) quấn xung quanh — nhớ \"triền miên\" (dây dưa, mãi không dứt). | Gương Hán-Việt | triền — gặp trong \"triền miên\" (dây dưa), \"vấn vương\", \"ràng buộc\". | Mở khoá kiến thức | Biết 纒/纏 (triền) mở khoá: 缠绕 (quấn quanh), 缠绵 (triền miên), 纠缠 (vướng bận).", "Tự nguyên_Xie": "纒 là dạng truyền thống của 纏 (triền). Không có phân tích nguồn gốc riêng trong Wiktionary. Nghĩa: quấn/cuộn quanh, ràng buộc — hình ảnh sợi chỉ (糸) quấn quanh vật thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "纺", "Hạng Tần Suất (Jun Da)": "8112.0", "Tần Suất % (Jun Da)": "99.9994547917", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "纒", "Unihan_Traditional (Chữ Phồn thể)": "纒", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "triền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Diễn tả hành động quấn quanh một vật hoặc sự vướng bận trong lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纗', '{"9000": "8113.0", "Chữ Trung Quốc": "纗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 24 | nét | 纗 | tuy | tượng hình | chữ hiếm thuộc bộ 糸; nghĩa chưa rõ | 纗 thuộc bộ 糸 (mịch). Wiktionary ghi hai âm zuī và xī nhưng không có định nghĩa. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": lụa (糸) mỏng manh — nhớ bộ 糸 như sợi tơ nhỏ. | Gương Hán-Việt | tuy — không dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết bộ 糸 nhận ra nhóm chữ sợi/lụa trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi hai âm đọc: zuī và xī (Quảng: kwai4, waa6, zeoi1) nhưng không có định nghĩa hay phân tích cấu trúc. Bộ 糸 gợi liên quan đến sợi/lụa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "纗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 巂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹巂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纗", "Unihan_Traditional (Chữ Phồn thể)": "纗", "Pinyin_Xie": "zuī", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chỉ các loại dây dùng để buộc hoặc treo đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罯', '{"9000": "8114.0", "Chữ Trung Quốc": "罯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 14 | nét | 罯 | ám | tượng hình | chữ thuộc bộ 网 (lưới); nghĩa chưa rõ | 罯 thuộc bộ 网 (võng — lưới). Wiktionary ghi âm ǎn nhưng không có định nghĩa rõ. Bộ 网 gợi hình ảnh lưới che phủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ám\": lưới (网) che tối — nhớ \"ám\" như \"ám muội\", \"ám ảnh\" (che khuất, tối tăm). | Gương Hán-Việt | ám — phổ biến trong tiếng Việt: \"ám ảnh\", \"ám muội\", \"bí ám\". | Mở khoá kiến thức | Biết 罯 (ám) liên kết với bộ 网 — nhóm chữ che phủ, bẫy, lưới trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi âm ǎn (Quảng: am2) nhưng không có định nghĩa cho 罯. Bộ 网 (lưới) gợi liên quan đến che phủ, bẫy. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "篯", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罯", "Unihan_Traditional (Chữ Phồn thể)": "罯", "Pinyin_Xie": "ǎn", "Âm Hán Việt_Xie": "ám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng để chỉ hành động che đậy hoặc bao phủ lên bề mặt vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羀', '{"9000": "8115.0", "Chữ Trung Quốc": "羀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 18 | nét | 羀 | lưu | tượng hình | cái bẫy cá, lưới bắt cá — bộ 网 gợi lưới | 羀 thuộc bộ 网 (võng — lưới). Nghĩa: bẫy cá, lưới bắt cá. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": lưới (网) bắt cá — nhớ \"lưu\" như \"lưu giữ\", bẫy lưu cá lại. | Gương Hán-Việt | lưu — không dùng trong tiếng Việt với nghĩa bẫy cá; phổ biến hơn trong \"lưu giữ\", \"lưu lạc\". | Mở khoá kiến thức | Biết bộ 网 nhận ra nhóm chữ lưới, bẫy, che phủ trong văn bản cổ.", "Tự nguyên_Xie": "Không có phân tích nguồn gốc của 羀 trong Wiktionary. Bộ 网 gợi hình ảnh lưới/bẫy. Nghĩa: bẫy bắt cá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "羀", "Hạng Tần Suất (Jun Da)": "8115.0", "Tần Suất % (Jun Da)": "99.999456342", "GavinGrover_Once (Chiết tự trực tiếp)": "网 + 畱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱网畱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "网", "Unihan_Simplified (Chữ Giản thể)": "羀", "Unihan_Traditional (Chữ Phồn thể)": "羀", "Pinyin_Xie": "liǔ", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chỉ các loại lưới hoặc dụng cụ chuyên dụng để đánh bắt thủy hải sản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耴', '{"9000": "8116.0", "Chữ Trung Quốc": "耴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 7 | nét | 耴 | ế | tượng hình | tai xệ xuống hoặc dái tai — bộ 耳 gợi tai | 耴 là chữ tượng hình (liushu: p) theo Wiktionary — có thể mô tả tai xệ xuống hoặc dái tai. Thuộc bộ 耳 (nhĩ). Bạch thư còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\": tai (耳) xệ xuống — nhớ \"ế\" liên quan đến tai, bộ 耳. | Gương Hán-Việt | ế — không dùng trong tiếng Việt hiện đại với nghĩa này. | Mở khoá kiến thức | Biết bộ 耳 nhận ra nhóm chữ liên quan đến tai, thính giác trong văn bản cổ.", "Tự nguyên_Xie": "Bạch thư | Theo Wiktionary, 耴 là chữ tượng hình ({{liushu|p}}) — có thể miêu tả tai xệ hoặc dái tai. Chữ rất cổ, còn lưu trong bạch thư (silk script). Không có phân tích hội ý hay hình thanh. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "耴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耴", "Unihan_Traditional (Chữ Phồn thể)": "耴", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để miêu tả hình dáng tai to hoặc làm danh từ chỉ bộ phận tai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肍', '{"9000": "8117.0", "Chữ Trung Quốc": "肍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 6 | nét | 肍 | cầu | tượng hình | chữ hiếm thuộc bộ 肉 (nhục — thịt); nghĩa chưa rõ | 肍 thuộc bộ 肉 (nhục). Không có phân tích cấu trúc hình thanh/hội ý trong nguồn. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": thịt (肉) tròn — nhớ \"cầu\" như hình tròn, bộ 肉 liên quan đến thân thể. | Gương Hán-Việt | cầu — không dùng trong tiếng Việt với nghĩa này. | Mở khoá kiến thức | Biết bộ 肉/月 nhận ra nhóm chữ thân thể, cơ quan nội tạng trong văn bản y học cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 肍 trong Wiktionary. Bộ 肉/月 (nhục) gợi liên quan đến thân thể, thịt. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "荍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肍", "Unihan_Traditional (Chữ Phồn thể)": "肍", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại thực vật hoặc món ăn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腨', '{"9000": "8118.0", "Chữ Trung Quốc": "腨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腨 | soạn | tượng hình | bắp chân — bộ 肉 chỉ bộ phận thân thể | 腨 thuộc bộ 肉/月 (nhục). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa: bắp chân (calf of leg). Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"soạn\": thịt (肉) ở chân — nhớ bắp \"soạn\" (bắp chân), bộ 肉 ở dưới. | Gương Hán-Việt | soạn — không dùng trong tiếng Việt hiện đại với nghĩa này. | Mở khoá kiến thức | Biết 腨 (soạn) giúp đọc văn bản y học cổ Trung Hoa mô tả bắp chân, kinh mạch vùng chân.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi âm shuàn và có tiểu triện nhưng không cung cấp phân tích cấu trúc. Bộ 肉 biểu nghĩa chỉ bộ phận thân thể. Nghĩa: bắp chân. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thịt lợn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腨", "Unihan_Traditional (Chữ Phồn thể)": "腨", "Pinyin_Xie": "shuàn", "Âm Hán Việt_Xie": "soạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ phần bắp thịt ở chân của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膗', '{"9000": "8119.0", "Chữ Trung Quốc": "膗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | 膗 | sậu | tượng hình | béo xấu, mập mạp bệ bệ — bộ 肉 chỉ thịt/thân thể | 膗 thuộc bộ 肉/月 (nhục). Wiktionary ghi nhiều nghĩa: béo xấu, đi khệnh khạng. Không có phân tích hình thanh/hội ý chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sậu\": thịt (肉) rủ xuống — hình ảnh người béo \"sậu sệu\", đi khệnh khạng. | Gương Hán-Việt | sậu — không dùng trong tiếng Việt chuẩn; gợi hình ảnh \"sậu sệu\" (béo bệ). | Mở khoá kiến thức | Biết 膗 (sậu) giúp đọc văn bản dân gian hoặc phương ngữ Hoa Nam mô tả hình thể.", "Tự nguyên_Xie": "Wiktionary ghi âm chuái với nhiều biến thể phương ngữ (Mân Nam, Quảng Đông). Nghĩa: béo xấu không di chuyển được, đi khệnh khạng. Có liên hệ đến 扭 (vặn) và 跩 (đi khệnh khạng). Bộ 肉 biểu nghĩa chỉ thân thể cồng kềnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mập mạp và bắp thịt nhão", "Hạng Tần Suất (Jun Da)": "8119.0", "Tần Suất % (Jun Da)": "99.9994584092", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膗", "Unihan_Traditional (Chữ Phồn thể)": "膗", "Pinyin_Xie": "chuái", "Âm Hán Việt_Xie": "suỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ đứng sau động từ hoặc bổ nghĩa cho danh từ để tả dáng vẻ béo phệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膟', '{"9000": "8120.0", "Chữ Trung Quốc": "膟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 15 | nét | ⺼ | nhục | biểu nghĩa | thịt/cơ thể — bộ 肉 dạng bên | 率 | suất | biểu âm | cho âm lǜ | 膟 = ⺼ (Nhục, biểu nghĩa: thịt/cơ thể) + 率 (Suất, biểu âm, cho âm lǜ); chữ hình thanh. Nghĩa: mỡ ruột, máu dùng trong tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lật\": thịt (⺼) kết hợp suất (率) — mỡ ruột dùng trong lễ \"lật\" (tế hiến máu). | Gương Hán-Việt | lật — không dùng trong tiếng Việt với nghĩa này; liên quan đến lễ tế cổ đại. | Mở khoá kiến thức | Biết 膟 (lật) giúp đọc văn bản lễ chế Chu Lễ mô tả nghi thức hiến tế.", "Tự nguyên_Xie": "Theo Wiktionary, 膟 là chữ hình thanh (psc): ⺼ (nhục) biểu nghĩa chỉ thịt/mỡ, 率 (suất) biểu âm. Nghĩa: mỡ bám quanh ruột, hoặc máu dùng trong lễ tế hiến sinh. Xuất hiện trong văn bản lễ chế cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế máu; mạng mỡ ở ruột", "Hạng Tần Suất (Jun Da)": "8120.0", "Tần Suất % (Jun Da)": "99.999458926", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 率", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月率", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "率", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膟", "Unihan_Traditional (Chữ Phồn thể)": "膟", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "suất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ phần mỡ ruột hoặc làm động từ chỉ nghi thức tế lễ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舦', '{"9000": "8121.0", "Chữ Trung Quốc": "舦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 10 | nét | 舦 | thái | tượng hình | bánh lái thuyền — bộ 舟 chỉ thuyền | 舦 thuộc bộ 舟 (chu — thuyền). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa (Quảng Đông): bánh lái thuyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\": thuyền (舟) lái hướng — nhớ bánh lái \"thái\" hướng con thuyền. | Gương Hán-Việt | thái — không dùng trong tiếng Việt với nghĩa bánh lái. | Mở khoá kiến thức | Biết bộ 舟 nhận ra nhóm chữ thuyền bè, hàng hải trong văn bản cổ.", "Tự nguyên_Xie": "Không có phân tích nguồn gốc của 舦 trong Wiktionary. Bộ 舟 gợi liên quan đến thuyền bè. Nghĩa trong tiếng Quảng Đông: bánh lái thuyền. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "舦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 太", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟太", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "太", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舦", "Unihan_Traditional (Chữ Phồn thể)": "舦", "Pinyin_Xie": "tài", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ bộ phận điều hướng của tàu thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艊', '{"9000": "8122.0", "Chữ Trung Quốc": "艊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 14 | nét | 艊 | bạc | tượng hình | chữ hiếm thuộc bộ 舟; nghĩa chưa rõ | 艊 thuộc bộ 舟 (chu — thuyền). Không có phân tích cấu trúc hay nghĩa rõ ràng trong nguồn. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": thuyền (舟) ghé bến — nhớ \"bạc\" như \"thuyền bạc bến\". | Gương Hán-Việt | bạc — không dùng với nghĩa thuyền trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết bộ 舟 nhận ra nhóm chữ thuyền, hàng hải trong văn bản cổ đại.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 艊 trong Wiktionary. Bộ 舟 gợi liên quan đến thuyền bè. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 帛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟帛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艊", "Unihan_Traditional (Chữ Phồn thể)": "艊", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ các loại tàu thuyền lớn chuyên chở hàng hóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菄', '{"9000": "8123.0", "Chữ Trung Quốc": "菄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菄 | đông | tượng hình | chữ hiếm thuộc bộ 艸 (thảo — cỏ); nghĩa chưa rõ | 菄 thuộc bộ 艸 (thảo). Wiktionary ghi âm dōng nhưng không có định nghĩa. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đông\": cỏ (艸) phương đông — nhớ bộ 艸 + âm đông như \"đông phương\". | Gương Hán-Việt | đông — phổ biến trong tiếng Việt: \"đông\" (mùa đông, phương đông). | Mở khoá kiến thức | Biết bộ 艸 nhận ra nhóm chữ thực vật trong văn bản thảo dược cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi âm dōng nhưng không có định nghĩa hay phân tích cấu trúc. Bộ 艸 gợi liên quan đến cây cỏ. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "菄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 東", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹東", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "東", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菄", "Unihan_Traditional (Chữ Phồn thể)": "菄", "Pinyin_Xie": "dōng", "Âm Hán Việt_Xie": "đông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong các danh từ riêng chỉ thảo mộc hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葾', '{"9000": "8124.0", "Chữ Trung Quốc": "葾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葾 | uyên | tượng hình | héo úa, tàn lụi — bộ 艸 chỉ cây cỏ | 葾 thuộc bộ 艸 (thảo). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa (cổ): héo, tàn úa. Chữ lỗi thời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyên\": cây cỏ (艸) héo tàn — nhớ \"uyên\" như \"uyển chuyển\" rồi \"uyên thâm\" héo tàn. | Gương Hán-Việt | uyên — gặp trong \"uyên ương\", \"uyên bác\"; không dùng với nghĩa héo tàn. | Mở khoá kiến thức | Biết 葾 (uyên) giúp đọc thơ ca cổ mô tả cây cỏ héo úa, sự tàn phai.", "Tự nguyên_Xie": "Wiktionary ghi âm yuān và nghĩa cổ: héo, tàn lụi (obs-std: to wither, to wilt). Ngoài ra còn ghi trong tiếng Quảng Đông với nghĩa mùi hôi. Bộ 艸 biểu nghĩa cây cỏ. Không có phân tích cấu trúc hợp thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葾", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 怨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹怨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "怨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葾", "Unihan_Traditional (Chữ Phồn thể)": "葾", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này dùng làm tính từ để miêu tả trạng thái khô héo của cây cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒕', '{"9000": "8125.0", "Chữ Trung Quốc": "蒕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒕 | uẩn | tượng hình | cây huệ Nhật Bản (Rohdea japonica) — bộ 艸 chỉ thực vật | 蒕 thuộc bộ 艸 (thảo). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa: cây huệ Nhật Bản (萬年青 — vạn niên thanh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uẩn\": cỏ (艸) xanh quanh năm — nhớ 蒕 là tên cây vạn niên thanh (万年青). | Gương Hán-Việt | uẩn — không dùng trong tiếng Việt với nghĩa tên cây. | Mở khoá kiến thức | Biết 蒕 (uẩn) giúp nhận diện tên cây dược thảo cổ đại trong văn bản thực vật học Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi âm yūn và nghĩa: cây Nippon lily (Rohdea japonica), còn gọi 萬年青 (vạn niên thanh). Xuất hiện trong tổ hợp 千年蒕, 茵蒕. Không có phân tích cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𥁕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𥁕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𥁕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒕", "Unihan_Traditional (Chữ Phồn thể)": "蒕", "Pinyin_Xie": "yūn", "Âm Hán Việt_Xie": "uẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại cỏ có mùi thơm đặc trưng thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒘', '{"9000": "8126.0", "Chữ Trung Quốc": "蒘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒘 | nhu | tượng hình | tên cây/cỏ cổ đại — bộ 艸 chỉ thực vật | 蒘 thuộc bộ 艸 (thảo). Không có phân tích hình thanh/hội ý. Chỉ dùng trong tổ hợp tên cây: 蘮蒘, 蕏蒘.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": cỏ (艸) mềm mại — nhớ \"nhu\" như \"nhu nhược\", bộ 艸 gợi cây cỏ. | Gương Hán-Việt | nhu — gặp trong \"nhu mì\", \"nhu cầu\" — không liên quan đến tên cây. | Mở khoá kiến thức | Biết 蒘 (nhu) giúp nhận diện tên thảo dược cổ trong bản thảo y học Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi âm ná/rú và nghĩa: chỉ dùng trong 蘮蒘 và 蕏蒘 — tên hai loại cây thảo mộc cổ đại. Không có phân tích cấu trúc hợp thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蒘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 挐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹挐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "挐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒘", "Unihan_Traditional (Chữ Phồn thể)": "蒘", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ loài rau hoặc làm động từ với nghĩa bao bọc, chứa đựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒧', '{"9000": "8127.0", "Chữ Trung Quốc": "蒧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒧 | điểm | tượng hình | chữ hiếm thuộc bộ 艸 (thảo — cỏ); nghĩa chưa rõ | 蒧 thuộc bộ 艸 (thảo). Không có phân tích cấu trúc hay nghĩa trong nguồn. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điểm\": cỏ (艸) điểm xuyết — nhớ bộ 艸 kết hợp với \"điểm\" như điểm nhỏ trên thảo mộc. | Gương Hán-Việt | điểm — phổ biến trong tiếng Việt: \"điểm số\", \"điểm tâm\" — không liên quan đến tên cây. | Mở khoá kiến thức | Biết bộ 艸 nhận ra nhóm chữ thực vật, thảo dược trong văn bản cổ.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 蒧 trong Wiktionary. Bộ 艸 gợi liên quan đến cây cỏ. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蒧", "Unihan_Traditional (Chữ Phồn thể)": "蒧", "Pinyin_Xie": "diǎn", "Âm Hán Việt_Xie": "điểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ thực vật hoặc làm động từ với nghĩa phân tích, giải thích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓃', '{"9000": "8128.0", "Chữ Trung Quốc": "蓃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蓃 | sấu | tượng hình | cây sấu, quả sấu — tên cây đặc trưng trong tiếng Việt Hán cổ | 蓃 thuộc bộ 艸 (thảo). Không có phân tích cấu trúc trong nguồn. Có đọc Hán-Việt \"sấu\" — liên quan đến cây sấu Việt Nam.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấu\": cỏ/cây (艸) chua — nhớ ngay cây sấu Hà Nội, quả sấu xanh chua đặc trưng. | Gương Hán-Việt | sấu — gắn liền với cây sấu, quả sấu — đặc sản ẩm thực miền Bắc Việt Nam. | Mở khoá kiến thức | Biết 蓃 (sấu) nhận ra tên cây sấu trong văn bản Hán-Nôm Việt Nam.", "Tự nguyên_Xie": "Không có phân tích nguồn gốc của 蓃 trong Wiktionary. Tuy nhiên, âm Hán-Việt \"sấu\" gợi liên quan đến tên cây sấu (Dracontomelon duperreanum) — cây đặc trưng của miền Bắc Việt Nam. Bộ 艸 gợi liên quan đến thực vật. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sấu; như \"cây sấu; quả sấu\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓃", "Unihan_Traditional (Chữ Phồn thể)": "蓃", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây ăn quả hoặc bộ phận của cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓆', '{"9000": "8129.0", "Chữ Trung Quốc": "蓆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓆 | tịch | tượng hình | chiếu rơm, chiếu cói — bộ 艸 gợi vật liệu thực vật | 蓆 thuộc bộ 艸 (thảo). Không có phân tích cấu trúc hợp thể trong nguồn. Là dạng truyền thống/dị thể của 席 (tịch — chiếu). Có tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tịch\": cỏ (艸) dệt thành chiếu — nhớ \"tịch\" như \"tịch thanh\" (chiếu trải ngồi thiền). | Gương Hán-Việt | tịch — gặp trong \"yến tịch\" (tiệc, chỗ ngồi), \"tịch\" nghĩa chỗ ngồi, chiếu. | Mở khoá kiến thức | Biết 蓆/席 (tịch) mở khoá: 席位 (chỗ ngồi, ghế), 酒席 (tiệc rượu), 出席 (tham dự).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 蓆 là dạng truyền thống của 席 (tịch). Wiktionary chỉ ghi {{Han etym}} nhưng không có phân tích. Bộ 艸 biểu nghĩa vật liệu thực vật (cỏ, rơm dùng dệt chiếu). Nghĩa: chiếu, đệm bằng cỏ/cói. Có tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 席", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹席", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "席", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓆", "Unihan_Traditional (Chữ Phồn thể)": "蓆", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại chiếu hoặc đệm lót để ngồi hoặc nằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔱', '{"9000": "8130.0", "Chữ Trung Quốc": "蔱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蔱 | sa | tượng hình | chữ hiếm thuộc bộ 艸; nghĩa chưa rõ | 蔱 thuộc bộ 艸 (thảo). Không có phân tích cấu trúc hay nghĩa trong nguồn. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\": cỏ (艸) sa mạc — nhớ bộ 艸 + âm sa như \"sa mạc\", \"sa thạch\". | Gương Hán-Việt | sa — gặp trong \"sa mạc\", \"phù sa\" — không liên quan đến tên cây. | Mở khoá kiến thức | Biết bộ 艸 nhận ra nhóm thực vật trong văn bản thảo dược cổ đại.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 蔱 trong Wiktionary. Bộ 艸 gợi liên quan đến cây cỏ. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 殺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹殺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔱", "Unihan_Traditional (Chữ Phồn thể)": "蔱", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây cỏ hoặc rau trong các tài liệu cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘔', '{"9000": "8131.0", "Chữ Trung Quốc": "蘔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘔 | quýnh | tượng hình | chữ hiếm thuộc bộ 艸; nghĩa chưa rõ | 蘔 thuộc bộ 艸 (thảo). Không có phân tích cấu trúc hay nghĩa trong nguồn. Chữ cực hiếm với nhiều nét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\": cỏ (艸) sáng rực — nhớ \"quýnh\" như \"quýnh quáng\", bộ 艸 gợi cây cỏ. | Gương Hán-Việt | quýnh — không dùng trong tiếng Việt với nghĩa này. | Mở khoá kiến thức | Biết bộ 艸 nhận ra nhóm thực vật trong văn bản cổ đại.", "Tự nguyên_Xie": "Không tìm thấy phân tích nguồn gốc của 蘔 trong Wiktionary. Bộ 艸 gợi liên quan đến cây cỏ. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 穎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹穎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "穎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘔", "Unihan_Traditional (Chữ Phồn thể)": "蘔", "Pinyin_Xie": "jiōng", "Âm Hán Việt_Xie": "quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân thảo hoặc củ cải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟨', '{"9000": "8132.0", "Chữ Trung Quốc": "蟨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟨 | quyết | tượng hình | chuột nhảy Siberia (Allactaga sibirica), hoặc thú huyền thoại — bộ 虫 chỉ động vật nhỏ | 蟨 thuộc bộ 虫 (trùng). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa: chuột nhảy Mông Cổ (Siberian jerboa, Allactaga sibirica), hoặc thú huyền thoại cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": sâu/thú (虫) nhảy vút — nhớ \"quyết\" như nhảy bật lên (quyết tâm), chuột nhảy Siberia. | Gương Hán-Việt | quyết — gặp trong \"quyết tâm\", \"quyết định\" — không liên quan đến tên thú. | Mở khoá kiến thức | Biết 蟨 (quyết) giúp nhận diện tên động vật cổ trong văn bản địa lý và bác vật học Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi âm jué (Quảng: kyut3) và nghĩa: chuột nhảy Siberia (Mongolian five-toed jerboa, Allactaga sibirica); ngoài ra còn là tên thú huyền thoại. Bộ 虫 biểu nghĩa chỉ động vật nhỏ/côn trùng. Không có phân tích cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Người lai Siberia", "Hạng Tần Suất (Jun Da)": "8132.0", "Tần Suất % (Jun Da)": "99.9994651274", "GavinGrover_Once (Chiết tự trực tiếp)": "厥 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厥虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟨", "Unihan_Traditional (Chữ Phồn thể)": "蟨", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài động vật gặm nhấm giống chuột nhảy thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠪', '{"9000": "8133.0", "Chữ Trung Quốc": "蠪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 22 | nét | 蠪 | lung | tượng hình | loài kiến lớn, hoặc tên thú/côn trùng huyền thoại — bộ 虫 | 蠪 thuộc bộ 虫 (trùng). Không có phân tích hình thanh/hội ý trong nguồn. Nghĩa: loài kiến lớn; hoặc dùng trong 蚵蠪, 蚗蠪, 蠪蛭 — các tên côn trùng/thú huyền thoại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": sâu (虫) to lớn — nhớ \"lung\" như \"long\" (rồng), con trùng huyền thoại to lớn. | Gương Hán-Việt | lung — không dùng trong tiếng Việt hiện đại; liên quan đến \"lung\" cổ. | Mở khoá kiến thức | Biết 蠪 (lung) giúp đọc văn bản bác vật học cổ Trung Hoa về côn trùng huyền thoại.", "Tự nguyên_Xie": "Wiktionary ghi âm lóng (Quảng: lung4) và ba nghĩa cổ: loài kiến lớn, tên dùng trong 蚵蠪, tên dùng trong 蚗蠪/蠪姪. Tất cả là nghĩa cổ lỗi thời. Bộ 虫 biểu nghĩa sinh vật nhỏ. Không có phân tích cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hà long 蚵蠪)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "龍 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龍虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龍", "Unihan_Simplified (Chữ Giản thể)": "蠪", "Unihan_Traditional (Chữ Phồn thể)": "蠪", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "long", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài côn trùng hoặc sâu bọ trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謟', '{"9000": "8134.0", "Chữ Trung Quốc": "謟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 謟 | thao | tượng hình | nịnh hót, ngờ vực — bộ 言 chỉ lời nói | 謟 thuộc bộ 言 (ngôn). Wiktionary chỉ ghi {{Han etym}} không có phân tích cấu trúc. Nghĩa: nịnh hót; hoặc ngờ vực, không chắc chắn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": lời nói (言) mơ hồ, nịnh nọt — nhớ \"thao\" như \"thao thiết\" (lời tâng bốc). | Gương Hán-Việt | thao — gặp trong \"thao lược\", \"thao túng\" — không liên quan đến nghĩa nịnh hót. | Mở khoá kiến thức | Biết 謟 (thao) giúp đọc văn bản cổ về nghi ngờ hoặc nịnh hót trong triều đình.", "Tự nguyên_Xie": "Wiktionary ghi {{Han etym}} và nghĩa: nịnh hót (flatter); ngờ vực, không chắc (suspect, be uncertain). Bộ 言 biểu nghĩa chỉ lời nói/ngôn ngữ. Không có phân tích cấu trúc hợp thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghi ngờ, ngờ vực, hoài nghi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謟", "Unihan_Traditional (Chữ Phồn thể)": "謟", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện trạng thái nghi ngờ hoặc không tin tưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讙', '{"9000": "8135.0", "Chữ Trung Quốc": "讙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 24 | nét | 讙 | hoan | tượng hình | kêu rầm, hân hoan — tự thể độc lập | 讙 là chữ độc thể, không phân tích được thành phần rõ ràng qua lsCodes. Chữ mang nghĩa tiếng ồn vui mừng, có liên hệ với 歡 (hoan). Chưa có nguồn phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoan\": chữ nói lên sự hân hoan — đám đông la hét vui mừng, ầm ĩ như hội. | Gương Hán-Việt | \"hoan\" trong \"hoan hỉ\" (喜), \"hân hoan\" — niềm vui sướng rộn ràng | Mở khoá kiến thức | Biết 讙 mở khoá các từ cổ văn chỉ tiếng ồn đám đông: 讙呼 (hoan hô), 讙嘩 (huyên náo).", "Tự nguyên_Xie": "Tiểu triện | 讙 (huān) là dạng văn ngôn chỉ tiếng ồn ào, xôn xao của đám đông. Wiktionary ghi nhận chữ có dạng tiểu triện (seal script) còn lưu lại. Chữ là dạng thay thế của 歡 (hoan, vui mừng). Trong Sử Ký, ''諸將盡讙'' nghĩa là ''các tướng đều xôn xao''. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoan; như \"hân hoan; hoan hỉ; truy hoan\" (gdhn)\n(Động) Làm rầm rĩ. ◇Sử Kí 史記: Thị nhật nãi bái Bình vi đô úy; sử vi tham thừa; điển hộ quân; chư tướng tận hoan 是日乃拜平為都尉; 使為參乘; 典護軍; 諸將盡讙 (Trần Thừa tướng thế gia 陳丞相世家) Hôm đó bèn phong (Trần) Bình làm đô úy; cho giữ chức tham thừa; cai quản các tướng quân; các tướng đều xôn xao.(Tính) Vui mừng. § Thông hoan 歡.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讙", "Unihan_Traditional (Chữ Phồn thể)": "讙", "Pinyin_Xie": "huān", "Âm Hán Việt_Xie": "hoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ sự làm rầm rĩ hoặc làm tính từ chỉ trạng thái vui vẻ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谽', '{"9000": "8136.0", "Chữ Trung Quốc": "谽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 14 | nét | 谽 | hám | tượng hình | miệng mở rộng, hố sâu — tự thể độc lập | 谽 không có phân tích linh kiện qua lsCodes. Chữ thường xuất hiện trong từ ghép 谽谺 (hám nha) mô tả vực sâu hoặc miệng hố mở rộng. Chưa có nguồn phân tích cấu trúc chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hám\": miệng hố há hốc, sâu hoắm — như cái hàm mở to nuốt chửng. | Gương Hán-Việt | \"hám\" gợi hình ảnh miệng (口) há rộng, vực thẳm — dùng trong cổ thi miêu tả địa hình hiểm trở | Mở khoá kiến thức | Biết 谽 mở khoá từ cổ văn 谽谺 (hám nha) — vực núi hoác sâu, thường gặp trong thơ tả cảnh.", "Tự nguyên_Xie": "谽 (hān) là chữ văn ngôn, chỉ dùng trong tổ hợp 谽谺, mô tả miệng hố hoặc vực núi mở toác ra. Wiktionary ghi nhận chữ chỉ xuất hiện trong từ ghép này. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miệng hoặc mở", "Hạng Tần Suất (Jun Da)": "8136.0", "Tần Suất % (Jun Da)": "99.9994682281", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 含", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷含", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "含", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "谽", "Unihan_Traditional (Chữ Phồn thể)": "谽", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả trạng thái trống rỗng, há to của hang động. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踨', '{"9000": "8137.0", "Chữ Trung Quốc": "踨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 踨 | tung | tượng hình | bước chân, theo dấu — tự thể độc lập | 踨 không có phân tích linh kiện qua lsCodes. Bộ thủ 足 (túc, chân) có thể suy ra từ cấu trúc, gợi ý liên quan đến bước chân. Chưa có nguồn phân tích chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tung\": dấu chân để lại — theo tung tích người đi trước. | Gương Hán-Việt | \"tung\" trong \"tung tích\" (踪跡) — dấu vết, manh mối của người hay vật đã qua | Mở khoá kiến thức | Biết 踨 liên hệ với 踪 (tung tích) — mở khoá nhóm chữ chỉ dấu vết, theo dõi.", "Tự nguyên_Xie": "踨 (zōng) là chữ hiếm gặp liên quan đến bước chân hoặc theo dấu vết. Gần nghĩa với 踪 (tung, dấu vết, tung tích). Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "踨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "踨", "Unihan_Traditional (Chữ Phồn thể)": "踨", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dấu vết để lại của người hoặc vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躱', '{"9000": "8138.0", "Chữ Trung Quốc": "躱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 13 | nét | 躱 | đóa | tượng hình | tránh né, ẩn núp — biến thể của 躲 | 躱 là biến thể chữ viết của 躲 (đóa, tránh né). Cả hai đều có bộ 身 (thân, thân thể) gợi ý hành động dùng thân mình để né tránh. Chưa có phân tích lsCodes chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đóa\": cái thân (身) co ro trốn — đóa tránh nguy hiểm, núp kín một góc. | Gương Hán-Việt | \"đóa\" — tránh né, ẩn mình; cùng nghĩa với 躲 trong văn ngôn | Mở khoá kiến thức | Biết 躱 mở khoá nhóm chữ tránh né: 躲 (đóa), 躲避 (tránh né), 躱開 (lẩn tránh).", "Tự nguyên_Xie": "躱 (duǒ) là dạng biến thể của 躲, chỉ hành động trốn tránh, né tránh, ẩn núp. Cấu trúc gồm bộ 身 (thân thể) kết hợp yếu tố biểu âm. Chữ 躲 phổ biến hơn trong văn viết hiện đại. Chưa có nguồn học thuật Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tránh, né, núp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 朶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身朶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躱", "Unihan_Traditional (Chữ Phồn thể)": "躱", "Pinyin_Xie": "duǒ", "Âm Hán Việt_Xie": "đóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng cần né tránh hoặc đứng độc lập trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輗', '{"9000": "8139.0", "Chữ Trung Quốc": "輗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 輗 | nghê | tượng hình | thanh ngang ách xe bò — tự thể độc lập | 輗 không có phân tích lsCodes. Bộ 車 (거, xe) có thể suy ra, gợi ý bộ phận xe. Wiktionary xác nhận nghĩa là thanh ngang dùng để móc ách vào xe bò (oxcart). Chưa có nguồn phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\": cái chốt nối ách xe — không có 輗 thì xe bò không thể lăn bánh, như người không có tín nghĩa. | Gương Hán-Việt | \"nghê\" — bộ phận kết nối xe ách; xuất hiện trong Luận Ngữ như ẩn dụ về tín nghĩa | Mở khoá kiến thức | Biết 輗 mở khoá điển cố Luận Ngữ: 大車無輗 — xe không có chốt nối thì vô dụng, người không có tín thì bỏ.", "Tự nguyên_Xie": "Tiểu triện | Lưu Thư Thông | 輗 (ní) chỉ thanh ngang (crossbar) dùng để gắn ách vào xe bò trong văn hóa cổ Trung Hoa. Chữ xuất hiện trong Luận Ngữ: ''大車無輗，小車無軏'' (xe lớn không có 輗, xe nhỏ không có 軏 thì không thể chạy được). Đây là ẩn dụ về tín nghĩa làm nền tảng. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "𫐐", "Unihan_Traditional (Chữ Phồn thể)": "輗", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đóng vai trò chủ ngữ hoặc tân ngữ trong văn ngôn để chỉ bộ phận của xe cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋕', '{"9000": "8140.0", "Chữ Trung Quốc": "鋕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋕 | chí | tượng hình | khắc ghi, khắc chữ — tự thể độc lập | 鋕 không có phân tích lsCodes. Bộ 金 (kim, kim loại) gợi ý dụng cụ kim loại dùng để khắc. Nghĩa là khắc ghi, khắc chữ lên vật liệu. Chưa có nguồn phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": bộ 金 (kim loại) dùng để khắc — chí nguyện được khắc sâu như dùi sắt ghi vào đá. | Gương Hán-Việt | \"chí\" — khắc ghi, ghi nhớ sâu; cùng gốc với 誌 (chí, ghi chép) | Mở khoá kiến thức | Biết 鋕 liên hệ với 誌 (ghi chép) và 志 (chí hướng) — nhóm chữ mang nghĩa ghi lại, lưu dấu.", "Tự nguyên_Xie": "鋕 (zhì) chỉ hành động khắc ghi, khắc chữ, đặc biệt trên vật liệu cứng dùng dụng cụ kim loại. Liên hệ với 誌/志 (chí, ghi chép, ghi nhớ). Chưa có nguồn học thuật Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khắc ghi", "Hạng Tần Suất (Jun Da)": "8140.0", "Tần Suất % (Jun Da)": "99.9994713288", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 志", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金志", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "志", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋕", "Unihan_Traditional (Chữ Phồn thể)": "鋕", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ chỉ sự việc cần ghi nhớ hoặc làm danh từ chỉ bia ký. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎚', '{"9000": "8141.0", "Chữ Trung Quốc": "鎚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鎚 | chùy | tượng hình | cái búa, cái chùy — biến thể của 錘 | 鎚 là biến thể của 錘 (chùy, cái búa/quả cân). Bộ 金 (kim loại) biểu nghĩa; phần còn lại biểu âm. Wiktionary xác nhận 鎚 là dạng thay thế (variant) của 錘. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chùy\": bộ 金 (sắt) hình tượng cái búa nặng — chùy đập xuống, tiếng vang rầm. | Gương Hán-Việt | \"chùy\" trong \"tiếng chùy\" (tiếng búa đập), \"chùy sắt\" — vũ khí hoặc dụng cụ hình búa | Mở khoá kiến thức | Biết 鎚 mở khoá từ vựng công cụ và võ khí: 鐵鎚 (búa sắt), 流星鎚 (lưu tinh chùy — vũ khí chuỗi búa).", "Tự nguyên_Xie": "鎚 (chuí) là biến thể chữ viết của 錘, chỉ cái búa hoặc vật hình búa. Bộ 金 (kim loại) gợi ý vật liệu kim loại. Trong võ thuật cổ đại, 鎚 chỉ loại vũ khí dạng chùy. Wiktionary liệt kê 鎚 là alt form của 錘. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái búa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 追", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金追", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "追", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎚", "Unihan_Traditional (Chữ Phồn thể)": "鎚", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ công cụ gõ đập hoặc làm động từ với nghĩa là nện, gõ bằng búa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯶', '{"9000": "8142.0", "Chữ Trung Quốc": "鯶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鯶 | hỗn | tượng hình | cá trắm cỏ — biến thể của 鯇 | 鯶 là biến thể của 鯇 (hỗn, cá trắm cỏ/white amur). Bộ 魚 (ngư, cá) biểu nghĩa. Wiktionary xác nhận đây là alt form của 鯇. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗn\": bộ 魚 (ngư) — con cá hỗn đục (trắm cỏ) sống trong ao đục ngầu. | Gương Hán-Việt | \"hỗn\" — cá trắm cỏ, loài cá nước ngọt; cùng gốc với 鯇 | Mở khoá kiến thức | Biết 鯶 mở khoá nhóm tên cá nước ngọt có bộ 魚: 鯇 (trắm cỏ), 鰱 (cá mè), 鱅 (cá hoa).", "Tự nguyên_Xie": "鯶 (hùn/huàn) là biến thể của 鯇 — cá trắm cỏ (grass carp, Ctenopharyngodon idella), loài cá nước ngọt quan trọng trong văn hóa và ẩm thực Trung Hoa. Bộ 魚 (cá) biểu nghĩa. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá trắm cỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯶", "Unihan_Traditional (Chữ Phồn thể)": "鯶", "Pinyin_Xie": "hǔn", "Âm Hán Việt_Xie": "hỗn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài cá nước ngọt, đóng vai trò chủ ngữ hoặc tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳋', '{"9000": "8143.0", "Chữ Trung Quốc": "鳋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鳋 | tao | tượng hình | loài cá giống cá tầm — chữ cổ | 鳋 không có phân tích lsCodes. Bộ 鱼/魚 (ngư, cá) biểu nghĩa; phần còn lại có thể biểu âm. Wiktionary ghi nhận đây là chữ lỗi thời (obs-std) chỉ loài cá giống cá tầm (sturgeon). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bộ 魚 (cá) + âm tao — loài cá tao nhã như cá tầm quý hiếm. | Gương Hán-Việt | \"tao\" — tên cổ loài cá giống cá tầm; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鳋 giúp nhận diện chữ cổ chỉ tên cá trong văn bản lịch sử tự nhiên Trung Hoa.", "Tự nguyên_Xie": "鳋 (sāo) là chữ cổ, lỗi thời, chỉ loài cá nước ngọt trông giống cá tầm (sturgeon). Bộ 魚 (ngư, cá) biểu nghĩa. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện chi tiết. Chữ tạo muộn, ít gặp trong văn bản hiện đại. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lươn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳋", "Unihan_Traditional (Chữ Phồn thể)": "鳋", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài thủy sản trong văn bản cổ hoặc chuyên ngành sinh học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹒', '{"9000": "8144.0", "Chữ Trung Quốc": "鹒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹒 | canh | tượng hình | con hoàng anh — chỉ dùng trong 鸧鹒 | 鹒 không có phân tích lsCodes. Bộ 鸟 (điểu, chim) biểu nghĩa; phần còn lại có thể biểu âm. Chữ chỉ xuất hiện trong từ ghép 鸧鹒 (thương canh) chỉ con chim hoàng anh (oriole). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": bộ 鸟 (chim) — con canh (hoàng anh) hót canh khuya, tiếng trong veo. | Gương Hán-Việt | \"canh\" trong \"thương canh\" (鸧鹒) — chim hoàng anh, tiếng hót trong trẻo | Mở khoá kiến thức | Biết 鹒 mở khoá từ cổ thi: 鸧鹒 (thương canh) — hoàng anh ca hót trong rừng xuân.", "Tự nguyên_Xie": "鹒 (gēng) là thành tố trong 鸧鹒 — tên cổ của chim hoàng anh (Oriolus chinensis). Bộ 鸟 (điểu, chim) biểu nghĩa. Chữ chỉ tồn tại trong tổ hợp này, không độc lập. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thương canh 鶬鶊,鸧鹒)", "Hạng Tần Suất (Jun Da)": "8144.0", "Tần Suất % (Jun Da)": "99.9994739127", "GavinGrover_Once (Chiết tự trực tiếp)": "庚 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰庚鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹒", "Unihan_Traditional (Chữ Phồn thể)": "鶊", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ thương tạo thành từ ghép chỉ loài chim hoàng anh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篭', '{"9000": "8145.0", "Chữ Trung Quốc": "篭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篭 | lung | tượng hình | lồng, giỏ — biến thể Nhật của 籠 | 篭 là biến thể chữ viết (chủ yếu trong chữ Hán Nhật Bản) của 籠 (lung, lồng/rổ). Bộ 竹 (trúc, tre) biểu nghĩa — lồng làm bằng tre. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": bộ 竹 (tre) đan thành cái lung (lồng) — nhốt chim trong lồng tre. | Gương Hán-Việt | \"lung\" trong \"lồng\" (lồng chim), \"lung tre\" — vật đan bằng tre để nhốt chim hoặc đựng đồ | Mở khoá kiến thức | Biết 篭 mở khoá từ vựng vật dụng tre: 鳥籠 (lồng chim), 竹籠 (giỏ tre), 籠罩 (bao phủ, trùm lên).", "Tự nguyên_Xie": "篭 (lóng) là biến thể của 籠, chỉ cái lồng hoặc rổ đan bằng tre. Bộ 竹 (trúc, tre) biểu nghĩa — vật dụng đan bằng tre. Dạng 篭 phổ biến trong chữ Hán Nhật (shinjitai) hơn trong chữ Hán Trung Quốc truyền thống. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lồng; như \"cái lồng\" (vhn) lung; như \"lung (lồng chim)\" (btcn) luông; như \"luông tuồng\" (gdhn) luồng; như \"cây luồng\" (gdhn) trông; như \"trông chờ\" (gdhn)", "Hạng Tần Suất (Jun Da)": "8145.0", "Tần Suất % (Jun Da)": "99.9994744295", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 竜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮竜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "竜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篭", "Unihan_Traditional (Chữ Phồn thể)": "篭", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ đồ dùng tre nứa để nhốt hoặc làm động từ chỉ sự bao phủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縜', '{"9000": "8146.0", "Chữ Trung Quốc": "縜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縜 | vân | tượng hình | sợi dây, dải — tự thể độc lập | 縜 không có phân tích lsCodes. Bộ 糸 (mịch, tơ/sợi) biểu nghĩa — liên quan đến sợi chỉ, dải vải. Nghĩa cụ thể chưa được Wiktionary xác định (rfdef). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": bộ 糸 (sợi tơ) uốn lượn như mây (vân) — sợi chỉ bay nhẹ như mây trời. | Gương Hán-Việt | \"vân\" — sợi dây, dải chỉ; ít xuất hiện trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 縜 giúp nhận diện nhóm chữ bộ 糸 chỉ sợi vải: 線 (tuyến), 縛 (phọc), 縫 (phùng).", "Tự nguyên_Xie": "縜 (yún) là chữ có bộ 糸 (tơ, sợi), gợi ý liên quan đến sợi chỉ hoặc dải vải. Wiktionary ghi chú ''rfdef'' — nghĩa cụ thể chưa được xác định đầy đủ trong tài liệu học thuật hiện đại. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. Chữ tạo muộn, ít gặp. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 員", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹員", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "員", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縜", "Unihan_Traditional (Chữ Phồn thể)": "縜", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại dây buộc thời cổ đại, đóng vai trò tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腣', '{"9000": "8147.0", "Chữ Trung Quốc": "腣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腣 | đệ | tượng hình | bụng to, bụng bự — tự thể độc lập | 腣 không có phân tích lsCodes. Bộ 肉/月 (nhục, thịt/thân thể) biểu nghĩa — liên quan đến bụng, thân thể. Chỉ xuất hiện trong 腣胿 (bụng to phình ra). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đệ\": bộ 肉 (thịt) phình ra — cái bụng đệ (bự) của người ăn nhiều. | Gương Hán-Việt | \"đệ\" — bụng to; chỉ dùng trong cổ văn y học hoặc miêu tả thân thể | Mở khoá kiến thức | Biết 腣 giúp đọc cổ văn y học Trung Hoa mô tả hình thể bụng phình.", "Tự nguyên_Xie": "腣 (dì) là chữ chỉ bụng to, phình ra. Wiktionary ghi chú chỉ dùng trong tổ hợp 腣胿. Bộ 月/肉 (nhục, thân thể) biểu nghĩa. Chưa có nguồn học thuật phân tích cấu trúc linh kiện chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bụng to; bụng bự", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腣", "Unihan_Traditional (Chữ Phồn thể)": "腣", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để miêu tả hình dáng bụng to hoặc béo phì. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赲', '{"9000": "8148.0", "Chữ Trung Quốc": "赲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 9 | nét | 赲 | lực | tượng hình | bước đi nhanh, gấp — tự thể độc lập | 赲 không có phân tích lsCodes. Bộ 走 (tẩu, đi/chạy) biểu nghĩa — liên quan đến bước chân, di chuyển. Nghĩa cụ thể chưa được Wiktionary xác định đầy đủ. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lực\": bộ 走 (chạy) + sức lực — bước đi lực lưỡng, nhanh mạnh. | Gương Hán-Việt | \"lực\" — bước đi nhanh, có lực; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 赲 giúp nhận diện nhóm chữ bộ 走 chỉ cách đi: 起 (khởi), 越 (việt), 超 (siêu).", "Tự nguyên_Xie": "赲 (lì) là chữ hiếm, bộ 走 (đi, chạy) gợi ý hành động di chuyển nhanh. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "赲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赲", "Unihan_Traditional (Chữ Phồn thể)": "赲", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu làm động từ biểu thị hành động chạy nhanh hoặc dốc sức lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馻', '{"9000": "8149.0", "Chữ Trung Quốc": "馻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 馻 | duẫn | tượng hình | lông ngựa mọc ngược chiều — chữ cổ | 馻 không có phân tích lsCodes. Bộ 馬 (mã, ngựa) biểu nghĩa — liên quan đến ngựa. Wiktionary xác nhận nghĩa là lông ngựa mọc ngược chiều (horse hair growing in opposite directions). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duẫn\": bộ 馬 (ngựa) — lông con ngựa duẫn (mọc ngược), dấu hiệu thú quý trong thuật giám mã. | Gương Hán-Việt | \"duẫn\" — lông ngựa xoáy ngược; thuật ngữ giám mã cổ đại | Mở khoá kiến thức | Biết 馻 giúp đọc cổ văn về giám mã, tướng ngựa trong văn học Trung Hoa.", "Tự nguyên_Xie": "馻 (yǔn) là chữ cổ, lỗi thời (obs-std), chỉ loại lông ngựa mọc ngược chiều — một đặc điểm được chú ý trong thuật giám mã (xem tướng ngựa) thời cổ đại Trung Hoa. Bộ 馬 (ngựa) biểu nghĩa. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "黦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 允", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬允", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "允", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "馻", "Unihan_Traditional (Chữ Phồn thể)": "馻", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "duẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ để mô tả màu sắc vàng đen hoặc vết ố bẩn trên bề mặt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磞', '{"9000": "8150.0", "Chữ Trung Quốc": "磞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磞 | bằng | tượng hình | tiếng đá va nhau, tiếng nổ đá — tự thể độc lập | 磞 không có phân tích lsCodes. Bộ 石 (thạch, đá) biểu nghĩa — liên quan đến đá. Phần còn lại có thể biểu âm. Gợi ý tiếng động khi đá va chạm. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bộ 石 (đá) + âm pēng — tiếng bằng (đá nổ), đá va nhau kêu bình bằng. | Gương Hán-Việt | \"bằng\" — tiếng đá va chạm; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 磞 giúp đọc cổ văn mô tả tiếng động đá đổ, núi lở.", "Tự nguyên_Xie": "磞 (pēng) là chữ mô phỏng âm thanh, bộ 石 (đá) + âm biểu âm, chỉ tiếng đá va nhau, đổ vỡ, hoặc vật cứng va chạm tạo âm mạnh. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật Wiktionary phân tích chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 崩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石崩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磞", "Unihan_Traditional (Chữ Phồn thể)": "磞", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này thường dùng làm từ tượng thanh mô tả âm thanh va đập mạnh của đất đá. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睕', '{"9000": "8151.0", "Chữ Trung Quốc": "睕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睕 | uyển | tượng hình | nhìn, liếc mắt — tự thể độc lập | 睕 không có phân tích lsCodes. Bộ 目 (mục, mắt) biểu nghĩa — liên quan đến mắt, nhìn. Nghĩa cụ thể chưa được Wiktionary xác định đầy đủ. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": bộ 目 (mắt) uyển chuyển — đôi mắt liếc nhẹ nhàng, uyển chuyển. | Gương Hán-Việt | \"uyển\" — nhìn nhẹ, liếc mắt; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 睕 giúp nhận diện nhóm chữ bộ 目 chỉ hành động mắt: 看 (khán), 睛 (tinh), 瞟 (phiểu).", "Tự nguyên_Xie": "睕 (wǎn) là chữ hiếm, bộ 目 (mắt) gợi ý hành động nhìn. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "睕", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睕", "Unihan_Traditional (Chữ Phồn thể)": "睕", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả vẻ đẹp của đôi mắt hoặc làm động từ chỉ hành động nhìn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞜', '{"9000": "8152.0", "Chữ Trung Quốc": "瞜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 瞜 | lâu | tượng hình | liếc nhìn, nhìn lén — tự thể độc lập | 瞜 không có phân tích lsCodes. Bộ 目 (mục, mắt) biểu nghĩa — hành động dùng mắt. Wiktionary xác nhận nghĩa là nhìn lướt, liếc mắt (to glance). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": bộ 目 (mắt) — mắt lâu (nhìn lâu) liếc theo, theo dõi từ xa. | Gương Hán-Việt | \"lâu\" — liếc nhìn, nhìn lén; dùng trong cổ văn và phương ngữ Mân Nam | Mở khoá kiến thức | Biết 瞜 giúp đọc văn bản phương ngữ Mân Nam (Hokkien) và cổ văn mô tả cử chỉ mắt.", "Tự nguyên_Xie": "瞜 (lōu/lóu) là chữ văn ngôn và phương ngữ, chỉ hành động nhìn lướt, liếc nhìn nhanh. Bộ 目 (mắt) biểu nghĩa. Gặp trong tổ hợp 瞘瞜, 矖瞜. Wiktionary ghi hai âm: lōu (nhìn lướt) và lǘ (dùng trong 眗瞜). Chưa có nguồn học thuật phân tích cấu trúc linh kiện chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "瞜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 婁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目婁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "䁖", "Unihan_Traditional (Chữ Phồn thể)": "瞜", "Pinyin_Xie": "lōu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ trong khẩu ngữ để chỉ hành động nhìn hoặc xem xét cái gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碠', '{"9000": "8153.0", "Chữ Trung Quốc": "碠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碠 | đính | tượng hình | đá phẳng, nền đá — tự thể độc lập | 碠 không có phân tích lsCodes. Bộ 石 (thạch, đá) biểu nghĩa — liên quan đến đá. Nghĩa cụ thể chưa được Wiktionary xác định đầy đủ. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": bộ 石 (đá) chắc đính — tảng đá đính (chắc) nằm yên không lay chuyển. | Gương Hán-Việt | \"đính\" — đá phẳng chắc chắn; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 碠 giúp nhận diện nhóm chữ bộ 石: 確 (xác), 磐 (bàn), 碑 (bi).", "Tự nguyên_Xie": "碠 (dìng) là chữ hiếm, bộ 石 (đá) gợi ý liên quan đến đá hoặc bề mặt đá phẳng. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "碠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 亭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石亭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碠", "Unihan_Traditional (Chữ Phồn thể)": "碠", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ loại đá cứng hoặc tính từ miêu tả sự vững chãi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簘', '{"9000": "8154.0", "Chữ Trung Quốc": "簘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 簘 | tiêu | tượng hình | sáo dọc, tiêu — biến thể giản của 簫 | 簘 là dạng giản hoá của 簫 (tiêu, sáo dọc), thay thành phần 肅 bằng 粛. Bộ 竹 (trúc, tre) biểu nghĩa — nhạc cụ làm bằng tre. Wiktionary xác nhận 簘 là biến thể (rocsgsv) của 簫.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ 竹 (tre) — cây tiêu (sáo tre) thổi lên tiếng trong veo lạnh lẽo như gió thu. | Gương Hán-Việt | \"tiêu\" trong \"tiêu sáo\" (tiêu = sáo dọc) — nhạc cụ truyền thống, tượng trưng cho sự thanh tao | Mở khoá kiến thức | Biết 簘/簫 mở khoá từ vựng âm nhạc cổ điển: 洞簫 (đổng tiêu — sáo dọc), 鳳簫 (phụng tiêu).", "Tự nguyên_Xie": "簘 (xiāo) là biến thể chữ viết của 簫 — sáo dọc nhiều ống (panpipes) hoặc sáo dọc đơn ống. Bộ 竹 (trúc, tre) biểu nghĩa. Wiktionary ghi {{Han simp|簫|f=肅|t=粛}} — đơn giản hoá thành phần 肅. Tiêu (簫) là nhạc cụ truyền thống Trung Hoa, gắn với hình ảnh tiên nhân, tao nhã. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 粛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮粛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簘", "Unihan_Traditional (Chữ Phồn thể)": "簘", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ một loại nhạc cụ thổi truyền thống làm bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腃', '{"9000": "8155.0", "Chữ Trung Quốc": "腃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腃 | quỹ | tượng hình | liên quan đến dạ dày — tự thể độc lập | 腃 không có phân tích lsCodes. Bộ 月/肉 (nhục, thân thể/thịt) biểu nghĩa — liên quan đến bộ phận cơ thể. Nghĩa gần với 胃 (vị, dạ dày). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ 肉 (thịt) — cơ quan nội tạng quỹ (bị thương tổn), cổ y dùng để chỉ tình trạng dạ dày. | Gương Hán-Việt | \"quỹ\" — bộ phận cơ thể; dùng trong cổ y văn Trung Hoa | Mở khoá kiến thức | Biết 腃 giúp đọc cổ văn y học Trung Hoa mô tả nội tạng.", "Tự nguyên_Xie": "腃 (kuì) là chữ hiếm, bộ 月/肉 (thân thể) gợi ý liên quan đến bộ phận nội tạng, cụ thể có thể là dạ dày hoặc bụng. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "胃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腃", "Unihan_Traditional (Chữ Phồn thể)": "腃", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ dạ dày hoặc động từ chỉ sự phình to ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腵', '{"9000": "8156.0", "Chữ Trung Quốc": "腵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 腵 | gia | tượng hình | mập mạp, béo — tự thể độc lập | 腵 không có phân tích lsCodes. Bộ 月/肉 (nhục, thịt) biểu nghĩa — liên quan đến thịt, thân thể. Nghĩa là mập mạp, béo tốt. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gia\": bộ 肉 (thịt) + gia tăng — thịt gia tăng, cơ thể mập mạp sung mãn. | Gương Hán-Việt | \"gia\" — mập mạp, béo tốt; dùng trong cổ văn miêu tả thân thể | Mở khoá kiến thức | Biết 腵 giúp đọc cổ văn y học và văn học mô tả hình thể con người.", "Tự nguyên_Xie": "腵 (jiā) là chữ chỉ sự mập mạp, béo tốt. Bộ 月/肉 (thịt, thân thể) biểu nghĩa. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mập", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腵", "Unihan_Traditional (Chữ Phồn thể)": "腵", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ để miêu tả trạng thái cơ thể béo tốt hoặc nhiều thịt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓳', '{"9000": "8157.0", "Chữ Trung Quốc": "蓳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 堇 | cẩn | biểu âm | 蓳 = 艸 (Thảo/Tháu, biểu nghĩa: cỏ/thực vật) + 堇 (Cẩn, biểu âm: jǐn). Chữ hình thanh — 艸 cho biết đây là loài thực vật, 堇 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩn\": 艸 (cỏ) + 堇 (cẩn âm) — hoa cẩn (violet) cỏ dại màu tím, mọc khiêm nhường. | Gương Hán-Việt | \"cẩn\" — hoa tím (violet), loài hoa cỏ dại nhỏ bé; dùng trong tên thực vật học | Mở khoá kiến thức | Biết 蓳 mở khoá nhóm tên thực vật bộ 艸: 菊 (cúc), 蘭 (lan), 蓮 (liên).", "Tự nguyên_Xie": "蓳 (jǐn) là chữ hình thanh: 艸 (thảo, cỏ) biểu nghĩa + 堇 (cẩn) biểu âm. Wiktionary xác nhận qua {{Han compound|艸|堇|ls=psc|c1=s|c2=p}}. Nghĩa: loài cây thuộc họ Viola verecunda (cây tím), một loại hoa tím nhỏ mọc dại. Có trong danh pháp 三色蓳 (hoa tím ba màu, pansy). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 堇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹堇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓳", "Unihan_Traditional (Chữ Phồn thể)": "蓳", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại rau hoặc loại đất sét mịn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覇', '{"9000": "8158.0", "Chữ Trung Quốc": "覇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 19 | nét | 覇 | bá | tượng hình | bá chủ, kẻ cường quyền — biến thể của 霸 | 覇 là biến thể truyền thống của 霸 (bá, bá chủ). Chữ có dạng đồng (bronze) và tiểu triện (seal) còn lưu. Bộ 西 (tây) và 革 (cách) gợi ý kết hợp ý nghĩa quyền lực áp đảo. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": kẻ bá chủ dùng sức mạnh như mưa (雨) phủ xuống — ai không phục thì bị nghiền nát. | Gương Hán-Việt | \"bá\" trong \"bá chủ\" (覇主), \"ác bá\" — kẻ dùng sức mạnh cai trị, trái với vương đạo | Mở khoá kiến thức | Biết 覇 mở khoá từ chính trị lịch sử: 覇主 (bá chủ), 五覇 (ngũ bá), 覇道 (bá đạo — cai trị bằng sức mạnh).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lưu Thư Thông | 覇 (bà) là biến thể của 霸, chỉ kẻ bá chủ, người cậy sức mạnh để thống trị. Dạng kim văn (bronze) và tiểu triện của chữ còn lưu lại. Trong lịch sử Trung Hoa, 五覇 (Ngũ Bá) là năm chư hầu quyền lực nhất thời Xuân Thu. 覇 phân biệt với 王 (vương): bá dùng sức mạnh, vương dùng đức trị. Chưa có nguồn Wiktionary phân tích cấu trúc chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bá; như \"ác bá (người cậy mạnh hiếp yếu)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "1835.0", "Tần Suất % (Jun Da)": "96.4663364251", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 䩗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀䩗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䩗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "霸", "Unihan_Traditional (Chữ Phồn thể)": "覇", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ kẻ thống trị hoặc động từ chỉ hành động chiếm đoạt quyền lực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銝', '{"9000": "8159.0", "Chữ Trung Quốc": "銝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銝 | tu | tượng hình | vật kim loại cổ — tự thể độc lập | 銝 không có phân tích lsCodes. Bộ 金 (kim loại) biểu nghĩa. Nghĩa cụ thể không được Wiktionary xác định. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": bộ 金 (kim loại) — vật kim loại tu (cũ, xưa) không còn ai nhắc đến. | Gương Hán-Việt | \"tu\" — vật kim loại cổ; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 銝 giúp nhận diện nhóm chữ bộ 金 chỉ dụng cụ cổ đại.", "Tự nguyên_Xie": "銝 (xiū) là chữ hiếm, bộ 金 (kim loại) gợi ý liên quan đến kim khí. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 休", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金休", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "休", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銝", "Unihan_Traditional (Chữ Phồn thể)": "銝", "Pinyin_Xie": "xiū", "Âm Hán Việt_Xie": "tu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đây là một chữ hiếm dùng để chỉ một loại vật liệu kim loại trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巛', '{"9000": "8160.0", "Chữ Trung Quốc": "巛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巛 | Số nét | 3 | nét | 巛 | xuyên | tượng hình | dòng nước chảy — tự thể tượng hình | 巛 là tự thể tượng hình (pictograph) mô tả ba dòng nước chảy song song. Wiktionary xác nhận đây là liushu tượng hình (pictograph of water flowing). Liên hệ mật thiết với 川 (xuyên) và 水 (thủy). Chưa liên hệ với 兪/俞.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuyên\": ba vạch song song — ba dòng nước xuyên qua đồng bằng, như sông Xuyên. | Gương Hán-Việt | \"xuyên\" trong \"xuyên qua\" — dòng nước chảy xuyên, đồng bằng có nhiều sông | Mở khoá kiến thức | Biết 巛 mở khoá bộ thủ chỉ địa hình nước: 川 (xuyên, sông), 州 (châu, bãi đất giữa sông).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Lưu Thư Thông | 巛 (chuān) là chữ tượng hình cổ, vẽ ba dòng nước chảy song song — mô tả sông ngòi hoặc đồng bằng. Wiktionary phân loại là {{liushu|p}} (pictograph) của nước chảy. Chữ này là nguồn gốc của 川 (xuyên, sông) và liên hệ với 水 (thủy, nước). Trong giáp cốt văn, dạng chữ này xuất hiện rất sớm mô tả địa hình sông ngòi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng nước, sông; cánh đồng", "Hạng Tần Suất (Jun Da)": "8160.0", "Tần Suất % (Jun Da)": "99.9994832149", "GavinGrover_Once (Chiết tự trực tiếp)": "㇛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿳ (3 phần hàng dọc)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿳㇛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "巛", "Unihan_Traditional (Chữ Phồn thể)": "巛", "Pinyin_Xie": "chuān", "Âm Hán Việt_Xie": "xuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện như một bộ thủ hoặc ký tự tượng hình chỉ dòng chảy của nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐴', '{"9000": "8161.0", "Chữ Trung Quốc": "鐴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鐴 | tế | tượng hình | mài dao/kiếm — xem 鐾 | 鐴 không có phân tích lsCodes. Bộ 金 (kim loại) biểu nghĩa. Nghĩa chỉ sang 鐾 (mài sắc dao/lưỡi kiếm). Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": bộ 金 (kim loại) — mài tế (mài sắc) lưỡi dao cho bén như gương. | Gương Hán-Việt | \"tế\" — mài sắc kim loại; xem 鐾 để tra nghĩa đầy đủ hơn | Mở khoá kiến thức | Biết 鐴 liên hệ với 鐾 — nhóm chữ chỉ mài, giũa kim loại trong thủ công truyền thống.", "Tự nguyên_Xie": "鐴 (bì) là chữ dẫn sang 鐾 — hành động mài dao/lưỡi kiếm cho sắc bén. Bộ 金 (kim loại) biểu nghĩa. Nghĩa cụ thể liên quan đến mài kim loại. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"鐾\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐴", "Unihan_Traditional (Chữ Phồn thể)": "鐴", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng để chỉ hành động mài hoặc giũa các vật dụng bằng kim loại cho sắc bén. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑵', '{"9000": "8162.0", "Chữ Trung Quốc": "鑵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 25 | nét | 鑵 | quán | tượng hình | cái lọ, cái hộp kim loại — tự thể độc lập | 鑵 không có phân tích lsCodes. Bộ 金 (kim loại) biểu nghĩa — đồ đựng bằng kim loại. Nghĩa là cái lọ, hộp thiếc, bình kim loại. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\": bộ 金 (kim loại) — cái quán (lọ) kim loại đựng thức ăn hoặc nước. | Gương Hán-Việt | \"quán\" — lọ, hộp thiếc; dùng phổ biến trong tiếng Quảng Đông | Mở khoá kiến thức | Biết 鑵 mở khoá từ vựng đồ dùng: 茶鑵 (hộp trà), 鐵鑵 (hộp thiếc).", "Tự nguyên_Xie": "鑵 (guàn) chỉ cái lọ, hộp hoặc bình làm bằng kim loại. Bộ 金 (kim loại) biểu nghĩa. Chữ được dùng trong tiếng Quảng Đông cho các loại hộp thiếc, lon đồ hộp. Chưa có nguồn học thuật Wiktionary phân tích cấu trúc linh kiện chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lọ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 雚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金雚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑵", "Unihan_Traditional (Chữ Phồn thể)": "鑵", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại đồ chứa bằng kim loại hoặc gốm sứ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隩', '{"9000": "8163.0", "Chữ Trung Quốc": "隩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 14 | nét | 隩 | áo | tượng hình | bờ sông cong, nơi ấm áp — tự thể độc lập | 隩 không có phân tích lsCodes. Bộ 阜/阝 (phụ, đất cao, bờ dốc) biểu nghĩa — liên quan đến địa hình đất, bờ sông. Wiktionary ghi hai âm: yù (bờ sông cong) và ào (nơi xa ấm áp). Có dạng tiểu triện còn lưu. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": bộ 阝 (bờ đất) — nơi bờ sông áo (cong, khuất gió), ấm áp như nước Úc. | Gương Hán-Việt | \"áo\" trong \"Úc\" (澳大利亞/Úc Đại Lợi Á) — nước Úc, vùng ấm áp xa xôi; cùng gốc với 澳 | Mở khoá kiến thức | Biết 隩 mở khoá nhóm chữ chỉ địa hình bờ nước: 澳 (áo, cảng), 湾 (loan, vịnh), 岸 (ngạn, bờ).", "Tự nguyên_Xie": "Tiểu triện | Lưu Thư Thông | 隩 (yù/ào) là chữ cổ có hai nghĩa: (1) bờ sông nơi khúc uốn — bờ cao ven sông cong; (2) nơi xa xôi ấm áp, có thể ở được. Bộ 阜 (đất cao, bờ dốc) biểu nghĩa. Wiktionary ghi dạng thay thế là 澳 (ào) và 燠 (ấm). Có dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật phân tích cấu trúc linh kiện chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấm áp; nước Úc, châu Úc", "Hạng Tần Suất (Jun Da)": "8163.0", "Tần Suất % (Jun Da)": "99.9994847652", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 奥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝奥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隩", "Unihan_Traditional (Chữ Phồn thể)": "隩", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "úc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng để miêu tả thời tiết ấm áp hoặc chỉ một địa điểm khuất gió, kín đáo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飮', '{"9000": "8164.0", "Chữ Trung Quốc": "飮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 飮 | ẩm | tượng hình | uống, nước uống — biến thể truyền thống của 飲 | 飮 là biến thể truyền thống của 飲 (ẩm, uống). Bộ 食 (thực, ăn/thức ăn) biểu nghĩa — liên quan đến ăn uống. Có dạng Lưu Thư Thông còn lưu. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ẩm\": bộ 食 (ăn) + hành động uống — ẩm thực = uống (ẩm) và ăn (thực). | Gương Hán-Việt | \"ẩm\" trong \"ẩm thực\" (飮食) — uống và ăn, văn hóa ẩm thực Việt Nam cũng dùng từ này | Mở khoá kiến thức | Biết 飮 mở khoá từ vựng ẩm thực: 飮食 (ẩm thực), 飮料 (nước uống), 冷飮 (đồ uống lạnh).", "Tự nguyên_Xie": "Lưu Thư Thông | 飮 (yǐn) là biến thể của 飲, chỉ uống, nước uống, thuốc nước. Bộ 食 (thức ăn, ăn uống) biểu nghĩa. 飮食 (ẩm thực) là cụm từ quan trọng trong văn hóa Trung Hoa chỉ ăn uống nói chung. Có dạng Lưu Thư Thông còn lưu. Wiktionary xác nhận 飮 là biến thể (alt form) của 飲. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uống; nước uống; thuốc nước", "Hạng Tần Suất (Jun Da)": "8164.0", "Tần Suất % (Jun Da)": "99.9994857988", "GavinGrover_Once (Chiết tự trực tiếp)": "𩙿 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𩙿欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𩙿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "飮", "Unihan_Traditional (Chữ Phồn thể)": "飮", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "ẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Đứng trước danh từ chỉ đồ uống hoặc dùng như danh từ chỉ các loại thức uống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飰', '{"9000": "8165.0", "Chữ Trung Quốc": "飰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 飰 | phạn | tượng hình | cơm, ăn cơm — biến thể của 飯 | 飰 là biến thể của 飯 (phạn, cơm/ăn cơm). Bộ 食 (thực, thức ăn) biểu nghĩa. Wiktionary xác nhận 飰 là dạng thay thế (variant form) của 飯. Chưa có lsCodes trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạn\": bộ 食 (ăn) — bữa phạn (bữa cơm), hạt cơm dẻo thơm mỗi ngày. | Gương Hán-Việt | \"phạn\" trong \"cơm phạn\" — bữa ăn, cơm gạo; \"cúng phạn\" trong nghi lễ Phật giáo | Mở khoá kiến thức | Biết 飰/飯 mở khoá từ vựng bữa ăn: 飯碗 (chén cơm), 飯桌 (bàn ăn), 米飯 (cơm gạo).", "Tự nguyên_Xie": "飰 (fàn) là biến thể của 飯, chỉ cơm hoặc hành động ăn cơm. Bộ 食 (thức ăn) biểu nghĩa. 飯 là một trong những từ thiết yếu nhất trong văn hóa Hán — 吃飯 (ăn cơm) là câu chào hỏi thường ngày. Wiktionary xác nhận 飰 là dạng cổ/biến thể của 飯. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm; ăn cơm", "Hạng Tần Suất (Jun Da)": "8165.0", "Tần Suất % (Jun Da)": "99.9994863156", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 卞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠卞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "飰", "Unihan_Traditional (Chữ Phồn thể)": "飰", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ món cơm hoặc động từ chỉ hành động ăn uống nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餇', '{"9000": "8166.0", "Chữ Trung Quốc": "餇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 餇 | đồng | tượng hình | đồ ăn, lương thực — tự thể độc lập | 餇 không có phân tích lsCodes. Bộ 食 (thực, thức ăn) biểu nghĩa — liên quan đến thức ăn, lương thực. Nghĩa là đồ ăn, thức ăn. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ 食 (thức ăn) — đồng ăn (cùng ăn), thức ăn cho mọi người. | Gương Hán-Việt | \"đồng\" — đồ ăn, lương thực; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 餇 giúp nhận diện nhóm chữ bộ 食 chỉ thức ăn: 餐 (xan), 饌 (soạn), 饒 (nhiêu).", "Tự nguyên_Xie": "餇 (tóng) chỉ đồ ăn, thức ăn hoặc lương thực. Bộ 食 (thức ăn) biểu nghĩa. Nghĩa cụ thể không được Wiktionary phân tích chi tiết. Chữ tạo muộn, ít gặp trong văn bản hiện đại. Chưa có nguồn học thuật phân tích cấu trúc linh kiện. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ ăn", "Hạng Tần Suất (Jun Da)": "8166.0", "Tần Suất % (Jun Da)": "99.9994868324", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餇", "Unihan_Traditional (Chữ Phồn thể)": "餇", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ chung các loại thực phẩm hoặc đồ ăn được chuẩn bị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饐', '{"9000": "8167.0", "Chữ Trung Quốc": "饐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 20 | nét | 食 | thực | biểu nghĩa | thức ăn, ăn uống | 壹 | nhất | biểu âm | 饐 = 食 (Thực, biểu nghĩa: thức ăn) + 壹 (Nhất, biểu âm: yī→yì). Chữ hình thanh — 食 cho biết liên quan đến thức ăn, 壹 cho âm đọc. Cơm nát/cơm thiu là trạng thái thức ăn bị hỏng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\": 食 (thức ăn) bị ế (hỏng) — cơm ế thiu không ai ăn. | Gương Hán-Việt | \"ế\" — thức ăn ôi thiu; xuất hiện trong Luận Ngữ như tiêu chuẩn ăn uống của Khổng Tử | Mở khoá kiến thức | Biết 饐 mở khoá điển cố Luận Ngữ về tiêu chuẩn ẩm thực: 食饐而餲，不食 — Khổng Tử không ăn đồ ôi.", "Tự nguyên_Xie": "饐 (yì) là chữ hình thanh: 食 (thực, thức ăn) biểu nghĩa + 壹 (nhất) biểu âm. Wiktionary xác nhận qua {{Han compound|食|壹|ls=psc|c1=s|c2=p|t1=food; to eat}}. Nghĩa: cơm nát, thức ăn thiu/ôi. Xuất hiện trong Luận Ngữ: ''食饐而餲，魚餒而肉敗，不食'' — cơm thiu và cá thịt ươn thì Khổng Tử không ăn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm nát, cơm thiu", "Hạng Tần Suất (Jun Da)": "8167.0", "Tần Suất % (Jun Da)": "99.9994873491", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 壹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠壹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饐", "Unihan_Traditional (Chữ Phồn thể)": "饐", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng để miêu tả tình trạng cơm bị hỏng, ôi thiu do để lâu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痃', '{"9000": "8168.0", "Chữ Trung Quốc": "痃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 痃 | huyễn | tượng hình | hạch bẹn, cục cứng ở bụng dưới — tự thể độc lập | 痃 không có phân tích lsCodes. Bộ 疒 (nạch/bệnh) biểu nghĩa — liên quan đến bệnh tật. Nghĩa là hạch ở bẹn hoặc cục cứng ở vùng bụng dưới, thuật ngữ y học cổ Trung Hoa. Chưa có phân tích linh kiện chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": bộ 疒 (bệnh) — cái hạch huyễn (cục u) ở bẹn, đông y dùng để chỉ bệnh tích tụ. | Gương Hán-Việt | \"huyễn\" — hạch bẹn, khối cứng trong bụng; thuật ngữ đông y cổ điển | Mở khoá kiến thức | Biết 痃 giúp đọc cổ thư đông y: 痃癖 (huyễn tích) — các chứng tích tụ trong bụng.", "Tự nguyên_Xie": "痃 (xuán) là thuật ngữ y học cổ Trung Hoa chỉ hạch hoặc cục cứng ở vùng bẹn/hạ bụng. Bộ 疒 (bệnh) biểu nghĩa. Trong đông y, 痃癖 (huyễn tích) chỉ các khối cứng trong bụng. Wiktionary ghi nhận âm đọc nhưng định nghĩa chưa đầy đủ. Chưa có nguồn học thuật phân tích cấu trúc linh kiện chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạch ở bẹn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痃", "Unihan_Traditional (Chữ Phồn thể)": "痃", "Pinyin_Xie": "xuán", "Âm Hán Việt_Xie": "hiền, huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong các từ ghép chỉ chứng bệnh liên quan đến kết hạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駞', '{"9000": "8169.0", "Chữ Trung Quốc": "駞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 駞 | đà | tượng hình | lạc đà; dạng cổ của 駝 | 駞 là dạng cổ (variant) của 駝 — chữ tượng hình chỉ con lạc đà. Không có phân tích hình-thanh riêng biệt; toàn bộ tự dạng đồng nhất với 駝.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": bộ 馬 (mã, ngựa) gợi liên tưởng con vật — nhưng 駞 không phải ngựa mà là lạc đà, kẻ vượt sa mạc khi ngựa đã bỏ cuộc. | Gương Hán-Việt | đà trong ''lạc đà'' (駱駝) — con vật vượt sa mạc | Mở khoá kiến thức | Biết 駞/駝 mở khoá: 駱駝 (lạc đà), 驼峰 (bướu lạc đà), 驼色 (màu be).", "Tự nguyên_Xie": "駞 là dị thể (variant form) của 駝 (lạc đà). Theo Wiktionary, chữ này chỉ được ghi nhận dưới dạng tham chiếu về 駝 mà không có phân tích glyph độc lập. Trong tiếng Việt Hán-Việt, 駝 đọc là ''đà'', xuất hiện trong ''lạc đà'' (lạc 駱 + đà 駝). Đây là chữ cực kỳ hiếm, chủ yếu xuất hiện trong văn bản cổ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lạc đà 駱駝,骆驼)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駞", "Unihan_Traditional (Chữ Phồn thể)": "駞", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là dạng chữ cổ hoặc dị thể của chữ đà trong từ lạc đà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴜', '{"9000": "8170.0", "Chữ Trung Quốc": "鴜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴜 | từ | tượng hình | tên một loài chim cổ chưa xác định | 鴜 thuộc bộ 鳥 (điểu, chim), nhưng cấu trúc thành phần chưa được phân tích trong CHISE. Tự dạng gợi ý đây là chữ chỉ loài chim cụ thể, ghi theo dạng tượng hình kết hợp bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"từ\": bộ 鳥 (điểu) cho biết đây là chim; âm \"từ\" gần với 此 (thử = này) — con chim 鴜 ẩn danh, chưa ai biết tên đầy đủ. | Gương Hán-Việt | từ — ít xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết bộ 鳥 mở khoá họ chữ chim: 鶴 (hạc), 鵬 (bằng), 鷹 (ưng), 鴿 (cáp).", "Tự nguyên_Xie": "Tiểu triện | Chữ 鴜 có âm Trung cổ (Middle Chinese) và cổ âm (Old Chinese) ghi nhận trong Wiktionary, nhưng định nghĩa bị đánh dấu là chưa có nội dung (rfdef). Tiểu triện của 鴜 đã được lưu lại. Đây là tên một loài chim chưa được xác định rõ trong văn liệu còn sót. Chưa có nguồn học thuật xác nhận nghĩa cụ thể. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鴜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "𪉈", "Unihan_Traditional (Chữ Phồn thể)": "鴜", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu xuất hiện trong các văn bản cổ để chỉ một loại chim cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睅', '{"9000": "8173.0", "Chữ Trung Quốc": "睅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睅 | hãn | tượng hình | mắt to lồi ra | 睅 thuộc bộ 目 (mục, mắt). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Chữ này dùng để mô tả đôi mắt to và lồi ra ngoài — một đặc điểm ngoại hình trong văn học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãn\": bộ 目 (mắt) kết hợp với âm ''hãn'' — đôi mắt 睅 to đùng, lồi ra như muốn thoát khỏi hốc mắt. | Gương Hán-Việt | hãn — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết bộ 目 mở khoá: 眼 (nhãn), 瞳 (đồng), 睫 (tiệp), 眶 (khuông).", "Tự nguyên_Xie": "Theo Wiktionary, 睅 mang nghĩa hình dung từ mô tả mắt to và lồi ra (big and protuberant), dùng trong văn ngữ. Chữ thuộc bộ 目 (mắt). Không có phân tích glyph-origin chi tiết trong nguồn. Âm Hán-Việt đọc là ''hãn''. Chưa có nguồn học thuật đầy đủ xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt to; mắt trợn lồi ra", "Hạng Tần Suất (Jun Da)": "8173.0", "Tần Suất % (Jun Da)": "99.9994904499", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睅", "Unihan_Traditional (Chữ Phồn thể)": "睅", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng để miêu tả hình dáng đôi mắt to hoặc trợn ngược lên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睍', '{"9000": "8174.0", "Chữ Trung Quốc": "睍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睍 | hiện | tượng hình | nhìn với vẻ sợ hãi; thận trọng | 睍 thuộc bộ 目 (mục, mắt). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE, nhưng tiểu triện đã được lưu lại. Chữ này ghi lại ánh mắt nhìn trong trạng thái sợ hãi, thận trọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiện\": bộ 目 (mắt) — đôi mắt 睍 ''hiện'' ra vẻ thận trọng, lo âu như người đang rình rập, sợ sệt. | Gương Hán-Việt | hiện — ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết bộ 目 mở khoá: 眼 (nhãn), 睛 (tình), 瞧 (tiều), 覩 (đổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 睍 thuộc bộ 目 (mắt) và mang nghĩa nhìn với vẻ sợ hãi hoặc thận trọng quá mức. Chữ xuất hiện trong cụm 伈伈睍睍 (vẻ mặt rụt rè sợ sệt) và 睍睆 (sáng lấp lánh — dùng cho ánh sao). Tiểu triện của chữ này đã được bảo tồn. Âm Hán-Việt đọc là ''hiện''. Chưa có nguồn học thuật đầy đủ xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "睝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "見", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "𪾢", "Unihan_Traditional (Chữ Phồn thể)": "睍", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hiển, hiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng để mô tả cử động của mắt hoặc trạng thái mắt nhìn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碽', '{"9000": "8175.0", "Chữ Trung Quốc": "碽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 碽 | củng | tượng hình | tiếng va chạm đá; cầu vòm | 碽 thuộc bộ 石 (thạch, đá). Cấu trúc thành phần chưa được phân tích trong CHISE. Chữ mang hai nghĩa liên quan đến đá: tiếng kêu khi va chạm và cầu vòm/cầu cuốn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củng\": bộ 石 (đá) — tiếng đá va nhau ''củng'' cong, hoặc chiếc cầu 碽 vòm cong như chữ củng. | Gương Hán-Việt | củng — ít gặp trong từ Hán-Việt; gần âm với ''vòm'' trong kiến trúc | Mở khoá kiến thức | Biết bộ 石 mở khoá: 碑 (bi), 磁 (từ), 礁 (tiêu), 確 (xác).", "Tự nguyên_Xie": "Theo Wiktionary, 碽 có âm gōng và mang hai nghĩa: (1) tiếng kêu khi va chạm/đập vào nhau; (2) cầu vòm (arched bridge). Không có phân tích glyph-origin chi tiết. Âm Hán-Việt đọc là ''củng''. Chữ cực kỳ hiếm, không có từ ghép thông dụng. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "罽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 貢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石貢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碽", "Unihan_Traditional (Chữ Phồn thể)": "碽", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "củng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là một loại chữ hiếm dùng để chỉ tên gọi của một loại đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磸', '{"9000": "8176.0", "Chữ Trung Quốc": "磸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 磸 | đính | tượng hình | chữ hiếm thuộc bộ thạch | 磸 thuộc bộ 石 (thạch, đá). Không có dữ liệu anchor Wiktionary hoặc CHISE cho chữ này. Đây là chữ cực kỳ hiếm, chưa có nguồn học thuật xác nhận nghĩa cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": bộ 石 (thạch = đá) — viên đá 磸 ''đính'' chặt vào đất, cứng như đinh đóng cột. | Gương Hán-Việt | đính — ít gặp trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết bộ 石 mở khoá: 碑 (bi), 硬 (ngạnh), 確 (xác), 磁 (từ).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 磸. Chữ thuộc bộ 石 (đá) và có âm đọc là dìng trong tiếng Trung. Âm Hán-Việt phỏng đoán là ''đính'' theo quy tắc đối âm. Đây là chữ cực kỳ hiếm, chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 奠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石奠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磸", "Unihan_Traditional (Chữ Phồn thể)": "磸", "Pinyin_Xie": "dìng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng để định danh cho một loại đá cụ thể trong các tài liệu cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礉', '{"9000": "8177.0", "Chữ Trung Quốc": "礉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礉 | hác | tượng hình | khắc nghiệt; tàn khốc | 礉 thuộc bộ 石 (thạch, đá). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Chữ mang nghĩa ''nghiêm khắc, tàn khốc'', thường đi cùng 慘 trong từ 慘礉.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hác\": bộ 石 (đá cứng) — sự nghiêm khắc 礉 ''hác'' như đá: lạnh lùng, cứng nhắc, không nể tình. | Gương Hán-Việt | hác — ít gặp trong từ Hán-Việt; xuất hiện trong 慘礉 | Mở khoá kiến thức | Biết bộ 石 mở khoá: 確 (xác), 磁 (từ), 碑 (bi), 硬 (ngạnh).", "Tự nguyên_Xie": "Theo Wiktionary, 礉 mang nghĩa ''nghiêm khắc, tàn khốc'' (severe, harsh). Chữ xuất hiện trong từ ghép 慘礉 (thảm khốc). Có ba âm đọc: hé (chuẩn), qiāo, qiào. Bộ 石 gợi sự cứng rắn, không nhượng bộ — như đá. Âm Hán-Việt đọc là ''hác''. Không có phân tích glyph-origin chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình ảnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 敫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石敫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礉", "Unihan_Traditional (Chữ Phồn thể)": "礉", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ hình dáng hoặc diện mạo của sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礽', '{"9000": "8178.0", "Chữ Trung Quốc": "礽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 6 | nét | 礽 | nhưng | tượng hình | phúc lành; con cháu đời xa | 礽 thuộc bộ 示 (thị, thần linh/lễ). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Bộ 示 gợi ý liên quan đến tín ngưỡng, phúc lành, thần linh. Chữ chỉ phúc lành hoặc con cháu đời xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhưng\": bộ 示 (phúc/lễ) — phúc 礽 ''nhưng nhưng'' tiếp nối từ đời này sang đời khác, ban cho con cháu. | Gương Hán-Việt | nhưng — hiếm trong từ Hán-Việt; nổi tiếng qua tên Dận Nhưng (胤礽) | Mở khoá kiến thức | Biết bộ 示 mở khoá: 福 (phúc), 祖 (tổ), 禮 (lễ), 神 (thần).", "Tự nguyên_Xie": "Theo Wiktionary, 礽 mang nghĩa ''phúc lành, hạnh phúc'' (blessings, happiness), thuộc bộ 示 (thần linh, lễ nghi). Âm đọc réng (chuẩn phổ thông), Cantonese jing4, Min Nan lêng/jêng. Âm Hán-Việt đọc là ''nhưng''. Chữ này nổi tiếng vì Hoàng tử Dận Nhưng (胤礽) — thái tử nhà Thanh thời Khang Hy. Không có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc; cháu đời xa", "Hạng Tần Suất (Jun Da)": "8178.0", "Tần Suất % (Jun Da)": "99.9994935506", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 乃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻乃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "礽", "Unihan_Traditional (Chữ Phồn thể)": "礽", "Pinyin_Xie": "réng", "Âm Hán Việt_Xie": "nhưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ thế hệ con cháu đời sau hoặc sự nối tiếp phúc đức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祾', '{"9000": "8179.0", "Chữ Trung Quốc": "祾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 祾 | linh | tượng hình | phúc lành | 祾 thuộc bộ 示 (thị, thần linh/lễ). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Bộ 示 gợi liên quan đến phúc lành, tín ngưỡng. Chữ cực kỳ hiếm, nghĩa chưa được xác định rõ (rfdef trong Wiktionary).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 示 (thần thánh/lễ) + âm ''linh'' — phúc 祾 ''linh thiêng'' đến từ thần linh, linh nghiệm. | Gương Hán-Việt | linh — ít gặp độc lập; bộ 示 liên quan đến lễ nghi tôn giáo | Mở khoá kiến thức | Biết bộ 示 mở khoá: 福 (phúc), 祈 (kỳ), 禮 (lễ), 神 (thần), 禱 (đảo).", "Tự nguyên_Xie": "Theo Wiktionary, 祾 bị đánh dấu ''rfdef'' — nghĩa chưa được xác định đầy đủ. Âm đọc líng (phổ thông), Cantonese ling4, Min Nan lêng. Thuộc bộ 示 (thần linh). Âm Hán-Việt đọc là ''linh''. Trong một số nguồn, 祾 mang nghĩa phúc lành. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祾", "Unihan_Traditional (Chữ Phồn thể)": "祾", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong văn bản cổ để chỉ phúc lộc hoặc điềm lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禌', '{"9000": "8180.0", "Chữ Trung Quốc": "禌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禌 | tư | tượng hình | chữ hiếm thuộc bộ thị | 禌 thuộc bộ 示 (thị, thần linh/lễ). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa chưa được xác định (rfdef). Bộ 示 gợi liên quan đến tín ngưỡng, tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 示 (thần linh) + âm ''tư'' — nghĩ đến việc lễ 禌 ''tư lự'' (suy nghĩ), thờ cúng trong im lặng. | Gương Hán-Việt | tư — ít gặp độc lập; bộ 示 liên quan đến lễ nghi | Mở khoá kiến thức | Biết bộ 示 mở khoá: 福 (phúc), 祈 (kỳ), 禮 (lễ), 神 (thần).", "Tự nguyên_Xie": "Theo Wiktionary, 禌 bị đánh dấu ''rfdef'' — nghĩa chưa được xác định. Âm đọc zī (phổ thông), Cantonese zi1. Âm Hán-Việt đọc là ''tư''. Đây là chữ cực kỳ hiếm, thuộc bộ 示 (tín ngưỡng, lễ nghi). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 兹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻兹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禌", "Unihan_Traditional (Chữ Phồn thể)": "禌", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ phúc lành hoặc động từ cầu phúc trong tế lễ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筥', '{"9000": "8181.0", "Chữ Trung Quốc": "筥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 筥 | rá | tượng hình | cái rá/sọt đựng gạo hình tròn bằng tre | 筥 thuộc bộ 竹 (trúc, tre). Không có dữ liệu CHISE chi tiết, nhưng kim văn, tiểu triện và Lục thư thông của 筥 đều được bảo tồn — cho thấy đây là chữ có lịch sử lâu đời. Chữ chỉ cái rá/sọt tròn đan bằng tre dùng đựng gạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"rá\": bộ 竹 (tre) — cái 筥 ''rá'' đan tre hình tròn để vo gạo, từ Hán-Việt trùng ngay với từ thuần Việt bạn dùng hàng ngày! | Gương Hán-Việt | rá — trùng âm với ''rá'' thuần Việt (đồ vo gạo bằng tre); rất dễ nhớ | Mở khoá kiến thức | Biết 筥 và bộ 竹 mở khoá: 籃 (lam), 笥 (tứ), 箱 (tương), 篩 (sải).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Không tìm thấy anchor Wiktionary chi tiết cho 筥. Kim văn và tiểu triện của 筥 đã được bảo tồn từ hanziyuan, cho thấy chữ có nguồn gốc cổ đại. Nghĩa là cái rá hình tròn đan bằng tre để đựng gạo (round-shaped bamboo basket). Âm Hán-Việt đọc là ''rá'' — trùng với từ thuần Việt ''rá'' (đồ đan bằng tre để vo gạo). Đây là trường hợp hiếm chữ Hán-Việt trùng âm với từ Việt thuần. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sọt", "Hạng Tần Suất (Jun Da)": "8181.0", "Tần Suất % (Jun Da)": "99.9994951009", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筥", "Unihan_Traditional (Chữ Phồn thể)": "筥", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "cử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại giỏ hoặc sọt tre tròn đựng thóc lúa thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簴', '{"9000": "8182.0", "Chữ Trung Quốc": "簴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簴 | cự | tượng hình | giá treo nhạc cụ bằng tre/gỗ | 簴 thuộc bộ 竹 (trúc, tre). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa là giá đỡ/treo nhạc cụ (chuông, khánh) trong nhã nhạc cổ đại. Đây là chữ chuyên dùng trong bối cảnh âm nhạc cung đình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": bộ 竹 (tre) + kích thước ''cự đại'' — cái giá 簴 tre khổng lồ trong cung đình để treo chuông, khánh nhã nhạc. | Gương Hán-Việt | cự — ít gặp; liên quan đến nhạc cụ cung đình cổ đại | Mở khoá kiến thức | Biết bộ 竹 mở khoá: 簫 (tiêu), 笛 (địch), 箏 (tranh), 筑 (trúc).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 簴. Nghĩa của chữ là giá treo nhạc cụ (như chuông, khánh) trong nhã nhạc cổ đại Trung Quốc. Bộ 竹 (tre) gợi ý vật liệu hoặc phân loại theo đồ dùng âm nhạc. Âm Hán-Việt đọc là ''cự''. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 虡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮虡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簴", "Unihan_Traditional (Chữ Phồn thể)": "簴", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ hàng cột gỗ làm giá treo nhạc cụ như chuông, khánh thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紣', '{"9000": "8183.0", "Chữ Trung Quốc": "紣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 紣 | tụy | tượng hình | chữ hiếm thuộc bộ mịch/tơ lụa | 紣 thuộc bộ 糸 (mịch, tơ lụa, sợi chỉ). Không có dữ liệu CHISE hoặc Wiktionary anchor. Đây là chữ cực kỳ hiếm, không có nghĩa ghi nhận trong nguồn tra cứu thông dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\": bộ 糸 (tơ, sợi) — sợi tơ 紣 ''tụy hội'' (tụ lại) thành vải, mỏng manh nhưng kết thành sức mạnh. | Gương Hán-Việt | tụy — ít gặp trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết bộ 糸 mở khoá: 絲 (ti), 綢 (trù), 縫 (phùng), 繡 (tú).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 紣. Chữ thuộc bộ 糸 (tơ lụa/sợi chỉ). Âm đọc cuì, âm Hán-Việt phỏng đoán là ''tụy''. Đây là chữ cực kỳ hiếm, chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Không có từ ghép thông dụng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "紣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 卆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹卆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紣", "Unihan_Traditional (Chữ Phồn thể)": "紣", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ sợi tơ rối hoặc động từ liên quan đến việc dệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絍', '{"9000": "8184.0", "Chữ Trung Quốc": "絍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絍 | nhẫm | tượng hình | mắc sợi dọc; dệt vải | 絍 thuộc bộ 糸 (mịch, tơ lụa). Không có dữ liệu CHISE chi tiết. Nghĩa là mắc sợi dọc vào khung cửi (lay the warp) hoặc dệt vải. Chữ chuyên dùng trong bối cảnh dệt vải truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫm\": bộ 糸 (tơ) + âm ''nhẫm'' gợi ''nhẫn nại'' — người thợ dệt nhẫn nại mắc từng sợi dọc 絍 vào khung cửi. | Gương Hán-Việt | nhẫm — ít gặp; liên quan đến kỹ thuật dệt truyền thống | Mở khoá kiến thức | Biết bộ 糸 mở khoá: 織 (chức), 絲 (ti), 緯 (vĩ), 縫 (phùng).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary chi tiết cho 絍. Nghĩa là mắc sợi dọc lên khung cửi (to lay the warp; to weave). Bộ 糸 (tơ lụa) gợi ý rõ ngữ cảnh dệt vải. Âm đọc rèn, âm Hán-Việt đọc là ''nhẫm''. Chữ chuyên dụng trong văn bản về nghề dệt cổ đại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絍", "Hạng Tần Suất (Jun Da)": "8184.0", "Tần Suất % (Jun Da)": "99.9994966513", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 任", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹任", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絍", "Unihan_Traditional (Chữ Phồn thể)": "絍", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc dệt vải hoặc danh từ chỉ sợi tơ dùng để dệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縆', '{"9000": "8185.0", "Chữ Trung Quốc": "縆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 縆 | canh | tượng hình | dây thừng; sợi dây | 縆 thuộc bộ 糸 (mịch, tơ lụa/dây). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE (Wiktionary chỉ ghi {{Han etym}}). Nghĩa là dây thừng (a rope). Bộ 糸 gợi ý trực tiếp về dây, sợi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": bộ 糸 (dây/tơ) + âm ''canh'' — cuộn dây thừng 縆 ''canh giữ'' cổng, buộc chặt như gánh canh thâu đêm. | Gương Hán-Việt | canh — ít gặp; bộ 糸 gợi ngữ cảnh dây thừng, buộc buộc | Mở khoá kiến thức | Biết bộ 糸 mở khoá: 綁 (bảng), 縛 (phọc), 繩 (thằng), 絆 (bạn).", "Tự nguyên_Xie": "Theo Wiktionary, 縆 chỉ có {{Han etym}} mà không có phân tích glyph-origin chi tiết. Nghĩa là dây thừng. Bộ 糸 (tơ/dây) phù hợp với nghĩa này. Âm đọc gēng, âm Hán-Việt đọc là ''canh''. Chữ cực kỳ hiếm trong văn bản hiện đại. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 恒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹恒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "恒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縆", "Unihan_Traditional (Chữ Phồn thể)": "縆", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "căng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dây thừng to hoặc động từ với nghĩa kéo căng sợi dây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繀', '{"9000": "8186.0", "Chữ Trung Quốc": "繀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繀 | tuy | tượng hình | quay tơ; suốt chỉ | 繀 thuộc bộ 糸 (mịch, tơ lụa). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa là quay tơ hoặc suốt chỉ — công cụ/hành động trong nghề dệt. Wiktionary ghi rfdef nhưng nghĩa thực là quay tơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": bộ 糸 (tơ) + âm ''tuy'' — tuy nhỏ bé nhưng suốt chỉ 繀 cứ quay đều đặn, xe từng sợi tơ mỏng thành cuộn. | Gương Hán-Việt | tuy — ít gặp; liên quan đến kỹ thuật dệt cổ truyền | Mở khoá kiến thức | Biết bộ 糸 mở khoá: 紡 (phảng), 絲 (ti), 織 (chức), 縫 (phùng).", "Tự nguyên_Xie": "Theo Wiktionary, 繀 bị đánh dấu rfdef nhưng nghĩa được ghi nhận là quay tơ (spinning silk). Âm đọc suì, âm Hán-Việt đọc là ''tuy''. Bộ 糸 (tơ lụa) phù hợp với nghĩa trong ngành dệt. Chữ cực kỳ hiếm, chưa thấy từ ghép thông dụng. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quay tơ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繀", "Unihan_Traditional (Chữ Phồn thể)": "繀", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ hành động quay tơ hoặc danh từ chỉ ống cuộn sợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羕', '{"9000": "8187.0", "Chữ Trung Quốc": "羕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 11 | nét | 羊 | dương | biểu âm | con dê/cừu | 永 | vĩnh | biểu nghĩa | lâu dài, mãi mãi | 羕 = 羊 (Dương, biểu âm) + 永 (Vĩnh, biểu nghĩa: lâu dài); chữ hình thanh. Phần 永 cho biết nghĩa liên quan đến sự dài lâu/dòng sông dài, phần 羊 cho âm gần với yàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dạng\": 永 (vĩnh cửu) + 羊 (dê kêu yàng yàng) — con sông 羕 dài ''dạng'' như vĩnh hằng, chảy mãi không ngừng. | Gương Hán-Việt | dạng — ít gặp trong từ Hán-Việt; gợi nhớ ''vĩnh dạng'' (dài lâu) | Mở khoá kiến thức | Biết 羕 mở khoá: 永 (vĩnh), 羊 (dương), 洋 (dương biển), 漾 (dạng — gợn sóng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 羕 được phân tích là chữ hình thanh: 羊 (biểu âm) + 永 (biểu nghĩa: lâu dài). Nghĩa gốc là dòng sông dài (original meaning: long river), sau mở rộng thành ''lâu dài, mãi mãi'' (long term). Tiểu triện của 羕 đã được bảo tồn. Âm đọc yàng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1057.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Dương (360) Vĩnh (314)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Dương (số 360 - con dê/chỉ âm) ở trên chữ Vĩnh (số 314 - dòng nước dài). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Dương chỉ âm, chữ Vĩnh chỉ ý. Dạng là dòng sông dài, nước chảy liên tục không ngừng.", "Nghĩa Tiếng Việt_Xie": "dài (dùng với sông)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 永", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊永", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "永", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羕", "Unihan_Traditional (Chữ Phồn thể)": "羕", "Pinyin_Xie": "yàng", "Âm Hán Việt_Xie": "dạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả dòng sông dài hoặc động từ chỉ làn nước dập dềnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羵', '{"9000": "8188.0", "Chữ Trung Quốc": "羵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 18 | nét | 羵 | phần | tượng hình | dê/quái thú trong truyền thuyết | 羵 thuộc bộ 羊 (dương, dê/cừu). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Chữ chỉ một loại quái thú giống dê trong truyền thuyết cổ Trung Hoa (羵羊 — phần dương).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": bộ 羊 (dê) + âm ''phần'' — con dê quái 羵 ''phần phần'' rực rỡ quái dị trong thần thoại Trung Hoa, không phải dê thường. | Gương Hán-Việt | phần — ít gặp; xuất hiện trong 羵羊 (phần dương — quái thú huyền thoại) | Mở khoá kiến thức | Biết bộ 羊 mở khoá: 美 (mỹ), 羔 (cao), 群 (quần), 羌 (khương).", "Tự nguyên_Xie": "Theo Wiktionary, 羵 mô tả một con vật huyền thoại giống dê (a goat-like monster from legends), là chữ lỗi thời (obs-std). Âm đọc fěn/fén, âm Hán-Việt đọc là ''phần''. Bộ 羊 (dê) xác định phạm trù sinh vật. 羵羊 (phần dương) là tên đầy đủ của quái thú này trong thần thoại. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(như: phần dương 羵羊)", "Hạng Tần Suất (Jun Da)": "8188.0", "Tần Suất % (Jun Da)": "99.9994992352", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 賁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶賁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羵", "Unihan_Traditional (Chữ Phồn thể)": "羵", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tổ hợp từ chỉ loài quái thú giống cừu thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耇', '{"9000": "8189.0", "Chữ Trung Quốc": "耇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 9 | nét | 老 | lão | biểu nghĩa | già | 句 | câu | biểu âm | câu/đoạn | 耇 = 老 (Lão, biểu nghĩa: già — viết tắt) + 句 (Câu, biểu âm); chữ hình thanh. Phần 老 (rút gọn) cho biết nghĩa liên quan đến người già, phần 句 cho âm gần với gǒu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩu\": 老 (lão = già) + 句 (câu) — ông già tóc bạc kể từng ''câu chuyện'' về nếp nhăn 耇 năm tháng. | Gương Hán-Việt | cẩu — ít gặp; gợi nhớ ''lão cẩu'' (già cẩu) | Mở khoá kiến thức | Biết 耇 mở khoá ngữ cảnh: 老 (lão), 耆 (kỳ — 60 tuổi), 耄 (mạo — 80 tuổi), 耋 (điệt — 70/80 tuổi).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 耇 được phân tích là chữ hình thanh: 老 (viết tắt, biểu nghĩa: già) + 句 (biểu âm). Nghĩa là khuôn mặt nhăn nheo của người cao tuổi (wrinkled face of the elderly). Kim văn và tiểu triện của 耇 đã được bảo tồn. Xuất hiện trong Kinh Thi: ''Lạc chỉ quân tử, hà bất hoàng 耇'' (người quân tử đáng mừng, sẽ không trường thọ sao?). Âm Hán-Việt đọc là ''cẩu''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "già cả", "Hạng Tần Suất (Jun Da)": "8189.0", "Tần Suất % (Jun Da)": "99.999499752", "GavinGrover_Once (Chiết tự trực tiếp)": "耂 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱耂句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耂", "Unihan_Simplified (Chữ Giản thể)": "耇", "Unihan_Traditional (Chữ Phồn thể)": "耇", "Pinyin_Xie": "gǒu", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả tuổi già hoặc danh từ chỉ người cao tuổi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聫', '{"9000": "8190.0", "Chữ Trung Quốc": "聫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 15 | nét | 聫 | liên | tượng hình | liên kết; câu đối | 聫 thuộc bộ 耳 (nhĩ, tai). Không có dữ liệu CHISE chi tiết. Chữ này là dạng cổ/biến thể của 聯, mang nghĩa liên kết, liên minh. Bộ 耳 (tai) gợi lắng nghe, kết nối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liên\": bộ 耳 (tai, lắng nghe) — ''liên'' 聫 kết hai người cần hai đôi tai lắng nghe nhau, như hai vế câu đối phải ăn nhau từng chữ. | Gương Hán-Việt | liên trong ''liên minh'', ''liên kết'', ''câu liên'' | Mở khoá kiến thức | Biết 聫/聯 mở khoá: 聯繫 (liên hệ), 聯合 (liên hợp), 聯盟 (liên minh), 聯絡 (liên lạc).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary chi tiết cho 聫. Chữ là biến thể cổ của 聯 (liên — liên kết, câu đối). Bộ 耳 (tai) phản ánh sự kết nối qua lắng nghe. Nghĩa bao gồm liên minh, liên kết, và câu đối (vế đối). Âm Hán-Việt đọc là ''liên''. Chữ này gần với 联 (giản thể)/聯 (phồn thể). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liên minh, liên kết; câu đối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "聫", "Unihan_Traditional (Chữ Phồn thể)": "聫", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ liên kết hoặc danh từ chỉ câu đối trong văn cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脗', '{"9000": "8191.0", "Chữ Trung Quốc": "脗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脗 | vẫn | tượng hình | môi; hôn; khớp khít | 脗 thuộc bộ 肉/月 (nhục, thịt/thân thể). Không có dữ liệu CHISE chi tiết. Nghĩa là môi, mép; hôn; hoặc khớp khít/ăn khớp (coinciding, agreeing). Đây là biến thể của 吻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": bộ 肉 (thân thể) + âm ''vẫn'' — nụ hôn 脗 ''vẫn'' là biểu hiện khớp khít của tình cảm, môi chạm môi ăn khớp hoàn hảo. | Gương Hán-Việt | vẫn — biến thể của 吻 (vẫn — môi, hôn) | Mở khoá kiến thức | Biết 脗/吻 mở khoá: 吻合 (vẫn hợp — khớp khít), 接吻 (tiếp vẫn — hôn).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary chi tiết cho 脗. Chữ thuộc bộ 肉 (thân thể) và mang nghĩa môi/hôn, đồng thời có nghĩa khớp khít, trùng hợp (coinciding, agreeing). Đây là biến thể của 吻 (vẫn — môi, hôn). Âm đọc wěn, âm Hán-Việt đọc là ''vẫn''. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "môi, mép; hôn, thơm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 𠯳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月𠯳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠯳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脗", "Unihan_Traditional (Chữ Phồn thể)": "脗", "Pinyin_Xie": "wěn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ sự phù hợp, khít khao hoặc danh từ chỉ môi mép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臯', '{"9000": "8192.0", "Chữ Trung Quốc": "臯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 自 | Số nét | 12 | nét | 臯 | cao | tượng hình | bờ bãi; vùng đất trũng ven sông; dạng cổ của 皋 | 臯 là dạng cổ/biến thể của 皋 (cao), thuộc bộ 自 (tự). Tiểu triện và Lục thư thông đã được bảo tồn. Nghĩa bao gồm bờ bãi, vùng đất ven sông; cũng dùng để ca ngợi/cầu phúc. Wiktionary ghi đây là dạng tham chiếu của 皋.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": bộ 自 kết hợp với âm ''cao'' — bờ 臯 ''cao'' ven sông, nơi người xưa đứng cao nhìn xuống đồng bằng ngập nước. | Gương Hán-Việt | cao trong ''cao nguyên'', ''tao'' (thơ văn); gắn với tên Cao Dao (皋陶) | Mở khoá kiến thức | Biết 臯/皋 mở khoá: 皋陶 (Cao Dao), 澤皋 (trạch cao — đầm lầy bờ bãi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 臯 là dạng biến thể (variant) của 皋. Tiểu triện và Lục thư thông của 臯 được bảo tồn qua hanziyuan. Nghĩa gốc là bờ bãi, vùng đất trũng hoặc đầm lầy ven sông; cũng dùng nghĩa ca ngợi, cầu phúc. Âm đọc gāo, âm Hán-Việt đọc là ''cao''. Chữ gắn với địa danh 皋陶 (Cao Dao — quan tư pháp thời Nghiêu Thuấn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khấn, vái; bờ, bãi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "自 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱自", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "臯", "Unihan_Traditional (Chữ Phồn thể)": "臯", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bờ sông hoặc động từ kêu gọi trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艁', '{"9000": "8193.0", "Chữ Trung Quốc": "艁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艁 | tạo | tượng hình | chữ hiếm thuộc bộ chu (thuyền) | 艁 thuộc bộ 舟 (chu, thuyền). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa không xác định được từ nguồn học thuật đáng tin cậy. Đây là chữ cực kỳ hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạo\": bộ 舟 (thuyền) + âm ''tạo'' — ''tạo'' ra chiếc thuyền 艁 từ gỗ, mộc mạc như cái nghề thủ công ven sông. | Gương Hán-Việt | tạo — ít gặp; bộ 舟 gợi ngữ cảnh thuyền bè, đi lại đường thủy | Mở khoá kiến thức | Biết bộ 舟 mở khoá: 船 (thuyền), 航 (hàng), 艇 (đĩnh), 艘 (sưu).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 艁. Chữ thuộc bộ 舟 (thuyền). Âm đọc zào, âm Hán-Việt đọc là ''tạo''. Không có từ ghép hay nghĩa được ghi nhận đáng tin cậy. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cocktail", "Hạng Tần Suất (Jun Da)": "8193.0", "Tần Suất % (Jun Da)": "99.9995018191", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艁", "Unihan_Traditional (Chữ Phồn thể)": "艁", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "tạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ thuyền bè hoặc động từ chế tạo trong văn tự cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艂', '{"9000": "8194.0", "Chữ Trung Quốc": "艂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 13 | nét | 艂 | phùng | tượng hình | chữ hiếm thuộc bộ chu (thuyền) | 艂 thuộc bộ 舟 (chu, thuyền). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa không xác định được. Đây là chữ cực kỳ hiếm trong văn bản hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phùng\": bộ 舟 (thuyền) + âm ''phùng'' — hai con thuyền 艂 ''phùng'' nhau trên sông, tình cờ gặp gỡ giữa mênh mông nước. | Gương Hán-Việt | phùng — ít gặp; bộ 舟 gợi thuyền bè đường thủy | Mở khoá kiến thức | Biết bộ 舟 mở khoá: 船 (thuyền), 航 (hàng), 艇 (đĩnh), 艘 (sưu).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 艂. Chữ thuộc bộ 舟 (thuyền). Âm đọc féng, âm Hán-Việt đọc là ''phùng''. Không có từ ghép hay nghĩa được ghi nhận đáng tin cậy. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 夆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟夆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艂", "Unihan_Traditional (Chữ Phồn thể)": "艂", "Pinyin_Xie": "féng", "Âm Hán Việt_Xie": "phùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại thuyền lớn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茞', '{"9000": "8195.0", "Chữ Trung Quốc": "茞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茞 | sấn | tượng hình | cỏ thơm; bạch chỉ (một loài thảo mộc) | 茞 thuộc bộ 艸/艹 (thảo, cỏ). Không có dữ liệu CHISE chi tiết. Tiểu triện của 茞 đã được bảo tồn. Nghĩa là cỏ thơm hoặc bạch chỉ (angelica) — một loài thảo mộc có mùi thơm dùng trong y học cổ truyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấn\": bộ 艹 (cỏ) + âm ''sấn'' — loài cỏ thơm 茞 ''sấn sổ'' mọc dại, tỏa hương thơm ngát như bạch chỉ trong vườn thuốc. | Gương Hán-Việt | sấn — ít gặp; bộ 艹 gợi thảo mộc, dược liệu | Mở khoá kiến thức | Biết bộ 艹 mở khoá: 草 (thảo), 芳 (phương), 芝 (chi), 蘭 (lan).", "Tự nguyên_Xie": "Tiểu triện | Không tìm thấy anchor Wiktionary chi tiết cho 茞. Tiểu triện của 茞 đã được bảo tồn qua wikimedia. Nghĩa là cỏ thơm hoặc bạch chỉ (fragrant plant; angelica) — loài cây thảo mộc. Bộ 艹 (cỏ) xác định phạm trù thực vật. Âm đọc chén, âm Hán-Việt đọc là ''sấn''. Chữ xuất hiện trong văn học cổ liên quan đến thảo mộc thơm. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cỏ)", "Hạng Tần Suất (Jun Da)": "8195.0", "Tần Suất % (Jun Da)": "99.9995028527", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 臣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹臣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茞", "Unihan_Traditional (Chữ Phồn thể)": "茞", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "thần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cỏ thơm dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葨', '{"9000": "8196.0", "Chữ Trung Quốc": "葨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葨 | vi | tượng hình | loài cỏ mọc trên núi | 葨 thuộc bộ 艸/艹 (thảo, cỏ). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa là một loài cỏ mọc trên vùng núi (a kind of grass that grows in the mountains). Chữ lỗi thời (obs-std).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": bộ 艹 (cỏ) + âm ''vi'' — loài cỏ 葨 ''vi vi'' (nhỏ bé, khiêm tốn) mọc trên núi cao, lặng lẽ tồn tại giữa đá lạnh. | Gương Hán-Việt | vi — ít gặp; bộ 艹 gợi thực vật hoang dã | Mở khoá kiến thức | Biết bộ 艹 mở khoá: 草 (thảo), 芽 (nha), 苔 (đài), 萌 (manh).", "Tự nguyên_Xie": "Theo Wiktionary, 葨 là chữ lỗi thời (obs-std), chỉ một loài cỏ mọc trên núi. Âm đọc wēi, âm Hán-Việt đọc là ''vi''. Bộ 艹 (cỏ) phù hợp với nghĩa thực vật. Chữ xuất hiện trong từ điển cổ đại nhưng không còn dùng trong tiếng Trung hiện đại. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葨", "Unihan_Traditional (Chữ Phồn thể)": "葨", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại cỏ dại trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒄', '{"9000": "8197.0", "Chữ Trung Quốc": "蒄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蒄 | quan | tượng hình | chữ hiếm thuộc bộ thảo | 蒄 thuộc bộ 艸/艹 (thảo, cỏ). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa không xác định được. Đây là chữ cực kỳ hiếm không có từ ghép thông dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quan\": bộ 艹 (thảo mộc) + âm ''quan'' — loài cây cỏ 蒄 ''quan trọng'' ẩn trong rừng, ít ai biết đến như một vị ''quan'' ẩn dật. | Gương Hán-Việt | quan — ít gặp; bộ 艹 gợi thực vật, thảo mộc | Mở khoá kiến thức | Biết bộ 艹 mở khoá: 草 (thảo), 菊 (cúc), 蕉 (tiêu), 蓮 (liên).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 蒄. Chữ thuộc bộ 艹 (cỏ/thực vật). Âm đọc guān, âm Hán-Việt đọc là ''quan''. Không có từ ghép hay nghĩa được ghi nhận đáng tin cậy. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "脄", "Hạng Tần Suất (Jun Da)": "8197.0", "Tần Suất % (Jun Da)": "99.9995038863", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 冠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹冠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒄", "Unihan_Traditional (Chữ Phồn thể)": "蒄", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cỏ hoặc biến thể của chữ quan nghĩa là cái mũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒭', '{"9000": "8198.0", "Chữ Trung Quốc": "蒭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艹 | thảo | biểu nghĩa | cỏ | 芻 | sô | biểu âm | cỏ khô, thức ăn gia súc | 蒭 = 艹 (Thảo, biểu nghĩa: cỏ) + 芻 (Sô, biểu âm); chữ hình thanh. Wiktionary ghi ls=psc và ls2=ic — vừa là hình thanh vừa có yếu tố hội ý (cả hai phần đều liên quan đến cỏ). 蒭 là dạng biến thể của 芻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sô\": 艹 (cỏ) + 芻 (sô — cỏ khô) — cỏ chồng lên cỏ, 蒭 ''sô'' thức ăn cho trâu ngựa, đơn giản và mộc mạc như người nông dân. | Gương Hán-Việt | sô trong ''sô bổ'' (cỏ khô), ''cầu sô'' (cỏ mềm) | Mở khoá kiến thức | Biết 蒭/芻 mở khoá: 芻議 (sô nghị — ý kiến khiêm tốn), 反芻 (phản sô — nhai lại), 馬芻 (thức ăn ngựa).", "Tự nguyên_Xie": "Theo Wiktionary, 蒭 được phân tích là chữ hình thanh: 艹 (cỏ, biểu nghĩa) + 芻 (biểu âm). Đồng thời có yếu tố hội ý vì 芻 cũng liên quan đến cỏ khô. 蒭 là biến thể/dị thể của 芻 (cắt cỏ; cỏ khô; thức ăn gia súc). Nghĩa là nuôi gia súc bằng cỏ; cắt cỏ; cỏ khô làm thức ăn. Âm đọc chú, âm Hán-Việt đọc là ''sô''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nuôi (trâu, ngựa) bằng cỏ", "Hạng Tần Suất (Jun Da)": "8198.0", "Tần Suất % (Jun Da)": "99.9995044031", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 芻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹芻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "芻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒭", "Unihan_Traditional (Chữ Phồn thể)": "蒭", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ cỏ khô hoặc động từ cắt cỏ cho súc vật ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薂', '{"9000": "8199.0", "Chữ Trung Quốc": "薂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薂 | tập | tượng hình | hạt sen (nghĩa cổ, lỗi thời) | 薂 thuộc bộ 艸/艹 (thảo, cỏ/thực vật). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa cổ là hạt sen (lotus seed), là chữ lỗi thời (obsolete).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bộ 艹 (thực vật) + âm ''tập'' — hạt sen 薂 ''tập hợp'' trong đài sen, từng hạt nhỏ xíu tập lại như bài học vỡ lòng về mùa hạ. | Gương Hán-Việt | tập — ít gặp; 薂 là chữ lỗi thời, hạt sen ngày nay dùng 蓮子 (liên tử) | Mở khoá kiến thức | Biết bộ 艹 + hạt sen mở khoá: 蓮 (liên), 荷 (hà), 芙 (phù), 菡 (hàm).", "Tự nguyên_Xie": "Theo Wiktionary, 薂 là chữ lỗi thời (obsolete), nghĩa là hạt sen. Từ đồng nghĩa: 的 (trong ngữ cảnh hạt sen). Bộ 艹 (thực vật) phù hợp với ngữ cảnh thực vật thủy sinh. Âm đọc xí, âm Hán-Việt đọc là ''tập''. Không còn dùng trong tiếng Trung hiện đại. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Xue", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 敫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹敫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薂", "Unihan_Traditional (Chữ Phồn thể)": "薂", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ hoa sen hoặc một loại cỏ nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藯', '{"9000": "8200.0", "Chữ Trung Quốc": "藯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藯 | vị | tượng hình | chữ hiếm thuộc bộ thảo | 藯 thuộc bộ 艸/艹 (thảo, cỏ/thực vật). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa không xác định được từ nguồn học thuật. Đây là chữ cực kỳ hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": bộ 艹 (thảo mộc) + âm ''vị'' — loài cây có ''vị'' thuốc đặc biệt藯, ẩn trong rừng sâu chưa ai định danh được. | Gương Hán-Việt | vị — ít gặp; bộ 艹 gợi thảo mộc, dược liệu | Mở khoá kiến thức | Biết bộ 艹 mở khoá: 草 (thảo), 藥 (dược), 苦 (khổ), 甘 (cam).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 藯. Chữ thuộc bộ 艹 (cỏ/thực vật). Âm đọc wèi, âm Hán-Việt đọc là ''vị''. Không có từ ghép hay nghĩa được ghi nhận đáng tin cậy. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "误", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 慰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹慰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "慰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藯", "Unihan_Traditional (Chữ Phồn thể)": "藯", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ cây ích mẫu trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螑', '{"9000": "8201.0", "Chữ Trung Quốc": "螑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螑 | tú | tượng hình | chữ hiếm thuộc bộ trùng | 螑 thuộc bộ 虫 (trùng, côn trùng/sinh vật). Không có dữ liệu CHISE hoặc Wiktionary anchor. Nghĩa không xác định được. Đây là chữ cực kỳ hiếm không có từ ghép thông dụng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tú\": bộ 虫 (côn trùng) + âm ''tú'' gợi ''tú tài'' — con sâu bọ 螑 ''tú tài'' ẩn mình, không ai biết tên nhưng vẫn tồn tại trong tự nhiên. | Gương Hán-Việt | tú — ít gặp; bộ 虫 gợi côn trùng, sinh vật nhỏ | Mở khoá kiến thức | Biết bộ 虫 mở khoá: 蟲 (trùng), 蝶 (điệp), 蛾 (nga), 蜻 (thanh).", "Tự nguyên_Xie": "Không tìm thấy anchor Wiktionary cho 螑. Chữ thuộc bộ 虫 (côn trùng/sinh vật). Âm đọc xiù, âm Hán-Việt đọc là ''tú''. Không có từ ghép hay nghĩa được ghi nhận đáng tin cậy. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 臭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫臭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螑", "Unihan_Traditional (Chữ Phồn thể)": "螑", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loài côn trùng trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟼', '{"9000": "8202.0", "Chữ Trung Quốc": "蟼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟼 | cảnh | tượng hình | loài ếch (nghĩa cổ, lỗi thời) | 蟼 thuộc bộ 虫 (trùng, côn trùng/sinh vật). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa cổ là một loài ếch (a kind of frog), là chữ lỗi thời (obs-std).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảnh\": bộ 虫 (sinh vật) + âm ''cảnh'' — con ếch nhảy 蟼 ''cảnh cảnh'' tỉnh trong đêm, tiếng kêu vang như tiếng ''cảnh báo'' của rừng xanh. | Gương Hán-Việt | cảnh — ít gặp; 蟼 là chữ lỗi thời chỉ loài ếch | Mở khoá kiến thức | Biết bộ 虫 mở khoá: 蛙 (oa — ếch), 蟾 (thiềm — cóc), 蜥 (tích — thằn lằn).", "Tự nguyên_Xie": "Theo Wiktionary, 蟼 là chữ lỗi thời (obs-std), nghĩa là một loài ếch (a kind of frog). Âm đọc jǐng, âm Hán-Việt đọc là ''cảnh''. Bộ 虫 (sinh vật) phù hợp. Không có từ ghép thông dụng. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敬 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敬虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟼", "Unihan_Traditional (Chữ Phồn thể)": "蟼", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ con dế trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衟', '{"9000": "8203.0", "Chữ Trung Quốc": "衟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 16 | nét | 行 | hàng | biểu nghĩa | đường đi, hàng ngũ | 衟 = 行 (Hàng, biểu nghĩa: đường đi) + 𩠐 (biểu âm); chữ hình thanh. Đây là dạng cổ của 道 (đạo — con đường). Bộ 行 (đường đi) cho biết nghĩa, phần âm đã biến dạng theo thời gian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": bộ 行 (đường đi) — ''衟'' là dạng cổ của 道 (đạo), con đường — dẫu là đường đất hay đường chân lý, đều bắt đầu từ bộ 行. | Gương Hán-Việt | đạo trong ''đạo đức'', ''đạo lý'', ''đạo Phật''; rất phổ biến trong từ Hán-Việt | Mở khoá kiến thức | Biết 衟/道 mở khoá: 道德 (đạo đức), 道路 (đạo lộ), 道理 (đạo lý), 道具 (đạo cụ).", "Tự nguyên_Xie": "Theo Wiktionary, 衟 được phân tích là chữ hình thanh: 行 (biểu nghĩa: đường đi) + 𩠐 (biểu âm). Wiktionary xác nhận 衟 là dạng cổ của 道 (đạo). Âm đọc dào, âm Hán-Việt đọc là ''đạo''. Nghĩa đầy đủ của 道 bao gồm: đường đi, phương pháp, đạo lý, học thuyết Đạo gia. Đây là chữ cổ ngữ văn, không dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衟", "Hạng Tần Suất (Jun Da)": "8203.0", "Tần Suất % (Jun Da)": "99.9995075038", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 𩠐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行𩠐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𩠐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衟", "Unihan_Traditional (Chữ Phồn thể)": "衟", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này là dị thể của chữ Đạo, thường làm danh từ chỉ đường lối hoặc động từ chỉ sự dẫn dắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褑', '{"9000": "8204.0", "Chữ Trung Quốc": "褑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褑 | uyển | tượng hình | đai ngọc đeo trên cổ áo | 褑 thuộc bộ 衣 (y, quần áo). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa là miếng ngọc đeo trên cổ áo (jade belt worn on the lapel). Chữ thuộc lĩnh vực trang phục cung đình cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": bộ 衣 (áo) + âm ''uyển'' gợi ''uyển chuyển'' — miếng ngọc 褑 ''uyển chuyển'' lung linh trên vạt áo quan lại, nhẹ nhàng thanh thoát. | Gương Hán-Việt | uyển — ít gặp; liên quan đến trang phục quý tộc cung đình | Mở khoá kiến thức | Biết bộ 衣 mở khoá: 袍 (bào), 衫 (sam), 裙 (quần), 袖 (tụ).", "Tự nguyên_Xie": "Theo Wiktionary, 褑 có nghĩa là miếng đai ngọc đeo trên vạt áo/cổ áo (jade belt worn on the lapel of a jacket). Âm đọc yuàn (chuẩn), còn có zhě và zhǔ. Bộ 衣 (quần áo) phù hợp với ngữ cảnh trang phục. Âm Hán-Việt đọc là ''uyển''. Chữ chuyên dùng trong văn bản về trang phục cung đình, không dùng trong tiếng Trung hiện đại. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "褑", "Unihan_Traditional (Chữ Phồn thể)": "褑", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ dải dây trang trí hoặc dây buộc trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褠', '{"9000": "8205.0", "Chữ Trung Quốc": "褠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 褠 | câu | tượng hình | gấu áo; viền ống tay | 褠 thuộc bộ 衣 (y, quần áo). Cấu trúc thành phần chưa được phân tích chi tiết trong CHISE. Nghĩa liên quan đến ''gấu áo'' (viền tay áo) hoặc phần ống tay áo. Chữ chuyên dùng trong ngữ cảnh may mặc cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": bộ 衣 (áo) + âm ''câu'' — cái ''câu'' ống tay áo 褠 như chiếc móc câu nhỏ giữ chặt viền vải, tinh tế như nghề thủ công. | Gương Hán-Việt | câu — ít gặp; gợi nhớ ''gấu áo'' trong tiếng Việt (viền ống tay) | Mở khoá kiến thức | Biết bộ 衣 mở khoá: 袖 (tụ — ống tay), 領 (lĩnh — cổ áo), 裾 (cư — gấu áo), 襟 (khâm — vạt áo).", "Tự nguyên_Xie": "Theo Wiktionary, 褠 bị đánh dấu rfdef. Tuy nhiên, nguồn dữ liệu ghi nghĩa tiếng Việt là ''gấu (vhn)/câu (btcn)'' — ''gấu'' theo tiếng Việt hiện đại là phần viền ống tay áo, ''câu'' là âm cổ. Âm đọc gōu, âm Hán-Việt đọc là ''câu''. Bộ 衣 (quần áo) phù hợp với ngữ cảnh may mặc. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gấu; như \"gấu áo\" (vhn) câu (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 冓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤冓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褠", "Unihan_Traditional (Chữ Phồn thể)": "褠", "Pinyin_Xie": "gōu", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại áo mặc ngoài thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訔', '{"9000": "8206.0", "Chữ Trung Quốc": "訔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 訔 | ngân | tượng hình | chữ độc thể bộ ngôn, chỉ trạng thái nói tranh luận | 訔 thuộc bộ 言 (Ngôn, lời nói); Wiktionary chỉ ghi nhận dùng trong từ láy 訔訔, cấu trúc thành phần không phân tích cụ thể. Đây là chữ hình thanh hoặc hội ý cổ, thường dùng dạng trùng lặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": bộ 言 (ngôn, lời nói) gợi hình ảnh tiếng cãi cọ vang lên như âm ngân — 訔訔 là tiếng tranh luận bướng bỉnh. | Gương Hán-Việt | ngân — không phổ biến trong Hán-Việt hiện đại; xuất hiện trong văn ngôn cổ | Mở khoá kiến thức | Biết 訔 (ngân) giúp nhận dạng chữ láy 訔訔 trong văn ngôn cổ chỉ sự bướng bỉnh, cãi cọ.", "Tự nguyên_Xie": "訔 (ngân): chữ thuộc bộ 言 (Ngôn). Wiktionary ghi âm Trung Cổ ngân (ngan4), Thượng Cổ có nguồn gốc. Nghĩa chính chỉ xuất hiện ở dạng láy 訔訔, diễn tả trạng thái cãi cọ, bướng bỉnh. Không có phân tích thành phần cụ thể, đây là chữ hiếm trong văn ngôn. Chưa có nguồn học thuật phân tích glyph cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồn; như \"cao ngồn ngộn\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "言", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "訔", "Unihan_Traditional (Chữ Phồn thể)": "訔", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả thái độ nói năng hòa nhã và tôn trọng khi tranh luận. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詗', '{"9000": "8207.0", "Chữ Trung Quốc": "詗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詗 | huýnh | tượng hình | chữ bộ ngôn, chỉ hành vi thăm dò, do thám bằng lời | 詗 thuộc bộ 言 (Ngôn, lời nói); cấu trúc thành phần không được Wiktionary phân tích cụ thể. Nghĩa liên quan đến thám thính, dò xét. Có thể là hình thanh nhưng chưa xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huýnh\": bộ 言 (lời nói) gợi hình ảnh dùng lời để dò xét, thăm dò bí mật — 詗 là hành vi thám thính qua ngôn ngữ. | Gương Hán-Việt | huýnh — không phổ biến trong từ vựng Hán-Việt hiện đại; thấy trong văn ngôn quân sự cổ | Mở khoá kiến thức | Biết 詗 (huýnh) giúp đọc văn ngôn về tình báo, thám thính cổ đại: 詗察, 詗伺.", "Tự nguyên_Xie": "詗 (huýnh): chữ thuộc bộ 言 (Ngôn). Âm Quan Thoại xiòng, Quảng Đông hing3/gwing2. Nghĩa gốc là do thám, thăm dò, thám thính. Thấy trong từ cổ như 詗察 (thám thính, quan sát), 詗伺 (rình rập, theo dõi), 詗邏 (tuần tra thám thính). Wiktionary không có phân tích thành phần glyph. Chưa có nguồn học thuật xác định cấu trúc chính xác. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tin đồn", "Hạng Tần Suất (Jun Da)": "7847.0", "Tần Suất % (Jun Da)": "99.9990723707", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "诇", "Unihan_Traditional (Chữ Phồn thể)": "詗", "Pinyin_Xie": "xiòng", "Âm Hán Việt_Xie": "huýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động đi dò xét tình hình hoặc làm danh từ chỉ tin tức thu thập được. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詪', '{"9000": "8208.0", "Chữ Trung Quốc": "詪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói | 艮 | cấn | biểu âm | cứng chắc, bướng — cung cấp âm | 詪 = 言 (Ngôn, biểu nghĩa: lời nói) + 艮 (Cấn, biểu âm); chữ hình thanh. Phần 言 cho biết liên quan đến ngôn từ, phần 艮 cung cấp âm đọc và gợi tính chất cứng rắn, hung hãn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngận\": 言 (ngôn, lời nói) + 艮 (cấn, cứng/bướng) — lời nói cứng rắn, hung ác như bản tính của 艮; 詪 là ngôn từ hung hãn. | Gương Hán-Việt | ngận — rất hiếm trong Hán-Việt hiện đại; từ điển cổ ghi nghĩa hung hãn | Mở khoá kiến thức | Biết 詪 (ngận) giúp nhận ra gốc chữ trong 狠 (hận/hung ác) và các chữ cùng âm 艮 trong văn ngôn.", "Tự nguyên_Xie": "詪 (ngận): chữ hình thanh, gồm 言 (Ngôn, lời nói, biểu nghĩa) và 艮 (Cấn, biểu âm). Wiktionary xác nhận cấu trúc Han compound: 言 (c1=s, biểu nghĩa) + 艮 (c2=p, biểu âm). Nghĩa trong từ điển cổ là hung hãn, tàn ác, dùng trong văn ngôn để chỉ lời lẽ hay tính cách độc ác, hung tàn. Âm đọc hěn liên quan đến 狠 (hung ác). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "說", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詪", "Unihan_Traditional (Chữ Phồn thể)": "詪", "Pinyin_Xie": "hěn", "Âm Hán Việt_Xie": "ngận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ trạng thái nói năng không lưu loát hoặc tranh cãi gay gắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諈', '{"9000": "8209.0", "Chữ Trung Quốc": "諈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 諈 | trụy | tượng hình | chữ bộ ngôn, nghĩa không rõ trong Wiktionary | 諈 thuộc bộ 言 (Ngôn, lời nói); Wiktionary không cung cấp phân tích thành phần cụ thể (rfdef). Đây là chữ cực hiếm trong văn ngôn cổ Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụy\": bộ 言 (lời nói) kết hợp với âm đọc zhuì gợi liên tưởng đến 墜 (trụy, rơi xuống) — lời nói rơi vào tai người nghe. | Gương Hán-Việt | trụy — không dùng trong Hán-Việt hiện đại; chữ cực hiếm | Mở khoá kiến thức | Biết 諈 (trụy) giúp nhận dạng chữ hiếm trong văn ngôn; liên hệ âm đọc với 墜 (trụy, rơi).", "Tự nguyên_Xie": "諈 (trụy): chữ thuộc bộ 言 (Ngôn). Âm Quan Thoại zhuì, Quảng Đông ceoi4. Wiktionary không cung cấp định nghĩa cụ thể (rfdef), chỉ ghi nhận âm đọc Trung Cổ và Thượng Cổ. Đây là chữ văn ngôn cực hiếm, nghĩa cụ thể không còn rõ ràng trong nguồn học thuật hiện đại. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "興", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諈", "Unihan_Traditional (Chữ Phồn thể)": "諈", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "trụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong từ ghép để chỉ việc đùn đẩy trách nhiệm hoặc ủy thác công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讌', '{"9000": "8210.0", "Chữ Trung Quốc": "讌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 23 | nét | 讌 | yến | tượng hình | dị thể của 宴, tiệc yến | 讌 là dị thể của 宴 (Yến, tiệc yến); Wiktionary ghi {{zh-see|宴|v}} xác nhận đây là chữ dị thể. Thành phần cụ thể không phân tích riêng, nhưng bộ 言 (Ngôn) có thể hiện diện trong cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\": 讌 là dị thể của 宴 (yến) — tiệc yến, hội tụ. Bộ 言 (lời nói) gợi hình ảnh bữa tiệc đầy tiếng nói cười. | Gương Hán-Việt | yến — dùng trong 宴會 (yến hội, bữa tiệc), 宴席 (tiệc tùng); 讌 là dạng cổ ít dùng | Mở khoá kiến thức | Biết 讌 (yến) giúp nhận ra dị thể của 宴 trong văn bản cổ; gặp 讌 = 宴.", "Tự nguyên_Xie": "讌 (yến): dị thể của 宴 (Yến). Wiktionary xác nhận 讌 = 宴 ({{zh-see|宴|v}}), cùng nghĩa là tiệc yến, bữa tiệc. Chữ 宴 gốc là hình hội ý: 宀 (mái nhà) + 妟 (yên bình), gợi ý cảnh tụ họp yên bình trong nhà. Dạng 讌 thêm bộ 言 (Ngôn) có thể nhấn mạnh tính chất hội thoại trong tiệc yến. Đây là chữ cổ, ngày nay dùng 宴. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yến", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 燕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言燕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "燕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "䜩", "Unihan_Traditional (Chữ Phồn thể)": "讌", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ bữa tiệc hoặc động từ chỉ việc thiết đãi tiệc rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豗', '{"9000": "8211.0", "Chữ Trung Quốc": "豗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 10 | nét | 豗 | hôi | tượng hình | chữ bộ tượng, chỉ tiếng ồn ào, huyên náo | 豗 thuộc bộ 豕 (Tượng, lợn); cấu trúc thành phần không được Wiktionary phân tích cụ thể. Nghĩa là tiếng ồn ào, huyên náo, hỗn loạn. Hình dạng gợi âm thanh hỗn độn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hôi\": bộ 豕 (tượng, lợn) gợi hình ảnh bầy lợn kêu ồn ào hỗn loạn — 豗 là tiếng huyên náo, hỗn độn. | Gương Hán-Việt | hôi — không phổ biến trong Hán-Việt hiện đại; thấy trong văn ngôn mô tả cảnh hỗn loạn | Mở khoá kiến thức | Biết 豗 (hôi) giúp đọc văn ngôn mô tả cảnh ồn ào, hỗn loạn: 喧豗, 轟豗.", "Tự nguyên_Xie": "豗 (hôi): chữ thuộc bộ 豕 (Tượng, lợn). Âm Quan Thoại huī. Nghĩa gốc là tiếng ồn ào, huyên náo, tiếng đụng chạm hỗn loạn. Thấy trong từ cổ 喧豗 (ồn ào náo nhiệt), 轟豗 (tiếng sấm sét, tiếng nổ lớn), 堆豗 (chất đống hỗn loạn). Wiktionary không có phân tích glyph chi tiết. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh nhau", "Hạng Tần Suất (Jun Da)": "8211.0", "Tần Suất % (Jun Da)": "99.9995131884", "GavinGrover_Once (Chiết tự trực tiếp)": "兀 + 豕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴兀豕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豗", "Unihan_Traditional (Chữ Phồn thể)": "豗", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "hôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn ngôn để chỉ hành vi đấm đá hoặc va chạm mạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豷', '{"9000": "8212.0", "Chữ Trung Quốc": "豷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 19 | nét | 豷 | ế | tượng hình | chữ bộ tượng, chỉ tiếng thở dốc của lợn | 豷 thuộc bộ 豕 (Tượng, lợn); nghĩa cổ là tiếng thở dốc, thở hổn hển của lợn. Wiktionary không phân tích cấu trúc thành phần cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\": bộ 豕 (tượng, lợn) trực tiếp gợi hình ảnh con lợn thở hổn hển — 豷 là âm thanh đặc trưng của lợn thở dốc. | Gương Hán-Việt | ế — không dùng trong Hán-Việt hiện đại; chữ cổ đã lỗi thời | Mở khoá kiến thức | Biết 豷 (ế) giúp nhận dạng chữ cổ mô tả hành vi động vật trong văn ngôn; liên hệ bộ 豕 với các chữ về lợn.", "Tự nguyên_Xie": "豷 (ế): chữ thuộc bộ 豕 (Tượng, lợn). Âm Quan Thoại yì. Wiktionary ghi nghĩa cổ là ''panting of a pig'' (tiếng thở dốc của lợn), với nhãn {{lb|zh|obs-std}} cho thấy đây là chữ cổ không còn dùng trong tiêu chuẩn hiện đại. Không có phân tích glyph chi tiết. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lợn thở, lợn nghỉ", "Hạng Tần Suất (Jun Da)": "8212.0", "Tần Suất % (Jun Da)": "99.9995137052", "GavinGrover_Once (Chiết tự trực tiếp)": "豕 + 壹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕壹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豷", "Unihan_Traditional (Chữ Phồn thể)": "豷", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loài heo lớn hoặc động từ mô tả tiếng heo thở phì phò. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貗', '{"9000": "8213.0", "Chữ Trung Quốc": "貗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 18 | nét | 貗 | cự | tượng hình | chữ bộ thú, chỉ lợn rừng nhỏ | 貗 thuộc bộ 豸 (Trĩ, thú không chân) hoặc bộ thú; Wiktionary ghi nghĩa cổ là lợn rừng còn nhỏ. Cấu trúc thành phần không được phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": chữ chỉ lợn rừng nhỏ — âm cự gợi liên tưởng đến sự hung hăng (cự tuyệt, cự địch) nhưng ở đây là con thú nhỏ bé, dữ dội. | Gương Hán-Việt | cự — không dùng trong Hán-Việt hiện đại; chữ cổ về động vật hoang dã | Mở khoá kiến thức | Biết 貗 (cự) giúp nhận dạng chữ cổ về động vật trong văn ngôn; liên hệ bộ thú.", "Tự nguyên_Xie": "貗 (cự): chữ thuộc bộ thú cổ. Âm Quan Thoại jù, Quảng Đông geoi6. Wiktionary ghi nghĩa {{lb|zh|obs-std}} là ''young wild boar'' (lợn rừng còn nhỏ). Đây là chữ cực cổ, lỗi thời trong tiêu chuẩn hiện đại. Không có phân tích glyph chi tiết. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "貗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 婁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸婁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貗", "Unihan_Traditional (Chữ Phồn thể)": "貗", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loài động vật hoang dã trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貣', '{"9000": "8214.0", "Chữ Trung Quốc": "貣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 貣 | đặc | tượng hình | chữ bộ bối, chỉ hành vi vay mượn | 貣 thuộc bộ 貝 (Bối, tiền bạc, của cải); Wiktionary chỉ cung cấp thông tin {{Han etym}} không có phân tích cụ thể. Nghĩa liên quan đến vay mượn, bổ trợ về tài chính.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đặc\": bộ 貝 (bối, tiền bạc) gợi hình ảnh hoạt động kinh tế — 貣 liên quan đến giao dịch tài chính cổ đại, âm đặc gợi sự đặc biệt, riêng biệt. | Gương Hán-Việt | đặc — không dùng trong Hán-Việt hiện đại; chữ cổ về tài chính | Mở khoá kiến thức | Biết 貣 (đặc) giúp nhận dạng chữ cổ bộ 貝 trong văn bản tài chính cổ; liên hệ bộ Bối với tiền bạc.", "Tự nguyên_Xie": "貣 (đặc): chữ thuộc bộ 貝 (Bối, tiền bạc). Âm Quan Thoại tè. Wiktionary chỉ ghi {{Han etym}}, không có định nghĩa hay phân tích glyph. Đây là chữ cực hiếm, nghĩa và cấu trúc không còn được ghi chép đầy đủ. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật phân tích cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Fen", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "弋 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱弋貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弋", "Unihan_Simplified (Chữ Giản thể)": "貣", "Unihan_Traditional (Chữ Phồn thể)": "貣", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "đặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong cổ văn với nghĩa vay mượn tiền tài hoặc cầu xin điều gì. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賯', '{"9000": "8215.0", "Chữ Trung Quốc": "賯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 賯 | hung | tượng hình | chữ bộ bối, nghĩa chưa rõ | 賯 thuộc bộ 貝 (Bối, tiền bạc); không có anchor glyph. Cấu trúc thành phần và nghĩa cụ thể không rõ trong nguồn hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hung\": bộ 貝 (tiền bạc) kết hợp âm xiōng gợi liên tưởng đến 凶 (hung hiểm) — 賯 có thể liên quan đến giao dịch không may mắn trong văn ngôn cổ. | Gương Hán-Việt | hung — không dùng trong Hán-Việt hiện đại; chữ cực hiếm | Mở khoá kiến thức | Biết 賯 (hung) giúp nhận dạng chữ cổ bộ Bối trong văn bản cực hiếm.", "Tự nguyên_Xie": "賯 (hung): chữ thuộc bộ 貝 (Bối, tiền bạc). Âm Quan Thoại xiōng. Wiktionary không có dữ liệu glyph. Đây là chữ cực hiếm, nghĩa không được ghi chép rõ ràng trong các nguồn học thuật hiện có. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 㝁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝㝁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㝁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賯", "Unihan_Traditional (Chữ Phồn thể)": "賯", "Pinyin_Xie": "xiōng", "Âm Hán Việt_Xie": "hung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc đem đồ vật đi biếu tặng hoặc đút lót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贋', '{"9000": "8216.0", "Chữ Trung Quốc": "贋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 19 | nét | 雁 | nhạn | biểu âm | chim nhạn — cung cấp âm | 貝 | bối | biểu nghĩa | tiền bạc, của cải | 贋 = 雁 (Nhạn, biểu âm) + 貝 (Bối, biểu nghĩa: tiền bạc); chữ hình thanh. Phần 貝 cho biết liên quan đến tiền bạc, của cải; phần 雁 cung cấp âm. Wiktionary xác nhận 贋 là dị thể của 贗 (giả mạo, đồ giả).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhạn\": 雁 (chim nhạn, biểu âm) + 貝 (tiền bạc) — chim nhạn bay cao nhưng đây là tiền giả; 贋 = hàng nhái, đồ giả trong giao dịch. | Gương Hán-Việt | nhạn — trong 贗品 (nhạn phẩm, hàng giả), 贗作 (nhạn tác, tác phẩm giả mạo) | Mở khoá kiến thức | Biết 贋/贗 (nhạn) giúp đọc văn bản về đồ cổ, nghệ thuật: 贗品 (hàng giả), 贗作 (tác phẩm giả).", "Tự nguyên_Xie": "贋 (nhạn): chữ hình thanh, gồm 雁 (Nhạn, biểu âm) và 貝 (Bối, tiền bạc, biểu nghĩa). Wiktionary xác nhận {{Han compound|雁|貝|c1=p|c2=s|t2=money|ls=psc}} và 贋 là dị thể của 贗. Nghĩa là đồ giả, hàng nhái, vật phẩm không thật — đặc biệt trong lĩnh vực tiền bạc và đồ vật quý. Hình ảnh chim nhạn (雁) kết hợp với tiền (貝) gợi ý kẻ mạo danh, lừa đảo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giả mạo", "Hạng Tần Suất (Jun Da)": "4692.0", "Tần Suất % (Jun Da)": "99.88759975", "GavinGrover_Once (Chiết tự trực tiếp)": "雁 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴雁貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "赝", "Unihan_Traditional (Chữ Phồn thể)": "贋", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "nhạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng trước danh từ để chỉ các loại hàng hóa hoặc tác phẩm nghệ thuật giả. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冱', '{"9000": "8217.0", "Chữ Trung Quốc": "冱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 6 | nét | 冱 | hỗ | tượng hình | chữ bộ băng, chỉ trạng thái đóng băng, bế tắc | 冱 thuộc bộ 冫 (Băng, lạnh); Wiktionary không phân tích thành phần cụ thể. Nghĩa là đóng băng, bị bịt kín, bế tắc do lạnh giá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": bộ 冫 (băng, lạnh) trực tiếp gợi cảnh lạnh giá đóng băng — 冱 là sự đông cứng, bế tắc do giá lạnh. | Gương Hán-Việt | hỗ — không phổ biến trong Hán-Việt hiện đại; thấy trong thơ văn cổ về mùa đông | Mở khoá kiến thức | Biết 冱 (hỗ) giúp đọc văn thơ cổ về mùa đông, băng giá: 冱寒, 凝冱.", "Tự nguyên_Xie": "冱 (hỗ): chữ thuộc bộ 冫 (Băng, lạnh). Âm Quan Thoại hù, Quảng Đông wu6. Nghĩa gốc là đóng băng, lạnh cứng; cũng có nghĩa là bị bịt kín, tắc nghẽn. Thấy trong từ cổ 冱寒 (lạnh giá, đóng băng), 凝冱 (đông cứng vì lạnh). Wiktionary cung cấp âm đọc nhưng không có phân tích glyph chi tiết. Chưa có nguồn học thuật xác định cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rét đóng lại", "Hạng Tần Suất (Jun Da)": "8217.0", "Tần Suất % (Jun Da)": "99.9995162891", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 互", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫互", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "互", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "冱", "Unihan_Traditional (Chữ Phồn thể)": "冱", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả thời tiết đông lạnh hoặc động từ chỉ sự ngưng kết do lạnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輀', '{"9000": "8218.0", "Chữ Trung Quốc": "輀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 輀 | nhĩ | tượng hình | chữ bộ xa, chỉ xe tang | 輀 thuộc bộ 車 (Xa, xe cộ); Wiktionary không phân tích thành phần cụ thể. Nghĩa là xe tang (hearse), xe chở linh cữu trong tang lễ cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhĩ\": bộ 車 (xa, xe) gợi hình ảnh xe cộ — 輀 là chiếc xe đặc biệt dùng trong tang lễ, chở linh cữu người đã khuất. | Gương Hán-Việt | nhĩ — không dùng trong Hán-Việt hiện đại; thấy trong văn ngôn về tang lễ cổ đại | Mở khoá kiến thức | Biết 輀 (nhĩ) giúp đọc văn ngôn về tang lễ hoàng gia cổ đại: 靈輀, 輀車, 龍輀.", "Tự nguyên_Xie": "輀 (nhĩ): chữ thuộc bộ 車 (Xa, xe). Âm Quan Thoại ér, Quảng Đông ji4. Wiktionary ghi nghĩa {{lb|zh|obsolete}} là ''hearse'' (xe tang). Thấy trong từ cổ 輀車 (xe tang), 靈輀 (xe tang thiêng liêng), 龍輀 (xe tang hoàng gia). Chữ lỗi thời, không dùng trong tiếng Trung hiện đại. Không có phân tích glyph chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe tang, xe đưa đám", "Hạng Tần Suất (Jun Da)": "8218.0", "Tần Suất % (Jun Da)": "99.9995168059", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輀", "Unihan_Traditional (Chữ Phồn thể)": "輀", "Pinyin_Xie": "ér", "Âm Hán Việt_Xie": "nhi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các nghi thức tang lễ cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒈', '{"9000": "8219.0", "Chữ Trung Quốc": "蒈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 皆 | giai | biểu âm | đều, tất cả — cung cấp âm | 蒈 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 皆 (Giai, biểu âm); chữ hình thanh. Phần 艹 cho biết liên quan đến thực vật, phần 皆 cung cấp âm đọc. Wiktionary xác nhận Han compound: 艹 (c1=s) + 皆 (c2=p).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khai\": 艹 (thảo, cỏ) + 皆 (giai, âm) — thực vật với âm giai/khai; 蒈 là tên hóa học của một terpen trong tinh dầu thực vật. | Gương Hán-Việt | khai — ít dùng trong Hán-Việt phổ thông; xuất hiện trong danh pháp hóa học thực vật | Mở khoá kiến thức | Biết 蒈 (khai) giúp nhận dạng tên hóa học thực vật trong văn bản khoa học Hán ngữ hiện đại.", "Tự nguyên_Xie": "蒈 (khai): chữ hình thanh, gồm 艹 (Thảo, cỏ/thực vật, biểu nghĩa) và 皆 (Giai, biểu âm). Wiktionary xác nhận cấu trúc {{Han compound|艸|alt1=艹|皆|ls=psc|c1=s|c2=p}}. Đây là tên một loại thực vật cụ thể (carene, một hợp chất terpene trong tinh dầu thực vật). Âm đọc kǎi gần với 皆 (jiē). Chữ chủ yếu dùng trong hóa học/thực vật học hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ca-ran; ca-ra-nơ (tiếng Anh: carane)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒈", "Unihan_Traditional (Chữ Phồn thể)": "蒈", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong thuật ngữ hóa học hoặc thực vật học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轓', '{"9000": "8220.0", "Chữ Trung Quốc": "轓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 19 | nét | 轓 | phiên | tượng hình | chữ bộ xa, nghĩa chưa rõ | 轓 thuộc bộ 車 (Xa, xe cộ); Wiktionary không cung cấp định nghĩa (rfdef) hay phân tích thành phần cụ thể. Nghĩa không rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": bộ 車 (xa, xe) gợi hình ảnh xe cộ — 轓 có thể là tên một bộ phận hoặc loại xe trong văn ngôn cổ, âm phiên gợi 翻 (lật, quay vòng). | Gương Hán-Việt | phiên — không dùng trong Hán-Việt hiện đại; chữ cực hiếm về xe cộ cổ | Mở khoá kiến thức | Biết 轓 (phiên) giúp nhận dạng chữ hiếm bộ Xa trong văn bản kỹ thuật cổ về xe cộ.", "Tự nguyên_Xie": "轓 (phiên): chữ thuộc bộ 車 (Xa, xe). Âm Quan Thoại fān, Quảng Đông faan1. Wiktionary ghi rfdef (chưa có định nghĩa) nhưng có âm đọc Trung Cổ và Thượng Cổ. Đây là chữ rất hiếm liên quan đến xe cộ hoặc bộ phận xe. Chưa có nguồn học thuật xác nhận nghĩa cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轓", "Unihan_Traditional (Chữ Phồn thể)": "轓", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bộ phận che chắn hai bên của xe ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迋', '{"9000": "8221.0", "Chữ Trung Quốc": "迋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 迋 | uổng | tượng hình | chữ bộ xước, nghĩa chưa rõ | 迋 thuộc bộ 辶 (Xước, đi lại); Wiktionary không cung cấp định nghĩa (rfdef) hay phân tích thành phần cụ thể. Nghĩa liên quan đến di chuyển hoặc hành trình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uổng\": bộ 辶 (xước, đi lại) gợi hình ảnh hành trình — 迋 là chữ cổ về di chuyển, âm uổng/wàng gợi 往 (đi về phía trước). | Gương Hán-Việt | uổng — không dùng trong Hán-Việt hiện đại; chữ cực hiếm | Mở khoá kiến thức | Biết 迋 (uổng) giúp nhận dạng chữ hiếm bộ Xước trong văn bản cổ về địa lý, hành trình.", "Tự nguyên_Xie": "迋 (uổng): chữ thuộc bộ 辶 (Xước, đi lại). Âm Quan Thoại wàng, Quảng Đông wong6. Wiktionary ghi rfdef, có âm đọc Trung Cổ và Thượng Cổ. Đây là chữ cực hiếm, nghĩa không được ghi chép rõ ràng. Có thể liên quan đến khái niệm đi lại, vùng lãnh thổ, hoặc danh từ địa danh. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lừa dối; sợ hãi; đi du lịch", "Hạng Tần Suất (Jun Da)": "8221.0", "Tần Suất % (Jun Da)": "99.9995183563", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 王", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迋", "Unihan_Traditional (Chữ Phồn thể)": "迋", "Pinyin_Xie": "wàng", "Âm Hán Việt_Xie": "vượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ việc di chuyển đi xa hoặc hành vi lừa gạt trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逓', '{"9000": "8222.0", "Chữ Trung Quốc": "逓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逓 | đệ | tượng hình | dạng rút gọn của 遞, chuyển tiếp, chuyển phát | 逓 là shinjitai Nhật Bản (chữ được giản hóa) của 遞, với phần 虒 đổi thành 乕. Wiktionary xác nhận: Japanese shinjitai {{Han simp|遞|f=虒|t=乕}}. Đây là dạng chữ Nhật, không phải chữ Trung truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đệ\": 逓 là dạng Nhật giản hóa của 遞 (đệ) — chuyển tiếp, truyền đi lần lượt. Bộ 辶 (xước, đi lại) cộng với âm đệ gợi hình ảnh truyền tin đi từng chặng. | Gương Hán-Việt | đệ — trong 遞送 (đệ tống, gửi đi), 遞增 (đệ tăng, tăng dần); 逓 là dạng Nhật của 遞 | Mở khoá kiến thức | Biết 逓/遞 (đệ) giúp đọc văn bản Nhật-Hán về truyền thông, bưu điện: 逓信 (teishin).", "Tự nguyên_Xie": "逓 (đệ): dạng shinjitai Nhật Bản của 遞 (Đệ), được giản hóa bằng cách thay thành phần 虒 bằng 乕. Wiktionary xác nhận điều này. Chữ gốc 遞 nghĩa là chuyển tiếp, luân chuyển, truyền đi lần lượt. Trong tiếng Nhật: 逓信 (teishin, truyền thông), đọc là tei. Trong chữ Hán cổ điển, dùng 遞 là dạng chính thống. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Biến thể tiếng Nhật của 遞", "Hạng Tần Suất (Jun Da)": "8222.0", "Tần Suất % (Jun Da)": "99.999518873", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 乕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶乕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逓", "Unihan_Traditional (Chữ Phồn thể)": "逓", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Chữ này thường dùng làm động từ chỉ hành động truyền đạt hoặc phó từ chỉ sự tăng tiến dần dần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酳', '{"9000": "8223.0", "Chữ Trung Quốc": "酳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酉 | dậu | biểu nghĩa | rượu, bình rượu | 胤 | dận | biểu âm | kế thừa — cung cấp âm (dạng rút gọn) | 酳 = 酉 (Dậu, biểu nghĩa: rượu) + 胤 (Dận, biểu âm, dạng rút gọn); chữ hình thanh. Phần 酉 cho biết liên quan đến rượu, phần 胤 (viết tắt) cung cấp âm. Wiktionary xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dận\": 酉 (dậu, rượu) + 胤 (dận, âm) — dùng rượu súc miệng sau tiệc. 酳 là nghi lễ tao nhã trong tiệc yến cổ đại Trung Hoa. | Gương Hán-Việt | dận — không phổ biến trong Hán-Việt hiện đại; thấy trong văn ngôn về lễ nghi tiệc tùng cổ | Mở khoá kiến thức | Biết 酳 (dận) giúp đọc văn ngôn về lễ nghi yến tiệc cổ đại: nghi thức súc miệng bằng rượu.", "Tự nguyên_Xie": "酳 (dận): chữ hình thanh, gồm 酉 (Dậu, rượu, biểu nghĩa) và 胤 (Dận, biểu âm, dạng rút gọn). Wiktionary xác nhận {{Han compound|酉|胤|abb2=y|c1=s|c2=p|t1=alcohol|ls=psc}}. Nghĩa cổ là hành động súc miệng bằng rượu sau bữa ăn — một nghi thức trong tiệc tùng cổ đại Trung Hoa. Nghi lễ này thể hiện sự tôn trọng và thanh tẩy sau khi ăn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "酳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "酳", "Unihan_Traditional (Chữ Phồn thể)": "酳", "Pinyin_Xie": "yìn", "Âm Hán Việt_Xie": "dận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ trong văn ngôn để chỉ nghi thức súc miệng bằng rượu sau bữa ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈪', '{"9000": "8224.0", "Chữ Trung Quốc": "鈪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈪 | ách | tượng hình | chữ bộ kim, nghĩa chưa rõ | 鈪 thuộc bộ 金 (Kim, kim loại); không có anchor glyph. Cấu trúc thành phần và nghĩa cụ thể không rõ trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": bộ 金 (kim, kim loại) gợi vật dụng bằng kim loại — 鈪 là một vật kim loại cụ thể trong văn ngôn cổ, âm ách gợi sự siết chặt (ách chế). | Gương Hán-Việt | ách — không dùng trong Hán-Việt hiện đại; chữ cực hiếm bộ Kim | Mở khoá kiến thức | Biết 鈪 (ách) giúp nhận dạng chữ hiếm bộ Kim trong văn bản kỹ thuật hoặc danh mục đồ vật cổ.", "Tự nguyên_Xie": "鈪 (ách): chữ thuộc bộ 金 (Kim, kim loại). Âm Quan Thoại è. Wiktionary không có dữ liệu glyph. Có thể liên quan đến một vật dụng kim loại hoặc bộ phận kim khí. Đây là chữ cực hiếm, nghĩa không được ghi chép rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈪", "Unihan_Traditional (Chữ Phồn thể)": "鈪", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ các loại vòng đeo tay trong phương ngữ Quảng Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尜', '{"9000": "8225.0", "Chữ Trung Quốc": "尜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 小 | Số nét | 9 | nét | 尜 | ga | tượng hình | tượng hình đồ chơi con quay, nhọn hai đầu | 尜 không có glyph anchor; cấu trúc có thể là hội ý với 大 (đại, to) ở giữa và hai phần nhỏ hai đầu gợi hình dạng con quay nhọn hai đầu. Tượng hình hoặc hội ý đơn giản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ga\": hình dạng chữ 尜 giống con quay — nhọn hai đầu, phình to ở giữa; 尜 là đồ chơi con quay của trẻ em Trung Hoa truyền thống. | Gương Hán-Việt | ga — không dùng trong Hán-Việt; từ thuần Hán chỉ đồ chơi dân gian Trung Hoa | Mở khoá kiến thức | Biết 尜 (ga) giúp nhận dạng tên đồ chơi dân gian trong văn bản văn hóa Trung Hoa: con quay nhọn hai đầu.", "Tự nguyên_Xie": "尜 (ga): chữ không có anchor glyph. Âm Quan Thoại gá. Nghĩa là con quay (spinning top) — đồ chơi trẻ em hình thoi nhọn hai đầu. Cấu trúc chữ gợi hình dạng vật thể nhọn hai đầu to ở giữa. Chưa có nguồn học thuật xác nhận phân tích glyph cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ''''cá'''' (đồ chơi của trẻ em, hai đầu nhọn, ở giữa phình to ra); vật giống cái ''''cá''''", "Hạng Tần Suất (Jun Da)": "8225.0", "Tần Suất % (Jun Da)": "99.9995209402", "GavinGrover_Once (Chiết tự trực tiếp)": "小 + 夵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱小夵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "小", "Unihan_Simplified (Chữ Giản thể)": "尜", "Unihan_Traditional (Chữ Phồn thể)": "尜", "Pinyin_Xie": "gá", "Âm Hán Việt_Xie": "dát, kiết, ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ món đồ chơi dân gian hoặc vật có hình dáng tương tự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轷', '{"9000": "8226.0", "Chữ Trung Quốc": "轷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轷 | hô | tượng hình | dạng giản hóa của 軤, chữ bộ xa | 轷 là dạng giản hóa của 軤, thay bộ 車 bằng 车 (giản thể). Wiktionary xác nhận {{Han simp|軤|f=車|t=car}}. Nghĩa theo 軤.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hô\": bộ 车 (xa, xe) gợi hình ảnh xe cộ — 轷 là dạng giản thể của 軤, một loại xe hoặc bộ phận xe cổ đại. | Gương Hán-Việt | hô — không dùng trong Hán-Việt hiện đại; chữ giản thể hiếm gặp | Mở khoá kiến thức | Biết 轷 (hô) giúp nhận dạng dạng giản thể của 軤 trong văn bản kỹ thuật cổ về xe cộ.", "Tự nguyên_Xie": "轷 (hô): dạng giản hóa của 軤, với 車 (Xa, phồn thể) đổi thành 车 (xa, giản thể). Wiktionary xác nhận {{Han simp|軤|f=車|t=车}} và chỉ về 軤. 軤 là tên một loại xe hoặc bộ phận xe trong văn ngôn cổ. Âm đọc hū liên quan đến âm của 乎 (hồ). Đây là chữ hiếm, chủ yếu dùng trong văn bản về xe cộ cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Hô", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 乎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车乎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轷", "Unihan_Traditional (Chữ Phồn thể)": "轷", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này dùng làm danh từ chỉ họ người hoặc từ tượng thanh mô tả tiếng xe chạy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霘', '{"9000": "8227.0", "Chữ Trung Quốc": "霘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 霘 | đổng | tượng hình | chữ bộ vũ, không có glyph anchor | 霘 thuộc bộ 雨 (Vũ, mưa); không có anchor glyph. Nghĩa liên quan đến hiện tượng khí tượng học. Cấu trúc thành phần không rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổng\": bộ 雨 (vũ, mưa) gợi hiện tượng khí tượng — 霘 là một hiện tượng thời tiết liên quan đến mưa trong văn ngôn cổ, âm đổng gợi 動 (động, chuyển động). | Gương Hán-Việt | đổng — không dùng trong Hán-Việt hiện đại; chữ cực hiếm bộ Vũ | Mở khoá kiến thức | Biết 霘 (đổng) giúp nhận dạng chữ hiếm bộ Vũ trong văn bản khí tượng hoặc thơ văn về thời tiết cổ đại.", "Tự nguyên_Xie": "霘 (đổng): chữ thuộc bộ 雨 (Vũ, mưa). Âm Quan Thoại dòng. Wiktionary không có dữ liệu glyph. Đây là chữ cực hiếm liên quan đến thời tiết hoặc hiện tượng mưa. Nghĩa cụ thể không được ghi chép rõ ràng trong nguồn học thuật hiện đại. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "霘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 洞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨洞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "洞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霘", "Unihan_Traditional (Chữ Phồn thể)": "霘", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này dùng làm danh từ hoặc từ tượng thanh để mô tả âm thanh dữ dội của sấm sét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞄', '{"9000": "8228.0", "Chữ Trung Quốc": "鞄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 14 | nét | 革 | cách | biểu nghĩa | da thuộc, da súc vật | 包 | bao | biểu âm | gói, túi — cung cấp âm | 鞄 = 革 (Cách, biểu nghĩa: da thuộc) + 包 (Bao, biểu âm); chữ hình thanh. Phần 革 cho biết liên quan đến da thuộc, phần 包 cung cấp âm. Wiktionary xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": 革 (cách, da thuộc) + 包 (bao, túi/âm) — da thuộc làm thành túi; 鞄 là nghề thuộc da hoặc túi da, rất phổ biến trong tiếng Nhật (kaban = túi xách). | Gương Hán-Việt | bao — ít dùng trong Hán-Việt; trong tiếng Nhật 鞄 (kaban) nghĩa là túi xách, ba lô | Mở khoá kiến thức | Biết 鞄 (bao) giúp đọc văn bản Nhật-Hán về đồ da: 鞄 (kaban, túi xách) rất phổ biến tiếng Nhật.", "Tự nguyên_Xie": "鞄 (bao): chữ hình thanh, gồm 革 (Cách, da thuộc, biểu nghĩa) và 包 (Bao, biểu âm). Wiktionary xác nhận {{Han compound|革|t1=leather|包|ls=psc|c1=s|c2=p}}. Nghĩa gốc là thuộc da, làm da; cũng có nghĩa là túi da. Trong tiếng Nhật, 鞄 (kaban) nghĩa là túi xách, vali — rất phổ biến trong văn bản Nhật ngữ. Âm Trung Quốc là páo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái túi da; thợ thuộc da", "Hạng Tần Suất (Jun Da)": "8228.0", "Tần Suất % (Jun Da)": "99.9995230073", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞄", "Unihan_Traditional (Chữ Phồn thể)": "鞄", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ túi xách bằng da hoặc động từ chỉ hành động thuộc da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騧', '{"9000": "8229.0", "Chữ Trung Quốc": "騧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 18 | nét | 騧 | qua | tượng hình | chữ bộ mã, chỉ ngựa có màu vàng nhạt | 騧 thuộc bộ 馬 (Mã, ngựa); Wiktionary không cung cấp định nghĩa (rfdef) nhưng có thành phần. Nghĩa liên quan đến ngựa — có thể là tên gọi ngựa màu sắc đặc biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": bộ 馬 (mã, ngựa) gợi hình ảnh con ngựa đẹp — 騧 là tên cổ của ngựa màu vàng nhạt, âm qua gợi 瓜 (dưa vàng) — màu vàng nhạt của dưa. | Gương Hán-Việt | qua — không phổ biến trong Hán-Việt hiện đại; thấy trong văn thơ cổ về ngựa | Mở khoá kiến thức | Biết 騧 (qua) giúp đọc văn thơ cổ về ngựa quý: 騧馬 (ngựa vàng nhạt).", "Tự nguyên_Xie": "騧 (qua): chữ thuộc bộ 馬 (Mã, ngựa). Âm Quan Thoại guā, Quảng Đông waa1/gwaa1. Wiktionary ghi rfdef nhưng có từ ghép 騧馬. Đây là chữ chỉ một loại ngựa màu vàng nhạt hoặc ngựa có màu đặc biệt trong văn ngôn cổ Trung Hoa. Chưa có nguồn học thuật xác định nghĩa cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "騧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 咼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬咼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "䯄", "Unihan_Traditional (Chữ Phồn thể)": "騧", "Pinyin_Xie": "guā", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ trong văn học cổ để chỉ một giống ngựa quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髽', '{"9000": "8230.0", "Chữ Trung Quốc": "髽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 17 | nét | 髽 | troa | tượng hình | chữ bộ bào, chỉ kiểu búi tóc tang lễ | 髽 thuộc bộ 髟 (Bão, tóc); Wiktionary ghi rfdef nhưng có từ ghép 髽髻 (kiểu búi tóc). Nghĩa liên quan đến tóc, đặc biệt là kiểu búi tóc trong tang lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"troa\": bộ 髟 (tóc) gợi hình ảnh tóc được tạo kiểu — 髽 là kiểu búi tóc đặc biệt dùng trong tang lễ cổ đại Trung Hoa. | Gương Hán-Việt | troa — không dùng trong Hán-Việt hiện đại; chữ cổ về nghi lễ tóc tang | Mở khoá kiến thức | Biết 髽 (troa) giúp đọc văn ngôn về tang lễ và lễ nghi tóc cổ đại: 髽髻.", "Tự nguyên_Xie": "髽 (troa): chữ thuộc bộ 髟 (Bão, tóc). Âm Quan Thoại zhuā, Quảng Đông zaa1. Wiktionary ghi rfdef nhưng từ ghép 髽髻 gợi ý đây là một kiểu búi tóc đặc biệt. Trong văn ngôn cổ, 髽 liên quan đến kiểu búi tóc đơn giản trong tang lễ, khi phụ nữ để tang. Chưa có nguồn học thuật phân tích glyph chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc hai mái; rẽ ngôi giữa", "Hạng Tần Suất (Jun Da)": "8230.0", "Tần Suất % (Jun Da)": "99.9995240409", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髽", "Unihan_Traditional (Chữ Phồn thể)": "髽", "Pinyin_Xie": "zhuā", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ kiểu tóc búi hoặc động từ chỉ việc chải tóc, búi tóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魣', '{"9000": "8231.0", "Chữ Trung Quốc": "魣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魣 | tự | tượng hình | chữ bộ ngư, chỉ một loài cá | 魣 thuộc bộ 魚 (Ngư, cá); không có anchor glyph. Là tên một loài cá cụ thể. Cấu trúc thành phần không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": bộ 魚 (ngư, cá) trực tiếp cho biết đây là tên cá — 魣 là tên loài cá cổ trong văn ngôn, âm tự gợi 序 (thứ tự) hay 緒 (đầu mối). | Gương Hán-Việt | tự — không dùng trong Hán-Việt hiện đại; tên loài cá cổ | Mở khoá kiến thức | Biết 魣 (tự) giúp nhận dạng tên loài cá trong danh mục sinh vật cổ đại Trung Hoa.", "Tự nguyên_Xie": "魣 (tự): chữ thuộc bộ 魚 (Ngư, cá). Âm Quan Thoại xù. Wiktionary không có dữ liệu glyph. Đây là tên một loài cá trong văn ngôn cổ. Nghĩa và đặc điểm cụ thể của loài cá không được ghi chép rõ ràng trong nguồn học thuật hiện đại. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá rô", "Hạng Tần Suất (Jun Da)": "8231.0", "Tần Suất % (Jun Da)": "99.9995245577", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 予", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚予", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "予", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魣", "Unihan_Traditional (Chữ Phồn thể)": "魣", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loài cá nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰰', '{"9000": "8232.0", "Chữ Trung Quốc": "鰰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鰰 | thần | tượng hình | chữ bộ ngư, tên loài cá | 鰰 thuộc bộ 魚 (Ngư, cá); không có anchor glyph. Là tên loài cá cụ thể. Cấu trúc thành phần không rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thần\": bộ 魚 (ngư, cá) + âm thần gợi 神 (thần linh) — 鰰 trong tiếng Nhật (hatahata) là cá sandfish nổi tiếng vùng Akita, gắn liền với văn hóa mùa đông Nhật Bản. | Gương Hán-Việt | thần — không dùng trong Hán-Việt thông dụng; trong tiếng Nhật 鰰 = hatahata (cá sandfish) | Mở khoá kiến thức | Biết 鰰 (thần) giúp nhận dạng tên loài cá trong danh mục hải sản Nhật-Hán: hatahata (cá sandfish Akita).", "Tự nguyên_Xie": "鰰 (thần): chữ thuộc bộ 魚 (Ngư, cá). Âm Quan Thoại shén. Wiktionary không có dữ liệu glyph. Đây là tên một loài cá. Trong tiếng Nhật, 鰰 (hatahata) là tên cá sandfish (Arctoscopus japonicus), một loài cá biển ở vùng biển Nhật Bản — nổi tiếng trong ẩm thực vùng Akita. Chưa có nguồn học thuật Trung Quốc xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 神", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚神", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "神", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰰", "Unihan_Traditional (Chữ Phồn thể)": "鰰", "Pinyin_Xie": "shen", "Âm Hán Việt_Xie": "thần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ một loài cá biển đặc trưng của Nhật Bản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴹', '{"9000": "8233.0", "Chữ Trung Quốc": "鴹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴹 | nhương | tượng hình | chữ bộ điểu, chỉ chim thần thoại | 鴹 thuộc bộ 鳥 (Điểu, chim); Wiktionary ghi đây là chim thần thoại có thể tạo ra mưa lớn. Cấu trúc thành phần không được phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhương\": bộ 鳥 (điểu, chim) gợi hình ảnh chim trời — 鴹 là chim thần thoại trong truyền thuyết Trung Hoa, có khả năng tạo ra mưa lớn. | Gương Hán-Việt | nhương — không dùng trong Hán-Việt hiện đại; chữ thần thoại học cổ đại | Mở khoá kiến thức | Biết 鴹 (nhương) giúp đọc văn ngôn thần thoại Trung Hoa về chim thần và hiện tượng mưa.", "Tự nguyên_Xie": "鴹 (nhương): chữ thuộc bộ 鳥 (Điểu, chim). Âm Quan Thoại rén/yáng. Wiktionary ghi nghĩa {{lb|zh|obs-std}} là ''a mythical bird which can create heavy rain'' (chim thần thoại có thể tạo ra mưa lớn). Đây là chim trong truyền thuyết Trung Hoa cổ đại, liên quan đến hiện tượng mưa. Chưa có phân tích glyph chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gà lôi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "鴹", "Unihan_Traditional (Chữ Phồn thể)": "鴹", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn bản cổ để chỉ một loài chim nước có hình dáng giống gà trĩ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼪', '{"9000": "8234.0", "Chữ Trung Quốc": "鼪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 18 | nét | 鼠 | thử | biểu nghĩa | chuột, loài gặm nhấm | 生 | sinh | biểu âm | sinh sống — cung cấp âm | 鼪 = 鼠 (Thử, biểu nghĩa: chuột) + 生 (Sinh, biểu âm); chữ hình thanh. Phần 鼠 cho biết là loài gặm nhấm, phần 生 cung cấp âm đọc. Wiktionary xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sinh\": 鼠 (thử, chuột) + 生 (sinh, âm) — loài vật họ chuột mà 生 mà ra; 鼪 là chuột chù hoặc chồn hôi, sinh sống bí ẩn. | Gương Hán-Việt | sinh — ít dùng trong Hán-Việt hiện đại; tên động vật cổ | Mở khoá kiến thức | Biết 鼪 (sinh) giúp đọc văn ngôn về động vật hoang dã: chuột chù hoặc chồn.", "Tự nguyên_Xie": "鼪 (sinh): chữ hình thanh, gồm 鼠 (Thử, chuột, biểu nghĩa) và 生 (Sinh, biểu âm). Wiktionary xác nhận {{Han compound|鼠|生|ls=psc|c1=s|c2=p|t1=mouse; rat}}. 鼪 là tên gọi chuột chù hoặc chồn hôi (weasel/stoat) trong tiếng Trung cổ. Đây là loài động vật nhỏ thuộc họ chuột chù hay chồn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chồn", "Hạng Tần Suất (Jun Da)": "8234.0", "Tần Suất % (Jun Da)": "99.9995266248", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 生", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠生", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "生", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼪", "Unihan_Traditional (Chữ Phồn thể)": "鼪", "Pinyin_Xie": "shēng", "Âm Hán Việt_Xie": "sinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài chồn hoặc loài gặm nhấm nhỏ trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秊', '{"9000": "8235.0", "Chữ Trung Quốc": "秊", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "秊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "秊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "秊", "Unihan_Traditional (Chữ Phồn thể)": "秊", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眮', '{"9000": "8237.0", "Chữ Trung Quốc": "眮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 眮 | đồng | tượng hình | chữ bộ mục, nghĩa chưa rõ | 眮 thuộc bộ 目 (Mục, mắt); Wiktionary ghi rfdef, không có phân tích thành phần cụ thể. Nghĩa liên quan đến mắt hoặc nhìn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ 目 (mục, mắt) gợi hình ảnh liên quan đến nhìn ngắm — 眮 âm đồng gợi 瞳 (đồng, con ngươi); có thể là trạng thái đặc biệt của mắt trong văn ngôn cổ. | Gương Hán-Việt | đồng — không dùng trong Hán-Việt hiện đại; chữ cực hiếm bộ Mục | Mở khoá kiến thức | Biết 眮 (đồng) giúp nhận dạng chữ hiếm bộ Mục trong văn bản y học hoặc thơ văn cổ về mắt.", "Tự nguyên_Xie": "眮 (đồng): chữ thuộc bộ 目 (Mục, mắt). Âm Quan Thoại tóng. Wiktionary ghi rfdef và {{rfdef|zh|sort=目06}}. Đây là chữ cực hiếm bộ Mục, nghĩa cụ thể không được ghi chép. Âm đọc tóng gần với 瞳 (đồng, con ngươi). Có thể liên quan đến một trạng thái nhìn hoặc đặc điểm mắt cụ thể. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồng; như \"đồng tử\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眮", "Unihan_Traditional (Chữ Phồn thể)": "眮", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ bộ phận của mắt hoặc động từ chỉ hành vi nhìn chăm chú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笀', '{"9000": "8238.0", "Chữ Trung Quốc": "笀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 笀 | măng | tượng hình | chữ bộ trúc, có thể là tên thực vật | 笀 thuộc bộ 竹 (Trúc, tre); không có anchor glyph. Cấu trúc thành phần không rõ. Có thể là tên gọi một bộ phận hoặc sản phẩm từ tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"măng\": bộ 竹 (trúc, tre) + âm máng gợi trực tiếp đến 笋/筍 (măng tre) — 笀 có thể là tên cổ hoặc dị thể liên quan đến măng hoặc sản phẩm từ tre. | Gương Hán-Việt | măng — âm thuần Việt \"măng\" (bamboo shoot) trùng với âm đọc Hán-Việt; 笀 có thể là tên cổ liên quan | Mở khoá kiến thức | Biết 笀 (măng) giúp nhận dạng chữ cổ bộ Trúc trong danh mục thực vật hoặc sản phẩm tre cổ đại.", "Tự nguyên_Xie": "笀 (măng): chữ thuộc bộ 竹 (Trúc, tre). Âm Quan Thoại máng. Wiktionary không có dữ liệu glyph. Đây là chữ cực hiếm bộ Trúc. Với âm máng/măng và bộ Trúc, rất có thể liên quan đến măng (bamboo shoot) hoặc một sản phẩm tre trong văn ngôn cổ. Tuy nhiên chưa có nguồn học thuật xác nhận cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "măng; như \"măng tre; mãng trúc; măng non\" (vhn)", "Hạng Tần Suất (Jun Da)": "8238.0", "Tần Suất % (Jun Da)": "99.9995292087", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 亡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮亡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笀", "Unihan_Traditional (Chữ Phồn thể)": "笀", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ phần râu nhọn của hạt ngũ cốc hoặc mầm non của tre trúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籣', '{"9000": "8239.0", "Chữ Trung Quốc": "籣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 23 | nét | 籣 | tràn | tượng hình | ống đựng tên (quiver), chữ độc thể bộ 竹 | 籣 là chữ độc thể dưới bộ 竹 (Trúc), chưa phân tích được thành phần biểu âm/biểu nghĩa rõ ràng qua nguồn học thuật hiện có. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tràn\": bộ Trúc (竹) gợi ống tre — ống đựng tên cung thủ ngày xưa làm bằng tre. | Gương Hán-Việt | tràn — ít dùng trong tiếng Việt hiện đại, xuất hiện trong văn bản Hán Nôm cổ. | Mở khoá kiến thức | Biết 籣 giúp đọc hiểu văn bản võ thuật và lịch sử cổ Trung Hoa về vũ khí.", "Tự nguyên_Xie": "Tiểu triện | 籣 (lán) chỉ bao đựng tên (mũi tên) trong lịch sử, ghi nhận trong Wiktionary dưới dạng danh từ lịch sử (historical quiver). Cấu trúc nội tại chưa được phân tích đầy đủ theo lục thư. Chưa có nguồn học thuật chính thức về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống đựng tên", "Hạng Tần Suất (Jun Da)": "8239.0", "Tần Suất % (Jun Da)": "99.9995297255", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 闌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮闌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籣", "Unihan_Traditional (Chữ Phồn thể)": "籣", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ dụng cụ đeo bên người để đựng cung tên của binh lính thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藑', '{"9000": "8240.0", "Chữ Trung Quốc": "藑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藑 | quỳnh | tượng hình | cỏ quỳnh mao — loài cỏ ghi trong sách cổ, bộ 艸 | 藑 là chữ độc thể dưới bộ 艸 (Thảo — cỏ), chưa có phân tích hình thanh/hội ý từ nguồn học thuật. Chữ chỉ xuất hiện trong tổ hợp 藑茅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": bộ Thảo (艸) — cỏ quỳnh, loài thực vật hiếm gặp chỉ nhắc đến trong kinh điển cổ Trung Hoa. | Gương Hán-Việt | quỳnh — trong tiếng Việt có \"quỳnh\" chỉ hoa quỳnh (Epiphyllum), không liên quan trực tiếp nhưng cùng âm. | Mở khoá kiến thức | Biết 藑 giúp nhận diện tên cây cỏ cổ trong Kinh Thi và thư tịch Hán cổ.", "Tự nguyên_Xie": "藑 (qióng) chỉ xuất hiện trong tổ hợp 藑茅 theo Wiktionary, là tên một loài cỏ ghi trong thư tịch cổ. Cấu trúc glyph chưa được phân tích chính thức. Chưa có nguồn học thuật về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ quỳnh mao (nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 夐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹夐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藑", "Unihan_Traditional (Chữ Phồn thể)": "藑", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cỏ tranh hoặc thảo mộc được nhắc đến trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垲', '{"9000": "8241.0", "Chữ Trung Quốc": "垲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垲 | khải | tượng hình | đất cao ráo; dạng giản hóa của 塏 | 垲 là dạng giản hóa (简化字) của 塏, thay bộ phận 豈 bằng 岂. Bản thể 塏 gồm 土 (Thổ, biểu nghĩa: đất) + 豈 (biểu âm). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": bộ Thổ (土) là đất — đất \"khải\" là đất cao ráo, giống như khải hoàn (凱旋) mang khí thế vươn cao. | Gương Hán-Việt | khải — trong tiếng Việt có \"khải hoàn\" (凱旋), cùng âm Hán-Việt nhưng chữ khác. | Mở khoá kiến thức | Biết 垲 giúp đọc mô tả địa lý trong văn bản cổ về địa thế, phong thủy.", "Tự nguyên_Xie": "Tiểu triện | 垲 là chữ giản hóa của 塏 theo Wiktionary ({{Han simp|塏|f=豈|t=岂}}). Bản thể 塏 gồm bộ 土 (đất) làm nghĩa phù và 豈 làm âm phù. Nghĩa gốc: vùng đất cao ráo, thoáng đãng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất cao ráo", "Hạng Tần Suất (Jun Da)": "8241.0", "Tần Suất % (Jun Da)": "99.9995307591", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垲", "Unihan_Traditional (Chữ Phồn thể)": "塏", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng trước danh từ để miêu tả địa hình đất đai cao ráo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍳', '{"9000": "8242.0", "Chữ Trung Quốc": "鍳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍳 | giám | tượng hình | gương soi bằng đồng; dạng cổ/dị thể của 鑑/鉴 | 鍳 là dị thể của 鑑 (giám — gương đồng). Không có phân tích thành phần rõ ràng từ nguồn học thuật. Chưa có glyph origin trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giám\": bộ Kim (金) — đồ kim loại dùng để soi bóng mình, như \"giám sát\" (监察) nghĩa nhìn xem kỹ lưỡng. | Gương Hán-Việt | giám — trong tiếng Việt có \"giám sát\", \"giám định\", \"giám khảo\" đều dùng chữ 監 cùng âm. | Mở khoá kiến thức | Biết 鍳 giúp đọc văn bản cổ về đồ dùng cung đình và nghề đúc kim loại thời xưa.", "Tự nguyên_Xie": "鍳 là dị thể cổ của 鑑/鉴 (giám), chỉ chiếc gương đồng dùng để soi mặt trong thời cổ đại Trung Hoa. Không có glyph origin trong Wiktionary cho chữ này. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gương soi bằng đồng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鍳", "Unihan_Traditional (Chữ Phồn thể)": "鍳", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "giám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ cái gương soi hoặc động từ với nghĩa xem xét, rút kinh nghiệm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禔', '{"9000": "8243.0", "Chữ Trung Quốc": "禔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禔 | chỉ | tượng hình | phúc lành; chữ độc thể bộ 示 | 禔 thuộc bộ 示 (Thị — thần linh, lễ tế), chưa có phân tích thành phần hình thanh/hội ý từ Wiktionary. Chữ chỉ ghi nhận {{Han etym}} không có compound.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": bộ Thị (示 — thờ phụng thần linh) — cầu phúc, xin thần ban điều lành; âm \"chỉ\" \"chỉ bảo\" (chỉ dẫn điều tốt). | Gương Hán-Việt | chỉ — ít dùng trong tiếng Việt; gặp trong văn Hán cổ về lễ tế phong thần. | Mở khoá kiến thức | Biết 禔 giúp đọc văn bản cổ về lễ nghi cung đình và cầu phúc trong thư tịch Hán.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 禔 (zhī) nghĩa phúc lành, bình an, mang ý nghĩa cát tường. Thuộc bộ 示 liên quan đến thần linh và lễ tế. Wiktionary chỉ ghi {{Han etym}} không cung cấp phân tích cấu trúc. Chưa có nguồn học thuật đầy đủ về glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phúc", "Hạng Tần Suất (Jun Da)": "8243.0", "Tần Suất % (Jun Da)": "99.9995323095", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禔", "Unihan_Traditional (Chữ Phồn thể)": "禔", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ sự an khang hoặc tính từ bổ nghĩa cho danh từ trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穯', '{"9000": "8244.0", "Chữ Trung Quốc": "穯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 20 | nét | 穯 | sắc | tượng hình | giống lúa; bộ 禾 | 穯 thuộc bộ 禾 (Hoà — lúa), không có glyph origin hay phân tích thành phần từ nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": bộ Hoà (禾 — lúa) — một giống lúa đặc biệt; âm \"sắc\" \"thu hoạch\" (sắc bén như lưỡi hái gặt lúa). | Gương Hán-Việt | sắc — ít dùng trong tiếng Việt với nghĩa lúa; gặp nhiều hơn trong \"màu sắc\", \"sắc bén\". | Mở khoá kiến thức | Biết 穯 giúp đọc văn bản nông nghiệp cổ điển về các giống ngũ cốc.", "Tự nguyên_Xie": "穯 không có glyph origin trong Wiktionary và không có dữ liệu Mongo. Thuộc bộ 禾 (lúa), âm đọc là sè. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "穯", "Hạng Tần Suất (Jun Da)": "8244.0", "Tần Suất % (Jun Da)": "99.9995328262", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "穯", "Unihan_Traditional (Chữ Phồn thể)": "穯", "Pinyin_Xie": "se", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc gặt hái hoặc kết hợp thành từ ghép như thu sắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茿', '{"9000": "8245.0", "Chữ Trung Quốc": "茿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | thảo | biểu nghĩa | cỏ | 筑 | trúc | biểu âm | 茿 = 艸 (Thảo, biểu nghĩa: cỏ) + 筑 (Trúc, biểu âm); chữ hình thanh. Bộ 艸 cho biết đây là loài thực vật, phần 筑 gợi âm đọc zhú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trúc\": bộ Thảo (艸 — cỏ) + phần 筑 (trúc) — loài cỏ có âm đọc giống \"trúc\", chỉ xuất hiện trong tên ghép cây cổ 萹茿. | Gương Hán-Việt | trúc — trong tiếng Việt \"trúc\" thường chỉ cây tre/trúc (竹), chữ này khác bộ nhưng cùng âm. | Mở khoá kiến thức | Biết 茿 giúp nhận diện tên thực vật hiếm trong Kinh Thi và bản thảo dược cổ.", "Tự nguyên_Xie": "茿 (zhú) là chữ hình thanh: 艸 (cỏ) làm nghĩa phù, 筑 làm âm phù (abb2=y tức dùng phần rút gọn). Chỉ xuất hiện trong tổ hợp 萹茿 theo Wiktionary — một tên cây trong thư tịch cổ. Cấu trúc rõ ràng: {{Han compound|艸|筑|c1=s|c2=p|t1=grass|ls=psc|abb2=y}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "迿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 巩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹巩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茿", "Unihan_Traditional (Chữ Phồn thể)": "茿", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ chỉ tên loài cỏ hoặc dùng trong danh từ riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莂', '{"9000": "8246.0", "Chữ Trung Quốc": "莂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莂 | biệt | tượng hình | bộ 艸; chữ chưa rõ nghĩa trong Wiktionary | 莂 thuộc bộ 艸 (Thảo — cỏ), chưa có phân tích thành phần hình thanh/hội ý. Wiktionary chỉ ghi {{rfdef|zh}} — chưa có định nghĩa chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biệt\": bộ Thảo (艸 — cỏ) — một loài thực vật chưa xác định; âm \"biệt\" \"biệt lập\" (riêng rẽ, ít gặp). | Gương Hán-Việt | biệt — trong tiếng Việt có \"biệt thự\", \"biệt tài\", \"đặc biệt\" đều dùng âm biệt nhưng chữ 別, không phải 莂. | Mở khoá kiến thức | Biết 莂 giúp nhận diện chữ hiếm trong văn bản thực vật cổ chưa được giải nghĩa đầy đủ.", "Tự nguyên_Xie": "莂 (bié) thuộc bộ 艸, âm đọc bié. Wiktionary không cung cấp định nghĩa cụ thể ({{rfdef|zh}}) và không có glyph origin phân tích. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "莂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 别", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹别", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "别", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莂", "Unihan_Traditional (Chữ Phồn thể)": "莂", "Pinyin_Xie": "bié", "Âm Hán Việt_Xie": "biệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại giấy tờ, khế ước phân chia thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薃', '{"9000": "8247.0", "Chữ Trung Quốc": "薃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薃 | hào | tượng hình | Cyperus amuricus — loài cỏ cổ; bộ 艸 | 薃 thuộc bộ 艸 (Thảo — cỏ), chưa có phân tích thành phần hình thanh/hội ý từ nguồn học thuật. Chữ chỉ xuất hiện trong tổ hợp 薃葔.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": bộ Thảo (艸 — cỏ) — loài cỏ 薃葔, âm \"hào\" \"hào phóng\" (豪), mọc rậm rạp như cỏ dại. | Gương Hán-Việt | hào — trong tiếng Việt có \"hào kiệt\", \"hào quang\"; chữ 薃 khác với 豪 (hào — hào phóng). | Mở khoá kiến thức | Biết 薃 giúp nhận diện tên thực vật cổ trong bản thảo dược học Trung Hoa.", "Tự nguyên_Xie": "薃 (hào) chỉ xuất hiện trong tổ hợp 薃葔 theo Wiktionary, là tên một loài cỏ thuộc họ Cyperus (cói) trong thư tịch cổ. Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cyperus amuricus", "Hạng Tần Suất (Jun Da)": "8247.0", "Tần Suất % (Jun Da)": "99.9995343766", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 滈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹滈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "滈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薃", "Unihan_Traditional (Chữ Phồn thể)": "薃", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại cỏ tế tự hoặc cỏ dại ven nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襛', '{"9000": "8248.0", "Chữ Trung Quốc": "襛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 18 | nét | 襛 | nùng | tượng hình | y phục đẹp; bộ 衣; không có glyph origin | 襛 thuộc bộ 衣 (Y — áo), không có glyph origin hay phân tích thành phần từ nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nùng\": bộ Y (衣 — áo) — áo đẹp rực rỡ; âm \"nùng\" gợi \"nồng nàn\" (浓), màu sắc đậm đà. | Gương Hán-Việt | nùng — ít dùng trong tiếng Việt; gần với \"nồng\" (浓) cùng âm Hán-Việt. | Mở khoá kiến thức | Biết 襛 giúp đọc thơ văn cổ mô tả trang phục cung đình và vẻ đẹp hoa lệ.", "Tự nguyên_Xie": "襛 (nóng) không có glyph origin trong Wiktionary. Thuộc bộ 衣 liên quan đến y phục. Nghĩa ghi nhận: y phục đẹp, hoặc ánh sáng ấm áp. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh sáng; đầm ấm", "Hạng Tần Suất (Jun Da)": "8248.0", "Tần Suất % (Jun Da)": "99.9995348934", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 農", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤農", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "農", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襛", "Unihan_Traditional (Chữ Phồn thể)": "襛", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả trang phục lộng lẫy hoặc sự sum vầy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谻', '{"9000": "8249.0", "Chữ Trung Quốc": "谻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 11 | nét | 谻 | cấp | tượng hình | bộ 谷; chưa có định nghĩa rõ | 谻 thuộc bộ 谷 (Cốc — thung lũng), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi {{rfdef|zh}} — chưa có định nghĩa chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấp\": bộ Cốc (谷 — thung lũng) — một chữ hiếm liên quan đến địa hình thung lũng; âm \"cấp\" gợi \"gấp gáp\", chữ nghĩa còn bí ẩn. | Gương Hán-Việt | cấp — trong tiếng Việt \"cấp\" thường là chữ 給/級/急, không phải 谻. | Mở khoá kiến thức | Biết 谻 giúp nhận diện chữ cực hiếm trong văn bản địa lý cổ.", "Tự nguyên_Xie": "谻 (jí) thuộc bộ 谷 (thung lũng), âm đọc jí. Wiktionary không có định nghĩa ({{rfdef|zh}}) và không phân tích cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 丮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷丮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "谻", "Unihan_Traditional (Chữ Phồn thể)": "谻", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ địa hình khe núi hiểm trở trong văn tự cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魳', '{"9000": "8250.0", "Chữ Trung Quốc": "魳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魳 | trát | tượng hình | cá barracuda; bộ 魚 | 魳 thuộc bộ 魚 (Ngư — cá), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi đây là tên cá barracuda (cá nhọn đầu) đã lỗi thời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": bộ Ngư (魚 — cá) — tên cổ của cá barracuda, loài cá dữ nhanh nhẹn; âm \"trát\" gợi \"trát giấy\" (ra lệnh nhanh như cá lao). | Gương Hán-Việt | trát — trong tiếng Việt \"trát\" là văn bản lệnh quan, không liên quan đến cá; chữ 魳 dùng riêng trong ngữ cảnh ngư nghiệp cổ. | Mở khoá kiến thức | Biết 魳 giúp đọc văn bản ngư nghiệp và bản thảo động vật cổ điển Trung Hoa.", "Tự nguyên_Xie": "魳 (zā) là tên cổ (obsolete) của cá barracuda theo Wiktionary. Thuộc bộ 魚 (cá). Không có glyph origin phân tích. Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng quan thoại", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 帀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚帀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魳", "Unihan_Traditional (Chữ Phồn thể)": "魳", "Pinyin_Xie": "zā", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài cá cụ thể trong các tài liệu sinh học hoặc ẩm thực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵄', '{"9000": "8251.0", "Chữ Trung Quốc": "鵄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 至 | chí | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鵄 = 至 (Chí, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 cho biết đây là tên loài chim, phần 至 gợi âm đọc zhī/chī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": 至 (chí — đến, đạt đến) + 鳥 (điểu — chim) — con chim diều hâu lao xuống như mũi tên \"chí\" thẳng mục tiêu. | Gương Hán-Việt | chí — trong tiếng Việt \"chí\" hay gặp trong \"chí khí\", \"chí hướng\" (chữ 志); 鵄 là dạng cổ của chim diều hâu. | Mở khoá kiến thức | Biết 鵄 giúp đọc thơ ca cổ và văn bản tả loài chim săn mồi trong văn học Trung Hoa.", "Tự nguyên_Xie": "鵄 (zhī/chī) là chữ hình thanh: 鳥 (chim) làm nghĩa phù, 至 làm âm phù. Là dị thể của 鴟 (chim diều hâu/cú sừng). Cấu trúc rõ ràng theo Wiktionary: {{Han compound|至|鳥|ls=psc|c1=p|c2=s|t2=bird}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "锄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "至 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰至鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "至", "Unihan_Simplified (Chữ Giản thể)": "鵄", "Unihan_Traditional (Chữ Phồn thể)": "鵄", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loài chim săn mồi thuộc họ cú hoặc diều hâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穄', '{"9000": "8253.0", "Chữ Trung Quốc": "穄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 16 | nét | 禾 | hoà | biểu nghĩa | lúa | 祭 | sái | biểu âm | 穄 = 禾 (Hoà, biểu nghĩa: lúa) + 祭 (Sái, biểu âm); chữ hình thanh. Bộ 禾 cho biết đây là loài ngũ cốc, phần 祭 gợi âm đọc jì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": 禾 (hoà — lúa) + 祭 (sái/tế — tế lễ) — loài kê dùng trong lễ tế của người xưa, âm \"tế\" nhớ qua phần 祭 bên phải. | Gương Hán-Việt | tế — trong tiếng Việt \"tế\" gặp trong \"tế lễ\", \"tế thần\"; chữ 穄 chỉ dùng trong nông nghiệp cổ. | Mở khoá kiến thức | Biết 穄 giúp đọc văn bản nông nghiệp cổ điển và danh mục ngũ cốc trong kinh điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 穄 (jì) là chữ hình thanh: 禾 (lúa) làm nghĩa phù, 祭 làm âm phù. Cấu trúc rõ theo Wiktionary: {{Han compound|禾|祭|c1=s|c2=p|ls=psc}}. Nghĩa: kê bông (panicled millet) — một giống lúa kê. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một giống lúa)", "Hạng Tần Suất (Jun Da)": "8253.0", "Tần Suất % (Jun Da)": "99.9995379941", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 祭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾祭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穄", "Unihan_Traditional (Chữ Phồn thể)": "穄", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại cây lương thực thuộc họ lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穵', '{"9000": "8254.0", "Chữ Trung Quốc": "穵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 6 | nét | 穵 | oa | tượng hình | hố sâu; đào; bộ 穴 | 穵 thuộc bộ 穴 (Huyệt — hang lỗ), chưa có phân tích thành phần rõ ràng từ nguồn học thuật. Wiktionary ghi chú đây là dị thể của 挖 (đào).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": bộ Huyệt (穴 — hang) — đào hang, khoét lỗ sâu; âm \"oa\" gợi \"cái oa\" (nồi đất tròn, hình hố lõm). | Gương Hán-Việt | oa — ít dùng trong tiếng Việt hiện đại; âm \"oa\" gặp trong tên riêng và phiên âm Hán Nôm cổ. | Mở khoá kiến thức | Biết 穵 giúp đọc văn bản kiến trúc và thủy lợi cổ mô tả việc đào đắp.", "Tự nguyên_Xie": "Tiểu triện | 穵 (wā) thuộc bộ 穴 (hang lỗ). Theo Wiktionary có nghĩa hố sâu và là dị thể của 挖 (đào, khoét). Không có phân tích compound chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào; múc ra", "Hạng Tần Suất (Jun Da)": "8254.0", "Tần Suất % (Jun Da)": "99.9995385109", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + ㇠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴㇠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "穵", "Unihan_Traditional (Chữ Phồn thể)": "穵", "Pinyin_Xie": "wā", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động đào đất hoặc khoét lỗ sâu xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篛', '{"9000": "8255.0", "Chữ Trung Quốc": "篛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篛 | nhược | tượng hình | bẹ tre; bộ 竹; không có glyph origin | 篛 thuộc bộ 竹 (Trúc — tre), không có glyph origin hay phân tích thành phần từ nguồn học thuật. Chữ tạo muộn, chỉ có hình đại triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": bộ Trúc (竹 — tre) — bẹ lá tre mỏng yếu như \"nhược\" (yếu ớt); người xưa dùng bẹ tre gói bánh. | Gương Hán-Việt | nhược — trong tiếng Việt \"nhược\" gặp trong \"nhược điểm\", \"nhu nhược\"; chữ 篛 dùng riêng cho bẹ tre. | Mở khoá kiến thức | Biết 篛 giúp đọc văn bản thực vật học và kỹ thuật đan lát cổ Trung Hoa.", "Tự nguyên_Xie": "Đại triện | 篛 không có glyph origin trong Wiktionary. Thuộc bộ 竹 (tre), nghĩa là bẹ/vỏ cây tre (cuticle of bamboo). Chỉ có hình đại triện. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tre", "Hạng Tần Suất (Jun Da)": "8255.0", "Tần Suất % (Jun Da)": "99.9995390277", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 弱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮弱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篛", "Unihan_Traditional (Chữ Phồn thể)": "篛", "Pinyin_Xie": "ruò", "Âm Hán Việt_Xie": "nhược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ lá tre to dùng để lợp nón hoặc gói bánh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簑', '{"9000": "8256.0", "Chữ Trung Quốc": "簑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 簑 | ta | tượng hình | áo mưa cổ; bộ 竹; chữ tạo muộn | 簑 thuộc bộ 竹 (Trúc — tre), không có glyph origin hay phân tích thành phần. Chỉ có hình lục thư thông (Lục thư thông — biên soạn thời Minh). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": bộ Trúc (竹 — tre) — áo mưa bện bằng cỏ/tre; âm \"ta\" gợi \"che ta\" (che chắn mình khỏi mưa). | Gương Hán-Việt | ta — ít dùng trong tiếng Việt hiện đại; âm \"ta\" gặp trong đại từ nhân xưng và địa danh Hán Nôm. | Mở khoá kiến thức | Biết 簑 giúp đọc thơ điền viên cổ miêu tả cảnh nông dân mặc áo mưa dầm mưa.", "Tự nguyên_Xie": "Lục thư thông | 簑 không có glyph origin trong Wiktionary. Chỉ có hình từ Lục thư thông (thời Minh), cho thấy đây là chữ tạo muộn. Nghĩa: áo mưa làm từ cỏ hoặc tre. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mưa xơ dừa", "Hạng Tần Suất (Jun Da)": "4464.0", "Tần Suất % (Jun Da)": "99.852924501", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 衰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮衰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "蓑", "Unihan_Traditional (Chữ Phồn thể)": "簑", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại áo che mưa kết bằng lá cọ hoặc cỏ của người xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絭', '{"9000": "8257.0", "Chữ Trung Quốc": "絭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絭 | quyện | tượng hình | dây bện; buộc; bộ 糸 | 絭 thuộc bộ 糸 (Mịch — sợi tơ), chưa có phân tích thành phần hình thanh/hội ý. Wiktionary ghi chú đây là dây bện, dây buộc, và cũng là dị thể của 弮 (dây cung).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyện\": bộ Mịch (糸 — sợi tơ) — dây bện từ tơ; âm \"quyện\" gợi \"quấn quyện\" (cuốn chặt vào nhau như sợi dây). | Gương Hán-Việt | quyện — ít dùng trong tiếng Việt; gần với \"quyến\" (眷 — thương nhớ) cùng âm Hán-Việt. | Mở khoá kiến thức | Biết 絭 giúp đọc văn bản về đồ dùng cung đình và kỹ thuật dệt may cổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 絭 (juàn) theo Wiktionary có nghĩa dây bện (braided cord), dùng để buộc, và là dị thể của 弮 (dây cung). Thuộc bộ 糸 (sợi tơ). Không có phân tích compound chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bữa tiệc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "龹 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龹糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "絭", "Unihan_Traditional (Chữ Phồn thể)": "絭", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ sợi dây hoặc động từ chỉ việc buộc chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緅', '{"9000": "8258.0", "Chữ Trung Quốc": "緅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 緅 | trâu | tượng hình | lụa màu đỏ thẫm/tím; bộ 糸 | 緅 thuộc bộ 糸 (Mịch — sợi tơ), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary chỉ ghi {{rfdef|zh}} — chưa có định nghĩa chi tiết. Có hình bạch thư và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": bộ Mịch (糸 — lụa tơ) — loại lụa màu đỏ thẫm như màu \"trâu\" (sậm sịt); màu sang trọng trong y phục cung đình. | Gương Hán-Việt | trâu — ít dùng trong tiếng Việt với nghĩa màu vải; âm \"trâu\" phổ biến hơn là con trâu (牛水). | Mở khoá kiến thức | Biết 緅 giúp đọc mô tả y phục màu sắc trong lễ nghi cung đình Trung Hoa cổ.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 緅 (zōu) thuộc bộ 糸 (lụa tơ), nghĩa lụa màu đỏ thẫm hoặc tím theo các nguồn cổ. Wiktionary không cung cấp định nghĩa ({{rfdef|zh}}) và không phân tích cấu trúc. Có hình bạch thư. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ thẫm", "Hạng Tần Suất (Jun Da)": "8258.0", "Tần Suất % (Jun Da)": "99.999540578", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緅", "Unihan_Traditional (Chữ Phồn thể)": "緅", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "tưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ bổ nghĩa cho danh từ để chỉ màu sắc của vải vóc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緍', '{"9000": "8259.0", "Chữ Trung Quốc": "緍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 緍 | mân | tượng hình | dây câu cá; xâu tiền; bộ 糸 | 緍 là dị thể của 緡 (mín), thuộc bộ 糸 (Mịch — sợi tơ). Không có glyph origin từ nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mân\": bộ Mịch (糸 — sợi tơ) — sợi dây câu cá; âm \"mân\" gợi \"mẫn cán\" (nhanh nhẹn như sợi dây câu giật lên). | Gương Hán-Việt | mân — ít dùng trong tiếng Việt; gần với \"Mân\" (閩 — Phúc Kiến) cùng âm nhưng khác chữ. | Mở khoá kiến thức | Biết 緍 giúp đọc văn bản ngư nghiệp và kinh tế cổ về xâu tiền và câu cá.", "Tự nguyên_Xie": "緍 là dị thể của 緡 (mín) theo Wiktionary, nghĩa dây câu cá, dây buộc, hoặc xâu tiền bằng giấy/rơm. Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"缗\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 昏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹昏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𦈏", "Unihan_Traditional (Chữ Phồn thể)": "緍", "Pinyin_Xie": "mín", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ chỉ sợi dây hoặc lượng từ cho các xâu tiền cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罇', '{"9000": "8260.0", "Chữ Trung Quốc": "罇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 18 | nét | 缶 | phẫu | biểu nghĩa | bình gốm | 尊 | tôn | biểu âm | 罇 = 缶 (Phẫu, biểu nghĩa: bình gốm) + 尊 (Tôn, biểu âm); chữ hình thanh. Là dị thể của 樽 (bình rượu). Bộ 缶 cho biết đây là đồ đựng bằng gốm, phần 尊 gợi âm zūn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": 缶 (phẫu — bình gốm) + 尊 (tôn — tôn kính) — bình rượu tôn quý dùng trong lễ tế; âm \"tôn\" nhớ qua 尊 bên phải. | Gương Hán-Việt | tôn — trong tiếng Việt \"tôn\" gặp trong \"tôn trọng\", \"tôn giáo\"; chữ 罇 dùng riêng cho bình rượu cổ. | Mở khoá kiến thức | Biết 罇 giúp đọc văn bản lễ nghi tế tự và thơ về rượu trong văn học cổ điển.", "Tự nguyên_Xie": "罇 (zūn) là chữ hình thanh: 缶 (bình gốm) làm nghĩa phù, 尊 làm âm phù. Theo Wiktionary là dị thể của 樽 (bình rượu). Cấu trúc: {{Han compound|缶|尊|c1=s|c2=p|ls=psc}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "罇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "罇", "Unihan_Traditional (Chữ Phồn thể)": "罇", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng chứa rượu trong các buổi tiệc thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耑', '{"9000": "8261.0", "Chữ Trung Quốc": "耑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 而 | Số nét | 9 | nét | 耑 | đoan | tượng hình | đầu ngọn cây; đầu mút; tượng hình chữ độc thể | 耑 là chữ tượng hình (象形) theo Wiktionary: phần trên là lá và cành non của cây, phần dưới là rễ — hình ảnh hai đầu mút của cây. Hoặc là người với chân và tóc, biểu thị hai đầu/đầu mút. Chữ cổ, có hình từ giáp cốt văn đến tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoan\": tượng hình cây non với rễ và ngọn — hai đầu \"đoan\" (đầu mút); từ đây sinh ra chữ 端 (đoan trang, ngay thẳng — ngay từ gốc đến ngọn). | Gương Hán-Việt | đoan — trong tiếng Việt có \"đoan trang\", \"đoan chính\"; chữ 耑 là dạng cổ của 端. | Mở khoá kiến thức | Biết 耑 giúp hiểu nguồn gốc của 端 (đoan) và các từ như 端正, 端午 trong văn học cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 耑 (duān) là chữ tượng hình theo Wiktionary ({{liushu|p}}): lá và cành non ở trên, rễ cây ở dưới — biểu thị hai đầu mút (đỉnh và gốc). Có thể là hình người với chân và tóc. Là dạng gốc của 端 (đoan — đầu ngọn, đoan trang). Có hình từ giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1360.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (046) Nhi (1359)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Sơn (số 046 - núi non/viết dạng 屮 như cỏ mọc) ở trên chữ Nhi (số 1359 - rễ/râu dài/ 而). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Tượng hình). Chữ Đoan ban đầu vẽ hình một cái cây mầm mọc trên đất và rễ cắm xuống dưới. Nghĩa gốc là cái mầm, phần mới sinh. (Sau này chữ Đoan có bộ Lập thay thế).", "Nghĩa Tiếng Việt_Xie": "chú ý hết cả vào một việc; chỉ có một, duy nhất", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "耑", "Unihan_Traditional (Chữ Phồn thể)": "耑", "Pinyin_Xie": "duān", "Âm Hán Việt_Xie": "đoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ phần đầu của sự vật hoặc tính từ chỉ sự tập trung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艒', '{"9000": "8262.0", "Chữ Trung Quốc": "艒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艒 | mộ | tượng hình | loại thuyền nhỏ; bộ 舟; không có glyph origin | 艒 thuộc bộ 舟 (Chu — thuyền), không có glyph origin hay phân tích thành phần từ nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộ\": bộ Chu (舟 — thuyền) — loại thuyền nhỏ trên sông; âm \"mộ\" gợi \"chiều mộ\" (chiều tối), thuyền về bến lúc hoàng hôn. | Gương Hán-Việt | mộ — trong tiếng Việt \"mộ\" gặp trong \"mộ phần\", \"ngưỡng mộ\"; chữ 艒 dùng riêng cho loại thuyền cổ. | Mở khoá kiến thức | Biết 艒 giúp đọc văn bản địa lý và giao thông đường thủy cổ Trung Hoa.", "Tự nguyên_Xie": "艒 không có glyph origin trong Wiktionary và không có dữ liệu Mongo. Thuộc bộ 舟 (thuyền). Chưa có nguồn học thuật về cấu trúc chữ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蒒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 冒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟冒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艒", "Unihan_Traditional (Chữ Phồn thể)": "艒", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loại thuyền nhỏ di chuyển trên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豠', '{"9000": "8263.0", "Chữ Trung Quốc": "豠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 12 | nét | 豠 | trư | tượng hình | một giống lợn; bộ 豕 | 豠 thuộc bộ 豕 (Thỉ — lợn), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi đây là loài lợn (obs-std — chuẩn lỗi thời).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trư\": bộ Thỉ (豕 — lợn) — một giống lợn cổ; âm \"trư\" là âm Hán-Việt của chữ lợn, gặp trong \"trư bát giới\" (猪八戒). | Gương Hán-Việt | trư — trong tiếng Việt \"trư\" ít dùng độc lập; gặp trong \"trư bát giới\" (nhân vật Tây Du Ký). | Mở khoá kiến thức | Biết 豠 giúp đọc văn bản chăn nuôi và phân loại động vật trong bản thảo cổ Trung Hoa.", "Tự nguyên_Xie": "豠 (chú) theo Wiktionary là tên một loài lợn, đã lỗi thời. Thuộc bộ 豕 (lợn). Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豕 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豠", "Unihan_Traditional (Chữ Phồn thể)": "豠", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài lợn trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹎', '{"9000": "8264.0", "Chữ Trung Quốc": "蹎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 蹎 | chân | tượng hình | té ngã; ngã nhào; bộ 足 | 蹎 thuộc bộ 足 (Túc — chân), chưa có phân tích thành phần hình thanh/hội ý từ nguồn học thuật. Wiktionary ghi rõ nghĩa: ngã xuống, lật ngược; và (phương ngữ) chạy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chân\": bộ Túc (足 — chân) — chân vấp ngã, té nhào; âm \"chân\" chính chữ \"chân\" (bàn chân) trong tiếng Việt. | Gương Hán-Việt | chân — trong tiếng Việt \"chân\" là bộ phận cơ thể; chữ 蹎 (chân Hán-Việt) dùng trong văn cổ tả ngã. | Mở khoá kiến thức | Biết 蹎 giúp đọc mô tả hành động và tai nạn trong văn học cổ điển và thư tịch lịch sử.", "Tự nguyên_Xie": "蹎 (diān) theo Wiktionary có nghĩa ngã xuống (to fall down/over) trong văn học cổ điển, và (phương ngữ) chạy. Là dị thể của 顛 (điên — ngã, đỉnh đầu). Thuộc bộ 足 (chân). Không có glyph origin phân tích. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "té ngã, nghiêng ngả", "Hạng Tần Suất (Jun Da)": "8264.0", "Tần Suất % (Jun Da)": "99.9995436787", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹎", "Unihan_Traditional (Chữ Phồn thể)": "蹎", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ trạng thái bị vấp chân ngã hoặc lảo đảo không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辢', '{"9000": "8265.0", "Chữ Trung Quốc": "辢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辛 | Số nét | 14 | nét | 辢 | lạt | tượng hình | cay; dị thể của 辣; bộ 辛 | 辢 thuộc bộ 辛 (Tân — gian khổ, vị cay), là dị thể của 辣 (lạt — cay). Wiktionary ghi {{zh-see|辣|v}}. Chữ tạo muộn, chỉ có hình lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạt\": bộ Tân (辛 — cay đắng) — vị cay; âm \"lạt\" gợi ngược nghĩa — \"lạt\" tiếng Việt là nhạt, nhưng chữ này lại có nghĩa \"cay\"! | Gương Hán-Việt | lạt — thú vị khi trong tiếng Việt \"lạt\" nghĩa nhạt, nhưng Hán-Việt \"lạt\" (辢/辣) lại nghĩa cay. | Mở khoá kiến thức | Biết 辢 giúp nhận diện dị thể của 辣 trong văn bản cổ về ẩm thực và vị giác.", "Tự nguyên_Xie": "Lục thư thông | 辢 (là) là dị thể của 辣 theo Wiktionary ({{zh-see|辣|v}}). Thuộc bộ 辛 (gian khổ, cay đắng). Chỉ có hình lục thư thông — chữ tạo muộn. Cấu trúc không phân tích riêng vì là dị thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cay", "Hạng Tần Suất (Jun Da)": "2415.0", "Tần Suất % (Jun Da)": "98.317031329", "GavinGrover_Once (Chiết tự trực tiếp)": "束 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辛", "Unihan_Simplified (Chữ Giản thể)": "辣", "Unihan_Traditional (Chữ Phồn thể)": "辢", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ đứng sau phó từ chỉ mức độ để miêu tả vị cay của thức ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醻', '{"9000": "8266.0", "Chữ Trung Quốc": "醻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 21 | nét | 醻 | thù | tượng hình | thù lao; đáp lễ; dị thể của 酬; bộ 酉 | 醻 thuộc bộ 酉 (Dậu — rượu, bình rượu), là dị thể của 酬 (thù — đáp lễ, thù lao). Không có glyph origin từ nguồn học thuật. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": bộ Dậu (酉 — rượu) — nâng chén đáp lễ, đền thù; âm \"thù\" gợi \"thù lao\", \"báo thù\" — đều có nghĩa đáp trả. | Gương Hán-Việt | thù — trong tiếng Việt \"thù lao\" (酬劳), \"thù địch\" (仇敵); chữ 醻 là dị thể cổ của 酬 trong \"thù lao\". | Mở khoá kiến thức | Biết 醻 giúp nhận diện dị thể của 酬 và đọc văn bản lễ nghi ẩm thực cổ.", "Tự nguyên_Xie": "醻 là dị thể của 酬 (chóu/thù — đáp lễ, cạn chén chúc tụng, thù lao). Thuộc bộ 酉 (rượu). Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thù; như \"thù lao\" (gdhn)\n§ Cũng như chữ thù 酬.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 壽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉壽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醻", "Unihan_Traditional (Chữ Phồn thể)": "醻", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong văn cổ với nghĩa chúc rượu qua lại hoặc đền đáp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐍', '{"9000": "8267.0", "Chữ Trung Quốc": "鐍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐍 | quyết | tượng hình | then cài khóa; bộ 金; không có glyph origin | 鐍 thuộc bộ 金 (Kim — kim loại), không có glyph origin hay phân tích thành phần từ nguồn học thuật. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ Kim (金 — kim loại) — then cài khóa bằng kim loại; âm \"quyết\" gợi \"quyết định\" (dứt khoát như cài then chốt). | Gương Hán-Việt | quyết — trong tiếng Việt \"quyết\" gặp trong \"quyết định\", \"kiên quyết\"; chữ 鐍 dùng riêng cho then khóa kim loại. | Mở khoá kiến thức | Biết 鐍 giúp đọc văn bản kỹ thuật về đồ kim loại và cơ chế khóa trong văn hiến cổ.", "Tự nguyên_Xie": "Tiểu triện | 鐍 (jué) chỉ then cài khóa (hasp of a lock), thuộc bộ 金 (kim loại). Không có glyph origin trong Wiktionary và không có dữ liệu Mongo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ping", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 矞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金矞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐍", "Unihan_Traditional (Chữ Phồn thể)": "鐍", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ cái khóa kim loại hoặc động từ với nghĩa khóa chặt lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑮', '{"9000": "8268.0", "Chữ Trung Quốc": "鑮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 24 | nét | 鑮 | bác | tượng hình | loại nhạc khí bằng kim loại; bộ 金 | 鑮 thuộc bộ 金 (Kim — kim loại), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary chỉ ghi {{rfdef|zh}} — chưa có định nghĩa chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": bộ Kim (金 — kim loại) — đồ vật kim loại; âm \"bác\" gợi \"bác sĩ\" hay \"bác bỏ\", nhưng chữ này thuần về đồ kim loại cổ. | Gương Hán-Việt | bác — trong tiếng Việt \"bác\" thường là bác sĩ hoặc bác bỏ; chữ 鑮 dùng riêng trong ngữ cảnh đồ kim loại cổ. | Mở khoá kiến thức | Biết 鑮 giúp nhận diện tên đồ vật kim loại hiếm trong văn hiến âm nhạc và kỹ thuật cổ Trung Hoa.", "Tự nguyên_Xie": "鑮 (bó) thuộc bộ 金 (kim loại). Wiktionary không cung cấp định nghĩa ({{rfdef|zh}}) và không phân tích cấu trúc. Có thể liên quan đến nhạc khí hoặc đồ đồng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鮮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 薄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金薄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "薄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑮", "Unihan_Traditional (Chữ Phồn thể)": "鑮", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại nhạc khí gõ bằng đồng thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頳', '{"9000": "8269.0", "Chữ Trung Quốc": "頳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 16 | nét | 頳 | tranh | tượng hình | màu đỏ; bộ 頁; không có glyph origin | 頳 thuộc bộ 頁 (Hiệt — đầu người), chưa có phân tích thành phần từ nguồn học thuật. Không có glyph origin. Nghĩa màu đỏ (red).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": bộ Hiệt (頁 — đầu người) — mặt đỏ bừng, đỏ như người vừa tranh luận kịch liệt; âm \"tranh\" gợi \"tranh đua\" (mặt đỏ lên khi căng thẳng). | Gương Hán-Việt | tranh — trong tiếng Việt \"tranh\" gặp trong \"tranh luận\", \"tranh thủ\"; chữ 頳 dùng riêng để tả màu đỏ. | Mở khoá kiến thức | Biết 頳 giúp đọc văn bản mô tả màu sắc và vẻ mặt trong thơ văn và y học cổ.", "Tự nguyên_Xie": "頳 (chēng) chỉ màu đỏ. Thuộc bộ 頁 (đầu người). Không có glyph origin trong Wiktionary và không có dữ liệu Mongo. Chưa có nguồn học thuật về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ", "Hạng Tần Suất (Jun Da)": "8269.0", "Tần Suất % (Jun Da)": "99.9995467794", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "頳", "Unihan_Traditional (Chữ Phồn thể)": "頳", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "trinh, xanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ chỉ sắc đỏ hoặc động từ chỉ trạng thái đỏ mặt do ngượng ngùng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驈', '{"9000": "8270.0", "Chữ Trung Quốc": "驈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 22 | nét | 驈 | úc | tượng hình | ngựa đen bụng trắng; bộ 馬 | 驈 thuộc bộ 馬 (Mã — ngựa), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi rõ nghĩa: ngựa đen (black horse).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úc\": bộ Mã (馬 — ngựa) — ngựa đen; âm \"úc\" gợi \"u ám\" (màu đen tối), hình ảnh con ngựa đen huyền bí. | Gương Hán-Việt | úc — ít dùng trong tiếng Việt; gặp trong \"úc ức\" (bực bội) hoặc địa danh Úc (Australia). | Mở khoá kiến thức | Biết 驈 giúp đọc thơ ca cổ và văn bản về ngựa trong lịch sử quân sự Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 驈 (yù) theo Wiktionary chỉ ngựa đen (black horse), cụ thể hơn là ngựa đen với phần háng màu trắng. Thuộc bộ 馬. Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa đen có khoảng giữa háng màu trắng", "Hạng Tần Suất (Jun Da)": "8270.0", "Tần Suất % (Jun Da)": "99.9995472962", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 矞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬矞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驈", "Unihan_Traditional (Chữ Phồn thể)": "驈", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ loại ngựa đen có phần háng màu trắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髲', '{"9000": "8271.0", "Chữ Trung Quốc": "髲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 15 | nét | 髲 | bị | tượng hình | tóc giả; bộ 髟 | 髲 thuộc bộ 髟 (Tiêu — tóc dài), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi rõ nghĩa: tóc giả (wig).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bị\": bộ Tiêu (髟 — tóc dài) — tóc giả che phủ đầu; âm \"bị\" gợi \"bị che\" (đội tóc giả là che giấu tóc thật). | Gương Hán-Việt | bị — trong tiếng Việt \"bị\" là trợ từ bị động; chữ 髲 dùng riêng trong ngữ cảnh tóc và làm đẹp cổ. | Mở khoá kiến thức | Biết 髲 giúp đọc văn bản về trang phục và làm đẹp trong lịch sử cung đình Trung Hoa.", "Tự nguyên_Xie": "髲 (bì) theo Wiktionary nghĩa là tóc giả (wig), dùng trong văn học cổ điển. Thuộc bộ 髟 (tóc dài). Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc giả", "Hạng Tần Suất (Jun Da)": "8271.0", "Tần Suất % (Jun Da)": "99.999547813", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髲", "Unihan_Traditional (Chữ Phồn thể)": "髲", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bộ tóc giả của phụ nữ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱮', '{"9000": "8272.0", "Chữ Trung Quốc": "鱮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 24 | nét | 鱮 | tư | tượng hình | cá trắm bạc; bộ 魚 | 鱮 thuộc bộ 魚 (Ngư — cá), chưa có phân tích thành phần từ nguồn học thuật. Wiktionary ghi là đồng nghĩa của 鰱 (cá trắm bạc, silver carp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ Ngư (魚 — cá) — cá trắm bạc bơi thong thả trên mặt nước; âm \"tư\" gợi \"tư do\" (tự do như cá bơi lội). | Gương Hán-Việt | tư — trong tiếng Việt \"tư\" gặp trong \"tư tưởng\", \"tư nhân\"; chữ 鱮 dùng riêng trong ngữ cảnh ngư nghiệp cổ. | Mở khoá kiến thức | Biết 鱮 giúp đọc văn bản ngư nghiệp và phân loại cá trong bản thảo cổ điển Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 鱮 (xù) theo Wiktionary là đồng nghĩa của 鰱 (Hypophthalmichthys molitrix — cá trắm bạc, silver carp). Thuộc bộ 魚. Không có glyph origin phân tích. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá tự", "Hạng Tần Suất (Jun Da)": "8272.0", "Tần Suất % (Jun Da)": "99.9995483298", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 與", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚與", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "與", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱮", "Unihan_Traditional (Chữ Phồn thể)": "鱮", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ một loài cá nước ngọt giống cá mè. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麰', '{"9000": "8273.0", "Chữ Trung Quốc": "麰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 麥 | Số nét | 17 | nét | 麥 | mạch | biểu nghĩa | lúa mì | 牟 | mưu | biểu âm | 麰 = 麥 (Mạch, biểu nghĩa: lúa mì) + 牟 (Mưu, biểu âm); chữ hình thanh. Bộ 麥 cho biết đây là loại ngũ cốc họ lúa mì, phần 牟 gợi âm móu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mưu\": 麥 (mạch — lúa mạch) + 牟 (mưu — mưu kế) — lúa mạch được \"mưu\" người nông dân trồng cấy cẩn thận; âm \"mưu\" nhớ qua 牟 bên phải. | Gương Hán-Việt | mưu — trong tiếng Việt \"mưu\" gặp trong \"mưu kế\", \"mưu trí\"; chữ 麰 dùng riêng cho lúa mạch cổ. | Mở khoá kiến thức | Biết 麰 giúp đọc văn bản nông nghiệp cổ điển về các loại ngũ cốc trong kinh điển Trung Hoa.", "Tự nguyên_Xie": "麰 (móu) là chữ hình thanh: 麥 (lúa mì) làm nghĩa phù, 牟 làm âm phù. Nghĩa: lúa mạch (barley). Cấu trúc theo Wiktionary: {{Han compound|麥|牟|c1=s|c2=p|t1=wheat|ls=psc}}. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa mạch", "Hạng Tần Suất (Jun Da)": "8273.0", "Tần Suất % (Jun Da)": "99.9995488466", "GavinGrover_Once (Chiết tự trực tiếp)": "麥 + 牟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰麥牟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麥", "Unihan_Simplified (Chữ Giản thể)": "麰", "Unihan_Traditional (Chữ Phồn thể)": "麰", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cây lúa mạch, thường đi đôi với chữ mâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼄', '{"9000": "8274.0", "Chữ Trung Quốc": "鼄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 19 | nét | 鼄 | trư | tượng hình | nhện; dạng cổ của 蛛; bộ 黽 | 鼄 thuộc bộ 黽 (Mãnh — ếch nhái, côn trùng), là dạng cổ (archaic variant) của 蛛 (nhện). Theo Wiktionary: {{zh-see|蛛|a}}. Chưa có phân tích thành phần chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trư\": bộ Mãnh (黽 — côn trùng/ếch) — con nhện, dạng cổ của 蛛; âm \"trư\" gần với \"trụ\" (treo lơ lửng như nhện giăng tơ). | Gương Hán-Việt | trư — ít dùng độc lập trong tiếng Việt; \"trư\" thường gặp trong văn cổ chỉ nhện (蜘蛛 = tri trư). | Mở khoá kiến thức | Biết 鼄 giúp nhận diện dạng cổ của 蛛 (nhện) và tổ hợp 鼅鼄 trong văn bản cổ điển.", "Tự nguyên_Xie": "鼄 (zhū) là dạng cổ của 蛛 (nhện) theo Wiktionary ({{zh-see|蛛|a}}). Thuộc bộ 黽 (ếch, côn trùng). Xuất hiện trong tổ hợp 鼅鼄. Không có glyph origin phân tích riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tri chu 蜘蛛,鼅鼄)", "Hạng Tần Suất (Jun Da)": "8274.0", "Tần Suất % (Jun Da)": "99.9995493634", "GavinGrover_Once (Chiết tự trực tiếp)": "朱 + 黽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱朱黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鼄", "Unihan_Traditional (Chữ Phồn thể)": "鼄", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chu, thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ và kết hợp với chữ tri để tạo thành từ chỉ con nhện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼅', '{"9000": "8275.0", "Chữ Trung Quốc": "鼅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黽 | Số nét | 21 | nét | 鼅 | tri | tượng hình | nhện; dạng cổ của 蜘; bộ 黽 | 鼅 thuộc bộ 黽 (Mãnh — ếch nhái, côn trùng), là dạng cổ (archaic variant) của 蜘 (nhện). Theo Wiktionary: {{zh-see|蜘|a}}. Chưa có phân tích thành phần chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tri\": bộ Mãnh (黽 — côn trùng) — nửa trước của tên nhện cổ (鼅鼄); âm \"tri\" gợi \"tri thức\" (nhện \"biết\" giăng tơ phức tạp). | Gương Hán-Việt | tri — trong tiếng Việt \"tri\" gặp trong \"tri thức\", \"tri ân\"; chữ 鼅 dùng riêng trong tên nhện cổ 鼅鼄. | Mở khoá kiến thức | Biết 鼅 giúp nhận diện dạng cổ của 蜘 (nhện) và tổ hợp 鼅鼄 trong văn bản cổ điển.", "Tự nguyên_Xie": "鼅 (zhī) là dạng cổ của 蜘 (nhện) theo Wiktionary ({{zh-see|蜘|a}}). Thuộc bộ 黽 (ếch, côn trùng). Xuất hiện trong tổ hợp 鼅鼄. Không có glyph origin phân tích riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tri chu 蜘蛛,鼅鼄)", "Hạng Tần Suất (Jun Da)": "8275.0", "Tần Suất % (Jun Da)": "99.9995498801", "GavinGrover_Once (Chiết tự trực tiếp)": "知 + 黽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱知黽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "知", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黽", "Unihan_Simplified (Chữ Giản thể)": "鼅", "Unihan_Traditional (Chữ Phồn thể)": "鼅", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ và kết hợp với chữ trư để tạo thành từ chỉ con nhện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼖', '{"9000": "8276.0", "Chữ Trung Quốc": "鼖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 18 | nét | 鼖 | phần | tượng hình | trống lớn hai mặt dùng trong quân đội | 鼖 là chữ tượng hình độc lập, bộ 鼓 (Cổ, trống). Cấu trúc nội tại chưa được Wiktionary phân tích rõ; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": tiếng trống 鼖 vang lên phân (phần) chia chiến trường — trống lớn hai mặt gióng giục ba quân. | Gương Hán-Việt | phần — dùng trong văn cổ chỉ loại trống quân đặc biệt | Mở khoá kiến thức | Biết 鼖 giúp nhận ra nhóm chữ bộ 鼓 chỉ nhạc khí trống: 鼓, 鼙, 鼗.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận âm đọc (fén/fan4) và nghĩa ''trống quân hai mặt dài tám thước thời cổ'', không có phân tích tự hình. Chữ thuộc bộ 鼓 (cổ, trống), chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái trống lớn hai mặt dùng trong quân đội thời xưa", "Hạng Tần Suất (Jun Da)": "8276.0", "Tần Suất % (Jun Da)": "99.9995503969", "GavinGrover_Once (Chiết tự trực tiếp)": "卉 + 鼓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱卉鼓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼖", "Unihan_Traditional (Chữ Phồn thể)": "鼖", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại trống lớn thời cổ dùng để chỉ huy quân đội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眣', '{"9000": "8278.0", "Chữ Trung Quốc": "眣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眣 | chợt | tượng hình | mắt lác, mắt lồi | 眣 là chữ độc lập thuộc bộ 目 (Mục, mắt). Wiktionary không có phân tích cấu tạo; chưa xác định được hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chợt\": đôi mắt 眣 lồi ra chợt nhìn — mắt lác, mắt lồi bất thường. | Gương Hán-Việt | chợt — hiếm gặp trong tiếng Việt Hán-Việt, chủ yếu ghi trong từ điển cổ | Mở khoá kiến thức | Biết 眣 giúp nhận ra nhóm chữ bộ 目 chỉ trạng thái mắt: 眯, 眨, 眩, 瞟.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 眣. Bộ 目 (mục, mắt) gợi ý nghĩa liên quan đến mắt — mắt lồi hoặc nhìn lệch. Chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt lác", "Hạng Tần Suất (Jun Da)": "8278.0", "Tần Suất % (Jun Da)": "99.9995514305", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眣", "Unihan_Traditional (Chữ Phồn thể)": "眣", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động nháy mắt hoặc danh từ chỉ tật mắt lác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睎', '{"9000": "8279.0", "Chữ Trung Quốc": "睎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 目 | mục | biểu nghĩa | mắt | 希 | hy | biểu âm | hy vọng | 睎 = 目 (Mục, biểu nghĩa: mắt) + 希 (Hy, biểu âm); chữ hình thanh. Mắt (目) cho biết nghĩa nhìn ngóng; 希 cho âm đọc xī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hy\": đôi mắt (目) hy vọng (希) nhìn xa — 睎 là ngưỡng vọng, trông ngóng. | Gương Hán-Việt | hy — trong ''hy vọng'', ''hy hữu''; 睎 gợi mắt hướng về điều mong đợi | Mở khoá kiến thức | Biết 睎 mở ra trường nghĩa ngưỡng vọng bộ 目: 望, 瞻, 眺, 盼.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 睎 là hợp thể hình thanh: 目 biểu nghĩa ''mắt'', 希 biểu âm. Nghĩa là ngước nhìn ra xa, ngưỡng vọng, mong mỏi. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn ra xa; ngưỡng vọng, ngưỡng mộ", "Hạng Tần Suất (Jun Da)": "8279.0", "Tần Suất % (Jun Da)": "99.9995519473", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 希", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目希", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "希", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睎", "Unihan_Traditional (Chữ Phồn thể)": "睎", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để chỉ việc nhìn xa hoặc mong mỏi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞣', '{"9000": "8280.0", "Chữ Trung Quốc": "瞣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 瞣 | hoàn | tượng hình | tên riêng hoặc trạng thái mắt | 瞣 thuộc bộ 目 (Mục, mắt). Wiktionary không có phân tích cấu tạo chi tiết; chữ tạo muộn, chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": đôi mắt 瞣 tròn xoe (hoàn = tròn) — chữ cổ bộ 目 dùng làm tên riêng. | Gương Hán-Việt | hoàn — hiếm dùng; gần với 環 (hoàn, vòng tròn) | Mở khoá kiến thức | Biết 瞣 giúp nhận diện nhóm chữ bộ 目 dùng làm tên riêng trong văn bản cổ.", "Tự nguyên_Xie": "Không có phân tích tự hình trong Wiktionary. Bộ 目 (mục) gợi ý liên quan đến mắt. Nghĩa là tên riêng hoặc một trạng thái mắt không rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Huân", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 患", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目患", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "患", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞣", "Unihan_Traditional (Chữ Phồn thể)": "瞣", "Pinyin_Xie": "huan", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả trạng thái mắt chuyển động hoặc nhìn xung quanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矀', '{"9000": "8281.0", "Chữ Trung Quốc": "矀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 18 | nét | 矀 | mi | tượng hình | chữ cực hiếm bộ 目 | 矀 thuộc bộ 目 (Mục, mắt), 18 nét. Wiktionary không có phân tích cấu tạo; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": đôi mắt 矀 với lông mi (mi) rậm — chữ bộ 目 cực hiếm, âm méi gần 眉. | Gương Hán-Việt | mi — gần 眉 (mi, lông mày); dùng trong văn cổ | Mở khoá kiến thức | Biết 矀 giúp nhận diện nhóm chữ bộ 目 liên quan đến nét mặt và mắt.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 矀. Bộ 目 gợi liên quan đến mắt. Âm méi gần với 眉 (mi, lông mày). Có thể liên quan đến trạng thái mắt hoặc lông mày, nhưng chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "瀀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 微", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目微", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "微", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矀", "Unihan_Traditional (Chữ Phồn thể)": "矀", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhìn trộm hoặc quan sát kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硊', '{"9000": "8282.0", "Chữ Trung Quốc": "硊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硊 | vy | tượng hình | chữ cổ bộ 石 | 硊 thuộc bộ 石 (Thạch, đá), 11 nét. Wiktionary chỉ có stub {{Han etym}}, không phân tích cấu tạo chi tiết. Chưa xác định hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vy\": tảng đá 硊 sừng sững uy (vy) nghi — chữ bộ 石, nghĩa cổ liên quan đến đá. | Gương Hán-Việt | vy — hiếm gặp; bộ 石 gợi đá cứng, vững chắc | Mở khoá kiến thức | Biết 硊 giúp nhận ra nhóm chữ bộ 石 chỉ loại đá hoặc khoáng chất đặc biệt.", "Tự nguyên_Xie": "Wiktionary chỉ đánh dấu {{Han etym}} mà không cung cấp phân tích. Bộ 石 (thạch, đá) gợi ý liên quan đến đá hoặc khoáng vật. Nghĩa gốc không rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "犊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硊", "Unihan_Traditional (Chữ Phồn thể)": "硊", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả địa hình đá gập ghềnh hoặc hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碅', '{"9000": "8283.0", "Chữ Trung Quốc": "碅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碅 | quân | tượng hình | tên địa danh; bộ 石 | 碅 thuộc bộ 石 (Thạch, đá), 13 nét. Không có phân tích cấu tạo trong Wiktionary. Dùng làm tên địa danh (nước Tề/Qi thời cổ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": đá (石) vững như quân vương (quân) — 碅 dùng làm địa danh thời cổ. | Gương Hán-Việt | quân — gần 均 (quân, đều), 軍 (quân, đội quân); dùng trong địa danh cổ | Mở khoá kiến thức | Biết 碅 giúp đọc hiểu địa danh và tên riêng cổ dùng chữ bộ 石.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 碅. Bộ 石 (thạch) và âm jūn gần với 均 (quân, đều), 君 (quân, vua). Dùng chủ yếu làm tên địa danh, không rõ cấu tạo gốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 囷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石囷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碅", "Unihan_Traditional (Chữ Phồn thể)": "碅", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái đá xếp lởm chởm hoặc gập ghềnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磪', '{"9000": "8284.0", "Chữ Trung Quốc": "磪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磪 | thôi | tượng hình | núi cao hiểm trở | 磪 thuộc bộ 石 (Thạch, đá), 16 nét. Không có phân tích Wiktionary. Nghĩa là núi đá cao dựng đứng. Chưa xác định cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": đá (石) xô đổ (thôi) — 磪 là núi đá cao dựng đứng, hiểm trở. | Gương Hán-Việt | thôi — gần 催 (thôi, thúc giục), 崔 (thôi, núi cao); dùng tả địa hình núi đá | Mở khoá kiến thức | Biết 磪 giúp đọc hiểu văn cổ tả địa hình núi đá hiểm trở, nhóm âm thôi/cuī.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 磪. Âm cuī gần với 崔 (thôi, núi cao), 摧 (thôi, phá tan). Bộ 石 (thạch) + hình dáng gợi đá núi hiểm trở. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một ngọn núi cao; có nhiều mưa", "Hạng Tần Suất (Jun Da)": "8284.0", "Tần Suất % (Jun Da)": "99.9995545312", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 崔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石崔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "崔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磪", "Unihan_Traditional (Chữ Phồn thể)": "磪", "Pinyin_Xie": "cuī", "Âm Hán Việt_Xie": "thôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng núi cao vút, hiểm trở hoặc đá lởm chởm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礒', '{"9000": "8285.0", "Chữ Trung Quốc": "礒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礒 | nghĩ | tượng hình | chữ cổ bộ 石, nghĩa chưa rõ | 礒 thuộc bộ 石 (Thạch, đá), 18 nét. Wiktionary chỉ có thông tin âm đọc (yǐ/ngai5), không có phân tích cấu tạo hay nghĩa cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghĩ\": đứng trước tảng đá (石) mà nghi (nghĩ) ngại — 礒 chữ cổ bộ 石, nghĩa chưa được xác định. | Gương Hán-Việt | nghĩ — gần 擬 (nghĩ, phỏng theo); bộ 石 gợi đá rắn chắc | Mở khoá kiến thức | Biết 礒 giúp nhận diện nhóm chữ hiếm bộ 石 trong từ điển Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm yǐ (MC: ngai5 Quảng Đông) nhưng không có định nghĩa (rfdef). Bộ 石 gợi liên quan đến đá. Không rõ cấu tạo và nghĩa gốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "璒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 義", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石義", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "義", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礒", "Unihan_Traditional (Chữ Phồn thể)": "礒", "Pinyin_Xie": "yǐ", "Âm Hán Việt_Xie": "nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả địa hình nhiều đá gập ghềnh hoặc vách đá hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禞', '{"9000": "8286.0", "Chữ Trung Quốc": "禞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 14 | nét | 禞 | cáo | tượng hình | tên riêng hoặc chữ lễ nghi cổ, bộ 示 | 禞 thuộc bộ 示 (Thị, lễ/thần), 14 nét. Không có phân tích Wiktionary. Bộ 示 thường liên quan đến lễ nghi, thần linh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": bài cáo (cáo) trước thần (示) — 禞 chữ cổ bộ 示, dùng làm tên riêng hoặc trong lễ nghi. | Gương Hán-Việt | cáo — gần 告 (cáo, báo cáo), 誥 (cáo, sắc phong); bộ 示 gợi ngữ cảnh lễ nghi | Mở khoá kiến thức | Biết 禞 giúp nhận ra nhóm chữ bộ 示 liên quan đến tên riêng và lễ nghi cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 禞. Bộ 示 (thị) liên quan đến tế lễ, thần linh. Nghĩa được ghi là ''con gái'', khả năng dùng làm tên riêng. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禞", "Unihan_Traditional (Chữ Phồn thể)": "禞", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc cúng tế cầu phúc hoặc danh từ chỉ nghi lễ tế thần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秠', '{"9000": "8287.0", "Chữ Trung Quốc": "秠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 秠 | phi | tượng hình | một loại kê, ngũ cốc | 秠 thuộc bộ 禾 (Hòa, lúa/ngũ cốc), 10 nét. Wiktionary không phân tích cấu tạo cụ thể. Nghĩa là một loại kê (millet).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": lúa (禾) bay (phi) trong gió — 秠 là loại kê cổ, hạt nhỏ nhẹ như bay. | Gương Hán-Việt | phi — gần 飛 (phi, bay), 批 (phi, phê); bộ 禾 gợi ngũ cốc | Mở khoá kiến thức | Biết 秠 giúp nhận ra nhóm chữ bộ 禾 chỉ giống ngũ cốc đặc biệt trong văn cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm pī và nghĩa ''một loại kê'', không có phân tích tự hình. Bộ 禾 (hòa) cho biết liên quan đến ngũ cốc/lúa. Chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(cây kê)", "Hạng Tần Suất (Jun Da)": "8287.0", "Tần Suất % (Jun Da)": "99.9995560816", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秠", "Unihan_Traditional (Chữ Phồn thể)": "秠", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống kê đen hoặc lúa nếp hạt đen thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穙', '{"9000": "8288.0", "Chữ Trung Quốc": "穙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 穙 | bộc | tượng hình | chữ cổ bộ 禾, nghĩa không rõ | 穙 thuộc bộ 禾 (Hòa, lúa), 17 nét. Không có phân tích Wiktionary. Nghĩa gốc chưa được xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": lúa (禾) bộc trực (bộc) như cánh đồng mộc mạc — 穙 chữ cổ bộ 禾 nghĩa chưa rõ. | Gương Hán-Việt | bộc — gần 樸 (bộc, mộc mạc), 僕 (bộc, tôi tớ); bộ 禾 gợi lúa gạo | Mở khoá kiến thức | Biết 穙 giúp nhận ra nhóm chữ bộ 禾 hiếm trong từ điển cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 穙. Bộ 禾 gợi liên quan đến lúa hoặc ngũ cốc. Âm pú gần với 樸 (bộc, giản dị), 葡 (bồ, nho). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "穙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穙", "Unihan_Traditional (Chữ Phồn thể)": "穙", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ bụi lúa hoặc tính từ mô tả lúa mọc rậm rạp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穱', '{"9000": "8289.0", "Chữ Trung Quốc": "穱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 22 | nét | 穱 | chước | tượng hình | lúa chín sớm | 穱 thuộc bộ 禾 (Hòa, lúa), 22 nét. Wiktionary không phân tích cấu tạo cụ thể. Nghĩa là loại lúa/hạt chín sớm trong thời cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chước\": lúa (禾) chín nhanh chước (chước, vội) — 穱 là giống lúa chín sớm trong nông nghiệp cổ. | Gương Hán-Việt | chước — gần 酌 (chước, rót rượu), 卓 (trác, xuất sắc); bộ 禾 gợi lúa chín sớm | Mở khoá kiến thức | Biết 穱 giúp đọc hiểu văn nông nghiệp cổ về giống lúa chín sớm.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm zhuō/jué và nghĩa ''lúa chín sớm (archaic early-maturing grain)''. Không có phân tích tự hình. Bộ 禾 (hòa) xác nhận liên quan đến ngũ cốc. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "穱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 爵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾爵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穱", "Unihan_Traditional (Chữ Phồn thể)": "穱", "Pinyin_Xie": "zhuō", "Âm Hán Việt_Xie": "chước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này dùng làm động từ chỉ hành động gặt lúa hoặc danh từ chỉ lúa gặt sớm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竢', '{"9000": "8290.0", "Chữ Trung Quốc": "竢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 12 | nét | 立 | lập | biểu nghĩa | đứng | 矣 | hĩ | biểu âm | trợ từ | 竢 = 立 (Lập, biểu nghĩa: đứng) + 矣 (Hĩ, biểu âm); chữ hình thanh. Đứng (立) gợi đứng chờ đợi; 矣 cho âm đọc gần sì. Là dạng gốc của 俟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sĩ\": đứng (立) yên chờ mà thôi (矣) — 竢 là đứng đợi, chờ đến lúc. | Gương Hán-Việt | sĩ — gần 俟 (sĩ, chờ đợi); 竢 là dạng gốc, 俟 là dạng phổ biến sau này | Mở khoá kiến thức | Biết 竢 giúp hiểu nguồn gốc chữ 俟 và nhóm từ nghĩa ''chờ đợi'' trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 竢 là dạng gốc (original form) của 俟 (sì, chờ đợi). Hợp thể hình thanh: 立 biểu nghĩa ''đứng'', 矣 biểu âm. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竢", "Unihan_Traditional (Chữ Phồn thể)": "竢", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "sĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ đứng trước tân ngữ chỉ đối tượng hoặc thời gian được chờ đợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笍', '{"9000": "8291.0", "Chữ Trung Quốc": "笍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笍 | trụy | tượng hình | chữ cổ bộ 竹, nghĩa chưa rõ | 笍 thuộc bộ 竹 (Trúc, tre), 10 nét. Wiktionary chỉ có âm đọc (zhuì/ruì), không có định nghĩa (rfdef). Chưa xác định cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụy\": cây trúc (竹) rơi trụy (trụy) xuống đất — 笍 chữ cổ bộ 竹, nghĩa chưa xác định. | Gương Hán-Việt | trụy — gần 墜 (trụy, rơi xuống), 綴 (trụy, ghép lại); bộ 竹 gợi tre trúc | Mở khoá kiến thức | Biết 笍 giúp nhận diện nhóm chữ bộ 竹 hiếm trong từ điển cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm zhuì hoặc ruì, không có nghĩa cụ thể. Bộ 竹 (trúc) cho biết liên quan đến tre/trúc. Nghĩa gốc không rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giới", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笍", "Unihan_Traditional (Chữ Phồn thể)": "笍", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "trụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ chỉ các loại tre nhỏ hoặc vật dụng làm từ tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筩', '{"9000": "8292.0", "Chữ Trung Quốc": "筩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筩 | thúng | tượng hình | ống trúc, nhạc khí | 筩 thuộc bộ 竹 (Trúc, tre), 13 nét. Không có phân tích Wiktionary. Tiểu triện còn lưu. Nghĩa là ống trúc dùng làm nhạc khí hoặc dụng cụ câu cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thúng\": ống trúc (竹) rỗng như cái thúng — 筩 là ống tre, có thể dùng làm nhạc cụ. | Gương Hán-Việt | thúng — trong tiếng Việt ''thúng'' là vật đựng hình tròn; 筩 gợi hình ống trụ rỗng bằng tre | Mở khoá kiến thức | Biết 筩 giúp nhận ra nhóm chữ bộ 竹 chỉ nhạc cụ và dụng cụ làm từ ống tre.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary cho 筩. Bộ 竹 (trúc) xác nhận làm từ tre. Tiểu triện (hanziyuan) còn lưu hình dạng cổ. Nghĩa là ống trúc (bamboo pipe) dùng làm nhạc cụ hoặc móc câu. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ống trúc (một nhạc cụ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筩", "Unihan_Traditional (Chữ Phồn thể)": "筩", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật dụng có hình ống hoặc nhạc cụ bằng tre trúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簠', '{"9000": "8293.0", "Chữ Trung Quốc": "簠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簠 | phủ | tượng hình | đồ đựng xôi tế lễ bằng đồng | 簠 thuộc bộ 竹 (Trúc, tre/đồ đan), 18 nét. Wiktionary không phân tích cấu tạo chi tiết. Giáp cốt văn, kim văn và tiểu triện đều còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": cái phủ (phủ, kho) chứa lúa tế thần — 簠 là bình đồng vuông dùng đựng ngũ cốc dâng cúng. | Gương Hán-Việt | phủ — trong 簠簋 (phủ quỹ, bộ đồ tế lễ); gặp trong văn cổ và khảo cổ học | Mở khoá kiến thức | Biết 簠 mở ra từ vựng đồ tế khí: 簠簋 (bộ bình tế), 彝器 (đồ tế lễ đồng thau cổ).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi nhận âm fǔ và mô tả chi tiết: đồ tế lễ bằng đồng hình chữ nhật, có hai tay cầm, bốn chân và nắp đậy hình dạng giống thân bình, dùng để đựng ngũ cốc trong nghi lễ. Bộ 竹 có thể liên quan đến thời kỳ trước khi đúc đồng, dùng tre đan. Giáp cốt văn, kim văn, tiểu triện đều còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏ đựng xôi cúng", "Hạng Tần Suất (Jun Da)": "8293.0", "Tần Suất % (Jun Da)": "99.9995602159", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 盙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮盙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簠", "Unihan_Traditional (Chữ Phồn thể)": "簠", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại tế khí dùng trong các nghi lễ cúng tế cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粃', '{"9000": "8294.0", "Chữ Trung Quốc": "粃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粃 | tẻ | tượng hình | lúa lép, trấu rỗng | 粃 thuộc bộ 米 (Mễ, gạo), 10 nét. Không có phân tích Wiktionary. Cùng nghĩa và cách dùng với 秕 (bỉ, lúa lép).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẻ\": gạo tẻ (米) lép không đầy — 粃 là hạt gạo/lúa lép, trấu rỗng, không có giá trị dinh dưỡng. | Gương Hán-Việt | tẻ — trong ''gạo tẻ'' (tiếng Việt); 粃 chỉ hạt lép không đầy, tương phản với hạt chắc | Mở khoá kiến thức | Biết 粃 giúp đọc văn nông nghiệp cổ về chất lượng lúa gạo; cùng nhóm với 秕.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 粃. Bộ 米 (mễ) xác nhận liên quan đến gạo. Nghĩa là vỏ trấu rỗng, lúa lép — tức là hạt lúa không có nhân bên trong. Cùng ý với 秕 (bộ 禾). Chưa có nguồn học thuật về cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tẻ; như \"gạo tẻ\" (vhn) bỉ; như \"khang bỉ (lúa lép)\" (gdhn)\nCũng như chữ bỉ 秕.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粃", "Unihan_Traditional (Chữ Phồn thể)": "粃", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "bǐ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này dùng làm danh từ chỉ hạt lép hoặc tính từ chỉ sự tầm thường, xấu xa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粖', '{"9000": "8295.0", "Chữ Trung Quốc": "粖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 11 | nét | 粖 | mạt | tượng hình | chữ cổ bộ 米, nghĩa chưa rõ | 粖 thuộc bộ 米 (Mễ, gạo), 11 nét. Wiktionary chỉ có âm đọc (mò), không có định nghĩa (rfdef). Chưa xác định cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạt\": gạo (米) mạt cuối cùng — 粖 chữ cổ bộ 米, nghĩa chưa được xác định. | Gương Hán-Việt | mạt — gần 末 (mạt, cuối cùng), 茉 (mạt, hoa nhài); bộ 米 gợi gạo | Mở khoá kiến thức | Biết 粖 giúp nhận diện nhóm chữ bộ 米 hiếm trong từ điển Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm mò nhưng không có nghĩa cụ thể. Bộ 米 (mễ) gợi liên quan đến gạo/ngũ cốc. Âm mò gần với 末 (mạt, cuối), 磨 (ma, xay). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粖", "Unihan_Traditional (Chữ Phồn thể)": "粖", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ bột mịn hoặc động từ chỉ hành động nghiền nhỏ thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糓', '{"9000": "8296.0", "Chữ Trung Quốc": "糓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 16 | nét | 糓 | cốc | tượng hình | dị thể của 穀, ngũ cốc | 糓 thuộc bộ 米 (Mễ, gạo), 16 nét. Wiktionary ghi nhận là biến thể của 穀 (cốc, ngũ cốc). Không phân tích cấu tạo riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cốc\": gạo (米) cốc lõi nuôi người — 糓 là dị thể của 穀, chỉ ngũ cốc, lương thực. | Gương Hán-Việt | cốc — trong ''ngũ cốc'', ''cốc vật''; 糓 là dạng cổ thay thế cho 穀 | Mở khoá kiến thức | Biết 糓 giúp đọc văn cổ về nông nghiệp; cùng nghĩa và âm với 穀 (cốc).", "Tự nguyên_Xie": "Wiktionary xác nhận 糓 là dị thể của 穀 (gǔ, ngũ cốc). 穀 gốc có bộ 禾; 糓 chuyển sang bộ 米. Cùng nghĩa: lúa, ngũ cốc. Chữ cổ, chủ yếu gặp trong văn bản lịch sử. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "糓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "糓", "Unihan_Traditional (Chữ Phồn thể)": "糓", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ lương thực hoặc tính từ chỉ sự tốt lành trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糺', '{"9000": "8297.0", "Chữ Trung Quốc": "糺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 糺 | củ | tượng hình | dây chập ba lần, thu gộp lại | 糺 thuộc bộ 糸 (Mịch, sợi chỉ), 7 nét. Không có phân tích Wiktionary. Tiểu triện và Lục thư thông còn lưu. Nghĩa là dây chập, thu gộp, liên kết cùng nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củ\": sợi chỉ (糸) tự củ kết lại — 糺 là nhiều sợi chập vào nhau, liên kết thành nhóm. | Gương Hán-Việt | củ — trong ''củ soát'' (kiểm tra), ''纠纷'' (củ phân, tranh chấp); bộ 糸 gợi dây sợi | Mở khoá kiến thức | Biết 糺 giúp nhận ra gốc của 纠 (củ, vướng/sửa) và nhóm nghĩa liên kết, gộp lại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Không có nguồn Wiktionary cho 糺. Bộ 糸 (mịch, sợi chỉ) gợi nghĩa liên quan đến dây sợi xoắn lại. Âm jiū gần với 纠 (củ, vướng víu, sửa). Tiểu triện và Lục thư thông còn lưu hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây chập ba lần; thu lại, gộp lại", "Hạng Tần Suất (Jun Da)": "8297.0", "Tần Suất % (Jun Da)": "99.999562283", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "糺", "Unihan_Traditional (Chữ Phồn thể)": "糺", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này dùng làm động từ chỉ hành động liên kết, kiểm tra hoặc trừng phạt sai phạm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紭', '{"9000": "8298.0", "Chữ Trung Quốc": "紭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 紭 | hoành | tượng hình | dây đai mũ, dị thể của 紘 | 紭 thuộc bộ 糸 (Mịch, sợi chỉ), 11 nét. Wiktionary ghi nhận là dạng cũ của 紘 (hoành, dây đai). Không phân tích cấu tạo riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoành\": sợi chỉ (糸) hoành tráng buộc mũ — 紭 là dây đai mũ, dị thể của 紘. | Gương Hán-Việt | hoành — trong ''hoành tráng'', ''tứ hải chi nội giai huynh đệ''; 紭/紘 chỉ dây đai trên mũ quan | Mở khoá kiến thức | Biết 紭 giúp đọc văn cổ về lễ phục, mũ quan; cùng nghĩa với 紘.", "Tự nguyên_Xie": "Wiktionary xác nhận 紭 là dạng cổ (obs-std alt form) của 紘 (hóng, dây đai mũ). Bộ 糸 (mịch, sợi chỉ) gợi liên quan đến dây, sợi. Âm hóng gần với 宏 (hoành, rộng lớn). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "筭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 弘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹弘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紭", "Unihan_Traditional (Chữ Phồn thể)": "紭", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ dây mũ quan hoặc tính từ chỉ sự rộng lớn trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紾', '{"9000": "8299.0", "Chữ Trung Quốc": "紾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 紾 | chẩn | tượng hình | vặn xoắn, xoay cong | 紾 thuộc bộ 糸 (Mịch, sợi chỉ), 11 nét. Wiktionary không phân tích cấu tạo cụ thể. Nghĩa là vặn, xoay, xoắn lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": sợi chỉ (糸) vặn chẩn lại — 紾 là vặn xoắn, xoay cong, như bẻ sợi dây. | Gương Hán-Việt | chẩn — gần 診 (chẩn, khám bệnh), 枕 (chẩm, gối); 紾 dùng trong văn cổ tả hành động xoay vặn | Mở khoá kiến thức | Biết 紾 giúp đọc văn cổ Mạnh Tử (紾臂, vặn tay); nhóm chữ bộ 糸 chỉ hành động với sợi dây.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm zhěn/tiǎn và nghĩa ''vặn, xoay'' (archaic twist/turn). Bộ 糸 (mịch) gợi hành động xoắn sợi chỉ. Dùng trong văn cổ với nghĩa vặn tay (紾臂) hoặc xoắn xéo. Chưa có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vặn cong; xoay cong", "Hạng Tần Suất (Jun Da)": "8299.0", "Tần Suất % (Jun Da)": "99.9995633166", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紾", "Unihan_Traditional (Chữ Phồn thể)": "紾", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động vặn, xoắn hoặc làm cong một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絶', '{"9000": "8300.0", "Chữ Trung Quốc": "絶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絶 | tuyệt | tượng hình | cắt đứt, tuyệt đối; phồn thể/cổ thể của 绝 | 絶 là dạng phồn thể/cổ thể của 绝 (tuyệt), thuộc bộ 糸 (Mịch, sợi chỉ), 12 nét. Không có phân tích Wiktionary riêng. Nghĩa gốc là cắt đứt sợi dây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuyệt\": sợi chỉ (糸) bị cắt tuyệt — 絶 là đứt đoạn, tuyệt đối, xuất sắc tuyệt vời. | Gương Hán-Việt | tuyệt — trong ''tuyệt vời'', ''tuyệt đối'', ''tuyệt thực''; 絶/绝 dùng rộng rãi trong Hán-Việt | Mở khoá kiến thức | Biết 絶 mở ra hàng loạt từ Hán-Việt: tuyệt vời, tuyệt đối, tuyệt giao, tuyệt tác.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 絶. Là dạng truyền thống của 绝 (jué, tuyệt). Bộ 糸 (mịch, sợi chỉ) gốc: cắt đứt sợi dây → nghĩa mở rộng: tuyệt đối, không còn, kỳ diệu. Đồng âm Hán-Việt với 絕 (tuyệt) vẫn dùng trong tiếng Việt. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tuyệt đối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 色", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹色", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "色", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絶", "Unihan_Traditional (Chữ Phồn thể)": "絶", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "tuyệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước tính từ để biểu thị mức độ cao nhất hoặc làm động từ chỉ sự chấm dứt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綅', '{"9000": "8301.0", "Chữ Trung Quốc": "綅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綅 | thâm | tượng hình | chỉ sợi, sợi tơ | 綅 thuộc bộ 糸 (Mịch, sợi chỉ), 13 nét. Wiktionary chỉ có định nghĩa không hoàn chỉnh (rfdef). Nghĩa là chỉ sợi/thread.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thâm\": sợi chỉ (糸) thâm (thâm sâu) — 綅 là sợi chỉ đặc biệt, dùng trong văn cổ. | Gương Hán-Việt | thâm — gần 深 (thâm, sâu), 侵 (thâm, xâm lấn); bộ 糸 gợi sợi chỉ | Mở khoá kiến thức | Biết 綅 giúp nhận diện nhóm chữ bộ 糸 chỉ các loại chỉ sợi đặc biệt.", "Tự nguyên_Xie": "Wiktionary có stub {{Han etym}} nhưng thiếu phần phát âm tiếng Quan Thoại (rfp|cmn). Bộ 糸 (mịch) gợi liên quan đến sợi chỉ/vải. Nghĩa đơn giản là sợi chỉ/dây sợi. Chưa có phân tích tự hình chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỉ sợi", "Hạng Tần Suất (Jun Da)": "8301.0", "Tần Suất % (Jun Da)": "99.9995643501", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "綅", "Unihan_Traditional (Chữ Phồn thể)": "綅", "Pinyin_Xie": "qīn", "Âm Hán Việt_Xie": "xâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại chỉ sợi hoặc dây tơ nhỏ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繂', '{"9000": "8302.0", "Chữ Trung Quốc": "繂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繂 | suất | tượng hình | dây thừng to, trục cuộn | 繂 thuộc bộ 糸 (Mịch, sợi chỉ), 17 nét. Wiktionary chỉ có âm đọc, không có định nghĩa (rfdef). Nghĩa theo từ điển Việt-Hán là dây thừng to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suất\": sợi (糸) suất dẫn — 繂 là dây thừng to, dây dẫn lớn. | Gương Hán-Việt | suất — gần 率 (suất, tỉ lệ, dẫn đầu), 帥 (suất, thống soái); 繂 là dây thừng to | Mở khoá kiến thức | Biết 繂 giúp nhận ra nhóm chữ bộ 糸 chỉ các loại dây thừng và sợi lớn.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm lǜ (Quảng Đông: leot6), không có định nghĩa. Theo từ điển Hán-Việt cổ, nghĩa là dây thừng to hoặc trục cuộn sợi. Bộ 糸 (mịch) xác nhận liên quan đến sợi dây. Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "suất; như \"suất chỉ (trục cuộn)\" \n (Danh) Dây thừng to.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 率", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹率", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "率", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繂", "Unihan_Traditional (Chữ Phồn thể)": "繂", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "luật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại dây thừng lớn dùng để buộc hoặc kéo đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繋', '{"9000": "8303.0", "Chữ Trung Quốc": "繋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 17 | nét | 繋 | hệ | tượng hình | buộc, nối kết, gắn lại | 繋 là dạng cổ/biến thể của 繫/系 (hệ), thuộc bộ 糸 (Mịch, sợi chỉ), 17 nét. Không có phân tích Wiktionary riêng. Nghĩa là buộc, kết nối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hệ\": sợi (糸) hệ buộc lại — 繋 là gắn kết, nối liền, như sợi dây trói buộc. | Gương Hán-Việt | hệ — trong ''hệ thống'', ''quan hệ'', ''liên hệ''; 繋 là dạng cổ của 繫 | Mở khoá kiến thức | Biết 繋 giúp đọc văn cổ về liên kết, ràng buộc; cùng nghĩa với 繫 (hệ).", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 繋. Là biến thể của 繫 (jì/xì, buộc/hệ thống). Bộ 糸 (mịch) gợi hành động buộc dây. Âm jì đọc theo nghĩa ''buộc, cột'' (khác xì = hệ thống). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hệ (gdhn)", "Hạng Tần Suất (Jun Da)": "8303.0", "Tần Suất % (Jun Da)": "99.9995653837", "GavinGrover_Once (Chiết tự trực tiếp)": "軗 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱軗糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "繋", "Unihan_Traditional (Chữ Phồn thể)": "繋", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "hệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành vi buộc, trói hoặc kết nối các sự vật lại với nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繣', '{"9000": "8304.0", "Chữ Trung Quốc": "繣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繣 | hoạch | tượng hình | dây thừng, cố chấp, gian trá | 繣 thuộc bộ 糸 (Mịch, sợi chỉ), 18 nét. Wiktionary ghi nhận âm huà/jiǎng và nghĩa ''dây sợi buộc đồ vật; dùng trong 緯繣 (cố chấp)''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạch\": sợi (糸) hoạch định cứng đầu — 繣 vừa là dây buộc, vừa tả tính cố chấp. | Gương Hán-Việt | hoạch — gần 劃 (hoạch, vạch ra), 畫 (hoạch, vẽ); 繣 dùng trong 緯繣 (gian trá) | Mở khoá kiến thức | Biết 繣 giúp đọc từ cổ 緯繣 (cố chấp, gian trá) và nhóm chữ bộ 糸 chỉ dây sợi.", "Tự nguyên_Xie": "Wiktionary ghi nhận: 繣 là dây/sợi buộc đồ vật; dùng trong từ ghép 緯繣 (gian trá, cố chấp). Bộ 糸 (mịch) xác nhận liên quan đến dây sợi. Không có phân tích tự hình chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cố chấp; gian trá", "Hạng Tần Suất (Jun Da)": "8304.0", "Tần Suất % (Jun Da)": "99.9995659005", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 畫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹畫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繣", "Unihan_Traditional (Chữ Phồn thể)": "繣", "Pinyin_Xie": "huà", "Âm Hán Việt_Xie": "hoạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả tính cách cố chấp, gian trá hoặc động từ chỉ sự đứt dây đàn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罙', '{"9000": "8305.0", "Chữ Trung Quốc": "罙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 8 | nét | 罙 | mịch | tượng hình | sâu, lưới sâu | 罙 thuộc bộ 网 (Võng, lưới), 8 nét. Không có phân tích Wiktionary. Tiểu triện còn lưu. Nghĩa là sâu (deep).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": lưới (网) mịch tìm sâu — 罙 là sâu thẳm, như lưới chìm sâu dưới nước. | Gương Hán-Việt | mịch — gần 覓 (mịch, tìm kiếm), 密 (mật, dày đặc); 罙 gợi chiều sâu | Mở khoá kiến thức | Biết 罙 giúp nhận ra nhóm chữ bộ 网 chỉ chiều sâu và ẩn khuất.", "Tự nguyên_Xie": "Tiểu triện | Không có nguồn Wiktionary cho 罙. Bộ 网 (võng, lưới) gợi hình ảnh lưới buông sâu xuống. Tiểu triện còn lưu hình. Âm mí gần với 迷 (mê, lạc), 密 (mật, dày). Chưa có nguồn học thuật về cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "罙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺳ + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺳木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺳", "Unihan_Simplified (Chữ Giản thể)": "罙", "Unihan_Traditional (Chữ Phồn thể)": "罙", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn chỉ hành động đi sâu vào bên trong hoặc bao trùm lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罥', '{"9000": "8306.0", "Chữ Trung Quốc": "罥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 12 | nét | 网 | võng | biểu nghĩa | lưới | 肙 | biểu âm | 罥 = 网 (Võng, biểu nghĩa: lưới) + 肙 (biểu âm); chữ hình thanh. Lưới (网) cho biết nghĩa bắt bằng lưới, vướng lưới; 肙 cho âm juàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyến\": lưới (网) quyến rũ vướng mắc — 罥 là vướng bẫy lưới, ngăn trở. | Gương Hán-Việt | quyến — gần 眷 (quyến, thân thuộc), 卷 (quyển, cuốn); 罥 dùng trong thơ cổ tả chướng ngại | Mở khoá kiến thức | Biết 罥 giúp đọc thơ cổ tả thiên nhiên hoang vu; nhóm chữ bộ 网 chỉ bẫy và lưới.", "Tự nguyên_Xie": "Theo Wiktionary, 罥 là hợp thể hình thanh: 网 biểu nghĩa ''lưới'', 肙 biểu âm. Nghĩa: cản trở, vướng vào, treo; cũng là lưới bắt chim nhỏ (đồng nghĩa 羂). Trích Bào Chiếu thế kỷ V: ''dây sắn rừng hoang vướng khắp lối đi''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngăn trở", "Hạng Tần Suất (Jun Da)": "8306.0", "Tần Suất % (Jun Da)": "99.9995669341", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 肙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒肙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罥", "Unihan_Traditional (Chữ Phồn thể)": "罥", "Pinyin_Xie": "juàn", "Âm Hán Việt_Xie": "quyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc bị mắc kẹt, vướng víu hoặc danh từ chỉ cái bẫy chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罼', '{"9000": "8307.0", "Chữ Trung Quốc": "罼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 15 | nét | 罼 | tất | tượng hình | lưới dài cán bắt chim, thỏ | 罼 thuộc bộ 网 (Võng, lưới), 15 nét. Wiktionary ghi nhận là dạng biến thể của 畢 (tất, lưới có cán dài). Không phân tích cấu tạo riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": tất (tất, lưới) bắt chim tất cả — 罼 là lưới cán dài dùng để tóm gọn chim thú. | Gương Hán-Việt | tất — gần 畢 (tất, hoàn thành/lưới); 罼 là dạng biến thể của 畢 | Mở khoá kiến thức | Biết 罼 giúp đọc văn cổ về săn bắt; cùng nghĩa với 畢 trong ngữ cảnh dụng cụ săn.", "Tự nguyên_Xie": "Theo Wiktionary, 罼 là dạng thay thế của 畢 (bì/tất) với nghĩa ''lưới có cán dài để bắt chim và thỏ''. Bộ 网 (võng, lưới) xác nhận là dụng cụ săn bắt. Chữ cổ, ít dùng ngoài văn bản lịch sử. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 畢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒畢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罼", "Unihan_Traditional (Chữ Phồn thể)": "罼", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại lưới hoặc vợt dùng để săn bắt chim muông thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羜', '{"9000": "8308.0", "Chữ Trung Quốc": "羜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 11 | nét | 羊 | dương | biểu nghĩa | cừu | 宁 | trữ | biểu âm | 羜 = 羊 (Dương, biểu nghĩa: cừu) + 宁 (Trữ, biểu âm); chữ hình thanh. Cừu (羊) cho biết đây là con cừu/dê; 宁 (trữ) cho âm zhù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": cừu (羊) nhỏ trữ (trữ, dự trữ) để nuôi — 羜 là con dê/cừu non, dê con. | Gương Hán-Việt | trữ — gần 貯 (trữ, tích trữ), 宁 (trữ/ninh); 羜 chỉ con dê con trong văn cổ | Mở khoá kiến thức | Biết 羜 giúp đọc văn cổ về chăn nuôi và tế lễ; nhóm chữ bộ 羊 chỉ các loài cừu.", "Tự nguyên_Xie": "Theo Wiktionary, 羜 là hợp thể hình thanh: 羊 biểu nghĩa ''cừu'', 宁 biểu âm. Nghĩa là con dê/cừu non (lamb). Chữ cổ, dùng trong văn ngôn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chiên, con dê non", "Hạng Tần Suất (Jun Da)": "8308.0", "Tần Suất % (Jun Da)": "99.9995684844", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羜", "Unihan_Traditional (Chữ Phồn thể)": "羜", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ con dê non hoặc chiên non dưới năm tháng tuổi trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翭', '{"9000": "8309.0", "Chữ Trung Quốc": "翭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 15 | nét | 翭 | hầu | tượng hình | lông vũ, bộ lông cứng của mũi tên | 翭 thuộc bộ 羽 (Vũ, lông vũ), 15 nét. Wiktionary chỉ có âm đọc (hóu), không có định nghĩa (rfdef). Bộ 羽 gợi liên quan đến lông chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": lông vũ (羽) của hầu tước — 翭 chữ cổ bộ 羽, nghĩa liên quan đến lông chim. | Gương Hán-Việt | hầu — gần 侯 (hầu, tước vị), 喉 (hầu, họng); bộ 羽 gợi lông vũ | Mở khoá kiến thức | Biết 翭 giúp nhận ra nhóm chữ bộ 羽 chỉ các loại lông vũ đặc biệt.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm hóu (Quảng Đông: hau4), không có nghĩa. Bộ 羽 (vũ, lông chim) gợi liên quan đến lông vũ, cánh. Âm hóu gần với 喉 (hầu, họng), 猴 (hầu, khỉ). Có thể liên quan đến lông đuôi mũi tên hoặc lông vũ đặc biệt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "筭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羽侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翭", "Unihan_Traditional (Chữ Phồn thể)": "翭", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ lông chim non hoặc động từ chỉ việc tính toán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耮', '{"9000": "8310.0", "Chữ Trung Quốc": "耮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 18 | nét | 耒 | lồi | biểu nghĩa | cán cày, dụng cụ nông nghiệp | 勞 | lao | biểu âm | lao động | 耮 = 耒 (Lồi, biểu nghĩa: dụng cụ nông nghiệp) + 勞 (Lao, biểu âm); chữ hình thanh. Cán cày (耒) cho biết đây là nông cụ; 勞 cho âm lào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": dụng cụ nông nghiệp (耒) lao động (lao) san đất — 耮 là bừa san đất sau khi cày. | Gương Hán-Việt | lao — gần 勞 (lao, vất vả), 牢 (lao, chuồng); 耮 là nông cụ san phẳng ruộng | Mở khoá kiến thức | Biết 耮 giúp đọc văn cổ về nông cụ; nhóm chữ bộ 耒 chỉ các dụng cụ nông nghiệp.", "Tự nguyên_Xie": "Theo Wiktionary, 耮 là hợp thể hình thanh: 耒 biểu nghĩa ''dụng cụ nông nghiệp'', 勞 biểu âm. Nghĩa là một loại nông cụ dùng để san phẳng đất sau khi bừa (smoothing harrow). Dùng trong nông nghiệp cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Rui", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耒 + 勞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耒勞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耒", "Unihan_Simplified (Chữ Giản thể)": "耮", "Unihan_Traditional (Chữ Phồn thể)": "耮", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nông cụ hoặc động từ chỉ hoạt động bừa đất trong nông nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聸', '{"9000": "8311.0", "Chữ Trung Quốc": "聸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 19 | nét | 聸 | đam | tượng hình | chữ cổ bộ 耳, nghĩa chưa rõ | 聸 thuộc bộ 耳 (Nhĩ, tai), 19 nét. Wiktionary chỉ có âm đọc (dān/daam1), không có định nghĩa (rfdef). Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": tai (耳) đam mê lắng nghe — 聸 chữ cổ bộ 耳, nghĩa chưa xác định. | Gương Hán-Việt | đam — gần 擔 (đam, gánh nặng), 單 (đơn, đơn độc); bộ 耳 gợi tai, âm thanh | Mở khoá kiến thức | Biết 聸 giúp nhận diện nhóm chữ bộ 耳 hiếm trong từ điển Hán cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận âm dān (Quảng Đông: daam1), không có nghĩa cụ thể. Bộ 耳 (nhĩ, tai) gợi liên quan đến tai hoặc âm thanh. Tiểu triện còn lưu. Âm dān gần với 單 (đơn, đơn độc), 擔 (đam, gánh). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "聸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聸", "Unihan_Traditional (Chữ Phồn thể)": "聸", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả đặc điểm tai chảy dài của người có phúc tướng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肸', '{"9000": "8312.0", "Chữ Trung Quốc": "肸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肸 | hất | tượng hình | vang dậy, lan tỏa | 肸 thuộc bộ 肉 (Nhục, thịt/cơ thể), 8 nét. Wiktionary có ghi chú bình luận từ Thuyết Văn: ''从十从䏌'' — từ 十 và 䏌. Tiểu triện còn lưu. Cấu tạo phức tạp, chưa đồng thuận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hất\": âm thanh hất (hất, phát ra) vang dậy khắp — 肸 là lan tỏa, vang dội. | Gương Hán-Việt | hất — gần 屹 (ngật, sừng sững), 迄 (ngật, đến); 肸 dùng tả âm thanh hoặc hương lan tỏa | Mở khoá kiến thức | Biết 肸 giúp đọc thơ cổ tả âm nhạc và hương thơm lan tỏa; bộ 肉 trong nghĩa rung chấn.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary có ghi chú từ Thuyết Văn (dạng comment): 从十从䏌 (từ thập và 䏌). 䏌 có thể đồng âm 佾 (nhất, hàng múa cúng). Nghĩa là lan tỏa, vang dậy, mỉm cười. Tiểu triện còn lưu hình. Cấu tạo chưa được phân tích hoàn chỉnh — chưa có nguồn học thuật rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vang dậy", "Hạng Tần Suất (Jun Da)": "8312.0", "Tần Suất % (Jun Da)": "99.9995705516", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "肸", "Unihan_Traditional (Chữ Phồn thể)": "肸", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ mô tả âm thanh vang dội hoặc hương thơm lan tỏa khắp nơi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胹', '{"9000": "8313.0", "Chữ Trung Quốc": "胹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胹 | nhi | tượng hình | thịt nấu chín | 胹 là chữ ít phân tích được thành phần rõ ràng; chưa có nguồn hội ý hay hình thanh được xác nhận. Dùng như tượng hình tự chỉ thịt đã qua lửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhi\": hình ảnh miếng thịt (肉) được đun sôi kỹ cho đến khi chín mềm — chữ hiếm chỉ dùng trong văn cổ. | Gương Hán-Việt | nhi — ít xuất hiện trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 胹 giúp đọc hiểu văn ngôn Trung Hoa về ẩm thực và bếp núc thời cổ.", "Tự nguyên_Xie": "Chữ 胹 (ér) chỉ thịt đã nấu chín hoặc hành động đun sôi. Wiktionary ghi nhận đây là chữ cổ, xuất hiện trong từ điển lịch sử với nghĩa ''cooked; done; to boil''. Chưa có dữ liệu glyph origin có cấu trúc rõ ràng; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đã nấu chín", "Hạng Tần Suất (Jun Da)": "8313.0", "Tần Suất % (Jun Da)": "99.9995710683", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 而", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月而", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "而", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胹", "Unihan_Traditional (Chữ Phồn thể)": "胹", "Pinyin_Xie": "ér", "Âm Hán Việt_Xie": "nhi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước danh từ chỉ thức ăn để diễn tả việc nấu nướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脣', '{"9000": "8314.0", "Chữ Trung Quốc": "脣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 辰 | thìn | biểu âm | cung thứ 5 trong 12 địa chi; âm thanh gợi âm chún | 肉 | nhục | biểu nghĩa | thịt, mô mềm | 脣 = 辰 (Thìn, biểu âm) + 肉 (Nhục, biểu nghĩa: mô mềm); chữ hình thanh. 辰 cho âm đọc, 肉 (月) chỉ đây là bộ phận thịt mềm của cơ thể — đôi môi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thần\": 辰 (Thìn — địa chi con rồng) + 月/肉 (nhục — thịt) → đôi môi mềm mại như da thịt, vận động như rồng uốn lượn khi nói chuyện. | Gương Hán-Việt | thần — trong \"thần khẩu\" (lời nói từ miệng); môi trong y học cổ | Mở khoá kiến thức | Biết 脣 (thần) giúp đọc văn ngôn về giải phẫu cổ và hiểu từ ghép như 脣亡齒寒 (thần vong xỉ hàn — môi mất thì răng lạnh).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 脣 là dạng truyền thống của 唇 (môi). Theo Wiktionary, chữ được cấu tạo theo kiểu hình thanh: 辰 (thìn) cho âm, 肉 (nhục) biểu nghĩa ''mô thịt mềm''. Hình tiểu triện còn lưu lại trên hanziyuan.net cho thấy cấu trúc này khá ổn định từ thời tiền Tần. Đôi môi (脣) là bộ phận thịt mềm bao quanh miệng, liên quan mật thiết đến phát âm và ăn uống. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1236.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thần (255) Nhục (130)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thần (số 255 - can Thìn/chỉ âm) ở trên bộ Nhục (số 130 - thịt/viết dạng 月 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thần chỉ âm, bộ Nhục chỉ ý. Thần là phần da thịt xăm ngoài miệng, cái môi (thần hở răng lạnh).", "Nghĩa Tiếng Việt_Xie": "đôi môi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辰 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辰", "Unihan_Simplified (Chữ Giản thể)": "脣", "Unihan_Traditional (Chữ Phồn thể)": "脣", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "than", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ làm chủ ngữ hoặc tân ngữ trong câu để chỉ bộ phận môi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腬', '{"9000": "8315.0", "Chữ Trung Quốc": "腬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 肉 | nhục | biểu nghĩa | thịt, mô mỡ | 柔 | nhu | biểu âm | mềm mại; gợi âm ròu | 腬 = 肉 (Nhục, biểu nghĩa: thịt/mỡ) + 柔 (Nhu, biểu âm); chữ hình thanh. 肉 chỉ đây là thuộc tính của mô thịt, 柔 cung cấp âm đọc gần với ròu trong tiếng Quảng Đông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": 肉 (nhục — thịt) + 柔 (nhu — mềm) → thịt mềm béo ngậy, mỡ màng — đúng với nghĩa ''greasy, oily'' trong tiếng Quảng. | Gương Hán-Việt | nhu — ít dùng trong Hán-Việt chuẩn, chủ yếu trong ngữ cảnh phương ngữ | Mở khoá kiến thức | Biết 腬 giúp hiểu mô tả ẩm thực trong văn viết tiếng Quảng Đông cổ điển.", "Tự nguyên_Xie": "腬 (ròu) là chữ Quảng Đông chỉ tính chất béo ngậy, dầu mỡ của thức ăn. Wiktionary ghi cấu trúc hình thanh: 肉 (nhục) biểu nghĩa ''thịt/mỡ'', 柔 (nhu) biểu âm. Chữ chủ yếu dùng trong văn viết tiếng Quảng, ít xuất hiện trong Quan thoại chuẩn; chưa có nguồn học thuật sâu ngoài ghi chép phương ngữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "béo ngậy (tiếng Quảng Đông)", "Hạng Tần Suất (Jun Da)": "8315.0", "Tần Suất % (Jun Da)": "99.9995721019", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腬", "Unihan_Traditional (Chữ Phồn thể)": "腬", "Pinyin_Xie": "ròu", "Âm Hán Việt_Xie": "nhục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để tả thịt béo tốt hoặc da dẻ mịn màng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膄', '{"9000": "8316.0", "Chữ Trung Quốc": "膄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 膄 | sấu | tượng hình | gầy còm, tiều tụy | 膄 chưa có phân tích hội ý hay hình thanh được xác nhận trong nguồn học thuật hiện có. Xem như tượng hình độc lập chỉ trạng thái gầy yếu của cơ thể; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sấu\": hình ảnh thân thể (bộ 肉) co lại, tiêu hao — người gầy đến mức xương thịt teo tóp, \"sấu\" như cành cây khô. | Gương Hán-Việt | sấu — trong \"gầy sấu\" (cách nói dân gian về người gầy gò) | Mở khoá kiến thức | Biết 膄 (sấu) giúp đọc miêu tả thể trạng trong y văn Hán cổ.", "Tự nguyên_Xie": "膄 (sòu) nghĩa là gầy còm, tiều tụy. Không có glyph origin có cấu trúc rõ ràng trong Wiktionary hay CHISE cho chữ này. Từ ngữ cảnh: chữ thuộc bộ 肉 (nhục), gợi ý liên quan đến thể xác con người; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ngu si", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膄", "Unihan_Traditional (Chữ Phồn thể)": "膄", "Pinyin_Xie": "sòu", "Âm Hán Việt_Xie": "sau", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng sau động từ liên kết để miêu tả trạng thái thể chất hoặc trí tuệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膋', '{"9000": "8317.0", "Chữ Trung Quốc": "膋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 14 | nét | 勞 | lao | biểu âm | lao động; âm liáo | 肉 | nhục | biểu nghĩa | thịt, mỡ | 膋 = 勞 (Lao, biểu âm) + 肉 (Nhục, biểu nghĩa: mỡ, thịt); chữ hình thanh. 勞 cung cấp âm liáo, 肉 chỉ đây là loại mỡ trong cơ thể động vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": 勞 (lao — lao nhọc) + 肉 (nhục — thịt) → lớp mỡ mỏng bao ruột, như người lao động tích mỡ từ nhọc nhằn — chữ cổ chỉ mỡ tế lễ. | Gương Hán-Việt | liêu — trong văn tế Kinh Thi; ít dùng hiện đại | Mở khoá kiến thức | Biết 膋 (liêu) giúp đọc hiểu nghi lễ tế tự và ẩm thực cổ đại trong Kinh Thi, Lễ Ký.", "Tự nguyên_Xie": "膋 (liáo) là từ cổ chỉ màng mỡ bao quanh ruột của động vật, dùng trong tế lễ. Wiktionary ghi cấu trúc hình thanh: 勞 (lao) biểu âm, 肉 (nhục) biểu nghĩa ''thịt/mỡ''. Chữ xuất hiện trong Kinh Thi và các văn bản tế lễ thời Chu, mô tả mỡ dùng để đốt trong nghi lễ hiến tế; chưa phổ biến trong tiếng Hán hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màng mỡ ở ruột", "Hạng Tần Suất (Jun Da)": "8317.0", "Tần Suất % (Jun Da)": "99.9995736523", "GavinGrover_Once (Chiết tự trực tiếp)": "炏 + 肎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱炏肎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "炏", "Unihan_Simplified (Chữ Giản thể)": "膋", "Unihan_Traditional (Chữ Phồn thể)": "膋", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các văn bản y học cổ truyền hoặc mô tả giải phẫu động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臕', '{"9000": "8318.0", "Chữ Trung Quốc": "臕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 19 | nét | 臕 | phiêu | tượng hình | mỡ dưới da gia súc; béo mập | 臕 là dạng dị thể của 膘, chưa có phân tích hình thanh hay hội ý riêng. Wiktionary dẫn 臕 về 膘. Thuộc bộ 肉 (nhục), chỉ lớp mỡ dưới da của gia súc; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": hình ảnh gia súc lên cân — lớp mỡ (bộ 肉) tích dưới da, \"trưởng phiêu\" là khi con vật béo mập trở lại sau mùa đông. | Gương Hán-Việt | phiêu — trong \"trưởng phiêu\" (gia súc lên cân, phục hồi) | Mở khoá kiến thức | Biết 臕/膘 (phiêu) giúp đọc văn bản chăn nuôi và y học thú y cổ điển Trung Hoa.", "Tự nguyên_Xie": "臕 (biāo) là dạng dị thể cổ của 膘, chỉ lớp mỡ dưới da của gia súc, dùng để đánh giá sức khỏe và độ béo của con vật. Wiktionary ghi ''See 膘''. Chữ 膘 (phiêu) có glyph origin từ 肉 + 票, nhưng dạng 臕 dùng 臼 thay vì 票, cho thấy đây là biến thể trong ghi chép. Chưa có nguồn học thuật đầy đủ về riêng dạng 臕. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phiếu; như \"phiếu (gia súc mập): trưởng phiếu (lên cân)\" \nCũng như chữ phiêu 膘.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 麃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月麃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臕", "Unihan_Traditional (Chữ Phồn thể)": "臕", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái béo tốt của gia súc hoặc danh từ chỉ mỡ động vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舃', '{"9000": "8319.0", "Chữ Trung Quốc": "舃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 12 | nét | 舃 | tích | tượng hình | giày đế kép dành cho quý tộc; chim ác | 舃 là chữ cổ chưa có phân tích hình thanh hoàn chỉnh trong nguồn học thuật hiện có. Chữ tượng hình hoặc hội ý cổ đại chỉ loại giày lễ đặc biệt có hai lớp đế; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": hình ảnh đôi giày quý tộc (舃) với hai lớp đế — dấu ấn của địa vị và nghi lễ trong triều đình cổ Trung Hoa. | Gương Hán-Việt | tích — ít xuất hiện trong Hán-Việt hiện đại; dùng trong khảo cổ và nghiên cứu văn hóa Chu | Mở khoá kiến thức | Biết 舃 (tích) giúp đọc tài liệu về trang phục lễ nghi và khảo cổ học thời Chu, Hán.", "Tự nguyên_Xie": "舃 (xì) chỉ loại giày nghi lễ có đế kép, dùng trong lễ phục của quý tộc thời Chu. Ngoài ra còn có nghĩa ''chim ác'' (magpie). Không có glyph origin có cấu trúc trong Wiktionary. Đây là chữ cổ ít được dùng sau thời Hán; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giày 2 lần đế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "臼 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舃", "Unihan_Traditional (Chữ Phồn thể)": "舃", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại giày nghi lễ của vua quan thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艭', '{"9000": "8320.0", "Chữ Trung Quốc": "艭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 24 | nét | 艭 | song | tượng hình | một loại thuyền nhỏ | 艭 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 舟 (chu — thuyền), chỉ một loại thuyền; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"song\": bộ 舟 (chu — thuyền) → loại thuyền nhỏ; \"song\" gợi hình ảnh đôi mái chèo (song = hai) trên chiếc thuyền nhỏ lướt nước. | Gương Hán-Việt | song — ít xuất hiện trong Hán-Việt; liên quan đến vận tải đường thủy cổ | Mở khoá kiến thức | Biết 艭 (song) giúp đọc tài liệu lịch sử về loại thuyền và giao thông đường thủy thời cổ đại.", "Tự nguyên_Xie": "艭 (shuāng) chỉ một loại thuyền nhỏ. Wiktionary ghi nhận âm Hán trung cổ và âm cổ đại nhưng định nghĩa còn thiếu (''rfdef''). Thuộc bộ 舟. Chưa có glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thuyền", "Hạng Tần Suất (Jun Da)": "8320.0", "Tần Suất % (Jun Da)": "99.9995757194", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 雙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟雙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艭", "Unihan_Traditional (Chữ Phồn thể)": "艭", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "sang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loại thuyền lớn hai chèo thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艶', '{"9000": "8321.0", "Chữ Trung Quốc": "艶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 色 | Số nét | 19 | nét | 艶 | diễm | tượng hình | đẹp đẽ, tươi sáng, quyến rũ | 艶 là dạng dị thể Nhật Bản / cổ của 艷. Cấu trúc gốc của 艷 gồm 豐 (phong — phong phú, đầy đủ) + 色 (sắc — màu sắc, vẻ đẹp), chỉ vẻ đẹp rực rỡ, tràn đầy. 艶 đơn giản hóa phần 豐 nhưng giữ nguyên nghĩa; chưa có nguồn học thuật đầy đủ về riêng dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diễm\": vẻ đẹp (色 — sắc) phong phú (豐 — phong) → \"diễm lệ\", \"diễm tình\" — những gì đẹp đến mức tràn đầy, không kìm được ánh mắt. | Gương Hán-Việt | diễm — trong ''diễm lệ'' (đẹp rực rỡ), ''diễm tình'' (tình yêu đẹp) | Mở khoá kiến thức | Biết 艶/艷 (diễm) giúp hiểu từ ''diễm lệ'', ''diễm ca'', ''diễm tình'' — dòng từ vựng về cái đẹp trong Hán-Việt.", "Tự nguyên_Xie": "艶 (yàn) là biến thể của 艷 (diễm), chỉ vẻ đẹp quyến rũ, tươi sáng. Chữ gốc 艷 gồm 豐 (phong) biểu nghĩa ''phong phú'' và 色 (sắc) biểu nghĩa ''màu sắc, vẻ đẹp'', kết hợp chỉ người hay vật có vẻ đẹp rực rỡ, đầy đặn. Không có glyph origin riêng cho dạng 艶; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp đẽ, tươi đẹp; con gái đẹp; chuyện tình yêu; hâm mộ, ham chuộng; khúc hát nước Sở", "Hạng Tần Suất (Jun Da)": "2100.0", "Tần Suất % (Jun Da)": "97.4829396049", "GavinGrover_Once (Chiết tự trực tiếp)": "豊 + 色", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豊色", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "色", "Unihan_Simplified (Chữ Giản thể)": "艳", "Unihan_Traditional (Chữ Phồn thể)": "艶", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "diễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để tả vẻ đẹp rực rỡ hoặc làm danh từ chỉ chuyện tình duyên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艼', '{"9000": "8322.0", "Chữ Trung Quốc": "艼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 5 | nét | 艼 | đinh | tượng hình | cây nhỏ; chỉ dùng trong từ ghép 艼熒 | 艼 chưa có phân tích hội ý hay hình thanh được xác nhận. Thuộc bộ 艸/艹 (thảo — cỏ cây), chỉ loại cây hoặc cỏ nhỏ; chỉ xuất hiện trong từ ghép 艼熒; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": bộ 艸 (thảo — cỏ) + hình dáng nhỏ bé → cây cỏ nhỏ như cái đinh, chỉ xuất hiện trong một từ ghép duy nhất — 艼熒. | Gương Hán-Việt | đinh — ít xuất hiện trong Hán-Việt; dùng trong thực vật học cổ điển | Mở khoá kiến thức | Biết 艼 giúp đọc từ ghép 艼熒 trong thực vật học và bản thảo học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 艼 (tīng/dǐng) chỉ được dùng trong từ ghép 艼熒 (tīng yíng), chỉ loài cây nhỏ hoặc cỏ dại. Wiktionary ghi nhận hai âm đọc: tīng (Hán trung cổ) và dǐng. Có hình tiểu triện lưu lại. Chưa có glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đinh (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "艼", "Unihan_Traditional (Chữ Phồn thể)": "艼", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại cỏ nhỏ mọc ở vùng đất ngập nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荢', '{"9000": "8323.0", "Chữ Trung Quốc": "荢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荢 | dữu | tượng hình | một loại cây cỏ không xác định | 荢 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 艸/艹 (thảo — cỏ cây). Nghĩa và cấu trúc chưa được ghi chép đầy đủ; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dữu\": bộ 艸 (thảo — cỏ) → một loài cỏ hay cây nào đó — chữ quá hiếm để truy nguyên rõ nghĩa, chỉ biết đây là thực vật trong văn ngôn cổ. | Gương Hán-Việt | dữu — không có từ Hán-Việt hiện đại dùng chữ này | Mở khoá kiến thức | Biết 荢 giúp nhận dạng chữ hiếm trong danh sách thực vật cổ đại Trung Hoa.", "Tự nguyên_Xie": "荢 (yú) là chữ hiếm thuộc bộ 艸, nghĩa không xác định rõ trong nguồn học thuật hiện đại. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 宇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹宇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荢", "Unihan_Traditional (Chữ Phồn thể)": "荢", "Pinyin_Xie": "yu", "Âm Hán Việt_Xie": "duu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại thực vật hoặc cỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萚', '{"9000": "8324.0", "Chữ Trung Quốc": "萚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萚 | thác | tượng hình | lá rụng, vỏ cây bong tróc | 萚 chưa có phân tích hình thanh hay hội ý được xác nhận trong Wiktionary. Thuộc bộ 艸 (thảo), chỉ lá khô rụng hoặc vỏ cây bong tróc trong mùa thu; có hình tiểu triện lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": bộ 艸 (thảo — cỏ cây) → lá và vỏ cây bong tróc, rụng xuống — \"thác\" gợi ''thoát'' (rời khỏi), lá thoát ra khỏi cành mùa thu. | Gương Hán-Việt | thác — xuất hiện trong thơ Kinh Thi mô tả cảnh mùa thu | Mở khoá kiến thức | Biết 萚 (thác) giúp đọc thơ Kinh Thi và thi ca cổ điển mô tả cảnh sắc mùa thu.", "Tự nguyên_Xie": "Tiểu triện | 萚 (tuò) chỉ lá đã rụng hoặc vỏ cây bong tróc. Wiktionary ghi nghĩa ''falling leaf or bark'' và xếp vào văn học. Có hình tiểu triện trên hanziyuan.net. Chữ xuất hiện trong Kinh Thi (《詩經》) mô tả cảnh thu lá vàng rụng; chưa có nguồn học thuật về glyph origin cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẹ cây, mo nang; lá cây đã rụng", "Hạng Tần Suất (Jun Da)": "8324.0", "Tần Suất % (Jun Da)": "99.9995783033", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 择", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹择", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "择", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萚", "Unihan_Traditional (Chữ Phồn thể)": "蘀", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ phần lá khô rụng hoặc bẹ cây trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓗', '{"9000": "8325.0", "Chữ Trung Quốc": "蓗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓗 | tổng | tượng hình | cụm hoa, cuống hoa mọc từ củ | 蓗 chưa có phân tích hình thanh hay hội ý được xác nhận trong Wiktionary. Thuộc bộ 艸 (thảo), nghĩa liên quan đến thực vật, đặc biệt là cụm hoa hay cuống hoa mọc từ củ (như hoa lan, thủy tiên); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tổng\": bộ 艸 (thảo — cỏ) → nhiều cuống hoa gom lại thành chùm, như ''tổng hợp'' — chữ thực vật học cổ ít dùng hiện đại. | Gương Hán-Việt | tổng — ít xuất hiện trong Hán-Việt; dùng trong bản thảo học và thực vật học cổ | Mở khoá kiến thức | Biết 蓗 (tổng) giúp đọc mô tả thực vật trong y dược thư cổ Trung Hoa.", "Tự nguyên_Xie": "蓗 (zǒng) chỉ cụm hoa hay cuống hoa mọc từ củ của một số loài thực vật như hoa lan, hoa thủy tiên. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giò; như \"giò lan; giò thuỷ tiên (cọng hoa mọc từ củ)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 徒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹徒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "徒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓗", "Unihan_Traditional (Chữ Phồn thể)": "蓗", "Pinyin_Xie": "zǒng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ phần cọng hoa mọc từ củ của một số loài cây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓱', '{"9000": "8326.0", "Chữ Trung Quốc": "蓱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 蓱 | bình | tượng hình | bèo; loài thực vật thủy sinh nhỏ | 蓱 chưa có phân tích hình thanh hay hội ý được xác nhận trong Wiktionary. Thuộc bộ 艸 (thảo), liên quan đến thực vật thủy sinh; nhiều khả năng là dạng dị thể hoặc chữ cổ của 萍 (bình — bèo); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": bộ 艸 (thảo — cỏ) → cây bèo nổi trên mặt nước — \"bình\" gợi ''bình thản'' (mặt nước phẳng lặng nơi bèo trôi). | Gương Hán-Việt | bình — trong ''phù bình'' (bèo nổi), ''bình bồng'' (trôi dạt như bèo) | Mở khoá kiến thức | Biết 蓱 (bình) giúp nhận dạng dạng dị thể của 萍 trong văn bản thực vật học và thơ ca cổ điển về sông nước.", "Tự nguyên_Xie": "蓱 (píng) nhiều khả năng là dạng cổ hoặc dị thể của 萍 (bình — bèo), chỉ loài thực vật thủy sinh nổi trên mặt nước. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ping", "Hạng Tần Suất (Jun Da)": "8326.0", "Tần Suất % (Jun Da)": "99.9995793369", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 洴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹洴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "洴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓱", "Unihan_Traditional (Chữ Phồn thể)": "蓱", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "binh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài bèo nổi trên mặt nước, thường dùng trong thơ văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕋', '{"9000": "8327.0", "Chữ Trung Quốc": "蕋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕋 | nhị | tượng hình | nhị hoa, nụ hoa chưa nở | 蕋 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 艸 (thảo), chỉ nhị hoa hoặc nụ hoa chưa nở; nhiều khả năng là dạng dị thể của 蕊 (nhị); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": bộ 艸 (thảo — cỏ/hoa) → phần nhị nằm giữa bông hoa — \"nhị\" trong ''nhị hoa'', ''nhị đực'', ''nhị cái'' đều từ gốc này. | Gương Hán-Việt | nhị — trong ''nhị hoa'' (phần sinh sản của hoa), ''hoa nhị'' | Mở khoá kiến thức | Biết 蕋/蕊 (nhị) giúp đọc tài liệu thực vật học, y học cổ và thơ ca mô tả hoa lá.", "Tự nguyên_Xie": "蕋 (ruǐ) là dạng dị thể của 蕊 (nhị), chỉ nhị hoa hoặc nụ hoa chưa nở. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. Chữ 蕊 gốc gồm ba bộ 心 (tâm) kết hợp với 艸, mô tả phần trung tâm của hoa. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhị hoa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 歮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹歮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕋", "Unihan_Traditional (Chữ Phồn thể)": "蕋", "Pinyin_Xie": "ruǐ", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận sinh sản của hoa, thường kết hợp với các danh từ chỉ hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕟', '{"9000": "8328.0", "Chữ Trung Quốc": "蕟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕟 | phế | tượng hình | một loại cỏ không xác định | 蕟 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 艸 (thảo), chỉ một loài cỏ hoặc cây không xác định được trong nguồn học thuật hiện đại; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phế\": bộ 艸 (thảo — cỏ) → loài cây cỏ bỏ hoang, \"phế\" gợi ''phế bỏ'' — chữ quá hiếm để truy nguyên rõ. | Gương Hán-Việt | phế — không có từ Hán-Việt hiện đại dùng chữ này | Mở khoá kiến thức | Biết 蕟 giúp nhận dạng chữ hiếm bộ 艸 trong danh sách thực vật cổ đại.", "Tự nguyên_Xie": "蕟 (fà) là chữ thực vật hiếm. Không có glyph origin có cấu trúc trong Wiktionary; nghĩa cụ thể không được ghi chép rõ ràng; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 發", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹發", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "發", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕟", "Unihan_Traditional (Chữ Phồn thể)": "蕟", "Pinyin_Xie": "fà", "Âm Hán Việt_Xie": "phe", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ một loại cỏ hoặc tính từ tả cảnh cỏ mọc um tùm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薐', '{"9000": "8329.0", "Chữ Trung Quốc": "薐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薐 | lăng | tượng hình | rau bó xôi; dùng trong 菠薐 | 薐 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 艸 (thảo), xuất hiện trong từ ghép 菠薐 (ba lăng — rau bó xôi/spinach); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": bộ 艸 (thảo) trong từ 菠薐 — rau bó xôi du nhập từ Ba Tư, âm ''lăng'' phản chiếu âm ngoại lai; \"lăng\" gợi ''lăng kính'' (nhìn xuyên qua nguồn gốc ngoại lai). | Gương Hán-Việt | lăng — trong ''ba lăng'' (菠薐 — rau bó xôi cổ) | Mở khoá kiến thức | Biết 薐 (lăng) giúp nhận biết tên cổ của rau bó xôi trong y thư và ẩm thực Hán cổ.", "Tự nguyên_Xie": "薐 (léng) chỉ xuất hiện trong từ 菠薐 (ba lăng), tên cũ của rau bó xôi (spinach). Wiktionary ghi nghĩa ''spinach'' nhưng không có glyph origin có cấu trúc. Rau bó xôi du nhập vào Trung Hoa qua con đường tơ lụa từ Ba Tư (Persia), tên 菠薐 phản ánh âm Ba Tư; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ba lăng 菠薐)", "Hạng Tần Suất (Jun Da)": "8329.0", "Tần Suất % (Jun Da)": "99.9995808873", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 稜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹稜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "稜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薐", "Unihan_Traditional (Chữ Phồn thể)": "薐", "Pinyin_Xie": "léng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép trong từ chỉ rau chân vịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薠', '{"9000": "8330.0", "Chữ Trung Quốc": "薠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薠 | phiên | tượng hình | loại cỏ tương tự cỏ dừa; cỏ nước cổ điển | 薠 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 艸 (thảo), chỉ loài cỏ thủy sinh tương tự cỏ dừa (莎草); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": bộ 艸 (thảo — cỏ) → loài cỏ mọc ở bờ nước, ''phiên'' gợi ''phiền não'' (mọc rậm rạp, khó dẹp) — cỏ nước cổ điển trong thi ca. | Gương Hán-Việt | phiên — ít xuất hiện trong Hán-Việt; dùng trong thi ca và bản thảo học cổ | Mở khoá kiến thức | Biết 薠 (phiên) giúp đọc thi ca cổ điển Trung Hoa mô tả cảnh quan sông nước.", "Tự nguyên_Xie": "薠 (fán) chỉ loài cỏ thủy sinh tương tự cỏ dừa (莎草, suō cǎo), dùng trong văn học cổ điển. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tương tự cỏ dừa 莎草 [suo1 cao3] (cổ điển)", "Hạng Tần Suất (Jun Da)": "8330.0", "Tần Suất % (Jun Da)": "99.999581404", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 煩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹煩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "煩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薠", "Unihan_Traditional (Chữ Phồn thể)": "薠", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ thủy sinh trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘓', '{"9000": "8331.0", "Chữ Trung Quốc": "蘓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘓 | tô | tượng hình | cây tô (thyme/perilla); hồi sinh; Soviet | 蘓 là dạng dị thể của 蘇 (tô). Chữ 蘇 gốc gồm 艸 (thảo) + 魚 (ngư — cá) + 禾 (hoà — lúa), kết hợp phức tạp chỉ loài cây thơm. 蘓 đơn giản hóa một phần nhưng giữ nguyên nghĩa; có hình kim văn, tiểu triện và lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tô\": cây tô thơm (艸 — thảo) hồi sinh (tô sinh) — \"tô\" trong ''Tô Đông Pha'', ''Giang Tô'', ''tô sanh'' (蘇生 — hồi sinh) đều từ gốc này. | Gương Hán-Việt | tô — trong ''Tô Châu'' (蘇州), ''tô sinh'' (蘇生 — hồi tỉnh), ''Giang Tô'' (江蘇) | Mở khoá kiến thức | Biết 蘓/蘇 (tô) giúp hiểu địa danh Tô Châu, Giang Tô, và từ ''tô sinh'' (hồi tỉnh sau ngất).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 蘓 (sū) là dạng dị thể của 蘇 (tô), chỉ cây tô (húng tây, thyme/perilla) hoặc mang nghĩa ''hồi sinh, thức dậy''. Ngoài ra dùng phiên âm ''Soviet'' (蘇維埃). Có hình kim văn và tiểu triện lưu lại trên hanziyuan.net với nhiều biến thể lục thư thông. Wiktionary không cung cấp glyph origin riêng cho dạng 蘓; chưa có nguồn học thuật đầy đủ về dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蘓", "Unihan_Traditional (Chữ Phồn thể)": "蘓", "Pinyin_Xie": "sū", "Âm Hán Việt_Xie": "to", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cây tía tô hoặc làm động từ với nghĩa hồi sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘪', '{"9000": "8332.0", "Chữ Trung Quốc": "蘪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 20 | nét | 蘪 | mi | tượng hình | loại cây thủy sinh; dị thể của 蘼 | 蘪 là dạng dị thể cổ của 蘼 (mi), chỉ loài cây thủy sinh hoặc cây thảo mộc cổ. Thuộc bộ 艸 (thảo); chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": bộ 艸 (thảo — cỏ) → cây thủy sinh mềm mại — \"mi\" gợi ''mi mắt'' (lông mày mịn như tơ), hình ảnh cây cỏ thanh mảnh bên nước. | Gương Hán-Việt | mi — ít xuất hiện trong Hán-Việt; liên quan 蘼蕪 (mi vô — loài thảo dược cổ) | Mở khoá kiến thức | Biết 蘪 (mi) giúp nhận dạng dạng dị thể trong văn bản dược thảo và thi ca cổ điển.", "Tự nguyên_Xie": "蘪 (méi/mí) là dạng dị thể cổ của 蘼 (mi), chỉ loài thực vật thủy sinh. Wiktionary ghi nhận chữ này là ''alt form'' của 蘼 và chỉ một loài cây thủy sinh; không có glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "昪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 麋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹麋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘪", "Unihan_Traditional (Chữ Phồn thể)": "蘪", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong tên các loại cỏ thơm cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虵', '{"9000": "8333.0", "Chữ Trung Quốc": "虵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 9 | nét | 虵 | xà | tượng hình | con rắn; dị thể cổ của 蛇 | 虵 là dạng cổ của 蛇 (xà — rắn). Thuộc bộ 虫 (trùng), chỉ loài rắn. Chữ tượng hình mô tả con rắn bò; chưa có nguồn học thuật đầy đủ về riêng dạng 虵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xà\": bộ 虫 (trùng — sâu bọ) → con rắn bò sát đất — \"xà\" trong ''mãng xà'' (trăn lớn), ''xà hình'' (hình chữ S), ''xà ma'' đều từ gốc này. | Gương Hán-Việt | xà — trong ''mãng xà'' (trăn lớn), ''xà hình'' (hình dáng rắn) | Mở khoá kiến thức | Biết 虵/蛇 (xà) giúp nhận biết dạng cổ và hiểu từ ''mãng xà'', ''xà tinh'' trong văn học dân gian.", "Tự nguyên_Xie": "虵 (shé) là dạng dị thể/cổ của 蛇 (xà), chỉ con rắn. Wiktionary liên kết về 蛇. Chữ 蛇 gốc có nguồn gốc tượng hình từ hình ảnh con rắn cuộn; bộ 虫 (trùng) trong cả hai chữ đều chỉ loài bò sát/côn trùng; chưa có nguồn học thuật riêng cho dạng 虵. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dã; như \"con dã tràng\" xà; như \"mãng xà; xà hình (hình chữ s); xà ma (chất ở cây)\" \n (Danh) Cũng như xà 蛇.", "Hạng Tần Suất (Jun Da)": "1687.0", "Tần Suất % (Jun Da)": "95.7308814125", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛇", "Unihan_Traditional (Chữ Phồn thể)": "虵", "Pinyin_Xie": "shé", "Âm Hán Việt_Xie": "xà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là biến thể cổ của chữ xà, làm danh từ chỉ con rắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚾', '{"9000": "8334.0", "Chữ Trung Quốc": "蚾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蚾 | bề | tượng hình | con cóc; toad | 蚾 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 虫 (trùng), chỉ loài cóc; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bề\": bộ 虫 (trùng — sâu bọ/bò sát) → con cóc ngồi phình bụng — \"bề\" gợi hình ảnh con cóc bề ngoài xù xì, to bụng. | Gương Hán-Việt | bề — ít xuất hiện trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 蚾 (bề) giúp đọc tài liệu sinh vật học và y học dân gian cổ điển về lưỡng thê.", "Tự nguyên_Xie": "蚾 (pí) chỉ con cóc (toad). Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cóc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚾", "Unihan_Traditional (Chữ Phồn thể)": "蚾", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "be", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ ghép chỉ con cóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛖', '{"9000": "8335.0", "Chữ Trung Quốc": "蛖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蛖 | mang | tượng hình | một loại côn trùng hoặc sinh vật không xác định | 蛖 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 虫 (trùng); nghĩa không được ghi chép rõ ràng; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mang\": bộ 虫 (trùng — sâu bọ) → sinh vật nhỏ bé mang tên khó nhớ — \"mang\" gợi ''mang vác'' (loài sinh vật mang mai cứng?); chữ quá hiếm để xác định rõ. | Gương Hán-Việt | mang — không có từ Hán-Việt hiện đại dùng chữ này | Mở khoá kiến thức | Biết 蛖 giúp nhận dạng chữ hiếm bộ 虫 trong danh lục sinh vật cổ Trung Hoa.", "Tự nguyên_Xie": "蛖 (máng) là chữ hiếm bộ 虫, nghĩa không xác định rõ trong nguồn học thuật hiện đại. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Xue", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 尨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫尨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛖", "Unihan_Traditional (Chữ Phồn thể)": "蛖", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "mang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài động vật thân mềm hai mảnh vỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛜', '{"9000": "8336.0", "Chữ Trung Quốc": "蛜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛜 | y | tượng hình | rệp gỗ (woodlouse); chỉ dùng trong 蛜蝛 | 蛜 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 虫 (trùng), chỉ con rệp gỗ (woodlouse / pillbug); chỉ dùng trong từ ghép 蛜蝛; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": bộ 虫 (trùng — sâu bọ) → con rệp gỗ cuộn tròn như viên thuốc — \"y\" gợi ''y sĩ'' (bác sĩ), con rệp gỗ cuộn tròn như viên thuốc chờ chữa bệnh. | Gương Hán-Việt | y — ít xuất hiện trong Hán-Việt; dùng trong côn trùng học cổ điển | Mở khoá kiến thức | Biết 蛜 giúp đọc tên côn trùng trong các bản thảo y học cổ Trung Hoa.", "Tự nguyên_Xie": "蛜 (yī) chỉ xuất hiện trong từ ghép 蛜蝛 (y uy) hoặc 蛜𧌴, chỉ con rệp gỗ (woodlouse, Armadillidium vulgare). Wiktionary ghi nhận âm Hán trung cổ và cổ đại. Thuộc bộ 虫. Chưa có glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "woodlouse", "Hạng Tần Suất (Jun Da)": "8336.0", "Tần Suất % (Jun Da)": "99.9995850215", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 伊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫伊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛜", "Unihan_Traditional (Chữ Phồn thể)": "蛜", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đi liền với chữ khác chỉ côn trùng ẩm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝍', '{"9000": "8337.0", "Chữ Trung Quốc": "蝍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蝍 | tức | tượng hình | rết; côn trùng có cánh; chỉ dùng trong 蝍蛆 | 蝍 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 虫 (trùng), chỉ con rết hoặc một loài côn trùng có cánh; chỉ dùng trong từ ghép 蝍蛆; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tức\": bộ 虫 (trùng) → con rết nhiều chân bò nhanh — \"tức\" gợi ''tức thì'' (nhanh như rết bò), chỉ dùng trong từ cổ 蝍蛆. | Gương Hán-Việt | tức — ít xuất hiện trong Hán-Việt; dùng trong từ điển côn trùng cổ | Mở khoá kiến thức | Biết 蝍 giúp đọc tên côn trùng trong y học cổ và văn bản tự nhiên học Trung Hoa.", "Tự nguyên_Xie": "蝍 (jié/jí) chỉ xuất hiện trong từ 蝍蛆 (tức thư), chỉ con rết. Wiktionary ghi thêm nghĩa ''winged insect'' (côn trùng có cánh). Thuộc bộ 虫. Chưa có glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tức thư 蝍蛆)", "Hạng Tần Suất (Jun Da)": "8337.0", "Tần Suất % (Jun Da)": "99.9995855383", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 即", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫即", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "即", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝍", "Unihan_Traditional (Chữ Phồn thể)": "蝍", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp để chỉ con rết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟂', '{"9000": "8338.0", "Chữ Trung Quốc": "蟂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 梟 | kiêu | biểu âm | cú mèo; gợi âm xiāo | 蟂 = 虫 (Trùng, biểu nghĩa: côn trùng/sinh vật) + 梟 (Kiêu, biểu âm); chữ hình thanh. 虫 chỉ đây là loài côn trùng hoặc sinh vật nhỏ, 梟 cung cấp âm xiāo/jiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": 虫 (trùng — côn trùng) + 梟 (kiêu — cú mèo, hung dữ) → sinh vật nhỏ hung dữ như cú — chữ hình thanh ít dùng trong Hán-Việt hiện đại. | Gương Hán-Việt | kiêu — ít xuất hiện trong Hán-Việt; dùng trong danh lục sinh vật học cổ | Mở khoá kiến thức | Biết 蟂 giúp đọc danh sách côn trùng trong bản thảo y học và sinh vật học cổ Trung Hoa.", "Tự nguyên_Xie": "蟂 (xiāo/jiāo) là chữ hiếm chỉ một loài côn trùng hoặc sinh vật nhỏ không xác định rõ. Wiktionary ghi cấu trúc hình thanh: 虫 (trùng) biểu nghĩa, 梟 (kiêu) biểu âm. Có hai âm đọc chuẩn: xiāo (Mainland) và jiāo (Taiwan); chưa có nguồn học thuật đầy đủ về loài sinh vật cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "肂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 梟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫梟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "梟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟂", "Unihan_Traditional (Chữ Phồn thể)": "蟂", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "kieu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài bò sát lớn dưới nước thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟜', '{"9000": "8339.0", "Chữ Trung Quốc": "蟜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟜 | kiểu | tượng hình | côn trùng có nọc độc; họ Kiểu | 蟜 chưa có phân tích hình thanh hay hội ý được xác nhận trong Wiktionary. Thuộc bộ 虫 (trùng), chỉ một loài côn trùng có nọc độc; cũng là họ người; có hình đại triện và tiểu triện lưu lại; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểu\": bộ 虫 (trùng — côn trùng) → loài có nọc độc hung dữ — \"kiểu\" gợi ''kiểu cách'' (vẻ ngoài đặc biệt), như côn trùng có màu sắc cảnh báo độc. | Gương Hán-Việt | kiểu — trong họ Kiểu (蟜) trong sử liệu cổ Trung Hoa | Mở khoá kiến thức | Biết 蟜 giúp đọc sử liệu về họ tộc và côn trùng học trong văn bản cổ Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 蟜 (jiǎo) chỉ một loài côn trùng có nọc độc, và cũng là họ người. Có hình đại triện và tiểu triện trên wikimedia. Wiktionary không cung cấp glyph origin có cấu trúc; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại côn trùng có nọc độc; họ Kiểu", "Hạng Tần Suất (Jun Da)": "8339.0", "Tần Suất % (Jun Da)": "99.9995870887", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 喬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫喬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟜", "Unihan_Traditional (Chữ Phồn thể)": "蟜", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài côn trùng có độc hoặc dùng làm họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠏', '{"9000": "8340.0", "Chữ Trung Quốc": "蠏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠏 | giải | tượng hình | con cua; dị thể của 蟹 | 蠏 là dạng dị thể cổ của 蟹 (giải — cua). Thuộc bộ 虫 (trùng), chỉ con cua; Wiktionary dẫn về 蟹; có hình tiểu triện lưu lại; chưa có nguồn học thuật riêng cho dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": bộ 虫 (trùng — động vật nhỏ) → con cua với càng kẹp hai bên — \"giải\" trong ''giải phóng'' (mở ra như cua mở càng), ''giải thích'' (phân tích từng phần như cua bóc vỏ). | Gương Hán-Việt | giải — trong văn cổ chỉ con cua; 蟹 là dạng chuẩn hiện đại | Mở khoá kiến thức | Biết 蠏/蟹 (giải) giúp đọc văn bản ẩm thực và sinh vật học cổ điển, nhận dạng từ cổ trong thơ văn.", "Tự nguyên_Xie": "Tiểu triện | 蠏 (xiè) là dạng dị thể cổ của 蟹 (giải), chỉ con cua. Wiktionary ghi ''See 蟹''. Có hình tiểu triện trên hanziyuan.net. Chữ 蟹 gốc gồm 解 (giải) + 虫 (trùng), là chữ hình thanh; 蠏 là biến thể trong truyền chép; chưa có nguồn học thuật riêng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giải; như \"con giải (tên một loại rùa lớn)\" cua; như \"con cua; cua gái\" \n (Danh) Con cua. \n§ Cũng như giải 蟹.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 解", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫解", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠏", "Unihan_Traditional (Chữ Phồn thể)": "蠏", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con cua, thường dùng như một biến thể của chữ giải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衘', '{"9000": "8341.0", "Chữ Trung Quốc": "衘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 行 | Số nét | 13 | nét | 衘 | hàm | tượng hình | hàm thiếc trong miệng ngựa; dị thể của 銜 | 衘 là dạng dị thể thông tục (''folk character'') của 銜 (hàm). Thuộc bộ 行 (hàng), Wiktionary ghi ''Folk character of 銜''; chưa có nguồn học thuật riêng cho dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": bộ 行 (hàng — đi) → hàm thiếc kiểm soát bước chân ngựa — \"hàm\" trong ''chức hàm'' (địa vị), ''hàm oan'' (oan ức ngậm trong lòng). | Gương Hán-Việt | hàm — trong ''chức hàm'' (銜 — địa vị chức vụ), ''hàm oan'' (oan ức) | Mở khoá kiến thức | Biết 衘/銜 (hàm) giúp hiểu từ ''chức hàm'', ''đầu hàm'' (dẫn đầu) trong văn bản hành chính và lịch sử.", "Tự nguyên_Xie": "衘 (xián) là dạng dị thể thông tục của 銜 (hàm), chỉ hàm thiếc trong miệng ngựa và theo nghĩa mở rộng là ''nắm giữ trong miệng'', ''chức hàm''. Wiktionary ghi ''Folk character of 銜''. Thuộc bộ 行 (hàng — đường, hàng ngũ); chưa có nguồn học thuật riêng về dạng 衘. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "行 + 𦈢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴行𦈢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦈢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "行", "Unihan_Simplified (Chữ Giản thể)": "衘", "Unihan_Traditional (Chữ Phồn thể)": "衘", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "ham", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động ngậm vật gì đó hoặc mang theo lòng biết ơn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袟', '{"9000": "8342.0", "Chữ Trung Quốc": "袟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袟 | trật | tượng hình | bìa sách; túi sách; trật tự | 袟 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 衣 (y — áo/vải), nghĩa liên quan đến bìa sách hoặc túi đựng sách; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trật\": bộ 衣 (y — vải) → túi vải bọc sách, giữ cho ngăn nắp theo thứ tự — \"trật\" trong ''trật tự'' (thứ bậc), như cách sách được xếp ngay ngắn trong bao. | Gương Hán-Việt | trật — trong ''trật tự'' (秩序), ít dùng với chữ 袟 trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 袟 giúp đọc tài liệu về thư pháp, thư tịch học và cách bảo quản sách thời cổ đại Trung Hoa.", "Tự nguyên_Xie": "袟 (zhì) chỉ bìa sách, túi hoặc bao đựng sách, và theo nghĩa mở rộng là ''trật tự, thứ tự''. Thuộc bộ 衣 (y — vải/áo), gợi ý ban đầu là vật làm từ vải để bọc hoặc bảo vệ sách. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thứ tự; trật (10 năm)", "Hạng Tần Suất (Jun Da)": "8342.0", "Tần Suất % (Jun Da)": "99.9995891558", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袟", "Unihan_Traditional (Chữ Phồn thể)": "袟", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ bao sách hoặc làm lượng từ chỉ khoảng thời gian mười năm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袬', '{"9000": "8343.0", "Chữ Trung Quốc": "袬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袬 | cổn | tượng hình | một loại trang phục; nghĩa không rõ | 袬 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 衣 (y — áo/vải), nghĩa liên quan đến trang phục; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổn\": bộ 衣 (y — áo) → loại áo lễ nghi hoặc trang phục đặc biệt — \"cổn\" gợi ''cổn lăn'' (lăn tròn như vải cuốn), hình ảnh áo choàng dài cuộn lại. | Gương Hán-Việt | cổn — ít xuất hiện trong Hán-Việt; dùng trong nghiên cứu trang phục cổ đại | Mở khoá kiến thức | Biết 袬 giúp nhận dạng chữ hiếm bộ 衣 trong tài liệu trang phục học và văn hóa cổ đại Trung Hoa.", "Tự nguyên_Xie": "袬 (gǔn) là chữ hiếm bộ 衣, nghĩa không được ghi chép rõ ràng trong nguồn học thuật hiện đại. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "袬", "Unihan_Traditional (Chữ Phồn thể)": "袬", "Pinyin_Xie": "gǔn", "Âm Hán Việt_Xie": "con", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại lễ phục thêu rồng của hoàng đế ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譅', '{"9000": "8344.0", "Chữ Trung Quốc": "譅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 21 | nét | 譅 | sắc | tượng hình | chậm chạp, ấp úng khi nói | 譅 chưa có phân tích hình thanh hay hội ý được xác nhận. Thuộc bộ 言 (ngôn — lời nói), chỉ cách nói chuyện chậm chạp, khó khăn, ấp úng; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": bộ 言 (ngôn — lời nói) → lời nói khó nhọc, ấp úng như màu sắc tối tăm — \"sắc\" gợi ''sắc bén'' (ngược lại với ấp úng), người sắc bén trong lời nói không bao giờ譅. | Gương Hán-Việt | sắc — ít xuất hiện trong Hán-Việt; dùng trong mô tả ngôn ngữ học cổ điển | Mở khoá kiến thức | Biết 譅 giúp đọc mô tả về phong cách diễn đạt trong tài liệu ngôn ngữ học và tu từ học cổ Trung Hoa.", "Tự nguyên_Xie": "譅 (sè) chỉ sự chậm chạp, ấp úng khi nói. Thuộc bộ 言 (ngôn). Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chậm chạp, ấp úng", "Hạng Tần Suất (Jun Da)": "8344.0", "Tần Suất % (Jun Da)": "99.9995907062", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 歰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言歰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譅", "Unihan_Traditional (Chữ Phồn thể)": "譅", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả giọng nói hoặc cách diễn đạt bị ấp úng, không lưu loát. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譌', '{"9000": "8345.0", "Chữ Trung Quốc": "譌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 譌 | ngoa | tượng hình | sai lầm, bịa đặt; làm bậy | 譌 chưa có phân tích hình thanh hay hội ý được xác nhận trong Wiktionary. Thuộc bộ 言 (ngôn — lời nói), chỉ lời nói sai lầm, bịa đặt hoặc hành động bậy bạ; có hình tiểu triện lưu lại; chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoa\": bộ 言 (ngôn — lời nói) → lời nói sai lầm, ngoa ngôn — \"ngoa\" trong ''nói ngoa'' (nói dối/cường điệu), ''ngoa ngoắt'' — đúng với nghĩa ''false, erroneous''. | Gương Hán-Việt | ngoa — trong ''nói ngoa'' (lời nói sai/dối); ít dùng dạng chữ 譌 trong Hán-Việt chuẩn | Mở khoá kiến thức | Biết 譌 (ngoa) giúp nhận dạng chữ cổ chỉ lời nói sai lầm trong văn bản ngôn ngữ học và triết học Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | 譌 (é) nghĩa là sai lầm, giả dối, làm bậy. Thuộc bộ 言 (ngôn). Có hình tiểu triện trên wikimedia. Không có glyph origin có cấu trúc trong Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm bậy; sai, nhầm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 爲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言爲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譌", "Unihan_Traditional (Chữ Phồn thể)": "譌", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "ngoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự sai lệch hoặc động từ chỉ việc phao tin đồn nhảm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譸', '{"9000": "8346.0", "Chữ Trung Quốc": "譸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 21 | nét | 譸 | chu | tượng hình | chữ độc thể, bộ ngôn (言) | 譸 là chữ độc thể thuộc bộ Ngôn (言), chưa phân tích được cấu trúc hình thanh hay hội ý rõ ràng. Chưa có nguồn học thuật xác định thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": chữ thuộc bộ Ngôn (lời nói) — lời nói gian dối, lừa đảo người khác. | Gương Hán-Việt | chu — dùng trong văn ngôn cổ, rất hiếm gặp trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 譸 (chu) giúp nhận ra nhóm chữ chỉ sự lừa dối trong văn ngôn Hán cổ.", "Tự nguyên_Xie": "Wiktionary ghi 譸 là biến thể của 侜 (chu), có nghĩa lừa dối, gian trá. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc tội", "Hạng Tần Suất (Jun Da)": "6670.0", "Tần Suất % (Jun Da)": "99.9948724579", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 壽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言壽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "诪", "Unihan_Traditional (Chữ Phồn thể)": "譸", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi lừa gạt, thường đi kèm trong từ ghép chu trương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趝', '{"9000": "8347.0", "Chữ Trung Quốc": "趝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 15 | nét | 趝 | tiện | tượng hình | chữ độc thể, bộ tẩu (走) | 趝 là chữ độc thể thuộc bộ Tẩu (走, chạy). Chưa phân tích được cấu trúc rõ ràng từ nguồn hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiện\": bộ Tẩu (走, chạy) — chạy đuổi theo, truy đuổi. | Gương Hán-Việt | tiện — rất hiếm, hầu như không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 趝 (tiện) giúp nhận ra nhóm chữ chỉ động tác chạy/đuổi trong bộ Tẩu.", "Tự nguyên_Xie": "Chữ 趝 thuộc bộ Tẩu (走), nghĩa: truy đuổi, theo dấu. Wiktionary chỉ ghi âm jiàn. Chưa có nguồn học thuật phân tích glyph origin. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趝", "Unihan_Traditional (Chữ Phồn thể)": "趝", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đi nhanh hoặc nhảy vọt qua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趡', '{"9000": "8348.0", "Chữ Trung Quốc": "趡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 15 | nét | 趡 | thôi | tượng hình | chữ độc thể, bộ tẩu (走) | 趡 là chữ độc thể thuộc bộ Tẩu (走). Chưa có phân tích hình thanh hay hội ý từ nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thôi\": bộ Tẩu (走, chạy) — chạy nhanh, xông tới. | Gương Hán-Việt | thôi — hiếm trong tiếng Việt, chủ yếu trong địa danh cổ | Mở khoá kiến thức | Biết 趡 (thôi) giúp đọc địa danh và văn ngôn cổ có bộ Tẩu.", "Tự nguyên_Xie": "Wiktionary ghi 趡 có âm cuǐ/wěi/jù, dùng trong văn ngôn cổ nghĩa là chạy nhanh hoặc dùng trong địa danh. Chữ tạo muộn, chưa có nguồn glyph origin học thuật. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên địa điểm", "Hạng Tần Suất (Jun Da)": "8348.0", "Tần Suất % (Jun Da)": "99.9995932901", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趡", "Unihan_Traditional (Chữ Phồn thể)": "趡", "Pinyin_Xie": "cuǐ", "Âm Hán Việt_Xie": "thuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ dáng đi nhanh hoặc làm danh từ riêng chỉ địa danh thời cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跾', '{"9000": "8349.0", "Chữ Trung Quốc": "跾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 跾 | xu | tượng hình | chữ độc thể, bộ túc (足) | 跾 là chữ độc thể thuộc bộ Túc (足, chân). Chưa phân tích được cấu trúc rõ ràng từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xu\": bộ Túc (足, chân) — bước chân lắc lư, không vững. | Gương Hán-Việt | xu — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 跾 (xu) giúp nhận ra các chữ mô tả dáng đi bất thường trong bộ Túc.", "Tự nguyên_Xie": "Chữ 跾 thuộc bộ Túc (足), nghĩa: lắc lư, đi không vững. Wiktionary chỉ ghi âm shū. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lắc lư", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "攸 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱攸足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "攸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "跾", "Unihan_Traditional (Chữ Phồn thể)": "跾", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "xu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ miêu tả dáng đi nhanh hoặc trạng thái lắc lư của cơ thể. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踀', '{"9000": "8350.0", "Chữ Trung Quốc": "踀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 踀 | súc | tượng hình | chữ độc thể, bộ túc (足) | 踀 là chữ độc thể thuộc bộ Túc (足, chân). Chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": bộ Túc (足, chân) — liên quan đến bước chân hoặc súc vật. | Gương Hán-Việt | súc — rất hiếm, hầu như không dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 踀 (súc) giúp nhận ra nhóm chữ cổ hiếm trong bộ Túc.", "Tự nguyên_Xie": "Chữ 踀 thuộc bộ Túc (足). Wiktionary chỉ ghi âm chù, liên quan đến heo (hog), nghĩa không rõ ràng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Heo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "足", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踀", "Unihan_Traditional (Chữ Phồn thể)": "踀", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này chủ yếu làm tính từ để mô tả trạng thái chật hẹp hoặc động từ chỉ hành động giẫm đạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踸', '{"9000": "8351.0", "Chữ Trung Quốc": "踸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 踸 | chậm | tượng hình | chữ độc thể, bộ túc (足) | 踸 là chữ độc thể thuộc bộ Túc (足, chân). Thường dùng trong tổ hợp 踸踔 (bước đi không đều). Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chậm\": bộ Túc (足, chân) — bước chân chậm chạp, khập khiễng. | Gương Hán-Việt | chậm — dùng trong 踸踔 (chậm chước), bước đi không đều | Mở khoá kiến thức | Biết 踸 (chậm) mở khoá cụm 踸踔 — diễn tả dáng đi khập khiễng trong thơ văn cổ.", "Tự nguyên_Xie": "Wiktionary ghi 踸 âm chěn, chủ yếu dùng trong tổ hợp 踸踔 — bước đi không đều, khập khiễng. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật phân tích glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy nhót", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踸", "Unihan_Traditional (Chữ Phồn thể)": "踸", "Pinyin_Xie": "chěn", "Âm Hán Việt_Xie": "sẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ hoặc tính từ trong từ ghép để tả dáng đi khập khiễng, không vững vàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹡', '{"9000": "8352.0", "Chữ Trung Quốc": "蹡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹡 | tường | tượng hình | chữ độc thể, bộ túc (足) | 蹡 là chữ độc thể thuộc bộ Túc (足, chân). Wiktionary ghi hai âm qiāng/qiàng với nghĩa bước đi theo nhịp điệu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": bộ Túc (足, chân) — bước đi uyển chuyển theo nhịp điệu, tường hoà. | Gương Hán-Việt | tường — dùng trong 踉蹡 (lượng tường), bước đi loạng choạng | Mở khoá kiến thức | Biết 蹡 (tường) mở khoá cụm 踉蹡 — diễn tả dáng đi khó khăn hoặc uyển chuyển trong thơ văn.", "Tự nguyên_Xie": "Wiktionary ghi 蹡 có hai âm: qiāng (đi nhịp nhàng, uyển chuyển) và qiàng (bước xiêu vẹo, loạng choạng). Chữ tạo muộn, không thấy trong giáp cốt/kim văn. Chưa có phân tích glyph origin học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lượng thương 踉蹡)", "Hạng Tần Suất (Jun Da)": "8352.0", "Tần Suất % (Jun Da)": "99.9995953572", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 將", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊將", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "將", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹡", "Unihan_Traditional (Chữ Phồn thể)": "蹡", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ phối hợp trong từ ghép để tả dáng đi loạng choạng hoặc đi theo hàng lối. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垌', '{"9000": "8353.0", "Chữ Trung Quốc": "垌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất, ruộng | 同 | đồng | biểu âm | cùng nhau, âm đồng | 垌 = 土 (Thổ, biểu nghĩa: đất) + 同 (Đồng, biểu âm); chữ hình thanh. 同 cho âm đồng, Thổ chỉ đây là vùng đất, cánh đồng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": 土 (đất) + 同 (đồng âm) — mảnh đất chung, cánh đồng làng. | Gương Hán-Việt | đồng — dùng trong địa danh miền Nam Trung Quốc, tương tự \"đồng\" trong tiếng Việt (cánh đồng) | Mở khoá kiến thức | Biết 垌 (đồng) giúp đọc địa danh vùng Quảng Tây, Quảng Đông có nghĩa cánh đồng.", "Tự nguyên_Xie": "Wiktionary ghi 垌 cấu tạo hình thanh: 土 (thổ, đất) là phần biểu nghĩa, 同 (đồng) là phần biểu âm. Nghĩa: cánh đồng, ruộng đất; dùng trong địa danh vùng Lưỡng Quảng, Quảng Tây (các vùng người Choang/Zhuang). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất đai; động (thường dùng làm tên đất); đồng chủng", "Hạng Tần Suất (Jun Da)": "8353.0", "Tần Suất % (Jun Da)": "99.999595874", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垌", "Unihan_Traditional (Chữ Phồn thể)": "垌", "Pinyin_Xie": "dòng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ để chỉ ruộng đất hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹳', '{"9000": "8354.0", "Chữ Trung Quốc": "蹳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹳 | bát | tượng hình | chữ độc thể, bộ túc (足) | 蹳 là chữ độc thể thuộc bộ Túc (足, chân). Chưa có phân tích cấu trúc học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\": bộ Túc (足, chân) — bước đi mạnh, đạp bát (tám) bước. | Gương Hán-Việt | bát — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 蹳 (bát) giúp nhận ra các chữ cổ hiếm trong bộ Túc.", "Tự nguyên_Xie": "Chữ 蹳 thuộc bộ Túc (足). Wiktionary chỉ ghi âm bō, nghĩa không rõ. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "賳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 發", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊發", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "發", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹳", "Unihan_Traditional (Chữ Phồn thể)": "蹳", "Pinyin_Xie": "bō", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này đóng vai trò là động từ chỉ hành động giẫm đạp bằng chân hoặc gạt bỏ đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躛', '{"9000": "8355.0", "Chữ Trung Quốc": "躛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 23 | nét | 躛 | vị | tượng hình | chữ độc thể, bộ túc (足) hoặc biến thể của 躗 | 躛 là biến thể của 躗 (vị), thuộc bộ Túc (足). Nghĩa: phóng đại, thêu dệt. Chưa có phân tích cấu trúc học thuật riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": biến thể của 躗 — lời nói phóng đại, thêu dệt quá mức. | Gương Hán-Việt | vị — rất hiếm, chủ yếu trong văn ngôn cổ | Mở khoá kiến thức | Biết 躛 (vị) giúp nhận ra nhóm chữ chỉ sự phóng đại, thêu dệt trong văn ngôn.", "Tự nguyên_Xie": "Chữ 躛 được Wiktionary ghi là biến thể của 躗 (wèi), nghĩa: phóng đại, nói quá. Thuộc bộ Túc (足). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể của 躗 [wei4]", "Hạng Tần Suất (Jun Da)": "8355.0", "Tần Suất % (Jun Da)": "99.9995969076", "GavinGrover_Once (Chiết tự trực tiếp)": "衞 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衞足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "躛", "Unihan_Traditional (Chữ Phồn thể)": "躛", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này được dùng như động từ chỉ sự vượt qua giới hạn hoặc tính từ chỉ sự dối trá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躩', '{"9000": "8356.0", "Chữ Trung Quốc": "躩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 27 | nét | 躩 | quyết | tượng hình | chữ độc thể, bộ túc (足) | 躩 là chữ độc thể thuộc bộ Túc (足, chân). Wiktionary ghi hai âm qì/jué, nghĩa bước đi nhanh, nhảy vọt. Chưa có phân tích cấu trúc rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ Túc (足, chân) — bước quyết đoán, nhảy vọt nhanh. | Gương Hán-Việt | quyết — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 躩 (quyết) giúp nhận ra các chữ cổ chỉ động tác chân nhanh trong bộ Túc.", "Tự nguyên_Xie": "Wiktionary ghi 躩 có âm qì/jué, nghĩa không rõ ràng (rfdef). Thuộc bộ Túc (足). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật phân tích glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ cong; nhảy vọt", "Hạng Tần Suất (Jun Da)": "8356.0", "Tần Suất % (Jun Da)": "99.9995974244", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 矍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊矍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躩", "Unihan_Traditional (Chữ Phồn thể)": "躩", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động nhảy vọt hoặc bước đi nhanh nhẹn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躶', '{"9000": "8357.0", "Chữ Trung Quốc": "躶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 15 | nét | 躶 | lõa | tượng hình | biến thể của 裸, bộ thân (身) hoặc y (衣) | 躶 là biến thể của 裸 (lõa), nghĩa: trần truồng, cởi áo. Wiktionary ghi 躶 như dạng thay thế (variant) của 裸. Bộ Thân (身).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lõa\": biến thể của 裸 — thân thể lõa lồ, trần truồng. | Gương Hán-Việt | lõa — dùng trong \"lõa thể\" (thân trần), \"lõa lồ\" trong tiếng Việt | Mở khoá kiến thức | Biết 躶 (lõa) cùng gốc với 裸 — mở khoá nhóm từ chỉ sự trần truồng trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary ghi 躶 là biến thể của 裸 (luǒ), nghĩa: trần truồng, cởi quần áo. Cùng nghĩa với 裸. Chữ tạo muộn so với 裸. Chưa có nguồn học thuật phân tích glyph origin riêng cho 躶. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vợ lẽ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躶", "Unihan_Traditional (Chữ Phồn thể)": "躶", "Pinyin_Xie": "luǒ", "Âm Hán Việt_Xie": "lõa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái trần truồng hoặc động từ chỉ việc để lộ cơ thể. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軏', '{"9000": "8358.0", "Chữ Trung Quốc": "軏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 10 | nét | 軏 | ngột | tượng hình | thanh ngang trên xe ngựa, bộ xa (車) | 軏 là chữ độc thể thuộc bộ Xa (車, xe). Chỉ thanh ngang (crossbar) ở đầu càng xe ngựa dùng để buộc ách. Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngột\": bộ Xa (車, xe) — thanh ngột ngang trên xe ngựa, giữ cho ách không rơi. | Gương Hán-Việt | ngột — dùng trong 輗軏, cặp từ chỉ khớp nối xe ngựa cổ | Mở khoá kiến thức | Biết 軏 (ngột) mở khoá cụm 輗軏 trong Luận Ngữ — ẩn dụ về sự kết nối, tin tưởng.", "Tự nguyên_Xie": "Wiktionary ghi 軏 thuộc bộ Xa (車), nghĩa: thanh ngang ở đầu càng xe ngựa dùng để buộc ách (crossbar at the end of cart poles). Dùng trong cụm 輗軏 — hai loại khớp nối xe ngựa. Chữ tạo muộn, chưa thấy rõ trong giáp cốt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xà ngang để ách ngựa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "𫐄", "Unihan_Traditional (Chữ Phồn thể)": "軏", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "ngột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận chốt gỗ nối giữa xe và ách trâu ngựa thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軬', '{"9000": "8359.0", "Chữ Trung Quốc": "軬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 軬 | phán | tượng hình | mui xe, bộ xa (車) | 軬 là chữ độc thể thuộc bộ Xa (車, xe). Nghĩa: mui xe, bạt che xe. Chưa có phân tích hình thanh rõ ràng từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phán\": bộ Xa (車, xe) — tấm phán (bạt) che mui xe, bảo vệ người ngồi trong xe. | Gương Hán-Việt | phán — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 軬 (phán) giúp đọc các văn bản cổ mô tả cấu tạo xe ngựa.", "Tự nguyên_Xie": "Wiktionary ghi 軬 âm fàn/bèn, nghĩa: mui xe, tấm bạt che xe (vehicle canopy). Đồng nghĩa với 車篷. Chữ tạo muộn. Chưa có nguồn học thuật phân tích glyph origin riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "厶 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱厶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "軬", "Unihan_Traditional (Chữ Phồn thể)": "軬", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái mui xe hoặc tấm che bằng tre trên xe kéo thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輵', '{"9000": "8360.0", "Chữ Trung Quốc": "輵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 輵 | cát | tượng hình | chữ độc thể, bộ xa (車) | 輵 là chữ độc thể thuộc bộ Xa (車, xe). Chưa có phân tích cấu trúc học thuật. Wiktionary không có glyph origin.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cát\": bộ Xa (車, xe) — hàng cát (hàng ngũ) xe ngựa và giáo mác rầm rộ. | Gương Hán-Việt | cát — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 輵 (cát) giúp đọc các văn bản cổ mô tả quân xa, binh khí.", "Tự nguyên_Xie": "Chữ 輵 thuộc bộ Xa (車), nghĩa: hàng loạt giáo và xe ngựa (great array of spears and chariots). Wiktionary không có glyph origin. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng loạt giáo và xe ngựa", "Hạng Tần Suất (Jun Da)": "8360.0", "Tần Suất % (Jun Da)": "99.9995994915", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輵", "Unihan_Traditional (Chữ Phồn thể)": "輵", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả cảnh tượng xe cộ và binh khí đông đúc, đan xen hỗn loạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轗', '{"9000": "8361.0", "Chữ Trung Quốc": "轗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 20 | nét | 轗 | khảm | tượng hình | chữ độc thể, bộ xa (車) | 轗 là chữ độc thể thuộc bộ Xa (車, xe). Chủ yếu dùng trong cụm 轗軻 (khảm kha), tương tự 坎坷 — con đường gian nan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảm\": bộ Xa (車, xe) — bánh xe sa vào ổ gà, đường khảm kha gian nan. | Gương Hán-Việt | khảm — dùng trong 轗軻 (khảm kha), ẩn dụ cuộc đời gian truân, không suôn sẻ | Mở khoá kiến thức | Biết 轗 (khảm) mở khoá cụm 轗軻 trong thơ văn cổ — ẩn dụ cuộc đời gập ghềnh.", "Tự nguyên_Xie": "Wiktionary ghi 轗 âm kǎn, chỉ dùng trong cụm 轗軻, là biến thể của 坎坷 — nghĩa: đường gập ghềnh, cuộc đời gian truân. Chữ tạo muộn, không thấy glyph origin riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khảm kha 轗軻)", "Hạng Tần Suất (Jun Da)": "8361.0", "Tần Suất % (Jun Da)": "99.9996000083", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 感", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車感", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "感", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轗", "Unihan_Traditional (Chữ Phồn thể)": "轗", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "khảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ trong từ ghép khảm kha để tả cảnh ngộ trắc trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轥', '{"9000": "8362.0", "Chữ Trung Quốc": "轥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 26 | nét | 轥 | lận | tượng hình | chữ độc thể, bộ xa (車) | 轥 là chữ độc thể thuộc bộ Xa (車, xe). Nghĩa: bánh xe lăn qua, đè lên, vượt qua. Wiktionary ghi tương đồng với 躪 (giẫm đạp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\": bộ Xa (車, xe) — bánh xe lận (lăn) qua, đè bẹp tất cả. | Gương Hán-Việt | lận — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 轥 (lận) giúp đọc văn bản cổ mô tả xe lăn qua, đè dẹp, liên quan 躪/蹂躪.", "Tự nguyên_Xie": "Wiktionary ghi 轥 âm lìn, nghĩa: bánh xe lăn qua (roll over), vượt qua, đạp giẫm. Tương đồng với 躪 (lăn bánh xe qua). Chữ tạo muộn, không thấy glyph origin rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh xe lăn; đi qua; qua; đạp; giẫm; vượt qua; hơn; vượt trội; (tiếng xe)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 藺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車藺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "藺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "轥", "Unihan_Traditional (Chữ Phồn thể)": "轥", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "lận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động bánh xe đè lên hoặc chà đạp lên vật khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逷', '{"9000": "8363.0", "Chữ Trung Quốc": "逷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 辵 | xước | biểu nghĩa | đi, bước chân | 易 | dịch | biểu âm | thay đổi, âm dịch | 逷 = 辵 (Xước, biểu nghĩa: đi) + 易 (Dịch, biểu âm); chữ hình thanh. 辵 chỉ sự di chuyển, 易 cho âm. Nghĩa: xa xôi, cách biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": 辵 (đi) + 易 (dịch âm) — đi mãi đến nơi địch (xa xôi) tít tắp. | Gương Hán-Việt | địch — \"địch phương\" (nơi xa), \"địch nhân\" (người phương xa) trong văn ngôn | Mở khoá kiến thức | Biết 逷 (địch) cùng gốc với 逖 — nhóm chữ chỉ sự xa cách, viễn phương.", "Tự nguyên_Xie": "Wiktionary ghi 逷 cấu tạo hình thanh: 辵 (xước, đi) là phần biểu nghĩa, 易 (dịch) là phần biểu âm. Nghĩa: xa xôi, cách biệt. Là biến thể của 逖 (tì/địch — xa). Chưa có glyph origin riêng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa xôi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逷", "Unihan_Traditional (Chữ Phồn thể)": "逷", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ khoảng cách xa xôi hoặc làm động từ với nghĩa tránh xa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遈', '{"9000": "8364.0", "Chữ Trung Quốc": "遈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 遈 | thật | tượng hình | chữ độc thể, bộ sước (辵) | 遈 là chữ độc thể thuộc bộ Sước (辵, đi). Wiktionary không có phân tích cấu trúc chi tiết. Nghĩa: bỏ trốn, chạy thoát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thật\": bộ Sước (辵, đi) — chạy thật nhanh để thoát thân. | Gương Hán-Việt | thật — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 遈 (thật) giúp nhận ra nhóm chữ chỉ sự bỏ trốn trong bộ Sước.", "Tự nguyên_Xie": "Wiktionary ghi 遈 âm shí, nghĩa: bỏ trốn, tẩu thoát. Chữ tạo muộn, không thấy glyph origin rõ ràng. Chưa có nguồn học thuật xác định. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Bỏ trốn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 是", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶是", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "是", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遈", "Unihan_Traditional (Chữ Phồn thể)": "遈", "Pinyin_Xie": "shí", "Âm Hán Việt_Xie": "thật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu làm động từ chỉ hành vi bỏ trốn hoặc di chuyển. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邌', '{"9000": "8365.0", "Chữ Trung Quốc": "邌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 18 | nét | 邌 | li | tượng hình | chữ độc thể, bộ sước (辵) | 邌 là chữ độc thể thuộc bộ Sước (辵, đi). Wiktionary ghi nghĩa: đi chậm, diễu hành. Thường dùng trong cụm 邌旦/邌明 chỉ lúc tảng sáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\": bộ Sước (辵, đi) — bước đi li ti chậm chạp trong buổi sáng sớm mờ mờ. | Gương Hán-Việt | li — dùng trong 邌明 (li minh), 邌旦 (li đán) — tảng sáng trong văn ngôn | Mở khoá kiến thức | Biết 邌 (li) mở khoá cụm 邌明/邌旦 — cách nói tảng sáng trong thơ văn cổ.", "Tự nguyên_Xie": "Wiktionary ghi 邌 âm lí, nghĩa: đi chậm, từ từ (slowly). Dùng trong cụm 邌旦, 邌明, 邌曙 — chỉ lúc trời tảng sáng, sáng sớm. Chữ tạo muộn, chưa thấy glyph origin riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "邌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 黎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶黎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "邌", "Unihan_Traditional (Chữ Phồn thể)": "邌", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này dùng làm động từ hoặc tính từ mô tả dáng đi chậm rãi, khoan thai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄟', '{"9000": "8366.0", "Chữ Trung Quốc": "鄟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 13 | nét | 鄟 | chuyên | tượng hình | chữ độc thể, bộ ấp (邑) | 鄟 là chữ độc thể thuộc bộ Ấp (邑, làng/huyện). Wiktionary ghi âm zhuān, nghĩa không rõ, có thể là địa danh. Chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyên\": bộ Ấp (邑, huyện/làng) — địa danh chuyên biệt, một vùng đất riêng. | Gương Hán-Việt | chuyên — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 鄟 (chuyên) giúp nhận ra các địa danh cổ trong bộ Ấp.", "Tự nguyên_Xie": "Wiktionary ghi 鄟 âm zhuān, thuộc bộ Ấp (邑). Nghĩa không rõ ràng (rfdef). Có thể là địa danh cổ. Chữ tạo muộn, chưa thấy glyph origin. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "專 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰專阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "專", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄟", "Unihan_Traditional (Chữ Phồn thể)": "鄟", "Pinyin_Xie": "zhuān", "Âm Hán Việt_Xie": "chuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên một quốc gia nhỏ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醎', '{"9000": "8367.0", "Chữ Trung Quốc": "醎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 醎 | hàm | tượng hình | biến thể của 鹹, bộ dậu (酉) | 醎 là biến thể cổ của 鹹 (hàm — mặn), thuộc bộ Dậu (酉). Wiktionary ghi 醎 đơn giản là variant của 鹹.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": biến thể của 鹹 — vị hàm (mặn), như muối biển. | Gương Hán-Việt | hàm — \"hàm vị\" (vị mặn), dùng trong y học cổ truyền và văn ngôn | Mở khoá kiến thức | Biết 醎 (hàm) cùng gốc với 鹹/咸 — nhóm từ chỉ vị mặn trong ngũ vị.", "Tự nguyên_Xie": "Wiktionary ghi 醎 là biến thể của 鹹 (xián), nghĩa: mặn, vị mặn. Cùng nghĩa với 咸. Chữ thuộc bộ Dậu (酉 — đồ uống, lên men). Chưa có glyph origin riêng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mặn, vị mặn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醎", "Unihan_Traditional (Chữ Phồn thể)": "醎", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ bổ nghĩa cho danh từ để chỉ tính chất mặn của thức ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釭', '{"9000": "8368.0", "Chữ Trung Quốc": "釭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 釭 | cong | tượng hình | vòng kim loại trung tâm bánh xe, bộ kim (金) | 釭 là chữ độc thể thuộc bộ Kim (金, kim loại). Nghĩa: vòng kim loại ở trung tâm bánh xe, hoặc đèn dầu. Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cong\": bộ Kim (金, kim loại) — vòng kim loại cong tròn ở trục bánh xe, hoặc đèn cong bằng bạc. | Gương Hán-Việt | cong — dùng trong \"ngân cong\" (銀釭, đèn bạc) trong thơ từ cổ | Mở khoá kiến thức | Biết 釭 (cong) mở khoá cụm 銀釭 trong từ khúc — hình ảnh đèn bạc trong phòng khuê.", "Tự nguyên_Xie": "Wiktionary ghi 釭 âm gāng/gōng, nghĩa: vòng kim loại ở trung tâm bánh xe nơi trục xuyên qua; cũng có nghĩa là đèn dầu (oil lamp). Dùng trong thơ Tống từ: 銀釭 (ngân cong — đèn bạc). Chữ tạo muộn, không thấy glyph origin rõ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ống gang trong bánh xe; cái đọi đèn; mũi tên", "Hạng Tần Suất (Jun Da)": "8368.0", "Tần Suất % (Jun Da)": "99.9996036258", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釭", "Unihan_Traditional (Chữ Phồn thể)": "釭", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "cang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vật dụng bằng kim loại như ống trục xe hoặc đọi đèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怊', '{"9000": "8369.0", "Chữ Trung Quốc": "怊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 怊 | siêu | tượng hình | chữ độc thể, bộ tâm (心) | 怊 là chữ độc thể thuộc bộ Tâm (心, lòng). Wiktionary ghi nghĩa: buồn, đau khổ, thất vọng. Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"siêu\": bộ Tâm (心, lòng) — lòng siêu (buồn siêu lòng), nỗi buồn không nguôi. | Gương Hán-Việt | siêu — dùng trong 怊悵 (siêu trướng), 怊惆 (siêu trù) — nỗi buồn sầu | Mở khoá kiến thức | Biết 怊 (siêu) mở khoá cụm 怊悵/怊惆 — diễn tả nỗi buồn trong thơ văn cổ.", "Tự nguyên_Xie": "Wiktionary ghi 怊 âm chāo, nghĩa: buồn (sad), đau khổ (sorrowful), thất vọng (disconsolate). Thuộc bộ Tâm (心). Dùng trong cụm 怊悵 (siêu trướng), 怊惆 (siêu trù). Chữ tạo muộn, không thấy glyph origin rõ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bi phẫn; bi ai phẫn nộ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怊", "Unihan_Traditional (Chữ Phồn thể)": "怊", "Pinyin_Xie": "chāo", "Âm Hán Việt_Xie": "siêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị trạng thái tâm lý buồn rầu, thất vọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銌', '{"9000": "8370.0", "Chữ Trung Quốc": "銌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銌 | tôn | tượng hình | chữ độc thể, bộ kim (金) | 銌 là chữ độc thể thuộc bộ Kim (金, kim loại). Wiktionary không có glyph origin hay định nghĩa rõ. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": bộ Kim (金, kim loại) — vật kim loại tôn trọng, hiếm quý. | Gương Hán-Việt | tôn — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 銌 (tôn) giúp nhận ra các chữ kim loại cổ cực hiếm trong bộ Kim.", "Tự nguyên_Xie": "Chữ 銌 thuộc bộ Kim (金). Wiktionary không có glyph origin hay định nghĩa. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 存", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金存", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "存", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銌", "Unihan_Traditional (Chữ Phồn thể)": "銌", "Pinyin_Xie": "zùn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ kim loại hoặc động từ chỉ việc đục, khảm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋂', '{"9000": "8371.0", "Chữ Trung Quốc": "鋂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋂 | mũi | tượng hình | chuỗi kim loại cổ, bộ kim (金) | 鋂 là chữ thuộc bộ Kim (金, kim loại). Nghĩa cổ: chuỗi kim loại có hai vòng; nghĩa hiện đại (Đài Loan): americium. Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mũi\": bộ Kim (金, kim loại) — chuỗi mũi kim loại, vòng đôi kết nối nhau. | Gương Hán-Việt | mũi — rất hiếm trong tiếng Việt, ngoại trừ thuật ngữ hóa học (americium) | Mở khoá kiến thức | Biết 鋂 (mũi) giúp đọc văn bản Đài Loan về nguyên tố hóa học americium.", "Tự nguyên_Xie": "Wiktionary ghi 鋂 âm méi, nghĩa cổ: chuỗi kim loại, vòng đôi (bit cup). Ở Đài Loan dùng để phiên âm americium (Am, nguyên tố 95). Thuộc bộ Kim. Chưa có glyph origin học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(cổ xưa) chuỗi kim loại; americium (hóa học) (Tw)", "Hạng Tần Suất (Jun Da)": "8371.0", "Tần Suất % (Jun Da)": "99.9996056929", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋂", "Unihan_Traditional (Chữ Phồn thể)": "鋂", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "môi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại xích sắt khóa chó hoặc tên nguyên tố hóa học Americium. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋎', '{"9000": "8372.0", "Chữ Trung Quốc": "鋎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋎 | hàn | tượng hình | chữ độc thể, bộ kim (金) | 鋎 là chữ độc thể thuộc bộ Kim (金, kim loại). Wiktionary không có glyph origin. Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàn\": bộ Kim (金, kim loại) — vật kim loại hàn gắn, kết nối. | Gương Hán-Việt | hàn — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 鋎 (hàn) giúp nhận ra nhóm chữ kim loại cổ cực hiếm.", "Tự nguyên_Xie": "Chữ 鋎 thuộc bộ Kim (金), âm hàn. Wiktionary không có glyph origin hay định nghĩa cụ thể. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鋎", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋎", "Unihan_Traditional (Chữ Phồn thể)": "鋎", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ trong ngữ cảnh hàn gắn hoặc chế tác kim loại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍐', '{"9000": "8373.0", "Chữ Trung Quốc": "鍐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍐 | tông | tượng hình | vật trang trí trên dây cương, bộ kim (金) | 鍐 là chữ thuộc bộ Kim (金, kim loại). Nghĩa: cột đầu ngựa, vật trang trí trên dây cương (headstall ornament). Chưa có phân tích hình thanh rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": bộ Kim (金, kim loại) — vật kim loại trang trí trên dây cương, phần tông (tổng) điều khiển ngựa. | Gương Hán-Việt | tông — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 鍐 (tông) giúp đọc các văn bản cổ mô tả trang bị ngựa và yên cương.", "Tự nguyên_Xie": "Wiktionary ghi 鍐 âm zōng, nghĩa: vật trang trí trên dây cương ngựa, cột đầu (a headstall, ornament on a bridle). Chữ thuộc bộ Kim. Không có glyph origin. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cột đầu, vật trang trí trên dây cương", "Hạng Tần Suất (Jun Da)": "8373.0", "Tần Suất % (Jun Da)": "99.9996067265", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鍐", "Unihan_Traditional (Chữ Phồn thể)": "鍐", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ món đồ trang trí bằng kim loại trên đầu ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎴', '{"9000": "8374.0", "Chữ Trung Quốc": "鎴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎴 | tập | tượng hình | strontium (lỗi thời), bộ kim (金) | 鎴 là chữ thuộc bộ Kim (金, kim loại). Từng dùng để phiên âm strontium trong Hán ngữ truyền thống, nay đã lỗi thời, thay bằng 鍶 (Sr).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bộ Kim (金, kim loại) — chữ kim loại tập (dùng tạm) để phiên âm strontium, nay đã thay bằng 鍶. | Gương Hán-Việt | tập — rất hiếm, chỉ trong ngữ cảnh hóa học cổ | Mở khoá kiến thức | Biết 鎴 (tập) giúp đọc tài liệu hóa học Hán ngữ cũ về bảng tuần hoàn nguyên tố.", "Tự nguyên_Xie": "Wiktionary ghi 鎴 âm xí, từng dùng để dịch strontium (nguyên tố Sr), nay lỗi thời, thay bằng 鍶. Chữ thuộc bộ Kim. Không có glyph origin. Chữ tạo muộn cho mục đích phiên âm hóa học. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "strontium (lỗi thời, hiện nay 鍶", "Hạng Tần Suất (Jun Da)": "8374.0", "Tần Suất % (Jun Da)": "99.9996072433", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 息", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金息", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "息", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎴", "Unihan_Traditional (Chữ Phồn thể)": "鎴", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các tài liệu hóa học cổ để chỉ nguyên tố stronti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎸', '{"9000": "8375.0", "Chữ Trung Quốc": "鎸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎸 | quyên | tượng hình | dụng cụ khắc, bộ kim (金) | 鎸 là chữ thuộc bộ Kim (金, kim loại). Nghĩa: dụng cụ khắc, khắc chạm. Wiktionary không có glyph origin chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": bộ Kim (金, kim loại) — dùi kim loại quyên (khắc) lên đá, tạo ra chữ khắc. | Gương Hán-Việt | quyên — dùng trong \"quyên khắc\" (khắc chạm) trong văn ngôn cổ | Mở khoá kiến thức | Biết 鎸 (quyên) giúp đọc văn bản về nghề khắc chữ, điêu khắc kim loại cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 鎸 âm juān, nghĩa: dụng cụ khắc, khắc chạm, điêu khắc (engraving tool; carve, engrave). Thuộc bộ Kim. Không có glyph origin. Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鎸", "Hạng Tần Suất (Jun Da)": "8375.0", "Tần Suất % (Jun Da)": "99.9996077601", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 隽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金隽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎸", "Unihan_Traditional (Chữ Phồn thể)": "鎸", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bia đá hoặc đồ vật được khắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑘', '{"9000": "8376.0", "Chữ Trung Quốc": "鑘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 23 | nét | 鑘 | lũy | tượng hình | chữ độc thể, bộ kim (金) | 鑘 là chữ độc thể thuộc bộ Kim (金, kim loại). Wiktionary chỉ ghi âm léi/lěi, không có định nghĩa rõ (rfdef). Chữ cực hiếm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũy\": bộ Kim (金, kim loại) — vật kim loại lũy tiến, tích lũy theo thời gian. | Gương Hán-Việt | lũy — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 鑘 (lũy) giúp nhận ra nhóm chữ kim loại cổ cực hiếm trong bộ Kim.", "Tự nguyên_Xie": "Wiktionary ghi 鑘 âm léi/lěi, thuộc bộ Kim. Không có định nghĩa rõ ràng (rfdef). Chữ tạo muộn, chưa thấy glyph origin. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鑘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 畾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金畾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑘", "Unihan_Traditional (Chữ Phồn thể)": "鑘", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lũy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại dụng cụ đựng rượu thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膪', '{"9000": "8377.0", "Chữ Trung Quốc": "膪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | 膪 | suy | tượng hình | mỡ bụng heo, bộ nhục (月/肉) | 膪 là chữ thuộc bộ Nhục (肉/月, thịt). Nghĩa: mỡ bụng heo, lớp mỡ lỏng chảy. Wiktionary ghi chỉ dùng trong 囊膪.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suy\": bộ Nhục (月, thịt) — lớp mỡ suy (xệ) nhão nhũn như mỡ bụng heo. | Gương Hán-Việt | suy — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 膪 (suy) mở khoá cụm 囊膪 — mô tả mỡ heo trong ẩm thực và văn học dân gian.", "Tự nguyên_Xie": "Wiktionary ghi 膪 âm chuài/zhài, chỉ dùng trong cụm 囊膪 — mỡ bụng heo mềm nhũn, lớp mỡ chảy trong túi. Cũng là biến thể của 䐱. Chữ tạo muộn, không thấy glyph origin rõ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nang suý 囊膪); sù sì, cục kịch", "Hạng Tần Suất (Jun Da)": "8377.0", "Tần Suất % (Jun Da)": "99.9996098272", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 啻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月啻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膪", "Unihan_Traditional (Chữ Phồn thể)": "膪", "Pinyin_Xie": "chuài", "Âm Hán Việt_Xie": "suý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ hoặc tính từ miêu tả phần thịt mỡ lỏng lẻo ở cổ lợn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霣', '{"9000": "8378.0", "Chữ Trung Quốc": "霣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 18 | nét | 霣 | vẫn | tượng hình | mưa rơi, vật rơi xuống, bộ vũ (雨) | 霣 là chữ thuộc bộ Vũ (雨, mưa). Wiktionary ghi hai âm yǔn/jūn, nghĩa: mưa, sấm (theo thổ ngữ Tề), hoặc biến thể của 隕 (rơi từ trên xuống).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": bộ Vũ (雨, mưa) — mưa vẫn rơi, vật từ trời vẫn (rơi) xuống như thiên thạch. | Gương Hán-Việt | vẫn — đồng gốc với 隕 (vẫn) trong \"vẫn thạch\" (thiên thạch), \"vẫn lạc\" (rơi xuống) | Mở khoá kiến thức | Biết 霣 (vẫn) cùng gốc với 隕 — mở khoá nhóm từ rơi từ bầu trời xuống trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary ghi 霣 âm yǔn, nghĩa: mưa; theo thổ ngữ Tề có nghĩa là sấm. Cũng là biến thể của 隕 — rơi từ trên trời xuống (to fall from sky). Thuộc bộ Vũ (雨). Chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa rơi lúc sấm nổ; rơi, rơi xuống; chết", "Hạng Tần Suất (Jun Da)": "8378.0", "Tần Suất % (Jun Da)": "99.999610344", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 員", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨員", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "員", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霣", "Unihan_Traditional (Chữ Phồn thể)": "霣", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hiện tượng rơi rụng từ trên cao xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靃', '{"9000": "8379.0", "Chữ Trung Quốc": "靃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 24 | nét | 靃 | hoắc | tượng hình | chữ độc thể, bộ vũ (雨) hoặc chim | 靃 là chữ độc thể thuộc bộ Vũ (雨). Wiktionary ghi hai âm huò/suǐ, nghĩa không rõ (rfdef). Chưa có phân tích cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": bộ Vũ (雨, mưa) — mưa hoắc xuống, bất ngờ dữ dội. | Gương Hán-Việt | hoắc — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 靃 (hoắc) giúp nhận ra các chữ cổ hiếm trong bộ Vũ.", "Tự nguyên_Xie": "Wiktionary ghi 靃 có hai âm: huò (mc=2, oc=2) và suǐ, nghĩa không rõ ràng (rfdef). Thuộc bộ Vũ (雨). Chữ tạo muộn, chưa có glyph origin. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hảo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 雔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨雔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "靃", "Unihan_Traditional (Chữ Phồn thể)": "靃", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả tiếng động nhanh hoặc làm tính từ chỉ màu sắc. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韍', '{"9000": "8380.0", "Chữ Trung Quốc": "韍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 14 | nét | 韍 | phất | tượng hình | tấm da che đầu gối khi tế lễ, bộ vi (韋) | 韍 là chữ thuộc bộ Vi (韋, da thuộc). Nghĩa: tấm da che đầu gối mặc khi tế lễ (leather knee-pad worn during sacrifices). Wiktionary ghi 韍 là biến thể của 紱.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": bộ Vi (韋, da thuộc) — tấm da phất (che) đầu gối trong lễ tế, biểu tượng phẩm trật quan chức. | Gương Hán-Việt | phất — dùng trong \"phất thụ\" (lễ phục tế tự), \"phất tế\" (áo tế) trong văn ngôn lễ nhạc | Mở khoá kiến thức | Biết 韍 (phất) mở khoá nhóm từ lễ phục, phẩm phục trong văn hóa cung đình cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 韍 âm fú, nghĩa: tấm da che đầu gối làm bằng da mặc trong các buổi lễ tế (historical leather knee covering worn during sacrifices). Cũng là biến thể của 紱 (đai buộc ấn). Thuộc bộ Vi (韋). Chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đệm đầu gối", "Hạng Tần Suất (Jun Da)": "7986.0", "Tần Suất % (Jun Da)": "99.9993090583", "GavinGrover_Once (Chiết tự trực tiếp)": "韋 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韋犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韋", "Unihan_Simplified (Chữ Giản thể)": "韨", "Unihan_Traditional (Chữ Phồn thể)": "韍", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ trang phục lễ nghi che đầu gối của quý tộc xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颩', '{"9000": "8381.0", "Chữ Trung Quốc": "颩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 12 | nét | 颩 | tiêu | tượng hình | chữ độc thể, bộ phong (風) | 颩 là chữ độc thể thuộc bộ Phong (風, gió). Wiktionary không có glyph origin. Nghĩa liên quan đến gió, có thể chỉ gió thổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ Phong (風, gió) — gió tiêu sắc (gió lành lạnh mùa thu), thổi vèo qua. | Gương Hán-Việt | tiêu — rất hiếm trong tiếng Việt | Mở khoá kiến thức | Biết 颩 (tiêu) giúp nhận ra các chữ cổ hiếm trong bộ Phong chỉ các loại gió.", "Tự nguyên_Xie": "Wiktionary ghi 颩 âm biāo, thuộc bộ Phong (風). Không có glyph origin hay định nghĩa rõ ràng. Chữ tạo muộn, chưa thấy glyph origin. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"丢\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "風 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴風彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "風", "Unihan_Simplified (Chữ Giản thể)": "颩", "Unihan_Traditional (Chữ Phồn thể)": "颩", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "bưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động vứt bỏ hoặc gió thổi mạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飦', '{"9000": "8382.0", "Chữ Trung Quốc": "飦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 11 | nét | 飦 | chiên | tượng hình | cháo đặc, thức ăn nấu nhừ | 飦 là chữ độc thể thuộc bộ 食 (thực), chỉ loại cháo nấu đặc sệt. Chưa xác định rõ cấu trúc hình-thanh hay hội-ý từ nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": bộ 食 (thức ăn) gợi hình ảnh nồi cháo sệt sền sệt — 飦 là cháo đặc, thức ăn nấu nhừ dùng cho người yếu. | Gương Hán-Việt | chiên — ít dùng trong tiếng Việt hiện đại; xuất hiện trong văn chương cổ chỉ cháo đặc | Mở khoá kiến thức | Biết 飦 mở khoá nhóm chữ thức ăn nấu chín thuộc bộ 食 như 餔, 餐, 饘.", "Tự nguyên_Xie": "Chữ 飦 thuộc bộ 食 (thực: ăn, thức ăn), đọc zhān, chỉ cháo đặc hoặc cháo bồi. Nguồn Wiktionary chỉ ghi ''{{Han etym}}'' mà không có phân tích cụ thể. Dựa trên bộ thủ 食, chữ này liên quan đến thức ăn được nấu kỹ. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháo đặc; cháo bồi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "飠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "干", "Unihan_Simplified (Chữ Giản thể)": "飦", "Unihan_Traditional (Chữ Phồn thể)": "飦", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ món cháo đặc trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駋', '{"9000": "8383.0", "Chữ Trung Quốc": "駋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 駋 | triệu | tượng hình | ngựa (dạng cổ, chưa rõ cấu trúc) | 駋 thuộc bộ 馬 (mã), chỉ một loài ngựa. Không có dữ liệu Wiktionary phân tích cấu trúc; chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệu\": bộ 馬 (ngựa) — 駋 là một loài ngựa cổ; hình ảnh con ngựa phi nước đại vào buổi sáng (zhāo = sáng sớm âm tương tự). | Gương Hán-Việt | triệu — không xuất hiện trong từ Hán-Việt thông dụng hiện đại | Mở khoá kiến thức | Biết 駋 giúp nhận diện nhóm chữ ngựa hiếm thuộc bộ 馬 trong văn bản cổ.", "Tự nguyên_Xie": "Chữ 駋 thuộc bộ 馬 (mã: ngựa), đọc zhāo. Không tìm thấy phân tích nguồn gốc trong Wiktionary. Dựa vào bộ thủ, đây là chữ chỉ loài ngựa hoặc đặc tính của ngựa. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(ngựa)", "Hạng Tần Suất (Jun Da)": "8383.0", "Tần Suất % (Jun Da)": "99.9996134447", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駋", "Unihan_Traditional (Chữ Phồn thể)": "駋", "Pinyin_Xie": "zhāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống ngựa có màu lông pha trộn đặc biệt thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騄', '{"9000": "8384.0", "Chữ Trung Quốc": "騄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 18 | nét | 騄 | lục | tượng hình | tên ngựa thần huyền thoại | 騄 thuộc bộ 馬 (mã), là tên riêng của con ngựa thần 騄駬 trong thần thoại Trung Hoa. Không có phân tích cấu trúc hình-thanh hay hội-ý từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": 騄 là tên con thần mã 騄駬 — ngựa phi nhanh như gió, xuất hiện trong thần thoại Trung Hoa cổ đại. | Gương Hán-Việt | lục — không xuất hiện trong từ Hán-Việt thông dụng; chỉ dùng trong tên ngựa thần 騄駬 | Mở khoá kiến thức | Biết 騄 giúp đọc hiểu văn bản thần thoại cổ đề cập đến bát tuấn mã (tám con ngựa thần).", "Tự nguyên_Xie": "Wiktionary ghi 騄 chỉ dùng trong tên ghép 騄駬 — tên một con ngựa chạy nhanh huyền thoại. Đọc lù (Hán-Việt: lục). Thuộc bộ 馬 (mã). Không có phân tích cấu tạo chi tiết, chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "騄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "𫘧", "Unihan_Traditional (Chữ Phồn thể)": "騄", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của loài ngựa chạy nhanh thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骩', '{"9000": "8385.0", "Chữ Trung Quốc": "骩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 11 | nét | 骩 | ổi | tượng hình | xương (bộ 骨), cấu trúc không rõ | 骩 thuộc bộ 骨 (cốt: xương), đọc wěi. Không có dữ liệu Wiktionary phân tích cấu trúc. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ổi\": bộ 骨 (xương) — 骩 liên quan đến xương người hoặc thú, xuất hiện trong văn bản y học hoặc giải phẫu cổ đại. | Gương Hán-Việt | ổi — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 骩 giúp nhận diện các chữ xương hiếm thuộc bộ 骨 trong văn bản y học cổ.", "Tự nguyên_Xie": "Chữ 骩 thuộc bộ 骨 (cốt: xương), đọc wěi. Không tìm thấy phân tích nguồn gốc trong Wiktionary. Nghĩa không rõ ràng, có thể chỉ một bộ phận xương cụ thể. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "骩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 九", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨九", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骩", "Unihan_Traditional (Chữ Phồn thể)": "骩", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "uỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả trạng thái xương bị cong hoặc uốn lượn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骻', '{"9000": "8386.0", "Chữ Trung Quốc": "骻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骻 | khoa | tượng hình | xương hông, chỗ lồi ở đầu xương (bộ 骨) | 骻 thuộc bộ 骨 (cốt: xương), đọc kuà. Wiktionary ghi ''{{Han etym}}'' không phân tích chi tiết. Có thể là chữ hình-thanh với 骨 biểu nghĩa, nhưng chưa xác nhận được thành phần biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoa\": bộ 骨 (xương) + âm kuà — 骻 chỉ xương hông, vùng hông của cơ thể, liên quan đến 胯 (khoa: hông). | Gương Hán-Việt | khoa — gần với 胯 (khoa: hông); xuất hiện trong văn bản y học cổ đại | Mở khoá kiến thức | Biết 骻 giúp đọc mô tả giải phẫu cổ về vùng xương hông và khớp háng.", "Tự nguyên_Xie": "Chữ 骻 thuộc bộ 骨 (cốt: xương), đọc kuà (Hán-Việt: khoa). Wiktionary không cung cấp phân tích cấu tạo, chỉ ghi rfdef (cần định nghĩa). Nghĩa gốc liên quan đến vùng hông, xương hông — tương tự 胯 (khoa: hông, háng). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoá; như \"khoá (chỗ u ở đầu xương)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骻", "Unihan_Traditional (Chữ Phồn thể)": "骻", "Pinyin_Xie": "kuà", "Âm Hán Việt_Xie": "khoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận hông hoặc vùng xương chậu của cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骾', '{"9000": "8387.0", "Chữ Trung Quốc": "骾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 16 | nét | 骾 | ngạnh | tượng hình | xương cá; người cứng cỏi, ngay thẳng (bộ 骨) | 骾 thuộc bộ 骨 (cốt: xương), là dị thể của 鯁 (ngạnh). Wiktionary ghi ''{{zh-see|鯁|v}}'' — chữ này chỉ là biến thể của 鯁. Chưa phân tích được cấu trúc hình-thanh riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạnh\": bộ 骨 (xương) — 骾 là xương cá mắc cổ, hình ảnh vật cứng sắc không thể nuốt trôi, gợi tính cách người ngay thẳng không chịu khuất phục. | Gương Hán-Việt | ngạnh — xuất hiện trong 骾直 (ngạnh trực: cứng cỏi thẳng thắn); gần với 鯁 thường dùng hơn | Mở khoá kiến thức | Biết 骾 mở khoá từ 鯁骾 chỉ người cứng cỏi, liêm trực trong văn ngôn cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 骾 là dị thể (variant) của 鯁 (ngạnh). 鯁 = 魚 (ngư: cá) + 更 (canh: biểu âm), chữ hình-thanh chỉ xương cá hoặc vật mắc trong cổ họng. Từ 骾, bộ 骨 (xương) thay cho 魚, gợi ý về vật cứng sắc mắc vào. Nghĩa mở rộng: người ngay thẳng, không nịnh nọt. Có ảnh Tiểu triện từ hanziyuan. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương cá; hóc xương; người ngay thẳng không nịnh nọt", "Hạng Tần Suất (Jun Da)": "5548.0", "Tần Suất % (Jun Da)": "99.962691214", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "鲠", "Unihan_Traditional (Chữ Phồn thể)": "骾", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "ngạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc bị hóc xương hoặc làm tính từ chỉ tính cách cương trực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬙', '{"9000": "8388.0", "Chữ Trung Quốc": "鬙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 22 | nét | 髟 | biểu nghĩa | tóc, lông dài | 曾 | tằng | biểu âm | gợi âm sēng/zēng | 鬙 = 髟 (biểu nghĩa: tóc dài, lông) + 曾 (Tằng, biểu âm); chữ hình thanh. Bộ 髟 xác định nghĩa liên quan đến tóc, 曾 cung cấp âm đọc sēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tăng\": bộ 髟 (tóc dài) + 曾 (tằng, âm sēng) — 鬙 vẽ hình mái tóc rối như đám mây, mọc lên chồng chất như chữ 曾 (nhiều tầng). | Gương Hán-Việt | tăng — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鬙 giúp đọc từ 鬅鬙 (tóc xõa rối bù) trong thơ văn cổ Hán.", "Tự nguyên_Xie": "Wiktionary ghi: {{Han compound|髟|曾|c1=s|c2=p|ls=psc|t1=hair}} — chữ hình thanh, 髟 biểu nghĩa ''tóc'', 曾 (tằng) biểu âm. Nghĩa ghi nhận là tóc rối bù, tóc xơ xác. Xuất hiện trong từ ghép 鬅鬙 (tóc rối bù). Chữ cổ ít dùng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc mượt", "Hạng Tần Suất (Jun Da)": "8388.0", "Tần Suất % (Jun Da)": "99.9996160286", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬙", "Unihan_Traditional (Chữ Phồn thể)": "鬙", "Pinyin_Xie": "sēng", "Âm Hán Việt_Xie": "tăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả đầu tóc rối bù, thường dùng trong từ ghép tăng tam. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬽', '{"9000": "8389.0", "Chữ Trung Quốc": "鬽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 12 | nét | 鬽 | mị | tượng hình | ma quỷ, quỷ mị (bộ 鬼) | 鬽 thuộc bộ 鬼 (quỷ: ma quỷ), là dị thể của 魅 (mị). Không có phân tích cấu trúc từ Wiktionary. Chữ chỉ loại quỷ mị trong thần thoại dân gian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": bộ 鬼 (quỷ) — 鬽 là loài quỷ mị ẩn trong rừng núi, dụ dỗ người lạc đường; dị thể của 魅 thường gặp trong 魑魅魍魉 (li mị võng lượng: bốn loại quỷ dữ). | Gương Hán-Việt | mị — xuất hiện trong 魑魅 (li mị: quỷ rừng núi); dị thể 魅 thông dụng hơn | Mở khoá kiến thức | Biết 鬽 (và dạng chính 魅) mở khoá từ 魑魅魍魉 — thành ngữ chỉ mọi loại yêu ma quỷ quái.", "Tự nguyên_Xie": "Chữ 鬽 thuộc bộ 鬼 (quỷ), là dị thể của 魅 (mị: quỷ mị, yêu quái). Không tìm thấy phân tích cấu tạo trong Wiktionary. Nghĩa gốc là ma quỷ, yêu tinh, thường dùng trong từ ghép 魑魅 (li mị: các loài quỷ dữ). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mị; như \"si mị hỉ (ma quỷ)\" \nCũng như mị 魅.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 彡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼彡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "鬽", "Unihan_Traditional (Chữ Phồn thể)": "鬽", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài yêu ma quỷ quái hại người trong truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魫', '{"9000": "8390.0", "Chữ Trung Quốc": "魫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魫 | thẩm | tượng hình | cá con, cá nhỏ mới nở (bộ 魚) | 魫 thuộc bộ 魚 (ngư: cá), đọc shěn. Wiktionary không cung cấp phân tích cấu tạo (rfdef). Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": bộ 魚 (cá) — 魫 là những con cá nhỏ li ti mới nở, bơi lội thành đàn dày đặc dưới nước. | Gương Hán-Việt | thẩm — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 魫 giúp đọc mô tả về cá non trong văn bản ngư nghiệp và thiên nhiên cổ đại.", "Tự nguyên_Xie": "Chữ 魫 thuộc bộ 魚 (ngư: cá), đọc shěn (Hán-Việt: thẩm). Wiktionary chỉ ghi phát âm mà không có định nghĩa hay phân tích cấu tạo. Nghĩa được ghi nhận là ''cá con, cá mới nở''. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "髫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魫", "Unihan_Traditional (Chữ Phồn thể)": "魫", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần xương đầu của cá hoặc một loại cá cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯈', '{"9000": "8391.0", "Chữ Trung Quốc": "鯈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鯈 | điều | tượng hình | cá du, cá nhỏ bơi thành đàn (bộ 魚) | 鯈 thuộc bộ 魚 (ngư: cá), đọc tiáo. Không có phân tích cấu trúc từ Wiktionary. Chữ chỉ loài cá nhỏ bơi tự do, xuất hiện trong các ẩn dụ triết học Trang Tử.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điều\": bộ 魚 (cá) — 鯈 là con cá tự tại trong Trang Tử: 鯈魚出游從容 — cá 鯈 bơi lội ung dung, biểu tượng của tự do thoát tục. | Gương Hán-Việt | điều — xuất hiện trong văn triết học Trang Tử; không dùng trong hội thoại thường ngày | Mở khoá kiến thức | Biết 鯈 mở khoá đoạn triết học nổi tiếng trong Trang Tử về cá bơi lội tự tại và câu hỏi về hạnh phúc.", "Tự nguyên_Xie": "Chữ 鯈 thuộc bộ 魚 (ngư), đọc tiáo (Hán-Việt: điều). Không có phân tích cấu tạo từ Wiktionary. Nổi tiếng nhất qua Trang Tử: 鯈魚出游從容 (cá 鯈 bơi lội tự tại ung dung), dùng làm ẩn dụ về sự tự do. Chưa có nguồn học thuật đầy đủ về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá du", "Hạng Tần Suất (Jun Da)": "8391.0", "Tần Suất % (Jun Da)": "99.999617579", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鯈", "Unihan_Traditional (Chữ Phồn thể)": "鯈", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nhỏ thân dài sống ở sông ngòi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯩', '{"9000": "8392.0", "Chữ Trung Quốc": "鯩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯩 | luân | tượng hình | cá giống cá chép có sọc đen (bộ 魚) | 鯩 thuộc bộ 魚 (ngư: cá), đọc lún. Wiktionary không phân tích cấu tạo. Chữ chỉ loài cá giống cá chép có sọc đen, nay đã lỗi thời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": bộ 魚 (cá) + âm lún — 鯩 là con cá chép sọc đen đã bị lãng quên theo thời gian, như bánh xe (luân: bánh xe) quay mãi rồi chìm vào quá khứ. | Gương Hán-Việt | luân — không dùng trong tiếng Việt hiện đại; chữ cá cổ lỗi thời | Mở khoá kiến thức | Biết 鯩 giúp nhận diện tên loài cá cổ trong văn bản sinh vật học Hán văn.", "Tự nguyên_Xie": "Wiktionary ghi 鯩 là loài cá giống cá chép (crucian carp) có sọc đen, hiện không còn dùng (obsolete). Đọc lún (Hán-Việt: luân). Thuộc bộ 魚. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "驩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 侖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚侖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯩", "Unihan_Traditional (Chữ Phồn thể)": "鯩", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chuyên dùng để gọi tên một loài cá trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯬', '{"9000": "8393.0", "Chữ Trung Quốc": "鯬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯬 | lê | tượng hình | tên cá, dị thể 鰣 (cá mòi/cá hoa) (bộ 魚) | 鯬 thuộc bộ 魚 (ngư: cá), đọc lí. Wiktionary ghi là dạng không chuẩn của 鰣. Chưa phân tích được cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": bộ 魚 (cá) — 鯬 là tên cổ của cá 鰣 (cá mòi sông), loài cá ngon nổi tiếng trong ẩm thực Giang Nam xưa. | Gương Hán-Việt | lê — không dùng trong tiếng Việt hiện đại; dị thể của 鰣 (cá mòi) | Mở khoá kiến thức | Biết 鯬 giúp nhận ra tên cổ của loài cá 鰣 — cá đặc sản Giang Nam nổi tiếng trong thơ văn Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi 鯬 là dạng không chuẩn (obs-std) của 鰣 — loài cá {{taxlink|Tenualosa reevesii|species}}, cá mòi sông (Reeves'' shad). Đọc lí (Hán-Việt: lê). Thuộc bộ 魚. Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vu khống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 魚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鯬", "Unihan_Traditional (Chữ Phồn thể)": "鯬", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành vi vu cáo hoặc đổ oan cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰌', '{"9000": "8394.0", "Chữ Trung Quốc": "鰌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鰌 | thu | tượng hình | cá chạch; lươn (bộ 魚) | 鰌 thuộc bộ 魚 (ngư: cá), đọc qiū. Wiktionary chỉ ghi ''{{Han etym}}'' không phân tích chi tiết. Có ảnh Tiểu triện từ hanziyuan. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": bộ 魚 (cá) — 鰌 là con cá chạch trơn trượt, uốn lượn như làn sóng mùa thu trong bùn nước. | Gương Hán-Việt | thu — không phổ biến trong từ Hán-Việt thông dụng; tương đương cá chạch (泥鳅) | Mở khoá kiến thức | Biết 鰌 giúp nhận diện tên cổ của cá chạch trong văn bản y học và ẩm thực Hán cổ.", "Tự nguyên_Xie": "Tiểu triện | Chữ 鰌 thuộc bộ 魚 (ngư: cá), đọc qiū (Hán-Việt: thu). Wiktionary ghi ''{{Han etym}}'' không có phân tích cụ thể. Nghĩa chỉ cá chạch (loach), lươn. Có ảnh Tiểu triện từ hanziyuan cho thấy chữ này đã dùng từ thời tiền Tần. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 酋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚酋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰌", "Unihan_Traditional (Chữ Phồn thể)": "鰌", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá chạch thường sống ở vùng bùn lầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲓', '{"9000": "8395.0", "Chữ Trung Quốc": "鲓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲓 | khảo | tượng hình | loài cá (bộ 魚, cấu trúc không rõ) | 鲓 thuộc bộ 魚 (ngư: cá, dạng giản thể 鱼), đọc kǎo. Không có phân tích cấu trúc từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảo\": bộ 魚 (cá) + âm kǎo — 鲓 là một loài cá chưa được xác định rõ trong văn bản cổ Hán. | Gương Hán-Việt | khảo — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鲓 giúp nhận diện tên cá hiếm trong văn bản ngư nghiệp cổ đại Hán.", "Tự nguyên_Xie": "Chữ 鲓 thuộc bộ 魚 (ngư: cá, dạng giản thể), đọc kǎo (Hán-Việt: khảo). Không tìm thấy phân tích nguồn gốc trong Wiktionary. Nghĩa không rõ, chỉ biết là loại cá. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "铓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 考", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼考", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "考", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲓", "Unihan_Traditional (Chữ Phồn thể)": "鲓", "Pinyin_Xie": "kǎo", "Âm Hán Việt_Xie": "khảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để chỉ các loại cá nhỏ được phơi khô hoặc ướp muối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴂', '{"9000": "8396.0", "Chữ Trung Quốc": "鴂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鴂 | quyết | tượng hình | chim bách thiệt, dị thể 鴃 (bộ 鳥) | 鴂 thuộc bộ 鳥 (điểu: chim), là dị thể của 鴃 (quyết). Wiktionary ghi ''{{zh-see|鴃|v}}''. Chưa phân tích được cấu trúc riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": bộ 鳥 (chim) — 鴂 là chim bách thiệt, kêu được trăm loại tiếng, dị thể của 鴃 thường gặp hơn trong thơ Tống. | Gương Hán-Việt | quyết — xuất hiện trong thơ cổ 鴂舌 (giọng chim bách thiệt, ý nói tiếng khó hiểu) | Mở khoá kiến thức | Biết 鴂 mở khoá từ 鴂舌 (quyết thiệt) trong thơ văn Tống, chỉ tiếng nói lạ tai, khó hiểu.", "Tự nguyên_Xie": "Wiktionary ghi 鴂 là dị thể của 鴃 (quyết: chim bách thiệt, chim thợ may). Thuộc bộ 鳥 (điểu). Chim này nổi tiếng bắt chước tiếng kêu của nhiều loài chim khác. Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim bách thiệt (kêu được trăm thứ tiếng)", "Hạng Tần Suất (Jun Da)": "8396.0", "Tần Suất % (Jun Da)": "99.9996201629", "GavinGrover_Once (Chiết tự trực tiếp)": "夬 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夬鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴂", "Unihan_Traditional (Chữ Phồn thể)": "鴂", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim bách thanh nổi tiếng với tiếng hót đa dạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶍', '{"9000": "8397.0", "Chữ Trung Quốc": "鶍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶍 | y | tượng hình | loài chim (bộ 鳥, cấu trúc không rõ) | 鶍 thuộc bộ 鳥 (điểu: chim), đọc yi. Không có phân tích cấu trúc từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": bộ 鳥 (chim) — 鶍 là một loài chim hiếm trong văn bản cổ, chưa được xác định rõ tên khoa học. | Gương Hán-Việt | y — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鶍 giúp nhận diện tên chim hiếm trong danh lục điểu loại học Hán cổ.", "Tự nguyên_Xie": "Chữ 鶍 thuộc bộ 鳥 (điểu: chim), đọc yi. Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Nghĩa không rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鶍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "易 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰易鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶍", "Unihan_Traditional (Chữ Phồn thể)": "鶍", "Pinyin_Xie": "yi", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nhỏ thuộc họ sẻ có mỏ chéo nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶠', '{"9000": "8398.0", "Chữ Trung Quốc": "鶠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 20 | nét | 鶠 | yển | tượng hình | phượng hoàng (tên cổ), bộ 鳥 | 鶠 thuộc bộ 鳥 (điểu: chim), đọc yǎn. Wiktionary ghi là tên cổ (obs-std) của 鳳凰 (phượng hoàng). Chưa phân tích cấu trúc riêng. Có ảnh Tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": bộ 鳥 (chim) — 鶠 là tên cổ của phượng hoàng, chim thần trong thần thoại Hán, biểu tượng của vẻ đẹp và đức hạnh hoàng gia. | Gương Hán-Việt | yển — không dùng thông dụng; tên cổ của phượng hoàng trong thư tịch cổ Hán | Mở khoá kiến thức | Biết 鶠 mở khoá nhóm tên cổ của phượng hoàng trong thư tịch Hán cổ đại — 鳳凰, 鶠, 鸑鷟 đều là cách gọi chim thần.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鶠 là tên cổ của 鳳凰 (phượng hoàng, Chinese phoenix). Đọc yǎn (Hán-Việt: yển). Thuộc bộ 鳥. Không có phân tích cấu tạo. Có ảnh Tiểu triện. Phượng hoàng trong thần thoại Hán là chim thần biểu trưng cho đức hạnh và thái bình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yến; như \"yến (Chim nhỏ; chim sâu; chim cun cút)\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "匽 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰匽鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶠", "Unihan_Traditional (Chữ Phồn thể)": "鶠", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nhỏ thuộc bộ gà giống như chim cút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷁', '{"9000": "8399.0", "Chữ Trung Quốc": "鷁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 21 | nét | 鷁 | ức | tượng hình | chim diều hâu biển; đầu mũi thuyền (bộ 鳥) | 鷁 thuộc bộ 鳥 (điểu: chim), đọc yì. Wiktionary chỉ ghi ''{{Han etym}}'' không phân tích chi tiết. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ức\": bộ 鳥 (chim) — 鷁 là chim diều hâu biển, hình của nó được khắc lên mũi thuyền cổ để trấn tà và cầu may mắn trên biển. | Gương Hán-Việt | ức — xuất hiện trong 鷁首 (ức thủ: mũi thuyền có hình chim 鷁) trong thơ văn cổ | Mở khoá kiến thức | Biết 鷁 mở khoá từ 鷁首 (mũi thuyền) và 鷁舟 (ức chu: thuyền cổ) trong thơ văn Đường Tống.", "Tự nguyên_Xie": "Chữ 鷁 thuộc bộ 鳥 (điểu), đọc yì (Hán-Việt: ức). Nghĩa: chim diều hâu biển (fishhawk), đồng thời nghĩa mũi thuyền (bow/prow) vì thuyền cổ Trung Hoa hay vẽ hình chim 鷁 trên mũi. Wiktionary ghi ''{{Han etym}}'' không có phân tích. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "diều", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "益 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰益鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹢", "Unihan_Traditional (Chữ Phồn thể)": "鷁", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim nước lớn thường được vẽ hình trên mũi thuyền thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷖', '{"9000": "8400.0", "Chữ Trung Quốc": "鷖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 鷖 | y | tượng hình | hải âu; tên khác của phượng hoàng (bộ 鳥) | 鷖 thuộc bộ 鳥 (điểu: chim), đọc yī. Wiktionary không phân tích cấu trúc chi tiết. Có ảnh Tiểu triện. Nghĩa phức tạp: vừa là hải âu, vừa là tên khác của phượng hoàng theo Vương Dật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\": bộ 鳥 (chim) — 鷖 vừa là hải âu lướt sóng, vừa được Vương Dật gọi là tên khác của phượng hoàng — chim nhỏ và chim thần cùng một chữ. | Gương Hán-Việt | y — xuất hiện trong 鳧鷖 (phù y: vịt trời và hải âu) trong Kinh Thi và Sở Từ | Mở khoá kiến thức | Biết 鷖 mở khoá đoạn Sở Từ với hình ảnh hải âu và phượng hoàng, biểu tượng tự do và cao quý.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鷖 là hải âu hoặc vịt trời (wigeon), đồng thời Vương Dật chú giải ''a nickname of the fenghuang'' (tên khác của phượng hoàng). Đọc yī/yì. Có trích dẫn từ Sở Từ và Bí Nhã. Bộ 鳥. Có ảnh Tiểu triện. Không có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gà lôi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "殹 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殹鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹥", "Unihan_Traditional (Chữ Phồn thể)": "鷖", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim nước thường sống ở vùng ven biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸇', '{"9000": "8401.0", "Chữ Trung Quốc": "鸇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 24 | nét | 鸇 | chiên | tượng hình | chim giống diều hâu nhỏ (bộ 鳥) | 鸇 thuộc bộ 鳥 (điểu: chim), đọc zhān. Wiktionary ghi ''{{Han etym}}'' không phân tích chi tiết. Có ảnh Tiểu triện từ wikimedia. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": bộ 鳥 (chim) — 鸇 là chim giống diều hâu nhỏ, mắt sắc bén như thép; thành ngữ 鸇視狼顧 dùng chim này để ví ánh mắt hung dữ, thâm độc. | Gương Hán-Việt | chiên — xuất hiện trong 鷹鸇 (ưng chiên: đại bàng và diều) trong thơ văn cổ | Mở khoá kiến thức | Biết 鸇 mở khoá thành ngữ 鸇視狼顧 (chiên thị lang cố) — nhìn như diều hâu, liếc như sói: mô tả kẻ hung ác xảo quyệt.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鸇 là loài chim giống diều hâu nhỏ (sparrow hawk), thuộc lịch sử/văn học cổ. Đọc zhān (Hán-Việt: chiên). Bộ 鳥. Từ ghép: 鷹鸇 (ưng chiên: đại bàng và diều hâu), 鸇視狼顧 (nhìn như chim 鸇 ngó như sói — mô tả cái nhìn hung ác). Có ảnh Tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim ưng", "Hạng Tần Suất (Jun Da)": "7140.0", "Tần Suất % (Jun Da)": "99.9975519888", "GavinGrover_Once (Chiết tự trực tiếp)": "亶 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亶鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹯", "Unihan_Traditional (Chữ Phồn thể)": "鸇", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim săn mồi dũng mãnh thuộc họ ưng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸘', '{"9000": "8402.0", "Chữ Trung Quốc": "鸘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 28 | nét | 鸘 | sương | tượng hình | chim 鷫鸘 (túc sương), loại chim huyền thoại (bộ 鳥) | 鸘 thuộc bộ 鳥 (điểu: chim), đọc shuāng. Wiktionary ghi chỉ dùng trong 鷫鸘 — dị thể của 鷫鷞. Chưa phân tích cấu trúc riêng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sương\": bộ 鳥 (chim) + âm shuāng (sương: sương giá) — 鸘 là chim 鷫鸘 bay trong làn sương lạnh phương Bắc, chỉ xuất hiện trong thơ văn huyền bí cổ đại. | Gương Hán-Việt | sương — xuất hiện trong tên 鷫鸘 (túc sương) trong thơ Sở Từ; không dùng độc lập | Mở khoá kiến thức | Biết 鸘 mở khoá từ 鷫鸘/鷫鷞 trong thơ Sở từ và văn học Hán cổ về chim thần phương Bắc.", "Tự nguyên_Xie": "Wiktionary ghi 鸘 chỉ dùng trong từ ghép 鷫鸘 (variant của 鷫鷞), chỉ loài chim huyền thoại phương Bắc. Đọc shuāng (Hán-Việt: sương). Bộ 鳥. Không có phân tích cấu tạo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sương cưu 鷞鳩,鹴鸠; túc sương 鷫鷞,鹔鹴)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "霜 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰霜鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鹴", "Unihan_Traditional (Chữ Phồn thể)": "鸘", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "sương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong các từ ghép chỉ loài chim nước cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸧', '{"9000": "8403.0", "Chữ Trung Quốc": "鸧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 9 | nét | 鸧 | thương | tượng hình | tên chim (dạng giản thể của 鶬), bộ 鳥 | 鸧 là dạng giản thể của 鶬 (thương), thuộc bộ 鳥 (điểu: chim), đọc cāng/qiāng. Wiktionary phân tích từ dạng phồn thể 鶬. Có ảnh Tiểu triện. Chưa phân tích cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": bộ 鳥 (chim) — 鸧 (thương) là loài chim lớn màu xám xanh như màu trời xanh biếc (thương: màu xanh ngọc), bay thành đàn trên đồng lúa. | Gương Hán-Việt | thương — xuất hiện trong 鶬鴰 (thương quát: hạc Nhật Bản) trong văn bản điểu loại học cổ | Mở khoá kiến thức | Biết 鸧 mở khoá từ 鶬鴰 (thương quát) — tên Hán cổ của hạc Nhật Bản và nhóm chim lớn màu xám trong văn học.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi từ dạng phồn thể 鶬: chỉ loài chim 鶬鴰 (xác định là Grus vipio — hạc Nhật Bản), hoặc Ardea cinerea (cò xám), hoặc chim thần thoại, và nghĩa bóng ''ánh sáng vàng kim'' trong 鶬鶬. Đọc cāng (thương) hoặc qiāng. Có ảnh Tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thương quát 鶬鴰,鸧鸹)", "Hạng Tần Suất (Jun Da)": "8403.0", "Tần Suất % (Jun Da)": "99.9996237804", "GavinGrover_Once (Chiết tự trực tiếp)": "仓 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰仓鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸧", "Unihan_Traditional (Chữ Phồn thể)": "鶬", "Pinyin_Xie": "cāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp để chỉ loài chim nước lớn có hình dáng giống chim hạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹙', '{"9000": "8404.0", "Chữ Trung Quốc": "鹙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 14 | nét | 鹙 | thu | tượng hình | cò già đầu trọc, dạng giản thể 鶖 (bộ 鳥) | 鹙 là dạng giản thể của 鶖 (thu), thuộc bộ 鳥 (điểu: chim), đọc qiū. Wiktionary phân tích từ dạng 鶖. Có ảnh Tiểu triện. Chưa phân tích cấu trúc hình-thanh riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": bộ 鳥 (chim) — 鹙 là cò già đầu trọc, đứng lặng yên bên hồ mùa thu, như một ẩn sĩ già. | Gương Hán-Việt | thu — xuất hiện trong 禿鶖 (tú thu: chim đầu trọc) trong văn bản điểu loại học và thơ cổ | Mở khoá kiến thức | Biết 鹙 mở khoá từ 禿鶖 (tú thu) — chim đầu trọc lớn, biểu tượng người già cô độc trong thơ Hán.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 鶖 (dạng phồn thể của 鹙) là chim Eurasian jay (Garrulus glandarius). Đọc qiū (Hán-Việt: thu). Bộ 鳥. Cũng được nhận diện là loài chim nước đầu trọc. Có ảnh Tiểu triện. Từ ghép: 禿鶖 (đầu trọc), 鵚鶖. Chưa có phân tích cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cò già (một loài chim nước)", "Hạng Tần Suất (Jun Da)": "8404.0", "Tần Suất % (Jun Da)": "99.9996242972", "GavinGrover_Once (Chiết tự trực tiếp)": "秋 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱秋鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹙", "Unihan_Traditional (Chữ Phồn thể)": "鶖", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim nước lớn thuộc họ hạc có đặc điểm đầu hói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麏', '{"9000": "8405.0", "Chữ Trung Quốc": "麏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 18 | nét | 麏 | quân | tượng hình | loài nai nhỏ, hươu (bộ 鹿) | 麏 thuộc bộ 鹿 (lộc: hươu nai), đọc jūn. Không có phân tích cấu trúc từ Wiktionary. Chưa xác định hình-thanh hay hội-ý. Chữ chỉ loài nai/hươu nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": bộ 鹿 (hươu nai) + âm jūn (quân: đông đảo) — 麏 là loài nai nhỏ đi thành đàn trong rừng, như đội quân (quân) của vua rừng. | Gương Hán-Việt | quân — không xuất hiện trong từ Hán-Việt thông dụng; chữ nai/hươu cổ | Mở khoá kiến thức | Biết 麏 giúp nhận diện tên các loài hươu nai cổ trong văn bản săn bắn và thiên nhiên Hán cổ.", "Tự nguyên_Xie": "Chữ 麏 thuộc bộ 鹿 (lộc: hươu nai), đọc jūn (Hán-Việt: quân). Không tìm thấy phân tích nguồn gốc trong Wiktionary. Nghĩa ghi là loài nai nhỏ. Chữ hiếm trong văn bản cổ về động vật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu mùi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鹿 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鹿君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麏", "Unihan_Traditional (Chữ Phồn thể)": "麏", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài hươu nhỏ trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黮', '{"9000": "8406.0", "Chữ Trung Quốc": "黮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 21 | nét | 黮 | đảm | tượng hình | màu đen tối; không rõ ràng (bộ 黑) | 黮 thuộc bộ 黑 (hắc: đen), đọc dǎn. Wiktionary chỉ ghi ''{{Han etym}}'' không phân tích chi tiết. Có ảnh Đại triện. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảm\": bộ 黑 (đen) — 黮 là màu đen mờ đục, tối tăm, không minh bạch; như cái đảm (gan mật đen) ẩn trong bóng tối. | Gương Hán-Việt | đảm — không phổ biến trong từ Hán-Việt thông dụng; xuất hiện trong văn học cổ về màu sắc và bóng tối | Mở khoá kiến thức | Biết 黮 mở khoá nhóm từ bộ 黑 chỉ sắc đen đặc biệt như 黯 (ám: tối), 黛 (đại: đen xanh).", "Tự nguyên_Xie": "Đại triện | Chữ 黮 thuộc bộ 黑 (hắc: đen tối), đọc dǎn (Hán-Việt: đảm). Wiktionary ghi ''{{Han etym}}'' không phân tích cụ thể. Nghĩa: màu đen, tối; mờ nhạt, không trong sáng; riêng tư, bí mật. Có ảnh Đại triện từ wikimedia cho thấy chữ này có từ thời kim văn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đen; không trong sáng, không rõ ràng, riêng tư", "Hạng Tần Suất (Jun Da)": "8406.0", "Tần Suất % (Jun Da)": "99.9996253308", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黮", "Unihan_Traditional (Chữ Phồn thể)": "黮", "Pinyin_Xie": "dǎn", "Âm Hán Việt_Xie": "đạm, thảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để tả màu sắc đen tối hoặc trạng thái mờ mịt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齯', '{"9000": "8407.0", "Chữ Trung Quốc": "齯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 23 | nét | 齯 | nghê | tượng hình | răng mọc lại lúc già (bộ 齒) | 齯 thuộc bộ 齒 (xỉ: răng), đọc ní. Wiktionary ghi ''{{Han etym}}'' không phân tích chi tiết. Có ảnh Tiểu triện từ hanziyuan. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\": bộ 齒 (răng) — 齯 là hiện tượng kỳ diệu: người già đến bạch đầu bỗng mọc lại răng mới, điềm trường thọ trong y học Hán cổ. | Gương Hán-Việt | nghê — xuất hiện trong 齯齒 (nghê xỉ: răng mọc lại lúc già); biểu tượng trường thọ | Mở khoá kiến thức | Biết 齯 mở khoá từ 齯齒 — hiện tượng y học cổ và biểu tượng trường thọ trong văn hóa Hán.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 齯 là ''teeth grown in old age'' — răng mọc lại lúc tuổi già. Đọc ní (Hán-Việt: nghê). Bộ 齒 (xỉ: răng). Từ ghép 齯齒 (nghê xỉ: răng già mọc lại). Có ảnh Tiểu triện. Hiện tượng răng mọc lại ở người cao tuổi được ghi chép trong y học cổ Hán như điềm lành hoặc dấu hiệu thọ. Chưa có nguồn học thuật đầy đủ về cấu tạo. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "齯", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "𫠜", "Unihan_Traditional (Chữ Phồn thể)": "齯", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ hiện tượng người già mọc lại răng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龓', '{"9000": "8408.0", "Chữ Trung Quốc": "龓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 22 | nét | 龓 | lung | tượng hình | dây cương (bộ 龍) | 龓 thuộc bộ 龍 (long: rồng), đọc lǒng. Wiktionary chỉ ghi ''{{Han etym}}'' không phân tích chi tiết. Chưa xác định cấu trúc hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": bộ 龍 (rồng) + âm lǒng — 龓 là dây cương kiểm soát, như người cầm dây cương điều khiển con rồng hung hãn. | Gương Hán-Việt | lung — không xuất hiện trong từ Hán-Việt thông dụng; chữ rất hiếm | Mở khoá kiến thức | Biết 龓 giúp nhận diện nhóm chữ bộ 龍 chỉ vật dụng liên quan đến kiểm soát và quyền lực trong văn bản cổ.", "Tự nguyên_Xie": "Chữ 龓 thuộc bộ 龍 (long: rồng), đọc lǒng (Hán-Việt: lung). Wiktionary ghi ''{{Han etym}}'' không có phân tích cụ thể. Nghĩa: dây cương (halter). Bộ 龍 gợi liên tưởng đến việc điều khiển sức mạnh như rồng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "铓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "有 + 龍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰有龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龍", "Unihan_Simplified (Chữ Giản thể)": "龓", "Unihan_Traditional (Chữ Phồn thể)": "龓", "Pinyin_Xie": "lǒng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ thể hiện hành động bao trùm hoặc dắt, kéo đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盓', '{"9000": "8409.0", "Chữ Trung Quốc": "盓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 11 | nét | 盓 | ư | tượng hình | xoáy nước, vũng xoáy (bộ 皿) | 盓 thuộc bộ 皿 (mãnh: đồ đựng), đọc yū. Wiktionary ghi chỉ dùng trong 盤盓 (bàn ư: xoáy nước). Chưa phân tích cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ư\": bộ 皿 (đồ đựng) — 盓 là xoáy nước cuộn tròn như cái tách quay (bàn ư), hình ảnh nước xoay tròn trong lòng bát. | Gương Hán-Việt | ư — xuất hiện trong 盤盓 (bàn ư: xoáy nước) trong văn bản thủy lợi và thơ cổ | Mở khoá kiến thức | Biết 盓 mở khoá từ 盤盓 (xoáy nước, vũng xoáy) trong mô tả địa lý và thủy văn cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 盓 chỉ dùng trong từ ghép 盤盓 (bàn ư) với nghĩa ''water swirl; whirlpool'' — xoáy nước. Đọc yū hoặc wū (Hán-Việt: ư). Bộ 皿 (đồ đựng). Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tách", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "汙 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱汙皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "汙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盓", "Unihan_Traditional (Chữ Phồn thể)": "盓", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "ư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đồ đựng nước hoặc thức ăn dạng bát nhỏ trong tiếng Hán cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眕', '{"9000": "8410.0", "Chữ Trung Quốc": "眕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眕 | chẩn | tượng hình | nhìn chăm chú; tự chủ, kiềm chế (bộ 目) | 眕 thuộc bộ 目 (mục: mắt), đọc zhěn. Wiktionary ghi hai nghĩa: nhìn chăm chú và tự kiềm chế. Chưa phân tích cấu trúc hình-thanh hay hội-ý. Từ ghép: 眕眼, 眕眕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": bộ 目 (mắt) — 眕 là ánh mắt kiên định, nhìn thẳng không dao động, biểu tượng sự tự chủ và kiềm chế cảm xúc. | Gương Hán-Việt | chẩn — không phổ biến trong từ Hán-Việt thông dụng; xuất hiện trong văn học cổ về đức hạnh tự kiềm chế | Mở khoá kiến thức | Biết 眕 mở khoá từ 眕眕 (chẩn chẩn: điềm tĩnh, tự chủ) trong văn bản đạo đức học cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 眕 có hai nghĩa cổ: ''to gaze at; to look at'' (nhìn chăm chú) và ''self-controlled; self-restrained'' (tự kiềm chế). Đọc zhěn (Hán-Việt: chẩn). Bộ 目 (mắt). Không có phân tích cấu tạo. Từ ghép: 眕眼, 眕眕 (điềm tĩnh). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kiềm chế cơn tức giận", "Hạng Tần Suất (Jun Da)": "8410.0", "Tần Suất % (Jun Da)": "99.9996273979", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眕", "Unihan_Traditional (Chữ Phồn thể)": "眕", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động tự kiềm chế cảm xúc hoặc nhìn chăm chú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睘', '{"9000": "8411.0", "Chữ Trung Quốc": "睘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 袁 | viên | biểu âm | gợi âm qióng/yuán | 睘 = 目 (Mục, biểu nghĩa: mắt) + 袁 (Viên, biểu âm; thường được viết tắt); chữ hình thanh. Bộ 目 xác định nghĩa liên quan đến mắt, 袁 cung cấp âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": bộ 目 (mắt) + 袁 (viên, biểu âm) — 睘 là đôi mắt mở to tròn xoe vì kinh sợ hoặc ngạc nhiên, như hình tròn của chữ 袁. | Gương Hán-Việt | quỳnh — không dùng độc lập trong từ Hán-Việt; hiếm gặp ngoài văn học cổ | Mở khoá kiến thức | Biết 睘 giúp đọc mô tả ánh mắt kinh sợ, trố mắt trong thơ văn cổ Hán và kim văn.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Wiktionary ghi: {{Han compound|目|袁|c1=s|c2=p|t1=eye|ls=psc}}; 袁 thường được viết tắt. Chữ hình thanh: 目 (mục) biểu nghĩa ''mắt'', 袁 (viên) biểu âm. Nghĩa: mắt tròn trố nhìn kinh sợ; đăm đăm nhìn. Có ảnh Kim văn và Bạch thư từ wikimedia — chữ này có từ rất sớm. Đọc qióng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt nhìn kinh sợ", "Hạng Tần Suất (Jun Da)": "8411.0", "Tần Suất % (Jun Da)": "99.9996279147", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "睘", "Unihan_Traditional (Chữ Phồn thể)": "睘", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái cô độc hoặc ánh mắt sợ hãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睩', '{"9000": "8412.0", "Chữ Trung Quốc": "睩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 睩 | lộc | tượng hình | trừng mắt nhìn; đảo mắt (bộ 目) | 睩 thuộc bộ 目 (mục: mắt), đọc lù. Wiktionary ghi ''{{Han etym}}'' không phân tích chi tiết. Có ảnh Tiểu triện. Nghĩa: nhìn trừng (stare) và đảo mắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": bộ 目 (mắt) + âm lù (lộc) — 睩 là ánh mắt đảo tròn như hươu lộc (lộc) bị giật mình, biểu hiện ngạc nhiên hoặc tức giận. | Gương Hán-Việt | lộc — không phổ biến trong từ Hán-Việt thông dụng; xuất hiện trong 睩眼 (lộc nhãn: đảo mắt) | Mở khoá kiến thức | Biết 睩 mở khoá thành ngữ 吹鬚睩眼 (thổi râu đảo mắt) — diễn tả sự tức giận lộ ra qua cử chỉ mắt và mặt.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 睩 có hai nghĩa: (1) trừng mắt nhìn; (2) đảo mắt — dùng trong 曼睩 và 雙睩. Đọc lù (Hán-Việt: lộc). Bộ 目. Có ảnh Tiểu triện từ hanziyuan. Từ ghép: 眼睩睩 (mắt đảo), 吹鬚睩眼 (thổi râu đảo mắt — mô tả tức giận). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đảo mắt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睩", "Unihan_Traditional (Chữ Phồn thể)": "睩", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động đảo mắt hoặc nhìn chăm chú vào vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矂', '{"9000": "8413.0", "Chữ Trung Quốc": "矂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 18 | nét | 矂 | tao | tượng hình | (nghĩa không rõ, bộ 目) | 矂 thuộc bộ 目 (mục: mắt), đọc sào. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bộ 目 (mắt) — 矂 là ánh mắt gì đó liên quan đến mắt trong văn bản cực cổ, nghĩa chưa được làm rõ. | Gương Hán-Việt | tao — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 矂 giúp nhận diện chữ mắt hiếm trong văn bản cổ đại khi cần tra cứu.", "Tự nguyên_Xie": "Chữ 矂 thuộc bộ 目 (mục: mắt), đọc sào (Hán-Việt: tao). Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Nghĩa không rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "炂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矂", "Unihan_Traditional (Chữ Phồn thể)": "矂", "Pinyin_Xie": "sào", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái thị lực kém hoặc mắt bị mờ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矵', '{"9000": "8414.0", "Chữ Trung Quốc": "矵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 7 | nét | 矵 | khất | tượng hình | (nghĩa không rõ, bộ 石) | 矵 thuộc bộ 石 (thạch: đá), đọc qì. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khất\": bộ 石 (đá) + âm qì (khất/khí) — 矵 là loại đá hoặc đặc tính của đá trong văn bản khoáng vật học cổ đại. | Gương Hán-Việt | khất — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 矵 giúp nhận diện tên đá hiếm trong văn bản địa chất và khoáng vật học Hán cổ.", "Tự nguyên_Xie": "Chữ 矵 thuộc bộ 石 (thạch: đá), đọc qì (Hán-Việt: khất). Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Nghĩa không rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "矵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矵", "Unihan_Traditional (Chữ Phồn thể)": "矵", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "khất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ bậc thềm hoặc động từ chỉ hành động xây lát bằng đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矺', '{"9000": "8415.0", "Chữ Trung Quốc": "矺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 8 | nét | 矺 | trác | tượng hình | ấn chặt, ép đều (bộ 石, Quảng Đông) | 矺 thuộc bộ 石 (thạch: đá), đọc zhé. Wiktionary chỉ ghi ''{{Han etym}}'' không phân tích chi tiết. Nghĩa Quảng Đông: nhấn ép đều đặn (press steadily). Chưa xác định cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": bộ 石 (đá) + âm zhé (trác/chiết) — 矺 gợi hình ảnh dùng đá ép đều lên vật, như nghề làm đậu phụ ép nước. | Gương Hán-Việt | trác — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 矺 giúp nhận diện từ ngữ thủ công nghiệp cổ trong tiếng Quảng Đông và văn bản kỹ thuật Hán cổ.", "Tự nguyên_Xie": "Chữ 矺 thuộc bộ 石 (thạch: đá), đọc zhé (Hán-Việt: trác). Wiktionary ghi ''{{Han etym}}'' không có phân tích cụ thể. Nghĩa theo tiếng Quảng Đông: ấn ép đều đặn. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "煺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矺", "Unihan_Traditional (Chữ Phồn thể)": "矺", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động ném mạnh hoặc đè ép vật gì đó xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砪', '{"9000": "8416.0", "Chữ Trung Quốc": "砪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砪 | mẫu | tượng hình | (nghĩa không rõ, bộ 石) | 砪 thuộc bộ 石 (thạch: đá), đọc mǔ. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫu\": bộ 石 (đá) + âm mǔ (mẫu: mẹ/đơn vị) — 砪 là loại đá hoặc đặc tính đá nào đó trong văn bản khoáng sản cổ đại. | Gương Hán-Việt | mẫu — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 砪 giúp nhận diện tên đá hiếm trong từ điển bộ 石 của văn bản Hán cổ.", "Tự nguyên_Xie": "Chữ 砪 thuộc bộ 石 (thạch: đá), đọc mǔ (Hán-Việt: mẫu). Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Nghĩa không rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "突", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 母", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石母", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "母", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砪", "Unihan_Traditional (Chữ Phồn thể)": "砪", "Pinyin_Xie": "mǔ", "Âm Hán Việt_Xie": "mẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các văn bản cổ để chỉ một loại đá cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硂', '{"9000": "8417.0", "Chữ Trung Quốc": "硂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硂 | toàn | tượng hình | (nghĩa không rõ, bộ 石) | 硂 thuộc bộ 石 (thạch: đá), đọc quán. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": bộ 石 (đá) + âm quán (toàn: đầy đủ, trọn vẹn) — 硂 có thể chỉ loại đá hoàn chỉnh hoặc đá quý trong văn bản cổ. | Gương Hán-Việt | toàn — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 硂 giúp nhận diện tên đá hiếm trong từ điển khoáng vật học Hán cổ.", "Tự nguyên_Xie": "Chữ 硂 thuộc bộ 石 (thạch: đá), đọc quán (Hán-Việt: toàn). Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Nghĩa không rõ ràng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "炂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硂", "Unihan_Traditional (Chữ Phồn thể)": "硂", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "toàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ đá cứng hoặc chất liệu bê tông trong xây dựng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碒', '{"9000": "8418.0", "Chữ Trung Quốc": "碒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碒 | ngân | tượng hình | tro tàn; màu xám tro (bộ 石) | 碒 thuộc bộ 石 (thạch: đá), đọc yín. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Nghĩa ghi nhận là tro tàn, màu xám tro. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": bộ 石 (đá) + âm yín (ngân: bạc) — 碒 gợi màu xám bạc của tro tàn sau khi lửa tắt, như màu đá bị đốt cháy. | Gương Hán-Việt | ngân — không xuất hiện trong từ Hán-Việt thông dụng trong nghĩa này | Mở khoá kiến thức | Biết 碒 giúp nhận diện từ mô tả màu sắc đá và tro trong văn bản luyện kim và hóa học cổ đại.", "Tự nguyên_Xie": "Chữ 碒 thuộc bộ 石 (thạch: đá), đọc yín (Hán-Việt: ngân). Không tìm thấy phân tích nguồn gốc trong Wiktionary. Nghĩa: tro tàn (ashen). Có thể liên quan đến màu sắc hoặc kết cấu đá xám tro. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tro tàn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碒", "Unihan_Traditional (Chữ Phồn thể)": "碒", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này chủ yếu làm tính từ mô tả dáng núi đá cao dốc hoặc danh từ chỉ tro tàn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祤', '{"9000": "8419.0", "Chữ Trung Quốc": "祤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祤 | hữu | tượng hình | (nghĩa không rõ, bộ 示) | 祤 thuộc bộ 示 (kỳ: thần, cúng tế), đọc yǔ. Không có phân tích cấu trúc hay định nghĩa từ Wiktionary. Chưa xác định hình-thanh hay hội-ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hữu\": bộ 示 (thần linh, lễ cúng) — 祤 có thể là một lễ cúng hoặc vật phẩm dâng thần trong nghi lễ cổ đại, như chữ 祐 (hữu: phù hộ) cùng bộ. | Gương Hán-Việt | hữu — không xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 祤 giúp nhận diện nhóm chữ nghi lễ hiếm thuộc bộ 示 trong văn bản tế tự cổ đại.", "Tự nguyên_Xie": "Chữ 祤 thuộc bộ 示 (kỳ: thần linh, nghi lễ cúng tế), đọc yǔ (Hán-Việt: hữu). Không tìm thấy phân tích nguồn gốc hay định nghĩa trong Wiktionary. Bộ 示 cho thấy liên quan đến thần linh hoặc nghi lễ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祤", "Unihan_Traditional (Chữ Phồn thể)": "祤", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "hữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng để chỉ địa danh cổ hoặc nơi thực hiện nghi lễ cúng tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禩', '{"9000": "8420.0", "Chữ Trung Quốc": "禩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 15 | nét | 禩 | tự | tượng hình | biến thể của 祀, chữ cúng tế | 禩 là biến thể (variant) của 祀 (Tự, nghĩa: cúng tế, năm lễ). Cấu trúc gốc 祀 = 示 (biểu nghĩa: thần linh, lễ nghi) + 巳 (biểu âm). Chữ 禩 xuất hiện trong một số dị bản cổ với cùng nghĩa và âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": chữ thờ cúng dùng bộ 示 (thần linh) — thấy 示 là biết liên quan lễ tế. | Gương Hán-Việt | tự trong \"tế tự\" (lễ cúng) | Mở khoá kiến thức | Biết 禩/祀 mở khoá các từ Hán-Việt về lễ nghi: tế tự, tự miếu, tự điển.", "Tự nguyên_Xie": "Tiểu triện | 禩 là dị thể tự của 祀 (sì). Wiktionary ghi nhận 禩 chỉ đơn giản là biến thể của 祀 — chữ chỉ lễ cúng tế và đơn vị năm theo lịch lễ nghi cổ. Chưa có nguồn học thuật riêng cho dạng này. Xem 祀 để hiểu đầy đủ nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cúng tế; năm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 異", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻異", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "異", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禩", "Unihan_Traditional (Chữ Phồn thể)": "禩", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc cúng tế hoặc danh từ chỉ năm tháng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稑', '{"9000": "8421.0", "Chữ Trung Quốc": "稑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 坴 | lục | biểu âm | âm gợi đọc | 稑 = 禾 (Hòa, biểu nghĩa: lúa/ngũ cốc) + 坴 (Lục, biểu âm). Chữ hình thanh: phần 禾 cho biết nghĩa liên quan đến cây lương thực, phần 坴 cho âm đọc gần lù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": bộ 禾 (lúa) + 坴 (âm lục) — lúa \"lục\" tức gieo muộn mà chín trước, nghịch lý của nông nghiệp cổ. | Gương Hán-Việt | lục trong văn cổ nông nghiệp (gieo muộn chín sớm) | Mở khoá kiến thức | Biết 稑 mở khoá hiểu thuật ngữ nông nghiệp cổ: 穜稑 (các loại lúa theo mùa vụ).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 稑 là chữ hình thanh (psc): 禾 (hòa) biểu nghĩa chỉ ngũ cốc, 坴 biểu âm. Nghĩa cổ: lúa/thóc trồng muộn nhưng chín sớm (sớm thu hoạch dù gieo muộn), đối nghĩa với 穜 (gieo sớm chín muộn). Chữ xuất hiện trong các nông thư cổ Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trồng sau chín trước (lúa thóc); chín, được mùa", "Hạng Tần Suất (Jun Da)": "8421.0", "Tần Suất % (Jun Da)": "99.9996335993", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 坴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾坴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稑", "Unihan_Traditional (Chữ Phồn thể)": "稑", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ loại lúa gieo sau nhưng chín trước hoặc tính từ chỉ sự chín sớm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穐', '{"9000": "8422.0", "Chữ Trung Quốc": "穐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 16 | nét | 穐 | thu | tượng hình | biến thể cổ của 秋, mùa thu | 穐 là biến thể cổ của 秋 (Thu, mùa thu). Không có dữ liệu phân tích cấu tạo riêng; dạng chữ này xuất hiện trong văn bản Nhật Bản (dùng thay 秋) và một số dị bản Hán cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thu\": dạng cổ/dị thể của 秋 — gặp 穐 trong văn bản cổ, đọc như \"thu\" (mùa thu). | Gương Hán-Việt | thu trong \"mùa thu\", \"thu hoạch\" | Mở khoá kiến thức | Biết 穐/秋 mở khoá từ Hán-Việt: thu phân, thu hoạch, thu thiên.", "Tự nguyên_Xie": "穐 là dị thể của 秋 (qiū, thu). Không có nguồn Wiktionary độc lập về cấu tạo của riêng 穐. Nghĩa và âm hoàn toàn giống 秋 — mùa thu, vụ gặt hái. Chữ này chưa có nguồn học thuật riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "琐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 亀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾亀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穐", "Unihan_Traditional (Chữ Phồn thể)": "穐", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ mùa thu hoặc giai đoạn gặt hái trong năm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穛', '{"9000": "8423.0", "Chữ Trung Quốc": "穛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 穛 | trác | tượng hình | lúa chín sớm, dị thể cổ | 穛 là chữ cổ chỉ loại lúa/ngũ cốc chín sớm. Cấu tạo không được phân tích rõ trong nguồn hiện có; hình thức chữ gợi ý liên quan bộ 禾 (lúa). Chữ đã lỗi thời (obsolete).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": chữ lúa chín sớm thời cổ — nhớ qua âm \"trác\" giống 桌 (bàn), hình dung lúa bày trên bàn thờ khi chín trước mùa. | Gương Hán-Việt | trác trong văn nông nghiệp cổ | Mở khoá kiến thức | Biết 穛 giúp đọc văn bản nông học cổ Trung Quốc về phân loại lúa theo thời vụ.", "Tự nguyên_Xie": "Wiktionary ghi 穛 (zhuō/zhuó) là chữ cổ chỉ loại lúa/ngũ cốc chín sớm (early-maturing grain), đã lỗi thời. Không có phân tích cấu tạo hình thanh hay hội ý rõ ràng trong nguồn có sẵn. Chưa có nguồn học thuật đầy đủ về nguồn gốc chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "穛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穛", "Unihan_Traditional (Chữ Phồn thể)": "穛", "Pinyin_Xie": "zhuō", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ để chỉ hành động gặt lúa khi còn non hoặc thu hoạch nông sản sớm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竂', '{"9000": "8424.0", "Chữ Trung Quốc": "竂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 17 | nét | 穴 | huyệt | biểu nghĩa | hang, hốc, lỗ | 尞 | liêu | biểu âm | âm gợi đọc | 竂 = 穴 (Huyệt, biểu nghĩa: hang/hốc) + 尞 (Liêu, biểu âm). Chữ hình thanh: phần 穴 cho biết liên quan đến hang/chỗ ở đơn sơ, phần 尞 cho âm. Wiktionary ghi 竂 là dị thể của 寮 (liêu: lều, túp lều nhỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": bộ 穴 (hang hốc) + âm 尞 (liêu) — túp lều \"liêu\" là chỗ ở thấp hèn như trong hang. | Gương Hán-Việt | liêu trong \"liêu lều\" (túp lều), \"đồng liêu\" (đồng nghiệp cùng chỗ ở) | Mở khoá kiến thức | Biết 竂/寮 mở khoá: liêu trai (lều trại), đồng liêu (bạn đồng nghiệp).", "Tự nguyên_Xie": "Wiktionary phân tích 竂 = 穴 (huyệt, biểu nghĩa: hang/hốc) + 尞 (biểu âm), chữ hình thanh. 竂 là biến thể của 寮, chỉ lều/chỗ ở nhỏ, túp lều thấp hèn. Ý nghĩa ban đầu là chỗ ở trong hang hoặc lán trại đơn sơ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "竂", "Unihan_Traditional (Chữ Phồn thể)": "竂", "Pinyin_Xie": "piáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cái cửa sổ nhỏ hoặc lò nung trống rỗng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笉', '{"9000": "8425.0", "Chữ Trung Quốc": "笉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笉 | khẩm | tượng hình | chữ tre cổ, nghĩa chưa rõ | 笉 mang bộ 竹 (trúc, tre) ở trên, gợi ý liên quan đến tre hoặc đồ vật làm từ tre. Cấu tạo phần dưới chưa được phân tích rõ trong nguồn học thuật hiện có. Wiktionary không định nghĩa cụ thể nghĩa của chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩm\": bộ 竹 (tre) ở trên — chữ tre cổ hiếm gặp, nhớ qua bộ thủ 竹 đặc trưng. | Gương Hán-Việt | khẩm trong văn bản cổ về tre trúc | Mở khoá kiến thức | Biết bộ 竹 trong 笉 gợi nhớ họ chữ liên quan tre: 笛 (địch), 筝 (tranh), 篮 (lam).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận 笉 có âm đọc qǐn (khẩm) và thuộc bộ 竹, không có định nghĩa hay phân tích cấu tạo rõ ràng. Nghĩa truyền thống được chép là \"dây tre\" hoặc \"nụ cười\" nhưng không có nguồn học thuật xác nhận. Chưa có nguồn học thuật đáng tin. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây tre; khuôn mặt tươi cười", "Hạng Tần Suất (Jun Da)": "8425.0", "Tần Suất % (Jun Da)": "99.9996356665", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笉", "Unihan_Traditional (Chữ Phồn thể)": "笉", "Pinyin_Xie": "qǐn", "Âm Hán Việt_Xie": "cẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ cọng tre, vỏ tre hoặc biểu cảm gương mặt tươi cười. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篟', '{"9000": "8426.0", "Chữ Trung Quốc": "篟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篟 | thiêm | tượng hình | tre mọc um tùm | 篟 mang bộ 竹 (trúc, tre) ở trên, chỉ một loại tre hoặc cảnh tre mọc rậm rạp. Phần dưới không được phân tích rõ cấu tạo hình thanh hay hội ý. Wiktionary không cung cấp thêm thông tin phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêm\": bộ 竹 (tre) — chữ tả cảnh tre rậm rạp, nhớ qua hình ảnh rừng tre tươi tốt. | Gương Hán-Việt | thiêm trong văn thơ tả cảnh tre | Mở khoá kiến thức | Biết bộ 竹 trong 篟 giúp nhận biết họ chữ tre: 篁 (hoàng, rừng tre), 篠 (tiểu, tre nhỏ).", "Tự nguyên_Xie": "Wiktionary ghi nhận 篟 (qiàn/thiêm) với âm Trung cổ và Thượng cổ, nhưng phần định nghĩa để trống (rfdef). Nghĩa truyền thống là \"tre mọc um tùm\" (luxuriant growth of bamboo). Không có phân tích cấu tạo chữ rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tre mọc um tùm", "Hạng Tần Suất (Jun Da)": "8426.0", "Tần Suất % (Jun Da)": "99.9996361833", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 倩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮倩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篟", "Unihan_Traditional (Chữ Phồn thể)": "篟", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "khiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả cảnh rừng tre mọc dày đặc và xanh tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篺', '{"9000": "8427.0", "Chữ Trung Quốc": "篺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 篺 | bì | tượng hình | chữ tre cổ hiếm, nghĩa chưa rõ | 篺 mang bộ 竹 (trúc, tre) ở trên, gợi ý liên quan đến tre hoặc đồ vật từ tre. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bì\": bộ 竹 (tre) — chữ tre hiếm gặp, nhớ qua bộ thủ 竹 đặc trưng như trong 笔 (bút), 篮 (giỏ). | Gương Hán-Việt | bì trong văn bản cổ về đồ dùng tre | Mở khoá kiến thức | Biết bộ 竹 mở khoá họ chữ tre: 笔 (bút lông), 筷 (đũa), 篮 (giỏ tre).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 篺. Chữ thuộc bộ 竹, âm đọc pí (bì). Chưa có nguồn học thuật về cấu tạo hay nghĩa cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "篺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 捭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮捭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "捭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篺", "Unihan_Traditional (Chữ Phồn thể)": "篺", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ chiếc bè bằng tre hoặc gỗ dùng để di chuyển trên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紻', '{"9000": "8428.0", "Chữ Trung Quốc": "紻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 紻 | ngưỡng | tượng hình | chữ tơ lụa cổ hiếm, nghĩa chưa rõ | 紻 mang bộ 糸 (mịch, tơ/sợi), gợi ý liên quan đến tơ lụa hoặc dây sợi. Phần còn lại chưa được phân tích rõ cấu tạo. Wiktionary không cung cấp định nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngưỡng\": bộ 糸 (tơ lụa) — chữ tơ hiếm cổ, nhớ qua bộ 糸 giống 绢 (quyên, lụa mỏng). | Gương Hán-Việt | ngưỡng trong văn bản dệt lụa cổ | Mở khoá kiến thức | Biết bộ 糸 trong 紻 gợi nhớ họ chữ tơ lụa: 绢 (quyên), 绸 (trù), 纺 (phưởng).", "Tự nguyên_Xie": "Wiktionary ghi nhận 紻 (yǎng/ngưỡng) thuộc bộ 糸, âm Trung cổ và Thượng cổ có ghi, nhưng định nghĩa để trống (rfdef). Không có phân tích cấu tạo rõ ràng. Chưa có nguồn học thuật về nghĩa cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "紻", "Unihan_Traditional (Chữ Phồn thể)": "紻", "Pinyin_Xie": "yǎng", "Âm Hán Việt_Xie": "ngưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ dây mũ hoặc tính từ tả màu sắc rực rỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緐', '{"9000": "8429.0", "Chữ Trung Quốc": "緐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 緐 | phồn | tượng hình | biến thể của 繁, nhiều/đông | 緐 là biến thể (variant) của 繁 (Phồn, nghĩa: nhiều, đông, phức tạp). Mang bộ 糸 gợi ý liên quan đến sợi tơ đan xen nhiều lớp — ẩn dụ cho sự phức tạp, đông đúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phồn\": dị thể của 繁 (phồn thịnh) — bộ 糸 (tơ) đan chồng nhiều lớp = phức tạp, phồn thịnh. | Gương Hán-Việt | phồn trong \"phồn thịnh\" (đông đúc phát triển), \"phồn hoa\" (phồn hoa đô thị) | Mở khoá kiến thức | Biết 緐/繁 mở khoá: phồn thể (繁體 — chữ phồn thể), phồn thịnh, phồn hoa.", "Tự nguyên_Xie": "Wiktionary ghi 緐 chỉ đơn giản là biến thể của 繁 (fán/phồn: nhiều, đông, phức tạp). Không có phân tích cấu tạo riêng cho 緐. Xem 繁 để hiểu đầy đủ: 繁 = 敏 + 糸, nghĩa gốc liên quan đến sợi tơ đan chồng nhiều lớp, mở rộng sang nghĩa phức tạp, đông đúc. Chưa có nguồn học thuật riêng cho 緐. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều, đông; sinh, đẻ", "Hạng Tần Suất (Jun Da)": "1294.0", "Tần Suất % (Jun Da)": "92.8500358065", "GavinGrover_Once (Chiết tự trực tiếp)": "每 + 系", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰每系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "系", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "每", "Unihan_Simplified (Chữ Giản thể)": "繁", "Unihan_Traditional (Chữ Phồn thể)": "緐", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả sự đông đúc, nhiều. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繖', '{"9000": "8430.0", "Chữ Trung Quốc": "繖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 糹 | mịch | biểu nghĩa | tơ lụa, sợi | 散 | tán | biểu âm | tản mát (cho âm) | 繖 = 糹 (Mịch, biểu nghĩa: tơ/sợi lụa) + 散 (Tán, biểu âm). Chữ hình thanh: phần 糹 chỉ chất liệu tơ lụa (vải dù/ô làm bằng lụa), phần 散 cho âm sǎn. Nghĩa: chiếc ô, dù che mưa/nắng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": 糹 (tơ lụa) + 散 (tán — tản ra) — lụa tơ mở ra tản đều như chiếc ô che nắng. | Gương Hán-Việt | tán trong \"tán che\" (ô dù che), \"bảo tán\" (lọng che nghi lễ) | Mở khoá kiến thức | Biết 繖 mở khoá từ nghi lễ cổ: 寶繖 (bảo tán — lọng nghi lễ), 繖蓋 (tán cái — ô lọng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary phân tích 繖 = 糸/糹 (mịch, biểu nghĩa: tơ lụa) + 散 (tán, biểu âm), chữ hình thanh. Nghĩa: ô dù (umbrella, parasol, parachute). Tơ lụa được dùng làm vải che cho ô dù trong thời cổ, giải thích phần nghĩa bộ 糹. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chiếc ô", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 散", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹散", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "散", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繖", "Unihan_Traditional (Chữ Phồn thể)": "繖", "Pinyin_Xie": "sǎn", "Âm Hán Việt_Xie": "tán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ cái ô che mưa nắng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繴', '{"9000": "8431.0", "Chữ Trung Quốc": "繴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 19 | nét | 繴 | bí | tượng hình | loại lưới đánh cá cổ | 繴 mang bộ 糸 (mịch, tơ/dây), gợi ý liên quan đến lưới đan bằng sợi dây. Cấu tạo phần còn lại chưa được phân tích rõ. Nghĩa truyền thống: một loại lưới đánh cá/bẫy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 糸 (sợi dây) — lưới cá đan bằng sợi, nhớ qua hình ảnh lưới 糸 quăng xuống nước. | Gương Hán-Việt | bí trong văn cổ về ngư cụ | Mở khoá kiến thức | Biết bộ 糸 trong 繴 gợi nhớ họ chữ đồ đan sợi: 绳 (thằng, dây thừng), 网 (võng, lưới).", "Tự nguyên_Xie": "Wiktionary ghi nhận 繴 (bì/bí) âm Trung cổ và Thượng cổ, nhưng định nghĩa để trống (rfdef). Nghĩa truyền thống chép là \"a kind of fishing-net\" (loại lưới đánh cá). Bộ 糸 gợi ý lưới đan bằng sợi. Không có phân tích cấu tạo rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "紴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "繴", "Unihan_Traditional (Chữ Phồn thể)": "繴", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại lưới đánh bắt trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纀', '{"9000": "8432.0", "Chữ Trung Quốc": "纀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 糸 | mịch | biểu nghĩa | sợi, dây | 僕 | bộc | biểu âm | người hầu (cho âm bộc) | 纀 = 糸 (Mịch, biểu nghĩa: sợi/dây) + 僕 (Bộc, biểu âm). Chữ hình thanh: phần 糸 chỉ vật liệu dây/sợi, phần 僕 cho âm bộc → đọc là buộc trong Nôm. Đây là chữ Nôm: chữ Hán viết để ghi tiếng Việt — biểu âm 僕 (bộc) → buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"buộc\": 糸 (dây) + 僕 (bộc → buộc âm Nôm) — chữ Nôm chỉ hành động buộc dây, đơn giản và trực tiếp. | Gương Hán-Việt | buộc trong \"trói buộc\", \"buộc dây\", \"đùm bọc\" | Mở khoá kiến thức | Biết 纀 (buộc/bọc) giúp đọc văn bản Nôm cổ và nhận biết cách cấu tạo chữ Nôm hình thanh.", "Tự nguyên_Xie": "Wiktionary (Nôm) ghi rõ: 纀 = 糸 (biểu nghĩa: sợi) + 僕 (biểu âm: bộc → buộc), chữ hình thanh, dùng trong văn bản chữ Nôm. Các âm Nôm: bọc (bundle/bag), buộc (to tie), vóc (brocade). Đây là chữ thuần Việt-ghi-âm, sáng tạo riêng cho tiếng Việt. Xem thêm 𦄾 — biến thể rút gọn của 纀. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc; như \"trói buộc\" (vhn) bọc; như \"đùm bọc\" (btcn) bộc (btcn) vóc; như \"gấm vóc\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 僕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹僕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纀", "Unihan_Traditional (Chữ Phồn thể)": "纀", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ khăn mũ hoặc động từ chỉ sự bao bọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羉', '{"9000": "8433.0", "Chữ Trung Quốc": "羉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 24 | nét | 羉 | loan | tượng hình | lưới bẫy lợn rừng cổ | 羉 mang bộ 网 (võng, lưới) — cấu trúc tổng thể gợi ý đây là loại lưới đặc biệt. Cấu tạo phần còn lại phức tạp (chữ 24 nét) chưa được phân tích rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": bộ 网 (lưới) bên trong — 羉 là lưới bẫy lợn rừng, nhớ qua hình ảnh lưới săn thú rừng khổng lồ (24 nét). | Gương Hán-Việt | loan trong văn cổ về săn bắt | Mở khoá kiến thức | Biết bộ 网 trong 羉 gợi nhớ họ chữ lưới bẫy: 罗 (la, lưới chim), 罟 (cổ, lưới cá), 罘 (phủ, bẫy thú).", "Tự nguyên_Xie": "Wiktionary ghi nhận 羉 (luán/loan) là chữ đã lỗi thời, nghĩa: \"net to catch wild boars\" — lưới bẫy lợn rừng. Bộ 网 (lưới) ở trong cấu trúc xác nhận nghĩa dụng cụ săn bắt. Chưa có phân tích cấu tạo chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hình ảnh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 䜌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒䜌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䜌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "羉", "Unihan_Traditional (Chữ Phồn thể)": "羉", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại lưới lớn dùng để săn thú thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翈', '{"9000": "8434.0", "Chữ Trung Quốc": "翈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 翈 | hiệp | tượng hình | cạnh lông vũ, tua lông | 翈 mang bộ 羽 (vũ, lông chim) — gợi ý liên quan đến chi tiết lông chim. Cấu tạo phần còn lại chưa được phân tích rõ. Nghĩa truyền thống: phần cạnh của lông vũ, tua lông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\": bộ 羽 (lông chim) — chữ chỉ phần hông/cạnh của lông chim, nhỏ và hiếm như tua lông. | Gương Hán-Việt | hiệp trong văn tả lông vũ cổ | Mở khoá kiến thức | Biết bộ 羽 trong 翈 gợi nhớ họ chữ lông chim: 翻 (phiên), 翼 (dực), 翅 (sí), 翠 (thuý).", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc xiá (hiệp), thuộc bộ 羽, định nghĩa để trống (rfdef). Nghĩa truyền thống ghi lại là phần cạnh lông vũ hoặc tua lông. Không có phân tích cấu tạo rõ ràng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cánh lông; tua lông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "甲 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甲羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翈", "Unihan_Traditional (Chữ Phồn thể)": "翈", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ phần lông vũ ở đuôi hoặc cánh chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耡', '{"9000": "8435.0", "Chữ Trung Quốc": "耡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耒 | Số nét | 13 | nét | 耡 | thừ | tượng hình | cuốc đất, dụng cụ làm đất | 耡 mang bộ 耒 (lỗi, cày/cuốc) — bộ thủ đặc trưng cho nông cụ. Đây là chữ nông nghiệp cổ, chỉ hành động hoặc dụng cụ cuốc/xới đất. Cấu tạo phần còn lại chưa được phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừ\": bộ 耒 (cày cuốc) — chữ nông dân dùng khi cuốc đất, nhớ qua bộ 耒 giống 耕 (canh tác). | Gương Hán-Việt | thừ trong văn nông nghiệp cổ (cuốc đất) | Mở khoá kiến thức | Biết bộ 耒 trong 耡 gợi nhớ họ chữ nông cụ: 耕 (canh), 耘 (vân — làm cỏ), 耗 (hao), 耙 (bá — bừa đất).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi nhận 耡 (chú/thừ) thuộc bộ 耒, không cung cấp phân tích cấu tạo chi tiết (Han etym template trống). Nghĩa truyền thống: cuốc đất (hoe). Bộ 耒 (lỗi — cày/cuốc) là bộ thủ đặc trưng của chữ nông cụ, xác nhận nghĩa liên quan đến làm đất. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuốc đất", "Hạng Tần Suất (Jun Da)": "8435.0", "Tần Suất % (Jun Da)": "99.9996429015", "GavinGrover_Once (Chiết tự trực tiếp)": "耝 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耝力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "耡", "Unihan_Traditional (Chữ Phồn thể)": "耡", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ cái cuốc hoặc động từ chỉ việc làm ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腀', '{"9000": "8436.0", "Chữ Trung Quốc": "腀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腀 | luân | tượng hình | trôn (lỗ kim), chữ thân thể cổ | 腀 mang bộ 肉/月 (nhục, thịt/thân thể) — bộ thủ đặc trưng cho chữ liên quan bộ phận cơ thể. Cấu tạo phần còn lại chưa được phân tích rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": bộ 月/肉 (thịt/thân thể) — chữ chỉ phần tròn nhỏ của cơ thể hoặc vật dụng, nhớ qua âm \"luân\" (vòng, tròn). | Gương Hán-Việt | luân trong văn tả bộ phận nhỏ tròn | Mở khoá kiến thức | Biết bộ 月/肉 trong 腀 gợi nhớ họ chữ cơ thể: 腰 (yêu, eo), 脑 (não), 胸 (hung, ngực).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 腀. Chữ thuộc bộ 肉/月 (nhục). Nghĩa Hán-Việt truyền thống ghi \"trôn\" (lỗ nhỏ, lỗ kim). Không có phân tích cấu tạo đáng tin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trôn; như \"trôn kim (lỗ kim)\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 侖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月侖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腀", "Unihan_Traditional (Chữ Phồn thể)": "腀", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cơ thể hoặc lỗ kim, thường xuất hiện trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艩', '{"9000": "8437.0", "Chữ Trung Quốc": "艩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 20 | nét | 艩 | kỳ | tượng hình | chốt thuyền (tholepin), bộ phận thuyền cổ | 艩 mang bộ 舟 (chu, thuyền) — bộ thủ đặc trưng cho chữ liên quan đến thuyền bè. Cấu tạo phần còn lại (20 nét tổng) chưa được phân tích rõ. Nghĩa: tholepin — chốt gỗ trên mạn thuyền để giữ mái chèo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": bộ 舟 (thuyền) — chốt thuyền \"kỳ\" giữ mái chèo cố định, nhớ qua bộ 舟 như 船 (thuyền). | Gương Hán-Việt | kỳ trong văn cổ về đóng thuyền | Mở khoá kiến thức | Biết bộ 舟 trong 艩 gợi nhớ họ chữ thuyền: 船 (thuyền), 舰 (hạm, tàu chiến), 艇 (đỉnh), 舱 (khoang).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 艩. Chữ thuộc bộ 舟 (chu, thuyền). Nghĩa: tholepin — chốt trên mạn thuyền để chèo. Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tholepin", "Hạng Tần Suất (Jun Da)": "8437.0", "Tần Suất % (Jun Da)": "99.999643935", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 齊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟齊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艩", "Unihan_Traditional (Chữ Phồn thể)": "艩", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận cọc gỗ trên thuyền để giữ mái chèo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苅', '{"9000": "8438.0", "Chữ Trung Quốc": "苅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 刈 | nghệ | biểu nghĩa | hái cắt, liềm | 苅 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 刈 (Nghệ, nghĩa: cắt/gặt bằng liềm). Theo Wiktionary, 苅 là chữ hội ý đồ thị: cỏ 艹 cộng hành động cắt 刈, tạo nên nghĩa cắt cỏ/gặt lúa. 苅 là biến thể của 刈.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": 艹 (cỏ) + 刈 (cắt) — nhìn thấy cỏ bị liềm cắt: đây chính là \"cắt cỏ\" viết thành một chữ. | Gương Hán-Việt | nghệ trong \"thu hoạch\" (gặt cắt mùa màng) | Mở khoá kiến thức | Biết 苅/刈 mở khoá từ gặt hái: 刈穗 (cắt bông), 刈禾 (gặt lúa).", "Tự nguyên_Xie": "Wiktionary ghi rõ 苅 là biến thể đồ thị (graphically) của 刈: 艹 (thảo, cỏ) + 刈 (nghệ, cắt), kết hợp bằng nghĩa — hội ý. Nghĩa: cắt cỏ, gặt lúa, cắt bằng liềm. Sự kết hợp trực quan: cỏ bị cắt = 苅. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt cỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 刈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹刈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苅", "Unihan_Traditional (Chữ Phồn thể)": "苅", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ngải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cắt cỏ hoặc thu hoạch nông sản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莁', '{"9000": "8439.0", "Chữ Trung Quốc": "莁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莁 | vô | tượng hình | tên cỏ cổ, chỉ dùng trong 莁荑 | 莁 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Chỉ xuất hiện trong từ ghép 莁荑 (wú tí). Cấu tạo phần còn lại chưa được phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vô\": bộ 艹 (cỏ) — cỏ \"vô\" hiếm, chỉ xuất hiện trong từ kép 莁荑, như cỏ ẩn mình không tên. | Gương Hán-Việt | vô trong tổ hợp 莁荑 (vô đề — tên cỏ cổ) | Mở khoá kiến thức | Biết 莁 nhắc nhở rằng nhiều chữ cổ chỉ tồn tại trong từ ghép cố định, không dùng độc lập.", "Tự nguyên_Xie": "Wiktionary ghi nhận 莁 (wú/vô) chỉ dùng duy nhất trong tổ hợp 莁荑 — tên một loại cỏ hoặc mầm cây. Không có phân tích cấu tạo riêng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "莁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 巫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹巫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莁", "Unihan_Traditional (Chữ Phồn thể)": "莁", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây cỏ, chủ yếu dùng trong danh từ riêng hoặc thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菞', '{"9000": "8440.0", "Chữ Trung Quốc": "菞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菞 | li | tượng hình | chữ thực vật cổ hiếm | 菞 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ không rõ nghĩa. Cấu tạo phần còn lại chưa được phân tích trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"li\": bộ 艹 (cỏ) — chữ thực vật cổ hiếm, nhớ qua bộ 艹 như trong 草 (thảo, cỏ). | Gương Hán-Việt | li trong văn thực vật cổ | Mở khoá kiến thức | Biết bộ 艹 trong 菞 gợi nhớ họ chữ thực vật: 草 (thảo), 花 (hoa), 苗 (miêu, mầm).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 菞. Chữ thuộc bộ 艹, âm đọc lí. Nghĩa không được xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "菞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "菞", "Unihan_Traditional (Chữ Phồn thể)": "菞", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài thực vật thân thảo trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菳', '{"9000": "8441.0", "Chữ Trung Quốc": "菳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菳 | cầm | tượng hình | loại cỏ cổ, dùng trong 黄菳 | 菳 mang bộ 艹 (thảo, cỏ) — chữ chỉ một loại cỏ. Chỉ xuất hiện trong từ ghép 黄菳 (hoàng cầm). Cấu tạo phần còn lại chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầm\": bộ 艹 (cỏ) — cỏ \"cầm\" chỉ dùng trong 黄菳, nhớ âm cầm như đàn cầm nhưng đây là tên cỏ vàng. | Gương Hán-Việt | cầm trong 黄菳 (hoàng cầm — tên cỏ dùng làm thuốc) | Mở khoá kiến thức | Biết 菳 giúp đọc tên thảo dược cổ trong Đông y: 黄菳 liên quan đến bạch đầu ông hoặc cỏ vàng.", "Tự nguyên_Xie": "Wiktionary ghi 菳 (qín/cầm) là tên loại cỏ, dùng trong 黄菳. Không có phân tích cấu tạo. Âm cầm gợi liên hệ với 秦 (Tần), 琴 (cầm đàn). Chưa có nguồn học thuật đầy đủ về nghĩa cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "菳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菳", "Unihan_Traditional (Chữ Phồn thể)": "菳", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cỏ dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萈', '{"9000": "8442.0", "Chữ Trung Quốc": "萈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萈 | hoàn | tượng hình | dê sừng nhỏ, thực vật mang hình dê | 萈 ban đầu là chữ tượng hình vẽ con dê với sừng, đầu, chân và đuôi. Shuowen (Thuyết Văn) lầm cho rằng đây là chữ hình thanh với 𥄕 biểu âm. Wiktionary khẳng định đây là chữ tượng hình (pictograph). Sau này đặt thêm bộ 艹 thành dạng hiện tại 萈.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\": hình vẽ con dê sừng nhỏ — 萈 là dê cổ đại, bộ 艹 thêm vào sau, nhớ qua Shuowen đã nhầm phân tích chữ này. | Gương Hán-Việt | hoàn trong văn cổ chỉ loài dê sừng nhỏ | Mở khoá kiến thức | Biết 萈 minh họa cách Shuowen đôi khi phân tích sai chữ tượng hình, giúp học lịch sử nghiên cứu Hán tự.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi rõ 萈 (huán/hoàn) ban đầu là chữ tượng hình vẽ con dê — vẽ rõ sừng, đầu, chân, đuôi. Shuowen nhầm phân tích là hình thanh với 𥄕 biểu âm. Nghĩa: dê có sừng mảnh/nhỏ. Chữ cổ lỗi thời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "萈", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "萈", "Unihan_Traditional (Chữ Phồn thể)": "萈", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài dê núi hoặc sừng của chúng trong văn tự cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒁', '{"9000": "8443.0", "Chữ Trung Quốc": "蒁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 蒁 | truật | tượng hình | loại cỏ Curcuma (nghệ), dùng trong 蒁藥 | 蒁 mang bộ 艹 (thảo, cỏ) — chỉ nhóm cây thảo dược. Phần còn lại chưa được phân tích rõ cấu tạo. Chữ dùng trong 蒁藥 — hỗn hợp thảo dược gồm các loài Curcuma.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"truật\": bộ 艹 (cỏ) — cây thuốc \"truật\" là chi Curcuma (nghệ), nhớ qua bạch truật (白朮) và nga truật (莪朮) trong Đông y. | Gương Hán-Việt | truật trong \"nga truật\" (莪朮), \"bạch truật\" — thảo dược Đông y | Mở khoá kiến thức | Biết 蒁 mở khoá tên thảo dược Đông y: 蒁藥 (hỗn hợp Curcuma), liên hệ với 薑黃 (nghệ vàng).", "Tự nguyên_Xie": "Wiktionary ghi 蒁 (shù/truật) dùng trong 蒁藥 — hỗn hợp thảo mộc từ chi Curcuma gồm: 莪朮 (Curcuma zedoaria), 鬱金 (Curcuma aromatica), 薑黃 (nghệ vàng, Curcuma longa). Đây là tên thảo dược Đông y cổ. Không có phân tích cấu tạo chữ rõ ràng. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 述", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹述", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "述", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒁", "Unihan_Traditional (Chữ Phồn thể)": "蒁", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "truật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cây thân củ dùng làm thuốc hoặc gia vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒑', '{"9000": "8444.0", "Chữ Trung Quốc": "蒑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒑 | ấn | tượng hình | loại thực vật cổ, nghĩa chưa rõ | 蒑 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấn\": bộ 艹 (cỏ) — cỏ \"ấn\" hiếm, nhớ qua bộ thủ 艹 như trong 花 (hoa), 草 (thảo). | Gương Hán-Việt | ấn trong văn thực vật cổ | Mở khoá kiến thức | Biết bộ 艹 mở khoá họ chữ cỏ cây: 草 (thảo), 芽 (nha, mầm), 苗 (miêu, cây non).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 蒑. Chữ thuộc bộ 艹, âm đọc yìn. Nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 殷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹殷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒑", "Unihan_Traditional (Chữ Phồn thể)": "蒑", "Pinyin_Xie": "yìn", "Âm Hán Việt_Xie": "ấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả màu sắc xanh tươi của cây cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓔', '{"9000": "8445.0", "Chữ Trung Quốc": "蓔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓔 | yêu | tượng hình | loại cỏ cổ | 蓔 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêu\": bộ 艹 (cỏ) — cỏ \"yêu\" cổ hiếm, nhớ qua bộ 艹 đặc trưng cho thực vật. | Gương Hán-Việt | yêu trong văn tả cỏ cây cổ | Mở khoá kiến thức | Biết bộ 艹 mở khoá họ chữ thực vật: 草 (thảo), 花 (hoa), 芳 (phương, thơm).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 蓔. Chữ thuộc bộ 艹, âm đọc yǎo. Nghĩa truyền thống: a variety of grass (nhiều loại cỏ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều loại cỏ", "Hạng Tần Suất (Jun Da)": "8445.0", "Tần Suất % (Jun Da)": "99.9996480693", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 羔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹羔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓔", "Unihan_Traditional (Chữ Phồn thể)": "蓔", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "diểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại cỏ khô hoặc cỏ úa dùng trong đời sống xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓕', '{"9000": "8446.0", "Chữ Trung Quốc": "蓕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓕 | quế | tượng hình | loại thực vật liên quan đến quế | 蓕 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật. Nghĩa Hán-Việt ghi \"蓓\" (bào, nụ hoa) nhưng không rõ mối liên hệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quế\": bộ 艹 (cỏ) — có thể liên quan đến cây quế hoặc thực vật có hương thơm, nhớ qua âm \"quế\" như cây quế (肉桂). | Gương Hán-Việt | quế trong tên thực vật cổ | Mở khoá kiến thức | Biết bộ 艹 và âm quế gợi nhớ cây quế (桂), hoa quế trong ẩm thực và y học.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 蓕. Chữ thuộc bộ 艹, âm đọc guì. Nghĩa chưa xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蓓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 桂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹桂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "桂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓕", "Unihan_Traditional (Chữ Phồn thể)": "蓕", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nụ hoa non, thường dùng trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔙', '{"9000": "8447.0", "Chữ Trung Quốc": "蔙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔙 | huyền | tượng hình | tên cổ của hoa Inula (triền phúc hoa) | 蔙 mang bộ 艹 (thảo, cỏ) — chữ thực vật. Wiktionary ghi đây là tên cổ (obs-std) của 旋覆花 (hoa Inula — triền phúc hoa). Cấu tạo phần còn lại chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": bộ 艹 (cỏ) + âm huyền — tên cổ của hoa Inula/triền phúc hoa, dùng trong Đông y trị ho. | Gương Hán-Việt | huyền trong tên cỏ cổ; nay gọi là 旋覆花 (triền phúc hoa) | Mở khoá kiến thức | Biết 蔙 giúp đọc tên thảo dược Đông y cổ liên quan đến 旋覆花 — cây vị đắng, trị nôn và ho.", "Tự nguyên_Xie": "Wiktionary ghi 蔙 (xuàn/huyền) là tên cổ đã lỗi thời của 旋覆花 — hoa Inula (triền phúc hoa), một loại cây thuốc trong Đông y. Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(thảo mộc)", "Hạng Tần Suất (Jun Da)": "8447.0", "Tần Suất % (Jun Da)": "99.9996491029", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 旋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹旋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔙", "Unihan_Traditional (Chữ Phồn thể)": "蔙", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "tuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài hoa cỏ dại trong các tài liệu thực vật cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔿', '{"9000": "8448.0", "Chữ Trung Quốc": "蔿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蔿 | vi | tượng hình | tên họ cổ, địa danh trong văn bản Xuân Thu | 蔿 mang bộ 艹 (thảo, cỏ) — cấu trúc gợi ý tên địa lý hoặc họ tên gắn với cây cỏ. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": bộ 艹 (cỏ) + âm vi — tên họ/địa danh trong Xuân Thu, nhớ qua các quý tộc nước Sở mang họ 蔿. | Gương Hán-Việt | vi trong tên họ quý tộc Sở (蔿氏) thời Xuân Thu | Mở khoá kiến thức | Biết 蔿 giúp đọc gia phả và văn bản lịch sử nước Sở thời Xuân Thu Chiến Quốc.", "Tự nguyên_Xie": "Tiểu triện | Không có dữ liệu Wiktionary về nguồn gốc 蔿. Chữ thuộc bộ 艹, âm đọc wěi. Nghĩa: tên họ (surname) và địa danh trong văn bản Xuân Thu — nước Sở có một số quan lại mang họ 蔿. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Môi trường sống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 爲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹爲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔿", "Unihan_Traditional (Chữ Phồn thể)": "蔿", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ họ người hoặc tên địa danh thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕧', '{"9000": "8449.0", "Chữ Trung Quốc": "蕧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕧 | phục | tượng hình | tên cổ khác của hoa Inula (triền phúc hoa) | 蕧 mang bộ 艹 (thảo, cỏ) — chữ thực vật. Tương tự 蔙, đây là tên cổ khác của 旋覆花 (hoa Inula). Cấu tạo phần còn lại chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": bộ 艹 (cỏ) + âm phục — tên cổ của hoa triền phúc (旋覆花), âm \"phục\" phản ánh âm trong tên chuẩn. | Gương Hán-Việt | phục trong tên cổ hoa triền phúc | Mở khoá kiến thức | Biết 蕧 và 蔙 đều là tên cổ của 旋覆花, giúp đọc y thư cổ về thảo dược Đông y.", "Tự nguyên_Xie": "Wiktionary ghi 蕧 (fù/phục) cũng là tên cổ đã lỗi thời của 旋覆花 — hoa Inula (triền phúc hoa), giống như 蔙. Âm phục liên hệ với chữ 覆 trong tên chuẩn 旋覆花. Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "qu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 復", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹復", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "復", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕧", "Unihan_Traditional (Chữ Phồn thể)": "蕧", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại thảo dược trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薆', '{"9000": "8450.0", "Chữ Trung Quốc": "薆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薆 | ái | tượng hình | ẩn giấu, che đậy; tươi tốt (thực vật) | 薆 mang bộ 艹 (thảo, cỏ) — chỉ sự tươi tốt rậm rạp của cỏ cây che khuất tầm nhìn. Cấu tạo phần còn lại chưa được phân tích rõ. Chữ có nghĩa: ẩn giấu, tươi tốt um tùm, hoặc thơm ngát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": bộ 艹 (cỏ) — cỏ rậm che giấu = 薆 (ẩn giấu, tươi tốt); nhớ qua 薆薆然 (um tùm kín đáo). | Gương Hán-Việt | ái trong 塕薆 (wěng ài — um tùm rậm rạp), 薆薆 (ái ái — kín đáo) | Mở khoá kiến thức | Biết 薆 mở khoá từ văn học: 蓊薆 (um tùm rậm rạp), 薆然 (ẩn ất, ẩn hiện).", "Tự nguyên_Xie": "Wiktionary ghi 薆 (ài/ái) là chữ văn học với các nghĩa: (1) ẩn giấu, che đậy; (2) um tùm, tươi tốt; (3) thơm ngát (dị thể của 馤). Không có phân tích cấu tạo hình thanh/hội ý rõ ràng. Chưa có nguồn học thuật đầy đủ về cấu tạo. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giấu giếm, che đậy", "Hạng Tần Suất (Jun Da)": "8450.0", "Tần Suất % (Jun Da)": "99.9996506532", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 愛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹愛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "愛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薆", "Unihan_Traditional (Chữ Phồn thể)": "薆", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ với nghĩa che giấu hoặc làm tính từ tả cây cối rậm rạp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薗', '{"9000": "8451.0", "Chữ Trung Quốc": "薗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薗 | viên | tượng hình | vườn cây, công viên (biến thể 園) | 薗 mang bộ 艹 (thảo, cỏ) — gợi ý vườn cây xanh. Đây có thể là biến thể/dị thể liên quan đến 園 (viên, vườn). Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": bộ 艹 (cỏ cây) + âm viên — vườn \"viên\" tức nơi trồng cây cỏ, nhớ qua 花园 (hoa viên, vườn hoa). | Gương Hán-Việt | viên trong \"vườn\" (hoa viên, thái viên), \"công viên\" | Mở khoá kiến thức | Biết 薗/園 mở khoá: viên lâm (vườn rừng), thái viên (vườn rau), hoa viên (vườn hoa).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 薗. Chữ thuộc bộ 艹, âm đọc yuán. Nghĩa: garden, park, orchard — vườn cây, công viên, vườn trái cây. Có thể là biến thể của 園 (viên). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "薗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 園", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹園", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "園", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薗", "Unihan_Traditional (Chữ Phồn thể)": "薗", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là dị thể của chữ Viên, dùng làm danh từ chỉ nơi trồng trọt cây cối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薝', '{"9000": "8452.0", "Chữ Trung Quốc": "薝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薝 | chiêm | tượng hình | tên cỏ cổ, dùng trong 薝蔔 (hoa dành dành) | 薝 mang bộ 艹 (thảo, cỏ) — chữ thực vật. Chỉ xuất hiện trong từ ghép 薝蔔 (zhān bó) — tên Phạn dịch âm cho hoa dành dành (Gardenia jasminoides) hay hoa Champak. Cấu tạo phần còn lại chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": bộ 艹 (cỏ) — 薝蔔 là hoa thơm Phật giáo, âm phiên từ Phạn, nhớ qua hoa champaka trong chùa. | Gương Hán-Việt | chiêm trong 薝蔔 (chiêm bặc — hoa Champak, hoa dành dành) | Mở khoá kiến thức | Biết 薝 giúp đọc văn bản Phật giáo về hoa dâng cúng: 薝蔔 = champaka, hoa quý trong kinh điển.", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 薝. Chữ thuộc bộ 艹, âm đọc zhān. Nghĩa liên quan đến 薝蔔 — dịch âm từ tiếng Phạn (champaka/gandha) chỉ một loài hoa thơm quý trong Phật giáo. Phần \"chiêm\" trong nghĩa Việt (xem: đảm bặc 薝蔔) xác nhận từ dùng theo lối phiên âm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đảm bặc 薝蔔)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薝", "Unihan_Traditional (Chữ Phồn thể)": "薝", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép chiêm bặc để chỉ một loài hoa thơm trong kinh Phật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藀', '{"9000": "8453.0", "Chữ Trung Quốc": "藀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 藀 | oanh | tượng hình | loại cỏ cổ đã lỗi thời | 藀 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Cấu tạo phần còn lại chưa được phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oanh\": bộ 艹 (cỏ) — loại cỏ \"oanh\" đã tuyệt tích, nhớ âm oanh như chim oanh vàng nhưng đây là tên cỏ. | Gương Hán-Việt | oanh trong tên thực vật cổ đã lỗi thời | Mở khoá kiến thức | Biết bộ 艹 mở khoá họ chữ cỏ cây: 草 (thảo), 苗 (miêu), 芽 (nha).", "Tự nguyên_Xie": "Wiktionary ghi 藀 (yíng/oanh) là loại cỏ đã lỗi thời (a kind of grass, obs-std). Không có phân tích cấu tạo. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 熒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹熒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "熒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藀", "Unihan_Traditional (Chữ Phồn thể)": "藀", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "oanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thư tịch cổ để chỉ một loài thực vật chưa rõ nguồn gốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘌', '{"9000": "8454.0", "Chữ Trung Quốc": "蘌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 20 | nét | 蘌 | vũ | tượng hình | thực vật cổ hiếm | 蘌 mang bộ 艹 (thảo, cỏ) — chữ thực vật cổ. Không có dữ liệu phân tích cấu tạo từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": bộ 艹 (cỏ) — thực vật cổ hiếm, nhớ qua bộ 艹 tương tự 蕉 (tiêu, chuối), 蒲 (bồ, cói). | Gương Hán-Việt | vũ trong văn thực vật cổ | Mở khoá kiến thức | Biết bộ 艹 mở khoá họ chữ thực vật: 草 (thảo), 芦 (lô), 蒲 (bồ).", "Tự nguyên_Xie": "Không có dữ liệu Wiktionary về nguồn gốc 蘌. Chữ thuộc bộ 艹, âm đọc yǔ. Nghĩa không xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蘌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 禦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹禦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘌", "Unihan_Traditional (Chữ Phồn thể)": "蘌", "Pinyin_Xie": "yǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng như một động từ chỉ hành vi nuôi dưỡng muông thú hoặc cai quản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虋', '{"9000": "8455.0", "Chữ Trung Quốc": "虋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 29 | nét | 虋 | môn | tượng hình | kê đỏ cổ, lúa miến thân đỏ | 虋 là chữ lớn (29 nét) mang bộ 艹 (thảo, cỏ). Wiktionary ghi đây là loại kê/lúa miến thân/cuống đỏ (red-stalked millet) thời cổ, đã lỗi thời. Cấu tạo phức tạp, chưa có phân tích hình thanh/hội ý rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"môn\": chữ 29 nét chỉ kê thân đỏ — phức tạp như cây lúa miến cao lớn, nhớ qua âm \"môn\" và sắc đỏ đặc trưng. | Gương Hán-Việt | môn trong văn nông nghiệp cổ (kê đỏ) | Mở khoá kiến thức | Biết 虋 giúp đọc văn bản nông học cổ về phân loại cây lương thực theo màu thân.", "Tự nguyên_Xie": "Wiktionary ghi 虋 (mén/môn) là chữ lỗi thời chỉ loại kê/lúa miến thân đỏ (red-stalked millet). Âm mén liên quan đến 門 (môn, cửa) nhưng không có phân tích rõ mối liên hệ. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "苋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 釁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹釁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "釁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "虋", "Unihan_Traditional (Chữ Phồn thể)": "虋", "Pinyin_Xie": "mén", "Âm Hán Việt_Xie": "môn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại ngũ cốc hoặc rau thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚿', '{"9000": "8456.0", "Chữ Trung Quốc": "蚿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | sâu bọ | 玄 | huyền | biểu âm | âm gần xián | 蚿 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 玄 (Huyền, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": con sâu (虫) màu huyền (玄) — đó là con rết nhiều chân uốn lượn. | Gương Hán-Việt | mã huyền (馬蚿) — tên cổ của con rết | Mở khoá kiến thức | Biết 蚿 giúp đọc từ cổ 馬蚿 chỉ loài rết lớn trong văn bản Hán Nôm.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 虫 (trùng) chỉ loài sâu bọ, 玄 (huyền) cho âm đọc gần xián. Chỉ loài rết/cuốn chiếu (mã huyền 馬蚿). Chưa có nguồn gốc kim văn hay giáp cốt được ghi nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mã huyền 馬蚿)", "Hạng Tần Suất (Jun Da)": "8456.0", "Tần Suất % (Jun Da)": "99.999653754", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚿", "Unihan_Traditional (Chữ Phồn thể)": "蚿", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường đi kèm với chữ mã để tạo thành danh từ chỉ con cuốn chiếu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜫', '{"9000": "8457.0", "Chữ Trung Quốc": "蜫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜫 | côn | tượng hình | biến thể cổ của 昆, chỉ côn trùng | 蜫 là dị thể (variant) cổ của 昆 và 䖵, chỉ côn trùng nói chung. Wiktionary ghi nhận chữ này xem lại 昆 hoặc 䖵.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": bộ 虫 nhân đôi (䖵) hoặc biến dạng thành 蜫 — đều chỉ thế giới côn trùng nhỏ bé. | Gương Hán-Việt | côn trùng (昆蟲) — loài sâu bọ | Mở khoá kiến thức | Biết 蜫 giúp nhận ra gốc chữ 昆 trong 昆蟲 (côn trùng), 昆仲 (côn trọng — anh em).", "Tự nguyên_Xie": "蜫 là dạng chữ cũ thay thế cho 昆 (côn) và 䖵, đều chỉ côn trùng. Dạng 蜫 thêm bộ 虫 để nhấn mạnh nghĩa sâu bọ. Chưa thấy trong giáp cốt hay kim văn, là chữ tạo muộn. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chích", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜫", "Unihan_Traditional (Chữ Phồn thể)": "蜫", "Pinyin_Xie": "kūn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là biến thể của chữ côn trong côn trùng, dùng làm danh từ chỉ loài sâu bọ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜽', '{"9000": "8458.0", "Chữ Trung Quốc": "蜽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜽 | lượng | tượng hình | loài yêu quái trong truyền thuyết, thường gặp trong từ 蝄蜽/魍魎 | 蜽 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ xuất hiện chủ yếu trong từ 蝄蜽 (võng lượng), chỉ loài yêu quái trong truyền thuyết Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lượng\": trong từ 蝄蜽 (võng lượng) — hai yêu quái sông núi trong truyền thuyết, chữ 蜽 mang bộ 虫 ám chỉ loài quái dị. | Gương Hán-Việt | võng lượng (魍魎) — tên hai loài yêu quái trong thần thoại | Mở khoá kiến thức | Biết 蜽 giúp đọc từ cổ 蝄蜽/魍魎 trong văn học cổ điển Trung Hoa và Hán Nôm.", "Tự nguyên_Xie": "蜽 dùng trong từ 蝄蜽 (魍魎, võng lượng), chỉ loài quỷ thần núi rừng trong thần thoại cổ Trung Hoa. Wiktionary không có cấu trúc hình thanh cụ thể; chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Cũng viết 魎. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: võng lượng 魍魎,魍魉,蝄蜽)", "Hạng Tần Suất (Jun Da)": "8458.0", "Tần Suất % (Jun Da)": "99.9996547875", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 兩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫兩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜽", "Unihan_Traditional (Chữ Phồn thể)": "蜽", "Pinyin_Xie": "liǎng", "Âm Hán Việt_Xie": "lưỡng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với võng để tạo thành danh từ chỉ các loài yêu quái trong truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螥', '{"9000": "8459.0", "Chữ Trung Quốc": "螥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螥 | thương | tượng hình | chỉ loài ruồi nhà, không rõ cấu trúc | 螥 không có dữ liệu cấu trúc hình thanh/hội ý được ghi nhận. Chữ chỉ loài ruồi nhà (house-fly), rất hiếm trong văn bản hiện đại. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": con ruồi (螥) mang màu xanh thương (thương = xanh lam) — ruồi nhặng lấp lánh. | Gương Hán-Việt | thương (螥) — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 螥 giúp nhận dạng các từ cổ chỉ côn trùng trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "螥 chỉ loài ruồi nhà. Không có nguồn Wiktionary với cấu trúc cụ thể. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận gốc tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xù lông", "Hạng Tần Suất (Jun Da)": "8459.0", "Tần Suất % (Jun Da)": "99.9996553043", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 倉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫倉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螥", "Unihan_Traditional (Chữ Phồn thể)": "螥", "Pinyin_Xie": "cāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với lang để tạo thành danh từ chỉ loài ruồi nhà hoặc ruồi trâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠚', '{"9000": "8460.0", "Chữ Trung Quốc": "蠚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 若 | nhược | biểu âm | âm gần hē/hè | 虫 | trùng | biểu nghĩa | sâu bọ | 蠚 = 若 (Nhược, biểu âm) + 虫 (Trùng, biểu nghĩa: sâu bọ); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": con sâu (虫) yếu ớt (nhược) lại đốt một cái — 蠚 — bạn sưng tay! | Gương Hán-Việt | nhược (蠚) — ít dùng trong tiếng Việt; nghĩa là đốt/chích | Mở khoá kiến thức | Biết 蠚 giúp đọc các từ cổ chỉ côn trùng đốt trong văn bản y học cổ truyền.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 虫 (trùng) chỉ côn trùng, 若 (nhược) cho âm đọc. Nghĩa gốc là đốt, cắn, chích — hành động của côn trùng. Phương ngôn Tứ Xuyên đọc ho2. Chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đốt; cắn; chích", "Hạng Tần Suất (Jun Da)": "8460.0", "Tần Suất % (Jun Da)": "99.9996558211", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蠚", "Unihan_Traditional (Chữ Phồn thể)": "蠚", "Pinyin_Xie": "hē", "Âm Hán Việt_Xie": "nhược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động côn trùng chích hoặc đốt người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袽', '{"9000": "8461.0", "Chữ Trung Quốc": "袽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 袽 | nhự | tượng hình | mảnh vải rách cũ, dùng để bít khe hở | 袽 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận trong nguồn hiện có. Chữ chỉ mảnh vải rách cũ, đặc biệt dùng để bít lỗ rò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhự\": tấm vải (袽) nhàu nát như người rũ (nhự) xuống — mảnh giẻ cũ bít lỗ thuyền. | Gương Hán-Việt | nhự (袽) — ít dùng trong tiếng Việt; nghĩa là vải rách cũ | Mở khoá kiến thức | Biết 袽 giúp đọc thành ngữ cổ 衣袽之戒 trong văn học Hán Nôm.", "Tự nguyên_Xie": "袽 chỉ mảnh vải cũ nát, đặc biệt là vải vo tròn dùng để bít khe hở rò rỉ. Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound. Xuất hiện trong thành ngữ 衣袽之戒 (cảnh giác từ tấm vải rách). Chưa có nguồn học thuật xác nhận gốc tự cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo rách", "Hạng Tần Suất (Jun Da)": "8461.0", "Tần Suất % (Jun Da)": "99.9996563379", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 如", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤如", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袽", "Unihan_Traditional (Chữ Phồn thể)": "袽", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "như", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại vải rách hoặc giẻ lau dùng trong sinh hoạt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裶', '{"9000": "8462.0", "Chữ Trung Quốc": "裶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裶 | phi | tượng hình | dáng áo dài bay phất phơ | 裶 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ chỉ dáng vẻ của áo dài bay phấp phới, hoặc dáng cờ phấp phới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": chiếc áo (裶) phi (飛) bay phất phơ trong gió — dáng áo dài thướt tha. | Gương Hán-Việt | phi (裶) — ít dùng; nghĩa là dáng áo dài bay phấp phới | Mở khoá kiến thức | Biết 裶 giúp nhận dạng từ ngữ cổ chỉ trang phục trong thư tịch Hán Nôm cổ điển.", "Tự nguyên_Xie": "裶 là chữ cổ (obs-std) chỉ dáng áo dài thướt tha hoặc dáng cờ phất phơ. Wiktionary ghi nhận hai nghĩa: dáng áo dài và dáng cờ bay. Không có cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dài; đồ dài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裶", "Unihan_Traditional (Chữ Phồn thể)": "裶", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả tà áo dài thướt tha hoặc làm danh từ chỉ vạt áo dài. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裺', '{"9000": "8463.0", "Chữ Trung Quốc": "裺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 裺 | yểm | tượng hình | yếm vải, cổ áo | 裺 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ chỉ yếm vải hoặc cổ áo. Xuất hiện trong từ 裺囊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": cái yếm (裺) che ngực — loại trang phục truyền thống của phụ nữ xưa. | Gương Hán-Việt | yếm (裺) — trong tiếng Việt ''yếm'' là loại áo lót ngực truyền thống | Mở khoá kiến thức | Biết 裺 giúp nhận ra gốc Hán của từ ''yếm'' trong tiếng Việt (yếm đào, yếm thắm).", "Tự nguyên_Xie": "裺 chỉ yếm vải hay cổ áo trong trang phục cổ đại. Wiktionary ghi nhận âm Middle Chinese nhưng không có cấu trúc Han compound. Từ 裺囊 chỉ loại túi đeo trước ngực. Chưa có nguồn học thuật xác nhận gốc tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yếm vải; yếm; cổ áo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "裺", "Unihan_Traditional (Chữ Phồn thể)": "裺", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần cổ áo hoặc loại yếm che ngực thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褣', '{"9000": "8464.0", "Chữ Trung Quốc": "褣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衣 | y | biểu nghĩa | quần áo | 容 | dung | biểu âm | âm gần róng | 褣 = 衣 (Y, biểu nghĩa: quần áo) + 容 (Dung, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": chiếc áo (衣) dung (容) dị — 褣 chỉ loại trang phục cổ xưa không rõ hình dạng. | Gương Hán-Việt | dung (褣) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 褣 giúp nhận dạng chữ quần áo hình thanh với bộ 衣 trong cổ thư.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 衣 (y) chỉ quần áo, 容 (dung) cho âm đọc gần róng. Nghĩa cụ thể chưa được ghi rõ trong các từ điển hiện đại. Wiktionary chỉ ghi nhận cấu trúc Han compound, không giải thích nghĩa thêm. Chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褣", "Unihan_Traditional (Chữ Phồn thể)": "褣", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ trang phục áo dài hoặc tính từ tả dáng áo rộng rãi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詅', '{"9000": "8465.0", "Chữ Trung Quốc": "詅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 言 | ngôn | biểu nghĩa | lời nói | 令 | lệnh | biểu âm | âm gần líng | 詅 = 言 (Ngôn, biểu nghĩa: lời nói) + 令 (Lệnh, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": dùng lời (言) ra lệnh (令) thiên hạ mua hàng — 詅 là rao bán, tự khoe hàng tốt. | Gương Hán-Việt | linh (詅) — ít dùng trong tiếng Việt; nghĩa là rao bán | Mở khoá kiến thức | Biết 詅 giúp nhận dạng các chữ hình thanh bộ 言 chỉ hành động ngôn ngữ trong cổ thư.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 言 (ngôn) chỉ lời nói, 令 (lệnh) cho âm đọc gần líng. Nghĩa: tự quảng cáo, rao hàng tốt để bán. Hàm ý dùng lời nói để thuyết phục mua hàng. Chưa thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tự khoe hàng tốt để bán", "Hạng Tần Suất (Jun Da)": "8465.0", "Tần Suất % (Jun Da)": "99.9996589218", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詅", "Unihan_Traditional (Chữ Phồn thể)": "詅", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động rao bán hoặc tự khoe khoang hàng hóa để dễ bán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詇', '{"9000": "8466.0", "Chữ Trung Quốc": "詇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詇 | ưởng | tượng hình | biết, hiểu; thông báo | 詇 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ chỉ hành động biết, hiểu hoặc thông báo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ưởng\": chữ 詇 liên quan đến lời nói (bộ 言 ẩn) và sự hiểu biết — biết điều và báo cho người khác. | Gương Hán-Việt | ưởng (詇) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 詇 giúp nhận dạng chữ cổ chỉ nhận thức và ngôn ngữ trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "詇 là chữ cổ chỉ hành động biết/hiểu hoặc thông báo. Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "詇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詇", "Unihan_Traditional (Chữ Phồn thể)": "詇", "Pinyin_Xie": "yàng", "Âm Hán Việt_Xie": "ưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả thái độ kiêu ngạo hoặc âm thanh nói năng lớn tiếng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誻', '{"9000": "8467.0", "Chữ Trung Quốc": "誻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 誻 | tháp | tượng hình | chữ cổ, nghĩa chưa rõ; có trong từ 誻誻 | 誻 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ xuất hiện trong từ láy 誻誻.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": chữ 誻 liên quan đến lời nói (bộ 言), trong từ láy 誻誻 — âm thanh lặp đi lặp lại. | Gương Hán-Việt | tháp (誻) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 誻 giúp nhận dạng từ láy cổ 誻誻 trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "Tiểu triện | 誻 là chữ cổ nghĩa chưa được định nghĩa rõ trong Wiktionary (rfdef). Xuất hiện trong từ láy 誻誻. Có hình tiểu triện được ghi nhận. Chưa có nguồn học thuật xác nhận đầy đủ gốc tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 沓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言沓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誻", "Unihan_Traditional (Chữ Phồn thể)": "誻", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ việc nói năng lảm nhảm hoặc tính từ tả trạng thái ồn ào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豧', '{"9000": "8468.0", "Chữ Trung Quốc": "豧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 14 | nét | 豧 | phụ | tượng hình | con lợn thở hổn hển | 豧 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ chỉ lợn thở hổn hển. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": con lợn (豧) phụ phụ thở nặng nề — hình ảnh lợn nằm thở hổn hển. | Gương Hán-Việt | phụ (豧) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 豧 giúp nhận dạng chữ cổ chỉ hành vi động vật trong bộ 豕 (lợn) trong cổ thư.", "Tự nguyên_Xie": "豧 là chữ cổ (obs-std) chỉ con lợn đang thở hổn hển. Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豕 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豕甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豧", "Unihan_Traditional (Chữ Phồn thể)": "豧", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ loài heo con. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貮', '{"9000": "8469.0", "Chữ Trung Quốc": "貮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 貮 | nhị | tượng hình | biến thể cổ của 二 (nhị), số hai | 貮 là dạng chữ cổ dùng thay cho 二 (nhị, số hai), không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": 貮 là cách viết phức tạp hơn của số hai (nhị) — dùng trong giấy tờ tài chính để tránh làm giả. | Gương Hán-Việt | nhị (二/貳) — số hai trong Hán-Việt, dùng trong đếm số thứ tự | Mở khoá kiến thức | Biết 貮 giúp nhận dạng các biến thể số đếm phức tạp trong văn bản tài chính Hán cổ.", "Tự nguyên_Xie": "貮 là biến thể cổ của số 二 (nhị, hai). Dạng chữ phức tạp hơn để tránh giả mạo trong văn bản tài chính — tương tự như 貳 (nhị phức) dùng trong séc, hợp đồng. Không có nguồn Wiktionary với cấu trúc cụ thể. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "貮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "貮", "Unihan_Traditional (Chữ Phồn thể)": "貮", "Pinyin_Xie": "èr", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Động từ | 动词 | Dùng làm số từ chỉ số hai hoặc động từ chỉ sự phản bội. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賱', '{"9000": "8470.0", "Chữ Trung Quốc": "賱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 賱 | vẫn | tượng hình | biến thể cổ của 豱 | 賱 là dị thể của 豱, không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": 賱 là dị thể của 豱, chỉ loài lợn rừng nhỏ trong thư tịch cổ. | Gương Hán-Việt | vẫn (賱) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 賱 giúp nhận dạng dị thể chữ Hán trong văn bản cổ điển.", "Tự nguyên_Xie": "賱 là dạng chữ hiếm, dị thể của 豱. Không có nguồn Wiktionary với cấu trúc cụ thể. Nghĩa liên quan đến loài lợn rừng nhỏ. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "豱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賱", "Unihan_Traditional (Chữ Phồn thể)": "賱", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ trong văn ngôn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赑', '{"9000": "8471.0", "Chữ Trung Quốc": "赑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 12 | nét | 贝 | bối | biểu nghĩa | vỏ sò — sức mạnh, của cải | 贝 | bối | biểu nghĩa | vỏ sò | 贝 | bối | biểu nghĩa | vỏ sò | 赑 là dạng giản hoá của 贔 (phồn thể), gồm ba chữ 贝 (Bối, vỏ sò) xếp chồng — hội ý sức mạnh tích lũy. Wiktionary ghi nhận {{zh-etym-triple|贝|shell}}.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": ba vỏ sò (贝贝贝) chồng lên nhau tạo ra sức mạnh tối thượng — 赑 là loài rùa thần bixi đội cả tấm bia đá. | Gương Hán-Việt | bí (赑) — ít dùng; bixi (贔屭) là loài rùa thần trong nghệ thuật Đông Á | Mở khoá kiến thức | Biết 赑 giúp đọc từ 贔屭 (bí kí) — loài rùa thần đội bia, hình ảnh phổ biến trong kiến trúc đền đài Việt Nam và Trung Quốc.", "Tự nguyên_Xie": "赑 là giản thể của 贔, được tạo từ ba chữ 贝 (bối, vỏ sò) xếp theo thể tam điệp — ba vỏ sò tượng trưng cho sức mạnh lớn lao. Wiktionary ghi rõ {{zh-etym-triple|贝|shell}}. Chỉ loài vật thần thoại giống rùa khổng lồ (con bixi) có sức mạnh phi thường, thường được điêu khắc đội bia đá. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài vật giống như rùa", "Hạng Tần Suất (Jun Da)": "8471.0", "Tần Suất % (Jun Da)": "99.9996640897", "GavinGrover_Once (Chiết tự trực tiếp)": "贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "赑", "Unihan_Traditional (Chữ Phồn thể)": "贔", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng trong từ ghép để chỉ con rùa đá hoặc sự gắng sức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赹', '{"9000": "8472.0", "Chữ Trung Quốc": "赹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 11 | nét | 赹 | quỳnh | tượng hình | chữ cổ, nghĩa chưa rõ | 赹 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ, nghĩa chưa được định nghĩa đầy đủ trong nguồn hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": 赹 là chữ cổ có bộ 走 (đi) — liên quan đến chuyển động hay hành trình trong cổ thư. | Gương Hán-Việt | quỳnh (赹) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 赹 giúp nhận dạng chữ cổ bộ 走 trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "赹 là chữ cổ với nghĩa chưa được xác định rõ (Wiktionary ghi rfdef). Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 匀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走匀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赹", "Unihan_Traditional (Chữ Phồn thể)": "赹", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để miêu tả sự cô độc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赽', '{"9000": "8473.0", "Chữ Trung Quốc": "赽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 11 | nét | 赽 | quyết | tượng hình | chữ cổ, nghĩa chưa rõ | 赽 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ, nghĩa chưa được định nghĩa đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": 赽 có thể liên quan đến bộ 走 (đi) và sự dứt khoát (quyết) — nhưng nghĩa cụ thể chưa xác định. | Gương Hán-Việt | quyết (赽) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 赽 giúp nhận dạng chữ cổ bộ 走 trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "赽 là chữ cổ với nghĩa chưa được xác định rõ (Wiktionary ghi rfdef). Ghi nhận âm Middle Chinese và Old Chinese. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "赽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "赽", "Unihan_Traditional (Chữ Phồn thể)": "赽", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ hành động chạy nhanh hoặc tính từ bổ nghĩa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踃', '{"9000": "8474.0", "Chữ Trung Quốc": "踃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 踃 | tiêu | tượng hình | chữ cổ bộ 足, nghĩa chưa rõ | 踃 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ, bộ 足 (chân), nghĩa chưa được định nghĩa đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bộ 足 (chân) trong 踃 gợi hành động chân — có thể là bước đi tiêu tao, nhẹ nhàng. | Gương Hán-Việt | tiêu (踃) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 踃 giúp nhận dạng chữ cổ bộ 足 trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "踃 là chữ cổ với nghĩa chưa được xác định rõ (Wiktionary ghi rfdef). Ghi nhận âm Middle Chinese và Old Chinese. Chữ có bộ 足 (chân), có thể liên quan đến hành động đi lại. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "胃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踃", "Unihan_Traditional (Chữ Phồn thể)": "踃", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ động tác nhảy hoặc di chuyển nhanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹞', '{"9000": "8475.0", "Chữ Trung Quốc": "蹞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹞 | quỹ | tượng hình | nửa bước chân; đơn vị đo lường bước đi cổ đại | 蹞 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 足, chỉ đơn vị đo bước chân (nửa bước). Chưa có nguồn học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỹ\": bộ 足 (chân) trong 蹞 — nửa bước chân, đơn vị nhỏ nhất của hành trình dài vạn dặm. | Gương Hán-Việt | quỹ (蹞) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蹞 giúp hiểu các đơn vị đo lường cổ đại trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "蹞 chỉ nửa bước chân — đơn vị đo lường bước đi trong cổ thư Trung Hoa. Không có nguồn Wiktionary với cấu trúc Han compound cụ thể. Chữ bộ 足 (chân). Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "螞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 頃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊頃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹞", "Unihan_Traditional (Chữ Phồn thể)": "蹞", "Pinyin_Xie": "kuǐ", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ hoặc lượng từ chỉ khoảng cách rất ngắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹧', '{"9000": "8476.0", "Chữ Trung Quốc": "蹧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹧 | tao | tượng hình | làm hỏng, làm nát; bộ 足 (chân) ám chỉ giẫm đạp | 蹧 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ có bộ 足 (chân), hàm ý giẫm đạp làm hỏng. Nghĩa: làm hỏng, làm nát, lãng phí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bộ 足 (chân) giẫm lên làm tao hỏng — 蹧 là phá hỏng, lãng phí. | Gương Hán-Việt | tao (蹧) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蹧 giúp đọc từ phương ngôn chỉ sự lãng phí và phá hoại trong cổ thư.", "Tự nguyên_Xie": "蹧 nghĩa là làm hỏng, làm nát hoặc lãng phí. Bộ 足 (chân) gợi hình ảnh giẫm đạp. Không có nguồn Wiktionary với cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hỏng, nát", "Hạng Tần Suất (Jun Da)": "8476.0", "Tần Suất % (Jun Da)": "99.9996666736", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹧", "Unihan_Traditional (Chữ Phồn thể)": "蹧", "Pinyin_Xie": "zāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự tàn hại hoặc tính từ chỉ trạng thái tồi tệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躻', '{"9000": "8477.0", "Chữ Trung Quốc": "躻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 15 | nét | 躻 | khổng | tượng hình | bộ 身 (thân), nghĩa chưa rõ | 躻 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 身 (thân thể). Chưa có nguồn học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổng\": bộ 身 (thân) trong 躻 — thân thể lớn lao, khổng lồ như Khổng Tử. | Gương Hán-Việt | khổng (躻) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 躻 giúp nhận dạng chữ cổ bộ 身 trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "躻 là chữ cổ với nghĩa chưa được xác định rõ. Bộ 身 (thân thể) gợi liên quan đến cơ thể. Không có nguồn Wiktionary cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 空", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身空", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躻", "Unihan_Traditional (Chữ Phồn thể)": "躻", "Pinyin_Xie": "kong", "Âm Hán Việt_Xie": "khổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ thân thể hoặc tính từ chỉ sự trống rỗng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躿', '{"9000": "8478.0", "Chữ Trung Quốc": "躿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 18 | nét | 躿 | khang | tượng hình | dong dỏng cao; bộ 身 (thân thể) | 躿 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 身, chỉ dáng người dong dỏng cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khang\": thân (身) khang trang dong dỏng — 躿 là dáng người cao ráo mạnh khỏe. | Gương Hán-Việt | khang (躿) — ít dùng; liên quan đến ''khang trang'', ''khang kiện'' | Mở khoá kiến thức | Biết 躿 giúp nhận dạng chữ cổ chỉ vóc dáng trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "躿 là chữ cổ chỉ dáng người dong dỏng cao. Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound, chỉ ghi rfdef. Bộ 身 (thân thể) gợi liên quan đến vóc dáng. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dong dỏng; cao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 康", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身康", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "康", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躿", "Unihan_Traditional (Chữ Phồn thể)": "躿", "Pinyin_Xie": "kāng", "Âm Hán Việt_Xie": "khang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả vóc dáng cao lớn của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄑', '{"9000": "8479.0", "Chữ Trung Quốc": "鄑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 12 | nét | 鄑 | tư | tượng hình | tên địa danh ở Sơn Đông; bộ 邑 (ấp, đất đai) | 鄑 có bộ 邑 (ấp — đất đai, địa danh) — đặc trưng của chữ chỉ địa danh. Tiểu triện và Lục thư thông có ghi nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": bộ 邑 (ấp) trong 鄑 — địa danh cổ ở Sơn Đông, đất đai tư hữu thời cổ đại. | Gương Hán-Việt | tư (鄑) — địa danh cổ ở Sơn Đông | Mở khoá kiến thức | Biết 鄑 giúp đọc địa danh lịch sử ở Sơn Đông trong sử sách Trung Hoa cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鄑 là tên địa danh ở Sơn Đông, Trung Quốc thời cổ đại. Bộ 邑 (ấp) chỉ đây là địa danh. Tiểu triện và Lục thư thông có ghi nhận. Nghĩa cụ thể chưa được định nghĩa đầy đủ trong Wiktionary (rfdef). Chưa có nguồn học thuật xác nhận chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên địa điểm", "Hạng Tần Suất (Jun Da)": "8479.0", "Tần Suất % (Jun Da)": "99.9996692575", "GavinGrover_Once (Chiết tự trực tiếp)": "晋 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰晋阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄑", "Unihan_Traditional (Chữ Phồn thể)": "鄑", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đây là danh từ riêng dùng để chỉ tên một vùng đất thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酼', '{"9000": "8480.0", "Chữ Trung Quốc": "酼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酼 | hải | tượng hình | chữ cổ bộ 酉 (rượu), nghĩa chưa rõ | 酼 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 酉 (rượu), nghĩa chưa được định nghĩa đầy đủ. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hải\": bộ 酉 (rượu) trong 酼 — một loại rượu hay dấm cổ đại bí ẩn như biển hải mênh mông. | Gương Hán-Việt | hải (酼) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 酼 giúp nhận dạng chữ cổ bộ 酉 trong thư tịch nấu rượu, ẩm thực Hán cổ.", "Tự nguyên_Xie": "酼 là chữ cổ bộ 酉 (rượu), nghĩa chưa được xác định. Không có nguồn Wiktionary cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "酼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 㐬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉㐬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酼", "Unihan_Traditional (Chữ Phồn thể)": "酼", "Pinyin_Xie": "hǎi", "Âm Hán Việt_Xie": "hải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại thực phẩm được ướp muối hoặc làm mắm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醁', '{"9000": "8481.0", "Chữ Trung Quốc": "醁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 醁 | lục | tượng hình | loại rượu màu xanh lục; bộ 酉 (rượu) | 醁 có bộ 酉 (rượu) — đặc trưng của chữ chỉ loại rượu. Chữ xuất hiện trong từ 醽醁 (linh lục), chỉ loại rượu xanh lục quý hiếm của cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": rượu (酉) màu lục (xanh) — 醁 là loại rượu xanh lục quý trong từ 醽醁. | Gương Hán-Việt | linh lục (醽醁) — tên loại rượu xanh lục quý hiếm trong thơ ca cổ điển | Mở khoá kiến thức | Biết 醁 giúp đọc từ 醽醁 trong thơ Đường và thơ chữ Hán Việt Nam.", "Tự nguyên_Xie": "醁 chỉ loại rượu màu xanh lục quý hiếm thời cổ đại. Bộ 酉 (rượu) chỉ đây là loại đồ uống. Xuất hiện trong từ 醽醁 (linh lục). Wiktionary ghi nhận âm nhưng không có cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh lục 醽醁)", "Hạng Tần Suất (Jun Da)": "8481.0", "Tần Suất % (Jun Da)": "99.9996702911", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醁", "Unihan_Traditional (Chữ Phồn thể)": "醁", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong các từ ghép chỉ tên gọi các loại rượu ngon cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醕', '{"9000": "8482.0", "Chữ Trung Quốc": "醕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 16 | nét | 醕 | thuần | tượng hình | gạo nếp; rượu thuần khiết; bộ 酉 (rượu) | 醕 có bộ 酉 (rượu) — liên quan đến gạo nếp hoặc rượu thuần khiết. Chỉ có hình Lục thư thông (biên soạn cuối Minh), chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": rượu (酉) thuần (醕) — nấu từ gạo nếp thuần khiết, không pha tạp. | Gương Hán-Việt | thuần (醕) — ít dùng; liên quan đến ''thuần khiết'', ''thuần túy'' | Mở khoá kiến thức | Biết 醕 giúp nhận dạng chữ chỉ gạo nếp và rượu thuần trong thư tịch ẩm thực cổ đại.", "Tự nguyên_Xie": "Lục thư thông | 醕 chỉ gạo nếp hoặc rượu nếp thuần khiết. Bộ 酉 (rượu) gợi liên quan đến quá trình lên men, nấu rượu. Chỉ có hình Lục thư thông (biên soạn cuối đời Minh), chữ tạo muộn, không có giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận gốc tự chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo nếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 亯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉亯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醕", "Unihan_Traditional (Chữ Phồn thể)": "醕", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Dùng làm tính từ miêu tả hương vị rượu đậm đà hoặc sự thuần khiết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醥', '{"9000": "8483.0", "Chữ Trung Quốc": "醥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 18 | nét | 醥 | phiếu | tượng hình | gạo nếp; bộ 酉 (rượu) | 醥 có bộ 酉 (rượu) — liên quan đến gạo nếp hoặc quá trình lên men. Wiktionary ghi nhận âm nhưng nghĩa chưa được định nghĩa đầy đủ (rfdef).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiếu\": bộ 酉 (rượu) trong 醥 — rượu nếp bay phiếu phiếu hương thơm. | Gương Hán-Việt | phiếu (醥) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 醥 giúp nhận dạng chữ chỉ gạo nếp và rượu nếp trong thư tịch ẩm thực cổ đại.", "Tự nguyên_Xie": "醥 chỉ gạo nếp, tương tự 醕. Bộ 酉 (rượu) gợi liên quan đến lên men hoặc nấu rượu nếp. Wiktionary ghi nhận âm Middle Chinese và Old Chinese nhưng không có cấu trúc Han compound, chỉ ghi rfdef. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo nếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醥", "Unihan_Traditional (Chữ Phồn thể)": "醥", "Pinyin_Xie": "piǎo", "Âm Hán Việt_Xie": "phiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ loại rượu nếp có màu sắc hoặc độ trong nhất định. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釪', '{"9000": "8484.0", "Chữ Trung Quốc": "釪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 金 | kim | biểu nghĩa | kim loại | 于 | vu | biểu âm | âm gần huá | 釪 = 金 (Kim, biểu nghĩa: kim loại) + 于 (Vu, biểu âm); chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": kim loại (金) tiếng vu vu — 釪 là cái chuông nhỏ reng reng hoặc bát khất thực của nhà sư. | Gương Hán-Việt | vu (釪) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 釪 giúp nhận dạng chữ chỉ vật dụng Phật giáo bằng kim loại trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 金 (kim) chỉ kim loại, 于 (vu) cho âm đọc gần huá. Có hai nghĩa: bát khất thực của nhà sư (alms bowl) và chuông nhỏ. Cả hai đều là vật dụng bằng kim loại. Chưa có nguồn học thuật xác nhận gốc tự chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một cái chuông nhỏ; một bát khất thực", "Hạng Tần Suất (Jun Da)": "8484.0", "Tần Suất % (Jun Da)": "99.9996718414", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 于", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金于", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "于", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釪", "Unihan_Traditional (Chữ Phồn thể)": "釪", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đóng vai trò danh từ chỉ các vật dụng bằng kim loại như chuông hoặc bát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈵', '{"9000": "8485.0", "Chữ Trung Quốc": "鈵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 鈵 | bính | tượng hình | chữ cổ bộ 金 (kim loại), nghĩa chưa rõ | 鈵 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 金 (kim loại), nghĩa chưa được định nghĩa đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": bộ 金 (kim loại) trong 鈵 — một loại vật dụng hay dụng cụ kim loại cổ đại không rõ hình dạng. | Gương Hán-Việt | bính (鈵) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 鈵 giúp nhận dạng chữ cổ bộ 金 trong thư tịch kỹ nghệ kim loại Hán cổ.", "Tự nguyên_Xie": "鈵 là chữ cổ bộ 金, nghĩa chưa được xác định rõ (Wiktionary ghi rfdef). Wiktionary ghi nhận âm Middle Chinese và Old Chinese. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 丙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金丙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈵", "Unihan_Traditional (Chữ Phồn thể)": "鈵", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại vũ khí hoặc vật dụng bằng kim loại cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銒', '{"9000": "8486.0", "Chữ Trung Quốc": "銒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銒 | hình | tượng hình | chữ cổ bộ 金 (kim loại), nghĩa chưa rõ | 銒 không có cấu trúc hình thanh/hội ý rõ ràng được ghi nhận. Chữ cổ bộ 金 (kim loại). Chưa có nguồn học thuật cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": bộ 金 (kim loại) trong 銒 — một vật dụng kim loại có hình dạng đặc trưng thời cổ đại. | Gương Hán-Việt | hình (銒) — ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 銒 giúp nhận dạng chữ cổ bộ 金 trong thư tịch đồ kim khí Hán cổ.", "Tự nguyên_Xie": "銒 là chữ cổ bộ 金, nghĩa chưa được xác định. Không có nguồn Wiktionary với cấu trúc Han compound cụ thể. Chưa có nguồn học thuật xác nhận gốc tự. Chữ tạo muộn, chưa thấy trong giáp cốt hay kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "銒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 幵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金幵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銒", "Unihan_Traditional (Chữ Phồn thể)": "銒", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ một loại bình hoặc đồ dùng bằng đồng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('銙', '{"9000": "8487.0", "Chữ Trung Quốc": "銙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 銙 | khoá | tượng hình | đồ trang trí trên thắt lưng; bộ 金 (kim loại) | 銙 có bộ 金 (kim loại) — chỉ đây là vật dụng kim loại. Chữ chỉ đồ trang trí hoặc khóa gắn trên thắt lưng thời cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoá\": kim loại (金) làm thành khoá (銙) thắt lưng — đồ trang trí quý giá trên đai lưng của quan lại. | Gương Hán-Việt | khoá (銙) — liên quan đến ''khoá'' trong tiếng Việt; đồ trang trí thắt lưng | Mở khoá kiến thức | Biết 銙 giúp đọc các từ chỉ trang phục lễ nghi trong cổ thư Đường-Tống và Hán Nôm.", "Tự nguyên_Xie": "銙 chỉ đồ trang sức hay khóa gắn trên thắt lưng trong trang phục cổ đại. Bộ 金 (kim) chỉ làm bằng kim loại. Wiktionary ghi nhận: đây là đồ trang trí bằng vàng/ngọc gắn vào thắt lưng trong lễ phục thời Đường-Tống. Trong tiếng Việt, ''khoá'' có thể từ âm Hán-Việt này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoá; như \"chìa khoá; khoá sổ\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "銙", "Unihan_Traditional (Chữ Phồn thể)": "銙", "Pinyin_Xie": "kuǎ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các bộ phận trang trí trên đai lưng hoặc đồ vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋺', '{"9000": "8488.0", "Chữ Trung Quốc": "鋺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 鋺 | uyển | tượng hình | bát kim loại; biến thể của 碗; bộ 金 (kim loại) | 鋺 là biến thể của 碗 (uyển — cái bát), dùng bộ 金 (kim loại) thay vì 石 (đá/sứ). Chỉ loại bát làm bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": cái bát (碗/uyển) làm bằng kim loại (金) — 鋺 là bát kim loại, khác với 碗 bát sứ. | Gương Hán-Việt | uyển (碗/鋺) — ''bát'' trong tiếng Việt từ âm Hán-Việt uyển/oan | Mở khoá kiến thức | Biết 鋺 giúp phân biệt các biến thể chữ 碗 (bát) theo chất liệu trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "鋺 là biến thể của 碗 (uyển — cái bát), dùng bộ 金 (kim loại) để chỉ bát kim loại thay vì bát sứ/gốm. Cấu trúc hình thanh rõ ràng nhưng không có nguồn Wiktionary với Han compound cụ thể. Chưa thấy trong giáp cốt hay kim văn. Chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể của 碗 [wan3]", "Hạng Tần Suất (Jun Da)": "8488.0", "Tần Suất % (Jun Da)": "99.9996739086", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋺", "Unihan_Traditional (Chữ Phồn thể)": "鋺", "Pinyin_Xie": "yuǎn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Được dùng như danh từ chỉ vật dụng đựng thức ăn tương đương với cái bát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錗', '{"9000": "8489.0", "Chữ Trung Quốc": "錗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錗 | nội | tượng hình | kim loại hiếm, âm nèi | 錗 là chữ tạo muộn thuộc bộ 金 (Kim), chưa có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật. Chữ này cực kỳ hiếm gặp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nội\": chữ bộ 金 (kim loại) siêu hiếm, đọc âm nèi — gần như không xuất hiện trong văn bản hiện đại. | Gương Hán-Việt | Chữ 錗 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 錗 giúp nhận diện ký hiệu kim loại hiếm trong văn bản cổ hoặc bảng tra ký tự.", "Tự nguyên_Xie": "Chữ tạo muộn thuộc bộ 金 (kim loại). Chưa có nguồn Wiktionary hay giáp cốt/kim văn ghi nhận cấu trúc của 錗. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "錗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錗", "Unihan_Traditional (Chữ Phồn thể)": "錗", "Pinyin_Xie": "nèi", "Âm Hán Việt_Xie": "nội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại đồ trang sức hoặc vật dụng bằng kim loại thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錥', '{"9000": "8490.0", "Chữ Trung Quốc": "錥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錥 | úc | tượng hình | vật bằng kim loại, âm yù | 錥 là chữ tạo muộn thuộc bộ 金 (Kim). Wiktionary ghi nhận chữ này chỉ dùng trong tổ hợp 鎢錥, không phân tích rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"úc\": 錥 chỉ xuất hiện trong 鎢錥 — hộp/nồi kim loại, bộ 金 cho thấy chất liệu. | Gương Hán-Việt | Chữ 錥 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 錥 giúp đọc hiểu tổ hợp cổ 鎢錥 trong văn bản lịch sử.", "Tự nguyên_Xie": "Chữ bộ 金, chỉ xuất hiện trong tổ hợp 鎢錥 (wūyù) chỉ loại hộp/vật dụng kim loại. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "錌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 育", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金育", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "育", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錥", "Unihan_Traditional (Chữ Phồn thể)": "錥", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "úc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại dụng cụ đựng nước bằng kim loại thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍓', '{"9000": "8491.0", "Chữ Trung Quốc": "鍓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍓 | tích | tượng hình | kim loại (berili), âm jí | 鍓 là chữ bộ 金 (Kim) dùng để phiên âm tên nguyên tố berili (Be). Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": 鍓 bộ 金 là ký hiệu Hán cho kim loại berili — nhẹ, cứng, dùng trong công nghệ cao. | Gương Hán-Việt | Chữ 鍓 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鍓 giúp nhận diện ký hiệu nguyên tố berili trong văn bản hóa học chữ Hán cổ.", "Tự nguyên_Xie": "Chữ tạo muộn thuộc bộ 金, dùng để phiên âm tên nguyên tố hóa học berili (beryllium, Be). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "berili", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍓", "Unihan_Traditional (Chữ Phồn thể)": "鍓", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ hóa học để chỉ nguyên tố beryli. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍟', '{"9000": "8492.0", "Chữ Trung Quốc": "鍟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 星 | tinh | biểu âm | ngôi sao (cho âm) | 鍟 = 金 (Kim, biểu nghĩa: kim loại) + 星 (Tinh, biểu âm: cho âm xīng). Chữ hình thanh. Là dị thể của 鉎, chỉ gỉ sét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": 鍟 = kim loại (金) + ngôi sao (星) — hình ảnh kim loại bị gỉ sét lấm tấm như sao trên bầu trời. | Gương Hán-Việt | Chữ 鍟 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鍟 giúp nhận diện dị thể của 鉎 (gỉ sét) trong văn bản phương ngữ Quảng Đông.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 金 chỉ nghĩa (kim loại), 星 cho âm xīng. Wiktionary ghi nhận đây là dị thể của 鉎 (gỉ sét trong tiếng Quảng Đông). Cấu trúc hình thanh điển hình của nhóm chữ bộ Kim. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鍟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 星", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金星", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍟", "Unihan_Traditional (Chữ Phồn thể)": "鍟", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ lớp chất bẩn hoặc gỉ sét hình thành trên bề mặt kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎍', '{"9000": "8493.0", "Chữ Trung Quốc": "鎍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎍 | toả | tượng hình | xích, dây kim loại, âm suǒ | 鎍 là chữ bộ 金 (Kim) chỉ chuỗi/dây điện. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toả\": 鎍 bộ 金 gợi hình chuỗi xích kim loại — liên tưởng đến 鎖 (khoá) cùng âm suǒ. | Gương Hán-Việt | Gần với 鎖 (toả — khoá, xích) trong tiếng Việt Hán-Việt. | Mở khoá kiến thức | Biết 鎍 giúp nhận diện biến thể chữ chỉ xích/dây kim loại trong văn bản cổ.", "Tự nguyên_Xie": "Chữ tạo muộn thuộc bộ 金, nghĩa là chuỗi hoặc dây (kim loại). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuỗi; dây điện", "Hạng Tần Suất (Jun Da)": "8493.0", "Tần Suất % (Jun Da)": "99.9996764925", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 索", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金索", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "索", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鎍", "Unihan_Traditional (Chữ Phồn thể)": "鎍", "Pinyin_Xie": "suǒ", "Âm Hán Việt_Xie": "tác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dây xích hoặc dây kim loại dùng để buộc trói. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏿', '{"9000": "8494.0", "Chữ Trung Quốc": "鏿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鏿 | tranh | tượng hình | chữ liên quan tộc Yi, âm chēng | 鏿 là chữ bộ 金 (Kim) cực hiếm. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": 鏿 bộ 金, âm chēng — chữ cực hiếm, hầu như chỉ xuất hiện trong bảng tra ký tự Unicode. | Gương Hán-Việt | Chữ 鏿 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鏿 giúp nhận diện ký tự hiếm trong bộ 金 khi tra từ điển Unicode.", "Tự nguyên_Xie": "Chữ tạo muộn thuộc bộ 金. Chưa có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 棠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金棠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "棠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏿", "Unihan_Traditional (Chữ Phồn thể)": "鏿", "Pinyin_Xie": "chēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ hoặc từ tượng thanh mô tả âm thanh vang lên khi kim loại va vào nhau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐎', '{"9000": "8495.0", "Chữ Trung Quốc": "鐎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐎 | tiêu | tượng hình | đồ đồng có chân, âm jiāo | 鐎 là chữ bộ 金 (Kim) chỉ loại đồ đồng có chân. Wiktionary ghi nhận có dùng trong tổ hợp 鐎斗 nhưng không có phân tích hình thanh cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": 鐎 bộ 金 gợi hình chiếc đỉnh đồng có chân nhọn (鐎斗) — đồ đựng sang trọng thời cổ đại. | Gương Hán-Việt | Chữ 鐎 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鐎 giúp đọc hiểu tổ hợp 鐎斗 trong văn bản lịch sử về đồ đồng cổ đại Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 金, chỉ loại đồ đồng cổ đại (đỉnh/nồi có chân). Xuất hiện trong tổ hợp 鐎斗 (jiāodǒu) — đồ đựng bằng đồng thời cổ. Không có dữ liệu giáp cốt hay kim văn chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鎎", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐎", "Unihan_Traditional (Chữ Phồn thể)": "鐎", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại ấm đồng ba chân có tay cầm thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐤', '{"9000": "8496.0", "Chữ Trung Quốc": "鐤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐤 | đính | tượng hình | đỉnh đồng lớn, đồ tế lễ, âm dǐng | 鐤 là chữ bộ 金 (Kim) chỉ chiếc đỉnh đồng khổng lồ dùng trong tế lễ. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đính\": 鐤 bộ 金 cùng âm với 鼎 (đỉnh) — đều chỉ đồ đồng tế lễ uy nghi thời cổ. | Gương Hán-Việt | Gần với 鼎 (đỉnh — đồ đồng tế lễ) trong Hán-Việt. | Mở khoá kiến thức | Biết 鐤 giúp nhận diện biến thể chữ chỉ đồ đồng tế lễ trong văn bản cổ.", "Tự nguyên_Xie": "Chữ bộ 金, chỉ loại đỉnh đồng lớn hai tai dùng trong lễ tế. Âm dǐng gần với 鼎 (đỉnh — chiếc đỉnh ba chân). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 鼎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金鼎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鼎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐤", "Unihan_Traditional (Chữ Phồn thể)": "鐤", "Pinyin_Xie": "dǐng", "Âm Hán Việt_Xie": "đính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái vạc lớn dùng làm đồ tế khí hoặc nấu ăn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锧', '{"9000": "8497.0", "Chữ Trung Quốc": "锧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 锧 | chất | tượng hình | bàn sắt hành hình, âm zhì | 锧 là chữ bộ 金 (Kim) chỉ chiếc bàn/thớt sắt dùng trong hành hình thời cổ đại. Không có phân tích hình thanh hay hội ý xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chất\": 锧 bộ 金 là chiếc bàn sắt hành hình — hình ảnh u ám của công cụ xử tử thời phong kiến. | Gương Hán-Việt | Chữ 锧 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 锧 giúp đọc hiểu văn bản lịch sử về hình phạt cổ đại Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 金, chỉ chiếc bàn sắt (đòn kê) dùng trong hành hình (斧鑕 — rìu và bàn chặt đầu). Wiktionary ghi nhận đây là chữ văn học. Không có dữ liệu giáp cốt hay kim văn chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bàn sắt; cái thớt; cái đòn kê", "Hạng Tần Suất (Jun Da)": "8497.0", "Tần Suất % (Jun Da)": "99.99968011", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 质", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅质", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "质", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锧", "Unihan_Traditional (Chữ Phồn thể)": "鑕", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái thớt gỗ hoặc bệ đá dùng để kê đầu khi thi hành án chém thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閧', '{"9000": "8498.0", "Chữ Trung Quốc": "閧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 14 | nét | 閧 | hổng | tượng hình | ồn ào, ẩu đả, âm hòng | 閧 là dị thể của 鬨, được đơn giản hóa bằng cách thay bộ 鬥 bằng bộ 門. Chỉ cảnh ồn ào, đánh nhau hỗn loạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hổng\": 閧 bộ 門 là dạng đơn giản của 鬨 — tiếng ồn ào, náo loạn bùng lên như lửa qua cổng. | Gương Hán-Việt | \"Hổng\" trong Hán-Việt chỉ cảnh ồn ào náo loạn — ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 閧 giúp nhận diện dị thể của 鬨 (hỗn loạn, náo động) trong văn bản cổ.", "Tự nguyên_Xie": "閧 là dị thể không chính thống của 鬨 (hổng — ồn ào, đánh nhau), thay 鬥 (đấu tranh) bằng 門 (cổng) — đơn giản hóa hình thức. Wiktionary ghi: \"Unorthodox character {{Han simp|鬨|f=鬥|t=門}}\". Xem 鬨 để hiểu đầy đủ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh nhau ầm ĩ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閧", "Unihan_Traditional (Chữ Phồn thể)": "閧", "Pinyin_Xie": "hòng", "Âm Hán Việt_Xie": "hống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng để mô tả hành động gây gổ hoặc tình trạng ồn ào, hỗn loạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闛', '{"9000": "8499.0", "Chữ Trung Quốc": "闛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 19 | nét | 闛 | đường | tượng hình | tiếng trống, âm táng/tāng | 闛 là chữ bộ 門 (Môn) dùng làm từ tượng thanh (onomatopoeia) chỉ tiếng trống. Không có phân tích hình thanh hay hội ý xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": 闛 bộ 門, âm táng — tượng thanh tiếng trống, như tiếng \"đùng đùng\" vang qua cổng. | Gương Hán-Việt | Chữ 闛 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 闛 giúp nhận diện từ tượng thanh tiếng trống trong văn bản thơ ca cổ điển.", "Tự nguyên_Xie": "Chữ bộ 門, dùng làm từ tượng thanh chỉ tiếng trống vang (táng/tāng). Wiktionary ghi nhận: {{lb|zh|onomatopoeia}} sound of a drum. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "闛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闛", "Unihan_Traditional (Chữ Phồn thể)": "闛", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu xuất hiện trong các văn bản cổ để chỉ cửa hoặc âm thanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隝', '{"9000": "8500.0", "Chữ Trung Quốc": "隝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 13 | nét | 阝 | biểu nghĩa | đồi đất (bộ phụ của 阜) | 鳥 | điểu | biểu âm | chim (cho âm dǎo) | 隝 = 阝(bộ phụ của 阜 — Phụ, biểu nghĩa: đất cao) + 鳥 (Điểu, biểu âm: cho âm dǎo). Chữ hình thanh. Là dị thể của 島 (đảo — hòn đảo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảo\": 隝 = đất cao (阝) + chim (鳥) — hòn đảo là nơi đất nổi lên giữa biển, chim chóc tụ hội. | Gương Hán-Việt | \"Đảo\" trong Hán-Việt (hòn đảo) — như \"bán đảo\", \"quần đảo\" trong tiếng Việt. | Mở khoá kiến thức | Biết 隝 giúp nhận diện dị thể của 島 (đảo) trong văn bản cổ và hiểu cách viết chữ đảo theo lối cũ.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 阝(阜) chỉ đất cao, 鳥 cho âm dǎo. Wiktionary ghi: {{Han compound|阜|alt1=阝|鳥|ls=psc|c1=s|c2=p}}. Đây là dị thể của 島 (đảo). Trên hòn đảo thường có chim, nên 鳥 vừa cho âm vừa gợi hình. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "皝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隝", "Unihan_Traditional (Chữ Phồn thể)": "隝", "Pinyin_Xie": "dǎo", "Âm Hán Việt_Xie": "đảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là dạng chữ cổ hoặc dị thể của chữ đảo, dùng để chỉ vùng đất giữa biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隥', '{"9000": "8501.0", "Chữ Trung Quốc": "隥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 14 | nét | 隥 | đặng | tượng hình | dốc leo, âm dèng | 隥 là chữ bộ 阜 (Phụ — đất cao, đồi núi) chỉ sườn dốc, chỗ leo lên. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đặng\": 隥 bộ 阜 (đất cao) chỉ dốc leo — gợi hình bậc thang đất trên đồi. | Gương Hán-Việt | Gần với 登 (đăng — leo lên) trong Hán-Việt. | Mở khoá kiến thức | Biết 隥 giúp đọc hiểu miêu tả địa hình dốc núi trong văn thơ cổ điển.", "Tự nguyên_Xie": "Chữ bộ 阜, chỉ chỗ dốc, sườn đồi cần leo lên (ascent, incline). Wiktionary ghi nhận có trung cổ âm và thượng cổ âm. Không có dữ liệu giáp cốt hay kim văn chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tùy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隥", "Unihan_Traditional (Chữ Phồn thể)": "隥", "Pinyin_Xie": "dèng", "Âm Hán Việt_Xie": "đặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ con đường hoặc lối đi có độ dốc cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隦', '{"9000": "8502.0", "Chữ Trung Quốc": "隦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 15 | nét | 隦 | giảo | tượng hình | ghen tị, âm jiǎo | 隦 là chữ bộ 阜 (Phụ) chỉ trạng thái ghen tị. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giảo\": 隦 bộ 阜 chỉ sự ghen tị — cảm giác như đứng trên đồi nhìn xuống người khác với lòng đố kị. | Gương Hán-Việt | Chữ 隦 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 隦 giúp nhận diện từ hiếm chỉ sự ghen tị trong văn bản cổ.", "Tự nguyên_Xie": "Chữ bộ 阜, nghĩa là ghen tị (jealous). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghen tị", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隦", "Unihan_Traditional (Chữ Phồn thể)": "隦", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Diễn tả tâm lý không bằng lòng hoặc đố kỵ với người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靱', '{"9000": "8503.0", "Chữ Trung Quốc": "靱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 12 | nét | 靱 | nhẫn | tượng hình | dẻo dai, bền bỉ, âm rèn | 靱 là chữ bộ 革 (Cách — da thuộc) chỉ tính chất dẻo dai, bền bỉ. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhẫn\": 靱 bộ 革 (da) là sự dẻo dai như da thuộc — chịu lực mà không gãy, giống tính cách nhẫn nại. | Gương Hán-Việt | Gần với 韌 (nhẫn — dẻo dai, bền bỉ) trong Hán-Việt tiếng Việt. | Mở khoá kiến thức | Biết 靱 giúp nhận diện biến thể chữ chỉ sự dẻo dai trong văn bản cổ, liên quan đến 韌 thông dụng hơn.", "Tự nguyên_Xie": "Chữ bộ 革, nghĩa là dẻo dai và bền chắc (strong and pliable). Bộ 革 (da thuộc) gợi hình chất liệu da vừa chắc vừa dẻo. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lương", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 刄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革刄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靱", "Unihan_Traditional (Chữ Phồn thể)": "靱", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng để chỉ tính chất vật liệu hoặc ý chí kiên cường, không dễ đứt gãy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞪', '{"9000": "8504.0", "Chữ Trung Quốc": "鞪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 18 | nét | 敄 | biểu âm | cho âm mù | 革 | cách | biểu nghĩa | da thuộc | 鞪 = 敄 (biểu âm: cho âm mù) + 革 (Cách, biểu nghĩa: da thuộc). Chữ hình thanh. Chỉ đồ vật liên quan đến da thuộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": 鞪 = da thuộc (革) + 敄 (âm) — vật dụng bằng da, chữ hình thanh điển hình của nhóm bộ Cách. | Gương Hán-Việt | Chữ 鞪 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鞪 giúp nhận diện chữ hình thanh hiếm thuộc bộ 革 trong văn bản cổ.", "Tự nguyên_Xie": "Chữ hình thanh: 敄 cho âm mù, bộ 革 chỉ nghĩa (da thuộc). Wiktionary ghi: {{Han compound|敄|革|c1=p|c2=s|t2=leather|ls=psc}}. Chữ cực hiếm, không có dữ liệu giáp cốt hay kim văn chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敄 + 革", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敄革", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞪", "Unihan_Traditional (Chữ Phồn thể)": "鞪", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng để chỉ bộ phận dây cương ngựa hoặc hành động buộc chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞺', '{"9000": "8505.0", "Chữ Trung Quốc": "鞺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 20 | nét | 鞺 | đường | tượng hình | tiếng trống, âm tāng | 鞺 là chữ bộ 革 (Cách — da thuộc, trống da) chỉ tiếng trống. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": 鞺 bộ 革 (da trống) gợi tiếng trống đùng đùng — da căng mặt trống tạo âm thanh vang dội. | Gương Hán-Việt | Chữ 鞺 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鞺 giúp nhận diện từ tượng thanh tiếng trống trong văn bản thơ ca cổ điển.", "Tự nguyên_Xie": "Chữ bộ 革, chỉ tiếng trống (the sound of drums). Bộ 革 (da thuộc) liên quan đến mặt trống làm bằng da. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "麺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 堂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革堂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞺", "Unihan_Traditional (Chữ Phồn thể)": "鞺", "Pinyin_Xie": "tāng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Dùng để mô phỏng âm thanh mạnh mẽ của tiếng trống hoặc tiếng vang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞿', '{"9000": "8506.0", "Chữ Trung Quốc": "鞿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 21 | nét | 鞿 | ky | tượng hình | hàm thiếc ngựa, âm jī | 鞿 là chữ bộ 革 (Cách — da thuộc) chỉ phần hàm thiếc của dây cương ngựa (bit — bộ phận đặt trong miệng ngựa). Không có phân tích hình thanh hay hội ý xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ky\": 鞿 bộ 革 là hàm thiếc ngựa — da thuộc (革) kiểm soát miệng ngựa, như ky cương kiểm soát hành vi. | Gương Hán-Việt | Chữ 鞿 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鞿 giúp đọc hiểu từ vựng kị mã và dây cương trong văn bản lịch sử.", "Tự nguyên_Xie": "Chữ bộ 革, chỉ hàm thiếc (bit) trong bộ dây cương ngựa làm bằng da. Wiktionary ghi nhận định nghĩa là \"bit\" (bộ phận dây cương). Không có dữ liệu giáp cốt hay kim văn chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "qu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 幾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革幾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞿", "Unihan_Traditional (Chữ Phồn thể)": "鞿", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ky", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng để chỉ dây cương ngựa hoặc nghĩa bóng là sự kiềm chế, kiểm soát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韟', '{"9000": "8507.0", "Chữ Trung Quốc": "韟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 19 | nét | 韟 | cao | tượng hình | đồ da thuộc, âm gāo | 韟 là chữ bộ 韋 (Vi — da thuộc mềm), cực hiếm. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": 韟 bộ 韋 (da mềm) — chữ cực hiếm trong nhóm chữ liên quan đến da thuộc và đồ da. | Gương Hán-Việt | Chữ 韟 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 韟 giúp nhận diện ký tự hiếm trong bộ 韋 khi tra từ điển Unicode.", "Tự nguyên_Xie": "Chữ tạo muộn thuộc bộ 韋 (da thuộc mềm). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "韋 + 皋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韋皋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韋", "Unihan_Simplified (Chữ Giản thể)": "韟", "Unihan_Traditional (Chữ Phồn thể)": "韟", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ các loại túi hoặc bao được làm bằng chất liệu da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顀', '{"9000": "8508.0", "Chữ Trung Quốc": "顀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 17 | nét | 顀 | chuy | tượng hình | đầu/mặt người, âm chuí | 顀 là chữ bộ 頁 (Hiệt — đầu người) chỉ một bộ phận đầu/mặt. Wiktionary ghi nhận định nghĩa chưa rõ (rfdef). Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuy\": 顀 bộ 頁 (đầu người) — chữ hiếm liên quan đến đầu/mặt, đọc âm chuí như chùy (vật nặng). | Gương Hán-Việt | Gần với 錘 (chùy — vật nặng hình trụ) trong Hán-Việt, cùng âm chuí. | Mở khoá kiến thức | Biết 顀 giúp nhận diện ký tự hiếm bộ 頁 trong văn bản cổ.", "Tự nguyên_Xie": "Chữ bộ 頁, âm chuí. Wiktionary ghi rfdef (chưa có định nghĩa xác thực). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giới", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "隹 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰隹頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "頁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "顀", "Unihan_Traditional (Chữ Phồn thể)": "顀", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Diễn tả hành động cúi đầu hoặc gục đầu xuống do mệt mỏi hoặc xấu hổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飀', '{"9000": "8509.0", "Chữ Trung Quốc": "飀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 19 | nét | 飀 | lưu | tượng hình | tiếng gió vi vu, âm liú | 飀 là chữ bộ 風 (Phong — gió) chỉ tiếng gió vi vu. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": 飀 bộ 風 (gió) gợi tiếng gió vi vu — 飀飀 như âm thanh gió lướt qua khe núi. | Gương Hán-Việt | Chữ 飀 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 飀 giúp đọc hiểu từ tượng thanh tiếng gió trong thơ cổ điển Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 風, chỉ tiếng gió vi vu (soughing of wind). Wiktionary ghi nhận dùng trong tổ hợp 颼飀 (gió rít), 飀飀 (vi vu). Không có dữ liệu giáp cốt hay kim văn chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "飗", "Hạng Tần Suất (Jun Da)": "6826.0", "Tần Suất % (Jun Da)": "99.9960512448", "GavinGrover_Once (Chiết tự trực tiếp)": "風 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴風留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "風", "Unihan_Simplified (Chữ Giản thể)": "飗", "Unihan_Traditional (Chữ Phồn thể)": "飀", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ tiếng gió hoặc động từ mô tả tiếng gió thổi vi vu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飥', '{"9000": "8510.0", "Chữ Trung Quốc": "飥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 11 | nét | 飥 | thác | tượng hình | bánh bột, đồ ăn làm từ bột, âm tuō | 飥 là chữ bộ 食 (Thực — thức ăn) chỉ loại bánh làm từ bột (dough food). Wiktionary ghi nhận dùng trong tổ hợp 餺飥. Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thác\": 飥 bộ 食 (thức ăn) chỉ bánh bột cổ đại — 餺飥 là món mì lát dẹt được nhắc trong thư tịch Đường. | Gương Hán-Việt | Chữ 飥 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 飥 giúp đọc hiểu từ 餺飥 (mì bột lát dẹt cổ đại) trong văn bản ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 食, chỉ đồ ăn làm từ bột nhào (dough). Wiktionary ghi: {{lb|zh|obs-std}} food made of dough, dùng trong tổ hợp 餺飥 (bó tuō — một loại mì cổ đại). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ngon", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饦", "Unihan_Traditional (Chữ Phồn thể)": "飥", "Pinyin_Xie": "tuō", "Âm Hán Việt_Xie": "thác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại bánh mì hoặc mì sợi trong ẩm thực cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饆', '{"9000": "8511.0", "Chữ Trung Quốc": "饆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 18 | nét | 饆 | tất | tượng hình | cơm thập cẩm, món bát bửu, âm bì | 饆 là chữ bộ 食 (Thực) chỉ loại cơm thập cẩm (饆饠). Wiktionary ghi nhận chỉ dùng trong tổ hợp 饆饠. Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": 饆 bộ 食 chỉ có trong 饆饠 — loại cơm thập cẩm sang trọng thời cổ đại. | Gương Hán-Việt | Chữ 饆 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 饆 giúp nhận diện món ăn cổ đại 饆饠 trong văn bản lịch sử ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 食, chỉ loại cơm thập cẩm bát bửu (饆饠 — bìluó, một món ăn cổ đại). Wiktionary ghi: {{zh-only|饆饠}}. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cơm thập cẩm; cơm bát bửu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 畢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠畢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饆", "Unihan_Traditional (Chữ Phồn thể)": "饆", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong tên món ăn cổ như tất la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馿', '{"9000": "8512.0", "Chữ Trung Quốc": "馿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 馿 | lư | tượng hình | con lừa, âm lǘ | 馿 là chữ bộ 馬 (Mã — ngựa) chỉ con lừa. Là dạng viết khác của 驢 (lừa). Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\": 馿 bộ 馬 là con lừa — trong tiếng Việt \"lừa\" (lư) chính là từ Hán-Việt từ 驢/馿. | Gương Hán-Việt | \"Lừa\" trong tiếng Việt (con lừa) bắt nguồn từ Hán-Việt 驢 (lư), cùng nghĩa với 馿. | Mở khoá kiến thức | Biết 馿 giúp nhận diện dị thể của 驢 (lừa) và hiểu nguồn gốc từ \"lừa\" trong tiếng Việt.", "Tự nguyên_Xie": "Chữ bộ 馬, chỉ con lừa (donkey/ass). Là dị thể của 驢 (lư — con lừa). Bộ 馬 cho thấy đây là loài vật họ ngựa. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Mì", "Hạng Tần Suất (Jun Da)": "2538.0", "Tần Suất % (Jun Da)": "98.5584981496", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 户", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬户", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "户", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驴", "Unihan_Traditional (Chữ Phồn thể)": "馿", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài lừa, là dạng viết khác của chữ lư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癀', '{"9000": "8513.0", "Chữ Trung Quốc": "癀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 癀 | hoàng | tượng hình | bệnh nhiệt thán gia súc, âm huáng | 癀 là chữ bộ 疒 (Nạch — bệnh tật) chỉ bệnh nhiệt thán (anthrax) ở gia súc hoặc bệnh vàng da. Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": 癀 bộ 疒 (bệnh) — bệnh \"hoàng\" của gia súc làm da vàng úa, liên tưởng màu vàng (hoàng) của triệu chứng. | Gương Hán-Việt | \"Hoàng\" trong Hán-Việt liên quan đến màu vàng và bệnh vàng da (黃疸 — hoàng đản). | Mở khoá kiến thức | Biết 癀 giúp đọc hiểu văn bản y học cổ điển và thú y truyền thống về bệnh gia súc.", "Tự nguyên_Xie": "Chữ bộ 疒, chỉ bệnh nhiệt thán (anthrax) ở gia súc (trâu, bò, ngựa, lợn) — còn gọi là \"bệnh hoàng\" trong phương ngữ Hokkien. Wiktionary ghi nhận hai nghĩa: anthrax của gia súc và bệnh vàng da. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh nhiệt thán (của trâu, bò, ngựa, lợn...)", "Hạng Tần Suất (Jun Da)": "8513.0", "Tần Suất % (Jun Da)": "99.9996899289", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癀", "Unihan_Traditional (Chữ Phồn thể)": "癀", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các chứng bệnh vàng da hoặc dịch bệnh ở động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驦', '{"9000": "8514.0", "Chữ Trung Quốc": "驦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 27 | nét | 驦 | song | tượng hình | ngựa (văn chương), âm shuāng | 驦 là chữ bộ 馬 (Mã — ngựa) dùng trong văn chương cổ điển để chỉ ngựa. Thấy trong tổ hợp 驌驦. Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"song\": 驦 bộ 馬 — ngựa quý trong thơ ca cổ đại, 驌驦 là danh từ riêng cho giống ngựa tốt. | Gương Hán-Việt | Chữ 驦 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 驦 giúp đọc hiểu tổ hợp 驌驦 trong thơ ca cổ điển về ngựa quý.", "Tự nguyên_Xie": "Chữ bộ 馬, dùng trong văn học cổ điển. Wiktionary ghi: {{lb|zh|literary}} horse. Xuất hiện trong tổ hợp 驌驦 (sùshuāng — ngựa quý thời cổ đại). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "馦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 霜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬霜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "骦", "Unihan_Traditional (Chữ Phồn thể)": "驦", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "song", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giống ngựa tốt thời xưa, thường dùng trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髉', '{"9000": "8515.0", "Chữ Trung Quốc": "髉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 19 | nét | 髉 | bác | tượng hình | xương, âm bō/xiāo | 髉 là chữ bộ 骨 (Cốt — xương) chỉ một bộ phận xương hoặc thịt. Wiktionary ghi nhận định nghĩa chưa rõ (rfdef). Không có phân tích xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bác\": 髉 bộ 骨 (xương) — chữ hiếm chỉ bộ phận xương/thịt, định nghĩa cụ thể chưa được xác nhận. | Gương Hán-Việt | Chữ 髉 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 髉 giúp nhận diện ký tự hiếm bộ 骨 trong văn bản cổ hoặc y học truyền thống.", "Tự nguyên_Xie": "Chữ bộ 骨, âm bō hoặc xiāo. Wiktionary ghi rfdef (chưa có định nghĩa xác thực). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 隺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨隺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髉", "Unihan_Traditional (Chữ Phồn thể)": "髉", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương bả vai của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬉', '{"9000": "8516.0", "Chữ Trung Quốc": "鬉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 19 | nét | 鬉 | tông | tượng hình | bờm, lông dài, âm zōng | 鬉 là chữ bộ 髟 (Phiêu — tóc dài) chỉ bờm hoặc lông dài. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": 鬉 bộ 髟 (tóc dài) — bờm tóc rợn người như 鬃 (tông — bờm ngựa) cùng âm. | Gương Hán-Việt | Gần với 鬃 (tông — bờm ngựa/lợn) trong Hán-Việt, cùng âm zōng. | Mở khoá kiến thức | Biết 鬉 giúp nhận diện biến thể chữ chỉ bờm/lông dài trong văn bản cổ.", "Tự nguyên_Xie": "Chữ bộ 髟, chỉ bờm hoặc tóc dài. Wiktionary chỉ ghi {{Han etym}} không có phân tích cụ thể. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉉", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鬉", "Unihan_Traditional (Chữ Phồn thể)": "鬉", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần bờm của ngựa hoặc bờm tóc của động vật nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬸', '{"9000": "8517.0", "Chữ Trung Quốc": "鬸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬲 | Số nét | 20 | nét | 鬸 | lục | tượng hình | vợ lẽ, âm liù | 鬸 là chữ bộ 鬲 (Cách — nồi ba chân cổ đại) nghĩa là vợ lẽ (concubine). Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": 鬸 bộ 鬲 (nồi cổ) nghĩa là vợ lẽ — chữ cực hiếm, gần như chỉ gặp trong từ điển. | Gương Hán-Việt | Chữ 鬸 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鬸 giúp nhận diện từ cổ chỉ vợ lẽ trong văn bản lịch sử Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 鬲, nghĩa là vợ lẽ (concubine). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vợ lẽ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鬲 + 留", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鬲留", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬲", "Unihan_Simplified (Chữ Giản thể)": "鬸", "Unihan_Traditional (Chữ Phồn thể)": "鬸", "Pinyin_Xie": "liù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ người vợ lẽ hoặc tính từ miêu tả vẻ đẹp của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魛', '{"9000": "8518.0", "Chữ Trung Quốc": "魛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 13 | nét | 魛 | đao | tượng hình | cá cơm/cá dao, âm dāo | 魛 là chữ bộ 魚 (Ngư — cá) chỉ loài cá nhỏ (cá cơm/cá dao). Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đao\": 魛 bộ 魚 (cá) + âm đao (dao) — cá cơm mỏng như lưỡi dao. | Gương Hán-Việt | Chữ 魛 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 魛 giúp nhận diện loài cá cơm trong văn bản ngư nghiệp cổ điển.", "Tự nguyên_Xie": "Chữ bộ 魚, chỉ loài cá nhỏ (anchovy). Wiktionary ghi nhận: {{lb|zh|obs-std}} anchovy. Âm dāo gợi hình con cá mỏng như lưỡi dao. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "7997.0", "Tần Suất % (Jun Da)": "99.9993317968", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 刀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚刀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱽", "Unihan_Traditional (Chữ Phồn thể)": "魛", "Pinyin_Xie": "dāo", "Âm Hán Việt_Xie": "đao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài cá có thân hình dài dẹt giống hình con dao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳷', '{"9000": "8519.0", "Chữ Trung Quốc": "鳷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鳷 | chi | tượng hình | chim anh vũ/quạ, âm zhī | 鳷 là chữ bộ 鳥 (Điểu — chim) chỉ loài chim jay (Garrulus lidthi). Wiktionary ghi nhận dùng trong 鳷鵲 và là chữ cũ của 翅. Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chi\": 鳷 bộ 鳥 — chim jay, tên chim đọc âm zhī như \"chí\" (chí hướng), chim lanh lợi. | Gương Hán-Việt | Chữ 鳷 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鳷 giúp nhận diện tên chim jay trong văn bản điểu học cổ điển Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 鳥, chỉ loài chim jay (Garrulus lidthi) hoặc dùng trong 鳷鵲. Wiktionary ghi nhận 鳷 cũng là dạng cũ của 翅 (cánh). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Garrulus lidthi; thuật ngữ chung cho jay", "Hạng Tần Suất (Jun Da)": "8519.0", "Tần Suất % (Jun Da)": "99.9996930296", "GavinGrover_Once (Chiết tự trực tiếp)": "支 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰支鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "支", "Unihan_Simplified (Chữ Giản thể)": "鳷", "Unihan_Traditional (Chữ Phồn thể)": "鳷", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim thuộc họ quạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵋', '{"9000": "8520.0", "Chữ Trung Quốc": "鵋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 忌 | kỵ | biểu âm | cho âm jì | 鳥 | điểu | biểu nghĩa | chim | 鵋 = 忌 (Kỵ, biểu âm: cho âm jì) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh. Chỉ loài chim cú mèo (owl), dùng trong tổ hợp 鵋䳢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỵ\": 鵋 = chim (鳥) + kỵ (忌 — điều kiêng kỵ) — cú mèo là con chim bị \"kỵ\" trong dân gian, âm thanh ghê rợn. | Gương Hán-Việt | \"Kỵ\" trong Hán-Việt liên quan đến điều kiêng cữ (忌讳 — kỵ húy), cú mèo là loài bị kiêng kỵ trong văn hóa. | Mở khoá kiến thức | Biết 鵋 giúp nhận diện tên cú mèo cổ trong văn bản điểu học và thơ ca có hình ảnh điềm dữ.", "Tự nguyên_Xie": "Chữ hình thanh: 鳥 chỉ nghĩa (chim), 忌 cho âm jì. Wiktionary ghi: {{Han compound|忌|鳥|ls=psc|c1=p|c2=s|t2=bird}}. 鵋 xuất hiện trong tổ hợp 鵋䳢 chỉ loài cú mèo — chim bị xem là điềm gở trong văn hóa cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "忌 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忌鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵋", "Unihan_Traditional (Chữ Phồn thể)": "鵋", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kỵ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loài chim giống như chim cú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵏', '{"9000": "8521.0", "Chữ Trung Quốc": "鵏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鵏 | bộc | tượng hình | chim ô-tit (bustard), âm bǔ | 鵏 là chữ bộ 鳥 (Điểu — chim) chỉ loài chim ô-tit (bustard). Không có phân tích hình thanh hay hội ý xác thực trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": 鵏 bộ 鳥 — chim ô-tit to lớn đi trên mặt đất, âm bǔ gợi tiếng bước chân nặng. | Gương Hán-Việt | Chữ 鵏 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鵏 giúp nhận diện tên chim ô-tit trong văn bản điểu học cổ điển.", "Tự nguyên_Xie": "Chữ bộ 鳥, chỉ loài chim ô-tit (bustard). Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim ô-tit", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "甫 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甫鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵏", "Unihan_Traditional (Chữ Phồn thể)": "鵏", "Pinyin_Xie": "bǔ", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim ô tít hoặc chim trĩ nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵨', '{"9000": "8522.0", "Chữ Trung Quốc": "鵨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鵨 | thư | tượng hình | chim giống vịt trời, âm shū | 鵨 là chữ bộ 鳥 (Điểu — chim) chỉ loài chim giống vịt trời. Wiktionary ghi nhận là dạng cổ (obs-std). Không có phân tích hình thanh xác thực.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": 鵨 bộ 鳥 — chim giống vịt trời, âm shū như \"thư\" (thư thái), bay nhẹ nhàng trên mặt nước. | Gương Hán-Việt | Chữ 鵨 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鵨 giúp nhận diện loài chim nước cổ trong văn bản điểu học Trung Hoa.", "Tự nguyên_Xie": "Chữ bộ 鳥, chỉ loài chim giống vịt trời. Wiktionary ghi: {{lb|zh|obs-std}} a bird similar to a wild duck. Không có dữ liệu giáp cốt hay kim văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舍 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舍鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵨", "Unihan_Traditional (Chữ Phồn thể)": "鵨", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim hoang dã thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵼', '{"9000": "8523.0", "Chữ Trung Quốc": "鵼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鵼 | không | tượng hình | loài chim quái dị trong truyền thuyết | 鵼 là chữ độc thể, chưa có phân tích thành phần rõ ràng trong nguồn học thuật. Chữ thuộc bộ 鳥 (điểu), biểu thị đây là tên một loài chim trong văn học cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"không\": chim huyền thoại mang âm 空 (không, trống rỗng) — một sinh vật chỉ tồn tại trong khoảng không của truyền thuyết. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鵼 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鵼 mở khoá tên các sinh vật thần thoại trong điển cố cổ văn Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn glyph origin từ Wiktionary cho 鵼. Theo bộ thủ 鳥 (điểu, chim) và âm đọc kōng, đây là tên một loài chim quái dị hoặc sinh vật thần thoại trong văn cổ Trung Hoa. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鵼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "空 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰空鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "空", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵼", "Unihan_Traditional (Chữ Phồn thể)": "鵼", "Pinyin_Xie": "kōng", "Âm Hán Việt_Xie": "không", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim truyền thuyết trong văn hóa Á Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷵', '{"9000": "8524.0", "Chữ Trung Quốc": "鷵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 鷵 | đồ | tượng hình | loài chim trong văn cổ, xuất hiện trong tổ hợp 鶶鷵 | 鷵 là chữ độc thể, không có phân tích thành phần trong nguồn học thuật. Thuộc bộ 鳥 (điểu), chỉ dùng trong tổ hợp 鶶鷵 — tên một loài chim cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồ\": chim cổ mang âm 途 (đồ, con đường) — một loài chim chỉ còn \"đi\" trên con đường của văn tự cổ. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鷵 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鷵 giúp nhận diện tên chim hiếm trong cổ văn Trung Hoa.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鷵. Chữ chỉ xuất hiện trong tổ hợp 鶶鷵, là tên một loài chim trong văn cổ. Âm đọc tú (tou4 Quảng Đông). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鷵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "屠 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰屠鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷵", "Unihan_Traditional (Chữ Phồn thể)": "鷵", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim săn mồi nhỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷼', '{"9000": "8525.0", "Chữ Trung Quốc": "鷼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 23 | nét | 鷼 | hàm | tượng hình | chim ưng, chim săn mồi | 鷼 là chữ độc thể, chưa có phân tích thành phần được xác nhận. Thuộc bộ 鳥 (điểu), chỉ một loài chim ưng hay chim săn mồi trong văn cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": chim ưng 鷼 — hình dung loài chim mang \"hàm răng\" sắc bén trên mỏ khi săn mồi. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鷼 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鷼 giúp nhận diện tên chim ưng hiếm trong điển cố cổ văn.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鷼. Căn cứ vào bộ 鳥 (điểu) và nghĩa \"falcon\" (chim ưng), đây là tên loài chim săn mồi trong văn cổ. Âm đọc xián. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chim ưng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "間 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰間鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "間", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷼", "Unihan_Traditional (Chữ Phồn thể)": "鷼", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim trĩ bạc hoặc chim kiểng cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸍', '{"9000": "8526.0", "Chữ Trung Quốc": "鸍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 25 | nét | 鸍 | mị | tượng hình | vịt trời, vịt hoang | 鸍 là chữ độc thể, không có phân tích thành phần rõ ràng. Thuộc bộ 鳥 (điểu), chỉ loài vịt trời hoặc vịt hoang trong văn cổ. Chỉ dùng trong tổ hợp 鴆鸍.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": vịt nước 鸍 — âm mị gợi tiếng vịt lội nước êm ái, bí ẩn như bóng tối (mị hoặc mê). | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鸍 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鸍 giúp đọc tên các loài chim nước hiếm trong cổ tịch Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鸍 dùng trong tổ hợp 鴆鸍 và có nghĩa là vịt trời (wild duck) trong văn cổ. Không có thông tin cấu tạo hình thanh hay hội ý. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "爾 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰爾鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸍", "Unihan_Traditional (Chữ Phồn thể)": "鸍", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim nước giống vịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸓', '{"9000": "8527.0", "Chữ Trung Quốc": "鸓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 26 | nét | 畾 | lỗi | biểu âm | 鳥 | điểu | biểu nghĩa | chim | 鸓 = 畾 (Lỗi, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Phần 鳥 cho biết đây là loài chim (hoặc động vật có cánh), phần 畾 cung cấp âm đọc lěi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": sóc bay 鸓 — con vật có cánh da như chim (鳥) nhưng thực ra là thú, mang âm lỗi như sấm 雷 (lôi/lỗi) ầm ầm khi lao xuống. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鸓 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鸓 mở khoá nhóm tên động vật bay lượn hiếm trong cổ văn Trung Hoa.", "Tự nguyên_Xie": "Wiktionary xác nhận: 鸓 là chữ hình thanh, gồm 畾 (biểu âm) + 鳥 (biểu nghĩa: chim). Chỉ loài sóc bay (flying squirrel). Tên gọi xuất phát từ âm tương đồng với 畾 (lỗi), bộ phận 鳥 phản ánh hình dáng bay lượn như chim. Chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sóc bay", "Hạng Tần Suất (Jun Da)": "8527.0", "Tần Suất % (Jun Da)": "99.9996971639", "GavinGrover_Once (Chiết tự trực tiếp)": "畾 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰畾鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸓", "Unihan_Traditional (Chữ Phồn thể)": "鸓", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài sóc bay hoặc chim thần thoại có hai đầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸖', '{"9000": "8528.0", "Chữ Trung Quốc": "鸖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 27 | nét | 鸖 | hạc | tượng hình | chim hạc — dạng cổ của 鶴 | 鸖 là dạng cổ (cổ tự) của 鶴 (hạc), là chữ độc thể. Không có phân tích thành phần được xác nhận trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạc\": 鸖 là dạng cổ của 鶴 — chim hạc trắng tượng trưng cho sự thanh cao, thường đứng một chân trong yên bình. | Gương Hán-Việt | Hạc trong \"hạc lập kê quần\" (hạc đứng giữa bầy gà) — ý chỉ người xuất chúng giữa đám tầm thường. | Mở khoá kiến thức | Biết 鸖 (dạng cổ của 鶴) giúp đọc văn tự cổ và khắc bản in thời Tống-Minh.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鸖. Đây là dạng cổ của 鶴 (chim hạc). Nghĩa: chim hạc trắng, biểu tượng cho sự thanh cao và trường thọ trong văn hoá Đông Á. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 鶴", "Hạng Tần Suất (Jun Da)": "8528.0", "Tần Suất % (Jun Da)": "99.9996976807", "GavinGrover_Once (Chiết tự trực tiếp)": "霍 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰霍鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鸖", "Unihan_Traditional (Chữ Phồn thể)": "鸖", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim hạc, là biến thể chữ cổ của chữ hạc thông thường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹠', '{"9000": "8529.0", "Chữ Trung Quốc": "鹠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鹠 | lưu | tượng hình | con cú — dùng trong tổ hợp 鵂鶹 (cú mèo) | 鹠 là chữ độc thể, chỉ dùng trong tổ hợp 鵂鶹 (hoặc 鸺鹠) chỉ loài cú mèo nhỏ. Thuộc bộ 鳥 (điểu). Không có phân tích thành phần xác nhận trong nguồn Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": cú mèo 鹠 — âm lưu gợi tiếng kêu trầm kéo dài của cú trong đêm tối, như dòng chảy (流 lưu) âm thanh không dứt. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鹠 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 鹠 giúp đọc tên chim đêm trong cổ tịch và thơ văn Đường Tống.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 鹠 (dạng phồn thể 鶹) là rút gọn từ 鵂鶹 (cú mèo nhỏ). Chỉ dùng trong tổ hợp này hoặc 鶹鷅. Có hình tiểu triện từ nguồn hanziyuan. Chưa có phân tích hình thanh/hội ý được xác nhận. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hưu lưu 鵂鶹,鸺鹠)", "Hạng Tần Suất (Jun Da)": "8529.0", "Tần Suất % (Jun Da)": "99.9996981975", "GavinGrover_Once (Chiết tự trực tiếp)": "留 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰留鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "留", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹠", "Unihan_Traditional (Chữ Phồn thể)": "鶹", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép để chỉ loài cú mèo nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黶', '{"9000": "8530.0", "Chữ Trung Quốc": "黶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 26 | nét | 厭 | ướm | biểu âm | 黑 | hắc | biểu nghĩa | đen | 黶 = 厭 (Ướm, biểu âm) + 黑 (Hắc, biểu nghĩa: đen, tối); chữ hình thanh. Phần 黑 cho biết nghĩa liên quan đến màu đen, phần 厭 cung cấp âm đọc yǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểm\": nốt ruồi đen 黶 — bộ 黑 (hắc) + âm 厭 (ướm/yếm) — nốt ruồi đen như dấu ấn (yểm) tối trên da. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 黶 trong tiếng Việt hiện đại; 黶翳 = che khuất. | Mở khoá kiến thức | Biết 黶 mở khoá nhóm từ chỉ vết đen trên da và khái niệm tối/che khuất trong văn ngữ cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận: 黶 là chữ hình thanh, gồm 厭 (biểu âm) + 黑 (biểu nghĩa: đen). Chỉ nốt ruồi hoặc vết sẹo đen trên da. Dùng trong văn ngữ. Xuất hiện trong các tổ hợp như 黶子 (nốt ruồi), 黶翳 (che khuất như vết đen). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đen", "Hạng Tần Suất (Jun Da)": "7806.0", "Tần Suất % (Jun Da)": "99.9990248265", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 黑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴黑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黡", "Unihan_Traditional (Chữ Phồn thể)": "黶", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ nốt ruồi đen hoặc làm tính từ chỉ sắc đen tối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齰', '{"9000": "8531.0", "Chữ Trung Quốc": "齰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 23 | nét | 齰 | trác | tượng hình | cắn, nghiến răng | 齰 là chữ độc thể thuộc bộ 齒 (xỉ, răng), không có phân tích thành phần được xác nhận trong nguồn Wiktionary. Bộ 齒 cho biết nghĩa liên quan đến răng hoặc hành động của răng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": cắn răng 齰 — bộ 齒 (xỉ, răng) gợi hình ảnh răng nghiến chặt (trác = gõ, đục — như răng đục vào thứ gì đó). | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 齰 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 齰 giúp đọc thành ngữ y học cổ tả hành động nghiến hoặc cắn lưỡi.", "Tự nguyên_Xie": "Wiktionary không cung cấp glyph origin rõ ràng cho 齰. Bộ 齒 (xỉ, răng) gợi ý nghĩa là hành động cắn hoặc nghiến răng. Âm đọc zé. Chỉ dùng trong tổ hợp 齰舌 (cắn lưỡi). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn", "Hạng Tần Suất (Jun Da)": "8531.0", "Tần Suất % (Jun Da)": "99.9996997478", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齰", "Unihan_Traditional (Chữ Phồn thể)": "齰", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động dùng răng cắn chặt vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碀', '{"9000": "8532.0", "Chữ Trung Quốc": "碀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 碀 | thừa | tượng hình | ghê tởm, đáng sợ; thuộc bộ thạch | 碀 là chữ độc thể, không có phân tích thành phần được xác nhận trong nguồn học thuật. Thuộc bộ 石 (thạch, đá), gợi ý liên quan đến đặc tính của đá hoặc vật chất cứng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thừa\": 碀 thuộc bộ 石 (thạch) — tảng đá ghê tởm, nặng nề như gánh nặng thừa (thừa = dư thừa, chồng chất). | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 碀 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 碀 giúp nhận diện một số chữ hiếm thuộc bộ 石 trong văn bản cổ.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 碀. Căn cứ vào bộ 石 (thạch) và âm đọc chéng, đây có thể là tên một loại đá hoặc tính trạng liên quan đến đá. Nghĩa ghi nhận: ghê tởm, đáng sợ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghê tởm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碀", "Unihan_Traditional (Chữ Phồn thể)": "碀", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thừa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ miêu tả trạng thái cảm xúc tiêu cực đối với sự vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礇', '{"9000": "8533.0", "Chữ Trung Quốc": "礇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 礇 | vụ | tượng hình | thuộc bộ thạch; nghĩa chưa rõ | 礇 là chữ độc thể, thuộc bộ 石 (thạch, đá). Không có phân tích thành phần hay glyph origin được xác nhận trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vụ\": 礇 thuộc bộ 石 (thạch) — tảng đá liên quan đến vụ việc (vụ) hay công việc nặng nhọc gắn với đá. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 礇 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 礇 giúp nhận diện chữ hiếm bộ 石 trong từ điển chữ Hán cổ.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 礇. Thuộc bộ 石 (thạch) và âm đọc yù. Nghĩa chưa được xác định rõ ràng trong nguồn tham khảo hiện có. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 奥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石奥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礇", "Unihan_Traditional (Chữ Phồn thể)": "礇", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "vụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại đá có đặc tính cứng rắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筣', '{"9000": "8534.0", "Chữ Trung Quốc": "筣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 筣 | ly | tượng hình | hàng rào tre — dạng cổ của 籬 | 筣 là dạng cổ hoặc dị thể của 籬 (hàng rào tre), thuộc bộ 竹 (trúc). Không có phân tích thành phần xác nhận trong Wiktionary ngoài việc đây là dị thể của 籬.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": hàng rào tre 筣 — bộ 竹 (trúc) gợi hàng tre (ly) bao quanh nhà, giống như từ \"ly\" trong \"cách ly\" hay \"ly cách\" phân chia không gian. | Gương Hán-Việt | Ly trong \"ly giậu\" (hàng rào phân cách), \"ly cách\" (ngăn cách). | Mở khoá kiến thức | Biết 筣 giúp đọc văn cổ tả kiến trúc làng quê với hàng rào tre và phân biệt với 籬 (dạng thông dụng hơn).", "Tự nguyên_Xie": "Wiktionary xác nhận 筣 là dạng cổ của 籬 (bamboo fence — hàng rào tre). Thuộc bộ 竹 (trúc). Cũng dùng trong tổ hợp 笓筣 / 筣笓. Không có glyph origin riêng biệt. Chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "筣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 利", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮利", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筣", "Unihan_Traditional (Chữ Phồn thể)": "筣", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "ly", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ vật dụng đan bằng tre dùng trong đánh bắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綀', '{"9000": "8535.0", "Chữ Trung Quốc": "綀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 糹 | mịch | biểu nghĩa | sợi tơ, vải | 疎 | sơ | biểu âm | 綀 = 糹 (Mịch rút gọn, biểu nghĩa: tơ/vải) + 疎 (Sơ, biểu âm, viết tắt); chữ hình thanh. Phần 糹 cho biết đây là loại vải hoặc sợi dệt, phần 疎 cung cấp âm đọc shū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sơ\": vải thô 綀 = 糹 (mịch, tơ) + 疎 (sơ, thô ráp) — vải (mịch) được dệt thô sơ (sơ), không tinh tế như lụa. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 綀 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 綀 giúp đọc các văn bản cổ về vải dệt và trang phục lễ tang hoặc đời thường trong Trung Hoa cổ đại.", "Tự nguyên_Xie": "Wiktionary xác nhận: 綀 là chữ hình thanh, gồm 糸 (viết tắt 糹, biểu nghĩa: tơ/vải) + 疎 (biểu âm, viết tắt). Nghĩa: một loại vải thô (sackcloth). Chỉ dùng trong tổ hợp 綀囊. Chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𦈌", "Unihan_Traditional (Chữ Phồn thể)": "綀", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "sơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại vải dệt thô sơ trong đời sống cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缾', '{"9000": "8536.0", "Chữ Trung Quốc": "缾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 12 | nét | 缾 | bình | tượng hình | bình, chai — bộ 缶 (phẫu, đồ gốm) | 缾 là chữ thuộc bộ 缶 (phẫu, đồ gốm/vật chứa). Không có phân tích thành phần xác nhận trong nguồn Wiktionary. Có hình kim văn, tiểu triện và lục thư thông — cho thấy chữ có lịch sử lâu đời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": cái bình 缾 = bộ 缶 (phẫu, đồ gốm) — chiếc bình gốm tròn, bình (bình an, bình yên) như chiếc bình không lay chuyển. | Gương Hán-Việt | Bình trong \"bình hoa\" (lọ hoa), \"bình rượu\" — cùng nghĩa với 瓶 (dạng thông dụng hiện đại). | Mở khoá kiến thức | Biết 缾 giúp đọc văn cổ và văn bia dùng dạng cổ thay vì 瓶 — mở khoá chữ Hán trên đồ gốm cổ đại.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Không có glyph origin cấu tạo từ Wiktionary cho 缾. Căn cứ bộ 缶 (phẫu, đồ gốm) và nghĩa \"bình, chai\", đây là chữ chỉ vật chứa bằng đất nung. Có hình kim văn (kim văn), tiểu triện và lục thư thông từ nguồn hanziyuan. Đây là dạng cổ của 瓶 (bình, chai). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chai", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "缶 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰缶并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "缶", "Unihan_Simplified (Chữ Giản thể)": "缾", "Unihan_Traditional (Chữ Phồn thể)": "缾", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ vật dụng chứa đựng chất lỏng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羷', '{"9000": "8537.0", "Chữ Trung Quốc": "羷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 19 | nét | 羷 | liễm | tượng hình | dê có ba xoắn ở sừng | 羷 là chữ độc thể, thuộc bộ 羊 (dương, dê). Không có phân tích thành phần xác nhận trong nguồn học thuật. Chỉ một loại dê đặc biệt có sừng xoắn trong văn cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễm\": dê xoắn sừng 羷 — bộ 羊 (dương) + âm liễm gợi \"liệm\" (thu lại, cuộn) — con dê có sừng cuộn lại ba vòng như thu liễm vào trong. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 羷 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 羷 giúp đọc các văn bản cổ tả động vật đặc biệt trong mục súc học cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi nhận 羷 chỉ con dê có ba xoắn ở sừng (goat with three curls in its horns), dùng trong văn ngữ cổ. Thuộc bộ 羊 (dương). Không có glyph origin hay cấu tạo hình thanh/hội ý được xác nhận. Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "羷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 僉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶僉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "僉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羷", "Unihan_Traditional (Chữ Phồn thể)": "羷", "Pinyin_Xie": "liǎn", "Âm Hán Việt_Xie": "liễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ mùi đặc trưng của loài dê hoặc các loài thú tương tự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耊', '{"9000": "8538.0", "Chữ Trung Quốc": "耊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 10 | nét | 耊 | điệt | tượng hình | người cao tuổi — thuộc bộ 老 | 耊 là chữ độc thể thuộc bộ 老 (lão, người già). Không có phân tích thành phần xác nhận trong nguồn học thuật. Cùng nhóm với 耄 (mão), 耋 (điệt) — các chữ chỉ người cao tuổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": người già 耊 — bộ 老 (lão) gợi hình ảnh cụ già run rẩy, âm điệt gần với \"điệt đà\" (chậm chạp, lập bập tuổi già). | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 耊 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 耊 giúp nhận ra nhóm chữ chỉ tuổi tác trong văn ngôn: 耄耋 (mão điệt) = người rất cao tuổi.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 耊. Thuộc bộ 老 (lão). Cùng nhóm với các chữ 耄 (70-80 tuổi), 耋 (70-80 tuổi) — đều chỉ người cao tuổi trong văn ngôn. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "芊", "Hạng Tần Suất (Jun Da)": "8538.0", "Tần Suất % (Jun Da)": "99.999706466", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "耊", "Unihan_Traditional (Chữ Phồn thể)": "耊", "Pinyin_Xie": "diè", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng như danh từ chỉ người cao tuổi trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艍', '{"9000": "8539.0", "Chữ Trung Quốc": "艍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 14 | nét | 艍 | cư | tượng hình | thuyền nhỏ — thuộc bộ 舟 | 艍 là chữ độc thể thuộc bộ 舟 (chu, thuyền). Không có phân tích thành phần xác nhận trong nguồn học thuật. Chỉ loại thuyền nhỏ trong văn cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cư\": thuyền nhỏ 艍 — bộ 舟 (chu, thuyền) + âm cư như \"cư ngụ\" — con thuyền nơi người ta cư ngụ lênh đênh trên sông. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 艍 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 艍 giúp đọc văn cổ tả thuyền bè và giao thông đường thuỷ trong lịch sử Trung Hoa.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 艍. Thuộc bộ 舟 (chu, thuyền) và âm đọc jū. Chỉ một loại thuyền nhỏ trong văn cổ. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "艍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艍", "Unihan_Traditional (Chữ Phồn thể)": "艍", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại phương tiện di chuyển trên mặt nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葏', '{"9000": "8540.0", "Chữ Trung Quốc": "葏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葏 | căng | tượng hình | cây cỏ chưa xác định — thuộc bộ 艸 | 葏 là chữ độc thể thuộc bộ 艸 (thảo, cỏ/cây). Không có phân tích thành phần hay glyph origin xác nhận trong nguồn học thuật. Âm đọc jiān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"căng\": cây cỏ 葏 — bộ 艸 (thảo) gợi loài thực vật, âm căng như \"căng thẳng\" — một loại cỏ mọc cứng căng. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 葏 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 葏 giúp nhận diện chữ hiếm thuộc bộ 艸 trong từ điển thực vật học cổ đại.", "Tự nguyên_Xie": "Wiktionary không cung cấp định nghĩa rõ ràng hay glyph origin cho 葏. Thuộc bộ 艸 (thảo) và âm đọc jiān. Nghĩa chưa xác định rõ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葏", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 津", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹津", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "津", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葏", "Unihan_Traditional (Chữ Phồn thể)": "葏", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "căng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tên gọi của một loài thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('誽', '{"9000": "8541.0", "Chữ Trung Quốc": "誽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 誽 | nghệ | tượng hình | nịnh hót, a dua — thuộc bộ 言 | 誽 là chữ thuộc bộ 言 (ngôn, lời nói). Không có phân tích thành phần xác nhận. Nghĩa: a dua, nịnh hót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": nịnh hót 誽 — bộ 言 (ngôn, lời) gợi miệng nói lời khéo léo, âm nghệ như \"nghệ thuật\" nịnh — lời hoa mỹ đầy nghệ thuật để a dua. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 誽 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 誽 giúp đọc văn cổ tả hành vi nịnh nọt, a dua trong xã hội phong kiến.", "Tự nguyên_Xie": "Wiktionary không cung cấp glyph origin cấu tạo cho 誽. Thuộc bộ 言 (ngôn, lời nói) và âm đọc nì. Nghĩa ghi nhận: dua nịnh (theo từ điển phương ngữ). Chưa có nguồn học thuật xác nhận chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dua; như \"a dua; dua nịnh\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "誽", "Unihan_Traditional (Chữ Phồn thể)": "誽", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ thái độ nói năng không trung thực để lấy lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輧', '{"9000": "8542.0", "Chữ Trung Quốc": "輧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 輧 | bình | tượng hình | xe có màn che dùng cho phụ nữ quý tộc | 輧 là chữ độc thể thuộc bộ 車 (xa, xe). Không có phân tích thành phần xác nhận trong nguồn học thuật. Chỉ loại xe có màn che dùng cho phụ nữ quý tộc trong thời cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bình\": xe màn 輧 — bộ 車 (xa, xe) + âm bình — chiếc xe kín bình yên (bình) cho phụ nữ quý tộc di chuyển che kín. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 輧 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 輧 giúp đọc văn cổ tả phương tiện đi lại của phụ nữ quý tộc và hầu phi trong xã hội phong kiến.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 輧. Thuộc bộ 車 (xa, xe) và âm đọc píng. Nghĩa: xe có màn che dùng cho phụ nữ quý tộc. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "輧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 幷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車幷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輧", "Unihan_Traditional (Chữ Phồn thể)": "輧", "Pinyin_Xie": "píng", "Âm Hán Việt_Xie": "bình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại xe ngựa có mái che thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輽', '{"9000": "8543.0", "Chữ Trung Quốc": "輽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 17 | nét | 輽 | bôn | tượng hình | xe — thuộc bộ 車 | 輽 là chữ độc thể thuộc bộ 車 (xa, xe). Không có phân tích thành phần xác nhận trong nguồn học thuật. Chỉ một loại xe trong văn cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bôn\": xe chạy 輽 — bộ 車 (xa, xe) + âm bôn gợi \"bôn ba\" (chạy rong) — chiếc xe chạy bôn ba trên đường. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 輽 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 輽 giúp nhận diện chữ hiếm bộ 車 trong từ điển chữ Hán cổ đại.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 輽. Thuộc bộ 車 (xa, xe) và âm đọc bèn. Nghĩa: xe (loại không xác định rõ trong văn cổ). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "载", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 畚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車畚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輽", "Unihan_Traditional (Chữ Phồn thể)": "輽", "Pinyin_Xie": "bèn", "Âm Hán Việt_Xie": "bôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng để diễn tả hành động vận chuyển hoặc mang vác vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏍', '{"9000": "8544.0", "Chữ Trung Quốc": "鏍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 19 | nét | 鏍 | la | tượng hình | ốc vít, đinh ốc — bộ 金 | 鏍 là chữ thuộc bộ 金 (kim, kim loại). Không có phân tích thành phần xác nhận trong nguồn học thuật. Tương đương 镙 (giản thể). Chỉ ốc vít hoặc đinh ốc bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": ốc vít 鏍 — bộ 金 (kim, kim loại) + âm la gợi vật xoắn như ốc (la = xoáy tròn, xoắn ốc). | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 鏍 trong tiếng Việt hiện đại; tương đương 螺絲 (ốc vít). | Mở khoá kiến thức | Biết 鏍 giúp đọc từ điển kỹ thuật và thủ công nghiệp cổ đại tả dụng cụ kim loại.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 鏍. Thuộc bộ 金 (kim, kim loại) và âm đọc luó. Là dạng phồn thể của 镙, chỉ ốc vít (screw), đinh ốc. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "镙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏍", "Unihan_Traditional (Chữ Phồn thể)": "鏍", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ các vật dụng có hình dạng xoắn ốc hoặc ốc vít kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏽', '{"9000": "8545.0", "Chữ Trung Quốc": "鏽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 金 | kim | biểu nghĩa | kim loại | 肅 | túc | biểu âm | 鏽 = 金 (Kim, biểu nghĩa: kim loại) + 肅 (Túc, biểu âm); chữ hình thanh. Phần 金 cho biết nghĩa liên quan đến kim loại, phần 肅 cung cấp âm đọc xiù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tú\": gỉ sét 鏽 = 金 (kim, kim loại) + 肅 (túc, nghiêm ngặt) — kim loại bị \"túc\" (thu lại, teo tóp) dưới tác động của gỉ sét — phản ứng oxy hóa \"nghiêm nghị\" không thể tránh. | Gương Hán-Việt | Tú trong \"gỉ tú\" hay từ Hán-Việt \"tú\" trong thêu thùa — nhưng 鏽 là nghĩa kim loại gỉ, không phải thêu. | Mở khoá kiến thức | Biết 鏽 mở khoá từ vựng khoa học vật liệu: 生鏽 (gỉ sét), 防鏽 (chống gỉ), 不鏽鋼 (thép không gỉ).", "Tự nguyên_Xie": "Wiktionary xác nhận: 鏽 là chữ hình thanh, gồm 金 (biểu nghĩa: kim loại) + 肅 (biểu âm). Nghĩa: gỉ sét, ăn mòn kim loại. Chưa có nguồn học thuật xác nhận thêm chi tiết. Dạng giản thể là 锈. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỉ (kim loại)", "Hạng Tần Suất (Jun Da)": "8545.0", "Tần Suất % (Jun Da)": "99.999713701", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 肅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金肅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏽", "Unihan_Traditional (Chữ Phồn thể)": "鏽", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng để chỉ lớp gỉ trên bề mặt kim loại hoặc trạng thái bị gỉ sét. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饝', '{"9000": "8546.0", "Chữ Trung Quốc": "饝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 24 | nét | 饝 | mạc | tượng hình | bánh bao — bộ 食 | 饝 là chữ thuộc bộ 食 (thực, ăn uống). Không có phân tích thành phần xác nhận trong nguồn học thuật. Căn cứ cấu trúc có thể: 食 (thực, biểu nghĩa: thức ăn) + 莫 (mạc, biểu âm). Chỉ bánh bao hoặc hành động bón thức ăn cho trẻ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": bánh bao 饝 — bộ 食 (thực, thức ăn) + âm mạc như \"mạc như\" (không gì bằng) — bánh bao trắng tròn ngon không gì bằng. | Gương Hán-Việt | Chưa có từ Hán-Việt thông dụng chứa 饝 trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 饝 giúp đọc phương ngữ và từ điển ẩm thực cổ đại về các loại bánh bột Trung Hoa.", "Tự nguyên_Xie": "Không có glyph origin từ Wiktionary cho 饝. Thuộc bộ 食 (thực) và âm đọc mó. Nghĩa ghi nhận: bánh bột (steamed bread) hoặc hành động bón thức ăn dạng bánh bao cho trẻ nhỏ. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bột", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 磨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠磨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "磨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饝", "Unihan_Traditional (Chữ Phồn thể)": "饝", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ các loại bánh làm từ bột mì được hấp chín. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騇', '{"9000": "8547.0", "Chữ Trung Quốc": "騇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 18 | nét | 馬 | mã | biểu nghĩa | ngựa | 舍 | xá | biểu âm | 騇 = 馬 (Mã, biểu nghĩa: ngựa) + 舍 (Xá, biểu âm); chữ hình thanh. Bộ Mã cho biết liên quan đến ngựa, phần Xá cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xạ\": ngựa (馬/mã) trú trong chuồng (舍/xá) — ngựa cái nghỉ ngơi trong chuồng trại. | Gương Hán-Việt | xạ — ít dùng trong tiếng Việt hiện đại, chủ yếu trong cổ văn chỉ ngựa cái. | Mở khoá kiến thức | Biết 騇 (xạ) giúp nhận ra các chữ liên quan đến ngựa trong cổ thư Hán-Việt.", "Tự nguyên_Xie": "Theo Wiktionary, 騇 là chữ hình thanh: bộ 馬 (mã, nghĩa: ngựa) kết hợp với 舍 (xá) làm phần biểu âm. Chữ chỉ ngựa cái hoặc ngựa đực chưa thiến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngựa cái; ngựa cái", "Hạng Tần Suất (Jun Da)": "8547.0", "Tần Suất % (Jun Da)": "99.9997157682", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 舍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬舍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騇", "Unihan_Traditional (Chữ Phồn thể)": "騇", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ giống ngựa cái trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腂', '{"9000": "8548.0", "Chữ Trung Quốc": "腂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 腂 | lỗi | tượng hình | tên gọi cổ (nghĩa không rõ) | 腂 không có dữ liệu cấu tạo rõ ràng trong kho dữ liệu hiện tại. Bộ 肉 (nhục) có thể liên quan đến cơ thể. Chưa có nguồn học thuật xác định cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": bộ thịt (肉/nhục) ẩn trong chữ — liên tưởng đến một phần cơ thể xa lạ, khó xác định. | Gương Hán-Việt | lỗi — không thấy trong từ Hán-Việt thông dụng hiện đại. | Mở khoá kiến thức | Biết 腂 (lỗi) giúp nhận dạng chữ hiếm trong cổ thư y học hoặc điển tịch.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 腂. Chữ thuộc bộ 肉 (nhục, thịt/cơ thể). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hyđrazin", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腂", "Unihan_Traditional (Chữ Phồn thể)": "腂", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng để chỉ các phần xương khớp hoặc mắt cá chân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臗', '{"9000": "8549.0", "Chữ Trung Quốc": "臗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 18 | nét | 臗 | khoan | tượng hình | hông, xương hông (dị thể của 髖) | 臗 là dị thể của 髖 (khoan, xương hông). Không có cấu tạo rõ ràng trong dữ liệu; bộ 肉 (nhục) gợi liên quan đến cơ thể. Chưa có nguồn học thuật xác định cụ thể ls cho chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoan\": dị thể của 髖 (xương hông) — phần hông rộng (khoan) của cơ thể. | Gương Hán-Việt | khoan — dùng trong 髖關節 (khớp hông) qua dạng chuẩn 髖. | Mở khoá kiến thức | Biết 臗 (khoan) giúp nhận dạng dị thể của 髖 trong y văn cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 臗 là dạng thay thế (alt form) của 髖 (khoan, xương hông, ổ cối hông). Chữ thuộc bộ 肉 (nhục). Không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết bẩn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "臗", "Unihan_Traditional (Chữ Phồn thể)": "臗", "Pinyin_Xie": "kuān", "Âm Hán Việt_Xie": "khoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng để chỉ các vết bẩn hoặc vết ố bám trên bề mặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眀', '{"9000": "8550.0", "Chữ Trung Quốc": "眀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 眀 | minh | tượng hình | sáng, rõ ràng (dị thể của 明) | 眀 là dị thể ít thông dụng của 明 (minh, sáng). Cấu tạo có thể gồm bộ 目 (mục, mắt) thay cho 日 (nhật, mặt trời) trong 明. Không có dữ liệu cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": mắt (目/mục) nhìn trăng (月/nguyệt) — thấy rõ ràng trong bóng tối, đó là minh (sáng). | Gương Hán-Việt | minh — xuất hiện trong nhiều từ: minh bạch, quang minh, văn minh (qua dạng chuẩn 明). | Mở khoá kiến thức | Biết 眀 (minh) giúp nhận ra dị thể của 明 trong cổ bản.", "Tự nguyên_Xie": "眀 là dị thể của 明 (minh, sáng sủa). Chữ 明 gốc gồm 日 (mặt trời) + 月 (mặt trăng); 眀 thay 日 bằng 目 (mắt), một biến thể trong lịch sử văn tự. Không có nguồn học thuật riêng cho 眀, áp dụng nguồn của 明. Chưa có nguồn học thuật riêng cho chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "眜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眀", "Unihan_Traditional (Chữ Phồn thể)": "眀", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ để mô tả trạng thái tối tăm hoặc mắt không nhìn rõ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砫', '{"9000": "8551.0", "Chữ Trung Quốc": "砫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砫 | trụ | tượng hình | tên địa danh (huyện Thạch Trụ, Tứ Xuyên) | 砫 có bộ 石 (thạch, đá). Không có dữ liệu cấu tạo chi tiết; chữ chủ yếu dùng trong địa danh Thạch Trụ (Tứ Xuyên). Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": đá (石/thạch) làm trụ cột — huyện Thạch Trụ, nơi có những cột đá vững chắc. | Gương Hán-Việt | trụ — ít dùng độc lập, chủ yếu trong địa danh Thạch Trụ. | Mở khoá kiến thức | Biết 砫 (trụ) giúp đọc địa danh lịch sử Thạch Trụ trong sử liệu Trung Quốc.", "Tự nguyên_Xie": "砫 là chữ dùng chủ yếu trong địa danh, chỉ huyện Thạch Trụ (石砫) tại tỉnh Tứ Xuyên, Trung Quốc. Bộ 石 (thạch, đá) gợi liên quan đến đá hoặc cột đá. Chưa có nguồn học thuật xác định cụ thể từ nguyên. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thạch Trụ (tên huyện, ở tỉnh Tứ Xuyên, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "8551.0", "Tần Suất % (Jun Da)": "99.9997183521", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砫", "Unihan_Traditional (Chữ Phồn thể)": "砫", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "trụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ bài vị bằng đá hoặc tên địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祙', '{"9000": "8552.0", "Chữ Trung Quốc": "祙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 祙 | mị | tượng hình | quỷ thần, ma quái | 祙 có bộ 示 (thị, tế lễ/thần linh). Không có dữ liệu cấu tạo chi tiết. Bộ 示 gợi liên quan đến tế tự hoặc thần linh ma quái. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": bộ tế lễ (示/thị) ẩn chứa ma quái — những thứ thuộc về cõi thần linh đáng sợ. | Gương Hán-Việt | mị — ít dùng trong tiếng Việt hiện đại; gần với mị quái, ma mị trong cổ văn. | Mở khoá kiến thức | Biết 祙 (mị) giúp nhận ra chữ hiếm chỉ quỷ thần trong cổ thư đạo giáo.", "Tự nguyên_Xie": "祙 thuộc bộ 示 (thị), bộ liên quan đến tế lễ và thần linh. Nghĩa chỉ quỷ thần hoặc ma quái. Không có dữ liệu từ nguyên chi tiết; chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祙", "Unihan_Traditional (Chữ Phồn thể)": "祙", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường đóng vai trò danh từ trong văn bản cổ để chỉ yêu ma hoặc tay áo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祳', '{"9000": "8553.0", "Chữ Trung Quốc": "祳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 祳 | thận | tượng hình | tế lễ, nghi lễ (chữ hiếm) | 祳 có bộ 示 (thị, tế lễ). Không có dữ liệu cấu tạo chi tiết. Bộ 示 gợi liên quan đến tế tự. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thận\": bộ tế lễ (示/thị) thực hiện cẩn trọng — thực hành nghi lễ một cách thận trọng. | Gương Hán-Việt | thận — ít dùng trong tiếng Việt hiện đại; có liên quan âm với 慎 (thận, thận trọng). | Mở khoá kiến thức | Biết 祳 (thận) giúp nhận ra chữ hiếm trong cổ thư tế lễ.", "Tự nguyên_Xie": "祳 thuộc bộ 示 (thị), liên quan đến tế lễ và nghi thức. Không có dữ liệu từ nguyên chi tiết; chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祳", "Unihan_Traditional (Chữ Phồn thể)": "祳", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ phần thịt dùng trong các nghi lễ cúng tế thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粧', '{"9000": "8554.0", "Chữ Trung Quốc": "粧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 米 | mễ | biểu nghĩa | gạo, bột phấn | 庄 | trang | biểu âm | 粧 = 米 (Mễ, biểu nghĩa: gạo/bột) + 庄 (Trang, biểu âm); chữ hình thanh. Bộ Mễ ám chỉ bột phấn trang điểm làm từ tinh chất ngũ cốc, phần Trang cho âm đọc. Chữ là dị thể phổ biến của 妝.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trang\": gạo (米/mễ) xay thành bột phấn — người xưa dùng bột gạo làm phấn trang điểm (trang). | Gương Hán-Việt | trang — dùng trong trang điểm, trang sức, hóa trang (qua dạng chuẩn 妝/庄). | Mở khoá kiến thức | Biết 粧 (trang) giúp đọc văn bản cổ và hiện đại Nhật-Trung về trang điểm, làm đẹp.", "Tự nguyên_Xie": "Theo Wiktionary, 粧 là chữ hình thanh: 米 (mễ, gạo) làm bộ biểu nghĩa gợi ý bột phấn trang điểm, 庄 (trang) làm phần biểu âm. Chữ mang nghĩa phấn son, trang sức, và qua nghĩa mở rộng là tự làm đẹp. Nguyên thủy là dạng phổ biến của 妝 (theo Digital Shinjigen 2017). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ trang điểm, trang sức", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 庄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米庄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粧", "Unihan_Traditional (Chữ Phồn thể)": "粧", "Pinyin_Xie": "zhuāng", "Âm Hán Việt_Xie": "trang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ việc trang điểm hoặc danh từ chỉ đồ trang sức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕣', '{"9000": "8555.0", "Chữ Trung Quốc": "蕣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕣 | thuấn | tượng hình | hoa dâm bụt (Hibiscus syriacus) | 蕣 có bộ 艸 (thảo, cỏ/thực vật). Không có dữ liệu cấu tạo chi tiết trong kho dữ liệu. Chữ là dị thể của 舜 trong tên loài cây dâm bụt. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuấn\": cỏ hoa (艸/thảo) của vua Thuấn (舜/thuấn) — hoa dâm bụt gắn liền với tên vị vua huyền thoại Thuấn trong cổ thư. | Gương Hán-Việt | thuấn — xuất hiện trong văn học cổ qua hình ảnh hoa 蕣華 (thuấn hoa, hoa thoáng qua). | Mở khoá kiến thức | Biết 蕣 (thuấn) giúp đọc thơ văn cổ dùng hình ảnh hoa dâm bụt tượng trưng cho vẻ đẹp phù du.", "Tự nguyên_Xie": "Wiktionary ghi nhận 蕣 là dạng thay thế (alt form) của 舜 khi dùng làm tên gọi cây dâm bụt (Hibiscus syriacus), còn gọi là 木槿 (mộc cẩn). Chữ có bộ 艸 (thảo). Không có phân tích cấu tạo chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dâm bụt; cây dâm bụt", "Hạng Tần Suất (Jun Da)": "8555.0", "Tần Suất % (Jun Da)": "99.9997204192", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 舜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹舜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕣", "Unihan_Traditional (Chữ Phồn thể)": "蕣", "Pinyin_Xie": "shùn", "Âm Hán Việt_Xie": "thuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ loài hoa dâm bụt nở sớm tàn nhanh trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觓', '{"9000": "8556.0", "Chữ Trung Quốc": "觓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 角 | Số nét | 9 | nét | 觓 | cầu | tượng hình | cong queo, uốn lượn (chữ hiếm) | 觓 có bộ 角 (giác, sừng). Không có dữ liệu cấu tạo chi tiết. Bộ 角 gợi liên quan đến hình dạng cong như sừng. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cầu\": sừng (角/giác) cong cầu — hình ảnh sừng uốn cong như cái cầu. | Gương Hán-Việt | cầu — ít dùng trong tiếng Việt hiện đại; âm tương ứng với 求/cầu. | Mở khoá kiến thức | Biết 觓 (cầu) giúp nhận ra chữ hiếm bộ Giác trong cổ thư.", "Tự nguyên_Xie": "Wiktionary ghi nhận 觓 âm đọc qiú, thuộc bộ 角 (giác, sừng). Nghĩa chưa được định rõ (rfdef). Không có phân tích từ nguyên chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "角 + 丩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰角丩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "角", "Unihan_Simplified (Chữ Giản thể)": "觓", "Unihan_Traditional (Chữ Phồn thể)": "觓", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "cầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường dùng làm tính từ để miêu tả hình dáng cong vút của sừng động vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趹', '{"9000": "8557.0", "Chữ Trung Quốc": "趹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 趹 | quyết | tượng hình | ngựa phi nước đại (chữ hiếm) | 趹 có bộ 足 (túc, chân). Không có dữ liệu cấu tạo chi tiết. Bộ 足 gợi liên quan đến động tác chân, phi nước đại. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": chân (足/túc) phi quyết liệt — bước chân ngựa phi nước đại, dứt khoát. | Gương Hán-Việt | quyết — ít dùng độc lập; âm tương ứng với 決/quyết (quyết đoán). | Mở khoá kiến thức | Biết 趹 (quyết) giúp nhận ra chữ cổ chỉ động tác phi nhanh trong thơ văn mô tả ngựa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 趹 có glyph origin từ thời cổ (có dữ liệu Han etym) nhưng không cung cấp phân tích chi tiết. Chữ thuộc bộ 足 (túc, chân), gợi nghĩa ngựa phi nhanh. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phi nước đại", "Hạng Tần Suất (Jun Da)": "8557.0", "Tần Suất % (Jun Da)": "99.9997214528", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趹", "Unihan_Traditional (Chữ Phồn thể)": "趹", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ để tả hành động chạy nhanh hoặc phi nước đại của ngựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄍', '{"9000": "8558.0", "Chữ Trung Quốc": "鄍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 12 | nét | 鄍 | minh | tượng hình | địa danh (tên đất ở Sơn Đông) | 鄍 có bộ 邑 (ấp, làng/địa danh). Không có dữ liệu cấu tạo chi tiết. Bộ 邑 cho biết chữ dùng chỉ địa danh. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"minh\": làng (邑/ấp) có tên gọi minh — địa danh cổ mang âm minh ở vùng Sơn Đông. | Gương Hán-Việt | minh — ít dùng trong tiếng Việt; âm tương ứng với 明/minh (sáng). | Mở khoá kiến thức | Biết 鄍 (minh) giúp đọc sử liệu địa lý cổ Trung Quốc liên quan Sơn Đông.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鄍 là địa danh (zh-used2 p), dùng chỉ một vùng đất ở tỉnh Sơn Đông, Trung Quốc. Bộ 邑 (ấp) đặc trưng cho các chữ chỉ địa danh hoặc tên làng xã trong cổ văn Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên địa điểm", "Hạng Tần Suất (Jun Da)": "8558.0", "Tần Suất % (Jun Da)": "99.9997219696", "GavinGrover_Once (Chiết tự trực tiếp)": "冥 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冥阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄍", "Unihan_Traditional (Chữ Phồn thể)": "鄍", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ riêng để chỉ một địa danh thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈡', '{"9000": "8559.0", "Chữ Trung Quốc": "鈡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 金 | kim | biểu nghĩa | kim loại | 中 | trung | biểu âm | 鈡 = 金 (Kim, biểu nghĩa: kim loại) + 中 (Trung, biểu âm); chữ hình thanh. Bộ Kim gợi vật bằng kim loại (chuông), phần Trung cho âm đọc. Chữ là dị thể của 鐘 (chuông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chung\": kim loại (金/kim) ở chính giữa (中/trung) — cái chuông đúc bằng kim loại, tiếng vang đúng trung tâm. | Gương Hán-Việt | chung — dùng trong đồng chung (cái chuông đồng), chung thanh (tiếng chuông) qua dạng chuẩn 鐘. | Mở khoá kiến thức | Biết 鈡 (chung) giúp nhận ra dị thể của 鐘 (chuông) trong văn bản cổ và Nhật ngữ.", "Tự nguyên_Xie": "Theo Wiktionary, 鈡 là chữ hình thanh: 金 (kim, kim loại) làm bộ biểu nghĩa, 中 (trung) làm phần biểu âm. Chữ là dị thể của 鐘 (chung, cái chuông), vật dụng bằng kim loại phát tiếng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 中", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金中", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈡", "Unihan_Traditional (Chữ Phồn thể)": "鈡", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ cái chuông hoặc nhạc cụ gõ bằng kim loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羭', '{"9000": "8560.0", "Chữ Trung Quốc": "羭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 15 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 俞 | du | biểu âm | 羭 = 羊 (Dương, biểu nghĩa: cừu/dê) + 俞 (Du, biểu âm); chữ hình thanh. Bộ Dương cho biết liên quan đến loài cừu, phần俞 cho âm đọc. Chữ chỉ con dê/cừu đực màu đen hoặc tốt lành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": dê (羊/dương) vượt qua (俞/du) — con dê đực mạnh khỏe, vượt trội trong đàn. | Gương Hán-Việt | du — ít dùng trong tiếng Việt hiện đại; âm tương ứng với 愉/du (vui vẻ). | Mở khoá kiến thức | Biết 羭 (du) giúp đọc cổ thư chăn nuôi hoặc thơ văn mô tả gia súc.", "Tự nguyên_Xie": "Theo Wiktionary, 羭 là chữ hình thanh: 羊 (dương, cừu/dê) làm bộ biểu nghĩa, 俞 (du) làm phần biểu âm. Chữ chỉ con dê đực tốt hoặc màu đen. Không có dữ liệu hình thái cổ (giáp cốt, kim văn) trong bộ dữ liệu. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ram đen", "Hạng Tần Suất (Jun Da)": "8560.0", "Tần Suất % (Jun Da)": "99.9997230032", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羭", "Unihan_Traditional (Chữ Phồn thể)": "羭", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ con dê hoặc con cừu đực có lông màu đen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝄', '{"9000": "8561.0", "Chữ Trung Quốc": "蝄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sâu bọ | 罔 | võng | biểu âm | 蝄 = 虫 (Trùng, biểu nghĩa: côn trùng/sinh vật nhỏ) + 罔 (Võng, biểu âm); chữ hình thanh. Bộ Trùng gợi liên quan đến sinh vật nhỏ hoặc ma quỷ dạng côn trùng, phần Võng cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": sinh vật (虫/trùng) như mạng lưới (罔/võng) — loài ma quái dạng côn trùng giăng mạng trong bóng tối. | Gương Hán-Việt | võng — ít dùng trong tiếng Việt; âm gần với 網/võng (mạng lưới). | Mở khoá kiến thức | Biết 蝄 (võng) giúp đọc cổ thư miêu tả ma quái thiên nhiên trong văn hóa dân gian Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary (dẫn từ 蛧 — dị thể), 蝄 là chữ hình thanh: 虫 (trùng, sâu/côn trùng) làm bộ biểu nghĩa, 罔 (võng) làm phần biểu âm. Chữ chỉ dùng trong tổ hợp 蝄蜽 (một loại ma quỷ theo quan niệm cổ đại). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: võng lượng 魍魎,魍魉,蝄蜽)", "Hạng Tần Suất (Jun Da)": "8561.0", "Tần Suất % (Jun Da)": "99.99972352", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 罔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝄", "Unihan_Traditional (Chữ Phồn thể)": "蝄", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ khác làm danh từ ghép để chỉ các loài yêu quái theo truyền thuyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衸', '{"9000": "8562.0", "Chữ Trung Quốc": "衸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衸 | giới | tượng hình | chữ hiếm (nghĩa không rõ) | 衸 không có dữ liệu cấu tạo rõ ràng. Bộ có thể liên quan đến 衣 (y, áo) hoặc 行 (hành). Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": chữ hiếm âm giới — liên tưởng đến ranh giới, giới hạn giữa các phần áo. | Gương Hán-Việt | giới — ít dùng trong tiếng Việt; âm tương ứng với 界/giới (ranh giới). | Mở khoá kiến thức | Biết 衸 (giới) giúp nhận ra chữ hiếm trong cổ thư.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 衸. Chữ hiếm, nghĩa chưa xác định rõ. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衸", "Unihan_Traditional (Chữ Phồn thể)": "衸", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vạt áo dài hoặc nếp áo trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謡', '{"9000": "8563.0", "Chữ Trung Quốc": "謡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 謡 | dao | tượng hình | ca dao, dân ca, tin đồn (dị thể của 謠) | 謡 là dị thể của 謠 (dao, ca dao/tin đồn), có bộ 言 (ngôn, lời nói). Không có dữ liệu cấu tạo chi tiết trong kho dữ liệu hiện tại. Bộ 言 gợi liên quan đến lời nói, hát hò, đồn đại. Chưa có nguồn học thuật xác định ls riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dao\": lời (言/ngôn) bay xa (dao/遙) — ca dao dân gian lan truyền khắp nơi như tin đồn. | Gương Hán-Việt | dao — dùng trong ca dao (歌謠/ca dao), đồng dao (童謠/đồng dao). | Mở khoá kiến thức | Biết 謡 (dao) giúp đọc cổ văn về ca dao dân gian và nhận ra từ 童謠, 歌謠 trong văn bản.", "Tự nguyên_Xie": "謡 là dị thể của 謠 (dao), chữ hình thanh gồm 言 (ngôn, lời nói) + 䍃 hoặc 遙 làm phần biểu âm. Chữ mang nghĩa ca dao dân gian, bài hát không có nhạc cụ, hoặc tin đồn. Dạng chuẩn hiện đại là 谣 (giản thể) / 謠 (phồn thể). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衡", "Hạng Tần Suất (Jun Da)": "8563.0", "Tần Suất % (Jun Da)": "99.9997245535", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "謡", "Unihan_Traditional (Chữ Phồn thể)": "謡", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "dao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ như ca hát hoặc truyền tai để chỉ bài hát, lời đồn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眲', '{"9000": "8564.0", "Chữ Trung Quốc": "眲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 眲 | nặc | tượng hình | khinh thường, coi thường (chữ cổ) | 眲 có bộ 目 (mục, mắt). Không có dữ liệu cấu tạo chi tiết. Bộ 目 gợi liên quan đến ánh mắt khinh miệt. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nặc\": mắt (目/mục) nhìn xuống nặc nặc — ánh mắt khinh thị, nhìn người khác như không đáng. | Gương Hán-Việt | nặc — ít dùng trong tiếng Việt hiện đại; chữ cổ chỉ thái độ khinh miệt. | Mở khoá kiến thức | Biết 眲 (nặc) giúp đọc cổ thư mô tả thái độ khinh miệt, coi thường người khác.", "Tự nguyên_Xie": "Wiktionary ghi nhận 眲 (nè/nặc) nghĩa cổ: khinh thường, coi thường, đánh giá thấp. Thuộc bộ 目 (mục, mắt). Không có phân tích cấu tạo chi tiết trong dữ liệu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quyến rũ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眲", "Unihan_Traditional (Chữ Phồn thể)": "眲", "Pinyin_Xie": "nè", "Âm Hán Việt_Xie": "nặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động liếc mắt nhìn hoặc tỏ thái độ khinh thường. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睋', '{"9000": "8565.0", "Chữ Trung Quốc": "睋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睋 | nga | tượng hình | chữ hiếm (nghĩa không rõ) | 睋 có bộ 目 (mục, mắt). Không có dữ liệu cấu tạo chi tiết. Nghĩa chưa được xác định (rfdef). Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": mắt (目/mục) như vầng trăng nga — chữ cổ bộ Mục, âm đọc nga như Hằng Nga. | Gương Hán-Việt | nga — ít dùng trong tiếng Việt; âm tương ứng với 娥/nga (Hằng Nga). | Mở khoá kiến thức | Biết 睋 (nga) giúp nhận ra chữ hiếm bộ Mục trong cổ thư.", "Tự nguyên_Xie": "Wiktionary ghi nhận 睋 âm đọc é, thuộc bộ 目 (mục, mắt), nhưng nghĩa chưa được định rõ (rfdef). Không có phân tích cấu tạo chi tiết trong dữ liệu. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn; xem; trông", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睋", "Unihan_Traditional (Chữ Phồn thể)": "睋", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng được quan sát hoặc trông ngóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矃', '{"9000": "8566.0", "Chữ Trung Quốc": "矃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 19 | nét | 矃 | ninh | tượng hình | nhìn chằm chằm, nhìn nghiêm | 矃 không có dữ liệu cấu tạo rõ ràng trong kho dữ liệu. Không có nguồn học thuật xác định ls. Chữ hiếm, dùng để diễn tả cái nhìn nghiêm nghị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ninh\": nhìn chằm chằm ninh ninh — ánh mắt tập trung, cứng rắn, không rời. | Gương Hán-Việt | ninh — ít dùng độc lập; âm tương ứng với 寧/ninh (yên bình). | Mở khoá kiến thức | Biết 矃 (ninh) giúp nhận ra chữ hiếm mô tả ánh mắt trong cổ thư.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 矃. Chữ hiếm, nghĩa chưa xác định đầy đủ. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "烃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 寧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目寧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矃", "Unihan_Traditional (Chữ Phồn thể)": "矃", "Pinyin_Xie": "nǐng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động tập trung ánh mắt nhìn vào một vật hay người nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矒', '{"9000": "8567.0", "Chữ Trung Quốc": "矒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 20 | nét | 矒 | mông | tượng hình | mắt mờ, không rõ (chữ hiếm) | 矒 không có dữ liệu cấu tạo rõ ràng trong kho dữ liệu. Chữ hiếm, có thể liên quan đến bộ 目 (mục). Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\": mắt mông lung, nhìn không rõ — như sương mù che phủ tầm nhìn. | Gương Hán-Việt | mông — ít dùng độc lập; âm tương ứng với 朦/mông (mờ mịt). | Mở khoá kiến thức | Biết 矒 (mông) giúp nhận ra chữ cổ liên quan thị giác mờ trong y văn cổ.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 矒. Pinyin méng, gợi nghĩa mờ mịt, mắt không rõ (gần với 朦/mông, mờ). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 瞢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目瞢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "矒", "Unihan_Traditional (Chữ Phồn thể)": "矒", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Làm tính từ miêu tả trạng thái thị lực suy giảm hoặc không rõ ràng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硟', '{"9000": "8568.0", "Chữ Trung Quốc": "硟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硟 | sạn | tượng hình | trượt, trơn (Quảng Đông); đá mài | 硟 có bộ 石 (thạch, đá). Không có dữ liệu cấu tạo chi tiết. Bộ 石 gợi liên quan đến đá hoặc bề mặt đá nhẵn trơn. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sạn\": đá (石/thạch) trơn sạn — bề mặt đá nhẵn bóng khiến dễ trượt ngã. | Gương Hán-Việt | sạn — ít dùng trong tiếng Việt; gần với từ sạn (đá nhỏ, sỏi) trong tiếng Việt thông thường. | Mở khoá kiến thức | Biết 硟 (sạn) giúp đọc văn bản Quảng Đông hoặc cổ thư liên quan bề mặt đá.", "Tự nguyên_Xie": "Wiktionary ghi nhận 硟 âm đọc chàn (tiếng Quảng Đông: cin3), nghĩa trượt. Thuộc bộ 石 (thạch, đá). Không có phân tích cấu tạo chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硟", "Unihan_Traditional (Chữ Phồn thể)": "硟", "Pinyin_Xie": "chàn", "Âm Hán Việt_Xie": "sạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ hành động mài nhẵn, làm phẳng hoặc làm danh từ chỉ đá mài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磄', '{"9000": "8569.0", "Chữ Trung Quốc": "磄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磄 | đường | tượng hình | chữ hiếm (nghĩa không rõ) | 磄 có bộ 石 (thạch, đá). Không có dữ liệu cấu tạo chi tiết. Nghĩa chưa được định rõ (rfdef). Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đường\": đá (石/thạch) màu đường — chữ hiếm bộ Thạch, âm đường gợi màu vàng nâu của đất đá. | Gương Hán-Việt | đường — ít dùng trong tiếng Việt; âm tương ứng với 唐/đường (nhà Đường). | Mở khoá kiến thức | Biết 磄 (đường) giúp nhận ra chữ hiếm bộ Thạch trong cổ thư địa lý.", "Tự nguyên_Xie": "Wiktionary ghi nhận 磄 âm đọc táng, thuộc bộ 石 (thạch, đá), nhưng nghĩa chưa được định rõ (rfdef). Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "磄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 唐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石唐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "唐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磄", "Unihan_Traditional (Chữ Phồn thể)": "磄", "Pinyin_Xie": "táng", "Âm Hán Việt_Xie": "đường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ thường dùng trong các từ ghép cổ để chỉ một loại đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礂', '{"9000": "8570.0", "Chữ Trung Quốc": "礂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 17 | nét | 礂 | tê | tượng hình | chữ hiếm (nghĩa không rõ) | 礂 có bộ 石 (thạch, đá). Không có dữ liệu cấu tạo hay từ nguyên chi tiết. Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": đá (石/thạch) đặc biệt, tê lạnh — chữ hiếm bộ Thạch, âm tê gợi cảm giác lạnh giá của đá. | Gương Hán-Việt | tê — ít dùng trong tiếng Việt; âm gần với 梯/tê hoặc 犀/tê (tê giác). | Mở khoá kiến thức | Biết 礂 (tê) giúp nhận ra chữ hiếm bộ Thạch trong văn bản cổ.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 礂. Chữ hiếm bộ 石 (thạch). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "炂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礂", "Unihan_Traditional (Chữ Phồn thể)": "礂", "Pinyin_Xie": "xi", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại đá cứng trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礊', '{"9000": "8571.0", "Chữ Trung Quốc": "礊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礊 | khắc | tượng hình | chữ hiếm (nghĩa không rõ) | 礊 có bộ 石 (thạch, đá). Không có dữ liệu cấu tạo chi tiết. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khắc\": đá (石/thạch) khắc chạm — liên tưởng đến nghệ thuật khắc đá cứng. | Gương Hán-Việt | khắc — ít dùng độc lập; âm tương ứng với 刻/khắc (khắc chạm). | Mở khoá kiến thức | Biết 礊 (khắc) giúp nhận ra chữ hiếm bộ Thạch trong cổ thư.", "Tự nguyên_Xie": "Wiktionary ghi nhận 礊 có dữ liệu Han etym nhưng không cung cấp phân tích glyphOrigin chi tiết. Thuộc bộ 石 (thạch). Nghĩa chưa xác định rõ. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "犊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𣪠 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𣪠石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣪠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礊", "Unihan_Traditional (Chữ Phồn thể)": "礊", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu làm danh từ chỉ con bê hoặc tính từ chỉ tính chất cứng như đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祰', '{"9000": "8572.0", "Chữ Trung Quốc": "祰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 祰 | cáo | tượng hình | tế cáo, cầu nguyện (chữ hiếm) | 祰 có bộ 示 (thị, tế lễ). Không có dữ liệu cấu tạo chi tiết. Bộ 示 gợi liên quan đến tế tự và cầu nguyện. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\": tế lễ (示/thị) cáo tế — dâng lời cáo tế lên thần linh, tổ tiên. | Gương Hán-Việt | cáo — ít dùng trong tiếng Việt; âm tương ứng với 告/cáo (báo cáo). | Mở khoá kiến thức | Biết 祰 (cáo) giúp đọc cổ thư tế lễ và nghi thức cúng bái.", "Tự nguyên_Xie": "Wiktionary ghi nhận 祰 âm đọc gào, thuộc bộ 示 (thị), nhưng nghĩa chưa được định rõ (rfdef). Không có phân tích cấu tạo chi tiết. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祰", "Unihan_Traditional (Chữ Phồn thể)": "祰", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong các nghi lễ cúng bái cổ đại để thông báo với thần linh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祹', '{"9000": "8573.0", "Chữ Trung Quốc": "祹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 祹 | đào | tượng hình | chữ hiếm (nghĩa không rõ) | 祹 có bộ 示 (thị, tế lễ). Không có dữ liệu cấu tạo hay từ nguyên chi tiết. Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": tế lễ (示/thị) theo dòng đào — chữ hiếm bộ Thị, âm đào gợi con đường nước/đào thoát. | Gương Hán-Việt | đào — ít dùng trong tiếng Việt; âm tương ứng với 桃/đào (đào tiên) hoặc 逃/đào (chạy trốn). | Mở khoá kiến thức | Biết 祹 (đào) giúp nhận ra chữ hiếm bộ Thị trong cổ thư.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 祹. Chữ hiếm thuộc bộ 示 (thị). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祹", "Unihan_Traditional (Chữ Phồn thể)": "祹", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn bản cổ để chỉ sự may mắn hoặc phúc lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禐', '{"9000": "8574.0", "Chữ Trung Quốc": "禐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禐 | nguyện | tượng hình | chữ hiếm bộ Thị (nghĩa không rõ) | 禐 có bộ 示 (thị, tế lễ). Không có dữ liệu cấu tạo hay từ nguyên chi tiết. Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyện\": tế lễ (示/thị) dâng lên nguyện vọng — chữ hiếm bộ Thị, âm nguyện gợi lời cầu nguyện. | Gương Hán-Việt | nguyện — ít dùng độc lập; âm tương ứng với 願/nguyện (ước nguyện). | Mở khoá kiến thức | Biết 禐 (nguyện) giúp nhận ra chữ hiếm bộ Thị trong văn bản tế lễ cổ.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 禐. Chữ hiếm thuộc bộ 示 (thị). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tề", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "禐", "Unihan_Traditional (Chữ Phồn thể)": "禐", "Pinyin_Xie": "yuàn", "Âm Hán Việt_Xie": "nguyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ hành vi cúng tế hoặc danh từ chỉ nghi lễ tế thần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秳', '{"9000": "8575.0", "Chữ Trung Quốc": "秳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 禾 | biểu nghĩa | lúa, ngũ cốc | 秳 = 禾 (biểu nghĩa: lúa/ngũ cốc) + 𠯑 (biểu âm, theo Wiktionary); chữ hình thanh. Bộ Hòa (禾) cho biết liên quan đến lúa hoặc nông nghiệp, phần 𠯑 cho âm đọc. Chữ hiếm, nghĩa liên quan đến cây lúa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạt\": lúa (禾/hòa) hoạt động — cây lúa non linh hoạt, uốn mình theo gió. | Gương Hán-Việt | hoạt — ít dùng trong tiếng Việt; âm tương ứng với 活/hoạt (sống động). | Mở khoá kiến thức | Biết 秳 (hoạt) giúp nhận ra chữ hình thanh bộ Hòa trong cổ thư nông nghiệp.", "Tự nguyên_Xie": "Theo Wiktionary, 秳 là chữ hình thanh: 禾 (hòa, lúa) làm bộ biểu nghĩa (c1=s), 𠯑 làm phần biểu âm (c2=p). Nghĩa cụ thể chưa được xác định rõ trong dữ liệu hiện có. Chưa có nguồn học thuật xác định đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Jian", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秳", "Unihan_Traditional (Chữ Phồn thể)": "秳", "Pinyin_Xie": "huó", "Âm Hán Việt_Xie": "hoạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại cây lương thực hoặc lúa non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秼', '{"9000": "8576.0", "Chữ Trung Quốc": "秼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秼 | chu | tượng hình | chữ hiếm bộ Hòa (nghĩa không rõ) | 秼 có bộ 禾 (hòa, lúa). Không có dữ liệu cấu tạo hay từ nguyên chi tiết. Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": lúa (禾/hòa) chu toàn — chữ hiếm bộ Hòa, âm chu gợi sự đầy đủ, trọn vẹn. | Gương Hán-Việt | chu — ít dùng trong tiếng Việt; âm tương ứng với 朱/chu (màu đỏ son) hoặc 株/chu (cây, cọc). | Mở khoá kiến thức | Biết 秼 (chu) giúp nhận ra chữ hiếm bộ Hòa trong cổ thư nông nghiệp.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 秼. Chữ hiếm thuộc bộ 禾 (hòa, lúa). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Minh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秼", "Unihan_Traditional (Chữ Phồn thể)": "秼", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại lúa hoặc ngũ cốc thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稄', '{"9000": "8577.0", "Chữ Trung Quốc": "稄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 12 | nét | 稄 | tấn | tượng hình | chữ hiếm bộ Hòa (nghĩa không rõ) | 稄 có bộ 禾 (hòa, lúa). Không có dữ liệu cấu tạo hay từ nguyên chi tiết. Chưa có nguồn học thuật xác định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấn\": lúa (禾/hòa) tấn tới — chữ hiếm bộ Hòa, âm tấn gợi sự tiến triển của mùa màng. | Gương Hán-Việt | tấn — ít dùng trong tiếng Việt; âm tương ứng với 進/tấn (tiến lên). | Mở khoá kiến thức | Biết 稄 (tấn) giúp nhận ra chữ hiếm bộ Hòa trong cổ thư nông nghiệp.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 稄. Chữ hiếm thuộc bộ 禾 (hòa, lúa). Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lou", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稄", "Unihan_Traditional (Chữ Phồn thể)": "稄", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hoạt động canh tác, gieo cấy nông nghiệp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稇', '{"9000": "8578.0", "Chữ Trung Quốc": "稇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 12 | nét | 稇 | khổn | tượng hình | bó lúa, bó rơm (chữ hiếm) | 稇 có bộ 禾 (hòa, lúa). Không có dữ liệu cấu tạo chi tiết. Bộ 禾 gợi liên quan đến lúa hoặc bó rơm. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khổn\": lúa (禾/hòa) bó khổn lại — bó lúa buộc chặt sau mùa gặt. | Gương Hán-Việt | khổn — ít dùng trong tiếng Việt; âm tương ứng với 困/khổn (khó khăn) hoặc 捆/khổn (bó lại). | Mở khoá kiến thức | Biết 稇 (khổn) giúp nhận ra chữ cổ chỉ việc bó lúa trong sách nông nghiệp cổ.", "Tự nguyên_Xie": "Không có dữ liệu từ nguyên chi tiết cho 稇. Chữ hiếm thuộc bộ 禾 (hòa, lúa). Có thể liên quan đến việc bó buộc ngũ cốc. Chưa có nguồn học thuật xác định. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"捆\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 困", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾困", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "困", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稇", "Unihan_Traditional (Chữ Phồn thể)": "稇", "Pinyin_Xie": "kǔn", "Âm Hán Việt_Xie": "khổn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động bó lúa hoặc danh từ chỉ bó lúa đã gặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稘', '{"9000": "8579.0", "Chữ Trung Quốc": "稘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | biểu nghĩa | lúa, ngũ cốc | 其 | kỳ | biểu âm | 稘 = 禾 (biểu nghĩa: lúa/ngũ cốc) + 其 (Kỳ, biểu âm); chữ hình thanh. Bộ Hòa (禾) cho biết liên quan đến ngũ cốc, phần Kỳ cho âm đọc. Chữ chỉ một năm đầy đủ, một chu kỳ nông nghiệp hoàn chỉnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": lúa (禾/hòa) qua một kỳ (其/kỳ) — một chu kỳ canh tác hoàn chỉnh từ gieo đến gặt. | Gương Hán-Việt | kỳ — ít dùng trong tiếng Việt; âm tương ứng với 期/kỳ (kỳ hạn, thời hạn). | Mở khoá kiến thức | Biết 稘 (kỳ) giúp đọc cổ thư lịch nông nghiệp và hiểu thuật ngữ chu kỳ mùa vụ.", "Tự nguyên_Xie": "Theo Wiktionary (dẫn từ Han etyl — chú ý đây là Han etyl, không phải etym), 稘 là chữ hình thanh: 禾 (hòa, lúa) làm bộ biểu nghĩa (c1=s), 其 (kỳ) làm phần biểu âm (c2=p). Chữ chỉ một chu kỳ nông nghiệp hoàn chỉnh, một năm đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "稘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稘", "Unihan_Traditional (Chữ Phồn thể)": "稘", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ thân cây lúa hoặc thời gian tròn một năm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稙', '{"9000": "8580.0", "Chữ Trung Quốc": "稙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稙 | trực | tượng hình | lúa sớm, gieo trồng sớm (chữ hiếm) | 稙 có bộ 禾 (hòa, lúa). Không có dữ liệu cấu tạo chi tiết trong kho dữ liệu. Bộ 禾 gợi liên quan đến cây ngũ cốc. Chưa có nguồn học thuật xác định ls.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trực\": lúa (禾/hòa) thẳng trực — cây lúa đầu tiên mọc thẳng tắp, gieo sớm nhất mùa. | Gương Hán-Việt | trực — ít dùng trong tiếng Việt; âm tương ứng với 直/trực (thẳng, ngay thẳng). | Mở khoá kiến thức | Biết 稙 (trực) giúp nhận ra chữ cổ chỉ lúa sớm trong sách nông nghiệp cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi nhận 稙 âm đọc zhì (MC: zik6 Quảng Đông), nghĩa chưa được định rõ (rfdef). Thuộc bộ 禾 (hòa, lúa). Trong văn cảnh nông nghiệp cổ, chữ này có thể chỉ loại lúa gieo sớm. Chưa có nguồn học thuật xác định đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trồng sớm hoặc chín sớm (lúa, hoa màu)", "Hạng Tần Suất (Jun Da)": "8580.0", "Tần Suất % (Jun Da)": "99.999735406", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 直", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾直", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "直", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稙", "Unihan_Traditional (Chữ Phồn thể)": "稙", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "trị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho các loại cây trồng gieo cấy sớm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竸', '{"9000": "8581.0", "Chữ Trung Quốc": "竸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 22 | nét | 竸 | cạnh | tượng hình | biến thể của 競 (cạnh tranh); chữ tự thân là thành tố | 竸 là biến thể cổ của 競 (Cạnh). Chữ không còn phân tích thành phần rõ ràng trong hệ thống hiện đại; chưa có nguồn học thuật xác nhận cấu trúc nội tại. Coi như tượng hình / biến thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cạnh\": hình dáng tương tự 競, gợi hình ảnh hai người đứng (立) tranh đua nhau — cạnh tranh, ganh đua. | Gương Hán-Việt | \"cạnh\" trong \"cạnh tranh\" (競爭), dạng biến thể cổ hiếm dùng | Mở khoá kiến thức | Biết 竸 giúp nhận dạng biến thể cổ của 競 trong văn bản Hán cổ điển về thi đua, cạnh tranh.", "Tự nguyên_Xie": "竸 là dạng biến thể cổ của 競 (cạnh tranh, thi đua). Không có nguồn Wiktionary về gốc chữ này. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "竟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴竟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竸", "Unihan_Traditional (Chữ Phồn thể)": "竸", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "cạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ thể hiện sự tranh đua hoặc làm danh từ chỉ cuộc cạnh tranh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竾', '{"9000": "8582.0", "Chữ Trung Quốc": "竾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 竾 | trì | tượng hình | biến thể cổ chỉ loại sáo trúc 8 lỗ | 竾 là chữ hiếm, biến thể cổ chỉ loại sáo trúc 8 lỗ (flute). Không có phân tích thành phần rõ ràng trong nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\": tưởng tượng tiếng sáo trúc (竹) ngân dài, âm thanh kéo lê chậm rãi như nghĩa \"trì\" (chậm, lê lết). | Gương Hán-Việt | \"trì\" ít gặp trong từ Hán-Việt hiện đại; liên quan đến nhạc cụ trúc cổ | Mở khoá kiến thức | Biết 竾 giúp nhận dạng ký tự nhạc cụ trúc trong văn bản âm nhạc cổ điển Trung Quốc.", "Tự nguyên_Xie": "竾 là biến thể cổ chỉ loại sáo trúc 8 lỗ. Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sáo 8 lỗi", "Hạng Tần Suất (Jun Da)": "8582.0", "Tần Suất % (Jun Da)": "99.9997369564", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "竾", "Unihan_Traditional (Chữ Phồn thể)": "竾", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ một loại nhạc cụ thổi cổ xưa làm bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笐', '{"9000": "8583.0", "Chữ Trung Quốc": "笐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笐 | hàng | tượng hình | biến thể cổ; bộ trúc (竹) liên quan đến vật bằng tre | 笐 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm hàng (háng). Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": cây tre (竹) xếp thành hàng (hàng) ngay ngắn — liên tưởng đến vật dụng tre xếp thành dãy. | Gương Hán-Việt | \"hàng\" ít dùng trong từ Hán-Việt hiện đại; liên quan đến tre trúc | Mở khoá kiến thức | Biết 笐 giúp nhận dạng các chữ bộ 竹 trong văn bản về đồ vật tre cổ.", "Tự nguyên_Xie": "笐 thuộc bộ 竹 (trúc), liên quan đến vật dụng bằng tre. Wiktionary chỉ ghi {{Han etym}} chưa triển khai. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tre đặt ngang khung gỗ trên đó có thể cất giữ ngũ cốc trong điều kiện khí hậu ẩm ướt", "Hạng Tần Suất (Jun Da)": "8583.0", "Tần Suất % (Jun Da)": "99.9997374732", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笐", "Unihan_Traditional (Chữ Phồn thể)": "笐", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng làm danh từ để chỉ các loại sào tre hoặc giá treo đồ bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笜', '{"9000": "8584.0", "Chữ Trung Quốc": "笜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笜 | trú | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 笜 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm zhù. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trú\": cây trúc (竹) làm nơi trú (trú) ẩn — liên tưởng đến mái che bằng tre. | Gương Hán-Việt | \"trú\" ít gặp trong từ Hán-Việt dạng này; liên quan đến tre | Mở khoá kiến thức | Biết 笜 giúp nhận dạng chữ bộ 竹 chỉ đồ dùng tre trong cổ văn.", "Tự nguyên_Xie": "笜 thuộc bộ 竹 (trúc). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "笜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笜", "Unihan_Traditional (Chữ Phồn thể)": "笜", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu dùng làm danh từ chỉ mầm măng hoặc động từ chỉ sự sinh trưởng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筂', '{"9000": "8585.0", "Chữ Trung Quốc": "筂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 筂 | trì | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 筂 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm chí/chī. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trì\": trúc (竹) dài lê thê, mang âm \"trì\" — gợi đến tre dài, chậm mọc. | Gương Hán-Việt | \"trì\" ít dùng trong từ Hán-Việt hiện đại với chữ này | Mở khoá kiến thức | Biết 筂 giúp nhận dạng chữ bộ 竹 chỉ đồ dùng tre hiếm gặp trong cổ thư.", "Tự nguyên_Xie": "筂 thuộc bộ 竹 (trúc). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "筂", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 池", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮池", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "池", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筂", "Unihan_Traditional (Chữ Phồn thể)": "筂", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "trì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ ao hồ nhỏ hoặc một loại nhạc cụ thổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箒', '{"9000": "8586.0", "Chữ Trung Quốc": "箒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箒 | trửu | tượng hình | biến thể cổ của 帚 (chổi); phần trên là trúc (竹) | 箒 là biến thể cổ / dạng thay thế của 帚 (chổi), thêm bộ 竹 (trúc) lên trên, ám chỉ chổi làm từ cây cỏ hoặc tre. Chưa có nguồn học thuật xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trửu\": cây trúc (竹) cong xuống thành cái chổi (箒) — hình ảnh chổi tre quét sân. | Gương Hán-Việt | \"trửu\" ít dùng; dạng phổ biến là 帚 trong \"chổi\" (cái chổi) | Mở khoá kiến thức | Biết 箒 giúp nhận ra biến thể chữ \"chổi\" trong văn bản cổ có bộ Trúc.", "Tự nguyên_Xie": "箒 là biến thể cổ của 帚 (chổi, zhǒu). Thêm bộ 竹 (trúc) có thể để nhấn mạnh chất liệu tre. Không có gốc chữ đầy đủ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chổi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 帚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮帚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箒", "Unihan_Traditional (Chữ Phồn thể)": "箒", "Pinyin_Xie": "zhǒu", "Âm Hán Việt_Xie": "trửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ dụng cụ quét dọn nhà cửa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箛', '{"9000": "8587.0", "Chữ Trung Quốc": "箛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箛 | cô | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 箛 thuộc bộ 竹 (trúc), phiên âm gū. Wiktionary ghi {{Han etym}} chưa triển khai, không có phân tích thành phần. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": ống tre (竹) đơn độc, âm \"cô\" — như cô gái một mình, chiếc ống tre lẻ loi. | Gương Hán-Việt | \"cô\" ít gặp với chữ này; liên quan đến đồ vật tre đơn lẻ | Mở khoá kiến thức | Biết 箛 giúp nhận dạng chữ bộ 竹 hiếm gặp trong cổ thư về nhạc cụ hay đồ dùng tre.", "Tự nguyên_Xie": "箛 thuộc bộ 竹 (trúc), âm gū. Wiktionary chỉ ghi {{Han etym}} chưa triển khai; nghĩa chưa xác định. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(cây tre); kèn cho xe ngựa", "Hạng Tần Suất (Jun Da)": "8587.0", "Tần Suất % (Jun Da)": "99.9997395403", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 孤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮孤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箛", "Unihan_Traditional (Chữ Phồn thể)": "箛", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này được dùng làm danh từ để chỉ một giống tre hoặc chiếc kèn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箞', '{"9000": "8588.0", "Chữ Trung Quốc": "箞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箞 | tiền | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 箞 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm qiān. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiền\": cây trúc (竹) dài như ngàn (tiền = nghìn) sải tay — ống trúc kéo dài vô tận. | Gương Hán-Việt | \"tiền\" ít gặp với chữ này trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 箞 giúp nhận dạng chữ bộ 竹 hiếm gặp liên quan đến đồ dùng tre trong cổ thư.", "Tự nguyên_Xie": "箞 thuộc bộ 竹 (trúc). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Rui", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箞", "Unihan_Traditional (Chữ Phồn thể)": "箞", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "tiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ thanh tre làm rui đỡ mái nhà cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箤', '{"9000": "8589.0", "Chữ Trung Quốc": "箤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 箤 | nhốt | tượng hình | chữ bộ trúc (竹) chỉ hành động nhốt, giam giữ | 箤 thuộc bộ 竹 (trúc), Hán-Việt nhốt. Không có phân tích thành phần từ nguồn học thuật. Cấu trúc chưa xác định từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhốt\": cái chuồng tre (竹) dùng để nhốt (nhốt) gia súc — hình ảnh rào tre nhốt gà vịt. | Gương Hán-Việt | \"nhốt\" trong \"nhốt gà\", \"nhốt chuồng\" — giam giữ bằng rào tre | Mở khoá kiến thức | Biết 箤 giúp liên tưởng đến các từ Hán-Việt về giam giữ, nhốt trong văn bản nông nghiệp cổ.", "Tự nguyên_Xie": "箤 thuộc bộ 竹 (trúc), mang nghĩa liên quan đến giam nhốt — có thể gốc từ chuồng tre hay rào tre. Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhốt; như \"nhốt vào lồng\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箤", "Unihan_Traditional (Chữ Phồn thể)": "箤", "Pinyin_Xie": "zú", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này được dùng như một động từ chỉ hành động giam giữ sinh vật vào lồng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箷', '{"9000": "8590.0", "Chữ Trung Quốc": "箷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箷 | di | tượng hình | biến thể cổ của 椸 (giá treo áo) | 箷 là biến thể của 椸 (giá treo quần áo), thêm bộ 竹 (trúc), chỉ giá treo làm từ tre. Wiktionary xác nhận đây là dạng thay thế của 椸. Chữ hình thanh hay hội ý chưa được xác định rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": cái giá tre (竹) để di chuyển (di) quần áo từ nơi này sang nơi khác — giá treo áo bằng tre. | Gương Hán-Việt | \"di\" ít gặp với chữ này; dạng thông dụng là 椸 | Mở khoá kiến thức | Biết 箷 giúp nhận dạng đồ vật bằng tre trong cổ văn về nội thất gia đình.", "Tự nguyên_Xie": "箷 là dạng thay thế của 椸 (giá treo quần áo, yí/shī). Wiktionary ghi nhận đây là alt form của 椸. Có thể bộ 竹 được thêm vào để chỉ vật liệu tre. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 施", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮施", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "施", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箷", "Unihan_Traditional (Chữ Phồn thể)": "箷", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò là danh từ chỉ các tấm phên hoặc mành làm bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箹', '{"9000": "8591.0", "Chữ Trung Quốc": "箹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箹 | ước | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 箹 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm yuē/yào/chuò. Wiktionary ghi {{Han etym}} chưa triển khai. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ước\": cây trúc (竹) uốn khúc như ước hẹn (ước) — hình ảnh cần trúc cong như chữ ký cam kết. | Gương Hán-Việt | \"ước\" ít gặp với chữ này; liên quan đến đồ vật tre | Mở khoá kiến thức | Biết 箹 giúp nhận dạng chữ bộ 竹 hiếm gặp trong cổ thư âm nhạc hay đồ dùng.", "Tự nguyên_Xie": "箹 thuộc bộ 竹 (trúc), có nhiều âm đọc (yuē, yào, chuò). Wiktionary chưa triển khai gốc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "箹", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 約", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮約", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "約", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箹", "Unihan_Traditional (Chữ Phồn thể)": "箹", "Pinyin_Xie": "yuē", "Âm Hán Việt_Xie": "ước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này dùng làm danh từ chỉ dây buộc bằng tre hoặc động từ chỉ việc bó buộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箿', '{"9000": "8592.0", "Chữ Trung Quốc": "箿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 箿 | tập | tượng hình | đan mép đồ tre; bước đi lê sát đất | 箿 là chữ bộ 竹 (trúc), có hai nghĩa: (1) đan vành mép đồ vật bằng tre; (2) phương ngữ Mân Nam: đi với bước chân nhỏ lê sát đất. Wiktionary cung cấp định nghĩa cụ thể. Chưa có phân tích gốc chữ (lsCodes).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": bàn tay (竹 gợi que tre) tập (tập) đan từng vòng mép giỏ tre — công việc đan lát kiên nhẫn. | Gương Hán-Việt | \"tập\" ít gặp với chữ này; nghĩa liên quan đến đan tre | Mở khoá kiến thức | Biết 箿 giúp nhận dạng thuật ngữ thủ công tre nứa trong văn bản cổ về nghề đan lát.", "Tự nguyên_Xie": "箿 (jí) thuộc bộ 竹 (trúc). Wiktionary ghi hai nghĩa: (1) đan vành hoặc mép đồ vật bằng tre; (2) phương ngữ Tuyền Châu/Chương Châu: đi với bước nhỏ lê sát đất. Chưa có phân tích gốc chữ đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "箿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箿", "Unihan_Traditional (Chữ Phồn thể)": "箿", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường dùng làm động từ chỉ hành động lợp hoặc tu sửa mái nhà bằng tre lá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篜', '{"9000": "8593.0", "Chữ Trung Quốc": "篜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 篜 | chưng | tượng hình | chữ hiếm thuộc bộ trúc (竹), liên quan đến hấp chưng | 篜 thuộc bộ 竹 (trúc), phiên âm zhēng. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chưng\": rổ tre (竹) đặt lên nồi để chưng (chưng) hấp thức ăn — gợi hình ảnh xửng hấp bằng tre. | Gương Hán-Việt | \"chưng\" ít gặp với chữ này; liên quan đến dụng cụ hấp bằng tre | Mở khoá kiến thức | Biết 篜 giúp nhận dạng dụng cụ nấu ăn bằng tre trong cổ thư về ẩm thực.", "Tự nguyên_Xie": "篜 thuộc bộ 竹 (trúc). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tre", "Hạng Tần Suất (Jun Da)": "8593.0", "Tần Suất % (Jun Da)": "99.999742641", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 烝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮烝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "烝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篜", "Unihan_Traditional (Chữ Phồn thể)": "篜", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "trưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ một loại tre nhỏ hoặc củi tre trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簤', '{"9000": "8594.0", "Chữ Trung Quốc": "簤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簤 | đại | tượng hình | chữ hiếm thuộc bộ trúc (竹) | 簤 là chữ hiếm thuộc bộ 竹 (trúc), phiên âm dài. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đại\": vật bằng tre (竹) lớn, đại (đại) — gợi cây tre to lớn, đồ đựng lớn bằng tre. | Gương Hán-Việt | \"đại\" ít gặp với chữ này; liên quan đến đồ vật tre lớn | Mở khoá kiến thức | Biết 簤 giúp nhận dạng chữ bộ 竹 hiếm gặp trong văn bản về dụng cụ cổ.", "Tự nguyên_Xie": "簤 thuộc bộ 竹 (trúc). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 買", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮買", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "買", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簤", "Unihan_Traditional (Chữ Phồn thể)": "簤", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này đóng vai trò làm danh từ chỉ một loại sọt hoặc giỏ đan bằng tre. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簨', '{"9000": "8595.0", "Chữ Trung Quốc": "簨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 18 | nét | 簨 | tổn | tượng hình | thanh ngang của giá treo nhạc khí (chuông, trống) | 簨 thuộc bộ 竹 (trúc), phiên âm sǔn. Wiktionary ghi nhận nghĩa cụ thể: thanh ngang của giá treo nhạc khí. Chưa có phân tích gốc chữ rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tổn\": thanh trúc (竹) nằm ngang như xà nhà, chịu tổn (tổn — mang) sức nặng của chuông trống treo lên. | Gương Hán-Việt | \"tổn\" ít gặp với chữ này; liên quan đến nhạc khí cổ điển | Mở khoá kiến thức | Biết 簨 giúp hiểu văn bản cổ điển về nhạc lễ và thiết bị treo nhạc khí trong triều đình.", "Tự nguyên_Xie": "簨 (sǔn) chỉ thanh ngang nằm ngang trên giá treo nhạc khí (chuông, trống) trong thời cổ đại, thường làm bằng tre hoặc gỗ. Wiktionary ghi nhận định nghĩa này. Chưa có nguồn học thuật đầy đủ về gốc chữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái xà ngang để treo chuông khánh", "Hạng Tần Suất (Jun Da)": "8595.0", "Tần Suất % (Jun Da)": "99.9997441914", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 巽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮巽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簨", "Unihan_Traditional (Chữ Phồn thể)": "簨", "Pinyin_Xie": "sǔn", "Âm Hán Việt_Xie": "tuẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giá gỗ hoặc xà ngang dùng để treo nhạc cụ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簹', '{"9000": "8596.0", "Chữ Trung Quốc": "簹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 簹 | đang | tượng hình | tre cao; mui xe | 簹 thuộc bộ 竹 (trúc), phiên âm dāng/dàng. Wiktionary ghi hai nghĩa: (1) cây tre cao (dùng trong từ ghép như 篔簹); (2) mui xe. Chưa có phân tích gốc chữ rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đang\": cây trúc (竹) cao vút đang (đang) mọc thẳng — hình ảnh rừng trúc cao đang vươn lên trời. | Gương Hán-Việt | \"đang\" ít gặp với chữ này; xuất hiện trong 篔簹 (loài tre cao) | Mở khoá kiến thức | Biết 簹 giúp nhận dạng loài tre cao 篔簹 trong thơ văn Hán cổ điển.", "Tự nguyên_Xie": "簹 (dāng/dàng) thuộc bộ 竹 (trúc). Wiktionary ghi nhận hai nghĩa: cây tre cao (xuất hiện trong 篔簹, tên một loài tre cao); và mui che của xe. Chưa có nguồn học thuật đầy đủ về gốc chữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vân đương 篔簹,筼筜)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 當", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮當", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "當", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筜", "Unihan_Traditional (Chữ Phồn thể)": "簹", "Pinyin_Xie": "dāng", "Âm Hán Việt_Xie": "đang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp thành từ ghép vân đương để chỉ một loại tre thân lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粔', '{"9000": "8597.0", "Chữ Trung Quốc": "粔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 10 | nét | 粔 | cự | tượng hình | bánh làm từ bột gạo cuộn tròn thành vòng | 粔 thuộc bộ 米 (mễ, gạo), phiên âm jù. Wiktionary ghi rõ nghĩa: bánh làm từ bột gạo cuộn xoắn thành vòng tròn (ring-shaped rice cake). Chưa có phân tích cấu trúc thành phần rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": gạo (米) được cự (cự = lớn, xoắn lại) thành chiếc bánh vòng tròn to — bánh gạo cuộn hình khuyên. | Gương Hán-Việt | \"cự\" ít gặp với chữ này; liên quan đến bánh gạo cổ điển | Mở khoá kiến thức | Biết 粔 giúp nhận dạng từ ghép 粔籹 — loại bánh gạo truyền thống trong văn học Sở Từ.", "Tự nguyên_Xie": "粔 (jù) thuộc bộ 米 (mễ, gạo). Wiktionary ghi: bánh làm từ bột gạo xoắn thành hình vòng. Xuất hiện trong từ ghép 粔籹. Chưa có nguồn học thuật đầy đủ về gốc chữ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại thực phẩm thời xưa hình vòng xuyến, làm từ gạo", "Hạng Tần Suất (Jun Da)": "8597.0", "Tần Suất % (Jun Da)": "99.9997462585", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粔", "Unihan_Traditional (Chữ Phồn thể)": "粔", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bánh nếp hình vòng xuyến thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粸', '{"9000": "8598.0", "Chữ Trung Quốc": "粸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 粸 | kỳ | tượng hình | chữ hiếm thuộc bộ gạo (米) | 粸 là chữ hiếm thuộc bộ 米 (mễ, gạo), phiên âm qī. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": hạt gạo (米) kỳ (kỳ = lạ, đặc biệt) — loại gạo đặc biệt, kỳ lạ ít gặp. | Gương Hán-Việt | \"kỳ\" ít gặp với chữ này; liên quan đến lúa gạo | Mở khoá kiến thức | Biết 粸 giúp nhận dạng chữ bộ 米 hiếm gặp trong văn bản cổ về nông nghiệp hay thực phẩm.", "Tự nguyên_Xie": "粸 thuộc bộ 米 (mễ, gạo). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "粸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粸", "Unihan_Traditional (Chữ Phồn thể)": "粸", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bánh làm từ bột gạo hoặc bột nếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綄', '{"9000": "8599.0", "Chữ Trung Quốc": "綄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綄 | hoãn | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 綄 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm huǎn/wàn. Wiktionary ghi {{Han etym}} chưa triển khai. Nghĩa chưa xác định. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoãn\": sợi tơ (糸) hoãn lại (hoãn = chậm, trì hoãn) — như sợi chỉ kéo dài mãi không dứt. | Gương Hán-Việt | \"hoãn\" ít gặp với chữ này; liên quan đến sợi vải | Mở khoá kiến thức | Biết 綄 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "綄 thuộc bộ 糸 (mịch, tơ sợi). Wiktionary ghi {{Han etym}} chưa triển khai, nghĩa chưa được xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綄", "Unihan_Traditional (Chữ Phồn thể)": "綄", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này là từ cổ, chủ yếu làm động từ trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綊', '{"9000": "8600.0", "Chữ Trung Quốc": "綊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綊 | hiệp | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 綊 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm xié. Wiktionary ghi {{Han etym}} chưa triển khai. Nghĩa chưa xác định. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\": sợi tơ (糸) kết hiệp (hiệp = hợp lại) nhiều sợi thành một — liên tưởng đến sợi dây nhiều tao bện lại. | Gương Hán-Việt | \"hiệp\" ít gặp với chữ này; liên quan đến sợi vải | Mở khoá kiến thức | Biết 綊 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "綊 thuộc bộ 糸 (mịch, tơ sợi), phiên âm xié. Wiktionary chưa triển khai gốc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綊", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 夾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹夾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綊", "Unihan_Traditional (Chữ Phồn thể)": "綊", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loại áo mặc bên trong thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綒', '{"9000": "8601.0", "Chữ Trung Quốc": "綒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綒 | phục | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 綒 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm fú. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": sợi tơ (糸) phục (phục = phủ phục, bao phủ) — gợi vải lụa trải phủ, bao bọc mềm mại. | Gương Hán-Việt | \"phục\" ít gặp với chữ này; liên quan đến sợi vải | Mở khoá kiến thức | Biết 綒 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "綒 thuộc bộ 糸 (mịch, tơ sợi). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "綒", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綒", "Unihan_Traditional (Chữ Phồn thể)": "綒", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động quấn hoặc buộc dây. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綔', '{"9000": "8602.0", "Chữ Trung Quốc": "綔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綔 | hồ | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 綔 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm hū. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": sợi tơ (糸) hồ (hồ = hồ dán) để cố định vải — gợi hình ảnh hồ bột dán vải cho cứng. | Gương Hán-Việt | \"hồ\" ít gặp với chữ này; liên quan đến sợi vải | Mở khoá kiến thức | Biết 綔 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "綔 thuộc bộ 糸 (mịch, tơ sợi). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "甔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "夸 + 系", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夸系", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "系", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夸", "Unihan_Simplified (Chữ Giản thể)": "綔", "Unihan_Traditional (Chữ Phồn thể)": "綔", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ chỉ một loại bình đất nung thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('綗', '{"9000": "8603.0", "Chữ Trung Quốc": "綗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 綗 | huỳnh | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 綗 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm jiǒng. Không có phân tích thành phần từ nguồn học thuật. Chưa có nguồn học thuật xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huỳnh\": sợi tơ (糸) sáng huỳnh (huỳnh = ánh sáng, lửa đom đóm) — gợi sợi lụa bóng ánh lên như ánh đom đóm. | Gương Hán-Việt | \"huỳnh\" ít gặp với chữ này; liên quan đến vải sáng bóng | Mở khoá kiến thức | Biết 綗 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "綗 thuộc bộ 糸 (mịch, tơ sợi). Không có gốc chữ từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên loại vải)", "Hạng Tần Suất (Jun Da)": "8603.0", "Tần Suất % (Jun Da)": "99.9997524599", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 冏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹冏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "綗", "Unihan_Traditional (Chữ Phồn thể)": "綗", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "cửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại vải dệt thưa hoặc lưới mỏng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緰', '{"9000": "8604.0", "Chữ Trung Quốc": "緰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緰 | du | tượng hình | chữ hiếm thuộc bộ tơ sợi (糸) | 緰 là chữ hiếm thuộc bộ 糸 (mịch, tơ sợi), phiên âm yú. Wiktionary ghi {{Han etym}} chưa triển khai. Nghĩa chưa xác định. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": sợi tơ (糸) du (du = du lịch, trôi nổi) — gợi hình ảnh sợi tơ nhẹ nhàng trôi theo gió. | Gương Hán-Việt | \"du\" ít gặp với chữ này; liên quan đến sợi vải | Mở khoá kiến thức | Biết 緰 giúp nhận dạng chữ bộ 糸 hiếm gặp trong văn bản cổ về dệt vải.", "Tự nguyên_Xie": "緰 thuộc bộ 糸 (mịch, tơ sợi), phiên âm yú. Wiktionary chưa triển khai gốc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "簰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "𦈕", "Unihan_Traditional (Chữ Phồn thể)": "緰", "Pinyin_Xie": "tóu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại vải lụa mỏng mịn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繜', '{"9000": "8605.0", "Chữ Trung Quốc": "繜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 糸 | mịch | biểu nghĩa | tơ lụa | 尊 | tôn | biểu âm | tôn kính | 繜 = 糸 (Mịch, biểu nghĩa: tơ lụa) + 尊 (Tôn, biểu âm); chữ hình thanh. Phần 糸 chỉ chất liệu liên quan tơ lụa, phần 尊 cho âm đọc zūn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định (âm Hán cổ *tsun): tưởng tượng sợi tơ (糸) được tôn trọng (尊) quấn quanh vật quý. | Gương Hán-Việt | 繜 chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 繜 giúp nhận diện chữ hiếm trong văn bản cổ về dệt lụa.", "Tự nguyên_Xie": "Theo Wiktionary: 繜 là chữ hình thanh, gồm 糸 (biểu nghĩa: tơ lụa) và 尊 (biểu âm). Chữ hiếm dùng, định nghĩa chưa được xác lập rõ trong từ điển hiện đại. chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "繜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 尊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹尊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繜", "Unihan_Traditional (Chữ Phồn thể)": "繜", "Pinyin_Xie": "zūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ loại quần mặc sát người hoặc làm động từ chỉ sự bó buộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繝', '{"9000": "8606.0", "Chữ Trung Quốc": "繝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 18 | nét | 繝 | tượng hình | chữ hiếm thuộc bộ 糸, cấu trúc chưa phân tích được | 繝 là chữ hiếm thuộc bộ 糸, cấu trúc nội tại chưa có phân tích hình thanh/hội ý rõ ràng trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định (âm jiàn): chữ hiếm trong nhóm 糸 — hình dung sợi tơ bện phức tạp. | Gương Hán-Việt | 繝 chưa có từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 繝 giúp nhận diện chữ hiếm trong văn bản dệt cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 繝. Chữ thuộc bộ 糸 (tơ lụa), âm đọc jiàn. Chưa có nguồn học thuật xác nhận cấu trúc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "睝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 閒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹閒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繝", "Unihan_Traditional (Chữ Phồn thể)": "繝", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ loại lụa dệt nhiều màu hoặc tính từ chỉ họa tiết sặc sỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罃', '{"9000": "8607.0", "Chữ Trung Quốc": "罃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 缶 | Số nét | 16 | nét | 罃 | anh | tượng hình | bình đựng rượu hình thuôn, cổ nhỏ | 罃 là dị thể của 罌 (anh — bình rượu). Không có phân tích hình thanh/hội ý rõ ràng cho dạng chữ này; thuộc bộ 缶 (đồ gốm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": chữ 罃 hình dạng như chiếc bình (罌) — cổ nhỏ, bụng to đựng rượu quý. | Gương Hán-Việt | 罃 là dị thể ít gặp; dạng thông dụng hơn là 罌 trong \"anh túc\" (thuốc phiện) | Mở khoá kiến thức | Biết 罃 giúp nhận dạng nhóm chữ chỉ đồ gốm cổ như 罌, 缶, 罄.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 罃 là dị thể cổ của 罌, đều chỉ loại bình đựng rượu có cổ nhỏ, bụng phình. Chữ tạo muộn, hình Tiểu triện còn lưu. Chưa có phân tích glyph origin chi tiết cho dạng 罃. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phong", "Hạng Tần Suất (Jun Da)": "8607.0", "Tần Suất % (Jun Da)": "99.9997591781", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 缶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱缶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "罃", "Unihan_Traditional (Chữ Phồn thể)": "罃", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ để chỉ các loại bình hoặc vò đất nung thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罝', '{"9000": "8608.0", "Chữ Trung Quốc": "罝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 10 | nét | 网 | võng | biểu nghĩa | lưới | 且 | thả | biểu âm | cho âm jū | 罝 = 网 (Võng, biểu nghĩa: lưới) + 且 (Thả, biểu âm); chữ hình thanh. Phần 网 chỉ loại công cụ lưới, phần 且 cho âm jū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt chưa xác định (âm Hán cổ *klja): lưới (网) giăng ra để bẫy — công cụ săn bắt thỏ trong rừng. | Gương Hán-Việt | 罝 ít dùng trong tiếng Việt; xuất hiện trong văn thơ cổ Kinh Thi | Mở khoá kiến thức | Biết 罝 giúp đọc thơ Kinh Thi (兔罝 — lưới bắt thỏ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 罝 là chữ hình thanh, gồm 网 (biểu nghĩa: lưới) và 且 (biểu âm). Nghĩa gốc là loại lưới dùng bắt thỏ rừng; mở rộng sang bắt các loài thú nói chung và hành động dùng lưới bẫy thú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lưới bắt thỏ rừng", "Hạng Tần Suất (Jun Da)": "8608.0", "Tần Suất % (Jun Da)": "99.9997596949", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罝", "Unihan_Traditional (Chữ Phồn thể)": "罝", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau động từ chỉ hành động giăng lưới săn bắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羴', '{"9000": "8609.0", "Chữ Trung Quốc": "羴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 18 | nét | 羊 | dương | biểu nghĩa | con dê/cừu — ba lần | 羊 | dương | biểu nghĩa | ba chữ 羊 ghép lại | 羊 | dương | biểu nghĩa | hội ý: mùi tanh của nhiều con dê | 羴 là chữ hội ý, ghép ba chữ 羊 (Dương — con dê/cừu) lại với nhau, theo cách tạo chữ từ ba phần giống nhau (triệt tự). Ba con dê tập hợp tạo nên mùi hôi tanh đặc trưng của dê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": ba con dê (羊羊羊) tụ lại — mùi hôi tanh không thể chịu được. | Gương Hán-Việt | 羴 là dị thể của 膻 (thiên), ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 羴 giúp nhận dạng nhóm chữ triệt (ba phần) như 森, 晶, 品.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 羴 được tạo bằng cách ghép ba 羊, theo kiểu chữ triệt (ba phần giống nhau). Nghĩa chỉ mùi hôi tanh của dê cừu. Tiểu triện xác nhận cấu trúc ba 羊. Đây là dị thể của 膻 (thiên — mùi tanh dê). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "羴", "Hạng Tần Suất (Jun Da)": "5581.0", "Tần Suất % (Jun Da)": "99.9644916934", "GavinGrover_Once (Chiết tự trực tiếp)": "羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "膻", "Unihan_Traditional (Chữ Phồn thể)": "羴", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "thiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả mùi hôi tanh đặc trưng của thịt dê cừu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翢', '{"9000": "8610.0", "Chữ Trung Quốc": "翢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 翢 | đảo | tượng hình | chữ hiếm thuộc bộ 羽, cấu trúc chưa phân tích được | 翢 là chữ hiếm thuộc bộ 羽 (lông vũ), âm dào. Cấu trúc nội tại chưa có phân tích hình thanh/hội ý trong nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảo\": chữ hiếm trong nhóm lông vũ (羽) — hình dung chiếc lông chim xoay vòng như đảo lộn. | Gương Hán-Việt | 翢 chưa có từ Hán-Việt thông dụng trong tiếng Việt | Mở khoá kiến thức | Biết 翢 giúp nhận diện chữ hiếm trong văn bản cổ về chim và lông vũ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm đọc dào, không có glyphorigin hay định nghĩa rõ ràng cho 翢. Chữ thuộc bộ 羽, nghĩa chưa xác định. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "碢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "周 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰周羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翢", "Unihan_Traditional (Chữ Phồn thể)": "翢", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong văn học cổ để chỉ các loại trang sức bằng lông chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聡', '{"9000": "8611.0", "Chữ Trung Quốc": "聡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 14 | nét | 聡 | thông | tượng hình | dị thể Nhật của 聰 — thông minh, tai thính | 聡 là dị thể Nhật (Shinjitai) của 聰 (thông — thông minh, tai thính). Cấu trúc đơn giản hóa, không phân tích riêng được như 聰 (耳 + 悤).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thông\": chữ 聡 — tai (耳) nhạy bén, đầu óc thông tuệ, nắm bắt mọi thứ. | Gương Hán-Việt | 聡 là dị thể Nhật; dạng tiếng Việt thông dụng là 聰 trong \"thông minh\" | Mở khoá kiến thức | Biết 聡 giúp đọc tên người Nhật và văn bản Nhật Hán tự.", "Tự nguyên_Xie": "聡 là dạng chữ Nhật giản hóa của 聰. Không có Wiktionary glyph origin riêng cho 聡. Chữ 聰 gốc gồm 耳 (nhĩ — tai) và 悤 (biểu âm), chỉ người tai thính, thông minh. chưa có nguồn học thuật riêng cho dạng 聡. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衡", "Hạng Tần Suất (Jun Da)": "8611.0", "Tần Suất % (Jun Da)": "99.9997617621", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 忩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳忩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聡", "Unihan_Traditional (Chữ Phồn thể)": "聡", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả sự nhạy bén của các giác quan hoặc trí tuệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聻', '{"9000": "8612.0", "Chữ Trung Quốc": "聻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 20 | nét | 聻 | nễ | tượng hình | chữ cổ chỉ hồn ma người chết | 聻 là chữ thuộc bộ 耳, âm nǐ/jiàn. Cấu trúc nội tại không có phân tích hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nễ\": chữ 聻 — tai nghe tiếng từ cõi âm, chỉ hồn ma người khuất. | Gương Hán-Việt | 聻 ít dùng trong tiếng Việt; chỉ gặp trong văn bản cổ về tín ngưỡng | Mở khoá kiến thức | Biết 聻 giúp đọc văn bản cổ về âm hồn và tín ngưỡng dân gian Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary: 聻 là chữ cổ (废弃字) chỉ hồn ma của người đã chết. Thuộc bộ 耳. Không có glyph origin rõ ràng. Nghĩa này phản ánh tín ngưỡng cổ đại Trung Hoa về âm hồn. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軻", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "漸 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱漸耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "漸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聻", "Unihan_Traditional (Chữ Phồn thể)": "聻", "Pinyin_Xie": "nǐ", "Âm Hán Việt_Xie": "nễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các văn bản cổ liên quan đến tín ngưỡng dân gian và trừ tà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脕', '{"9000": "8613.0", "Chữ Trung Quốc": "脕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脕 | uyển | tượng hình | chữ hiếm thuộc bộ 肉, âm wàn/wǎn, nghĩa chưa xác định | 脕 là chữ hiếm thuộc bộ 肉 (thịt), âm wàn. Cấu trúc nội tại chưa có phân tích hình thanh/hội ý rõ ràng trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": chữ hiếm trong nhóm thịt (肉) — hình dung phần cổ tay (腕) gần với nghĩa âm đọc. | Gương Hán-Việt | 脕 ít dùng; có thể liên hệ với 腕 (uyển — cổ tay) | Mở khoá kiến thức | Biết 脕 giúp nhận diện nhóm chữ hiếm thuộc bộ 肉 trong văn bản y học cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 脕 thuộc bộ 肉, âm wǎn/wèn/wàn. Không có định nghĩa hay glyph origin cụ thể. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Ồ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脕", "Unihan_Traditional (Chữ Phồn thể)": "脕", "Pinyin_Xie": "wàn", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả vẻ đẹp mềm mại và láng mịn của làn da. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脟', '{"9000": "8614.0", "Chữ Trung Quốc": "脟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脟 | luyến | tượng hình | chữ cổ thuộc bộ 肉, dạng dị thể của 脔 (miếng thịt nhỏ) | 脟 là chữ cổ thuộc bộ 肉, có thể liên hệ với 脔 (luyến — miếng thịt nhỏ). Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luyến\": chữ cổ nhóm thịt (肉) — gợi hình ảnh miếng thịt nhỏ được cắt ra. | Gương Hán-Việt | 脟 ít dùng; dị thể của 脔 (luyến — miếng thịt nhỏ) | Mở khoá kiến thức | Biết 脟 giúp đọc văn bản cổ về ẩm thực và nghi lễ tế tự.", "Tự nguyên_Xie": "Tiểu triện | Không tìm thấy glyph origin từ Wiktionary cho 脟. Nghĩa ghi là xem 脔 (liè — miếng thịt cắt nhỏ). Có hình Tiểu triện (nguồn hanziyuan). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xem \"脔\"", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脟", "Unihan_Traditional (Chữ Phồn thể)": "脟", "Pinyin_Xie": "liè", "Âm Hán Việt_Xie": "liệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể dùng làm danh từ chỉ miếng thịt hoặc động từ chỉ hành động thái thịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脳', '{"9000": "8615.0", "Chữ Trung Quốc": "脳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | 脳 | não | tượng hình | dị thể Nhật của 腦 — não, óc | 脳 là dị thể Nhật (Shinjitai) của 腦 (não — não bộ). Không có cấu trúc hình thanh/hội ý riêng; dạng gốc 腦 gồm 囟 (thóp đầu) và 𠃜.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"não\": dị thể Nhật của 腦 — bộ óc điều khiển mọi hoạt động của cơ thể. | Gương Hán-Việt | 脳 là dị thể Nhật; dạng Việt thông dụng là 腦 trong \"não bộ\", \"đại não\" | Mở khoá kiến thức | Biết 脳 giúp đọc tên khoa học Nhật-Hán về thần kinh học và y học.", "Tự nguyên_Xie": "脳 là dạng chữ Nhật giản hóa của 腦. Không có Wiktionary glyph origin riêng cho 脳. Chữ 腦 gốc có 囟 (thóp đầu trẻ em) chỉ phần đầu não. chưa có nguồn học thuật riêng cho dạng 脳. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "脳", "Hạng Tần Suất (Jun Da)": "8615.0", "Tần Suất % (Jun Da)": "99.9997648628", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "脳", "Unihan_Traditional (Chữ Phồn thể)": "脳", "Pinyin_Xie": "nao", "Âm Hán Việt_Xie": "não", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận cơ thể hoặc làm tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脽', '{"9000": "8616.0", "Chữ Trung Quốc": "脽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 脽 | thuỳ | tượng hình | chữ hiếm thuộc bộ 肉, âm shuí, nghĩa chưa rõ | 脽 là chữ hiếm thuộc bộ 肉, âm shuí. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuỳ\": chữ hiếm trong nhóm thịt (肉) — âm shuí gần giống 水 (nước). | Gương Hán-Việt | 脽 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 脽 giúp nhận diện nhóm chữ hiếm thuộc bộ 肉 trong văn bản y học cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm shuí cho 脽, không có glyphorigin hay định nghĩa rõ ràng. Nghĩa tiếng Việt ghi là \"đồ chua\" nhưng thiếu xác nhận học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ chua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脽", "Unihan_Traditional (Chữ Phồn thể)": "脽", "Pinyin_Xie": "shuí", "Âm Hán Việt_Xie": "thuỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ phần mông của người hoặc phần phao câu của gia cầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脿', '{"9000": "8617.0", "Chữ Trung Quốc": "脿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt — chất liệu cơ thể | 表 | biểu | biểu âm | bề ngoài — cho âm biāo/béo | 脿 = 肉/⺼ (Nhục, biểu nghĩa: thịt) + 表 (Biểu, biểu âm); chữ hình thanh. Đây là chữ Nôm cho nghĩa \"béo\", phần ⺼ chỉ thịt/cơ thể, phần 表 cho âm béo trong tiếng Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"béo\": thịt (⺼) bày ra bên ngoài (表) — người béo thì thịt lộ ra ngoài. | Gương Hán-Việt | 脿 là chữ Nôm thuần Việt, không có từ Hán-Việt gốc Trung Quốc | Mở khoá kiến thức | Biết 脿 giúp đọc văn bản Nôm miêu tả ngoại hình con người và thức ăn.", "Tự nguyên_Xie": "Theo Wiktionary: 脿 là chữ Nôm hình thanh, gồm ⺼ (biểu nghĩa: thịt) và 表 (biểu âm, âm Hán-Việt \"biểu\" gần với âm Nôm \"béo\"). Đây là chữ Nôm tự tạo để ghi từ thuần Việt \"béo\" (mập, nhiều mỡ). Không xuất hiện trong Hán tự Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "béo; như \"béo tròn; béo bở\" (vhn)", "Hạng Tần Suất (Jun Da)": "8617.0", "Tần Suất % (Jun Da)": "99.9997658963", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 表", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月表", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "表", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脿", "Unihan_Traditional (Chữ Phồn thể)": "脿", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "biểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái cơ thể béo tốt của con người hoặc gia súc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臈', '{"9000": "8618.0", "Chữ Trung Quốc": "臈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | ⺼ | nhục | biểu nghĩa | thịt — liên quan đến lễ vật thịt | 葛 | cát | biểu âm | cây sắn dây — cho âm là/lạp | 臈 = ⺼ (Nhục, biểu nghĩa: thịt) + 葛 (Cát, biểu âm); chữ hình thanh. Phần ⺼ gợi lễ vật thịt trong nghi lễ cuối năm, phần 葛 cho âm là.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạp\": thịt (⺼) dâng lên trong lễ cuối năm — ngày Lạp Bát (8/12 âm lịch) cúng tổ tiên. | Gương Hán-Việt | 臈 trong \"lạp nhục\" (thịt muối phơi khô dịp tết), \"tháng lạp\" (tháng 12 âm lịch) | Mở khoá kiến thức | Biết 臈 (lạp) mở khoá: 臘月 (lạp nguyệt — tháng 12), 臘肉 (lạp nhục — thịt muối), 臘八 (lễ Lạp Bát).", "Tự nguyên_Xie": "Theo Wiktionary: 臈 là chữ hình thanh, gồm ⺼ (biểu nghĩa: thịt) và 葛 (biểu âm). Nghĩa là ngày lễ tất niên (lễ Lạp — ngày 8 tháng 12 âm lịch), ngày xưa dùng thịt làm lễ vật tế thần. Dị thể của 臘 (lạp). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày lễ tất niên", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 葛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月葛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "葛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臈", "Unihan_Traditional (Chữ Phồn thể)": "臈", "Pinyin_Xie": "là", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ thời gian cuối năm âm lịch hoặc các ngày lễ cúng tế cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艑', '{"9000": "8619.0", "Chữ Trung Quốc": "艑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 15 | nét | 艑 | biện | tượng hình | chữ hiếm thuộc bộ 舟, chỉ thuyền nhỏ | 艑 là chữ hiếm thuộc bộ 舟 (thuyền), âm biàn, nghĩa là thuyền nhỏ. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": chữ hiếm nhóm thuyền (舟) — chiếc thuyền nhỏ lướt theo dòng. | Gương Hán-Việt | 艑 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 艑 giúp nhận diện nhóm chữ hiếm thuộc bộ 舟 trong văn bản hàng hải cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 艑. Nghĩa ghi là thuyền nhỏ (thuyền con). Thuộc bộ 舟. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuyền con", "Hạng Tần Suất (Jun Da)": "8619.0", "Tần Suất % (Jun Da)": "99.9997669299", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艑", "Unihan_Traditional (Chữ Phồn thể)": "艑", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại thuyền nhỏ dùng để di chuyển trên sông ngòi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艢', '{"9000": "8620.0", "Chữ Trung Quốc": "艢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 19 | nét | 艢 | tường | tượng hình | cột buồm tàu thuyền | 艢 là chữ hiếm thuộc bộ 舟, chỉ cột buồm của tàu thuyền. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\": chữ hiếm nhóm thuyền (舟) — hình dung chiếc cột buồm vươn cao trên mặt biển. | Gương Hán-Việt | 艢 ít dùng trong tiếng Việt; liên hệ với 桅 (cột buồm) | Mở khoá kiến thức | Biết 艢 giúp nhận diện nhóm chữ hiếm về trang bị tàu thuyền cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 艢. Nghĩa là cột buồm (帆柱) hoặc cần cẩu trên tàu thuyền. Thuộc bộ 舟. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cột buồm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 嗇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟嗇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嗇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艢", "Unihan_Traditional (Chữ Phồn thể)": "艢", "Pinyin_Xie": "qiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong văn thơ cổ để miêu tả cột buồm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茻', '{"9000": "8621.0", "Chữ Trung Quốc": "茻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | tháo | biểu nghĩa | cỏ | 艸 | tháo | biểu nghĩa | cỏ — hai lần, thành bốn 屮 | 茻 là chữ hội ý, ghép hai 艸 (hay bốn 屮) với nhau, biểu thị đám cỏ rậm rạp. Sách Thuyết Văn Giải Tự giải thích: \"茻: 眾艸也\" (茻: nhiều cỏ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": bốn cây cỏ (屮屮屮屮) mọc um tùm — đám cỏ rậm không thể đi qua được. | Gương Hán-Việt | 茻 ít dùng trong tiếng Việt; liên hệ với 莽 (mãng — rậm rạp, bộc trực) | Mở khoá kiến thức | Biết 茻 giúp hiểu gốc của 莽 (mãng — rừng rậm, người thô lỗ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary và Thuyết Văn: 茻 là chữ hội ý, gồm bốn 屮 (cỏ non), biểu thị đám cỏ rậm rạp, nhiều cỏ mọc chen nhau. Cách đọc giống 冈. Tiểu triện xác nhận cấu trúc bốn 屮. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loài cỏ", "Hạng Tần Suất (Jun Da)": "8621.0", "Tần Suất % (Jun Da)": "99.999768997", "GavinGrover_Once (Chiết tự trực tiếp)": "屮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴屮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "茻", "Unihan_Traditional (Chữ Phồn thể)": "茻", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ thảm cỏ rậm rạp hoặc bụi cây thấp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菐', '{"9000": "8622.0", "Chữ Trung Quốc": "菐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 丵 | trác | biểu nghĩa | cây gai mọc rậm | 廾 | trấp | biểu nghĩa | hai tay — hành động | 菐 = 丵 (biểu nghĩa: bụi gai) + 廾 (biểu nghĩa: hai tay); chữ hội ý (hoặc hình thanh tùy phân tích). Shuowen phân tích theo cả hội ý và hình thanh. Hình ảnh hai tay vật lộn với bụi gai rậm rạp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": hai tay (廾) vật lộn với bụi gai (丵) — hình ảnh người bộc lộ sức lực trong đám cây rậm. | Gương Hán-Việt | 菐 ít dùng độc lập; thành phần tạo nên chữ 僕 (bộc — người hầu) | Mở khoá kiến thức | Biết 菐 giúp hiểu nguồn gốc chữ 僕 (bộc — người hầu, đầy tớ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: Shuowen Jiezi phân tích 菐 gồm 丵 (biểu nghĩa/âm) và 廾 (biểu âm/nghĩa), là một chữ cổ chỉ bụi rậm. Xem thêm phân tích tại 僕. Nghĩa gốc là bụi cây rậm (thicket). Tiểu triện còn lưu hình. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1174.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trác (1173) Đại (029)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trác (số 1173 - bụi cỏ rậm) ở trên chữ Đại (số 029 - to lớn - thực ra là bộ Củng 廾 viết biến dạng). Bụi cỏ mọc cao lớn um tùm. Giải thích sự chuyển ý: Đây là chữ Hội ý. Bộc là bụi cây cỏ mọc đã cao lớn rậm rạp.", "Nghĩa Tiếng Việt_Xie": "tẻ nhạt; cây dày", "Hạng Tần Suất (Jun Da)": "8622.0", "Tần Suất % (Jun Da)": "99.9997700306", "GavinGrover_Once (Chiết tự trực tiếp)": "业 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱业", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "菐", "Unihan_Traditional (Chữ Phồn thể)": "菐", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong chữ Hán cổ để miêu tả trạng thái rậm rạp hoặc phiền toái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菓', '{"9000": "8623.0", "Chữ Trung Quốc": "菓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | tháo | biểu nghĩa | cỏ cây, thực vật | 果 | quả | biểu âm | quả, kết quả | 菓 = 艹 (Tháo, biểu nghĩa: thực vật) + 果 (Quả, biểu âm); chữ hình thanh. Phần 艹 chỉ nguồn gốc thực vật, phần 果 cho âm và gợi nghĩa quả cây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": cây (艹) cho ra quả (果) — chữ 菓 như thêm bộ cây lên trên quả để nhấn mạnh đây là trái cây thực vật. | Gương Hán-Việt | 菓 là dị thể của 果 (quả); từ thông dụng: 果物 (quả vật — trái cây, tiếng Nhật) | Mở khoá kiến thức | Biết 菓 giúp đọc nhãn hiệu và tên tiệm bánh kẹo tiếng Nhật (菓子 — kẹo, bánh).", "Tự nguyên_Xie": "Theo Wiktionary: 菓 là dị thể của 果 (quả), gồm 艹 (biểu nghĩa: cỏ/cây) và 果 (biểu âm). Nghĩa là quả, trái cây — giống 果 nhưng thêm bộ 艹 nhấn mạnh nguồn gốc thực vật. Chữ tạo muộn, ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả, trái; quả nhiên; kết quả; nếu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菓", "Unihan_Traditional (Chữ Phồn thể)": "菓", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại trái cây hoặc kết quả, là dạng cổ của chữ 果. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菙', '{"9000": "8624.0", "Chữ Trung Quốc": "菙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菙 | chùy | tượng hình | loài cây cổ chưa xác định, thuộc bộ 艸 | 菙 là chữ hiếm thuộc bộ 艸 (cỏ cây), âm chuí, chỉ một loài cây nhắc đến trong sách cổ nhưng chưa xác định được loài cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chùy\": chữ hiếm trong nhóm cỏ cây (艸) — âm chuí gợi hình chiếc dùi (槌). | Gương Hán-Việt | 菙 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 菙 giúp nhận diện chữ hiếm về tên cây cỏ trong văn bản thực vật học cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 菙. Nghĩa ghi là một loại cây nhắc trong sách cổ. Thuộc bộ 艸. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cây nói trong sách cổ)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菙", "Unihan_Traditional (Chữ Phồn thể)": "菙", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn bản cổ để chỉ một loại cây dùng làm roi hoặc chính cái roi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菚', '{"9000": "8625.0", "Chữ Trung Quốc": "菚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菚 | chiếm | tượng hình | chữ hiếm thuộc bộ 艸, nghĩa chưa xác định | 菚 là chữ hiếm thuộc bộ 艸, âm zhàn. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiếm\": chữ hiếm trong nhóm cỏ cây (艸) — nghĩa chưa xác định. | Gương Hán-Việt | 菚 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 菚 giúp nhận diện chữ hiếm về tên cây cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 菚. Thuộc bộ 艸, âm zhàn. Nghĩa ghi là 蚚 (cũng hiếm gặp). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蚚", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 戔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹戔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菚", "Unihan_Traditional (Chữ Phồn thể)": "菚", "Pinyin_Xie": "zhàn", "Âm Hán Việt_Xie": "chiếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu làm danh từ trong thư tịch cổ để chỉ một loài thực vật cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菣', '{"9000": "8626.0", "Chữ Trung Quốc": "菣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菣 | khẩn | tượng hình | loai cay thuoc bo 艸, ten co cua Artemisia annua (thanh hao) | 菣 la chu hiem thuoc bo 艸, am qin, chi cay thanh hao (Artemisia annua).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩn\": chữ hiếm trong nhóm cỏ (艸) — chỉ cây thanh hao quý dùng làm thuốc chữa sốt. | Gương Hán-Việt | 菣 la ten co cua thanh hao trong y hoc co | Mở khoá kiến thức | Biet 菣 giup doc van ban y hoc co Trung Hoa ve duoc thao.", "Tự nguyên_Xie": "Theo Wiktionary: 菣 la ten co cua 青蒿 (thanh hao), loai cay dung lam thuoc. Chu co bi thay the boi 青蒿. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Artemisia apiacea", "Hạng Tần Suất (Jun Da)": "8626.0", "Tần Suất % (Jun Da)": "99.9997720978", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 臤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹臤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菣", "Unihan_Traditional (Chữ Phồn thể)": "菣", "Pinyin_Xie": "qìn", "Âm Hán Việt_Xie": "khẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại cây thân thảo thuộc họ cúc dùng làm thuốc trong Đông y. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菦', '{"9000": "8627.0", "Chữ Trung Quốc": "菦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 菦 | cần | tượng hình | chữ hiếm thuộc bộ 艸, âm qín | 菦 là chữ hiếm thuộc bộ 艸, âm qín. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cần\": chữ hiếm nhóm cỏ cây (艸) — gợi hình ảnh thân cây cứng chắc. | Gương Hán-Việt | 菦 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 菦 giúp nhận diện chữ hiếm về tên thực vật trong văn bản cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 菦. Thuộc bộ 艸, âm qín. Nghĩa ghi là 榦 (thân cây). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "榦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 近", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹近", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "近", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菦", "Unihan_Traditional (Chữ Phồn thể)": "菦", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loại rau cần trong văn bản cổ, tương đương với chữ 芹 ngày nay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菨', '{"9000": "8628.0", "Chữ Trung Quốc": "菨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 菨 | tiết | tượng hình | chữ hiếm thuộc bộ 艸, âm jiē | 菨 là chữ hiếm thuộc bộ 艸, âm jiē. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": chữ hiếm nhóm cỏ cây (艸) — gợi hình ảnh cây cỏ trong sạch, liêm khiết như tiết tháo. | Gương Hán-Việt | 菨 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 菨 giúp nhận diện nhóm chữ hiếm về đức hạnh và tên thực vật cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 菨. Thuộc bộ 艸, âm jiē. Nghĩa ghi là thanh liêm, liêm khiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thanh liêm; liêm khiết; thanh bạch", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 妾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹妾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菨", "Unihan_Traditional (Chữ Phồn thể)": "菨", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ một loại cỏ nước hoặc làm tính từ chỉ phẩm chất thanh cao, liêm khiết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葔', '{"9000": "8629.0", "Chữ Trung Quốc": "葔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葔 | hầu | tượng hình | chữ cổ thuộc bộ 艸, chỉ dùng trong từ 薃葔 | 葔 là chữ hiếm thuộc bộ 艸, âm hóu, chỉ dùng trong từ ghép 薃葔 (một loại thực vật cổ). Không có phân tích cấu trúc riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hầu\": chữ hiếm nhóm cỏ (艸) — chỉ dùng trong từ ghép 薃葔, gợi hình ảnh loài cỏ nước cổ. | Gương Hán-Việt | 葔 ít dùng trong tiếng Việt; chỉ gặp trong nghiên cứu thực vật học cổ | Mở khoá kiến thức | Biết 葔 giúp đọc tên thực vật trong Nhĩ Nhã và các từ điển cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 葔 chỉ xuất hiện trong từ 薃葔, không có định nghĩa độc lập. Thuộc bộ 艸. Không có glyph origin chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 侯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹侯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葔", "Unihan_Traditional (Chữ Phồn thể)": "葔", "Pinyin_Xie": "hóu", "Âm Hán Việt_Xie": "hầu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ để chỉ một loại thực vật cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葠', '{"9000": "8630.0", "Chữ Trung Quốc": "葠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葠 | sâm | tượng hình | cây sâm — loài dược thảo quý, lá như bàn tay | 葠 là dị thể của 蔘/參 (sâm), thuộc bộ 艸, chỉ cây nhân sâm. Không có phân tích cấu trúc hình thanh/hội ý riêng cho dạng 葠.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sâm\": chữ 葠 là dị thể cổ của sâm — loài cây dược quý nhất Đông y, lá xòe như bàn tay năm ngón. | Gương Hán-Việt | 葠 là dị thể của 蔘/參 trong \"nhân sâm\", \"hồng sâm\", \"sâm tươi\" | Mở khoá kiến thức | Biết 葠 giúp nhận dạng dị thể của chữ sâm trong văn bản y học cổ và dược điển.", "Tự nguyên_Xie": "Tiểu triện | Không tìm thấy glyph origin từ Wiktionary cho 葠. Nghĩa là cỏ sâm (cây quý, lá như bàn tay, hoa trắng, dùng làm thuốc); sao Sâm. Có hình Tiểu triện (nguồn hanziyuan). chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ sâm (thứ cỏ quý, lá như bàn tay, hoa trắng, dùng làm thuốc); sao Sâm (một trong Nhị thập bát tú)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 侵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹侵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "侵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葠", "Unihan_Traditional (Chữ Phồn thể)": "葠", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong y học cổ truyền hoặc thiên văn học cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葮', '{"9000": "8631.0", "Chữ Trung Quốc": "葮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葮 | đoạn | tượng hình | chữ hiếm thuộc bộ 艸, âm duàn | 葮 là chữ hiếm thuộc bộ 艸, âm duàn. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoạn\": chữ hiếm nhóm cỏ cây (艸) — âm duàn gần giống 断 (cắt đứt). | Gương Hán-Việt | 葮 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 葮 giúp nhận diện chữ hiếm về thực vật và sửa chữa trong văn bản cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 葮. Thuộc bộ 艸, âm duàn. Nghĩa ghi là sửa chữa. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Sửa chữa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 段", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葮", "Unihan_Traditional (Chữ Phồn thể)": "葮", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Có thể làm động từ chỉ hành động sửa sang hoặc danh từ chỉ loài cỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葲', '{"9000": "8632.0", "Chữ Trung Quốc": "葲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葲 | quyên | tượng hình | loài cỏ cổ, thuộc bộ 艸 | 葲 là chữ hiếm thuộc bộ 艸, âm quán, chỉ một loài cỏ không xác định trong sách cổ. Không có phân tích cấu trúc hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": chữ hiếm nhóm cỏ (艸) — gợi hình ảnh loài cỏ mọc hoang trong đồng cổ. | Gương Hán-Việt | 葲 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 葲 giúp nhận diện chữ hiếm về phân loại cỏ trong văn bản thực vật học cổ.", "Tự nguyên_Xie": "Theo Wiktionary: 葲 là chữ cổ chỉ một loài cỏ (a kind of grass). Không có glyph origin chi tiết. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 泉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹泉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葲", "Unihan_Traditional (Chữ Phồn thể)": "葲", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các tài liệu dược thảo cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓙', '{"9000": "8633.0", "Chữ Trung Quốc": "蓙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 艸 | tháo | biểu nghĩa | cỏ — vật liệu làm chiếu | 座 | toạ | biểu âm | chỗ ngồi — cho âm za | 蓙 = 艸 (Tháo, biểu nghĩa: cỏ) + 座 (Toạ, biểu âm); chữ hình thanh. Phần 艸 chỉ chất liệu cỏ/lác, phần 座 cho âm za. Chữ Nhật dùng để chỉ chiếu goza (茣蓙).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tọa\": cỏ (艸) dùng để ngồi (座) — tấm chiếu cỏ trải xuống đất để ngồi. | Gương Hán-Việt | 蓙 chủ yếu dùng trong tiếng Nhật (茣蓙 — goza chiếu cỏ) | Mở khoá kiến thức | Biết 蓙 giúp đọc tên đồ dùng truyền thống Nhật Bản làm từ cỏ lác.", "Tự nguyên_Xie": "Theo Wiktionary: 蓙 là chữ hình thanh, gồm 艸 (biểu nghĩa: cỏ) và 座 (biểu âm, âm za). Chữ Nhật, dùng trong từ 茣蓙 (goza — chiếu đan bằng cỏ/lác). Không phổ biến trong Hán tự Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 座", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹座", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "座", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓙", "Unihan_Traditional (Chữ Phồn thể)": "蓙", "Pinyin_Xie": "zuo", "Âm Hán Việt_Xie": "tọa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ tấm chiếu lót ngồi trong văn hóa Nhật Bản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔁', '{"9000": "8634.0", "Chữ Trung Quốc": "蔁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔁 | chương | tượng hình | chữ hiếm thuộc bộ 艸, âm zhāng, nghĩa chưa xác định | 蔁 là chữ hiếm thuộc bộ 艸, âm zhāng. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": chữ hiếm nhóm cỏ cây (艸) — âm zhāng gợi hình chữ 章 (chương — điều lệ, hoa văn). | Gương Hán-Việt | 蔁 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蔁 giúp nhận diện chữ hiếm về tên thực vật trong văn bản cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi âm zhāng cho 蔁, không có định nghĩa hay glyph origin. Có hình Tiểu triện. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔁", "Unihan_Traditional (Chữ Phồn thể)": "蔁", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu xuất hiện làm danh từ chỉ tên một loài thực vật trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕛', '{"9000": "8635.0", "Chữ Trung Quốc": "蕛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕛 | đề | tượng hình | chữ hiếm thuộc bộ 艸, âm tí, nghĩa chưa xác định | 蕛 là chữ hiếm thuộc bộ 艸, âm tí. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": chữ hiếm nhóm cỏ cây (艸) — âm tí gần với 提 (đề — nâng lên). | Gương Hán-Việt | 蕛 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蕛 giúp nhận diện chữ hiếm về tên thực vật trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary chỉ ghi âm tí cho 蕛, không có định nghĩa hay glyph origin. Thuộc bộ 艸. chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蛛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 稊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹稊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "稊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕛", "Unihan_Traditional (Chữ Phồn thể)": "蕛", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để ví với sự nhỏ bé. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕜', '{"9000": "8636.0", "Chữ Trung Quốc": "蕜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕜 | phỉ | tượng hình | chữ hiếm thuộc bộ 艸, âm fěi, nghĩa chưa xác định | 蕜 là chữ hiếm thuộc bộ 艸, âm fěi. Không có phân tích cấu trúc hình thanh/hội ý trong nguồn học thuật hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": chữ hiếm nhóm cỏ cây (艸) — âm fěi gần giống 非 (phi — không phải). | Gương Hán-Việt | 蕜 ít dùng trong tiếng Việt | Mở khoá kiến thức | Biết 蕜 giúp nhận diện chữ hiếm về tên thực vật trong văn bản cổ.", "Tự nguyên_Xie": "Không tìm thấy glyph origin từ Wiktionary cho 蕜. Thuộc bộ 艸, âm fěi. Nghĩa ghi là 蜜 (mật ong) nhưng thiếu xác nhận học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 悲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹悲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕜", "Unihan_Traditional (Chữ Phồn thể)": "蕜", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tên loài thực vật trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕦', '{"9000": "8637.0", "Chữ Trung Quốc": "蕦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕦 | hu | tượng hình | cỏ tiên dùng để so sánh với mù tạt chua (sorrel) | 蕦 là chữ độc thể thuộc bộ 艸 (thảo), dùng chỉ một loại thảo mộc. Chưa xác định rõ cấu trúc hình thanh hay hội ý từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hu\": bộ 艸 (cỏ) gợi loại thảo mộc, âm xū như tiếng thở dài trước vị chua của sorrel. | Gương Hán-Việt | Chữ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蕦 mở khoá tên các loại thảo mộc cổ trong y học và thực vật học Hán cổ.", "Tự nguyên_Xie": "蕦 (âm Hán-Việt học thuật: Hu, từ Trung Cổ Hán *xio) là tên cổ của một loại thực vật tương tự cây chua me đất (sorrel). Wiktionary ghi nhận chữ này là dạng cổ phi tiêu chuẩn của 酸模. Chưa có nguồn học thuật chi tiết về cấu tạo chữ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 須", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹須", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "須", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕦", "Unihan_Traditional (Chữ Phồn thể)": "蕦", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "hu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ tên một loài thực vật ít phổ biến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕵', '{"9000": "8638.0", "Chữ Trung Quốc": "蕵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艸 | tháu | biểu nghĩa | cỏ, thảo mộc | 飧 | tôn | biểu âm | bữa tối, âm sūn | 蕵 = 艸 (Tháu, biểu nghĩa: cỏ/thảo mộc) + 飧 (Tôn, biểu âm, âm sūn); chữ hình thanh. Bộ 艸 chỉ đây là thực vật, phần 飧 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tôn\": bộ 艸 (cỏ) kết hợp với 飧 (bữa tối) — loại cỏ dại người xưa hái về ăn bữa tối đạm bạc. | Gương Hán-Việt | Chữ hiếm, xuất hiện trong tên thảo dại cổ 蕵蕪. | Mở khoá kiến thức | Biết 蕵 giúp đọc tên thảo mộc cổ trong thực vật học Hán văn.", "Tự nguyên_Xie": "蕵 (âm Hán-Việt học thuật: Tôn, Trung Cổ Hán *suon) là hình thanh tự: 艸 biểu nghĩa (thực vật) + 飧 biểu âm. Wiktionary xác nhận cấu trúc Han compound ls=psc. Chữ dùng trong từ ghép 蕵蕪, chỉ một loại thảo dại. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蕵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蕵", "Unihan_Traditional (Chữ Phồn thể)": "蕵", "Pinyin_Xie": "sūn", "Âm Hán Việt_Xie": "tôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một loại rau hoang dã có thể ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薖', '{"9000": "8639.0", "Chữ Trung Quốc": "薖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 薖 | kha | tượng hình | rộng rãi, trống trải; dáng vẻ to lớn, mênh mông | 薖 thuộc bộ 艸 (thảo), dùng trong văn học cổ với nghĩa rộng rãi, mênh mông. Cấu trúc nội bộ chưa được phân tích rõ trong nguồn học thuật; xem như chữ độc thể trong ngữ cảnh này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": bộ 艸 (cỏ) trên cánh đồng mênh mông — âm kē gợi không gian rộng mở như cỏ trải dài không thấy biên. | Gương Hán-Việt | Chữ hiếm, xuất hiện chủ yếu trong thơ văn cổ. | Mở khoá kiến thức | Biết 薖 mở khoá từ vựng tả cảnh thiên nhiên rộng lớn trong thơ Kinh Thi và văn học Hán cổ.", "Tự nguyên_Xie": "薖 (Hán-Việt học thuật: Kha, Trung Cổ Hán *kha) mang nghĩa văn học: rộng lớn, mênh mông, trống trải. Wiktionary ghi nhận đây là chữ văn ngôn (literary) với nghĩa ''great; expansive''. Không có phân tích glyph-origin chi tiết. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn; trông đói", "Hạng Tần Suất (Jun Da)": "8639.0", "Tần Suất % (Jun Da)": "99.9997793327", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 過", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹過", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "過", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薖", "Unihan_Traditional (Chữ Phồn thể)": "薖", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để tả vẻ to lớn, rộng rãi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藨', '{"9000": "8640.0", "Chữ Trung Quốc": "藨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藨 | phiêu | tượng hình | loại cây giống mâm xôi (raspberry), cỏ dùng đan giỏ | 藨 thuộc bộ 艸 (thảo), chỉ một loại thực vật gần giống mâm xôi hoặc cỏ dùng đan thủ công. Cấu trúc nội bộ không được phân tích trong nguồn; xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": bộ 艸 (cỏ) + âm biāo bay bổng — loài cây mọc nhanh như bay, quả mọng đỏ như lửa. | Gương Hán-Việt | Chữ hiếm, dùng chủ yếu trong thực vật học cổ và đan lát thủ công. | Mở khoá kiến thức | Biết 藨 mở khoá tên các loài thực vật hoang dã trong Erya và thực vật học Hán cổ.", "Tự nguyên_Xie": "藨 (Hán-Việt học thuật: Phiêu, Trung Cổ Hán *pjaw) là tên một loài cây thuộc họ mâm xôi (Rubus) hoặc cỏ dùng đan lát. Wiktionary không cung cấp phân tích glyph-origin chi tiết cho chữ này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cói", "Hạng Tần Suất (Jun Da)": "8640.0", "Tần Suất % (Jun Da)": "99.9997798495", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 麃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹麃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "麃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藨", "Unihan_Traditional (Chữ Phồn thể)": "藨", "Pinyin_Xie": "biāo", "Âm Hán Việt_Xie": "biều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loại cỏ thuộc họ cói hoặc quả mâm xôi rừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藮', '{"9000": "8641.0", "Chữ Trung Quốc": "藮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 藮 | kiều | tượng hình | loại thảo mộc không xác định rõ trong sách cổ | 藮 thuộc bộ 艸 (thảo). Cấu trúc và nghĩa cụ thể không được làm rõ trong nguồn học thuật hiện có. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": bộ 艸 (cỏ) gợi thảo mộc; âm qiáo như cầu — loại cỏ mọc ở chân cầu ven sông trong cổ thư. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 藮 giúp đọc tên thảo mộc trong các bộ bách khoa thực vật cổ điển Trung Hoa.", "Tự nguyên_Xie": "藮 (Hán-Việt học thuật: Kiều, Trung Cổ Hán *gjaw) là tên một loại thảo mộc hiếm, nghĩa cụ thể không được ghi chép đầy đủ trong các từ điển hiện đại. Wiktionary và nguồn học thuật chưa cung cấp phân tích glyph-origin. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藮", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 樵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹樵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "樵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藮", "Unihan_Traditional (Chữ Phồn thể)": "藮", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "kiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ củi khô hoặc làm động từ chỉ hành động kiếm củi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藰', '{"9000": "8642.0", "Chữ Trung Quốc": "藰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藰 | lưu | tượng hình | loại thảo mộc không xác định rõ trong sách cổ | 藰 thuộc bộ 艸 (thảo). Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật hiện có. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ 艸 (cỏ) + âm liú như dòng chảy — loại cỏ mọc dọc theo dòng chảy của suối nhỏ. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 藰 giúp đọc thực vật danh trong các cổ thư Hán ngữ chuyên biệt.", "Tự nguyên_Xie": "藰 (Hán-Việt học thuật: Lưu, Trung Cổ Hán *ljuw) là tên một loại thảo mộc hiếm trong Hán ngữ cổ. Nguồn gốc chữ và nghĩa cụ thể chưa được làm rõ trong tài liệu học thuật. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 劉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹劉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藰", "Unihan_Traditional (Chữ Phồn thể)": "藰", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để tả cảnh cây cối xanh tốt, rậm rạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藳', '{"9000": "8643.0", "Chữ Trung Quốc": "藳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藳 | cảo | tượng hình | rơm, cọng cỏ khô; bản thảo viết trên cỏ gianh | 藳 thuộc bộ 艸 (thảo), liên quan đến cỏ khô, rơm hoặc bản thảo. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật; xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảo\": bộ 艸 (cỏ) trên mặt chữ — cọng cỏ khô (rơm) dùng để viết bản thảo sơ khai ngày xưa. | Gương Hán-Việt | 藳 gần nghĩa với 稿 (cảo, bản thảo) — biết 藳 giúp hiểu từ 文稿, 草稿. | Mở khoá kiến thức | Biết 藳 mở khoá nhóm chữ chỉ rơm rạ, cỏ khô và bản thảo viết tay trong văn học cổ.", "Tự nguyên_Xie": "藳 (Hán-Việt học thuật: Cảo, Trung Cổ Hán *kawʔ) có nghĩa liên quan đến rơm rạ, cọng cỏ khô. Về mặt âm vị học, tương đồng với 稿 (cảo, bản thảo). Wiktionary không cung cấp phân tích glyph-origin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藳", "Hạng Tần Suất (Jun Da)": "8643.0", "Tần Suất % (Jun Da)": "99.9997813999", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 稾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹稾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "稾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藳", "Unihan_Traditional (Chữ Phồn thể)": "藳", "Pinyin_Xie": "gǎo", "Âm Hán Việt_Xie": "cảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ rơm khô hoặc các bản viết thảo, bản nháp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藵', '{"9000": "8644.0", "Chữ Trung Quốc": "藵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 藵 | bao | tượng hình | loại thảo mộc không xác định rõ trong sách cổ | 藵 thuộc bộ 艸 (thảo). Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật hiện có. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": bộ 艸 (cỏ) + âm bao như bọc — loại cỏ có lá to bọc quanh thân cây trong đầm lầy cổ. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 藵 giúp đọc danh mục thực vật trong các bộ từ điển Hán cổ như Nhĩ Nhã (爾雅).", "Tự nguyên_Xie": "藵 (Hán-Việt học thuật: Bao, Trung Cổ Hán *paw) là tên một loại thảo mộc hiếm trong Hán ngữ cổ. Nghĩa cụ thể và nguồn gốc chữ chưa được làm rõ trong tài liệu học thuật hiện đại. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 𧛱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹𧛱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𧛱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藵", "Unihan_Traditional (Chữ Phồn thể)": "藵", "Pinyin_Xie": "bao", "Âm Hán Việt_Xie": "bao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ miêu tả trạng thái cỏ cây phát triển tươi tốt, rậm rạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虃', '{"9000": "8645.0", "Chữ Trung Quốc": "虃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 23 | nét | 虃 | tiêm | tượng hình | loại thực vật hiếm thuộc bộ 艸 (thảo) | 虃 thuộc bộ 艸 (thảo). Nghĩa và cấu trúc nội bộ không rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêm\": bộ 艸 (cỏ) với âm jiān như vật nhọn — loại cỏ lá nhọn sắc trong cổ thư. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 虃 giúp nhận diện các chữ bộ 艸 hiếm trong từ điển cổ điển Trung Hoa.", "Tự nguyên_Xie": "虃 (Hán-Việt học thuật: Tiêm, Trung Cổ Hán *tsem) xuất hiện trong từ điển cổ với định nghĩa chưa rõ (rfdef). Wiktionary ghi nhận âm jiān và xếp chữ vào bộ 艸. Chưa có nguồn học thuật chi tiết về nghĩa hoặc cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虃", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 瀸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹瀸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瀸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "虃", "Unihan_Traditional (Chữ Phồn thể)": "虃", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại cỏ nhỏ, cỏ non mới nhú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虘', '{"9000": "8646.0", "Chữ Trung Quốc": "虘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 11 | nét | 虘 | ta | tượng hình | chữ hiếm thuộc bộ 虍 (hổ), nghĩa chưa rõ | 虘 thuộc bộ 虍 (hổ đầu). Nghĩa và cấu trúc nội bộ không được làm rõ trong nguồn học thuật hiện có. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": bộ 虍 (hổ) gợi hình ảnh oai dũng; âm cuó như sai lầm — con hổ lạc đường, hoang mang. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 虘 giúp nhận diện chữ hiếm bộ 虍 trong từ điển học Hán ngữ cổ điển.", "Tự nguyên_Xie": "虘 (Hán-Việt học thuật: Ta, Trung Cổ Hán *dza) là chữ hiếm thuộc bộ 虍 (hổ). Wiktionary ghi nhận âm cuó nhưng không cung cấp định nghĩa rõ ràng (rfdef). Nguồn gốc chữ chưa được phân tích. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "虘", "Unihan_Traditional (Chữ Phồn thể)": "虘", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để miêu tả tính cách gian trá hoặc tính chất hung dữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虝', '{"9000": "8647.0", "Chữ Trung Quốc": "虝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虍 | Số nét | 12 | nét | 虝 | hổ | tượng hình | chữ cổ liên quan đến hổ, biến thể hoặc dị thể của 虎 | 虝 thuộc bộ 虍 (hổ đầu), là dị thể hoặc chữ cổ liên quan đến 虎 (hổ). Cấu trúc nội bộ không được phân tích trong nguồn hiện có; xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hổ\": bộ 虍 (đầu hổ) cộng với phần dưới gợi toàn thân hổ — chữ tượng hình cổ của con hổ uy mãnh. | Gương Hán-Việt | 虝 thông với 虎 (hổ) — biết 虝 giúp hiểu nhóm chữ tượng hình về hổ trong cổ tự. | Mở khoá kiến thức | Biết 虝 mở khoá nhóm dị thể chữ 虎 và chữ cổ liên quan đến động vật hung mãnh.", "Tự nguyên_Xie": "虝 (Hán-Việt học thuật: Hổ, Trung Cổ Hán *hʷaʔ) là dị thể cổ của chữ 虎 (hổ). Wiktionary ghi nhận âm hǔ. Đây là chữ hiếm thuộc bộ 虍. Chưa có phân tích glyph-origin chi tiết trong nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虎 + 勿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虎勿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虎", "Unihan_Simplified (Chữ Giản thể)": "虝", "Unihan_Traditional (Chữ Phồn thể)": "虝", "Pinyin_Xie": "hǔ", "Âm Hán Việt_Xie": "hổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài hổ trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛥', '{"9000": "8648.0", "Chữ Trung Quốc": "蛥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 蛥 | xà | tượng hình | loài côn trùng kêu tiếng nhỏ (cricket), dùng trong 蛥蚗 | 蛥 thuộc bộ 虫 (trùng), chỉ một loại côn trùng. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xà\": bộ 虫 (côn trùng) + âm shé như rắn — con dế nhỏ kêu tiếng sắc như xà xà trong đêm thu. | Gương Hán-Việt | Chữ hiếm, xuất hiện trong tên sinh vật cổ 蛥蚗. | Mở khoá kiến thức | Biết 蛥 giúp đọc tên côn trùng cổ trong Nhĩ Nhã và sách tự nhiên sử Hán ngữ.", "Tự nguyên_Xie": "蛥 (Hán-Việt học thuật: Xà, Trung Cổ Hán *dʑjat) là tên một loại côn trùng, chỉ dùng trong từ ghép 蛥蚗 (chỉ loài ve sầu hoặc dế). Wiktionary xác nhận âm shé và ngữ cảnh 蛥蚗. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛥", "Unihan_Traditional (Chữ Phồn thể)": "蛥", "Pinyin_Xie": "shé", "Âm Hán Việt_Xie": "xà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loại côn trùng như dế hoặc ve. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛶', '{"9000": "8649.0", "Chữ Trung Quốc": "蛶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蛶 | giới | tượng hình | loài côn trùng có ngòi đốt, dùng trong từ 螪蛶 | 蛶 thuộc bộ 虫 (trùng), chỉ một loài côn trùng có ngòi đốt. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn; xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": bộ 虫 (côn trùng) + âm jiè như giới hạn — loài côn trùng có ranh giới rõ ràng giữa các đốt thân mình. | Gương Hán-Việt | Chữ hiếm, xuất hiện trong tên sinh vật 螪蛶. | Mở khoá kiến thức | Biết 蛶 giúp đọc tên côn trùng cổ trong danh mục sinh vật học Hán ngữ.", "Tự nguyên_Xie": "蛶 (Hán-Việt học thuật: Giới, Trung Cổ Hán *krɛjʔ) chỉ một loài côn trùng, xuất hiện trong từ ghép 螪蛶 (một loại côn trùng). Wiktionary ghi nhận là chữ phi tiêu chuẩn (obs-std) chỉ xuất hiện trong 螪蛶. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chích", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 寽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫寽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛶", "Unihan_Traditional (Chữ Phồn thể)": "蛶", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại côn trùng nhỏ theo sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜠', '{"9000": "8650.0", "Chữ Trung Quốc": "蜠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜠 | quân | tượng hình | loài ốc lớn (large shell), dùng trong Hán ngữ cổ | 蜠 thuộc bộ 虫 (trùng), chỉ một loài ốc lớn. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": bộ 虫 (sinh vật) + âm jùn như quân vương — loài ốc lớn uy nghi như vua trong thế giới động vật thân mềm. | Gương Hán-Việt | Chữ hiếm, ít xuất hiện trong từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蜠 giúp đọc tên động vật thân mềm cổ trong sách tự nhiên sử Hán ngữ.", "Tự nguyên_Xie": "蜠 (Hán-Việt học thuật: Quân, Trung Cổ Hán *gjun) là tên một loài ốc lớn trong Hán ngữ cổ. Wiktionary xác nhận là chữ phi tiêu chuẩn (obs-std) chỉ loài động vật có vỏ lớn. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 囷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫囷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "囷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜠", "Unihan_Traditional (Chữ Phồn thể)": "蜠", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loài động vật thân mềm có vỏ như ốc sên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螐', '{"9000": "8651.0", "Chữ Trung Quốc": "螐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螐 | ô | tượng hình | loài sinh vật nhỏ thuộc bộ 虫, nghĩa chưa rõ | 螐 thuộc bộ 虫 (trùng). Nghĩa và cấu trúc nội bộ không được làm rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": bộ 虫 (sinh vật nhỏ) + âm wū tối tăm — loài sinh vật nhỏ ẩn mình trong bóng tối, kêu tiếng ô ô. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 螐 giúp nhận diện chữ bộ 虫 hiếm trong từ điển học Hán ngữ cổ điển.", "Tự nguyên_Xie": "螐 (Hán-Việt học thuật: Ô, Trung Cổ Hán *ʔo) là chữ hiếm thuộc bộ 虫. Wiktionary ghi nhận âm wū nhưng không cung cấp định nghĩa (rfdef). Chưa có nguồn học thuật chi tiết về nghĩa hoặc cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "萐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 烏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫烏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "烏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螐", "Unihan_Traditional (Chữ Phồn thể)": "螐", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chủ yếu xuất hiện trong các từ ghép cổ chỉ các loài sâu bọ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螖', '{"9000": "8652.0", "Chữ Trung Quốc": "螖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 螖 | hoạt | tượng hình | loài động vật giáp xác, dùng trong từ 蟛螖 (cua nhỏ) | 螖 thuộc bộ 虫 (trùng), chỉ một loài động vật giáp xác nhỏ. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạt\": bộ 虫 (sinh vật) + âm huá trơn trượt — con cua nhỏ (蟛螖) chạy trơn như trượt trên bùn. | Gương Hán-Việt | 螖 xuất hiện trong 蟛螖 (loài cua nhỏ ven biển). | Mở khoá kiến thức | Biết 螖 giúp đọc tên giáp xác trong sinh vật học và ẩm thực học Hán ngữ cổ.", "Tự nguyên_Xie": "螖 (Hán-Việt học thuật: Hoạt, Trung Cổ Hán *ɦwat) xuất hiện trong từ ghép 蟛螖 (loài cua nhỏ) và 螖蠌. Wiktionary xác nhận âm huá và ngữ cảnh 螖蠌, 蟛螖子, 蟛螖. Đây là tên sinh vật biển cổ. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "báo gêpa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 骨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫骨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "骨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螖", "Unihan_Traditional (Chữ Phồn thể)": "螖", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong văn ngôn để chỉ một loại cua nhỏ ở bờ biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螡', '{"9000": "8653.0", "Chữ Trung Quốc": "螡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螡 | văn | tượng hình | loài côn trùng hoặc sinh vật nhỏ thuộc bộ 虫 | 螡 thuộc bộ 虫 (trùng). Cấu trúc nội bộ và nghĩa cụ thể không được làm rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": bộ 虫 (sinh vật nhỏ) + âm wén như hoa văn — loài sinh vật có hoa văn đẹp trên thân mình. | Gương Hán-Việt | Chữ hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 螡 giúp nhận diện chữ hiếm bộ 虫 trong tự điển Hán ngữ cổ điển.", "Tự nguyên_Xie": "螡 (Hán-Việt học thuật: Văn, Trung Cổ Hán *mɨn) là chữ hiếm thuộc bộ 虫. Wiktionary ghi nhận âm wén và nghĩa 衡 (cân bằng/thước đo). Mối liên hệ giữa âm wén và bộ 虫 không hoàn toàn rõ ràng trong nguồn hiện có. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 䖵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱文䖵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䖵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "螡", "Unihan_Traditional (Chữ Phồn thể)": "螡", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, là dạng chữ cổ của chữ văn dùng để chỉ con muỗi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟳', '{"9000": "8654.0", "Chữ Trung Quốc": "蟳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 尋 | tầm | biểu âm | âm xún, tìm kiếm | 蟳 = 虫 (Trùng, biểu nghĩa: sinh vật) + 尋 (Tầm, biểu âm, âm xún); chữ hình thanh. Bộ 虫 chỉ đây là động vật nhỏ/giáp xác, phần 尋 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằm\": bộ 虫 (giáp xác) + 尋 (tầm — tìm kiếm) cho âm — con cua tìm kiếm mồi, bước đi như tìm đường dưới đáy sông. | Gương Hán-Việt | 蟳 là tên loài cua trong phương ngữ Nam Hán, ít xuất hiện trong từ Hán-Việt phổ thông. | Mở khoá kiến thức | Biết 蟳 giúp đọc tên giáp xác trong ẩm thực và sinh vật học Hán ngữ vùng Phúc Kiến, Quảng Đông.", "Tự nguyên_Xie": "蟳 (Hán-Việt học thuật: Tằm, Trung Cổ Hán *dzim) là hình thanh tự: 虫 (biểu nghĩa: giáp xác) + 尋 (biểu âm, âm xún). Wiktionary xác nhận cấu trúc Han compound ls=psc với c1=s (semantic: bug), c2=p (phonetic). Chữ chỉ một loài cua (a kind of crab). Lưu ý: slug anchor dùng đọc \"tằm\", tuy nhiên nghĩa thực là cua, không phải tằm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(cua biển lông)", "Hạng Tần Suất (Jun Da)": "8654.0", "Tần Suất % (Jun Da)": "99.9997886349", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "蟳", "Unihan_Traditional (Chữ Phồn thể)": "蟳", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong tên gọi các loài cua biển hoặc ghẹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠌', '{"9000": "8655.0", "Chữ Trung Quốc": "蠌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蠌 | trách | tượng hình | loài động vật giáp xác nhỏ, dùng trong từ 螖蠌 | 蠌 thuộc bộ 虫 (trùng), chỉ một loài động vật nhỏ, dùng trong từ 螖蠌. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": bộ 虫 (sinh vật nhỏ) + âm zé như trách nhiệm — loài giáp xác nhỏ mang \"trách nhiệm\" làm sạch đáy sông. | Gương Hán-Việt | 蠌 xuất hiện trong 螖蠌 — tên một loài giáp xác cổ trong tự nhiên sử. | Mở khoá kiến thức | Biết 蠌 giúp đọc tên giáp xác trong sinh vật học và điển tịch cổ đại Hán ngữ.", "Tự nguyên_Xie": "蠌 (Hán-Việt học thuật: Trách, Trung Cổ Hán *dzrak) xuất hiện chủ yếu trong từ ghép 螖蠌 (một loài giáp xác nhỏ). Wiktionary xác nhận âm zé và ngữ cảnh 螖蠌. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 睪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫睪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠌", "Unihan_Traditional (Chữ Phồn thể)": "蠌", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chủ yếu dùng trong các từ ghép cổ chỉ loài cua nhỏ hoặc côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠒', '{"9000": "8656.0", "Chữ Trung Quốc": "蠒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 爾 | nhãi | khung cửi | 虫 | trùng | côn trùng | 蠒 = 爾 (Nhãi, biểu khung cửi/loom) + 虫 (Trùng, côn trùng); chữ hội ý theo Wiktionary (ls=ic). Ý nghĩa: côn trùng (tằm) trên khung cửi, liên quan đến việc kéo tơ dệt lụa. Là dị thể cổ của 繭 (kén tằm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiển\": 爾 (khung cửi) kết hợp 虫 (tằm) — con tằm nhả tơ bọc mình thành kén (繭/蠒), dệt lụa từ khung cửi. | Gương Hán-Việt | 蠒 thông với 繭 (kiển — kén tằm) — biết 蠒 giúp hiểu từ 蠶繭 (tằm kén), 繭絲 (tơ kén). | Mở khoá kiến thức | Biết 蠒 mở khoá nhóm chữ nghề tằm tơ: 繭 (kén), 蠶 (tằm), 絲 (tơ) trong văn hóa dệt lụa Hán cổ.", "Tự nguyên_Xie": "蠒 (Hán-Việt học thuật: Kiển, Trung Cổ Hán *kenʔ) là hội ý tự: 爾 (khung cửi/loom) + 虫 (côn trùng). Wiktionary xác nhận cấu trúc Han compound ls=ic. Chữ này là dị thể của 繭 (kén tằm). Wiktionary ghi 蠒 = 繭 với định nghĩa Trichoderma (nấm). Nghĩa gốc liên quan đến kén tằm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Trichoderma", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "爾 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爾虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠒", "Unihan_Traditional (Chữ Phồn thể)": "蠒", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, dùng để chỉ kén của sâu tằm hoặc vết chai sạn trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠗', '{"9000": "8657.0", "Chữ Trung Quốc": "蠗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 蠗 | trác | tượng hình | loài khỉ hoặc ốc nhỏ trong Hán ngữ cổ | 蠗 thuộc bộ 虫 (trùng). Wiktionary ghi hai nghĩa: (1) loài khỉ, (2) loài ốc nhỏ. Cấu trúc nội bộ không được phân tích chi tiết. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": bộ 虫 (sinh vật) + âm zhuó như đục chạm — loài vật nhỏ (khỉ hay ốc) đục khoét, leo trèo nhanh nhẹn. | Gương Hán-Việt | Chữ hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蠗 giúp đọc mô tả động vật hiếm trong bác vật học và tự nhiên sử Hán cổ điển.", "Tự nguyên_Xie": "蠗 (Hán-Việt học thuật: Trác, Trung Cổ Hán *drjawk) có hai nghĩa trong sách cổ: (1) một loài khỉ nhỏ (obs-std), (2) một loài ốc nhỏ (obs-std). Sự đa nghĩa này phản ánh đặc điểm chữ cổ dùng cho nhiều thực thể khác nhau. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(vượn); (vỏ bọc)", "Hạng Tần Suất (Jun Da)": "8657.0", "Tần Suất % (Jun Da)": "99.999790702", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 翟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫翟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠗", "Unihan_Traditional (Chữ Phồn thể)": "蠗", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, xuất hiện trong thư tịch cổ để chỉ một loài vượn hoặc loài động vật có vỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠝', '{"9000": "8658.0", "Chữ Trung Quốc": "蠝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 21 | nét | 蠝 | lôi | tượng hình | con gián hoặc côn trùng tương tự trong Hán ngữ cổ | 蠝 thuộc bộ 虫 (trùng), chỉ một loài côn trùng (gián hoặc tương tự). Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": bộ 虫 (côn trùng) + âm léi như sấm — con gián chạy nhanh như sấm sét, để lại tiếng xào xạo trong bóng tối. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 蠝 giúp nhận diện tên côn trùng hiếm trong từ điển học Hán ngữ cổ điển.", "Tự nguyên_Xie": "蠝 (Hán-Việt học thuật: Lôi, Trung Cổ Hán *rɨj) là tên một loài côn trùng (cockroach hoặc tương tự) trong Hán ngữ cổ. Wiktionary không cung cấp phân tích glyph-origin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gián", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 畾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫畾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠝", "Unihan_Traditional (Chữ Phồn thể)": "蠝", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, dùng trong văn ngôn để chỉ con gián hoặc côn trùng tương tự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袘', '{"9000": "8659.0", "Chữ Trung Quốc": "袘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 袘 | di | tượng hình | vạt áo dài, phần tà dưới áo | 袘 thuộc bộ 衣 (y — áo), chỉ phần vạt hoặc tà áo dài. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": bộ 衣 (áo) gợi y phục — phần tà áo (袘) kéo dài theo bước di chuyển uyển chuyển của người mặc. | Gương Hán-Việt | Chữ hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 袘 giúp đọc mô tả y phục truyền thống trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "袘 (Hán-Việt học thuật: Di, Trung Cổ Hán *jie) là tên chỉ phần vạt hoặc đuôi áo dài. Wiktionary ghi nhận chữ này với tham chiếu Han etym (衪). Chưa có phân tích glyph-origin chi tiết trong nguồn học thuật hiện đại. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "袘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袘", "Unihan_Traditional (Chữ Phồn thể)": "袘", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ phần vạt áo hoặc tay áo rộng trong trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褜', '{"9000": "8660.0", "Chữ Trung Quốc": "褜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 褜 | bào | tượng hình | loại áo dài rộng, áo bào | 褜 thuộc bộ 衣 (y — áo), liên quan đến một loại áo rộng. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bộ 衣 (áo) + âm pao rộng rãi — chiếc áo bào rộng thùng thình bao trùm khắp người. | Gương Hán-Việt | Chữ hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 褜 giúp đọc mô tả trang phục quan lại và nghi lễ trong sử sách Hán cổ.", "Tự nguyên_Xie": "褜 (Hán-Việt học thuật: Bào, Trung Cổ Hán *paw) là tên một loại áo rộng trong Hán ngữ cổ. Wiktionary không cung cấp phân tích glyph-origin chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "胞 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱胞衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "褜", "Unihan_Traditional (Chữ Phồn thể)": "褜", "Pinyin_Xie": "pao", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ chỉ nhau thai hoặc màng bọc thai nhi trong y học cổ truyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褨', '{"9000": "8661.0", "Chữ Trung Quốc": "褨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 褨 | tỏa | tượng hình | loại y phục hoặc phụ kiện áo cổ | 褨 thuộc bộ 衣 (y — áo). Nghĩa và cấu trúc nội bộ không được làm rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỏa\": bộ 衣 (áo) + âm suǒ như khóa — chi tiết áo có khóa/cài cẩn thận, gợi y phục cung đình trang trọng. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 褨 giúp đọc mô tả chi tiết y phục trong điển lễ và sử học Hán cổ.", "Tự nguyên_Xie": "褨 (Hán-Việt học thuật: Tỏa, Trung Cổ Hán *swa) là thuật ngữ y phục cổ, nghĩa cụ thể chưa được làm rõ (rfdef theo Wiktionary). Wiktionary ghi âm suǒ. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "褨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褨", "Unihan_Traditional (Chữ Phồn thể)": "褨", "Pinyin_Xie": "suǒ", "Âm Hán Việt_Xie": "tỏa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái quần áo mặc lỏng lẻo hoặc không gọn gàng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襾', '{"9000": "8662.0", "Chữ Trung Quốc": "襾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 6 | nét | 襾 | á | tượng hình | bìa/nắp đậy; bộ thủ 146 trong Khang Hy tự điển | 襾 là độc thể tượng hình, là bộ thủ 146 trong hệ thống phân loại Khang Hy. Theo Hứa Thận: 冂 (cái khung) chồng lên 凵 (hõm) với nét ngang trên đỉnh, biểu thị hành động đậy/che phủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"á\": hình tượng nắp đậy từ trên xuống — 冂 (khung) úp lên 凵 (hõm), che chắn hoàn toàn. Bộ thủ chính của các chữ liên quan đến che phủ. | Gương Hán-Việt | \"á\" là bộ thủ chính của 覆 (phúc — che phủ), 覇 (bá — bá quyền), 要 (yếu — quan trọng). | Mở khoá kiến thức | Biết 襾 mở khoá bộ thủ 146: 要, 覆, 覇 và các chữ liên quan đến khái niệm che phủ, bá quyền.", "Tự nguyên_Xie": "襾 (Hán-Việt: Á, Trung Cổ Hán *ʔaj) là tượng hình tự biểu thị hành động che phủ/đậy. Wiktionary ghi: theo Hứa Thận (Thuyết Văn Giải Tự), chữ này là 冂 chồng lên 凵 với nét ngang ở trên, mô tả nắp đậy. Đây là bộ thủ Khang Hy số 146. Nghĩa: cover (đậy, che). Âm: yà hoặc xià. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che, chùm lên", "Hạng Tần Suất (Jun Da)": "8662.0", "Tần Suất % (Jun Da)": "99.9997938027", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "襾", "Unihan_Traditional (Chữ Phồn thể)": "襾", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "á", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động che phủ hoặc làm danh từ chỉ cái nắp đậy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覊', '{"9000": "8663.0", "Chữ Trung Quốc": "覊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 襾 | Số nét | 25 | nét | 覊 | ki | tượng hình | dây cương ngựa; ràng buộc, kiềm chế | 覊 là chữ phồn thể, liên quan đến dây cương ngựa và khái niệm ràng buộc/kiểm soát. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể trong ngữ cảnh này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": hình ảnh dây cương (覊) siết chặt — bị ràng buộc xa quê, như ngựa mang cương không tự do. | Gương Hán-Việt | \"ki\" xuất hiện trong 覊絆 (ki bạn — ràng buộc), 覊旅 (ki lữ — lữ khách tha phương). | Mở khoá kiến thức | Biết 覊 mở khoá khái niệm ràng buộc, xa quê: 羁旅 (ki lữ), 要绊 (trói buộc), nhóm từ văn học về ly hương.", "Tự nguyên_Xie": "覊 (Hán-Việt học thuật: Ki, Trung Cổ Hán *kje) mang nghĩa dây cương ngựa, và rộng hơn là ràng buộc, kiềm chế, khống chế. Wiktionary xác nhận nghĩa: halter (dây cương); restrain, hold, control. Đây là chữ phồn thể, liên quan đến 羁 (ki — ràng buộc, xa quê). Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giữ gìn, duy trì, kiềm chế", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "覀 + 䩻", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱覀䩻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䩻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "覀", "Unihan_Simplified (Chữ Giản thể)": "覊", "Unihan_Traditional (Chữ Phồn thể)": "覊", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dây cương hoặc làm động từ với nghĩa ràng buộc, hạn chế tự do. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覚', '{"9000": "8664.0", "Chữ Trung Quốc": "覚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 12 | nét | 覚 | giác | tượng hình | tỉnh giác, thức dậy; ý thức; dạng giản thể Nhật của 覺 | 覚 là dạng giản thể hóa Nhật Bản (shinjitai) của 覺 (giác), từ Han simp với 𦥯 → 𰃮. Cấu trúc gốc của 覺: bộ 見 (kiến — nhìn) kết hợp với phần biểu âm/nghĩa phía trên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giác\": bộ 見 (nhìn, kiến) trong nền tảng chữ — nhìn thấy sự thật khi tỉnh giác; giác ngộ, thức dậy khỏi vô minh. | Gương Hán-Việt | \"giác\" xuất hiện trong 覺悟 (giác ngộ), 覺醒 (giác tỉnh), 自覺 (tự giác). | Mở khoá kiến thức | Biết 覚/覺 mở khoá: 覺悟 (giác ngộ), 覺醒 (giác tỉnh), 感覺 (cảm giác), 知覺 (tri giác).", "Tự nguyên_Xie": "覚 (Hán-Việt: Giác, Trung Cổ Hán *kjewk) là dạng giản thể Nhật của 覺. Wiktionary xác nhận: Han simp 覺 với f=𦥯, t=𰃮. Nghĩa: thức dậy từ giấc ngủ; có ý thức; nhận ra. Chữ phồn thể 覺 phổ biến hơn trong Hán ngữ tiêu chuẩn và Hán-Việt học. Đây là dạng dùng trong tiếng Nhật hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thức dậy, tỉnh dậy", "Hạng Tần Suất (Jun Da)": "8664.0", "Tần Suất % (Jun Da)": "99.9997948363", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "覚", "Unihan_Traditional (Chữ Phồn thể)": "覚", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "giác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ biểu thị sự nhận thức, cảm giác hoặc tỉnh ngộ sau một quá trình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覛', '{"9000": "8665.0", "Chữ Trung Quốc": "覛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 13 | nét | 覛 | mịch | tượng hình | nhìn trộm, nhìn lén; bộ 見 (kiến) | 覛 thuộc bộ 見 (kiến — nhìn), liên quan đến hành động nhìn lén, nhìn trộm. Cấu trúc nội bộ không được phân tích chi tiết trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mịch\": bộ 見 (mắt nhìn) + âm mì bí mật — đôi mắt mịch lén nhìn qua khe cửa. | Gương Hán-Việt | Chữ hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 覛 giúp đọc mô tả hành vi quan sát bí mật trong văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "覛 (Hán-Việt học thuật: Mịch, Trung Cổ Hán *mɛk) có nghĩa nhìn trộm, nhìn lén (rfdef theo Wiktionary, sort=見06). Wiktionary xác nhận âm mì. Chưa có phân tích glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覛", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "覛", "Unihan_Traditional (Chữ Phồn thể)": "覛", "Pinyin_Xie": "mì", "Âm Hán Việt_Xie": "mịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi nhìn lén hoặc tìm kiếm một cách kín đáo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覟', '{"9000": "8666.0", "Chữ Trung Quốc": "覟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 14 | nét | 覟 | chí | tượng hình | nhìn kỹ, nhìn chăm chú; bộ 見 (kiến) | 覟 thuộc bộ 見 (kiến — nhìn), liên quan đến hành động nhìn kỹ, quan sát. Cấu trúc nội bộ không được phân tích trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": bộ 見 (nhìn) + âm zhì như ý chí — nhìn chăm chú với ý chí mạnh mẽ, không rời mắt khỏi mục tiêu. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 覟 giúp nhận diện chữ bộ 見 hiếm liên quan đến hành động quan sát trong tự điển cổ.", "Tự nguyên_Xie": "覟 (Hán-Việt học thuật: Chí, Trung Cổ Hán *tɕi) là chữ hiếm thuộc bộ 見, liên quan đến hành động nhìn. Wiktionary không cung cấp định nghĩa chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "志 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰志見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "志", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覟", "Unihan_Traditional (Chữ Phồn thể)": "覟", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ miêu tả hành động nhìn một cách tập trung và rõ ràng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覠', '{"9000": "8667.0", "Chữ Trung Quốc": "覠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 14 | nét | 覠 | quân | tượng hình | nhìn; bộ 見 (kiến), nghĩa chưa rõ | 覠 thuộc bộ 見 (kiến — nhìn). Nghĩa và cấu trúc nội bộ không được làm rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": bộ 見 (nhìn) + âm jūn như quân vương — cái nhìn uy nghiêm của bậc quân vương, bao quát tất cả. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 覠 giúp nhận diện chữ bộ 見 hiếm trong từ điển Hán ngữ cổ điển.", "Tự nguyên_Xie": "覠 (Hán-Việt học thuật: Quân, Trung Cổ Hán *kjun) là chữ hiếm thuộc bộ 見. Wiktionary không cung cấp định nghĩa chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "君 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰君見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覠", "Unihan_Traditional (Chữ Phồn thể)": "覠", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc quan sát hoặc xem xét một đối tượng một cách cẩn thận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訜', '{"9000": "8668.0", "Chữ Trung Quốc": "訜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 訜 | phân | tượng hình | lời nói, tiếng kêu; bộ 言 (ngôn), nghĩa chưa rõ | 訜 thuộc bộ 言 (ngôn — lời nói). Cấu trúc nội bộ và nghĩa cụ thể không được làm rõ trong nguồn học thuật. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phân\": bộ 言 (lời nói) + âm fēn như phân tán — tiếng nói phân tán vang lên tứ phía, ồn ào khó nghe. | Gương Hán-Việt | Chữ cực hiếm, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 訜 giúp nhận diện chữ bộ 言 hiếm trong từ điển học Hán ngữ cổ điển.", "Tự nguyên_Xie": "訜 (Hán-Việt học thuật: Phân, Trung Cổ Hán *pɨn) là chữ hiếm thuộc bộ 言 (lời nói). Wiktionary không cung cấp định nghĩa chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "訜", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訜", "Unihan_Traditional (Chữ Phồn thể)": "訜", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ âm thanh hỗn loạn hoặc tính từ miêu tả lời nói không rõ ràng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訡', '{"9000": "8669.0", "Chữ Trung Quốc": "訡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 訡 | ngâm | tượng hình | ngâm nga, rên rỉ, thở dài; bộ 言 (ngôn) | 訡 thuộc bộ 言 (ngôn — lời nói), là dị thể hoặc chữ cổ của 吟 (ngâm). Cấu trúc nội bộ không được phân tích chi tiết trong nguồn. Xem như chữ độc thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngâm\": bộ 言 (lời) gợi tiếng phát ra — ngâm nga (訡/吟) là tiếng nói kéo dài, du dương như tiếng thơ vang trong đêm khuya. | Gương Hán-Việt | \"ngâm\" xuất hiện trong 吟詩 (ngâm thi — ngâm thơ), 呻吟 (thân ngâm — rên rỉ). | Mở khoá kiến thức | Biết 訡/吟 mở khoá: 吟詩 (ngâm thơ), 吟唱 (ngâm hát), 呻吟 (rên rỉ) — nhóm từ về biểu đạt cảm xúc qua giọng nói.", "Tự nguyên_Xie": "訡 (Hán-Việt: Ngâm, Trung Cổ Hán *ngɨm) là dị thể cổ của 吟 (ngâm nga, rên rỉ, thở dài). Wiktionary xác nhận: 訡 = 吟 (dạng thay thế). Nghĩa: ngâm thơ, rên rỉ, thở dài. Bộ 言 (lời nói) phản ánh đây là hành động phát âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "衡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訡", "Unihan_Traditional (Chữ Phồn thể)": "訡", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "ngâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động ngâm thơ hoặc phát ra tiếng rên rỉ nhỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訮', '{"9000": "8670.0", "Chữ Trung Quốc": "訮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 訮 | hiên | tượng hình | chữ không rõ cấu trúc, dùng bộ 言 (ngôn) | 訮 là chữ thuộc bộ 言 (ngôn, lời nói). Cấu trúc nội bộ chưa được phân tích rõ ràng; chưa có nguồn học thuật xác định thành phần biểu âm hay biểu nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiên\": chữ hiếm thuộc bộ 言 (lời nói), âm Hán-Việt phỏng đoán theo Trung cổ âm. | Gương Hán-Việt | hiên — ít xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 訮 giúp nhận diện chữ hiếm trong bộ 言 (ngôn).", "Tự nguyên_Xie": "Chưa có dữ liệu glyph-origin học thuật cho 訮. Wiktionary chỉ ghi nhận âm đọc (xiān) mà không giải thích cấu tạo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "议", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訮", "Unihan_Traditional (Chữ Phồn thể)": "訮", "Pinyin_Xie": "xiān", "Âm Hán Việt_Xie": "hiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ chỉ hành động bàn luận hoặc tính từ miêu tả sự khéo nói trong văn ngôn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('証', '{"9000": "8671.0", "Chữ Trung Quốc": "証", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 言 | ngôn | biểu nghĩa | lời nói, lời | 正 | chinh | biểu âm | thẳng, đúng (cho âm) | 証 = 言 (Ngôn, biểu nghĩa: lời nói) + 正 (Chinh, biểu âm); chữ hình thanh. Phần 言 chỉ lĩnh vực ngôn ngữ/lời chứng, phần 正 cho âm đọc gần với zhèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chứng\": 言 (lời nói) + 正 (ngay thẳng) → lời nói ngay thẳng = bằng chứng, chứng nhận. | Gương Hán-Việt | chứng — trong \"chứng nhận\", \"chứng minh\", \"bằng chứng\" | Mở khoá kiến thức | Biết 証 mở khoá: chứng nhận (証明), chứng chỉ (証書), bằng chứng (証拠).", "Tự nguyên_Xie": "Tiểu triện | 証 là dạng giản thể của 證, được tạo bằng cách thay thành phần 登 bằng 正 (Han simp). Cấu tạo gốc: 言 (biểu nghĩa: lời nói) + 正 (biểu âm). Ban đầu mang nghĩa \"can gián, khuyên bảo\", về sau chuyển sang nghĩa \"bằng chứng, chứng minh\" (Digital Shinjigen 2017). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giấy chứng nhận", "Hạng Tần Suất (Jun Da)": "373.0", "Tần Suất % (Jun Da)": "69.4614274108", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 正", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "正", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "证", "Unihan_Traditional (Chữ Phồn thể)": "証", "Pinyin_Xie": "zhèng", "Âm Hán Việt_Xie": "chứng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ vật chứng thực hoặc động từ đứng trước tân ngữ để làm rõ sự thật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詷', '{"9000": "8672.0", "Chữ Trung Quốc": "詷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 詷 | đồng | tượng hình | chữ thuộc bộ 言, thành phần nội bộ chưa rõ | 詷 thuộc bộ 言 (ngôn). Cấu trúc chi tiết chưa được Wiktionary ghi nhận rõ; nhiều khả năng là hình thanh với âm phần gần 同 (đồng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": chữ hiếm bộ 言: cùng nhau). | Gương Hán-Việt | đồng — ít dùng độc lập trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 詷 giúp nhận diện dạng cổ của các từ đồng âm trong văn bản cổ.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có glyph-origin cho 詷. Chữ thuộc bộ 言 (lời nói), âm đọc tóng gần với 同 (đồng). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đinh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詷", "Unihan_Traditional (Chữ Phồn thể)": "詷", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng như tính từ chỉ sự đồng nhất hoặc động từ biểu thị việc bày tỏ ý kiến trong cổ văn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詺', '{"9000": "8673.0", "Chữ Trung Quốc": "詺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 言 | ngôn | biểu nghĩa | lời nói | 名 | danh | biểu âm | tên, danh (cho âm) | 詺 = 言 (Ngôn, biểu nghĩa: lời nói) + 名 (Danh, biểu âm); chữ hình thanh. Phần 名 cung cấp âm đọc gần mìng/míng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"danh\": 言 (lời nói) + 名 (tên gọi) → gọi tên bằng lời, đặt danh. | Gương Hán-Việt | danh — liên quan đến tên gọi, danh xưng trong văn bản cổ | Mở khoá kiến thức | Biết 詺 giúp đọc văn bản cổ bàn về cách gọi tên sự vật.", "Tự nguyên_Xie": "Theo Wiktionary, 詺 là chữ hình thanh: 言 (biểu nghĩa: lời nói) + 名 (biểu âm). Nghĩa cụ thể chưa được định nghĩa rõ (rfdef). Chưa có nguồn học thuật bổ sung. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "詺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 名", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言名", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "名", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詺", "Unihan_Traditional (Chữ Phồn thể)": "詺", "Pinyin_Xie": "mìng", "Âm Hán Việt_Xie": "danh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chủ yếu dùng làm động từ thể hiện hành động đặt tên hoặc định danh cho sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('諘', '{"9000": "8674.0", "Chữ Trung Quốc": "諘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 15 | nét | 諘 | biêu | tượng hình | chữ hiếm bộ 言, âm biǎo | 諘 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Âm đọc biǎo gợi 表 (biểu) là âm phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biêu\": chữ hiếm bộ 言: bày tỏ). | Gương Hán-Việt | biêu — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 諘 giúp nhận diện chữ hiếm trong văn bản cổ bộ 言.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 諘. Chữ thuộc bộ 言 (ngôn, lời nói), âm biǎo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蘘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 表", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言表", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "表", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "諘", "Unihan_Traditional (Chữ Phồn thể)": "諘", "Pinyin_Xie": "biǎo", "Âm Hán Việt_Xie": "biêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn để biểu thị việc ca ngợi công đức của ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謩', '{"9000": "8675.0", "Chữ Trung Quốc": "謩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 謩 | mô | tượng hình | chữ hiếm bộ 言, âm mò | 謩 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm mò gợi 莫 (mạc) hoặc 模 (mô) làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mô\": chữ hiếm bộ 言: khuôn mẫu) — lời khuôn mẫu cổ. | Gương Hán-Việt | mô — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 謩 giúp đọc văn bản cổ và nhận diện chữ hiếm bộ 言.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có glyph-origin cho 謩. Chữ thuộc bộ 言 (ngôn), âm mò. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưu đã định sẵn; tiến hành", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "謩", "Unihan_Traditional (Chữ Phồn thể)": "謩", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mưu lược đã định sẵn hoặc động từ bàn thảo kế hoạch trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謸', '{"9000": "8676.0", "Chữ Trung Quốc": "謸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 17 | nét | 謸 | ngạo | tượng hình | chữ hiếm bộ 言, âm áo | 謸 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được phân tích rõ. Âm áo gợi 傲 (ngạo) làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạo\": chữ hiếm bộ 言: kiêu ngạo) — lời kiêu ngạo. | Gương Hán-Việt | ngạo — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 謸 giúp nhận diện chữ hiếm trong văn bản cổ bộ 言.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 謸. Chữ thuộc bộ 言, âm áo. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "踸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 敖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言敖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謸", "Unihan_Traditional (Chữ Phồn thể)": "謸", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả thái độ kiêu căng hoặc động từ chỉ hành vi nói năng khinh thị. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('謽', '{"9000": "8677.0", "Chữ Trung Quốc": "謽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 謽 | cương | tượng hình | chữ hiếm bộ 言, âm jiàng | 謽 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Âm jiàng gợi 強/講 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": chữ hiếm bộ 言: giảng giải). | Gương Hán-Việt | cương — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 謽 giúp nhận diện chữ hiếm trong văn bản cổ bộ 言.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 謽. Chữ thuộc bộ 言, âm jiàng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "载", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "强 + 言", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱强言", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "强", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "謽", "Unihan_Traditional (Chữ Phồn thể)": "謽", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ đứng sau các phó từ chỉ mức độ để miêu tả tính cách bướng bỉnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讍', '{"9000": "8678.0", "Chữ Trung Quốc": "讍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 23 | nét | 讍 | ác | tượng hình | chữ hiếm bộ 言, âm è | 讍 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được phân tích rõ. Âm è gợi 惡/噩 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ác\": chữ hiếm bộ 言: xấu ác) — lời ác độc. | Gương Hán-Việt | ác — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 讍 giúp nhận diện chữ hiếm trong văn bản cổ bộ 言.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 讍. Chữ thuộc bộ 言, âm è. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "荍", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 噩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言噩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "噩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讍", "Unihan_Traditional (Chữ Phồn thể)": "讍", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ lời can ngăn ngay thẳng hoặc động từ can gián bề trên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讛', '{"9000": "8679.0", "Chữ Trung Quốc": "讛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 25 | nét | 讛 | dịch | tượng hình | chữ hiếm bộ 言, âm yì | 讛 thuộc bộ 言 (ngôn). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Âm yì gợi 易/義 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": chữ hiếm bộ 言: dễ dàng, biến đổi). | Gương Hán-Việt | dịch — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 讛 giúp nhận diện chữ hiếm trong văn bản cổ bộ 言.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 讛. Chữ thuộc bộ 言, âm yì. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghệ; như \"tài nghệ\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 藝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言藝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "藝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "讛", "Unihan_Traditional (Chữ Phồn thể)": "讛", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động nói mớ khi ngủ hoặc danh từ chỉ tài nghệ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貦', '{"9000": "8680.0", "Chữ Trung Quốc": "貦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 11 | nét | 貦 | ngoạn | tượng hình | chữ hiếm bộ 貝, dạng cổ của 玩 | 貦 thuộc bộ 貝 (bối — vỏ sò, tiền). Wiktionary ghi đây là biến thể cổ của 玩 (ngoạn — chơi đùa, thưởng ngoạn). Cấu trúc hình thanh chưa được phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoạn\": chữ cổ bộ 貝 (của cải), dạng xưa của 玩 — dùng của quý để thưởng ngoạn. | Gương Hán-Việt | ngoạn — trong \"thưởng ngoạn\", \"ngoạn mục\" (liên quan 玩) | Mở khoá kiến thức | Biết 貦 giúp nhận diện dạng cổ của 玩 (ngoạn) trong văn bản cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 貦 là dạng cũ (v — variant) của 玩. Nghĩa: chơi đùa, thưởng thức (to play, to enjoy). Âm wàn. Chữ này thuộc bộ 貝 (bối) trong cách phân tích cổ điển. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Dao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "貦", "Unihan_Traditional (Chữ Phồn thể)": "貦", "Pinyin_Xie": "wàn", "Âm Hán Việt_Xie": "ngoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước danh từ chỉ đồ vật quý giá để biểu thị sự thưởng ngoạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賳', '{"9000": "8681.0", "Chữ Trung Quốc": "賳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 16 | nét | 賳 | tai | tượng hình | chữ hiếm bộ 貝, âm zāi | 賳 thuộc bộ 貝 (bối). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Âm zāi gợi 災/哉 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tai\": chữ hiếm bộ 貝: tai họa) — của cải và tai họa. | Gương Hán-Việt | tai — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 賳 giúp nhận diện chữ hiếm trong văn bản cổ bộ 貝.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 賳. Chữ thuộc bộ 貝, âm zāi. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "賳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 哉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝哉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "哉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "賳", "Unihan_Traditional (Chữ Phồn thể)": "賳", "Pinyin_Xie": "zāi", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ tiền tài hoặc của cải trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贀', '{"9000": "8682.0", "Chữ Trung Quốc": "贀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 18 | nét | 贀 | ải | tượng hình | chữ hiếm bộ 貝, âm yì | 贀 thuộc bộ 貝 (bối). Cấu trúc nội bộ chưa được phân tích rõ trong Wiktionary. Âm yì. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ải\": chữ hiếm bộ 貝, âm yì — không rõ nghĩa trong tài liệu học thuật hiện có. | Gương Hán-Việt | ải — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 贀 giúp nhận diện chữ hiếm trong văn bản cổ bộ 貝.", "Tự nguyên_Xie": "Wiktionary ghi 贀 có âm yì (mc: y, oc: y) nhưng không định nghĩa rõ nghĩa (rfdef). Chữ thuộc bộ 貝. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "耀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "殹 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殹貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贀", "Unihan_Traditional (Chữ Phồn thể)": "贀", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc ban thưởng hoặc danh từ chỉ của cải trong cổ văn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贌', '{"9000": "8683.0", "Chữ Trung Quốc": "贌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 19 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền của | 菐 | biểu âm | thành phần cho âm pu | 贌 = 貝 (Bối, biểu nghĩa: tiền của) + 菐 (biểu âm, không có âm Hán-Việt phổ biến); chữ hình thanh. Phần 貝 chỉ phạm trù tài chính/thuê mướn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": 貝 (tiền của) + 菐 (âm bộc) → giao dịch tiền bạc, thuê mướn — từ điển Đài Loan ghi nghĩa \"thuê đất\". | Gương Hán-Việt | bộc — ít dùng trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 贌 giúp đọc văn bản pháp lý cổ về thuê mướn đất đai (tiếng Mân Nam, Đài Loan).", "Tự nguyên_Xie": "Theo Wiktionary, 贌 là chữ hình thanh: 貝 (biểu nghĩa: tiền của) + 菐 (biểu âm). Âm đọc pu. Chưa có nguồn học thuật bổ sung về glyph-origin chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "貝 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贌", "Unihan_Traditional (Chữ Phồn thể)": "贌", "Pinyin_Xie": "pu", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu dùng làm động từ trong văn bản cổ để chỉ việc thuê mướn hoặc thầu đất đai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趪', '{"9000": "8684.0", "Chữ Trung Quốc": "趪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 18 | nét | 趪 | hoàng | tượng hình | chữ hiếm bộ 走, âm huáng | 趪 thuộc bộ 走 (tẩu — chạy). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm huáng gợi 黄/皇 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": chữ hiếm bộ 走 (chạy): vàng) — chạy vội như tia sáng vàng. | Gương Hán-Việt | hoàng — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 趪 giúp nhận diện chữ hiếm trong văn bản cổ bộ 走.", "Tự nguyên_Xie": "Wiktionary chỉ có {{Han etym}} không chi tiết cho 趪. Chữ thuộc bộ 走 (tẩu — chạy). Âm huáng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Fu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趪", "Unihan_Traditional (Chữ Phồn thể)": "趪", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ để miêu tả dáng đi nhanh nhẹn, mạnh mẽ hoặc oai phong của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跁', '{"9000": "8685.0", "Chữ Trung Quốc": "跁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 跁 | bá | tượng hình | chữ hiếm bộ 足, âm bà | 跁 thuộc bộ 足 (túc — chân, bước đi). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm bà gợi 巴/把 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": chữ hiếm bộ 足 (chân), âm bà — động tác của chân, đi khập khiễng. | Gương Hán-Việt | bá — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 跁 giúp nhận diện chữ hiếm trong văn bản cổ bộ 足.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 跁. Chữ thuộc bộ 足 (túc), âm bà. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồi xổm; bò đi", "Hạng Tần Suất (Jun Da)": "8685.0", "Tần Suất % (Jun Da)": "99.9998129238", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跁", "Unihan_Traditional (Chữ Phồn thể)": "跁", "Pinyin_Xie": "bà", "Âm Hán Việt_Xie": "bả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để miêu tả tư thế ngồi xổm hoặc hành động bò, lết sát đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跈', '{"9000": "8686.0", "Chữ Trung Quốc": "跈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跈 | niễm | tượng hình | chữ hiếm bộ 足, âm niǎn | 跈 thuộc bộ 足 (túc — chân). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm niǎn gợi 碾/捻 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niễm\": chữ hiếm bộ 足 (chân): nghiền, xay) — bước chân nghiền đất. | Gương Hán-Việt | niễm — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 跈 giúp nhận diện chữ hiếm trong văn bản cổ bộ 足.", "Tự nguyên_Xie": "Wiktionary chỉ có {{Han etym}} không chi tiết cho 跈. Chữ thuộc bộ 足, âm niǎn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "興", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跈", "Unihan_Traditional (Chữ Phồn thể)": "跈", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hành động giẫm đạp hoặc bước lên một vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跒', '{"9000": "8687.0", "Chữ Trung Quốc": "跒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跒 | kháp | tượng hình | chữ hiếm bộ 足, âm qiǎ | 跒 thuộc bộ 足 (túc — chân). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm qiǎ gợi 恰/洽 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháp\": chữ hiếm bộ 足 (chân), âm qiǎ — động tác của bàn chân. | Gương Hán-Việt | kháp — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 跒 giúp nhận diện chữ hiếm trong văn bản cổ bộ 足.", "Tự nguyên_Xie": "Wiktionary ghi 跒 có âm qiǎ nhưng không định nghĩa rõ nghĩa (rfdef). Chữ thuộc bộ 足 (túc). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跒", "Unihan_Traditional (Chữ Phồn thể)": "跒", "Pinyin_Xie": "qiǎ", "Âm Hán Việt_Xie": "kháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm tính từ hoặc động từ để miêu tả dáng đi đứng khó khăn, khập khiễng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹖', '{"9000": "8688.0", "Chữ Trung Quốc": "蹖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹖 | sung | tượng hình | chữ hiếm bộ 足, âm chōng | 蹖 thuộc bộ 足 (túc — chân). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm chōng gợi 充/冲 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sung\": chữ hiếm bộ 足 (chân): va đập, xung) — bước chân xung lên mạnh mẽ. | Gương Hán-Việt | sung — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 蹖 giúp nhận diện chữ hiếm trong văn bản cổ bộ 足.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 蹖. Chữ thuộc bộ 足, âm chōng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rùng mình", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 舂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊舂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹖", "Unihan_Traditional (Chữ Phồn thể)": "蹖", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "sung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này dùng làm động từ để chỉ hành động giẫm đạp, va chạm hoặc trạng thái rùng mình, run rẩy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軇', '{"9000": "8689.0", "Chữ Trung Quốc": "軇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 21 | nét | 軇 | đạo | tượng hình | chữ hiếm bộ 身, âm dào | 軇 thuộc bộ 身 (thân — thân mình). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm dào gợi 道/导 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạo\": chữ hiếm bộ 身 (thân): con đường). | Gương Hán-Việt | đạo — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 軇 giúp nhận diện chữ hiếm trong văn bản cổ bộ 身.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 軇. Chữ thuộc bộ 身, âm dào. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chân", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 壽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身壽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "軇", "Unihan_Traditional (Chữ Phồn thể)": "軇", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này dùng làm tính từ để miêu tả vóc dáng cơ thể cao lớn hoặc dài rộng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軘', '{"9000": "8690.0", "Chữ Trung Quốc": "軘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 軘 | đồn | tượng hình | xe chiến đấu cổ; bộ 車 | 軘 thuộc bộ 車 (xa — xe). Wiktionary ghi nghĩa \"xe chiến tranh\" (war car). Cấu tạo chi tiết không được phân tích rõ. Âm tún gợi 吞/屯 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\": chữ bộ 車 (xe), nghĩa xe chiến đấu cổ — đồn binh có xe quân sự. | Gương Hán-Việt | đồn — trong \"đồn xa\" (軘車 — xe chiến tranh cổ) | Mở khoá kiến thức | Biết 軘 giúp đọc văn bản cổ về chiến xa, binh xa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 軘 nghĩa là xe chiến tranh (war car), dùng trong 軘車. Âm tún. Cấu tạo chi tiết không được giải thích rõ trong Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiến xa", "Hạng Tần Suất (Jun Da)": "8690.0", "Tần Suất % (Jun Da)": "99.9998165413", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軘", "Unihan_Traditional (Chữ Phồn thể)": "軘", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại xe quân sự hoặc chiến xa dùng trong chiến tranh thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軣', '{"9000": "8691.0", "Chữ Trung Quốc": "軣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 軣 | hoằng | tượng hình | chữ hiếm bộ 車, âm hōng | 軣 thuộc bộ 車 (xa — xe). Cấu trúc nội bộ chưa được Wiktionary phân tích rõ. Âm hōng gợi 红/轰 làm âm phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoằng\": chữ hiếm bộ 車 (xe): ầm ầm, bùng nổ) — tiếng xe lăn ầm ầm. | Gương Hán-Việt | hoằng — không phổ biến trong Hán-Việt hiện đại | Mở khoá kiến thức | Biết 軣 giúp nhận diện chữ hiếm trong văn bản cổ bộ 車.", "Tự nguyên_Xie": "Wiktionary không có glyph-origin cho 軣. Chữ thuộc bộ 車, âm hōng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "軣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "軣", "Unihan_Traditional (Chữ Phồn thể)": "軣", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hoằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ chỉ tiếng nổ lớn hoặc động từ mô tả âm thanh vang dội. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逇', '{"9000": "8692.0", "Chữ Trung Quốc": "逇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 逇 | độn | tượng hình | chạy trốn, lẩn tránh | 逇 là chữ hiếm, không có phân tích IDS trong dữ liệu hiện có. Theo ngữ âm học Hán-Việt, đọc là ''độn'', thuộc nhóm chữ có bộ 辶 (辵, chỉ sự di chuyển). Chữ biểu thị hành động trốn chạy. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độn\": chữ hiếm, nhớ qua âm ĐỘN — người độn thổ trốn biến mất. | Gương Hán-Việt | độn trong ''độn thổ'' (chui trốn) | Mở khoá kiến thức | Biết 逇 mở khoá nhóm chữ chỉ sự trốn tránh trong văn ngôn cổ.", "Tự nguyên_Xie": "逇 (độn) là chữ hiếm gặp trong văn bản hiện đại. Không có dữ liệu glyph-origin từ Wiktionary. Âm đọc dùn (dùn) gần với 遁 (độn: trốn chạy). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "采", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 地", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶地", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "地", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逇", "Unihan_Traditional (Chữ Phồn thể)": "逇", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động lẩn trốn hoặc rút lui khỏi nơi nguy hiểm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邔', '{"9000": "8693.0", "Chữ Trung Quốc": "邔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 5 | nét | 邔 | kỉ | tượng hình | địa danh cổ | 邔 là chữ chỉ địa danh, không có phân tích IDS trong dữ liệu. Bộ 邑 (ấp) thường xuất hiện trong các chữ chỉ địa danh. Wiktionary ghi pinyin qǐ, Middle Chinese và Old Chinese đều có. Chưa có nguồn phân tích cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỉ\": chữ địa danh cổ, nhớ qua bộ ẤP (邑) — một làng/ấp tên Kỉ đã mất trong lịch sử. | Gương Hán-Việt | kỉ trong địa danh cổ | Mở khoá kiến thức | Biết 邔 giúp đọc địa danh cổ trong văn bản Hán Nôm.", "Tự nguyên_Xie": "邔 (kỉ) là chữ chỉ địa danh cổ, Wiktionary chỉ ghi nhận phát âm (m=qǐ, mc=y, oc=y) mà không có phân tích glyph-origin chi tiết. Chữ thuộc bộ 邑 (ấp), nhóm chữ địa danh. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "锔", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "己 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰己阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "己", "Unihan_Simplified (Chữ Giản thể)": "邔", "Unihan_Traditional (Chữ Phồn thể)": "邔", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ địa danh cổ hoặc họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邥', '{"9000": "8694.0", "Chữ Trung Quốc": "邥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 邥 | thẩm | tượng hình | địa danh cổ 邥垂 | 邥 là chữ chỉ địa danh, Wiktionary ghi dùng trong 邥垂 (tên đất cổ). Bộ 邑 (ấp) thường xuất hiện trong địa danh. Pinyin shěn, phát âm Middle Chinese đã có. Chưa có nguồn phân tích IDS.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thẩm\": chữ địa danh cổ — ẤP (邑) tên Thẩm, chỉ còn trong sử sách. | Gương Hán-Việt | thẩm trong địa danh 邥垂 | Mở khoá kiến thức | Biết 邥 giúp nhận diện địa danh cổ 邥垂 trong sử liệu Hán văn.", "Tự nguyên_Xie": "邥 (thẩm) chỉ dùng trong địa danh 邥垂, theo Wiktionary. Không có phân tích glyph-origin. Thuộc bộ 邑 (ấp), nhóm địa danh làng xã. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "冘 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冘阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邥", "Unihan_Traditional (Chữ Phồn thể)": "邥", "Pinyin_Xie": "shěn", "Âm Hán Việt_Xie": "thẩm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ họ người hoặc địa danh thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邫', '{"9000": "8695.0", "Chữ Trung Quốc": "邫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 11 | nét | 邫 | bang | tượng hình | biến thể cổ của 邦, chỉ nước/bang | 邫 là biến thể cổ của 邦 (bang: nước, bang). Không có phân tích IDS trong dữ liệu. Thuộc bộ 邑 (ấp). Chưa có nguồn phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bang\": nhớ như 邦 (bang quốc) — 邫 là dạng viết cổ của cùng một chữ. | Gương Hán-Việt | bang trong ''bang quốc'' (nước, bang) | Mở khoá kiến thức | Biết 邫 giúp nhận diện biến thể cổ của 邦 trong văn bản Hán Nôm cổ.", "Tự nguyên_Xie": "邫 (bang) là biến thể cổ của 邦, không có dữ liệu glyph-origin từ Wiktionary. Pinyin bāng, nhóm địa danh/chính trị. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Pi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "丰 + 邑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丰邑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "邑", "Unihan_Simplified (Chữ Giản thể)": "邫", "Unihan_Traditional (Chữ Phồn thể)": "邫", "Pinyin_Xie": "bāng", "Âm Hán Việt_Xie": "bang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ đất nước, quốc gia hoặc các bang bang giao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鄽', '{"9000": "8696.0", "Chữ Trung Quốc": "鄽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 17 | nét | 廛 | chờn | biểu âm | 邑 | ấp | biểu nghĩa | thành ấp, khu dân cư | 鄽 = 廛 (Chờn, biểu âm) + 邑 (Ấp, biểu nghĩa: thành ấp). Chữ hình thanh: 廛 cho âm đọc gần, 邑 cho nghĩa địa điểm trong thành phố — chỉ khu chợ hoặc khu buôn bán trong thành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trần\": ẤP (邑) +廛 (khu chợ) = khu buôn bán đông đúc trong thành — nhớ \"phố trần\" náo nhiệt. | Gương Hán-Việt | trần trong ''phố trần'' (khu buôn bán) | Mở khoá kiến thức | Biết 鄽 mở khoá nghĩa khu buôn bán trong văn ngôn cổ điển.", "Tự nguyên_Xie": "鄽 (trần) là chữ hình thanh theo Wiktionary: {{Han compound|廛|邑|ls=psc|t2=city|c1=p|c2=s}}. Bộ 邑 (ấp, thành phố) cho nghĩa địa điểm đô thị; 廛 cho âm. Chữ chỉ khu buôn bán hoặc nhà ở trong thành phố cổ. Phát âm Middle Chinese và Old Chinese đã được ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鄄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "廛 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰廛阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "鄽", "Unihan_Traditional (Chữ Phồn thể)": "鄽", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "trần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ khu đất ở hoặc nơi buôn bán trong thành thị cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醆', '{"9000": "8697.0", "Chữ Trung Quốc": "醆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 醆 | trảm | tượng hình | chén rượu nhỏ | 醆 không có phân tích IDS chi tiết trong dữ liệu. Thuộc bộ 酉 (rượu). Wiktionary ghi nghĩa ''winecup'' và dùng như số từ (classifier). Chưa có nguồn phân tích cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trảm\": chén RƯỢU (酉) nhỏ xinh — TRẢM một hơi cạn chén! | Gương Hán-Việt | trảm trong ''trảm rượu'' (chén rượu) | Mở khoá kiến thức | Biết 醆 giúp đọc văn ngôn cổ về tiệc rượu và nghi lễ ẩm thực.", "Tự nguyên_Xie": "Tiểu triện | 醆 (trảm) thuộc bộ 酉 (rượu), Wiktionary ghi nghĩa ''chén rượu nhỏ'' (winecup) và cũng dùng như số từ đếm chén. Middle Chinese và Old Chinese đều được ghi nhận. Không có phân tích glyph-origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chén nhỏ", "Hạng Tần Suất (Jun Da)": "8697.0", "Tần Suất % (Jun Da)": "99.9998227427", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 戔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉戔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醆", "Unihan_Traditional (Chữ Phồn thể)": "醆", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "trản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loại chén nhỏ chuyên dùng để uống rượu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醽', '{"9000": "8698.0", "Chữ Trung Quốc": "醽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 24 | nét | 醽 | linh | tượng hình | tên một loại rượu cổ | 醽 thuộc bộ 酉 (rượu). Không có phân tích IDS. Wiktionary ghi chú dùng trong 醽醁 (tên loại rượu). Middle Chinese và Old Chinese đều ghi nhận. Chưa có nguồn phân tích cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": RƯỢU (酉) mang tên LINH — một loại mỹ tửu thanh linh của người xưa. | Gương Hán-Việt | linh trong ''linh lộc'' (tên rượu cổ) | Mở khoá kiến thức | Biết 醽 giúp đọc văn ngôn cổ về các loại rượu quý thời xưa.", "Tự nguyên_Xie": "醽 (linh) là tên một loại rượu cổ, thuộc bộ 酉 (rượu). Wiktionary chỉ ghi phát âm (m=líng, mc=y, oc=y) và dùng trong 醽醁 mà không có phân tích glyph-origin. Chưa có nguồn học thuật xác nhận cấu trúc nội bộ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rượu xanh", "Hạng Tần Suất (Jun Da)": "8698.0", "Tần Suất % (Jun Da)": "99.9998237763", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 霝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉霝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "霝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醽", "Unihan_Traditional (Chữ Phồn thể)": "醽", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ một loại rượu ngon màu xanh thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釥', '{"9000": "8699.0", "Chữ Trung Quốc": "釥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 釥 | khiếu | tượng hình | chữ Hán hiếm, không rõ nghĩa cụ thể | 釥 không có phân tích IDS trong dữ liệu. Wiktionary ghi pinyin qiǎo, Middle Chinese và Old Chinese. Thuộc bộ 金 (kim loại). Không rõ nghĩa cụ thể (rfdef). Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếu\": chữ KIM LOẠI (金) hiếm gặp — KHIẾU một thứ kim loại đặc biệt thời cổ. | Gương Hán-Việt | khiếu trong văn ngôn cổ | Mở khoá kiến thức | Biết 釥 giúp nhận diện chữ Hán cổ hiếm trong văn bản kim loại học cổ.", "Tự nguyên_Xie": "釥 (khiếu) thuộc bộ 金 (kim loại), Wiktionary ghi phát âm (m=qiǎo, mc=y, oc=y) nhưng không có định nghĩa cụ thể (rfdef). Không có phân tích glyph-origin. Chưa có nguồn học thuật xác nhận nghĩa và cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "釥", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 小", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金小", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "小", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釥", "Unihan_Traditional (Chữ Phồn thể)": "釥", "Pinyin_Xie": "qiǎo", "Âm Hán Việt_Xie": "khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ chỉ tính chất khéo léo hoặc chất lượng vàng tốt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈂', '{"9000": "8700.0", "Chữ Trung Quốc": "鈂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈂 | đâm | tượng hình | chữ Hán hiếm thuộc bộ kim | 鈂 không có phân tích IDS chi tiết trong dữ liệu. Thuộc bộ 金 (kim loại). Wiktionary ghi hai âm (chén/qín) nhưng HV dùng âm ''đâm''. Chưa có nguồn phân tích cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đâm\": KIM LOẠI (金) nhọn — ĐÂM thẳng, sắc bén như lưỡi dao thép. | Gương Hán-Việt | đâm trong ''đâm chém'' (đâm đầu, bổ nhào) | Mở khoá kiến thức | Biết 鈂 giúp nhận diện âm Hán-Việt ''đâm'' trong từ vựng Việt gốc Hán.", "Tự nguyên_Xie": "Tiểu triện | 鈂 (đâm) thuộc bộ 金 (kim loại), Wiktionary ghi hai phát âm (m=chén,qín) và Middle Chinese, Old Chinese đều có. Không có định nghĩa cụ thể (rfdef). Không có phân tích glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đâm; như \"đâm chán; đâm chém; đâm đầu vào chỗ chết; đâm trồi\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈂", "Unihan_Traditional (Chữ Phồn thể)": "鈂", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động đâm hoặc đâm chém. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋷', '{"9000": "8701.0", "Chữ Trung Quốc": "鋷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 鋷 | tụy | tượng hình | chữ Hán hiếm thuộc bộ kim | 鋷 không có phân tích IDS trong dữ liệu. Thuộc bộ 金 (kim loại). Wiktionary không có dữ liệu glyph-origin. Pinyin zuì. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\": chữ KIM LOẠI (金) hiếm — TỤY tập chất kim hiếm của người xưa. | Gương Hán-Việt | tụy trong văn ngôn cổ | Mở khoá kiến thức | Biết 鋷 giúp nhận diện chữ Hán hiếm trong kim loại học cổ.", "Tự nguyên_Xie": "鋷 (tụy) là chữ hiếm thuộc bộ 金 (kim loại). Không có dữ liệu glyph-origin từ Wiktionary. Không có nghĩa cụ thể được xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鋷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 取", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金取", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "取", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋷", "Unihan_Traditional (Chữ Phồn thể)": "鋷", "Pinyin_Xie": "zuì", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ cái kẹp hoặc cái kìm nhỏ bằng kim loại trong thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎲', '{"9000": "8702.0", "Chữ Trung Quốc": "鎲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 鎲 | thưởng | tượng hình | tên một loại binh khí/công cụ kim loại cổ | 鎲 không có phân tích IDS trong dữ liệu. Thuộc bộ 金 (kim loại). Không có dữ liệu glyph-origin. Pinyin tǎng. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thưởng\": chữ KIM LOẠI (金) cổ — một loại vũ khí hay công cụ thời xưa, nay chỉ THƯỞNG thức trong từ điển. | Gương Hán-Việt | thưởng trong văn ngôn cổ về binh khí | Mở khoá kiến thức | Biết 鎲 giúp nhận diện tên binh khí cổ trong văn bản Hán Nôm.", "Tự nguyên_Xie": "鎲 (thưởng) là chữ hiếm thuộc bộ 金 (kim loại), pinyin tǎng. Không có dữ liệu glyph-origin từ Wiktionary. Chưa có nguồn học thuật xác nhận nghĩa và cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鎢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 党", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金党", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "党", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "镋", "Unihan_Traditional (Chữ Phồn thể)": "鎲", "Pinyin_Xie": "tǎng", "Âm Hán Việt_Xie": "thưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong văn bản cổ để chỉ một loại vũ khí có mũi nhọn hoặc nguyên tố hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐑', '{"9000": "8703.0", "Chữ Trung Quốc": "鐑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐑 | khiết | tượng hình | chữ Hán hiếm thuộc bộ kim | 鐑 không có phân tích IDS trong dữ liệu. Thuộc bộ 金 (kim loại). Wiktionary không có dữ liệu glyph-origin. Pinyin qiè. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiết\": chữ KIM LOẠI (金) hiếm — KHIẾT tịnh như kim loại tinh luyện chưa ai biết đến. | Gương Hán-Việt | khiết trong văn ngôn cổ | Mở khoá kiến thức | Biết 鐑 giúp nhận diện chữ Hán hiếm trong kim loại học cổ.", "Tự nguyên_Xie": "鐑 (khiết) là chữ hiếm thuộc bộ 金 (kim loại), pinyin qiè. Không có dữ liệu glyph-origin từ Wiktionary. Chưa có nguồn học thuật xác nhận nghĩa và cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鑑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 結", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金結", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "結", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐑", "Unihan_Traditional (Chữ Phồn thể)": "鐑", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động cắt khắc hoặc danh từ chỉ dụng cụ khóa trong văn bản cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐬', '{"9000": "8704.0", "Chữ Trung Quốc": "鐬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 21 | nét | 鐬 | huệ | tượng hình | chữ Hán hiếm thuộc bộ kim | 鐬 không có phân tích IDS trong dữ liệu. Thuộc bộ 金 (kim loại). Wiktionary ghi pinyin huì, không có định nghĩa cụ thể (rfdef). Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huệ\": chữ KIM LOẠI (金) hiếm — ân HUỆ của đồ cổ kim loại chưa ai giải mã. | Gương Hán-Việt | huệ trong văn ngôn cổ về đồ kim loại | Mở khoá kiến thức | Biết 鐬 giúp nhận diện chữ Hán hiếm trong kim loại học cổ.", "Tự nguyên_Xie": "鐬 (huệ) là chữ hiếm thuộc bộ 金 (kim loại), Wiktionary chỉ ghi phát âm huì và Middle Chinese, Old Chinese — không có định nghĩa (rfdef). Không có phân tích glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xuất hiện hưng thịnh; tiếng chuông xe đạp", "Hạng Tần Suất (Jun Da)": "8704.0", "Tần Suất % (Jun Da)": "99.9998330784", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 歲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金歲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐬", "Unihan_Traditional (Chữ Phồn thể)": "鐬", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả tiếng chuông xe ngựa hoặc làm tính từ chỉ sự hưng thịnh. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑴', '{"9000": "8705.0", "Chữ Trung Quốc": "鑴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 26 | nét | 鑴 | quỳ | tượng hình | loại đỉnh cổ hoặc hào quang mặt trời | 鑴 không có phân tích IDS trong dữ liệu. Thuộc bộ 金 (kim loại). Wiktionary ghi pinyin xī (Cantonese: kwai4), và nghĩa ''đỉnh cổ'' hoặc ''hào quang mặt trời''. Chưa có nguồn phân tích IDS.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": KIM LOẠI (金) cổ kính — cái vạc QUỲ cổ đại toả hào quang như mặt trời. | Gương Hán-Việt | quỳ trong văn ngôn cổ về đồ đồng cổ | Mở khoá kiến thức | Biết 鑴 giúp nhận diện chữ Hán hiếm trong nghiên cứu đồ đồng cổ đại.", "Tự nguyên_Xie": "鑴 (quỳ) là chữ hiếm thuộc bộ 金, Wiktionary ghi pinyin xī nhưng Cantonese kwai4 — nghĩa là một loại đỉnh (vạc) thời xưa hoặc vầng hơi toả ra bên mặt trời. Không có phân tích glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loại đỉnh (vạc) thời xưa; vầng hơi toả ra bên mặt trời", "Hạng Tần Suất (Jun Da)": "8705.0", "Tần Suất % (Jun Da)": "99.999834112", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 巂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金巂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鑴", "Unihan_Traditional (Chữ Phồn thể)": "鑴", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "huề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong thư tịch cổ để chỉ một loại dụng cụ nấu ăn bằng đồng hoặc hiện tượng khí tượng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镻', '{"9000": "8706.0", "Chữ Trung Quốc": "镻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 長 | Số nét | 12 | nét | 镻 | điệt | tượng hình | tên rắn độc trong văn bản cổ | 镻 không có phân tích IDS trong dữ liệu. Bộ gốc là 長 (trường). Wiktionary không có dữ liệu. Pinyin dié. Nghĩa ghi nhận là tên rắn độc. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": chữ hiếm chỉ loài RẮN ĐỘC — ĐIỆT một vết cắn, chết ngay! | Gương Hán-Việt | điệt trong văn cổ về rắn | Mở khoá kiến thức | Biết 镻 giúp nhận diện tên rắn độc trong văn bản cổ.", "Tự nguyên_Xie": "镻 (điệt) là chữ hiếm, pinyin dié, nghĩa là tên một loài rắn độc trong văn bản cổ. Không có dữ liệu glyph-origin từ Wiktionary. Chưa có nguồn học thuật xác nhận cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tên rắn độc trong văn bản cổ", "Hạng Tần Suất (Jun Da)": "8706.0", "Tần Suất % (Jun Da)": "99.9998351455", "GavinGrover_Once (Chiết tự trực tiếp)": "镸 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰镸失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "镸", "Unihan_Simplified (Chữ Giản thể)": "镻", "Unihan_Traditional (Chữ Phồn thể)": "镻", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các tài liệu cổ sinh vật học hoặc thư tịch cổ để chỉ một loài rắn độc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閰', '{"9000": "8707.0", "Chữ Trung Quốc": "閰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 14 | nét | 閰 | cự | tượng hình | đóng cửa lại | 閰 không có phân tích IDS trong dữ liệu. Thuộc bộ 門 (cửa). Wiktionary ghi pinyin jú và nghĩa ''to close''. Middle Chinese và Old Chinese đều ghi nhận. Chưa có nguồn phân tích IDS.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": CỬA (門) đóng CỰ — cánh cửa lớn khép chặt, không cho ai vào. | Gương Hán-Việt | cự trong văn ngôn cổ | Mở khoá kiến thức | Biết 閰 giúp nhận diện chữ Hán hiếm trong nhóm bộ Môn.", "Tự nguyên_Xie": "閰 (cự) thuộc bộ 門 (cửa), Wiktionary ghi nghĩa ''to close'' — đóng cửa. Phát âm jú, Middle Chinese và Old Chinese đều ghi nhận. Không có phân tích glyph-origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 臼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門臼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閰", "Unihan_Traditional (Chữ Phồn thể)": "閰", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ dùng để chỉ ngưỡng cửa hoặc ranh giới lối ra vào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閳', '{"9000": "8708.0", "Chữ Trung Quốc": "閳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 15 | nét | 閳 | xiển | tượng hình | biến thể cổ của 闡, nghĩa là mở ra, làm sáng tỏ | 閳 là biến thể cổ của 闡 (xiển: mở ra, làm sáng tỏ). Thuộc bộ 門 (cửa). Không có phân tích IDS riêng. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiển\": CỬA (門) mở rộng — XIỂN minh, giải thích rõ ràng như cửa mở toang. | Gương Hán-Việt | xiển trong ''xiển minh'' (làm sáng tỏ) | Mở khoá kiến thức | Biết 閳 giúp nhận diện biến thể cổ của 闡 trong văn bản cổ điển.", "Tự nguyên_Xie": "閳 (xiển) là biến thể cổ của 闡, nghĩa là mở rộng cánh cửa, làm sáng tỏ. Thuộc bộ 門 (cửa). Không có phân tích glyph-origin riêng. Chưa có nguồn học thuật xác nhận cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 闡", "Hạng Tần Suất (Jun Da)": "8708.0", "Tần Suất % (Jun Da)": "99.9998366959", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 車", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "車", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閳", "Unihan_Traditional (Chữ Phồn thể)": "閳", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "xiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này chủ yếu làm động từ đứng trước tân ngữ để diễn tả việc làm rõ nghĩa lý. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閴', '{"9000": "8709.0", "Chữ Trung Quốc": "閴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 15 | nét | 閴 | khúc | tượng hình | chữ Hán hiếm thuộc bộ Môn | 閴 không có phân tích IDS trong dữ liệu. Thuộc bộ 門 (cửa). Wiktionary không có dữ liệu glyph-origin. Pinyin qù. Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khúc\": CỬA (門) KHÚC khuỷu — con đường vòng vèo qua cửa hẹp. | Gương Hán-Việt | khúc trong văn ngôn cổ | Mở khoá kiến thức | Biết 閴 giúp nhận diện chữ Hán hiếm trong nhóm bộ Môn.", "Tự nguyên_Xie": "閴 (khúc) là chữ hiếm thuộc bộ 門 (cửa), pinyin qù. Không có dữ liệu glyph-origin từ Wiktionary. Chưa có nguồn học thuật xác nhận nghĩa và cấu trúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鴴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "閴", "Unihan_Traditional (Chữ Phồn thể)": "閴", "Pinyin_Xie": "qù", "Âm Hán Việt_Xie": "khúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ chỉ không gian hoặc trạng thái tĩnh lặng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陮', '{"9000": "8710.0", "Chữ Trung Quốc": "陮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 10 | nét | 陮 | đuệ | tượng hình | chữ Hán hiếm thuộc bộ Phụ (đồi, sườn núi) | 陮 không có phân tích IDS trong dữ liệu. Thuộc bộ 阜 (phụ: đồi, sườn núi). Wiktionary ghi pinyin duì, không có định nghĩa cụ thể (rfdef). Chưa có nguồn phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đuệ\": ĐỒI NÚI (阜) hiểm trở — ĐUỆ một sườn núi cổ quái không ai đặt chân tới. | Gương Hán-Việt | đuệ trong văn ngôn cổ | Mở khoá kiến thức | Biết 陮 giúp nhận diện chữ Hán hiếm trong nhóm bộ Phụ (đồi núi).", "Tự nguyên_Xie": "陮 (đuệ) là chữ hiếm thuộc bộ 阜 (đồi núi), pinyin duì. Wiktionary chỉ ghi phát âm (m=duì, mc=y, oc=y) và không có định nghĩa. Không có phân tích glyph-origin. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陮", "Unihan_Traditional (Chữ Phồn thể)": "陮", "Pinyin_Xie": "duì", "Âm Hán Việt_Xie": "duê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp thành từ ghép để miêu tả địa hình núi non hiểm trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陻', '{"9000": "8711.0", "Chữ Trung Quốc": "陻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 陻 | nhân | tượng hình | gò đất, vùi lấp | 陻 là chữ độc thể, chưa xác định rõ cấu trúc nội bộ. Toàn bộ chữ biểu thị ý nghĩa vùi lấp, đắp đập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhân\": bộ 阜 (gò đất) gợi hình ảnh đắp đất vùi lấp — chữ hiếm dùng trong văn cổ. | Gương Hán-Việt | 陻 ít gặp trong từ Hán-Việt thông dụng; liên hệ bộ 阜 như trong ''giang sơn''. | Mở khoá kiến thức | Biết 陻 giúp nhận ra nhóm chữ bộ 阜 chỉ địa hình: 陵, 陸, 陷.", "Tự nguyên_Xie": "陻 không có nguồn từ nguyên Wiktionary. Chữ thuộc bộ 阜 (phụ, gò đất), âm Hán-Việt phục nguyên theo Trung cổ âm là ''nhân'' (Middle Chinese: ʔin). Ý nghĩa liên quan đến đất đai, gò mô, đắp ngăn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùi lấp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "陻", "Unihan_Traditional (Chữ Phồn thể)": "陻", "Pinyin_Xie": "yīn", "Âm Hán Việt_Xie": "nhân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động lấp đất, ngăn sông hoặc che giấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霂', '{"9000": "8712.0", "Chữ Trung Quốc": "霂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 15 | nét | 雨 | vũ | biểu nghĩa | mưa | 沐 | mộc | biểu âm | gội | 霂 = 雨 (Vũ, biểu nghĩa: mưa) + 沐 (Mộc, biểu âm); chữ hình thanh. Phần 雨 cho biết liên quan đến mưa, phần 沐 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"móc\": 雨 (mưa) + 沐 (gội) — mưa phùn như sương móc gội nhẹ lên vạn vật. | Gương Hán-Việt | 霂 xuất hiện trong cụm 霢霂 (mạch mộc) chỉ mưa nhỏ rỉ rả. | Mở khoá kiến thức | Biết 霂 giúp đọc thơ văn cổ tả cảnh mưa phùn; bộ 雨 chỉ các hiện tượng mưa.", "Tự nguyên_Xie": "Theo Wiktionary, 霂 là chữ hình thanh: 雨 (biểu nghĩa, mưa) kết hợp với 沐 (biểu âm). Âm Hán-Việt ''móc'' (hoặc ''mộc'') phản ánh Trung cổ âm muk. Chữ chỉ mưa phùn, mưa nhỏ; thường gặp trong cụm 霢霂 (mạch mộc, mưa rào nhỏ giọt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa phùn", "Hạng Tần Suất (Jun Da)": "8712.0", "Tần Suất % (Jun Da)": "99.9998403134", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 沐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨沐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霂", "Unihan_Traditional (Chữ Phồn thể)": "霂", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong văn thơ cổ để tả cảnh mưa bụi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靵', '{"9000": "8713.0", "Chữ Trung Quốc": "靵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 靵 | nữu | tượng hình | chày, cối giã | 靵 là chữ độc thể thuộc bộ 革 (cách, da thuộc). Cấu trúc nội bộ chưa phân tích được qua nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": bộ 革 (da) + âm nữu — hình ảnh chiếc chày bọc da dùng trong nghi lễ cổ xưa. | Gương Hán-Việt | 靵 ít dùng trong tiếng Việt; bộ 革 gặp trong ''cách mạng'' (革命). | Mở khoá kiến thức | Biết bộ 革 giúp nhận diện các chữ liên quan đến da: 鞋, 鞭, 鞍.", "Tự nguyên_Xie": "靵 không có nguồn từ nguyên Wiktionary. Thuộc bộ 革 (da thuộc), âm Hán-Việt phục nguyên theo Trung cổ âm niǔ là ''nữu''. Ý nghĩa ghi là ''chày'' (pestle). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chày", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靵", "Unihan_Traditional (Chữ Phồn thể)": "靵", "Pinyin_Xie": "niǔ", "Âm Hán Việt_Xie": "nữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dây buộc hoặc bộ phận bằng da trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞊', '{"9000": "8714.0", "Chữ Trung Quốc": "鞊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 鞊 | tiết | tượng hình | vật làm bằng da | 鞊 là chữ độc thể thuộc bộ 革 (cách, da thuộc). Cấu trúc nội bộ chưa được phân tích rõ trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": bộ 革 (da) + âm tiết — vật dụng da cứng, gọn tiết. | Gương Hán-Việt | 鞊 ít gặp trong từ Hán-Việt; bộ 革 như trong ''cách mạng''. | Mở khoá kiến thức | Biết bộ 革 giúp nhận diện: 鞋 (hài, giày), 鞭 (tiên, roi), 鞍 (yên, yên ngựa).", "Tự nguyên_Xie": "鞊 không có nguồn từ nguyên Wiktionary chi tiết. Thuộc bộ 革 (da thuộc), âm Hán-Việt phục nguyên theo Trung cổ âm jié là ''tiết''. Nghĩa cụ thể không rõ ràng trong nguồn tham khảo hiện có. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lý", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞊", "Unihan_Traditional (Chữ Phồn thể)": "鞊", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần dây da dùng để điều khiển ngựa hoặc thắt lưng da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞛', '{"9000": "8715.0", "Chữ Trung Quốc": "鞛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 鞛 | bổng | tượng hình | vật da, bao đựng cung | 鞛 là chữ độc thể thuộc bộ 革 (cách, da thuộc). Cấu trúc nội bộ chưa rõ theo nguồn học thuật hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": bộ 革 (da) + âm bổng — bao da căng phồng đựng cung tên. | Gương Hán-Việt | 鞛 ít dùng trong tiếng Việt; liên hệ 鞞 (bao cung). | Mở khoá kiến thức | Biết bộ 革 giúp nhận diện chữ liên quan đến đồ dùng da: 鞋, 鞭, 鞍.", "Tự nguyên_Xie": "鞛 không có nguồn từ nguyên Wiktionary. Thuộc bộ 革, âm Hán-Việt phục nguyên theo Trung cổ âm běng là ''bổng''. Nghĩa 鞞 (bao đựng cung) được ghi chú; là chữ đồng nghĩa hoặc dị thể của 鞞. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鞞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞛", "Unihan_Traditional (Chữ Phồn thể)": "鞛", "Pinyin_Xie": "běng", "Âm Hán Việt_Xie": "bổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ bao đựng kiếm hoặc phần trang trí trên bao kiếm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韴', '{"9000": "8716.0", "Chữ Trung Quốc": "韴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 13 | nét | 韴 | tạp | tượng hình | âm nhạc, thanh âm | 韴 là chữ độc thể thuộc bộ 音 (âm, thanh âm). Cấu trúc chi tiết chưa được xác lập qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạp\": bộ 音 (âm) + âm tạp — âm thanh hỗn tạp, nhiều giọng xen nhau. | Gương Hán-Việt | 韴 ít dùng; bộ 音 gặp trong ''âm nhạc'' (音樂), ''âm thanh''. | Mở khoá kiến thức | Biết bộ 音 giúp nhận ra: 韵 (vận, vần), 韶 (thiều, nhạc hay).", "Tự nguyên_Xie": "韴 thuộc bộ 音 (âm nhạc, thanh âm), âm Hán-Việt phục nguyên theo Trung cổ âm zá là ''tạp''. Wiktionary ghi nhận có Middle Chinese và Old Chinese nhưng không có nghĩa định rõ (rfdef). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 帀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音帀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韴", "Unihan_Traditional (Chữ Phồn thể)": "韴", "Pinyin_Xie": "zá", "Âm Hán Việt_Xie": "tạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ trong văn ngôn để chỉ dây da trang trí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韷', '{"9000": "8717.0", "Chữ Trung Quốc": "韷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 14 | nét | 韷 | lạc | tượng hình | âm thanh, nhạc | 韷 là chữ độc thể thuộc bộ 音 (âm, thanh âm). Cấu trúc nội bộ chưa được phân tích rõ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": bộ 音 (âm nhạc) + âm lạc — âm nhạc mang lại niềm vui lạc thú. | Gương Hán-Việt | 韷 ít dùng; bộ 音 gặp trong ''âm nhạc'' (音樂). | Mở khoá kiến thức | Biết bộ 音 mở ra: 韵 (vận), 韶 (thiều), 響 (hưởng, vang).", "Tự nguyên_Xie": "韷 thuộc bộ 音, âm Hán-Việt phục nguyên theo Trung cổ âm lè là ''lạc''. Không có nguồn từ nguyên Wiktionary. Nghĩa chưa xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "韷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韷", "Unihan_Traditional (Chữ Phồn thể)": "韷", "Pinyin_Xie": "lè", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này dùng làm danh từ chỉ tiếng nhạc hoặc từ tượng thanh mô phỏng âm thanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('頋', '{"9000": "8718.0", "Chữ Trung Quốc": "頋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 13 | nét | 頋 | ngạc | tượng hình | ngoảnh đầu nhìn, chăm sóc | 頋 là chữ độc thể thuộc bộ 頁 (hiệt, đầu/mặt). Cấu trúc nội bộ chưa rõ nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": bộ 頁 (đầu) — ngoảnh đầu ngạc nhiên nhìn lại. | Gương Hán-Việt | 頋 ít dùng; bộ 頁 gặp trong ''đề mục'' (題目). | Mở khoá kiến thức | Biết bộ 頁 giúp nhận ra: 顧 (cố, ngoảnh nhìn), 頭 (đầu), 額 (ngạch, trán).", "Tự nguyên_Xie": "頋 không có nguồn từ nguyên Wiktionary. Thuộc bộ 頁, âm Hán-Việt phục nguyên theo Trung cổ âm ě là ''ngạc''. Nghĩa ghi là ''ngoảnh đầu nhìn, chăm sóc''. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鋋", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "厄 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰厄頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "頋", "Unihan_Traditional (Chữ Phồn thể)": "頋", "Pinyin_Xie": "ě", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ để chỉ một loại binh khí ngắn thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顕', '{"9000": "8719.0", "Chữ Trung Quốc": "顕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 18 | nét | 顕 | hiển | tượng hình | hiển thị, biểu lộ rõ ràng | 顕 là dạng chữ Nhật (shinjitai) của 顯 (giản thể: 显). Bộ 頁 (hiệt, đầu/mặt) làm nghĩa phù; phần trên rút gọn từ 𢇁 thành 业.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiển\": bộ 頁 (mặt) + nghĩa hiển lộ — khi điều gì hiển ra, nó lộ rõ trước mặt. | Gương Hán-Việt | 顕 (dạng Nhật của 顯) gặp trong ''hiển vi kính'' (顕微鏡, kính hiển vi). | Mở khoá kiến thức | Biết 顕 giúp đọc tài liệu Nhật-Hán: 顕微鏡 (kính hiển vi), 顕著 (rõ rệt).", "Tự nguyên_Xie": "Theo Wiktionary, 顕 là dạng shinjitai của Nhật Bản, rút gọn từ 顯 bằng cách thay 𢇁 bằng 业. Chữ gốc 顯 chỉ sự hiển lộ, rõ ràng, biểu lộ. Hán-Việt đọc là ''hiển'', như trong ''hiển hiện'', ''hiển thị''. Âm Nhật: けん (ken). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Biến thể tiếng Nhật của 顯", "Hạng Tần Suất (Jun Da)": "8719.0", "Tần Suất % (Jun Da)": "99.999845998", "GavinGrover_Once (Chiết tự trực tiếp)": "显 + 頁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰显頁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "显", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "頁", "Unihan_Simplified (Chữ Giản thể)": "顕", "Unihan_Traditional (Chữ Phồn thể)": "顕", "Pinyin_Xie": "xiǎn", "Âm Hán Việt_Xie": "hiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này dùng làm tính từ chỉ sự rõ ràng hoặc động từ biểu thị việc làm lộ ra. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顨', '{"9000": "8720.0", "Chữ Trung Quốc": "顨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 21 | nét | 顨 | tốn | tượng hình | nghiêng đầu, khiêm nhường | 顨 là chữ độc thể thuộc bộ 頁 (hiệt, đầu/mặt). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tốn\": bộ 頁 (đầu) + âm tốn — cúi đầu tốn kính, khiêm nhường. | Gương Hán-Việt | 顨 ít dùng; bộ 頁 gặp trong ''đề mục'', ''lĩnh hội''. | Mở khoá kiến thức | Biết bộ 頁 mở ra: 顧 (cố), 額 (ngạch), 題 (đề).", "Tự nguyên_Xie": "顨 không có nguồn từ nguyên Wiktionary. Thuộc bộ 頁, âm Hán-Việt phục nguyên theo Trung cổ âm xùn là ''tốn''. Nghĩa chưa xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "顨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𩔊 + 丌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𩔊丌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "𩔊", "Unihan_Simplified (Chữ Giản thể)": "顨", "Unihan_Traditional (Chữ Phồn thể)": "顨", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tốn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này dùng làm tính từ chỉ thái độ cung kính hoặc động từ nhường nhịn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飷', '{"9000": "8721.0", "Chữ Trung Quốc": "飷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 飷 | giải | tượng hình | thức ăn | 飷 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": bộ 食 (ăn) — ăn uống để giải tỏa đói khát. | Gương Hán-Việt | 飷 ít dùng; bộ 食 gặp trong ''thực phẩm'', ''ẩm thực''. | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn, cơm), 飲 (ẩm, uống), 餐 (xan, bữa ăn).", "Tự nguyên_Xie": "Theo Wiktionary, 飷 có MC và OC được ghi nhận nhưng nghĩa chưa định rõ (rfdef). Thuộc bộ 食 (thức ăn), âm Hán-Việt phục nguyên theo jiě là ''giải''. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "飷", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "飷", "Unihan_Traditional (Chữ Phồn thể)": "飷", "Pinyin_Xie": "jiě", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này dùng làm động từ chỉ hành vi ăn uống hoặc nuốt thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('飺', '{"9000": "8722.0", "Chữ Trung Quốc": "飺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 15 | nét | 飺 | từ | tượng hình | thức ăn, cháo | 飺 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"từ\": bộ 食 (ăn) + âm từ — loại thức ăn dạng cháo từ thuở xưa. | Gương Hán-Việt | 飺 ít dùng; bộ 食 gặp trong ''thực phẩm'', ''ẩm thực''. | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn), 飲 (ẩm), 餐 (xan).", "Tự nguyên_Xie": "Theo Wiktionary, 飺 có MC cí và OC được ghi nhận nhưng nghĩa chưa định rõ (rfdef). Thuộc bộ 食, âm Hán-Việt phục nguyên theo cí là ''từ''. Nghĩa ghi là ''Chao''. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chao", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "此 + 食", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱此食", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "食", "Unihan_Simplified (Chữ Giản thể)": "飺", "Unihan_Traditional (Chữ Phồn thể)": "飺", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ sự chán ghét thức ăn hoặc làm danh từ chỉ thức ăn thừa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餀', '{"9000": "8723.0", "Chữ Trung Quốc": "餀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 13 | nét | 餀 | hải | tượng hình | thức ăn nhiễm độc | 餀 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hải\": bộ 食 (ăn) — thức ăn bị hỏng gây hại (hại) như biển hải đổi màu. | Gương Hán-Việt | 餀 ít dùng; bộ 食 gặp trong ''thực phẩm'', ''ẩm thực''. | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn, cơm), 飲 (ẩm, uống), 饑 (ky, đói kém).", "Tự nguyên_Xie": "Theo Wiktionary, 餀 có MC hài và OC được ghi nhận nhưng nghĩa chưa định rõ (rfdef). Thuộc bộ 食, âm Hán-Việt phục nguyên theo hài là ''hải''. Nghĩa ghi là ''thức ăn nhiễm độc'' (tainted food). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thức ăn nhiễm độc", "Hạng Tần Suất (Jun Da)": "8723.0", "Tần Suất % (Jun Da)": "99.9998490987", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 艾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠艾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餀", "Unihan_Traditional (Chữ Phồn thể)": "餀", "Pinyin_Xie": "hài", "Âm Hán Việt_Xie": "hải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để chỉ thức ăn đã bị hư hỏng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饡', '{"9000": "8724.0", "Chữ Trung Quốc": "饡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 27 | nét | 饡 | tán | tượng hình | đổ canh lên cơm | 饡 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật; 27 nét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tán\": bộ 食 (ăn) — tán canh xuống cơm, phủ đều như tản ra. | Gương Hán-Việt | 饡 ít dùng; liên hệ 澆饡 (đổ canh lên cơm). | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn), 飲 (ẩm), 餐 (xan).", "Tự nguyên_Xie": "Theo Wiktionary, 饡 có MC zàn và OC được ghi nhận. Nghĩa là ''đổ canh đặc lên cơm''. Gặp trong cụm 澆饡. Hán-Việt phục nguyên theo Trung cổ âm zàn là ''tán''. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "háu ăn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 贊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠贊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "饡", "Unihan_Traditional (Chữ Phồn thể)": "饡", "Pinyin_Xie": "zàn", "Âm Hán Việt_Xie": "tán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các món ăn ngon hoặc làm động từ trong văn viết cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饳', '{"9000": "8725.0", "Chữ Trung Quốc": "饳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 8 | nét | 饳 | đoá | tượng hình | bánh gạo, bột | 饳 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoá\": bộ 食 (ăn) + âm đoá — bánh bột đoá tròn, gọn nhỏ. | Gương Hán-Việt | 饳 gặp trong cụm 餶飿 (馉饳) — tên loại bánh gạo cổ đại. | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn), 飲 (ẩm), 餃 (giảo, bánh).", "Tự nguyên_Xie": "饳 không có nguồn từ nguyên Wiktionary. Thuộc bộ 食, âm Hán-Việt phục nguyên theo duò là ''đoá''. Nghĩa ghi là thành phần trong cụm 餶飿/馉饳 (loại bánh gạo cổ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cốt đốt 餶飿,馉饳)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饳", "Unihan_Traditional (Chữ Phồn thể)": "饳", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng trong các từ ghép cổ để chỉ các loại bánh làm từ bột mì. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饻', '{"9000": "8726.0", "Chữ Trung Quốc": "饻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饻 | tích | tượng hình | đơn vị tiền tệ | 饻 là chữ độc thể thuộc bộ 食 (thực, ăn). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bộ 食 (ăn) + âm tích — tích lũy từng đơn vị nhỏ như hạt gạo. | Gương Hán-Việt | 饻 ít dùng; bộ 食 gặp trong ''thực phẩm''. | Mở khoá kiến thức | Biết bộ 食 mở ra: 飯 (phạn), 飲 (ẩm), 糧 (lương, lương thực).", "Tự nguyên_Xie": "饻 không có nguồn từ nguyên Wiktionary. Thuộc bộ 食, âm Hán-Việt phục nguyên theo xī là ''tích''. Nghĩa ghi là đơn vị tính tiền tệ tại vùng giải phóng cũ của Trung Quốc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thi (đơn vị tính tiền tệ ở vùng giải phóng cũ của Trung Quốc bằng tổng giá cả của một số hiện vật)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饻", "Unihan_Traditional (Chữ Phồn thể)": "饻", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn bản cổ để chỉ phần lương thực được cấp phát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駜', '{"9000": "8727.0", "Chữ Trung Quốc": "駜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 駜 | bí | tượng hình | ngựa to béo, mạnh khỏe | 駜 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": bộ 馬 (ngựa) — con ngựa bí ẩn sức mạnh, to béo căng tròn. | Gương Hán-Việt | 駜 ít dùng; gặp trong cụm 有駜 (thơ kinh cổ). | Mở khoá kiến thức | Biết bộ 馬 mở ra: 驥 (ký, tuấn mã), 驕 (kiêu, ngựa hung), 馴 (thuần).", "Tự nguyên_Xie": "Theo Wiktionary, 駜 có MC và OC được ghi nhận, nghĩa là ''ngựa to béo, mạnh khỏe'' (stout and strong horse). Gặp trong cụm 有駜. Hán-Việt phục nguyên theo Trung cổ âm bjijX là ''bí''. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa mập khoẻ", "Hạng Tần Suất (Jun Da)": "8727.0", "Tần Suất % (Jun Da)": "99.999853233", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駜", "Unihan_Traditional (Chữ Phồn thể)": "駜", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ ngựa trong thơ ca cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駣', '{"9000": "8728.0", "Chữ Trung Quốc": "駣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 16 | nét | 駣 | đào | tượng hình | ngựa ba/bốn tuổi | 駣 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\": bộ 馬 (ngựa) + âm đào — con ngựa đào tơ, còn trẻ mạnh. | Gương Hán-Việt | 駣 ít dùng trong từ Hán-Việt thông dụng; gặp trong điển tịch cổ về ngựa. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 駒 (câu, ngựa con), 驥 (ký, tuấn mã), 馴 (thuần).", "Tự nguyên_Xie": "Theo Wiktionary, 駣 có MC táo và OC được ghi nhận. Nghĩa cổ là ''ngựa ba tuổi'' hoặc ''ngựa bốn tuổi''. Hán-Việt phục nguyên theo Trung cổ âm daw là ''đào''. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駣", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駣", "Unihan_Traditional (Chữ Phồn thể)": "駣", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ độ tuổi của ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駥', '{"9000": "8729.0", "Chữ Trung Quốc": "駥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 16 | nét | 駥 | dong | tượng hình | ngựa cao tám thước | 駥 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dong\": bộ 馬 (ngựa) + âm dong — ngựa dong dỏng cao, tám thước sừng sững. | Gương Hán-Việt | 駥 ít dùng; gặp trong điển tịch cổ mô tả ngựa quý theo chiều cao. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 驥 (ký, tuấn mã), 駜 (bí, ngựa to), 馴 (thuần).", "Tự nguyên_Xie": "Theo Wiktionary, 駥 có MC róng và OC được ghi nhận. Nghĩa cổ là ''ngựa cao tám thước'' (horse which is eight chi tall). Hán-Việt phục nguyên theo Trung cổ âm rjowng là ''dong''. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 戎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬戎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駥", "Unihan_Traditional (Chữ Phồn thể)": "駥", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại ngựa cao lớn thời cổ hoặc ngựa chiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駨', '{"9000": "8730.0", "Chữ Trung Quốc": "駨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 16 | nét | 駨 | huân | tượng hình | ngựa | 駨 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huân\": bộ 馬 (ngựa) + âm huân — ngựa huân huân phi nước đại. | Gương Hán-Việt | 駨 ít dùng; bộ 馬 gặp trong ''mã lực'', ''tuấn mã''. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 馬 (mã), 驥 (ký), 騰 (đằng, phi lên).", "Tự nguyên_Xie": "駨 không có nguồn từ nguyên Wiktionary. Thuộc bộ 馬, âm Hán-Việt phục nguyên theo xūn là ''huân''. Nghĩa không xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "駨", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駨", "Unihan_Traditional (Chữ Phồn thể)": "駨", "Pinyin_Xie": "xūn", "Âm Hán Việt_Xie": "huân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một giống ngựa có màu sắc đặc biệt thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('駶', '{"9000": "8731.0", "Chữ Trung Quốc": "駶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 17 | nét | 駶 | cúc | tượng hình | ngựa | 駶 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": bộ 馬 (ngựa) + âm cúc — ngựa co cúc mình lại chuẩn bị phi. | Gương Hán-Việt | 駶 ít dùng; bộ 馬 gặp trong ''mã lực'', ''tuấn mã''. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 馬 (mã), 驥 (ký), 騰 (đằng).", "Tự nguyên_Xie": "駶 không có nguồn từ nguyên Wiktionary. Thuộc bộ 馬, âm Hán-Việt phục nguyên theo jú là ''cúc''. Nghĩa không xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 局", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬局", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "局", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "駶", "Unihan_Traditional (Chữ Phồn thể)": "駶", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngựa chân cong hoặc làm tính từ mô tả dáng ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騿', '{"9000": "8732.0", "Chữ Trung Quốc": "騿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 騿 | trương | tượng hình | ngựa | 騿 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trương\": bộ 馬 (ngựa) + âm trương — ngựa trương bờm, oai phong lẫm liệt. | Gương Hán-Việt | 騿 ít dùng; bộ 馬 gặp trong ''mã lực'', ''tuấn mã''. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 騰 (đằng, phi lên), 驕 (kiêu), 馴 (thuần).", "Tự nguyên_Xie": "騿 không có nguồn từ nguyên Wiktionary. Thuộc bộ 馬, âm Hán-Việt phục nguyên theo zhāng là ''trương''. Nghĩa không xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "騿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騿", "Unihan_Traditional (Chữ Phồn thể)": "騿", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "trương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giống ngựa có đặc điểm bụng trắng thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驇', '{"9000": "8733.0", "Chữ Trung Quốc": "驇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 21 | nét | 驇 | trí | tượng hình | ngựa nặng nề, khó đi | 驇 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trí\": bộ 馬 (ngựa) + âm trí — ngựa bị trí cẳng, nặng nề không bước đi được. | Gương Hán-Việt | 驇 ít dùng; bộ 馬 gặp trong ''mã lực'', ''tuấn mã''. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 騰 (đằng), 驥 (ký), 馴 (thuần).", "Tự nguyên_Xie": "驇 không có nguồn từ nguyên Wiktionary. Thuộc bộ 馬, âm Hán-Việt phục nguyên theo zhì là ''trí''. Nghĩa ghi là ''ngựa nặng nề không di chuyển được do chân bị xoắn''. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "驇", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "埶 + 馬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱埶馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "埶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驇", "Unihan_Traditional (Chữ Phồn thể)": "驇", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ ngựa chậm chạp hoặc làm tính từ miêu tả trạng thái trì trệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驑', '{"9000": "8734.0", "Chữ Trung Quốc": "驑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 22 | nét | 驑 | lưu | tượng hình | ngựa | 驑 là chữ độc thể thuộc bộ 馬 (mã, ngựa). Cấu trúc nội bộ chưa rõ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lưu\": bộ 馬 (ngựa) + âm lưu — ngựa lưu lại, chần chừ không phi. | Gương Hán-Việt | 驑 ít dùng; bộ 馬 gặp trong ''mã lực'', ''tuấn mã''. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 騰 (đằng), 驥 (ký), 馴 (thuần).", "Tự nguyên_Xie": "驑 không có nguồn từ nguyên Wiktionary. Thuộc bộ 馬, âm Hán-Việt phục nguyên theo liú là ''lưu''. Nghĩa không xác định rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 畱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬畱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驑", "Unihan_Traditional (Chữ Phồn thể)": "驑", "Pinyin_Xie": "liú", "Âm Hán Việt_Xie": "lưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ giống ngựa lông đỏ có bờm và đuôi đen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驖', '{"9000": "8735.0", "Chữ Trung Quốc": "驖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 23 | nét | 馬 | mã | biểu nghĩa | ngựa | 驖 = 馬 (Mã, biểu nghĩa: ngựa) + 𢧜 (biểu âm, theo Wiktionary); chữ hình thanh. Bộ 馬 chỉ loài ngựa; phần biểu âm (𢧜) cho âm đọc. Chữ chỉ ngựa màu đen có sợi lông hơi đỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiết\": bộ 馬 (ngựa) — ngựa màu thiết đen như sắt, điểm hơi đỏ như gỉ sắt. | Gương Hán-Việt | 驖 ít dùng; liên hệ 鐵 (thiết, sắt) qua màu sắc đen tối. | Mở khoá kiến thức | Biết bộ 馬 mở ra: 騰 (đằng), 驥 (ký), 驕 (kiêu).", "Tự nguyên_Xie": "Theo Wiktionary, 驖 là chữ hình thanh: 馬 (biểu nghĩa) + 𢧜 (biểu âm). Nghĩa là ''ngựa đen có ngọn lông hơi đỏ'' (black horse with reddish tinge). Hán-Việt phục nguyên theo tiě là ''thiết'', cùng âm với 鐵 (thiết, sắt) — gợi màu tối như sắt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa đen có ngọn lông hơi đỏ", "Hạng Tần Suất (Jun Da)": "8735.0", "Tần Suất % (Jun Da)": "99.9998589177", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "驖", "Unihan_Traditional (Chữ Phồn thể)": "驖", "Pinyin_Xie": "tiě", "Âm Hán Việt_Xie": "thiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại ngựa có màu lông đen sẫm như sắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髞', '{"9000": "8736.0", "Chữ Trung Quốc": "髞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 高 | Số nét | 23 | nét | 髞 | tảo | tượng hình | cao vút, uy nghiêm, lỗi lạc | 髞 là chữ thuộc bộ 高 (cao). Cấu trúc nội bộ chưa rõ nguồn học thuật. Toàn chữ biểu thị sự cao vút, uy nghiêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tảo\": bộ 高 (cao) — tảo vút như ngọn núi tảo đứng cao ngất. | Gương Hán-Việt | 髞 ít dùng; bộ 高 gặp trong ''cao nguyên'', ''cao thủ''. | Mở khoá kiến thức | Biết bộ 高 mở ra: 高 (cao), 髙 (biến thể của cao), và nhóm chữ chỉ sự vượt trội.", "Tự nguyên_Xie": "Theo Wiktionary, 髞 có MC và OC được ghi nhận, nghĩa là ''cao vút, uy nghiêm''. Gặp trong cụm 髝髞. Hán-Việt phục nguyên theo Trung cổ âm sawX là ''tảo''. Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lỗi lạc; cao; uy nghiêm", "Hạng Tần Suất (Jun Da)": "8736.0", "Tần Suất % (Jun Da)": "99.9998599512", "GavinGrover_Once (Chiết tự trực tiếp)": "高 + 喿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰高喿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "高", "Unihan_Simplified (Chữ Giản thể)": "髞", "Unihan_Traditional (Chữ Phồn thể)": "髞", "Pinyin_Xie": "sào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ dùng để miêu tả dáng vẻ cao lớn hoặc phong thái uy nghiêm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬀', '{"9000": "8737.0", "Chữ Trung Quốc": "鬀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 17 | nét | 鬀 | thế | tượng hình | chữ biểu thị hành động cạo, alt form của 剃 | 鬀 là dạng thay thế cổ của 剃 (thế, cạo). Chưa có dữ liệu thành phần rõ ràng trong CHISE IDS; xét là chữ độc thể tượng hình mang nghĩa cạo tóc. Chưa có nguồn học thuật về cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": hình ảnh người thợ cạo (bộ 髟 tóc) dùng dao \"thế\" đi từng sợi tóc — nhớ 鬀 = cạo sạch. | Gương Hán-Việt | thế trong nghĩa cạo tóc, cạo râu | Mở khoá kiến thức | Biết 鬀 (thế) mở khoá nhóm từ cổ về việc cạo tóc, tu hành trong văn bản Hán Nôm.", "Tự nguyên_Xie": "Tiểu triện | 鬀 là dạng cổ thay thế (alt form) của 剃 mang nghĩa ''cạo'' (tóc, râu). Wiktionary xác nhận đây là biến thể của 剃. Cấu trúc nội tại chưa được phân tích rõ trong nguồn học thuật; chưa có nguồn học thuật về glyph origin chi tiết. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thế; như \"thế (cạo sát)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬀", "Unihan_Traditional (Chữ Phồn thể)": "鬀", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động cạo tóc hoặc cạo râu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬄', '{"9000": "8738.0", "Chữ Trung Quốc": "鬄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 18 | nét | 髟 | biểu nghĩa | tóc dài | 易 | dịch | biểu âm | thay đổi | 鬄 = 髟 (bộ tóc dài, biểu nghĩa) + 易 (Dịch, biểu âm). Chữ hình thanh: 髟 cho nghĩa ''tóc'', 易 cho âm gần với ''dí/tì''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": bộ 髟 (tóc) cộng 易 (dịch, thay) — cắt tóc là ''thay'' đi mái tóc cũ, nhớ 鬄 = cắt tóc. | Gương Hán-Việt | đề trong nghĩa cắt tóc | Mở khoá kiến thức | Biết 鬄 (đề) giúp nhận ra nhóm chữ bộ 髟 liên quan đến tóc và việc chăm sóc tóc.", "Tự nguyên_Xie": "鬄 là chữ hình thanh (psc): bộ 髟 biểu nghĩa tóc dài, 易 biểu âm. Mang nghĩa cắt tóc. Wiktionary ghi nhận cấu trúc Han compound 髟+易. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt tóc", "Hạng Tần Suất (Jun Da)": "8738.0", "Tần Suất % (Jun Da)": "99.9998609848", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 易", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟易", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬄", "Unihan_Traditional (Chữ Phồn thể)": "鬄", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cắt tóc hoặc loại bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬅', '{"9000": "8739.0", "Chữ Trung Quốc": "鬅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 18 | nét | 鬅 | bồng | tượng hình | tóc rối bù, xõa tung | 鬅 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể hoặc biến thể tượng hình mô tả tóc rời rạc, xõa tung. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồng\": tưởng tượng mái tóc ''bồng'' xõa ra bốn phía — 鬅 = tóc rối bù, xù lên như bông. | Gương Hán-Việt | bồng trong ''bồng bềnh'', tóc bồng | Mở khoá kiến thức | Biết 鬅 (bồng) giúp đọc các văn bản cổ miêu tả ngoại hình, đặc biệt về mái tóc.", "Tự nguyên_Xie": "鬅 mang nghĩa tóc rối bù, xõa tung. Wiktionary không cung cấp glyph origin cụ thể. Cấu trúc nội tại chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc rời rạc lỏng lẻo", "Hạng Tần Suất (Jun Da)": "8739.0", "Tần Suất % (Jun Da)": "99.9998615016", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬅", "Unihan_Traditional (Chữ Phồn thể)": "鬅", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả trạng thái tóc tai bù xù hoặc rối bời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魰', '{"9000": "8740.0", "Chữ Trung Quốc": "魰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魰 | văn | tượng hình | loài cá da trơn | 魰 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ loài cá da trơn. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"văn\": loài cá (魚) mang hoa văn (văn) trên da — 魰 = cá da trơn có hoa văn đặc trưng. | Gương Hán-Việt | văn trong nghĩa hoa văn, vân — cá có vân da | Mở khoá kiến thức | Biết 魰 (văn) giúp nhận ra nhóm từ cổ về các loài cá trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "魰 chỉ một loài cá da trơn. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc nội tại chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá da trơn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魰", "Unihan_Traditional (Chữ Phồn thể)": "魰", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá có hoa văn trên thân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魵', '{"9000": "8741.0", "Chữ Trung Quốc": "魵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魚 | ngư | biểu nghĩa | cá | 分 | phân | biểu âm | chia, phân | 魵 = 魚 (Ngư, biểu nghĩa: cá) + 分 (Phân, biểu âm). Chữ hình thanh: 魚 cho nghĩa ''cá/tôm'', 分 cho âm ''fén''. Đây là chữ hình thanh chuẩn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": cá (魚/ngư) ''phân'' (分) thành nhiều lớp vảy nhỏ — 魵 = loài tôm cá nhỏ li ti. | Gương Hán-Việt | phần trong nghĩa phân chia — loài cá/tôm nhỏ | Mở khoá kiến thức | Biết 魵 (phần) giúp đọc danh sách thủy sản trong thư tịch Hán cổ.", "Tự nguyên_Xie": "魵 là chữ hình thanh (psc): 魚 biểu nghĩa cá, 分 biểu âm. Wiktionary ghi: Han compound 魚+分, ls=psc, c1=s, c2=p, t1=fish. Mang nghĩa con tôm hoặc một loài cá nhỏ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tôm", "Hạng Tần Suất (Jun Da)": "8741.0", "Tần Suất % (Jun Da)": "99.9998635687", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魵", "Unihan_Traditional (Chữ Phồn thể)": "魵", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài tôm hoặc cá nhỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魸', '{"9000": "8742.0", "Chữ Trung Quốc": "魸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 魸 | thiên | tượng hình | cá mèo, cá da trơn | 魸 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá mèo (cá da trơn). Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiên\": cá (魚) ''thiên'' về nước sâu — 魸 = một loài cá sống dưới đáy, cá mèo. | Gương Hán-Việt | thiên trong nghĩa nghiêng, lệch — cá mèo bơi sát đáy | Mở khoá kiến thức | Biết 魸 (thiên) giúp đọc các mục từ về thuỷ sản trong từ điển Hán cổ.", "Tự nguyên_Xie": "魸 chỉ một loài cá mèo. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cá mèo", "Hạng Tần Suất (Jun Da)": "8742.0", "Tần Suất % (Jun Da)": "99.9998640855", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 片", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚片", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "片", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魸", "Unihan_Traditional (Chữ Phồn thể)": "魸", "Pinyin_Xie": "pian", "Âm Hán Việt_Xie": "phiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá da trơn như cá trê hoặc cá nheo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魺', '{"9000": "8743.0", "Chữ Trung Quốc": "魺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魺 | hà | tượng hình | loài cá sông | 魺 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": con cá sông (魚) mang âm ''hà'' như dòng Hà (河) — 魺 = cá sông loài cổ. | Gương Hán-Việt | hà trong nghĩa sông, cá sông | Mở khoá kiến thức | Biết 魺 (hà) giúp đọc các danh mục thủy sản cổ điển trong thư tịch Hán.", "Tự nguyên_Xie": "魺 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "魺", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魺", "Unihan_Traditional (Chữ Phồn thể)": "魺", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯐', '{"9000": "8744.0", "Chữ Trung Quốc": "鯐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 鯐 | tựu | tượng hình | loài cá nhỏ | 鯐 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá nhỏ. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tựu\": cá (魚) nhỏ ''tựu'' về thành đàn — 鯐 = loài cá nhỏ sống thành đàn. | Gương Hán-Việt | tựu trong nghĩa tập họp — cá nhỏ kéo đàn | Mở khoá kiến thức | Biết 鯐 (tựu) giúp nhận ra tên loài cá trong văn bản cổ.", "Tự nguyên_Xie": "鯐 chỉ một loài cá nhỏ (Chí). Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 走", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚走", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "走", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯐", "Unihan_Traditional (Chữ Phồn thể)": "鯐", "Pinyin_Xie": "zou", "Âm Hán Việt_Xie": "tựu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá hoặc hiện tượng liên quan đến cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯓', '{"9000": "8745.0", "Chữ Trung Quốc": "鯓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 魚 | ngư | biểu nghĩa | cá | 身 | thân | biểu âm | thân thể | 鯓 = 魚 (Ngư, biểu nghĩa: cá) + 身 (Thân, biểu âm). Chữ hình thanh: 魚 cho nghĩa ''cá'', 身 cho âm ''ní/shēn''. Đây là chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thân\": con cá (魚/ngư) mang ''thân'' (身) hình dài — 鯓 = loài cá có thân dài. | Gương Hán-Việt | thân trong nghĩa thân thể — cá có thân đặc trưng | Mở khoá kiến thức | Biết 鯓 (thân) giúp nhận ra tên loài cá trong thư tịch Hán cổ.", "Tự nguyên_Xie": "鯓 là chữ hình thanh (psc): 魚 biểu nghĩa cá, 身 biểu âm. Wiktionary ghi cấu trúc 魚+身, ls=psc. Nghĩa: một loài cá (鈥铓). Hán-Việt ''thân'' theo âm Sino-Việt của 身. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "铓", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 身", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚身", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "身", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯓", "Unihan_Traditional (Chữ Phồn thể)": "鯓", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "thân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần thân của con cá hoặc dùng trong địa danh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰞', '{"9000": "8746.0", "Chữ Trung Quốc": "鰞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰞 | ô | tượng hình | loài cá | 鰞 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": loài cá (魚) màu ''ô'' (đen) sống dưới bùn — 鰞 = cá sống ở nơi tối tăm. | Gương Hán-Việt | ô trong nghĩa đen, tối — cá tối màu | Mở khoá kiến thức | Biết 鰞 (ô) giúp đọc danh sách thủy sản trong thư tịch Hán Nôm cổ.", "Tự nguyên_Xie": "鰞 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 烏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚烏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "烏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰞", "Unihan_Traditional (Chữ Phồn thể)": "鰞", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi các loài sinh vật biển như mực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰬', '{"9000": "8747.0", "Chữ Trung Quốc": "鰬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 21 | nét | 鰬 | kiềm | tượng hình | loài cá | 鰬 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiềm\": cá (魚) như chiếc ''kiềm'' (kẹp) — 鰬 = loài cá có hình dạng đặc trưng. | Gương Hán-Việt | kiềm trong nghĩa cặp kẹp, hình dạng kẹp | Mở khoá kiến thức | Biết 鰬 (kiềm) giúp đọc các danh mục thủy sản trong văn bản Hán cổ.", "Tự nguyên_Xie": "鰬 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鬬", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 虔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚虔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰬", "Unihan_Traditional (Chữ Phồn thể)": "鰬", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cá lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰵', '{"9000": "8748.0", "Chữ Trung Quốc": "鰵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鰵 | mẫn | tượng hình | loài cá | 鰵 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\": cá (魚) ''mẫn'' cảm — 鰵 = loài cá nhạy cảm với môi trường nước. | Gương Hán-Việt | mẫn trong nghĩa nhạy cảm, nhanh nhẹn | Mở khoá kiến thức | Biết 鰵 (mẫn) giúp đọc danh mục thủy sản trong thư tịch Hán cổ.", "Tự nguyên_Xie": "鰵 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鰵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敏 + 魚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敏魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰵", "Unihan_Traditional (Chữ Phồn thể)": "鰵", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá biển lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰸', '{"9000": "8749.0", "Chữ Trung Quốc": "鰸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鰸 | câu | tượng hình | loài cá | 鰸 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": cá (魚) bị ''câu'' — 鰸 = loài cá thường bị câu bởi ngư dân xưa. | Gương Hán-Việt | câu trong nghĩa câu cá — loài cá dễ câu | Mở khoá kiến thức | Biết 鰸 (câu) giúp đọc danh mục thủy sản trong văn bản Hán Nôm.", "Tự nguyên_Xie": "鰸 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鸸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 區", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚區", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "區", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰸", "Unihan_Traditional (Chữ Phồn thể)": "鰸", "Pinyin_Xie": "qū", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cá cụ thể trong cổ thư. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱌', '{"9000": "8750.0", "Chữ Trung Quốc": "鱌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鱌 | tương | tượng hình | loài cá | 鱌 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài cá. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": cá (魚) như hương ''tương'' — 鱌 = loài cá đặc trưng trong văn bản cổ. | Gương Hán-Việt | tương trong nghĩa tương xứng, giống nhau | Mở khoá kiến thức | Biết 鱌 (tương) giúp đọc các danh mục thủy sản trong thư tịch Hán Nôm.", "Tự nguyên_Xie": "鱌 chỉ một loài cá. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 象", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚象", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "象", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱌", "Unihan_Traditional (Chữ Phồn thể)": "鱌", "Pinyin_Xie": "xiàng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá lớn thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳪', '{"9000": "8751.0", "Chữ Trung Quốc": "鳪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 卜 | bốc | biểu âm | bói toán | 鳥 | điểu | biểu nghĩa | chim | 鳪 = 卜 (Bốc, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: 鳥 cho nghĩa ''chim'', 卜 cho âm ''bú''. Đây là chữ hình thanh chỉ một loài chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bốc\": chim (鳥/điểu) ''bốc'' bay — 鳪 = loài chim bốc vụt bay lên khi bị động. | Gương Hán-Việt | bốc trong nghĩa bốc bay, chim bốc lên | Mở khoá kiến thức | Biết 鳪 (bốc) giúp đọc tên chim trong văn bản cổ, đặc biệt từ ghép 鳪雉.", "Tự nguyên_Xie": "鳪 là chữ hình thanh (psc): 卜 biểu âm, 鳥 biểu nghĩa chim. Wiktionary ghi: Han compound 卜+鳥, ls=psc. Chỉ dùng trong từ 鳪雉 (bú zhì). Hán-Việt ''bốc'' theo âm Sino-Việt của 卜. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "骁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "卜 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卜鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卜", "Unihan_Simplified (Chữ Giản thể)": "鳪", "Unihan_Traditional (Chữ Phồn thể)": "鳪", "Pinyin_Xie": "bú", "Âm Hán Việt_Xie": "bốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chim xuất hiện trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴭', '{"9000": "8752.0", "Chữ Trung Quốc": "鴭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴭 | đôi | tượng hình | loài chim | 鴭 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôi\": chim đi theo ''đôi'' — 鴭 = loài chim thường đi thành cặp, thành đôi. | Gương Hán-Việt | đôi trong nghĩa cặp đôi — chim bay từng đôi | Mở khoá kiến thức | Biết 鴭 (đôi) giúp đọc tên chim trong thư tịch Hán cổ.", "Tự nguyên_Xie": "鴭 chỉ một loài chim. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "魴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂤 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰𠂤鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴭", "Unihan_Traditional (Chữ Phồn thể)": "鴭", "Pinyin_Xie": "duī", "Âm Hán Việt_Xie": "đôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này đóng vai trò danh từ chỉ một loài chim cổ trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴳', '{"9000": "8753.0", "Chữ Trung Quốc": "鴳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 安 | an | biểu âm | bình an | 鳥 | điểu | biểu nghĩa | chim | 鴳 = 安 (An, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: 鳥 cho nghĩa ''chim'', 安 cho âm ''yàn''. Chỉ loài chim yến tước hoặc chim cút.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"an\": chim nhỏ ''an'' phận — 鴳 = loài chim nhỏ thư thái, chim sẻ núi bình yên. | Gương Hán-Việt | an trong nghĩa an phận — chim nhỏ sống bình yên | Mở khoá kiến thức | Biết 鴳 (an) giúp đọc điển tích về chim nhỏ trong văn học Trang Tử và thơ cổ.", "Tự nguyên_Xie": "鴳 là chữ hình thanh (psc): 安 biểu âm, 鳥 biểu nghĩa chim. Wiktionary ghi: Han compound 安+鳥, ls=psc, c1=p, c2=s, t2=bird. Nghĩa: chim yến tước, chim cút nhỏ. Hán-Việt ''an'' từ âm Sino-Việt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim yến tước; chim cút", "Hạng Tần Suất (Jun Da)": "8753.0", "Tần Suất % (Jun Da)": "99.9998733876", "GavinGrover_Once (Chiết tự trực tiếp)": "安 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰安鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴳", "Unihan_Traditional (Chữ Phồn thể)": "鴳", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim cút hoặc chim yến tước trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴵', '{"9000": "8754.0", "Chữ Trung Quốc": "鴵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴵 | tiêu | tượng hình | loài chim cú | 鴵 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim cú. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": chim (鳥) ''tiêu'' vong — 鴵 = loài chim cú kêu ban đêm, tiếng kêu u sầu. | Gương Hán-Việt | tiêu trong nghĩa buồn bã, đêm tối — chim cú kêu đêm | Mở khoá kiến thức | Biết 鴵 (tiêu) giúp đọc tên chim trong văn bản cổ về điềm gở hay thú tự nhiên.", "Tự nguyên_Xie": "鴵 chỉ một loài chim cú. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鵵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "兆 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰兆鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴵", "Unihan_Traditional (Chữ Phồn thể)": "鴵", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ một loài chim nhỏ thời cổ đại, ít khi dùng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴺', '{"9000": "8755.0", "Chữ Trung Quốc": "鴺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鴺 | đề | tượng hình | chim gà ri hoặc loài chim tương tự | 鴺 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đề\": chim ''đề'' hót — 鴺 = loài chim nhỏ hót líu lo. | Gương Hán-Việt | đề trong nghĩa hót, kêu — chim hót tiếng đề | Mở khoá kiến thức | Biết 鴺 (đề) giúp đọc tên chim trong văn bản Hán Nôm cổ điển.", "Tự nguyên_Xie": "鴺 chỉ một loài chim (ri, như ''gà ri''). Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ri; như \"gà ri\" (vhn) đề; như \"đề hồ (chim bồ nông)\" (btcn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "夷 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夷鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴺", "Unihan_Traditional (Chữ Phồn thể)": "鴺", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "đề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong từ ghép đề hồ để chỉ loài chim bồ nông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴽', '{"9000": "8756.0", "Chữ Trung Quốc": "鴽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 如 | như | biểu âm | như là | 鳥 | điểu | biểu nghĩa | chim | 鴽 = 如 (Như, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim). Chữ hình thanh: 鳥 cho nghĩa ''chim'', 如 cho âm ''rú''. Chỉ loài chim như chim cun cú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"như\": chim (鳥/điểu) ''như'' loài cun cú — 鴽 = chim giống cun cú, chim đồng nhỏ. | Gương Hán-Việt | như trong nghĩa giống như — chim như cun cú | Mở khoá kiến thức | Biết 鴽 (như) giúp đọc tên chim đồng trong văn bản cổ về tự nhiên.", "Tự nguyên_Xie": "鴽 là chữ hình thanh (psc): 如 biểu âm, 鳥 biểu nghĩa chim. Wiktionary ghi: Han compound 如+鳥, ls=psc, c1=p, c2=s, t2=bird. Nghĩa: loài chim giống chim cun cú (quail-like bird). Hán-Việt ''như'' theo âm Sino-Việt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim như (một loài chim cun cút, tên khoa học: trunix blakistoni)", "Hạng Tần Suất (Jun Da)": "8756.0", "Tần Suất % (Jun Da)": "99.9998754548", "GavinGrover_Once (Chiết tự trực tiếp)": "如 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱如鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鴽", "Unihan_Traditional (Chữ Phồn thể)": "鴽", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "như", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ một loài chim nhỏ giống chim cút trong sách cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵁', '{"9000": "8757.0", "Chữ Trung Quốc": "鵁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 17 | nét | 鵁 | giao | tượng hình | loài chim nước | 鵁 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim nước. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": chim nước ''giao'' hòa — 鵁 = loài chim nước sống thành đàn hòa thuận. | Gương Hán-Việt | giao trong nghĩa giao hòa, kết hợp | Mở khoá kiến thức | Biết 鵁 (giao) giúp đọc tên chim nước trong văn bản Hán cổ về tự nhiên.", "Tự nguyên_Xie": "鵁 chỉ một loài chim nước. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "遁", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "交 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰交鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "䴔", "Unihan_Traditional (Chữ Phồn thể)": "鵁", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp thành từ ghép giao tinh để chỉ một loài chim nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶈', '{"9000": "8758.0", "Chữ Trung Quốc": "鶈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶈 | thê | tượng hình | loài chim | 鶈 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thê\": chim ''thê'' đậu — 鶈 = loài chim thê đậu trên cành, yên lặng. | Gương Hán-Việt | thê trong nghĩa đậu, trú ngụ — chim đậu yên tĩnh | Mở khoá kiến thức | Biết 鶈 (thê) giúp đọc tên chim trong văn bản Hán cổ.", "Tự nguyên_Xie": "鶈 chỉ một loài chim. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": ":", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "妻 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰妻鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妻", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶈", "Unihan_Traditional (Chữ Phồn thể)": "鶈", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "thê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ một loài chim trong thư tịch cổ Trung Hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鶐', '{"9000": "8759.0", "Chữ Trung Quốc": "鶐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 19 | nét | 鶐 | thụ | tượng hình | loài chim | 鶐 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ một loài chim. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thụ\": chim ''thụ'' lĩnh — 鶐 = loài chim uy nghi, đứng đắn. | Gương Hán-Việt | thụ trong nghĩa nhận lĩnh, uy nghiêm | Mở khoá kiến thức | Biết 鶐 (thụ) giúp đọc tên chim trong văn bản Hán cổ.", "Tự nguyên_Xie": "鶐 chỉ một loài chim. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "述 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰述鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "述", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鶐", "Unihan_Traditional (Chữ Phồn thể)": "鶐", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài chim cổ, hiện nay rất hiếm dùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷩', '{"9000": "8760.0", "Chữ Trung Quốc": "鷩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 鷩 | bí | tượng hình | chim trĩ, chim dẽ | 鷩 chưa có phân tích thành phần rõ trong CHISE IDS. Xét là chữ độc thể chỉ loài chim trĩ hoặc chim dẽ. Chưa có nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": chim trĩ ''bí'' ẩn — 鷩 = loài chim trĩ rực rỡ nhưng trú ẩn trong rừng. | Gương Hán-Việt | bí trong nghĩa ẩn, rực rỡ mà kín đáo — chim trĩ đỏ | Mở khoá kiến thức | Biết 鷩 (bí) giúp đọc tên chim quý trong văn bản Hán cổ về điểu thú.", "Tự nguyên_Xie": "鷩 chỉ loài chim trĩ đỏ (red pheasant) hoặc chim dẽ. Wiktionary không cung cấp glyph origin chi tiết. Cấu trúc chưa được phân tích học thuật; chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim trĩ, chim dẽ", "Hạng Tần Suất (Jun Da)": "8760.0", "Tần Suất % (Jun Da)": "99.9998795891", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷩", "Unihan_Traditional (Chữ Phồn thể)": "鷩", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim trĩ cổ, thường xuất hiện trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼑', '{"9000": "8761.0", "Chữ Trung Quốc": "鼑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼎 | Số nét | 14 | nét | 鼑 | dinh | tượng hình | biến thể của 鼎 (đỉnh — vạc ba chân) | 鼑 là biến thể cổ của 鼎 (Đỉnh), bộ Đỉnh (鼎). Cấu trúc tượng hình phỏng theo hình chiếc vạc đồng ba chân. Chưa có phân tích hình-thanh trong nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đỉnh\": 鼑 là biến thể cổ của chiếc đỉnh (vạc ba chân) — chữ tạo muộn, chưa thấy trong giáp cốt văn. | Gương Hán-Việt | Đỉnh — trong \"đỉnh cao\", \"đỉnh núi\"; gốc là hình ảnh chiếc vạc đứng vững. | Mở khoá kiến thức | Biết 鼑 (dinh) giúp nhận ra nhóm chữ bộ Đỉnh liên quan đến đồ đồng và lễ khí cổ đại.", "Tự nguyên_Xie": "鼑 là dạng biến thể của 鼎 (đỉnh — chiếc vạc đồng ba chân dùng trong lễ tế). Không có nguồn Wiktionary phân tích cấu trúc riêng cho chữ này. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鑫", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼎 + ⺊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿶ (Bao quanh phía dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鼎⺊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼎", "Unihan_Simplified (Chữ Giản thể)": "鼑", "Unihan_Traditional (Chữ Phồn thể)": "鼑", "Pinyin_Xie": "dǐng", "Âm Hán Việt_Xie": "dinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái đỉnh đồng thời cổ, thường làm chủ ngữ hoặc tân ngữ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼘', '{"9000": "8762.0", "Chữ Trung Quốc": "鼘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼓 | Số nét | 22 | nét | 鼓 | cổ | biểu nghĩa | trống | 淵 | uyên | biểu âm | vực sâu (cho âm) | 鼘 = 鼓 (Cổ, biểu nghĩa: trống) + 淵 (Uyên, biểu âm). Chữ hình thanh: bộ Cổ cho nghĩa (âm trống), 淵 cho âm yuān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Uyên\": 鼘 — tiếng trống (鼓) vang vọng sâu như vực thẳm (淵), âm \"uyên\" rền trầm. | Gương Hán-Việt | Uyên — ít dùng độc lập; liên quan đến âm trầm, sâu trong văn cổ. | Mở khoá kiến thức | Biết 鼘 (uyên) giúp nhận bộ Cổ (鼓) trong các chữ chỉ nhạc cụ gõ cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, 鼘 là chữ hình thanh gồm 鼓 (trống, biểu nghĩa) và 淵 (biểu âm, cho âm yuān). Nghĩa chỉ tiếng trống vang sâu, trầm. Chữ hiếm, chỉ thấy trong văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼓 + 𣶒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱鼓𣶒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣶒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼓", "Unihan_Simplified (Chữ Giản thể)": "鼘", "Unihan_Traditional (Chữ Phồn thể)": "鼘", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyen", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ chỉ âm thanh tiếng trống lớn hoặc dùng làm từ tượng thanh mô tả tiếng trống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼮', '{"9000": "8763.0", "Chữ Trung Quốc": "鼮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 19 | nét | 鼮 | dinh | tượng hình | chuột có vằn (bộ Thử) | 鼮 thuộc bộ Thử (鼠, chuột). Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu; đây là chữ chỉ một loài chuột vằn. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đình\": 鼮 — con chuột (鼠) với lông đốm như sân đình hoa văn, âm \"đình\" gợi sự đứng yên quan sát. | Gương Hán-Việt | Đình — ít dùng trong tiếng Việt; chỉ loài chuột vằn trong điển tích. | Mở khoá kiến thức | Biết 鼮 (đình) giúp nhận bộ Thử (鼠) trong nhóm chữ chỉ các loài gặm nhấm cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi âm Hán Trung cổ tíng, nghĩa là con chuột có đốm (spotted rat), dùng trong văn cổ. Không có phân tích hình-thanh cụ thể. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột vá (có vằn như con báo)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 廷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠廷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼮", "Unihan_Traditional (Chữ Phồn thể)": "鼮", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài chuột có vằn báo, thường làm chủ ngữ hoặc tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('齼', '{"9000": "8764.0", "Chữ Trung Quốc": "齼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 28 | nét | 齒 | xỉ | biểu nghĩa | răng | 楚 | sở | biểu âm | nước Sở (cho âm) | 齼 = 齒 (Xỉ, biểu nghĩa: răng) + 楚 (Sở, biểu âm). Chữ hình thanh: bộ Xỉ cho nghĩa (cảm giác ở răng), 楚 cho âm chǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sở\": 齼 — răng (齒) ê buốt như bị nước Sở (楚) tra tấn bằng vị chua — cảm giác ê nhức khi ăn khế. | Gương Hán-Việt | Sở — ít dùng độc lập trong tiếng Việt; liên quan đến cảm giác răng nhạy cảm. | Mở khoá kiến thức | Biết 齼 (sở) giúp nhận nhóm chữ bộ Xỉ chỉ các tình trạng bệnh lý về răng.", "Tự nguyên_Xie": "Theo Wiktionary, 齼 là chữ hình thanh gồm 齒 (răng, biểu nghĩa) và 楚 (biểu âm). Nghĩa chỉ cảm giác ê buốt ở răng khi ăn đồ chua — một triệu chứng răng nhạy cảm. Chữ hiếm trong tiếng Hán hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răng tê vì ăn chua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "齒 + 楚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齒楚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "楚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齒", "Unihan_Simplified (Chữ Giản thể)": "齼", "Unihan_Traditional (Chữ Phồn thể)": "齼", "Pinyin_Xie": "chǔ", "Âm Hán Việt_Xie": "sở", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ chỉ trạng thái răng bị ghê, buốt do ăn đồ chua. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龝', '{"9000": "8765.0", "Chữ Trung Quốc": "龝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 22 | nét | 龝 | thu | tượng hình | biến thể cổ của 秋 (mùa thu) | 龝 là biến thể cổ của 秋 (Thu), bộ Hòa (禾). Cấu trúc nội bộ chưa được phân tích rõ; chữ tạo muộn, chưa thấy trong giáp cốt/kim văn với dạng này. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thu\": 龝 là biến thể cổ của 秋 — mùa thu vàng óng, chữ phức tạp như vẻ đẹp trù phú của mùa gặt. | Gương Hán-Việt | Thu — trong \"mùa thu\", \"thu hoạch\", \"thu phân\"; gốc chỉ mùa gặt. | Mở khoá kiến thức | Biết 龝 (thu) giúp nhận dạng biến thể cổ của 秋 trong văn bản cổ điển.", "Tự nguyên_Xie": "龝 là dạng biến thể phồn thể của 秋 (mùa thu). Không có Wiktionary phân tích cấu trúc riêng. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mùa thu", "Hạng Tần Suất (Jun Da)": "8765.0", "Tần Suất % (Jun Da)": "99.9998847569", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 龜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾龜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "龝", "Unihan_Traditional (Chữ Phồn thể)": "龝", "Pinyin_Xie": "qiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ mùa thu hoặc thời gian, thường đứng sau giới từ chỉ thời gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禖', '{"9000": "8769.0", "Chữ Trung Quốc": "禖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禖 | mai | tượng hình | lễ cầu tự (bộ Kỳ/Thị) | 禖 thuộc bộ Kỳ/Thị (示, thần linh, lễ nghi). Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu. Nghĩa chỉ nghi lễ cúng bái cầu có con cái. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mai\": 禖 — nghi lễ thần linh (示) cầu có con, như hoa mai nở báo mùa sinh sôi. | Gương Hán-Việt | Mai — ít dùng trong tiếng Việt hiện đại; liên quan đến nghi lễ cổ đại cầu con cái. | Mở khoá kiến thức | Biết 禖 (mai) giúp nhận nhóm chữ bộ Thị (示) liên quan đến lễ nghi và thần linh trong văn hóa cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 禖 có âm Hán Trung cổ méi, nghĩa là nghi lễ tế thần cầu có con, nghi lễ cầu tự. Bộ Thị (示) cho thấy liên quan đến lễ nghi và thần linh. Không có phân tích hình-thanh cụ thể. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ cầu tự", "Hạng Tần Suất (Jun Da)": "8769.0", "Tần Suất % (Jun Da)": "99.9998868241", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 某", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻某", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "某", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禖", "Unihan_Traditional (Chữ Phồn thể)": "禖", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "môi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vị thần cầu tự hoặc nghi lễ cầu con. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禵', '{"9000": "8770.0", "Chữ Trung Quốc": "禵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 22 | nét | 禵 | te | tượng hình | chữ dùng trong tên người (bộ Thị) | 禵 thuộc bộ Thị (示). Cấu trúc nội bộ chưa được phân tích rõ; chữ thường dùng trong tên người thời Thanh triều. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đề\": 禵 — chữ bộ Thị dùng trong tên hoàng tử nhà Thanh, hiếm thấy ngoài danh tính lịch sử. | Gương Hán-Việt | Đề — ít dùng trong tiếng Việt; chủ yếu gặp trong danh tính lịch sử triều Thanh. | Mở khoá kiến thức | Biết 禵 (đề) giúp đọc hiểu tên nhân vật lịch sử trong văn bản cổ điển về triều Thanh.", "Tự nguyên_Xie": "禵 (âm tí) là chữ dùng chủ yếu trong tên riêng, nổi tiếng với hoàng tử Phúc Trinh (禵) nhà Thanh, còn gọi là Doãn Trinh. Không có Wiktionary phân tích cấu trúc. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 題", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻題", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "題", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禵", "Unihan_Traditional (Chữ Phồn thể)": "禵", "Pinyin_Xie": "tí", "Âm Hán Việt_Xie": "de", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ điềm lành hoặc nghi lễ cúng tế cầu phúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秅', '{"9000": "8771.0", "Chữ Trung Quốc": "秅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 8 | nét | 秅 | tra | tượng hình | chữ thuộc bộ Hòa (禾), nghĩa chưa rõ | 秅 thuộc bộ Hòa (禾, lúa). Cấu trúc nội bộ chưa được phân tích rõ. Wiktionary ghi rfdef — nghĩa chưa xác định. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tra\": 秅 — chữ bộ Hòa (禾) chưa rõ nghĩa — như một hạt lúa chưa được phân loại trong kho. | Gương Hán-Việt | Tra — ít dùng trong tiếng Việt; chữ học thuật chưa xác định nghĩa. | Mở khoá kiến thức | Biết 秅 (tra) giúp nhận bộ Hòa (禾) trong nhóm chữ liên quan đến ngũ cốc và nông nghiệp.", "Tự nguyên_Xie": "Wiktionary ghi nhận âm chá, bộ Hòa (禾), nhưng nghĩa chưa được xác định (rfdef). Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秅", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 乇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾乇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秅", "Unihan_Traditional (Chữ Phồn thể)": "秅", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Chữ này làm lượng từ chỉ số lượng bó lúa hoặc ngũ cốc thời xưa. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竌', '{"9000": "8772.0", "Chữ Trung Quốc": "竌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 7 | nét | 竌 | xuất | tượng hình | chữ thuộc bộ Lập (立), nghĩa chưa rõ | 竌 thuộc bộ Lập (立, đứng). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chưa xác định. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Xuất\": 竌 — chữ bộ Lập chưa rõ nghĩa — như một người đứng (立) chưa biết đi về đâu. | Gương Hán-Việt | Xuất — ít dùng trong tiếng Việt; chữ học thuật chưa xác định nghĩa. | Mở khoá kiến thức | Biết 竌 (xuất) giúp nhận bộ Lập (立) trong nhóm chữ liên quan đến tư thế đứng và sự vững chắc.", "Tự nguyên_Xie": "竌 (âm chù) thuộc bộ Lập (立). Không có Wiktionary phân tích cấu trúc hay nghĩa cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "竌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竌", "Unihan_Traditional (Chữ Phồn thể)": "竌", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "xuat", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ miêu tả tư thế đứng thẳng hoặc nghiêm trang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羠', '{"9000": "8773.0", "Chữ Trung Quốc": "羠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 12 | nét | 羠 | di | tượng hình | cừu đực đã thiến (bộ Dương) | 羠 thuộc bộ Dương (羊, cừu/dê). Cấu trúc nội bộ chưa được phân tích rõ. Wiktionary ghi nghĩa là cừu đực đã thiến (wether) hoặc dê cái hoang. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Di\": 羠 — cừu (羊) đực đã thiến, âm \"di\" nhẹ nhàng như con vật hiền lành bị loại khỏi đàn. | Gương Hán-Việt | Di — ít dùng trong tiếng Việt; thuật ngữ chăn nuôi cổ đại. | Mở khoá kiến thức | Biết 羠 (di) giúp nhận bộ Dương (羊) trong nhóm chữ chỉ các loài vật họ cừu/dê.", "Tự nguyên_Xie": "Theo Wiktionary, 羠 có âm yí, bộ Dương (羊), nghĩa là cừu đực đã thiến (wether) hoặc dê cái hoang dã. Không có phân tích hình-thanh cụ thể. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "羠", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺶ + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺶夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺶", "Unihan_Simplified (Chữ Giản thể)": "羠", "Unihan_Traditional (Chữ Phồn thể)": "羠", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài dê đực đã bị thiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翖', '{"9000": "8774.0", "Chữ Trung Quốc": "翖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 12 | nét | 翖 | hap | tượng hình | biến thể cổ của 翕 (bộ Vũ) | 翖 là biến thể cổ của 翕 (Hấp, bộ Vũ). 翕 nghĩa là nhắm lại, thu vào, hòa hợp. Cấu trúc nội bộ chưa được phân tích rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hấp\": 翖 — biến thể cổ của 翕, cánh chim (羽) khép lại thu vào — hấp thụ, hòa hợp. | Gương Hán-Việt | Hấp — ít dùng độc lập; gặp trong \"hấp dẫn\" (thu hút), \"hấp thụ\" (absorb). | Mở khoá kiến thức | Biết 翖 (hấp) giúp nhận dạng biến thể của 翕 trong nhóm chữ chỉ sự thu hút, hòa hợp.", "Tự nguyên_Xie": "Theo Wiktionary, 翖 là biến thể cổ của 翕 (hấp — thu vào, nhắm lại, hòa hợp). Bộ Vũ (羽) liên quan đến cánh chim, động tác khép cánh. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trốn", "Hạng Tần Suất (Jun Da)": "8774.0", "Tần Suất % (Jun Da)": "99.9998909583", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰合羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翖", "Unihan_Traditional (Chữ Phồn thể)": "翖", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hap", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động thu cánh của chim hoặc sự đồng lòng nhất trí. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艣', '{"9000": "8775.0", "Chữ Trung Quốc": "艣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 19 | nét | 艣 | lo | tượng hình | mái chèo đuôi thuyền (bộ Chu) | 艣 thuộc bộ Chu (舟, thuyền). Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu. Nghĩa chỉ mái chèo lái ở đuôi thuyền. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lỗ\": 艣 — mái chèo (bộ Chu) ở đuôi thuyền, chèo lái như người lỗ mãng dùng sức mạnh điều hướng. | Gương Hán-Việt | Lỗ — ít dùng trong tiếng Việt; liên quan đến dụng cụ chèo thuyền cổ đại. | Mở khoá kiến thức | Biết 艣 (lỗ) giúp nhận bộ Chu (舟) trong nhóm chữ liên quan đến thuyền bè và hàng hải.", "Tự nguyên_Xie": "艣 (âm lǔ) thuộc bộ Chu (舟, thuyền), nghĩa là mái chèo lớn ở đuôi thuyền dùng để lái. Không có Wiktionary phân tích cấu trúc. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mái chèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 虜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟虜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "艣", "Unihan_Traditional (Chữ Phồn thể)": "艣", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mái chèo gỗ lớn hoặc động từ chỉ hành động chèo thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚡', '{"9000": "8776.0", "Chữ Trung Quốc": "蚡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚡 | phan | tượng hình | con chuột chũi (bộ Trùng) | 蚡 thuộc bộ Trùng (虫, sâu bọ/động vật nhỏ). Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu. Nghĩa chỉ con chuột chũi. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phần\": 蚡 — con chuột chũi (bộ Trùng) đào bới phần đất dưới lòng đất — âm \"phần\" như bổ đất chia phần. | Gương Hán-Việt | Phần — ít dùng trong tiếng Việt; thuật ngữ chỉ loài động vật trong văn cổ. | Mở khoá kiến thức | Biết 蚡 (phần) giúp nhận bộ Trùng (虫) trong nhóm chữ chỉ các loài động vật nhỏ.", "Tự nguyên_Xie": "Tiểu triện | 蚡 (âm fén) thuộc bộ Trùng (虫), nghĩa là chuột cống hoặc chuột chũi. Không có Wiktionary phân tích cấu trúc hình-thanh. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chuột cống", "Hạng Tần Suất (Jun Da)": "8776.0", "Tần Suất % (Jun Da)": "99.9998919919", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚡", "Unihan_Traditional (Chữ Phồn thể)": "蚡", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loài chuột cống hoặc động từ chỉ sự nổi lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訹', '{"9000": "8777.0", "Chữ Trung Quốc": "訹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 言 | ngôn | biểu nghĩa | lời nói | 朮 | truật | biểu âm | cây truật (cho âm) | 訹 = 言 (Ngôn, biểu nghĩa: lời nói) + 朮 (Truật, biểu âm). Chữ hình thanh: bộ Ngôn cho nghĩa (lời nói gian dối, dụ dỗ), 朮 cho âm xù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tuất\": 訹 — lời (言) mê hoặc như những câu chuyện hoang đường — dụ dỗ bằng lời \"tuất\" (giờ Tuất u tối, lừa bịp trong bóng tối). | Gương Hán-Việt | Tuất — ít dùng trong tiếng Việt; thuật ngữ văn ngôn chỉ hành động dụ dỗ. | Mở khoá kiến thức | Biết 訹 (tuất) giúp nhận nhóm chữ bộ Ngôn chỉ các hành động lời nói tiêu cực trong văn cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 訹 là chữ hình thanh gồm 言 (lời nói, biểu nghĩa) và 朮 (biểu âm). Nghĩa là dùng lời nói gian dối để mê hoặc, dụ dỗ người khác tin vào những điều sai sự thật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "để ngụy tạo với những câu chuyện sai sự thật", "Hạng Tần Suất (Jun Da)": "8777.0", "Tần Suất % (Jun Da)": "99.9998925087", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 术", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言术", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "术", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訹", "Unihan_Traditional (Chữ Phồn thể)": "訹", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tuất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành vi lừa gạt, dụ dỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輂', '{"9000": "8778.0", "Chữ Trung Quốc": "輂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 13 | nét | 輂 | cuc | tượng hình | xe ngựa cổ đại (bộ Xa) | 輂 thuộc bộ Xa (車, xe). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chỉ xe ngựa kéo hoặc dụng cụ chở đất thời cổ đại. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cúc\": 輂 — xe ngựa (bộ Xa) cổ đại chở đất, âm \"cúc\" gợi bánh xe lăn tròn như hoa cúc. | Gương Hán-Việt | Cúc — ít dùng trong tiếng Việt; thuật ngữ phương tiện vận tải cổ đại. | Mở khoá kiến thức | Biết 輂 (cúc) giúp nhận bộ Xa (車) trong nhóm chữ chỉ các loại xe cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi âm jú, bộ Xa (車), nghĩa là xe ngựa kéo trong lịch sử hoặc dụng cụ chở đất. Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe ngựa; dụng cụ chở đất; dụng cụ chuyển đất", "Hạng Tần Suất (Jun Da)": "8778.0", "Tần Suất % (Jun Da)": "99.9998935423", "GavinGrover_Once (Chiết tự trực tiếp)": "共 + 車", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱共車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輂", "Unihan_Traditional (Chữ Phồn thể)": "輂", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại xe thô sơ dùng để chở đất cát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輨', '{"9000": "8779.0", "Chữ Trung Quốc": "輨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 輨 | quan | tượng hình | nắp đầu trục bánh xe (bộ Xa) | 輨 thuộc bộ Xa (車, xe). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chỉ nắp sắt bảo vệ đầu trục bánh xe (hubcap). Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quán\": 輨 — nắp trục xe (bộ Xa) quản lý, bảo vệ bánh xe như quán trọ che chở khách — âm \"quán\" gợi sự bảo vệ. | Gương Hán-Việt | Quán — ít dùng trong tiếng Việt; thuật ngữ kỹ thuật xe cộ cổ đại. | Mở khoá kiến thức | Biết 輨 (quán) giúp nhận bộ Xa (車) trong nhóm chữ chỉ các bộ phận xe cộ cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi âm guǎn, bộ Xa (車), nghĩa là nắp bảo vệ đầu trục bánh xe (hubcap). Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắp sắt ở xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輨", "Unihan_Traditional (Chữ Phồn thể)": "輨", "Pinyin_Xie": "guǎn", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bộ phận bọc bằng kim loại ở đầu trục bánh xe cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遶', '{"9000": "8780.0", "Chữ Trung Quốc": "遶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 15 | nét | 遶 | nhao | tượng hình | biến thể cổ của 繞 (vòng quanh, bộ Sước) | 遶 là biến thể cổ của 繞 (Nhiễu/Nhao — vòng quanh, bao vây), bộ Sước (辵, di chuyển). Cấu trúc nội bộ chưa được phân tích rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nháo\": 遶 — biến thể cổ của 繞, di chuyển (辵) vòng vòng nháo nhác — quanh co bao vây. | Gương Hán-Việt | Nháo — ít dùng độc lập; gặp trong \"nháo nhào\" (quay vòng hỗn loạn). | Mở khoá kiến thức | Biết 遶 (nháo) giúp nhận dạng biến thể cổ của 繞 trong văn bản cổ điển.", "Tự nguyên_Xie": "Theo Wiktionary, 遶 là biến thể cổ của 繞 (vòng quanh, bao vây). Bộ Sước (辵) gợi sự di chuyển vòng vòng. Không có phân tích hình-thanh riêng cho 遶. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xung quanh", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 堯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶堯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遶", "Unihan_Traditional (Chữ Phồn thể)": "遶", "Pinyin_Xie": "rào", "Âm Hán Việt_Xie": "nhao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ chỉ hành động đi vòng quanh hoặc làm giới từ chỉ vị trí xung quanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈆', '{"9000": "8781.0", "Chữ Trung Quốc": "鈆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈆 | dien | tượng hình | chì (kim loại) — dạng cổ bộ Kim | 鈆 thuộc bộ Kim (金, kim loại). Là dạng cổ chỉ kim loại chì. Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Điên\": 鈆 — kim loại chì (bộ Kim) nặng trĩu, âm \"điên\" gợi sự nặng nề điên đảo của khối chì. | Gương Hán-Việt | Điên — ít dùng trong tiếng Việt; thuật ngữ khoáng vật học cổ đại. | Mở khoá kiến thức | Biết 鈆 (điên) giúp nhận bộ Kim (金) trong nhóm chữ chỉ các kim loại cổ đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi 鈆 là dạng cổ chỉ kim loại chì (lead/plumbum). Bộ Kim (金) cho biết đây là kim loại. Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể cũ của 沿 [yán]", "Hạng Tần Suất (Jun Da)": "8781.0", "Tần Suất % (Jun Da)": "99.9998950926", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 公", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金公", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈆", "Unihan_Traditional (Chữ Phồn thể)": "鈆", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ chất chì hoặc động từ chỉ việc đi men theo sông núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鈖', '{"9000": "8782.0", "Chữ Trung Quốc": "鈖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 鈖 | phan | tượng hình | chữ bộ Kim chưa rõ nghĩa | 鈖 thuộc bộ Kim (金, kim loại). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chưa xác định. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Phân\": 鈖 — chữ bộ Kim chưa rõ nghĩa, âm \"phân\" như chia phân kim loại thành từng phần. | Gương Hán-Việt | Phân — ít dùng trong tiếng Việt; chữ học thuật chưa xác định nghĩa. | Mở khoá kiến thức | Biết 鈖 (phân) giúp nhận bộ Kim (金) trong nhóm chữ chỉ kim loại và khoáng sản.", "Tự nguyên_Xie": "鈖 (âm fēn) thuộc bộ Kim (金). Không có Wiktionary phân tích cấu trúc hay nghĩa cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鈖", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鈖", "Unihan_Traditional (Chữ Phồn thể)": "鈖", "Pinyin_Xie": "fēn", "Âm Hán Việt_Xie": "phan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các tài liệu cổ để chỉ một loại khoáng vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绗', '{"9000": "8783.0", "Chữ Trung Quốc": "绗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 绗 | hang | tượng hình | khâu lược, may chần (bộ Mịch) | 绗 thuộc bộ Mịch (糸, tơ sợi). Là dạng giản hóa/biến thể của 絎. Nghĩa là khâu lược hay chần đường chỉ để giữ lớp bông vào vải. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hành\": 绗 — đường chỉ (糸) hành ngang chần qua lớp bông — âm \"hành\" gợi đường may chạy ngang. | Gương Hán-Việt | Hành — ít dùng trong tiếng Việt; thuật ngữ may mặc chỉ đường khâu lược. | Mở khoá kiến thức | Biết 绗 (hành) giúp nhận bộ Mịch (糸) trong nhóm chữ liên quan đến kỹ thuật may vá và dệt may.", "Tự nguyên_Xie": "Wiktionary ghi 绗 (qua dạng 絎) có nghĩa là may chần — đường khâu lỏng để giữ bông lót vào vải ngoài. Bộ Mịch (糸) chỉ liên quan đến sợi chỉ và vải dệt. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khâu lược", "Hạng Tần Suất (Jun Da)": "8783.0", "Tần Suất % (Jun Da)": "99.9998976765", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 行", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟行", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "行", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绗", "Unihan_Traditional (Chữ Phồn thể)": "絎", "Pinyin_Xie": "háng", "Âm Hán Việt_Xie": "hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đứng trước danh từ để chỉ hành động khâu chần vải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐷', '{"9000": "8784.0", "Chữ Trung Quốc": "鐷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐷 | dip | tượng hình | díp, nhíp kim loại (bộ Kim) | 鐷 thuộc bộ Kim (金, kim loại). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chỉ cái díp (nhíp) hoặc dao díp nhỏ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Diệp\": 鐷 — kim loại (金) mỏng như lá (diệp) — díp nhíp mỏng kẹp chặt. | Gương Hán-Việt | Diệp — ít dùng trong tiếng Việt; liên quan đến dụng cụ kim loại mỏng. | Mở khoá kiến thức | Biết 鐷 (diệp) giúp nhận bộ Kim (金) trong nhóm chữ chỉ dụng cụ kim loại nhỏ.", "Tự nguyên_Xie": "鐷 (âm yè) thuộc bộ Kim (金), nghĩa là cái díp/nhíp hoặc dao díp nhỏ bằng kim loại. Không có Wiktionary phân tích cấu trúc. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "díp; như \"cái díp (cái nhíp); dao díp\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 葉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金葉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "葉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鐷", "Unihan_Traditional (Chữ Phồn thể)": "鐷", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "diệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dụng cụ nhỏ bằng kim loại như nhíp hoặc dao xếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闟', '{"9000": "8785.0", "Chữ Trung Quốc": "闟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 20 | nét | 門 | môn | biểu nghĩa | cửa | 翕 | hấp | biểu âm | thu hợp (cho âm xì) | 闟 = 門 (Môn, biểu nghĩa: cửa) + 翕 (Hấp, biểu âm). Chữ hình thanh: bộ Môn cho nghĩa (cửa đóng kín, yên tĩnh), 翕 cho âm xì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hấp\": 闟 = cửa (門) + hấp (翕) — cánh cửa khép lại hấp thụ mọi tiếng ồn — yên tĩnh tuyệt đối. | Gương Hán-Việt | Hấp — ít dùng độc lập trong tiếng Việt; gặp trong văn ngôn chỉ sự yên tĩnh. | Mở khoá kiến thức | Biết 闟 (hấp) giúp nhận nhóm chữ bộ Môn chỉ các trạng thái của cửa và sự yên tĩnh.", "Tự nguyên_Xie": "Theo Wiktionary, 闟 là chữ hình thanh gồm 門 (cửa, biểu nghĩa) và 翕 (biểu âm). Nghĩa là yên bình, lặng lẽ, đột ngột — như cánh cửa khép lại trong yên tĩnh. Chữ hiếm trong tiếng Hán hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên bình; lặng lẽ", "Hạng Tần Suất (Jun Da)": "8785.0", "Tần Suất % (Jun Da)": "99.9998992269", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 翕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門翕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闟", "Unihan_Traditional (Chữ Phồn thể)": "闟", "Pinyin_Xie": "xì", "Âm Hán Việt_Xie": "hấp, tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái yên tĩnh hoặc làm động từ chỉ sự tụ hội. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韮', '{"9000": "8786.0", "Chữ Trung Quốc": "韮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韭 | Số nét | 12 | nét | 韮 | cuu | tượng hình | biến thể của 韭 (hẹ thơm, bộ Cửu) | 韮 là biến thể/dạng tục dùng của 韭 (Cửu — hẹ thơm). Cấu trúc nội bộ chưa được phân tích rõ. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cửu\": 韮 — biến thể cổ của hẹ (韭), cây hẹ \"cửu\" mọc lại suốt nhiều năm như con số cửu bất tận. | Gương Hán-Việt | Cửu — trong \"cửu thái\" (hẹ thơm, tên Hán-Việt của cây hẹ). | Mở khoá kiến thức | Biết 韮 (cửu) giúp nhận dạng biến thể của 韭 trong văn bản cổ và tên thực vật.", "Tự nguyên_Xie": "韮 là biến thể tục dùng của 韭 (hẹ thơm). Wiktionary không có phân tích riêng cho 韮. Chữ 韭 là tượng hình từ cổ đại, mô tả cây hẹ với lá mọc thẳng. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửu; như \"cửu thái (hẹ thơm)\" \n\n§ Tục dùng như chữ 韭.", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 韭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹韭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "韮", "Unihan_Traditional (Chữ Phồn thể)": "韮", "Pinyin_Xie": "jiǔ", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây rau hẹ, thường dùng trong văn bản cổ hoặc tên món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騣', '{"9000": "8787.0", "Chữ Trung Quốc": "騣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 19 | nét | 騣 | tong | tượng hình | bờm ngựa (bộ Mã) | 騣 thuộc bộ Mã (馬, ngựa). Cấu trúc nội bộ chưa được phân tích rõ trong dữ liệu. Nghĩa chỉ bờm (lông cứng) trên cổ ngựa. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tông\": 騣 — bờm ngựa (馬) rủ xuống như dòng tông tộc nối tiếp — lông bờm phất phơ theo gió. | Gương Hán-Việt | Tông — ít dùng trong tiếng Việt; liên quan đến bộ phận của ngựa trong văn cổ. | Mở khoá kiến thức | Biết 騣 (tông) giúp nhận bộ Mã (馬) trong nhóm chữ chỉ các bộ phận và đặc điểm của ngựa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi 騣 thuộc bộ Mã (馬), nghĩa là bờm ngựa — lông cứng mọc trên cổ và đầu ngựa. Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông bờm ngựa", "Hạng Tần Suất (Jun Da)": "4313.0", "Tần Suất % (Jun Da)": "99.8238067594", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鬃", "Unihan_Traditional (Chữ Phồn thể)": "騣", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần lông bờm của ngựa hoặc động vật thuộc họ ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髧', '{"9000": "8788.0", "Chữ Trung Quốc": "髧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髧 | dam | tượng hình | tóc dài buông xõa (bộ Tiêu) | 髧 thuộc bộ Tiêu (髟, tóc dài). Cấu trúc nội bộ chưa được phân tích rõ. Nghĩa chỉ tóc dài buông xõa hoặc vật gì đó rủ xuống. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đảm\": 髧 — tóc (髟) dài buông thõng như gánh nặng đảm đương — xõa xuống vai. | Gương Hán-Việt | Đảm — ít dùng trong tiếng Việt; liên quan đến mô tả tóc rũ trong văn cổ. | Mở khoá kiến thức | Biết 髧 (đảm) giúp nhận bộ Tiêu (髟) trong nhóm chữ chỉ các kiểu tóc và trạng thái tóc.", "Tự nguyên_Xie": "Wiktionary ghi 髧 thuộc bộ Tiêu (髟, tóc dài), nghĩa là tóc dài buông xuống hoặc động từ chỉ sự rủ xuống (tiếng Quảng Đông). Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xoã xuống; buông xoã", "Hạng Tần Suất (Jun Da)": "8788.0", "Tần Suất % (Jun Da)": "99.9999007773", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髧", "Unihan_Traditional (Chữ Phồn thể)": "髧", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái tóc buông xõa xuống trán hoặc vai. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴢', '{"9000": "8789.0", "Chữ Trung Quốc": "鴢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴢 | au | tượng hình | loài chim giống vịt/diệc (bộ Điểu) | 鴢 thuộc bộ Điểu (鳥, chim). Cấu trúc nội bộ chưa được phân tích rõ. Wiktionary ghi nghĩa là một loài chim giống diệc. Chưa có nguồn học thuật đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Ảo\": 鴢 — loài chim (鳥) huyền ảo trong văn cổ, như hình ảnh diệc trắng bay mờ ảo. | Gương Hán-Việt | Ảo — ít dùng trong tiếng Việt; loài chim trong điển tích cổ đại. | Mở khoá kiến thức | Biết 鴢 (ảo) giúp nhận bộ Điểu (鳥) trong nhóm chữ chỉ các loài chim nước cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi 鴢 có âm yòu/yǎo, bộ Điểu (鳥), nghĩa là một loài chim diệc cổ đại. Không có phân tích hình-thanh cụ thể. Chữ tạo muộn, chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(Vịt)", "Hạng Tần Suất (Jun Da)": "8789.0", "Tần Suất % (Jun Da)": "99.999901294", "GavinGrover_Once (Chiết tự trực tiếp)": "幺 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰幺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鴢", "Unihan_Traditional (Chữ Phồn thể)": "鴢", "Pinyin_Xie": "yǎo", "Âm Hán Việt_Xie": "ấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong cổ văn để chỉ một loài chim nước giống vịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鷘', '{"9000": "8790.0", "Chữ Trung Quốc": "鷘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 鷘 | xích | tượng hình | loài chim nước, dạng biến thể của 鶒 | 鷘 là dạng chữ thay thế (variant) của 鶒 (xích), chỉ loài chim nước họ vịt. Chữ dùng bộ 鳥 (điểu) làm thành tố. Cấu trúc thành phần không rõ trong CHISE; chưa có nguồn học thuật phân tích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xích\": chim nước (鸟) mang màu đỏ (赤 xích) — tưởng tượng con chim đỏ lặn xuống mặt hồ. | Gương Hán-Việt | xích trong 鸂鷘 (tên loài chim nước cổ) | Mở khoá kiến thức | Biết 鷘 (xích) giúp nhận ra nhóm chim nước cổ điển trong văn học Hán.", "Tự nguyên_Xie": "鷘 là dạng chữ khác của 鶒, theo Wiktionary. Chưa có phân tích nguồn gốc hình chữ riêng biệt. Âm Hán-Việt tái lập là *xích* theo âm Trung cổ (Middle Chinese *ɖʱɨk). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá bống tượng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "敕 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敕鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鷘", "Unihan_Traditional (Chữ Phồn thể)": "鷘", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "xích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đi kèm trong từ ghép để chỉ một loài chim nước cổ xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黺', '{"9000": "8791.0", "Chữ Trung Quốc": "黺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黹 | Số nét | 16 | nét | 黺 | phẫn | tượng hình | hoa văn màu sắc rực rỡ; dạng chữ cổ của 紛 | 黺 dùng bộ 黹 (trù — thêu thùa) làm thành tố chính. Cấu trúc chi tiết chưa rõ trong CHISE. Chữ chỉ hoa văn sặc sỡ, có âm phẫn/phế theo âm Trung cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫn\": bộ thêu thùa (黹) kết hợp với màu sắc rực rỡ — tưởng tượng thợ thêu tạo ra những hoa văn (phẫn) sặc sỡ trên vải. | Gương Hán-Việt | phẫn — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 黺 (phẫn) giúp nhận ra nhóm chữ liên quan đến nghề thêu thùa trong văn bản cổ.", "Tự nguyên_Xie": "Tiểu triện | 黺 theo Wiktionary có âm Trung cổ *pɨonX và *bɨu, chỉ ''hoa văn nhiều màu sắc'' (colorful pattern). Đây là chữ cổ ghi trong từ điển, không phổ biến trong văn bản thông thường. Có dạng tiểu triện còn lưu lại. Chưa có nguồn học thuật phân tích chi tiết nguồn gốc hình chữ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "黹 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黹分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黹", "Unihan_Simplified (Chữ Giản thể)": "黺", "Unihan_Traditional (Chữ Phồn thể)": "黺", "Pinyin_Xie": "fěn", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tóc hoặc kiểu tóc của phụ nữ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祶', '{"9000": "8792.0", "Chữ Trung Quốc": "祶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 11 | nét | 祶 | đế | tượng hình | chữ liên quan đến tế lễ, dưới bộ 示 | 祶 dùng bộ 示 (thị — thần linh, tế lễ) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *đế* theo âm Trung cổ (Middle Chinese *deiH). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đế\": bộ tế lễ (示) — chữ liên quan đến nghi lễ thờ cúng (đế) trong tín ngưỡng cổ. | Gương Hán-Việt | đế — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 祶 (đế) giúp nhận nhóm chữ tế lễ dưới bộ 示 trong văn bản cổ.", "Tự nguyên_Xie": "祶 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 示 gợi ý liên quan đến tế lễ hoặc thần linh. Âm pinyin *dì* tương ứng với âm Hán-Việt *đế* hoặc *đễ*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祶", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 弟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻弟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祶", "Unihan_Traditional (Chữ Phồn thể)": "祶", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại áo dùng trong nghi lễ cúng tế hoặc khâm liệm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荮', '{"9000": "8793.0", "Chữ Trung Quốc": "荮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 紂 | trụ | biểu âm | 荮 = 艹 (Thảo, biểu nghĩa: cỏ) + 紂 (Trụ, biểu âm); chữ hình thanh. Phần 艹 xác định nghĩa liên quan đến thực vật; phần 紂 (trụ) cho âm gần *zhòu*.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụ\": bó cỏ (艹) buộc chắc như cái trụ (紂 trụ) — hình ảnh bó rơm bện chặt. | Gương Hán-Việt | trụ — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 荮 (trụ) giúp nhận nhóm chữ thực vật hình thanh với bộ 艹 trong văn bản phương ngữ.", "Tự nguyên_Xie": "荮 theo Wiktionary là chữ hình thanh (psc): 艹 biểu nghĩa (cỏ) + 紂 biểu âm. Có âm Trung cổ *drjuwH. Nghĩa gốc là ''một loại cỏ''; trong phương ngữ còn có nghĩa ''bọc hoặc buộc bằng rơm''. Chưa có hình ảnh hình chữ cổ lưu lại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấn bằng cỏ; bọc bằng cỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 纣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹纣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "纣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荮", "Unihan_Traditional (Chữ Phồn thể)": "荮", "Pinyin_Xie": "zhòu", "Âm Hán Việt_Xie": "dược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động dùng cỏ hoặc rơm để bao bọc, bảo vệ đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞏', '{"9000": "8794.0", "Chữ Trung Quốc": "瞏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 15 | nét | 瞏 | quỳnh | tượng hình | nhìn cô đơn, kinh hoàng; dạng chữ liên quan đến mắt (目) | 瞏 dùng bộ 目 (mục — mắt) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *quỳnh* theo âm Trung cổ (Middle Chinese *gjowng). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳnh\": đôi mắt (目) nhìn trống rỗng cô đơn (quỳnh) — ánh mắt lạc lõng giữa đêm khuya. | Gương Hán-Việt | quỳnh — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 瞏 (quỳnh) giúp nhận nhóm chữ diễn tả trạng thái mắt nhìn trong văn bản cổ.", "Tự nguyên_Xie": "瞏 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Nghĩa cô đơn, nhìn trong nỗi kinh hoàng gắn với bộ 目 (mắt). Âm pinyin *qióng* tương ứng Hán-Việt *quỳnh*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cô đơn; nhìn trong nỗi kinh hoàng", "Hạng Tần Suất (Jun Da)": "8794.0", "Tần Suất % (Jun Da)": "99.999903878", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 袁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒袁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "瞏", "Unihan_Traditional (Chữ Phồn thể)": "瞏", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "quỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để tả cảnh cô đơn, lo sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稴', '{"9000": "8795.0", "Chữ Trung Quốc": "稴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 稴 | liêm | tượng hình | rơm rạ; chữ cổ bộ 禾 | 稴 dùng bộ 禾 (hòa — lúa) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *liêm* theo âm Trung cổ (Middle Chinese *ɦem). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\": cây lúa (禾) sau mùa gặt còn lại rơm rạ (liêm) — hình ảnh đồng lúa trơ gốc rạ. | Gương Hán-Việt | liêm — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 稴 (liêm) giúp nhận nhóm chữ lúa gạo dưới bộ 禾 trong nông nghiệp cổ.", "Tự nguyên_Xie": "稴 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 禾 gợi ý nghĩa liên quan đến lúa, rơm rạ. Âm pinyin *xián* tương ứng Hán-Việt *liêm* hoặc *hiêm*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rơm; như \"rơm rạ\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 兼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾兼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稴", "Unihan_Traditional (Chữ Phồn thể)": "稴", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ các loại rơm rạ hoặc lúa lép trong nông nghiệp cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笲', '{"9000": "8796.0", "Chữ Trung Quốc": "笲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 笲 | phàn | tượng hình | giỏ tre của cô dâu; chữ cổ bộ 竹 | 笲 dùng bộ 竹 (trúc — tre) làm thành tố. Wiktionary ghi rõ nghĩa là giỏ tre dùng trong lễ cưới của cô dâu. Âm Hán-Việt tái lập là *phàn* theo âm Trung cổ (Middle Chinese *bɨon). Chưa có hình ảnh hình chữ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": giỏ tre (竹) mang theo trong lễ cưới — cô dâu (phàn) xách giỏ tre về nhà chồng. | Gương Hán-Việt | phàn — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 笲 (phàn) giúp nhận nhóm chữ đồ vật bằng tre trong văn hóa hôn nhân cổ.", "Tự nguyên_Xie": "笲 theo Wiktionary có âm Trung cổ *bɨon, nghĩa là ''giỏ tre của cô dâu'' (bride''s basket made of bamboo). Chữ hình thanh với bộ 竹 biểu nghĩa (tre). Chưa có hình ảnh hình chữ cổ lưu lại. Chưa có nguồn học thuật phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giỏ cô dâu osier", "Hạng Tần Suất (Jun Da)": "8796.0", "Tần Suất % (Jun Da)": "99.9999049115", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "笲", "Unihan_Traditional (Chữ Phồn thể)": "笲", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ loại giỏ tre mà cô dâu dùng để đựng lễ vật ngày xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笿', '{"9000": "8797.0", "Chữ Trung Quốc": "笿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 笿 | lạc | tượng hình | khay, mâm tre; lồng tre | 笿 dùng bộ 竹 (trúc — tre) làm thành tố. Wiktionary ghi âm Trung cổ và nghĩa nhưng thiếu định nghĩa cụ thể. Âm Hán-Việt tái lập là *lạc* theo âm Trung cổ (Middle Chinese *lɑk). Chưa có hình ảnh hình chữ cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": vật bằng tre (竹) đặt thức ăn — mâm lạc bằng tre trong bữa ăn cổ. | Gương Hán-Việt | lạc — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 笿 (lạc) giúp nhận nhóm chữ đồ dùng nhà bếp bằng tre trong văn bản cổ.", "Tự nguyên_Xie": "笿 theo Wiktionary có âm Trung cổ *lɑk. Bộ 竹 biểu nghĩa (tre). Nghĩa có thể là khay hoặc mâm bằng tre. Wiktionary đánh dấu rfdef (cần định nghĩa). Chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khay chén bát; mâm tre (bằng tre); lồng tre", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笿", "Unihan_Traditional (Chữ Phồn thể)": "笿", "Pinyin_Xie": "luò", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các vật dụng bằng tre dùng để đựng chén bát hoặc đồ đạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縪', '{"9000": "8798.0", "Chữ Trung Quốc": "縪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縪 | bí | tượng hình | chữ cổ bộ 糸, liên quan đến dây buộc | 縪 dùng bộ 糸 (mịch — tơ lụa, dây) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *bí* theo âm Trung cổ (Middle Chinese *bjit). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": sợi tơ (糸) buộc chặt bí mật (bí) — dây tơ thắt kín không gỡ được. | Gương Hán-Việt | bí — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 縪 (bí) giúp nhận nhóm chữ dây buộc tơ lụa trong văn bản cổ.", "Tự nguyên_Xie": "縪 theo Wiktionary có âm Trung cổ *bjit, dùng bộ 糸 biểu nghĩa (tơ, dây). Wiktionary đánh dấu rfdef. Không rõ nghĩa cụ thể ngoài liên quan đến dây buộc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縪", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 畢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹畢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縪", "Unihan_Traditional (Chữ Phồn thể)": "縪", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ dải dây buộc mũ hoặc đường viền trang trí trên trang phục cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翸', '{"9000": "8799.0", "Chữ Trung Quốc": "翸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 18 | nét | 翸 | phẫn | tượng hình | xiềng xích; chữ cổ bộ 羽 | 翸 dùng bộ 羽 (vũ — lông vũ) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *phẫn* theo âm Trung cổ (Middle Chinese *pɨonX). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫn\": đôi cánh (羽) bị xiềng lại — chim bị trói không bay được, phẫn uất (phẫn). | Gương Hán-Việt | phẫn — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 翸 (phẫn) giúp nhận nhóm chữ liên quan đến cánh và sự trói buộc trong văn bản cổ.", "Tự nguyên_Xie": "翸 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Nghĩa ''xiềng xích'' kết hợp với bộ 羽 (lông vũ) gợi ra hình ảnh trói buộc đôi cánh. Âm pinyin *pěn* tương ứng Hán-Việt *phẫn*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xiềng xích", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "賁 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰賁羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "賁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翸", "Unihan_Traditional (Chữ Phồn thể)": "翸", "Pinyin_Xie": "pěn", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái dang cánh bay của loài chim. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肧', '{"9000": "8800.0", "Chữ Trung Quốc": "肧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肧 | phôi | tượng hình | phôi thai; dạng chữ khác của 胚 | 肧 là dạng chữ khác của 胚 (phôi), dùng bộ 肉 (nhục — thịt, cơ thể). Wiktionary xác nhận đây là biến thể của 胚 (phôi thai). Âm Hán-Việt là *phôi*.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phôi\": cơ thể (肉/月) ở giai đoạn phôi (phôi) — khởi đầu mầm sống nhỏ bé trong bụng mẹ. | Gương Hán-Việt | phôi trong 胚胎 (phôi thai — giai đoạn đầu của thai nhi) | Mở khoá kiến thức | Biết 肧 (phôi) giúp nhận từ 胚胎 (phôi thai), 胚芽 (phôi mầm) trong sinh học.", "Tự nguyên_Xie": "Tiểu triện | 肧 theo Wiktionary là dạng chữ thay thế của 胚 (phôi). Có âm Trung cổ *pɨj. Bộ 肉 (月) biểu nghĩa (cơ thể, sinh học). Nghĩa là phôi thai, giai đoạn đầu của sự phát triển. Có hình tiểu triện lưu lại từ hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "2922.0", "Tần Suất % (Jun Da)": "99.1034785645", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 不", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月不", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胚", "Unihan_Traditional (Chữ Phồn thể)": "肧", "Pinyin_Xie": "pēi", "Âm Hán Việt_Xie": "phôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các danh từ khác để chỉ trạng thái phôi thai, sơ khai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臶', '{"9000": "8801.0", "Chữ Trung Quốc": "臶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 至 | Số nét | 12 | nét | 臶 | tiễn | tượng hình | hắt hơi; chữ cổ bộ 至 | 臶 dùng bộ 至 (chí — đến, tới) làm thành tố. Wiktionary ghi âm jiàn và nghĩa hắt hơi nhưng đánh dấu rfdef. Âm Hán-Việt tái lập là *tiễn* theo âm Trung cổ (Middle Chinese *dzjænH). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiễn\": khi hắt hơi, hơi thở bắn ra tới (至) nơi xa — tiễn (tiễn) hơi ra ngoài. | Gương Hán-Việt | tiễn — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 臶 (tiễn) giúp nhận nhóm chữ cổ bộ 至 trong văn bản y học cổ.", "Tự nguyên_Xie": "臶 theo Wiktionary có âm Trung cổ *dzjænH, nghĩa là hắt hơi. Bộ 至 không có liên hệ ngữ nghĩa rõ ràng với nghĩa này. Wiktionary đánh dấu rfdef. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hắt hơi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "至 + 存", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰至存", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "存", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "至", "Unihan_Simplified (Chữ Giản thể)": "臶", "Unihan_Traditional (Chữ Phồn thể)": "臶", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường dùng làm phó từ đứng trước động từ để chỉ hành động lặp đi lặp lại nhiều lần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜸', '{"9000": "8802.0", "Chữ Trung Quốc": "蜸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜸 | thiển | tượng hình | chữ cổ bộ 虫, chưa rõ nghĩa | 蜸 dùng bộ 虫 (trùng — sâu bọ, côn trùng) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *thiển* theo âm Trung cổ (Middle Chinese *tshjænX). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiển\": côn trùng (虫) nhỏ thiển cận (thiển) — sinh vật bé bằng mắt thường khó thấy. | Gương Hán-Việt | thiển — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 蜸 (thiển) giúp nhận nhóm chữ côn trùng ít phổ biến trong văn bản cổ.", "Tự nguyên_Xie": "蜸 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 虫 gợi ý liên quan đến côn trùng hoặc sinh vật nhỏ. Âm pinyin *qiǎn* tương ứng Hán-Việt *thiển*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蜸", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "臤 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱臤虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜸", "Unihan_Traditional (Chữ Phồn thể)": "蜸", "Pinyin_Xie": "qiǎn", "Âm Hán Việt_Xie": "thiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loài côn trùng hoặc sâu đất trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豊', '{"9000": "8803.0", "Chữ Trung Quốc": "豊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豆 | Số nét | 13 | nét | 壴 | trú | trống | 玨 | giác | chuỗi ngọc bích | 豊 = 壴 (Trú, trống) + 玨 (Giác, chuỗi ngọc bích); chữ hội ý. Hình gốc mô tả nghi lễ với trống và ngọc, là dạng ban đầu của chữ 禮 (lễ). Trong một số kim văn, 壴 bị tách ra, với 豆 ở phía dưới — biến thể do viết sai dẫn đến cách giải thích sai của Thuyết Văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lễ\": trống (壴) và ngọc (玨) cùng nhau trong nghi lễ — lễ (lễ) là sự kết hợp âm nhạc và báu vật trong tế lễ cổ. | Gương Hán-Việt | lễ trong 豊年 (năm được mùa, phong lưu) | Mở khoá kiến thức | Biết 豊 (lễ) mở khoá chữ 禮 (lễ nghi) và hiểu nguồn gốc nghi lễ trong văn hóa Đông Á.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | 豊 theo Wiktionary là chữ hội ý (ic): 壴 (trống) + 玨 (chuỗi ngọc) — nghi lễ với trống và ngọc. Đây là dạng ban đầu của 禮 (lễ nghi). Trong một số kim văn, 壴 bị tách thành hai phần với 豆 ở dưới, khiến Thuyết Văn giải thích sai là chữ tượng hình. Có hình giáp cốt, kim văn, bạch thư và tiểu triện lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1027.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khúc (496) Đậu (153)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khúc (số 496 - cong/chỉ âm) ở trên chữ Đậu (số 153 - bát chân cao). Giải thích sự chuyển ý: Đây là chữ Hội ý (hoặc Hình thanh). Lễ là đồ dùng khi cúng tế, đồ thờ (cũng là chữ Lễ trong Lễ nghi, sau này thêm bộ Thị 礻 thành 禮). Chữ có âm là Phong nghĩa là phong phú.", "Nghĩa Tiếng Việt_Xie": "Toyo", "Hạng Tần Suất (Jun Da)": "8803.0", "Tần Suất % (Jun Da)": "99.9999090458", "GavinGrover_Once (Chiết tự trực tiếp)": "曲 + 豆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱曲豆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豆", "Unihan_Simplified (Chữ Giản thể)": "豊", "Unihan_Traditional (Chữ Phồn thể)": "豊", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các nghi lễ, nghi thức cúng tế hoặc phép tắc ứng xử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輐', '{"9000": "8804.0", "Chữ Trung Quốc": "輐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 14 | nét | 輐 | uyển | tượng hình | đài hoa; chữ cổ bộ 車 | 輐 dùng bộ 車 (xa — xe) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *uyển* theo âm Trung cổ (Middle Chinese *ʔwɑnH). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": bánh xe (車) trang trí như đài hoa uyển chuyển (uyển) — vành xe thêu hoa văn. | Gương Hán-Việt | uyển — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 輐 (uyển) giúp nhận nhóm chữ xe cộ trang trí trong văn bản cổ.", "Tự nguyên_Xie": "輐 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 車 gợi ý liên quan đến xe cộ. Nghĩa ''đài hoa'' không rõ liên hệ với bộ 車. Âm pinyin *wàn* tương ứng Hán-Việt *uyển* hoặc *vạn*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đài hoa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輐", "Unihan_Traditional (Chữ Phồn thể)": "輐", "Pinyin_Xie": "wàn", "Âm Hán Việt_Xie": "ngoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để miêu tả trạng thái tròn trịa hoặc động từ chỉ việc đẽo gọt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('輘', '{"9000": "8805.0", "Chữ Trung Quốc": "輘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 輘 | lăng | tượng hình | xe nghiến qua; tiếng xe lăn ầm ầm | 輘 dùng bộ 車 (xa — xe) làm thành tố. Wiktionary ghi ba âm: léng, líng, lèng với nghĩa tiếng xe lăn ầm, hoặc trục xe. Âm Hán-Việt tái lập là *lăng* theo âm Trung cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": xe (車) lao qua với tiếng lăng lăng — bánh xe nghiến qua đường sỏi ầm ầm. | Gương Hán-Việt | lăng — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 輘 (lăng) giúp nhận nhóm chữ âm thanh xe cộ trong thơ văn cổ.", "Tự nguyên_Xie": "輘 theo Wiktionary có ba âm: léng (âm Trung cổ *leng), líng và lèng, nghĩa là tiếng xe lăn ầm ầm (輘輷), hoặc trục xe. Chữ thuần bộ 車. Chưa có hình ảnh hình chữ cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xe nghiến qua", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "輘", "Unihan_Traditional (Chữ Phồn thể)": "輘", "Pinyin_Xie": "léng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ âm thanh của xe hoặc động từ chỉ hành động xe lăn qua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雘', '{"9000": "8806.0", "Chữ Trung Quốc": "雘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 17 | nét | 雘 | hoắc | tượng hình | đá đỏ, sắc tố đỏ; chữ cổ bộ 隹 | 雘 dùng bộ 隹 (chuy — chim nhỏ, đuôi ngắn) làm thành tố. Wiktionary ghi nghĩa là sắc tố đỏ nhưng không phân tích hình chữ. Âm Hán-Việt tái lập là *hoắc* theo âm Trung cổ (Middle Chinese *wɑk). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoắc\": đá đỏ quý (雘 hoắc) — sắc tố đỏ chiết xuất từ khoáng vật dùng trong tranh vẽ cung đình. | Gương Hán-Việt | hoắc trong 丹雘 (đan hoắc — sắc tố đỏ quý) | Mở khoá kiến thức | Biết 雘 (hoắc) giúp nhận từ 丹雘 trong văn học cổ chỉ màu son đỏ quý.", "Tự nguyên_Xie": "雘 theo Wiktionary có âm Trung cổ *wɑk (hoặc *ʔwɑk), nghĩa là đá màu đỏ, sắc tố đỏ dùng trong tranh vẽ và trang trí cổ. Bộ 隹 không có liên hệ rõ ràng với nghĩa này. Chưa có hình ảnh hình chữ cổ. Chưa có nguồn học thuật phân tích chi tiết. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ đá đỏ)", "Hạng Tần Suất (Jun Da)": "8806.0", "Tần Suất % (Jun Da)": "99.9999116297", "GavinGrover_Once (Chiết tự trực tiếp)": "丹 + 蒦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰丹蒦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丹", "Unihan_Simplified (Chữ Giản thể)": "雘", "Unihan_Traditional (Chữ Phồn thể)": "雘", "Pinyin_Xie": "wò", "Âm Hán Việt_Xie": "hoạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại khoáng vật màu đỏ thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眞', '{"9000": "8808.0", "Chữ Trung Quốc": "眞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眞 | chân | tượng hình | dạng chữ thay thế của 真 (chân thật, thực sự) | 眞 là dạng chữ cũ của 真. Wiktionary ghi IDS là ⿳匕⿺𠃊目八, gồm: 匕 (thìa/dao) + 𠃊 (chữ uốn) + 目 (mắt) + 八 (tám/phân kỳ). Đây là dạng kim văn và tiểu triện của 真, chưa có phân tích thống nhất về hội ý hay hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chân\": đôi mắt (目) nhìn thẳng thật sự (chân) — ánh mắt thành thật không che giấu, đó là chân thật (chân). | Gương Hán-Việt | chân trong 眞實 (chân thực), 眞理 (chân lý), 眞心 (chân tâm) | Mở khoá kiến thức | Biết 眞 (chân) mở khoá 眞實 (chân thực), 眞理 (chân lý), 眞誠 (chân thành).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 眞 là dạng chữ cổ của 真 theo Wiktionary. Có hình kim văn và tiểu triện lưu lại. Wiktionary ghi cấu trúc IDS phức tạp (⿳匕⿺𠃊目八) nhưng không phân tích nguồn gốc hội ý hay hình thanh rõ ràng. Âm Hán-Việt là *chân* (Middle Chinese *tɕin). Chữ này là nguồn gốc của nhiều chữ phái sinh như 嗔, 塡, 鎭. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ĐÚNG VẬY", "Hạng Tần Suất (Jun Da)": "8808.0", "Tần Suất % (Jun Da)": "99.9999131801", "GavinGrover_Once (Chiết tự trực tiếp)": "匕 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "眞", "Unihan_Traditional (Chữ Phồn thể)": "眞", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "chân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc phó từ đứng trước động từ để biểu thị mức độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睴', '{"9000": "8809.0", "Chữ Trung Quốc": "睴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 目 | mục | biểu nghĩa | mắt | 軍 | quân | biểu âm | 睴 = 目 (Mục, biểu nghĩa: mắt) + 軍 (Quân, biểu âm); chữ hình thanh. Phần 目 xác định nghĩa liên quan đến mắt nhìn; phần 軍 (quân) cho âm gần *gùn*.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"côn\": đôi mắt (目) của quân sĩ (軍 quân) nhìn thẳng — ánh nhìn nghiêm nghị của người lính. | Gương Hán-Việt | côn — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 睴 (côn) giúp nhận nhóm chữ hình thanh bộ 目 trong văn bản cổ.", "Tự nguyên_Xie": "Tiểu triện | 睴 theo Wiktionary là chữ hình thanh (psc): 目 biểu nghĩa (mắt) + 軍 biểu âm. Wiktionary đánh dấu rfdef cho nghĩa cụ thể. Có hình tiểu triện lưu lại từ wikimedia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "睴", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睴", "Unihan_Traditional (Chữ Phồn thể)": "睴", "Pinyin_Xie": "gùn", "Âm Hán Việt_Xie": "côn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động trợn mắt hoặc nhìn chăm chú vào một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞡', '{"9000": "8810.0", "Chữ Trung Quốc": "瞡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 瞡 | quý | tượng hình | chữ cổ bộ 目, chưa rõ nghĩa cụ thể | 瞡 dùng bộ 目 (mục — mắt) làm thành tố. Wiktionary ghi âm guī và rfdef cho nghĩa. Âm Hán-Việt tái lập là *quý* theo âm Trung cổ (Middle Chinese *kwej). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quý\": đôi mắt (目) nhìn quý trọng (quý) — ánh mắt trân trọng điều gì đó. | Gương Hán-Việt | quý — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 瞡 (quý) giúp nhận nhóm chữ bộ 目 ít phổ biến trong văn bản cổ.", "Tự nguyên_Xie": "瞡 theo Wiktionary có âm Trung cổ *kwej, nghĩa chưa rõ (rfdef). Bộ 目 gợi ý liên quan đến mắt nhìn. Có thể xuất hiện trong từ ghép 瞡瞡. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "硡", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 規", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目規", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "規", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞡", "Unihan_Traditional (Chữ Phồn thể)": "瞡", "Pinyin_Xie": "guǐ", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành vi nhìn hoặc quan sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砏', '{"9000": "8811.0", "Chữ Trung Quốc": "砏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 砏 | bân | tượng hình | chữ cổ bộ 石, chưa rõ nghĩa | 砏 dùng bộ 石 (thạch — đá) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *bân* theo âm Trung cổ (Middle Chinese *pen). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bân\": đá (石) vỡ bân tứ tán (bân) — tiếng đá vỡ ra nhiều mảnh nhỏ. | Gương Hán-Việt | bân — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 砏 (bân) giúp nhận nhóm chữ đá cổ ít phổ biến trong văn bản địa chất cổ.", "Tự nguyên_Xie": "砏 không có dữ liệu nguồn gốc hình chữ trong Wiktionary (rfdef). Bộ 石 gợi ý liên quan đến đá. Âm pinyin *fēn/bīn* tương ứng Hán-Việt *bân* hoặc *phân*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Lý", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砏", "Unihan_Traditional (Chữ Phồn thể)": "砏", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "bân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Dùng làm danh từ chỉ âm thanh hoặc tính từ miêu tả tính chất của đá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粿', '{"9000": "8812.0", "Chữ Trung Quốc": "粿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 14 | nét | 米 | mễ | biểu nghĩa | gạo | 果 | quả | biểu âm | 粿 = 米 (Mễ, biểu nghĩa: gạo) + 果 (Quả, biểu âm); chữ hình thanh. Phần 米 xác định nghĩa là thực phẩm từ gạo; phần 果 (quả) cho âm *guǒ*.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\": gạo (米) nặn thành hình quả (果 quả) — bánh gạo (quả) tròn xinh làm từ nếp hấp. | Gương Hán-Việt | quả trong 粿條 (quả điều — bánh gạo thái sợi, phở kiểu Mân Nam) | Mở khoá kiến thức | Biết 粿 (quả) giúp nhận các món ăn Mân Nam: 粿條 (bún gạo), 碗粿 (bánh bát), 菜頭粿 (bánh củ cải).", "Tự nguyên_Xie": "粿 theo Wiktionary là chữ hình thanh (psc): 米 biểu nghĩa (gạo) + 果 biểu âm. Nghĩa là bánh gạo nếp hấp (rice cake, thường dùng trong ẩm thực Mân Nam và Triều Châu). Chưa có hình ảnh hình chữ cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh gạo (thường được làm bằng bột gạo nếp và hấp)", "Hạng Tần Suất (Jun Da)": "8812.0", "Tần Suất % (Jun Da)": "99.999915764", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粿", "Unihan_Traditional (Chữ Phồn thể)": "粿", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại bánh làm từ bột gạo nếp ở vùng Mân Nam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紘', '{"9000": "8813.0", "Chữ Trung Quốc": "紘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 紘 | hoằng | tượng hình | dây đội mũ; chữ bộ 糸 | 紘 dùng bộ 糸 (mịch — tơ lụa, dây) làm thành tố. Wiktionary ghi âm hóng và nghĩa liên quan đến dây hoặc mở rộng. Âm Hán-Việt tái lập là *hoằng* theo âm Trung cổ (Middle Chinese *ɦwɨŋ). Có hình tiểu triện lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoằng\": sợi dây (糸) mở rộng hoằng (hoằng) — dây tơ kéo dài bốn phương, ý chí bao la. | Gương Hán-Việt | hoằng trong 八紘 (bát hoằng — tám cực của vũ trụ) | Mở khoá kiến thức | Biết 紘 (hoằng) giúp nhận từ 八紘 trong văn học triết học cổ chỉ sự rộng lớn vũ trụ.", "Tự nguyên_Xie": "Tiểu triện | 紘 theo Wiktionary có âm Trung cổ *ɦwɨŋ. Bộ 糸 biểu nghĩa (dây tơ). Nghĩa liên quan đến dây đội mũ hoặc dây buộc rộng lớn. Xuất hiện trong 八紘 (bát hoằng — tám dây, ý nghĩa vũ trụ rộng lớn). Có hình tiểu triện lưu lại từ wikimedia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Hồng", "Hạng Tần Suất (Jun Da)": "6300.0", "Tần Suất % (Jun Da)": "99.9898353532", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 厷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹厷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "纮", "Unihan_Traditional (Chữ Phồn thể)": "紘", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hoằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ dây mũ hoặc tính từ chỉ sự to lớn bao la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舋', '{"9000": "8814.0", "Chữ Trung Quốc": "舋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 臼 | Số nét | 20 | nét | 舋 | hấn | tượng hình | dạng chữ thay thế của 釁; dùng máu thú tế lễ, xung đột | 舋 là dạng chữ thay thế của 釁 (hấn). Dùng bộ 臼 (cữu — cối giã). Nghĩa gốc liên quan đến dùng máu súc vật bôi vào đồ thờ cúng, hoặc xung đột, phân tranh. Âm Hán-Việt là *hấn*.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hấn\": cối giã (臼) nhuốm máu — nghi lễ hấn (hấn) bôi máu thú vật lên đồ tế; cũng là mầm bất hoà. | Gương Hán-Việt | hấn trong 釁端 (hấn đoan — mầm mống xung đột) | Mở khoá kiến thức | Biết 舋 (hấn) giúp nhận 釁 và từ 釁端 (hấn đoan — mầm xung đột) trong văn học cổ.", "Tự nguyên_Xie": "舋 theo Wiktionary là dạng chữ thay thế của 釁 (hấn). Có âm Trung cổ *xɨnH. Nghĩa là dùng máu súc vật bôi vào đồ thờ cúng (nghi lễ tịnh vật), hoặc cãi nhau, xung đột, phân tranh. Chưa có hình ảnh hình chữ cổ riêng biệt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy máu súc vật bôi vào đồ thờ cúng; lấy phấn sáp thơm xoa vào người; cãi nhau, xung đột, phân tranh", "Hạng Tần Suất (Jun Da)": "8814.0", "Tần Suất % (Jun Da)": "99.9999167976", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舋", "Unihan_Traditional (Chữ Phồn thể)": "舋", "Pinyin_Xie": "xìn", "Âm Hán Việt_Xie": "hấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ mối hiềm khích hoặc động từ chỉ việc bôi máu tế lễ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葋', '{"9000": "8815.0", "Chữ Trung Quốc": "葋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葋 | cừ | tượng hình | một loại cỏ; chữ cổ bộ 艸 | 葋 dùng bộ 艸 (thảo — cỏ, thực vật) làm thành tố. Wiktionary ghi rõ nghĩa là ''một loại cỏ'' (obs-std). Âm Hán-Việt tái lập là *cừ* theo âm Trung cổ (Middle Chinese *gjɨo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cừ\": cỏ (艸) mọc thẳng như cừ (cừ) — loại cỏ thân thẳng trong đồng cỏ cổ. | Gương Hán-Việt | cừ — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 葋 (cừ) giúp nhận nhóm chữ thực vật cổ hiếm trong bản thảo dược học.", "Tự nguyên_Xie": "葋 theo Wiktionary có âm Trung cổ *gjɨo, nghĩa là ''một loại cỏ'' (obs-std — tiêu chuẩn cổ). Bộ 艸 biểu nghĩa (thực vật). Chưa có hình ảnh hình chữ cổ và phân tích chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Vườn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 朐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹朐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葋", "Unihan_Traditional (Chữ Phồn thể)": "葋", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ để chỉ một loại cây cỏ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薭', '{"9000": "8816.0", "Chữ Trung Quốc": "薭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薭 | bái | tượng hình | chữ cổ bộ 艸, chưa rõ nghĩa | 薭 dùng bộ 艸 (thảo — cỏ, thực vật) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *bái* theo âm Trung cổ (Middle Chinese *brajs). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": cỏ (艸) cúi đầu bái (bái) — loại cỏ rũ xuống như nghiêng mình kính cẩn. | Gương Hán-Việt | bái — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 薭 (bái) giúp nhận nhóm chữ thực vật cổ hiếm trong văn bản bản thảo học.", "Tự nguyên_Xie": "薭 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 艸 gợi ý liên quan đến thực vật. Âm pinyin *bai* tương ứng Hán-Việt *bái*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "薭", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 稗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹稗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "稗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薭", "Unihan_Traditional (Chữ Phồn thể)": "薭", "Pinyin_Xie": "bai", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loài cỏ dại mọc hoang ruộng lúa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('虲', '{"9000": "8817.0", "Chữ Trung Quốc": "虲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 8 | nét | 虲 | hà | tượng hình | chữ cổ bộ 虫, chưa rõ nghĩa | 虲 dùng bộ 虫 (trùng — sâu bọ, sinh vật nhỏ) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *hà* theo âm Trung cổ (Middle Chinese *ɦɛ). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": sinh vật (虫) dưới nước như tôm hà (hà) — sinh vật nhỏ dưới nước hay ẩn nấp. | Gương Hán-Việt | hà — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 虲 (hà) giúp nhận nhóm chữ sinh vật thủy sinh cổ hiếm trong văn bản tự nhiên học.", "Tự nguyên_Xie": "虲 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 虫 gợi ý liên quan đến sinh vật nhỏ, côn trùng. Âm pinyin *xiā* tương ứng Hán-Việt *hà* hoặc *hạ*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "虲", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "虲", "Unihan_Traditional (Chữ Phồn thể)": "虲", "Pinyin_Xie": "xiā", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ con tôm trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠩', '{"9000": "8818.0", "Chữ Trung Quốc": "蠩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 21 | nét | 蠩 | trư | tượng hình | con cóc; dạng chữ thay thế của 蝫 | 蠩 là dạng chữ thay thế của 蝫, dùng bộ 虫 (trùng — sâu bọ). Wiktionary ghi đây là obs-std alt form của 蝫, chỉ con cóc. Xuất hiện trong từ ghép 蜛蠩. Âm Hán-Việt tái lập là *trư* theo âm Trung cổ (Middle Chinese *tɕjɨo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trư\": sinh vật (虫) to xù xì như con heo (trư) — con cóc (trư) da sần sùi trông như heo nhỏ. | Gương Hán-Việt | trư — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 蠩 (trư) giúp nhận tên động vật lưỡng cư cổ trong văn bản tự nhiên học Trung Hoa.", "Tự nguyên_Xie": "蠩 theo Wiktionary là dạng chữ thay thế của 蝫 (obs-std). Có âm Trung cổ *tɕjɨo. Bộ 虫 biểu nghĩa (sinh vật nhỏ). Nghĩa là con cóc. Xuất hiện trong 蜛蠩. Chưa có hình ảnh hình chữ cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Một con cóc", "Hạng Tần Suất (Jun Da)": "8818.0", "Tần Suất % (Jun Da)": "99.9999188647", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 諸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫諸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "諸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠩", "Unihan_Traditional (Chữ Phồn thể)": "蠩", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong từ ghép để chỉ một loài cóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覵', '{"9000": "8819.0", "Chữ Trung Quốc": "覵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 19 | nét | 覵 | giản | tượng hình | rình nhìn; dạng chữ thay thế của 瞯 | 覵 là dạng chữ thay thế của 瞯, dùng bộ 見 (kiến — nhìn, thấy). Wiktionary ghi nghĩa là ''rình nhìn'' (to spy on), alt form của 瞯. Âm Hán-Việt tái lập là *giản* theo âm Trung cổ (Middle Chinese *kɛnH).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": nhìn (見) qua khe hở gián điệp (giản) — rình nhìn lén lút như thám tử. | Gương Hán-Việt | giản — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 覵 (giản) giúp nhận nhóm chữ bộ 見 chỉ hành động nhìn lén trong văn bản cổ.", "Tự nguyên_Xie": "覵 theo Wiktionary là dạng chữ thay thế của 瞯 (to spy on). Có các âm jiàn, biǎn, jiān. Bộ 見 biểu nghĩa (nhìn, thấy). Chưa có hình ảnh hình chữ cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhớn; như \"nhớn nhác\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "閒 + 見", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰閒見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "閒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "覵", "Unihan_Traditional (Chữ Phồn thể)": "覵", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "gián, kiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành vi nhìn trộm hoặc hé mắt quan sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詄', '{"9000": "8820.0", "Chữ Trung Quốc": "詄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詄 | điệt | tượng hình | chữ cổ bộ 言, chưa rõ nghĩa | 詄 dùng bộ 言 (ngôn — lời nói) làm thành tố. Wiktionary ghi âm dié và rfdef. Âm Hán-Việt tái lập là *điệt* theo âm Trung cổ (Middle Chinese *det). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": lời nói (言) trôi qua điệt (điệt) — lời nói thoảng qua như gió. | Gương Hán-Việt | điệt — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 詄 (điệt) giúp nhận nhóm chữ bộ 言 ít phổ biến trong văn bản cổ.", "Tự nguyên_Xie": "詄 theo Wiktionary có âm Trung cổ *det. Bộ 言 biểu nghĩa (lời nói). Wiktionary đánh dấu rfdef. Nghĩa cụ thể chưa rõ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "脄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "詄", "Unihan_Traditional (Chữ Phồn thể)": "詄", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Dùng làm động từ chỉ sự quên lãng hoặc tính từ chỉ sự phóng khoáng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('譗', '{"9000": "8821.0", "Chữ Trung Quốc": "譗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 19 | nét | 譗 | trát | tượng hình | chữ cổ bộ 言, chưa rõ nghĩa | 譗 dùng bộ 言 (ngôn — lời nói) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *trát* theo âm Trung cổ (Middle Chinese *tsrɛp). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": lời (言) trát lên như vữa (trát) — lời nói đắp chồng lên nhau không rõ nghĩa. | Gương Hán-Việt | trát — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 譗 (trát) giúp nhận nhóm chữ bộ 言 ít phổ biến trong văn bản cổ.", "Tự nguyên_Xie": "譗 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 言 biểu nghĩa (lời nói). Âm pinyin *zhá* tương ứng Hán-Việt *trát*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "藗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 答", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言答", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "答", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "譗", "Unihan_Traditional (Chữ Phồn thể)": "譗", "Pinyin_Xie": "zhá", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành vi nói năng rườm rà, lặp đi lặp lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趰', '{"9000": "8822.0", "Chữ Trung Quốc": "趰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 21 | nét | 趰 | nhĩ | tượng hình | chữ cổ bộ 走, chưa rõ nghĩa | 趰 dùng bộ 走 (tẩu — chạy, đi) làm thành tố. Không có dữ liệu phân tích hình chữ từ Wiktionary. Âm Hán-Việt tái lập là *nhĩ* theo âm Trung cổ (Middle Chinese *ɲɨX). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhĩ\": chạy (走) nhĩ nhĩ (nhĩ) — bước chân nhẹ nhàng di chuyển. | Gương Hán-Việt | nhĩ — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 趰 (nhĩ) giúp nhận nhóm chữ bộ 走 chỉ di chuyển trong văn bản cổ.", "Tự nguyên_Xie": "趰 không có dữ liệu nguồn gốc hình chữ trong Wiktionary. Bộ 走 biểu nghĩa (chạy, di chuyển). Âm pinyin *ěr* tương ứng Hán-Việt *nhĩ*. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谰", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 爾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走爾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趰", "Unihan_Traditional (Chữ Phồn thể)": "趰", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ trong văn ngôn để miêu tả hành động đi lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軧', '{"9000": "8823.0", "Chữ Trung Quốc": "軧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 12 | nét | 軧 | để | tượng hình | chữ cổ bộ 車, chưa rõ nghĩa | 軧 dùng bộ 車 (xa — xe) làm thành tố. Wiktionary ghi âm dǐ và rfdef. Âm Hán-Việt tái lập là *để* theo âm Trung cổ (Middle Chinese *tej). Có hình tiểu triện lưu lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"để\": bộ phận xe (車) ở phía để (để) — bộ phận phía dưới hoặc đáy của xe cộ cổ. | Gương Hán-Việt | để — ít dùng trong nghĩa này trong tiếng Việt | Mở khoá kiến thức | Biết 軧 (để) giúp nhận nhóm chữ bộ 車 chỉ bộ phận xe trong văn bản kỹ thuật cổ.", "Tự nguyên_Xie": "Tiểu triện | 軧 theo Wiktionary có âm Trung cổ *tej. Bộ 車 biểu nghĩa (xe). Wiktionary đánh dấu rfdef. Nghĩa cụ thể chưa rõ nhưng liên quan đến xe cộ. Có hình tiểu triện lưu lại từ wikimedia. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "車 + 氐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車氐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "軧", "Unihan_Traditional (Chữ Phồn thể)": "軧", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ bộ phận trục bánh xe thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岍', '{"9000": "8824.0", "Chữ Trung Quốc": "岍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 岍 | khiên | tượng hình | tên núi ở Thiểm Tây | 岍 là chữ tượng hình chỉ địa danh, tự thân là một đơn vị, không phân tích được thành phần âm-nghĩa rõ ràng. Chưa có nguồn học thuật xác định cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiên\": núi 山 gắn với âm qiān — hình dung ngọn núi Khiên hùng vĩ ở Thiểm Tây. | Gương Hán-Việt | 岍 dùng trong địa danh 岍山 (Núi Khiên). | Mở khoá kiến thức | Biết chữ này giúp nhận diện địa danh cổ trong văn bản lịch sử Trung Quốc.", "Tự nguyên_Xie": "岍 là địa danh chỉ núi Khiên (岍山) ở tỉnh Thiểm Tây, Trung Quốc. Wiktionary ghi nhận chữ này thuộc dạng dùng trong tên riêng ({{zh-used2|p}}), không có phân tích glyph-origin chi tiết. Chưa có nguồn học thuật về gốc chữ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi Khiên (ở tỉnh Thiểm Tây của Trung Quốc)", "Hạng Tần Suất (Jun Da)": "8824.0", "Tần Suất % (Jun Da)": "99.9999224822", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 开", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岍", "Unihan_Traditional (Chữ Phồn thể)": "岍", "Pinyin_Xie": "qiān", "Âm Hán Việt_Xie": "khiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng để chỉ địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉼', '{"9000": "8825.0", "Chữ Trung Quốc": "鉼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 并 | tinh | biểu âm | ghép lại | 鉼 = 金 (Kim, biểu nghĩa: kim loại) + 并 (Tinh, biểu âm); chữ hình thanh. Bộ 金 cho biết liên quan đến kim loại; 并 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": kim loại 金 được đúc song song 并 thành miếng phẳng như cái bánh — hình dung miếng vàng dẹt. | Gương Hán-Việt | 鉼 ít dùng trong tiếng Việt hiện đại; gặp trong văn bản Hán cổ chỉ đồ vật kim loại đúc phẳng. | Mở khoá kiến thức | Biết 鉼 giúp nhận diện các chữ kim loại cổ trong thư tịch lịch sử.", "Tự nguyên_Xie": "Theo Wiktionary, 鉼 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 并 biểu âm. Chữ chỉ miếng kim loại đúc phẳng như bánh, hoặc đồ đựng rượu cổ. chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miếng kim loại như cái bánh; đồ đựng rượu cổ dài; một loại nồi", "Hạng Tần Suất (Jun Da)": "8825.0", "Tần Suất % (Jun Da)": "99.999922999", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉼", "Unihan_Traditional (Chữ Phồn thể)": "鉼", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các vật dụng bằng kim loại thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞻', '{"9000": "8826.0", "Chữ Trung Quốc": "鞻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 20 | nét | 革 | cách | biểu nghĩa | da thuộc | 婁 | lâu | biểu âm | 鞻 = 革 (Cách, biểu nghĩa: da thuộc) + 婁 (Lâu, biểu âm); chữ hình thanh. Bộ 革 cho biết liên quan đến da; 婁 cho âm đọc lóu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": da 革 kết hợp âm lâu 婁 — hình dung đôi giày da cổ xưa lâu đời. | Gương Hán-Việt | 鞻 chỉ dùng trong 鞮鞻, không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 鞻 giúp đọc văn bản cổ về trang phục và đồ da Trung Quốc xưa.", "Tự nguyên_Xie": "Theo Wiktionary, 鞻 là chữ hình thanh: 革 (da thuộc) biểu nghĩa, 婁 biểu âm. Chữ chỉ dùng trong tổ hợp 鞮鞻, chỉ loại giày hoặc đồ da cổ đại. Chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rám nắng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 婁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革婁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞻", "Unihan_Traditional (Chữ Phồn thể)": "鞻", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn bản cổ để chỉ các loại giày dép bằng da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颵', '{"9000": "8827.0", "Chữ Trung Quốc": "颵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 風 | Số nét | 16 | nét | 颵 | thiêu | tượng hình | tên gió hoặc trạng thái khí hậu | 颵 là chữ hiếm, cấu trúc nội bộ chưa được phân tích rõ trong nguồn học thuật. Wiktionary chỉ ghi rfdef (chưa có định nghĩa). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiêu\": bộ 風 (phong) gợi cơn gió — tên gọi một trạng thái gió hiếm gặp trong cổ văn. | Gương Hán-Việt | 颵 không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 颵 giúp nhận diện ký tự hiếm liên quan đến gió trong thư tịch cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp định nghĩa hay phân tích glyph-origin cho 颵 (rfdef). Chữ thuộc bộ 風 (phong, gió), gợi liên quan đến gió hoặc hiện tượng khí hậu. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "颵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "風 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴風肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "風", "Unihan_Simplified (Chữ Giản thể)": "颵", "Unihan_Traditional (Chữ Phồn thể)": "颵", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "thiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ hiện tượng thời tiết hoặc động từ tả gió thổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鯘', '{"9000": "8828.0", "Chữ Trung Quốc": "鯘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鯘 | nỗi | tượng hình | cá thối rữa | 鯘 không có phân tích Han compound trong Wiktionary. Theo cấu trúc chữ Hán, khả năng có bộ 魚 (ngư, cá) biểu nghĩa, nhưng chưa xác nhận được từ anchor. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỗi\": bộ 鱼 (ngư) gợi con cá — hình dung con cá bị thối rữa gây khó chịu. | Gương Hán-Việt | 鯘 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鯘 giúp nhận diện ký tự hiếm liên quan đến cá trong cổ văn.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 鯘. Chữ có nghĩa liên quan đến cá (hoặc cá thối). Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "阘", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鯘", "Unihan_Traditional (Chữ Phồn thể)": "鯘", "Pinyin_Xie": "něi", "Âm Hán Việt_Xie": "nỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ miêu tả trạng thái ươn thối của cá hoặc thức ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳿', '{"9000": "8829.0", "Chữ Trung Quốc": "鳿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 15 | nét | 鳿 | dục | tượng hình | loài chim/rùa trong tên ghép 鸀鳿 | 鳿 chỉ dùng trong tổ hợp 鸀鳿, là tên một loài động vật (rùa hoặc chim). Wiktionary không phân tích cấu trúc chi tiết. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": bộ 鸟 (điểu) gợi con chim — 鸀鳿 là tên gọi một sinh vật cổ kỳ bí trong thư tịch cổ. | Gương Hán-Việt | 鳿 không có từ Hán-Việt thông dụng; chỉ gặp trong tên sinh vật cổ. | Mở khoá kiến thức | Biết 鳿 giúp đọc sách bác vật cổ đại Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 鳿 chỉ dùng trong 鸀鳿 ({{zh-only|鸀鳿}}), chỉ một loài động vật cổ (có thể là rùa hoặc chim). Âm đọc yù. Không có phân tích glyph-origin. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rùa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "鳿", "Unihan_Traditional (Chữ Phồn thể)": "鳿", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loài chim nước trong văn học cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龎', '{"9000": "8830.0", "Chữ Trung Quốc": "龎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 18 | nét | 龎 | bàng | tượng hình | lớn, đồ sộ; họ Bàng | 龎 là biến thể cổ của 龐 (bàng), chỉ sự to lớn, đồ sộ, hoặc dùng làm họ. Không có phân tích glyph-origin trong anchor. Cấu trúc có liên quan đến bộ 龍 (long, rồng) nhưng chưa xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàng\": chữ mang dáng vẻ to lớn đồ sộ — họ Bàng nổi tiếng với nhân vật Bàng Thống trong Tam Quốc. | Gương Hán-Việt | \"bàng\" trong họ Bàng (龐) của danh nhân lịch sử Trung Quốc. | Mở khoá kiến thức | Biết 龎 giúp nhận họ Bàng và các từ chỉ sự to lớn trong sử liệu cổ.", "Tự nguyên_Xie": "龎 là biến thể phồn thể của 龐 (bàng), chỉ sự to lớn, đồ sộ, hoặc họ người. Không có phân tích Wiktionary cụ thể trong anchor. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Bang", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 龍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂龍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厐", "Unihan_Traditional (Chữ Phồn thể)": "龎", "Pinyin_Xie": "páng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự to lớn hoặc hỗn tạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睉', '{"9000": "8831.0", "Chữ Trung Quốc": "睉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睉 | toả | tượng hình | chữ chưa rõ nghĩa | 睉 là chữ hiếm, Wiktionary ghi rfdef (chưa có định nghĩa). Bộ 目 (mục, mắt) có thể là thành phần nghĩa. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toả\": bộ 目 (mục) gợi đôi mắt — một chữ bí ẩn chưa được giải mã đầy đủ. | Gương Hán-Việt | 睉 không có từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 睉 giúp nhận diện ký tự hiếm chưa được xác định nghĩa trong cổ văn.", "Tự nguyên_Xie": "Wiktionary không cung cấp định nghĩa cho 睉 (rfdef). Âm cuó. Bộ 目 (mắt) gợi liên quan đến thị giác hoặc quan sát, nhưng nghĩa cụ thể chưa xác định. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "牝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 坐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目坐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睉", "Unihan_Traditional (Chữ Phồn thể)": "睉", "Pinyin_Xie": "cuó", "Âm Hán Việt_Xie": "toả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả đặc điểm của mắt hoặc động từ nhìn hé. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砤', '{"9000": "8832.0", "Chữ Trung Quốc": "砤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 砤 | đà | tượng hình | đá; liên quan đến tên gọi lau sậy hoặc đá | 砤 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 石 (thạch, đá) có thể là thành phần nghĩa. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": bộ 石 (thạch) gợi đá — hình dung hòn đá dùng để mài hoặc nghiền. | Gương Hán-Việt | 砤 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 砤 giúp nhận diện ký tự hiếm liên quan đến đá và công cụ thủ công cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 砤. Chữ có nghĩa là 礤 (dụng cụ mài hoặc lọc) theo nghĩa tương đương. Âm tuó. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 㐌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石㐌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砤", "Unihan_Traditional (Chữ Phồn thể)": "砤", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại đá mài thô hoặc đá nhám trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礑', '{"9000": "8833.0", "Chữ Trung Quốc": "礑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礑 | đảng | tượng hình | đá phẳng; tiếng bộp | 礑 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 石 (thạch, đá) gợi liên quan đến đá. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảng\": bộ 石 (thạch) gợi hòn đá — tiếng bộp phát ra khi đá va chạm. | Gương Hán-Việt | 礑 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 礑 giúp nhận diện ký tự hiếm trong văn bản cổ về địa chất hoặc khai khoáng.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 礑. Âm dàng. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礑", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 當", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石當", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "當", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礑", "Unihan_Traditional (Chữ Phồn thể)": "礑", "Pinyin_Xie": "dàng", "Âm Hán Việt_Xie": "đảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ đá lớn hoặc đáy khe núi trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窤', '{"9000": "8834.0", "Chữ Trung Quốc": "窤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 13 | nét | 窤 | quản | tượng hình | chữ liên quan đến hang hốc hoặc đồ vật | 窤 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 穴 (huyệt, hang hốc) có thể là thành phần nghĩa. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\": bộ 穴 (huyệt) gợi hang hốc — hình dung vật thể nhét vào hang. | Gương Hán-Việt | 窤 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 窤 giúp nhận diện ký tự hiếm trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 窤. Âm guān. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỉ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 昆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴昆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窤", "Unihan_Traditional (Chữ Phồn thể)": "窤", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động nhìn lén qua khe hở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竈', '{"9000": "8835.0", "Chữ Trung Quốc": "竈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 21 | nét | 竈 | táo | tượng hình | cái bếp lò | 竈 là phồn thể của 灶 (táo, bếp). Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Đây là chữ tạo muộn, chưa thấy phân tích glyph-origin từ giáp cốt hay kim văn cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"táo\": hình dung bếp lò đất nung cổ — Táo Quân (ông Táo) ngự trị trong lòng bếp 竈 của mỗi gia đình. | Gương Hán-Việt | \"táo\" trong ''Táo Quân'' (竈君/灶君) — vị thần bếp trong văn hóa Việt-Hoa. | Mở khoá kiến thức | Biết 竈 mở khoá từ: 竈君 (Táo Quân), 竈火 (lửa bếp), liên hệ tục thờ Táo Quân.", "Tự nguyên_Xie": "竈 là phồn thể của 灶 (bếp lò). Wiktionary chỉ ghi {{Han etym}}, không có mô tả glyph-origin chi tiết. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bếp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "竈", "Unihan_Traditional (Chữ Phồn thể)": "竈", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "táo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái bếp lò hoặc vị thần bếp trong văn hóa dân gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕒', '{"9000": "8836.0", "Chữ Trung Quốc": "蕒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 蕒 | mãi | tượng hình | rau diếp hoang; cây thuộc họ cúc | 蕒 chỉ dùng trong 苣蕒菜 và 苦蕒. Bộ 艸 (thảo, cỏ) gợi liên quan đến thực vật. Cấu trúc glyph-origin không có trong Wiktionary anchor. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãi\": bộ 艸 (thảo) gợi cây cỏ — hình dung bụi rau diếp hoang mọc tự do trên đồng. | Gương Hán-Việt | 蕒 không có từ Hán-Việt thông dụng; gặp trong tên thực vật cổ. | Mở khoá kiến thức | Biết 蕒 giúp nhận diện tên thực vật cổ trong y học hoặc thực vật học Hán văn.", "Tự nguyên_Xie": "Theo Wiktionary, 蕒 chỉ dùng trong tổ hợp 苣蕒菜 (rau diếp hoang) và 苦蕒 (tên khoa học Crepidiastrum sonchifolium). Âm mǎi. Bộ 艸 chỉ thực vật. Chưa có phân tích glyph-origin chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "荬", "Hạng Tần Suất (Jun Da)": "7633.0", "Tần Suất % (Jun Da)": "99.9988212131", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 買", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹買", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "買", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荬", "Unihan_Traditional (Chữ Phồn thể)": "蕒", "Pinyin_Xie": "mǎi", "Âm Hán Việt_Xie": "mãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại rau thân thảo có vị đắng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('説', '{"9000": "8837.0", "Chữ Trung Quốc": "説", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 14 | nét | 説 | thuyết | tượng hình | nói, giảng; biến thể của 說 | 説 là biến thể phồn thể của 說 (thuyết), nghĩa nói, giảng giải. Không có phân tích glyph-origin riêng trong anchor; cấu trúc tương tự 說 = 言 + 兑 (hình thanh). Chưa xác nhận từ anchor cụ thể cho 説.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyết\": lời nói 言 kết hợp âm đoài 兌 — hình dung bậc thầy đứng thuyết giảng lưu loát trước đám đông. | Gương Hán-Việt | \"thuyết\" trong ''thuyết trình'', ''thuyết phục'', ''học thuyết'' — từ Hán-Việt cực kỳ thông dụng. | Mở khoá kiến thức | Biết 説/說 mở khoá: 説明 (giải thích), 小說 (tiểu thuyết), 學說 (học thuyết), 傳說 (truyền thuyết).", "Tự nguyên_Xie": "説 là biến thể của 說 (thuyết), chữ hình thanh gồm 言 (ngôn, lời nói) biểu nghĩa và 兌 (đoài) biểu âm. Wiktionary không có anchor riêng cho 説. Nghĩa: nói, giảng, thuyết phục. chưa có nguồn học thuật riêng cho dạng 説. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói, giảng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 兑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言兑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "説", "Unihan_Traditional (Chữ Phồn thể)": "説", "Pinyin_Xie": "shuō", "Âm Hán Việt_Xie": "thuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ đứng trước tân ngữ để diễn đạt việc trình bày hoặc giải thích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趌', '{"9000": "8838.0", "Chữ Trung Quốc": "趌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 走 | Số nét | 13 | nét | 趌 | kiết | tượng hình | bước đi mạnh; bỏ đi trong giận dữ | 趌 là chữ hiếm, Wiktionary cung cấp định nghĩa nhưng không có Han compound. Bộ 走 (tẩu, chạy/bước) có thể là thành phần nghĩa gợi hành động chân. Chưa có nguồn học thuật về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiết\": bộ 走 (tẩu) gợi đôi chân — hình dung người bỏ đi trong cơn tức giận, bước chân mạnh mẽ. | Gương Hán-Việt | 趌 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 趌 giúp đọc văn bản cổ mô tả cử chỉ và hành động bước đi đặc thù.", "Tự nguyên_Xie": "Theo Wiktionary, 趌 có nghĩa: bỏ đi trong giận dữ, bước thẳng tới, hoặc nhảy lên (âm jié). Hai cách đọc: jí và jié với nghĩa khác nhau. Dẫn chứng tổ hợp 趌𧼨, 趌高. Không có phân tích glyph-origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "茌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "走 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴走吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "走", "Unihan_Simplified (Chữ Giản thể)": "趌", "Unihan_Traditional (Chữ Phồn thể)": "趌", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mô tả dáng điệu đi đứng nhanh nhẹn hoặc vội vàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踄', '{"9000": "8839.0", "Chữ Trung Quốc": "踄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 踄 | bộ | tượng hình | bước đi loạng choạng | 踄 là chữ hiếm, Wiktionary ghi rfdef (chưa có định nghĩa). Bộ 足 (túc, chân) gợi liên quan đến bước chân. Chưa có nguồn học thuật về cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộ\": bộ 足 (túc) gợi đôi chân — hình dung bước đi loạng choạng, vấp váp. | Gương Hán-Việt | 踄 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 踄 giúp nhận diện ký tự hiếm liên quan đến bước đi trong cổ văn.", "Tự nguyên_Xie": "Wiktionary không cung cấp định nghĩa rõ cho 踄 (rfdef). Âm bù. Bộ 足 (chân) gợi liên quan đến bước đi. Chỉ thấy trong tổ hợp 跋踄. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "loạng choạng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 步", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊步", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "步", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踄", "Unihan_Traditional (Chữ Phồn thể)": "踄", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đặt chân xuống hoặc bước đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隣', '{"9000": "8840.0", "Chữ Trung Quốc": "隣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 14 | nét | 阝 | biểu nghĩa | gò đất, địa danh | 粦 | biểu âm | 隣 = 阝 (biến thể của 阜, biểu nghĩa: gò đất/khu vực) + 粦 (biểu âm); chữ hình thanh. Bộ 阝trái gợi khu vực cư trú; 粦 cho âm đọc lín. Biến thể của 鄰.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lân\": khu vực 阝 kề cận âm lân 粦 — hình dung nhà hàng xóm sát vách, cùng xóm làng. | Gương Hán-Việt | \"lân\" trong ''láng giềng lân cận'', ''lân bang'' (nước láng giềng) — từ Hán-Việt thông dụng. | Mở khoá kiến thức | Biết 隣 mở khoá: 隣人 (láng giềng), 隣家 (nhà bên cạnh), 近隣 (lân cận).", "Tự nguyên_Xie": "Theo Wiktionary, 隣 là biến thể của 鄰: hình thanh gồm 阜 (gò đất, biểu nghĩa) viết tắt thành 阝 và 粦 (biểu âm). Nghĩa: gần, kề cận, láng giềng. Xem chính tự 鄰. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gần, kề; láng giềng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 粦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝粦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "粦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隣", "Unihan_Traditional (Chữ Phồn thể)": "隣", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ hàng xóm hoặc làm tính từ bổ nghĩa cho danh từ chỉ vị trí lân cận. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骿', '{"9000": "8841.0", "Chữ Trung Quốc": "骿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骿 | biền | tượng hình | xương sườn; lưng | 骿 là chữ hiếm. Wiktionary cung cấp định nghĩa nhưng không có Han compound. Theo âm đọc và nghĩa, có thể có bộ 骨 (cốt, xương) biểu nghĩa. chưa xác nhận cấu trúc từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biền\": bộ 骨 (cốt) gợi xương — hình dung xương sườn sau của cơ thể trong phương ngữ miền Nam. | Gương Hán-Việt | 骿 không có từ Hán-Việt thông dụng; chủ yếu dùng trong phương ngữ Quảng Đông và Mân Nam. | Mở khoá kiến thức | Biết 骿 giúp đọc văn bản y học hoặc thể chất học cổ đại.", "Tự nguyên_Xie": "Theo Wiktionary, 骿 chỉ xương sườn (đặc biệt xương sườn sau) trong tiếng Quảng và Mân Nam, hoặc chỉ lưng thân người. Không có phân tích glyph-origin trong anchor. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "骿", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骿", "Unihan_Traditional (Chữ Phồn thể)": "骿", "Pinyin_Xie": "pián", "Âm Hán Việt_Xie": "biền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ để mô tả xương sườn khép kín hoặc liền bánh với nhau. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼥', '{"9000": "8842.0", "Chữ Trung Quốc": "鼥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼠 | Số nét | 18 | nét | 鼥 | bạt | tượng hình | loài gặm nhấm; xem 鼧鼥 | 鼥 chỉ dùng trong tổ hợp 鼧鼥, chỉ một loài gặm nhấm. Bộ 鼠 (thử, chuột) gợi liên quan đến loài gặm nhấm. Không có phân tích glyph-origin từ anchor. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạt\": bộ 鼠 (thử) gợi con chuột — 鼧鼥 là tên gọi một loài gặm nhấm bí ẩn trong sách bác vật cổ. | Gương Hán-Việt | 鼥 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 鼥 giúp đọc sách bác vật học và tên sinh vật cổ đại Trung Quốc.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 鼥. Chữ chỉ dùng trong 鼧鼥 — tên một loài gặm nhấm cổ đại. Bộ 鼠 (chuột) gợi loài động vật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đà bạt 鼧鼥)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鼠 + 犮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼠犮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼠", "Unihan_Simplified (Chữ Giản thể)": "鼥", "Unihan_Traditional (Chữ Phồn thể)": "鼥", "Pinyin_Xie": "bá", "Âm Hán Việt_Xie": "bạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đà để tạo thành từ ghép chỉ loài chuột đất lớn ở vùng thảo nguyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碵', '{"9000": "8843.0", "Chữ Trung Quốc": "碵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 碵 | điền | tượng hình | đá; liên quan đến địa chất | 碵 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 石 (thạch, đá) gợi liên quan đến đá. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": bộ 石 (thạch) gợi đá — hình dung hòn đá trên cánh đồng điền. | Gương Hán-Việt | 碵 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 碵 giúp nhận diện ký tự hiếm trong văn bản địa chất cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 碵. Âm tian. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 貞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石貞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碵", "Unihan_Traditional (Chữ Phồn thể)": "碵", "Pinyin_Xie": "tian", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ một loại đá quý dùng làm đồ trang sức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竤', '{"9000": "8844.0", "Chữ Trung Quốc": "竤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 12 | nét | 竤 | hồng | tượng hình | chữ hiếm chưa rõ nghĩa | 竤 không có phân tích glyph-origin trong Wiktionary anchor. Chưa xác định được thành phần cấu tạo từ anchor. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": âm hóng gợi chữ 红 (đỏ) hay 鸿 (hồng hạc) — một ký tự hiếm chưa được giải mã. | Gương Hán-Việt | 竤 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 竤 giúp nhận diện ký tự hiếm trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 竤. Âm hóng. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礤", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 宏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立宏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竤", "Unihan_Traditional (Chữ Phồn thể)": "竤", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ hoặc dùng trong tên người để chỉ sự to lớn, hùng vĩ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絒', '{"9000": "8845.0", "Chữ Trung Quốc": "絒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絒 | trù | tượng hình | tơ lụa; sợi | 絒 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 糸 (mịch, sợi tơ) gợi liên quan đến vải sợi. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": bộ 糸 (mịch) gợi sợi tơ — hình dung cuộn tơ lụa trù mật được dệt nên. | Gương Hán-Việt | 絒 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 絒 giúp nhận diện ký tự hiếm liên quan đến dệt may trong cổ văn.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 絒. Âm chóu. Bộ 糸 gợi liên quan đến sợi tơ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 州", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹州", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "州", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絒", "Unihan_Traditional (Chữ Phồn thể)": "絒", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn cổ để chỉ các loại dây buộc bằng tơ nhuộm màu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絓', '{"9000": "8846.0", "Chữ Trung Quốc": "絓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絓 | quái | tượng hình | vướng mắc; tơ thô | 絓 là chữ hội ý/hình thanh liên quan đến sợi tơ. Wiktionary cung cấp định nghĩa nhưng không có Han compound. Bộ 糸 (mịch, sợi tơ) biểu nghĩa. chưa xác nhận cấu trúc từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quái\": sợi tơ 糸 bị vướng vào nhau — hình dung sợi chỉ rối vương vấn không tháo ra được. | Gương Hán-Việt | 絓 không có từ Hán-Việt thông dụng; liên quan đến 掛 (quái, treo). | Mở khoá kiến thức | Biết 絓 giúp đọc văn bản cổ về dệt may và vướng mắc.", "Tự nguyên_Xie": "Theo Wiktionary, 絓 (âm guà) nghĩa vướng mắc, cản trở, treo lên (alt form của 掛); (âm kuā) nghĩa tơ thô. Bộ 糸 gợi liên quan đến sợi vải. Wiktionary cung cấp định nghĩa nhưng không có phân tích glyph-origin. chưa có nguồn học thuật cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trở ngại, cản trở, vướng víu", "Hạng Tần Suất (Jun Da)": "8846.0", "Tần Suất % (Jun Da)": "99.9999385026", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絓", "Unihan_Traditional (Chữ Phồn thể)": "絓", "Pinyin_Xie": "guà", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để biểu thị trạng thái bị vướng mắc hoặc cản trở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芼', '{"9000": "8847.0", "Chữ Trung Quốc": "芼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 毛 | mao | biểu âm | lông | 芼 = 艸 (Thảo, biểu nghĩa: cỏ/thực vật) + 毛 (Mao, biểu âm); chữ hình thanh. Bộ 艸 cho biết liên quan đến thực vật; 毛 cho âm đọc mào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mào\": cỏ 艸 mao 毛 — hình dung tay hái rau thủy sinh dâng lên bàn thờ trong nghi lễ Kinh Thi. | Gương Hán-Việt | \"mào\" trong Hán văn cổ điển chỉ hành động hái rau dâng cúng; ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 芼 giúp đọc Kinh Thi và nghi lễ tế tự cổ đại Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 芼 là chữ hình thanh: 艸 (cỏ) biểu nghĩa, 毛 biểu âm. Nghĩa cổ: nấu chín và dâng lên (trong nghi lễ tế tự, đặc biệt rau thủy sinh); lựa chọn; hoặc rau xanh. Dẫn chứng từ Kinh Thi: ''tả hữu mào chi'' (左右芼之 — bên trái bên phải hái rau dâng lên). Chú giải của Chu Hi: mào nghĩa là nấu chín và dâng lên. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lựa chọn; rao mạo", "Hạng Tần Suất (Jun Da)": "8847.0", "Tần Suất % (Jun Da)": "99.9999390194", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芼", "Unihan_Traditional (Chữ Phồn thể)": "芼", "Pinyin_Xie": "mào", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các loại rau cỏ dưới nước hoặc động từ với nghĩa hái lượm, tuyển chọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萢', '{"9000": "8848.0", "Chữ Trung Quốc": "萢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萢 | bào | tượng hình | thực vật; cây rau | 萢 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 艸 (thảo, cỏ) gợi liên quan đến thực vật. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": bộ 艸 (thảo) gợi cây cỏ — hình dung loài thực vật mọng nước phồng như bong bóng. | Gương Hán-Việt | 萢 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 萢 giúp nhận diện tên thực vật hiếm trong văn bản thực vật học cổ.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 萢. Âm pao. Chưa có nguồn học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "萢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 泡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹泡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萢", "Unihan_Traditional (Chữ Phồn thể)": "萢", "Pinyin_Xie": "pao", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong khẩu ngữ để chỉ các loại quả mọng hoang dại thuộc họ dâu tằm hoặc hoa hồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓧', '{"9000": "8849.0", "Chữ Trung Quốc": "蓧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓧 | điếu | tượng hình | đồ cào cỏ; bừa cào | 蓧 là chữ hiếm chỉ dụng cụ cào cỏ hoặc bừa. Wiktionary chỉ ghi {{Han etym}} không có chi tiết. Bộ 艸 (thảo, cỏ) gợi liên quan đến nông cụ và thực vật. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếu\": bộ 艸 (thảo) gợi cỏ cần cào — hình dung nông dân cầm cái bừa cào dọn sạch đồng ruộng. | Gương Hán-Việt | 蓧 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 蓧 giúp đọc văn bản nông nghiệp và nông cụ cổ đại Trung Quốc.", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} cho 蓧 mà không có nội dung cụ thể. Nghĩa: đồ cào cỏ, bừa cào (nông cụ). Bộ 艸 gợi liên quan đến thực vật/nông nghiệp. chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ cào cỏ; bừa cào cỏ", "Hạng Tần Suất (Jun Da)": "8849.0", "Tần Suất % (Jun Da)": "99.9999400529", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 條", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹條", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "條", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓧", "Unihan_Traditional (Chữ Phồn thể)": "蓧", "Pinyin_Xie": "diào", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ một loại nông cụ bằng tre dùng để cào cỏ hoặc đựng đất cát thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔄', '{"9000": "8850.0", "Chữ Trung Quốc": "蔄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 蔄 | mạn | tượng hình | địa danh ở Sơn Đông; họ người | 蔄 là chữ dùng trong địa danh (蔄山鎮 ở Sơn Đông) và họ người. Wiktionary cung cấp định nghĩa nhưng không có Han compound. Bộ 艸 (thảo) gợi thực vật, nhưng dùng chính trong tên riêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": bộ 艸 (thảo) gợi cây cỏ lan tràn — địa danh 蔄山 ở Sơn Đông, vùng đất tươi tốt. | Gương Hán-Việt | 蔄 không có từ Hán-Việt thông dụng; dùng chủ yếu trong địa danh và họ người. | Mở khoá kiến thức | Biết 蔄 giúp nhận diện địa danh và họ người hiếm gặp trong văn bản địa lý Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 蔄 dùng trong địa danh 蔄山鎮 (thị trấn Mạn Sơn ở Sơn Đông) và làm họ người. Âm màn. Wiktionary không có phân tích glyph-origin chi tiết. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蔄", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 問", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹問", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "問", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔄", "Unihan_Traditional (Chữ Phồn thể)": "蔄", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ họ người hoặc tên một địa danh cụ thể ở tỉnh Sơn Đông, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螦', '{"9000": "8851.0", "Chữ Trung Quốc": "螦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螦 | tao | tượng hình | côn trùng; chữ hiếm chưa rõ nghĩa | 螦 không có phân tích glyph-origin trong Wiktionary anchor. Bộ 虫 (trùng, côn trùng) gợi liên quan đến động vật nhỏ. chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tao\": bộ 虫 (trùng) gợi côn trùng — hình dung con sâu bọ nhỏ ít ai biết đến. | Gương Hán-Việt | 螦 không có từ Hán-Việt thông dụng trong tiếng Việt. | Mở khoá kiến thức | Biết 螦 giúp nhận diện tên côn trùng hiếm trong sách bác vật cổ Trung Quốc.", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích glyph-origin cho 螦. Âm sao. Bộ 虫 gợi liên quan đến côn trùng hoặc động vật nhỏ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "覦", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 素", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫素", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "素", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螦", "Unihan_Traditional (Chữ Phồn thể)": "螦", "Pinyin_Xie": "sao", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành vi dòm ngó hoặc mong muốn điều gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('詀', '{"9000": "8852.0", "Chữ Trung Quốc": "詀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 詀 | chiêm | tượng hình | nói nhiều; đùa giỡn | 詀 là chữ hiếm. Wiktionary cung cấp định nghĩa nhưng không có Han compound. Bộ 言 (ngôn, lời nói) gợi liên quan đến ngôn ngữ và giao tiếp. chưa xác nhận cấu trúc từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiêm\": lời 言 tuôn ra không ngừng — hình dung người ba hoa lắm lời, cứ chiêm bao chiêm bao không thôi. | Gương Hán-Việt | 詀 không có từ Hán-Việt thông dụng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 詀 giúp đọc văn học cổ điển miêu tả người lắm lời hoặc khôi hài.", "Tự nguyên_Xie": "Theo Wiktionary, 詀 nghĩa: nói nhiều, giữ lời mãi; đùa giỡn, chọc đùa. Âm zhān (hoặc chè). Bộ 言 gợi liên quan đến lời nói. Không có phân tích glyph-origin trong anchor. chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "耀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "𧮪", "Unihan_Traditional (Chữ Phồn thể)": "詀", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành vi nói năng ba hoa hoặc khoe khoang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狨', '{"9000": "8853.0", "Chữ Trung Quốc": "狨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 狨 | nhung | tượng hình | khỉ lông dài; khỉ sóc marmoset | 狨 là chữ chỉ loài khỉ sóc (marmoset). Wiktionary cung cấp định nghĩa nhưng không có Han compound. Bộ 犭(quải, thú vật) gợi liên quan đến động vật. chưa xác nhận cấu trúc từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": bộ 犭(khuyển) gợi thú vật + âm nhung (mềm mại) — hình dung con khỉ sóc nhỏ nhắn với bộ lông nhung mềm mịn. | Gương Hán-Việt | 狨 không có từ Hán-Việt thông dụng; gặp trong văn bản về động vật học cổ. | Mở khoá kiến thức | Biết 狨 giúp đọc sách bác vật và văn học cổ mô tả thú vật phương nam.", "Tự nguyên_Xie": "Theo Wiktionary, 狨 nghĩa là khỉ sóc (marmoset), một loài linh trưởng nhỏ có bộ lông mềm. Âm róng. Bộ 犭gợi thú vật. Không có phân tích glyph-origin chi tiết trong anchor. chưa có nguồn học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống khỉ lông dài", "Hạng Tần Suất (Jun Da)": "8853.0", "Tần Suất % (Jun Da)": "99.9999426369", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 戎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭戎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狨", "Unihan_Traditional (Chữ Phồn thể)": "狨", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm thành phần trong tên gọi các loài linh trưởng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錋', '{"9000": "8854.0", "Chữ Trung Quốc": "錋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錋 | bằng | tượng hình | chữ kim loại không rõ cấu tạo | 錋 là chữ thuộc bộ 金 (kim, kim loại). Chưa có phân tích cấu tạo từ nguồn học thuật; xử lý như tượng hình trong nhóm kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bộ 金 (kim loại) đọc âm bằng — kim loại bằng phẳng, cân đối. | Gương Hán-Việt | bằng — ít dùng trong từ Hán-Việt hiện đại | Mở khoá kiến thức | Biết 錋 (bằng) giúp nhận bộ 金 trong các chữ kim loại hiếm.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 錋. Bộ 金 gợi ý liên quan đến kim loại. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bằng; như \"bằng nhau\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 朋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金朋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錋", "Unihan_Traditional (Chữ Phồn thể)": "錋", "Pinyin_Xie": "péng", "Âm Hán Việt_Xie": "băng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ nguyên tố hóa học hoặc làm tính từ chỉ sự bằng phẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鎝', '{"9000": "8855.0", "Chữ Trung Quốc": "鎝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鎝 | đáp | tượng hình | chữ kim loại, có thể liên quan đến technetium hoặc dụng cụ cày | 鎝 thuộc bộ 金 (kim, kim loại). Chưa có phân tích hình thanh/hội ý từ Wiktionary; xử lý như tượng hình trong nhóm kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": bộ 金 (kim loại) + âm dā — dụng cụ kim loại đáp đất làm ruộng. | Gương Hán-Việt | đáp — ít xuất hiện trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 鎝 (đáp) giúp nhận bộ 金 trong ký hiệu hóa học kim loại hiếm.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 鎝. Bộ 金 gợi ý liên quan kim loại. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Techneti", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 荅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金荅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𨱏", "Unihan_Traditional (Chữ Phồn thể)": "鎝", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "táp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong thuật ngữ hóa học để chỉ nguyên tố tecneti. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鐩', '{"9000": "8856.0", "Chữ Trung Quốc": "鐩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鐩 | tuy | tượng hình | thấu kính hoặc gương tập trung ánh sáng bằng kim loại | 鐩 thuộc bộ 金 (kim). Chưa có dữ liệu cấu tạo Wiktionary; xử lý như tượng hình trong nhóm kim loại liên quan đến quang học cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\": bộ 金 (kim loại) — chiếc gương kim loại tuy nhỏ nhưng tập trung ánh sáng mạnh. | Gương Hán-Việt | tuy — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鐩 (tuy) giúp đọc văn cổ về dụng cụ quang học kim loại.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 鐩. Âm suì, bộ 金 gợi ý dụng cụ kim loại dùng để hội tụ ánh sáng (thấu kính). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鐩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬭼", "Unihan_Traditional (Chữ Phồn thể)": "鐩", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loại gương đồng cổ dùng để lấy lửa từ ánh mặt trời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隲', '{"9000": "8857.0", "Chữ Trung Quốc": "隲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 16 | nét | 隲 | trất | tượng hình | ngựa đực; phân định; đề bạt | 隲 thuộc bộ 阜 (phụ, gò đất). Chưa có phân tích Wiktionary; xử lý như tượng hình trong nhóm danh từ liên quan đến thứ bậc và ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trật\": bộ 阜 (gò đất, địa vị) — ngựa được trật tự đề bạt lên gò cao. | Gương Hán-Việt | trất — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 隲 (trất) giúp đọc văn ngôn về chế độ phong kiến và thứ bậc quan lại.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 隲. Bộ 阜 gợi ý liên quan đến địa vị, thứ bậc. Âm zhì (trất) liên hệ với ý nghĩa phân định, đề bạt. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "định sẵn; phân biệt; ngựa cái", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "隲", "Unihan_Traditional (Chữ Phồn thể)": "隲", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "chất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc sắp đặt, định sẵn hoặc làm danh từ chỉ con ngựa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霝', '{"9000": "8858.0", "Chữ Trung Quốc": "霝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 17 | nét | 霝 | linh | tượng hình | mưa rào, giọt mưa rơi — tượng hình mưa lớn và nhỏ cùng lúc | 霝 là chữ tượng hình (liushu: p), liên quan đến 雨 (vũ, mưa). Hình dạng mô tả cả giọt mưa nhỏ lẫn hạt mưa lớn rơi xuống cùng lúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": hình ảnh mưa (雨) với nhiều giọt lớn nhỏ rơi xuống — \"linh\" như linh hoạt, linh mưa linh tinh. | Gương Hán-Việt | linh — dùng trong \"linh thiêng\" (靈), \"linh hoạt\"; 霝 là dạng cổ | Mở khoá kiến thức | Biết 霝 (linh) mở khoá 零 (không, lẻ) và 靈 (linh thiêng) — cùng gốc tượng hình mưa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Wiktionary xác định 霝 là chữ tượng hình (象形), liên quan đến 雨 (mưa) — hình dạng cổ mô tả mưa với cả giọt nhỏ và giọt lớn cùng rơi. Đây là dạng cổ của 零 (mưa rơi) và 靈 (linh thiêng). Hình ảnh giáp cốt và kim văn xác nhận nguồn gốc tượng hình từ thời rất sớm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa rào; rơi xuống", "Hạng Tần Suất (Jun Da)": "8858.0", "Tần Suất % (Jun Da)": "99.9999452208", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 𠱠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨𠱠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠱠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霝", "Unihan_Traditional (Chữ Phồn thể)": "霝", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hiện tượng mưa rơi hoặc làm danh từ chỉ giọt mưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞟', '{"9000": "8859.0", "Chữ Trung Quốc": "鞟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 鞟 | khoát | tượng hình | da đã thuộc, da thú đã qua xử lý | 鞟 thuộc bộ 革 (cách, da thuộc). Chưa có phân tích Wiktionary; xử lý như tượng hình trong nhóm da thuộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoát\": bộ 革 (da thuộc) + âm kuò — \"khoát\" như khoác tấm da lên người. | Gương Hán-Việt | khoát — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鞟 (khoát) giúp nhận bộ 革 trong các chữ về da và giày dép.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 鞟. Bộ 革 xác nhận liên quan đến da thuộc. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "da đã thuộc", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞟", "Unihan_Traditional (Chữ Phồn thể)": "鞟", "Pinyin_Xie": "kuò", "Âm Hán Việt_Xie": "khuếch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tấm da thú đã được cạo sạch lông và thuộc kỹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礐', '{"9000": "8860.0", "Chữ Trung Quốc": "礐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 18 | nét | 礐 | xác | tượng hình | tiếng sóng đánh đá; tảng đá lớn; hố phân | 礐 thuộc bộ 石 (thạch, đá). Wiktionary ghi nhận là từ tượng thanh và mô tả tảng đá lớn; không có cấu tạo hình thanh/hội ý rõ ràng từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xác\": bộ 石 (đá) + âm xác/que — tảng đá \"xác\" thịt vùng ven biển, sóng đánh ầm ầm. | Gương Hán-Việt | xác — dùng trong \"xác thực\" mang nghĩa chắc chắn như đá | Mở khoá kiến thức | Biết 礐 (xác) giúp đọc văn bản địa lý và văn học Quảng Đông cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 礐 thuộc bộ 石. Âm là què/hú. Nghĩa cổ: tiếng sóng đánh vào đá (từ tượng thanh), tảng đá lớn, mạnh mẽ. Trong Min Nam còn dùng chỉ hố phân/nhà vệ sinh đơn giản. Tên địa danh 礐石 ở Quảng Đông. chưa có nguồn học thuật về glyph-origin. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "礐", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𦥯 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𦥯石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦥯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "𬒈", "Unihan_Traditional (Chữ Phồn thể)": "礐", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "xác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Chữ này làm danh từ chỉ đá lớn hoặc làm tính từ miêu tả địa hình nhiều đá sỏi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禗', '{"9000": "8861.0", "Chữ Trung Quốc": "禗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 13 | nét | 禗 | ti | tượng hình | chữ liên quan tế lễ, dùng trong từ láy 禗禗 | 禗 thuộc bộ 示 (thị, thần linh, tế lễ). Wiktionary không cung cấp phân tích glyph-origin; chỉ dùng trong từ láy 禗禗.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ti\": bộ 示 (thần linh, tế lễ) + âm sī — \"ti\" như tiếng gió thì thầm trong nghi lễ tế thần. | Gương Hán-Việt | ti — ít dùng trong từ Hán-Việt thông dụng | Mở khoá kiến thức | Biết 禗 (ti) giúp nhận bộ 示 trong các chữ tế lễ và thần linh.", "Tự nguyên_Xie": "Wiktionary xác nhận 禗 thuộc bộ 示, âm sī. Chỉ dùng trong từ láy 禗禗, nghĩa không rõ ràng. Chưa có phân tích glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "禗", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禗", "Unihan_Traditional (Chữ Phồn thể)": "禗", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "ti", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ vị thần bảo hộ hoặc làm động từ chỉ việc cúng tế. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稡', '{"9000": "8862.0", "Chữ Trung Quốc": "稡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 稡 | tụy | tượng hình | đọt non, chồi non của cây lúa hoặc mía | 稡 thuộc bộ 禾 (hòa, lúa). Wiktionary không cung cấp glyph-origin; nghĩa liên quan đến chồi non của cây họ hòa thảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\": bộ 禾 (lúa) + âm zuì — \"tụy\" như chồi non \"tụ\" về đỉnh ngọn cây lúa mía. | Gương Hán-Việt | tụy — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 稡 (tụy) giúp đọc văn ngôn nông nghiệp về cây trồng họ hòa thảo.", "Tự nguyên_Xie": "Wiktionary xác nhận 稡 thuộc bộ 禾, âm zuì. Nghĩa: đọt non, chồi mía/chuối (theo từ điển GDHN/VHN). Không có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đọt; như \"đọt mía; đọt chuối\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稡", "Unihan_Traditional (Chữ Phồn thể)": "稡", "Pinyin_Xie": "zuì", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ chỉ sự tụ họp hoặc danh từ chỉ đọt cây. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穽', '{"9000": "8863.0", "Chữ Trung Quốc": "穽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 9 | nét | 穽 | tỉnh | tượng hình | hố bẫy, hố đào để bắt thú | 穽 thuộc bộ 穴 (huyệt, cái hang, hố). Chưa có phân tích Wiktionary; bộ 穴 xác nhận ý nghĩa hố, bẫy. Xử lý như tượng hình mô tả hố bẫy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉnh\": bộ 穴 (hố, hang) + âm jǐng — \"tỉnh\" như cái giếng (井) ẩn trong hố bẫy. | Gương Hán-Việt | tỉnh — liên hệ 井 (giếng), đều là hố đào sâu xuống đất | Mở khoá kiến thức | Biết 穽 (tỉnh) giúp đọc văn ngôn săn bắn và chiến thuật quân sự cổ.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 穽. Bộ 穴 (hang, hố) gợi ý liên quan đến hố bẫy. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hố làm bẫy", "Hạng Tần Suất (Jun Da)": "3218.0", "Tần Suất % (Jun Da)": "99.3688229254", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 井", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴井", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "井", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "阱", "Unihan_Traditional (Chữ Phồn thể)": "穽", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "tỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đóng vai trò tân ngữ sau các động từ như đào hoặc rơi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糮', '{"9000": "8864.0", "Chữ Trung Quốc": "糮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 20 | nét | 糮 | hiển | tượng hình | chè lam, bánh gạo nếp | 糮 thuộc bộ 米 (mễ, gạo). Chưa có phân tích Wiktionary; bộ 米 xác nhận liên quan đến gạo, thực phẩm. Xử lý như tượng hình trong nhóm thực phẩm gạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiển\": bộ 米 (gạo) + âm xiàn — \"hiển\" như bánh chè lam \"hiển thị\" vị ngọt gạo nếp. | Gương Hán-Việt | hiển — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 糮 (hiển) giúp nhận bộ 米 trong các chữ chỉ thực phẩm gạo truyền thống.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 糮. Bộ 米 gợi ý liên quan đến chế phẩm gạo. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lam; như \"bánh chè lam\" (gdhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 監", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米監", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "監", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糮", "Unihan_Traditional (Chữ Phồn thể)": "糮", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bánh ngọt làm từ bột nếp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羮', '{"9000": "8865.0", "Chữ Trung Quốc": "羮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 15 | nét | 羮 | canh | tượng hình | canh, súp nấu từ thịt và rau | 羮 thuộc bộ 羊 (dương, dê/cừu). Đây là dạng cổ/dị thể của 羹. Chưa có phân tích Wiktionary riêng; bộ 羊 xác nhận liên quan đến thực phẩm từ thịt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": bộ 羊 (dê/cừu) liên quan đến thịt — \"canh\" thịt nghi ngút khói, ăn kèm cơm. | Gương Hán-Việt | canh — dùng rộng rãi trong tiếng Việt: canh chua, canh rau | Mở khoá kiến thức | Biết 羮 (canh) mở khoá 羹 (canh súp), 羊 (dương, cừu) — nhóm từ thực phẩm truyền thống.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin riêng cho 羮. Đây là dạng dị thể của 羹 (canh). Bộ 羊 (dê) gợi ý canh nấu từ thịt dê hoặc thịt nói chung. chưa có nguồn học thuật riêng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "canh (ăn cơm)", "Hạng Tần Suất (Jun Da)": "8865.0", "Tần Suất % (Jun Da)": "99.9999488383", "GavinGrover_Once (Chiết tự trực tiếp)": "羔 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "羮", "Unihan_Traditional (Chữ Phồn thể)": "羮", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng sau các động từ nấu ăn hoặc làm chủ ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肰', '{"9000": "8866.0", "Chữ Trung Quốc": "肰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 肉 | nhục | biểu nghĩa | thịt | 犬 | khuyển | biểu nghĩa | chó | 肰 = 肉 (Nhục, biểu nghĩa: thịt) + 犬 (Khuyển, biểu nghĩa: chó); chữ hội ý. Hai thành phần kết hợp ý nghĩa: thịt + chó = thịt chó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiên\": 肉 (thịt) + 犬 (chó) ghép lại = thịt chó — \"nhiên\" như nhiên liệu bữa nhậu thời cổ! | Gương Hán-Việt | nhiên — ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 肰 (nhiên) giúp nhận cấu tạo hội ý kết hợp bộ 肉 và 犬 trong Hán tự cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 肰 là chữ hội ý (hội ý, ls=ic): 肉 (nhục, thịt) + 犬 (khuyển, chó). Kết hợp hai bộ phận theo nghĩa trực tiếp: thịt + chó = thịt chó. Đây là cách tạo chữ hội ý điển hình trong Hán tự cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt chó", "Hạng Tần Suất (Jun Da)": "8866.0", "Tần Suất % (Jun Da)": "99.9999493551", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肰", "Unihan_Traditional (Chữ Phồn thể)": "肰", "Pinyin_Xie": "rán", "Âm Hán Việt_Xie": "nhiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này là danh từ cổ dùng để chỉ thịt chó trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('艸', '{"9000": "8867.0", "Chữ Trung Quốc": "艸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 6 | nét | 艸 | tháu | tượng hình | cỏ xanh mọc thành bụi — tượng hình hai cành cỏ | 艸 là chữ tượng hình (liushu: p) mô tả hai cành cỏ mọc lên. Đây là dạng cổ của bộ 艹 (thảo) dùng làm bộ thủ trong rất nhiều chữ thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháu\": hình ảnh hai cành cỏ (艸) mọc song song — \"tháu\" như tháo vát, nhanh nhẹn như cỏ mọc khắp nơi. | Gương Hán-Việt | tháu — 艸 là bộ thủ (草 = thảo) trong \"thảo mộc\", \"thảo nguyên\" | Mở khoá kiến thức | Biết 艸 (tháu/thảo) mở khoá hàng trăm chữ thực vật: 花, 草, 茶, 菜, 英...", "Tự nguyên_Xie": "Tiểu triện | Wiktionary xác nhận 艸 là chữ tượng hình (象形), mô tả những cành cỏ (grass blades). Là dạng ghép đôi của 屮 (chồi cỏ đơn). Tiểu triện còn lưu hình dạng hai cành cỏ song song. Đây là bộ thủ 140 trong Khang Hi tự điển, dùng làm bộ cho hàng trăm chữ thực vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "276.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh hai cây cỏ đứng cạnh nhau (gồm 2 chữ Triệt 屮 ghép lại).", "Nghĩa Tiếng Việt_Xie": "bộ thảo", "Hạng Tần Suất (Jun Da)": "787.0", "Tần Suất % (Jun Da)": "85.0374311091", "GavinGrover_Once (Chiết tự trực tiếp)": "屮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴屮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "草", "Unihan_Traditional (Chữ Phồn thể)": "艸", "Pinyin_Xie": "cǎo", "Âm Hán Việt_Xie": "thảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài thực vật thân thảo hoặc dùng làm bộ thủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葇', '{"9000": "8868.0", "Chữ Trung Quốc": "葇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葇 | nhú | tượng hình | cây hương nhu — loài cỏ thơm họ bạc hà | 葇 thuộc bộ 艹 (thảo, cỏ). Wiktionary không cung cấp phân tích glyph-origin; chỉ dùng trong 香葇 (hương nhu, Elsholtzia ciliata). Xử lý như tượng hình trong nhóm thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhú\": bộ 艹 (cỏ) + âm róu — \"nhú\" như mầm cỏ thơm 香葇 vừa nhú lên từ đất. | Gương Hán-Việt | nhú — ít dùng độc lập; 葇 chủ yếu trong tên thực vật cổ điển | Mở khoá kiến thức | Biết 葇 (nhú) giúp đọc văn bản y học và thực vật học cổ Trung Quốc.", "Tự nguyên_Xie": "Wiktionary xác nhận 葇 thuộc bộ 艹, âm róu. Chỉ dùng trong 香葇 — một loài cỏ thơm họ bạc hà (Elsholtzia ciliata), có thể chưng cất tinh dầu và dùng làm thuốc. Đồng nghĩa với 香薷. Chưa có glyph-origin học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cỏ thơm)", "Hạng Tần Suất (Jun Da)": "8868.0", "Tần Suất % (Jun Da)": "99.9999503886", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葇", "Unihan_Traditional (Chữ Phồn thể)": "葇", "Pinyin_Xie": "róu", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại thảo dược hoặc cỏ có mùi thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葟', '{"9000": "8869.0", "Chữ Trung Quốc": "葟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 葟 | hoàng | tượng hình | chưa xác định nghĩa cụ thể — chữ thuộc bộ thảo | 葟 thuộc bộ 艹 (thảo, cỏ). Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Xử lý như tượng hình trong nhóm thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": bộ 艹 (cỏ) + âm hoáng — \"hoàng\" như cỏ hoàng hoa vàng rực trên đồng. | Gương Hán-Việt | hoàng — liên hệ 黄 (vàng), 皇 (hoàng đế); cùng âm | Mở khoá kiến thức | Biết 葟 (hoàng) giúp nhận nhóm âm hoáng trong các chữ thực vật cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 葟 thuộc bộ 艹, âm huáng. Nghĩa chưa được xác định rõ (rfdef). Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "葟", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葟", "Unihan_Traditional (Chữ Phồn thể)": "葟", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả trạng thái cây cỏ mọc sum suê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒪', '{"9000": "8870.0", "Chữ Trung Quốc": "蒪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒪 | bạc | tượng hình | rau thuần — loài rau nước | 蒪 thuộc bộ 艹 (thảo). Wiktionary không cung cấp glyph-origin rõ ràng. Bộ 艹 xác nhận đây là thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạc\": bộ 艹 (cỏ/rau) + âm pò — \"bạc\" như rau bạc hà mọc dưới nước, vị thanh mát. | Gương Hán-Việt | bạc — liên hệ \"rau bạc hà\" trong tiếng Việt | Mở khoá kiến thức | Biết 蒪 (bạc) giúp nhận nhóm rau nước trong văn bản thực vật học cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 蒪 thuộc bộ 艹, âm pò. Nghĩa chưa xác định rõ (rfdef), nhưng theo từ điển GDHN có nghĩa \"rau thuần\" — một loài rau nước. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây rau thuần", "Hạng Tần Suất (Jun Da)": "8870.0", "Tần Suất % (Jun Da)": "99.9999514222", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒪", "Unihan_Traditional (Chữ Phồn thể)": "蒪", "Pinyin_Xie": "pò", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại rau thủy sinh ăn được. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝑', '{"9000": "8871.0", "Chữ Trung Quốc": "蝑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 胥 | tư | biểu âm | 蝑 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 胥 (Tư, biểu âm); chữ hình thanh. Phần 虫 cho biết đây là loài côn trùng; phần 胥 cho âm đọc xū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 虫 (sâu bọ) + 胥 (tư, cho âm) = côn trùng \"tư\" — loài sinh vật nhỏ. | Gương Hán-Việt | tư — ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 蝑 (tư) giúp nhận cấu tạo hình thanh với bộ 虫 trong các chữ côn trùng hiếm.", "Tự nguyên_Xie": "Wiktionary xác nhận 蝑 là chữ hình thanh (ls=psc): 虫 (trùng, sâu bọ — biểu nghĩa) + 胥 (tư — biểu âm). Đây là cấu tạo hình thanh điển hình trong nhóm côn trùng của Hán tự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "蝑", "Hạng Tần Suất (Jun Da)": "8871.0", "Tần Suất % (Jun Da)": "99.999951939", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝑", "Unihan_Traditional (Chữ Phồn thể)": "蝑", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài côn trùng thuộc bộ cánh thẳng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螧', '{"9000": "8872.0", "Chữ Trung Quốc": "螧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螧 | khải | tượng hình | loài côn trùng chưa xác định | 螧 thuộc bộ 虫 (trùng). Không có dữ liệu Wiktionary. Xử lý như tượng hình trong nhóm côn trùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": bộ 虫 (sâu bọ) — \"khải\" như con bọ mở ra đôi cánh. | Gương Hán-Việt | khải — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 螧 (khải) giúp nhận bộ 虫 trong các chữ côn trùng hiếm gặp.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 螧. Bộ 虫 gợi ý đây là loài côn trùng. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "觧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 耆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫耆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螧", "Unihan_Traditional (Chữ Phồn thể)": "螧", "Pinyin_Xie": "qi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cua nhỏ sống ở bờ biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟅', '{"9000": "8873.0", "Chữ Trung Quốc": "蟅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟅 | giá | tượng hình | ba ba, rùa nước | 蟅 thuộc bộ 虫 (trùng). Không có dữ liệu Wiktionary. Bộ 虫 xác nhận đây là động vật bò sát hay lưỡng cư. Xử lý như tượng hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\": bộ 虫 (sinh vật) + âm zhè — \"giá\" như con ba ba \"giá\" lạnh nằm dưới bùn. | Gương Hán-Việt | giá — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蟅 (giá) giúp đọc văn bản y học cổ dùng ba ba làm dược liệu.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 蟅. Bộ 虫 và nghĩa \"ba ba\" xác nhận liên quan đến động vật lưỡng cư/bò sát. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ba ba", "Hạng Tần Suất (Jun Da)": "8873.0", "Tần Suất % (Jun Da)": "99.9999529726", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 庶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫庶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟅", "Unihan_Traditional (Chữ Phồn thể)": "蟅", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con ba ba hoặc một loại côn trùng dùng làm thuốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟢', '{"9000": "8874.0", "Chữ Trung Quốc": "蟢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 蟢 | hỉ | tượng hình | nhện chân dài — loài nhện được coi là điềm lành | 蟢 thuộc bộ 虫 (trùng). Wiktionary không cung cấp phân tích glyph-origin; nghĩa liên quan đến loài nhện. Xử lý như tượng hình trong nhóm côn trùng/nhện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỉ\": bộ 虫 (sâu bọ) + âm xǐ — con nhện \"hỉ\" (mừng) đến nhà là điềm lành, tên còn gọi là \"hỉ nhện\". | Gương Hán-Việt | hỉ — liên hệ 喜 (hỉ, vui mừng), cùng âm | Mở khoá kiến thức | Biết 蟢 (hỉ) mở khoá liên hệ văn hóa: nhện hỉ = điềm lành trong phong tục Á Đông.", "Tự nguyên_Xie": "Wiktionary xác nhận 蟢 thuộc bộ 虫, âm xǐ. Chỉ loài nhện chân dài (蟢子), được coi là điềm lành trong văn hóa Trung Quốc. Chưa có glyph-origin học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhện cao chân", "Hạng Tần Suất (Jun Da)": "8874.0", "Tần Suất % (Jun Da)": "99.9999534893", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟢", "Unihan_Traditional (Chữ Phồn thể)": "蟢", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "hỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ một loài nhện nhỏ chân dài theo quan niệm dân gian mang lại điềm lành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貒', '{"9000": "8875.0", "Chữ Trung Quốc": "貒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豸 | Số nét | 16 | nét | 貒 | đoàn | tượng hình | heo rừng — loài thú họ bò sát/thú hoang | 貒 thuộc bộ 豸 (trãi, thú không chân trước). Wiktionary chỉ ghi {{Han etym}} không có nội dung. Xử lý như tượng hình trong nhóm thú hoang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoàn\": bộ 豸 (thú) + âm tuān — đàn heo rừng chạy \"đoàn\" tụ trong rừng sâu. | Gương Hán-Việt | đoàn — liên hệ 团 (đoàn, nhóm); cùng âm tuán | Mở khoá kiến thức | Biết 貒 (đoàn) giúp nhận bộ 豸 trong các chữ thú hoang cổ điển.", "Tự nguyên_Xie": "Wiktionary xác nhận 貒 thuộc bộ 豸, âm tuān. Nghĩa: heo rừng. Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "heo rừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "豸 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰豸耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豸", "Unihan_Simplified (Chữ Giản thể)": "貒", "Unihan_Traditional (Chữ Phồn thể)": "貒", "Pinyin_Xie": "tuān", "Âm Hán Việt_Xie": "thon", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ loài thú giống lợn rừng hoặc con lửng trong các tài liệu cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('関', '{"9000": "8876.0", "Chữ Trung Quốc": "関", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 14 | nét | 関 | quan | tượng hình | cửa ải, cửa quan — dạng rút gọn của 關 | 関 là dạng bất chính thể của 關 (quan), được liệt kê trong Khang Hi tự điển. Cấu tạo ⿵門关 (bộ 門 + 关 bên trong). Trong tiếng Nhật hiện đại đây là dạng cải cách (shinjitai).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quan\": 門 (cửa) bao quanh 关 (đóng lại) — \"quan\" như cửa quan ải đóng chặt, kiểm soát qua lại. | Gương Hán-Việt | quan — dùng rộng rãi: quan ải, cơ quan, quan hệ, quan trọng | Mở khoá kiến thức | Biết 関/關 (quan) mở khoá: 关系 (quan hệ), 关键 (quan trọng), 海关 (hải quan).", "Tự nguyên_Xie": "Kim văn | Lục thư thông | Wiktionary xác nhận 関 là dạng rút gọn/bất chính thể của 關, với 𢇇 được thay bằng 关. Dạng này được Khang Hi tự điển liệt kê là bất chính thể. Tiếng Nhật hiện đại dùng 関 như dạng cải cách (shinjitai). Hình kim văn hiện diện, xác nhận chữ có lịch sử lâu đời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa ải, cửa ô; đóng (cửa); quan hệ, liên quan", "Hạng Tần Suất (Jun Da)": "8876.0", "Tần Suất % (Jun Da)": "99.9999550397", "GavinGrover_Once (Chiết tự trực tiếp)": "門 + 关", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門关", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "关", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "関", "Unihan_Traditional (Chữ Phồn thể)": "関", "Pinyin_Xie": "guān", "Âm Hán Việt_Xie": "quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cửa ải hoặc động từ mang nghĩa đóng cửa, liên quan trong văn bản. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礤', '{"9000": "8877.0", "Chữ Trung Quốc": "礤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 19 | nét | 礤 | sát | tượng hình | đá mài, dụng cụ nạo thực phẩm | 礤 thuộc bộ 石 (thạch, đá). Wiktionary không cung cấp glyph-origin cấu tạo; nghĩa rõ ràng liên quan đến đá thô và dụng cụ bếp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sát\": bộ 石 (đá) + âm cǎ — cái \"sát\" nạo củ cải, cọ xát như đá nhám. | Gương Hán-Việt | sát — liên hệ \"sát hạch\" (cọ sát, kiểm tra); cùng âm thanh | Mở khoá kiến thức | Biết 礤 (sát) giúp đọc văn bản ẩm thực và nông cụ dân gian.", "Tự nguyên_Xie": "Wiktionary xác nhận 礤 thuộc bộ 石, âm cǎ/cā. Nghĩa: đá mài/dụng cụ nạo rau củ (grater/shredder); động từ chỉ hành động cọ, mài, nạo. Trong tiếng Min Nam còn có nghĩa đá thô. Không có glyph-origin học thuật. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá thô", "Hạng Tần Suất (Jun Da)": "8877.0", "Tần Suất % (Jun Da)": "99.9999555565", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 蔡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石蔡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蔡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "礤", "Unihan_Traditional (Chữ Phồn thể)": "礤", "Pinyin_Xie": "cǎ", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dụng cụ xát rau củ hoặc động từ chỉ hành động chà xát, mài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鴙', '{"9000": "8878.0", "Chữ Trung Quốc": "鴙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 鴙 | trĩ | tượng hình | chim trĩ hoặc loài chim tương tự | 鴙 thuộc bộ 鳥 (điểu, chim). Không có dữ liệu Wiktionary. Bộ 鳥 xác nhận đây là loài chim. Xử lý như tượng hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": bộ 鳥 (chim) + âm zhì — con chim \"trĩ\" đuôi dài sặc sỡ trong rừng. | Gương Hán-Việt | trĩ — dùng trong \"chim trĩ\" tiếng Việt, loài chim đẹp | Mở khoá kiến thức | Biết 鴙 (trĩ) giúp nhận nhóm chim trĩ và họ hàng trong văn bản điểu học cổ.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 鴙. Bộ 鳥 xác nhận đây là loài chim. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Soo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "矢 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矢鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矢", "Unihan_Simplified (Chữ Giản thể)": "鴙", "Unihan_Traditional (Chữ Phồn thể)": "鴙", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để chỉ loài chim trĩ có đuôi dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鵣', '{"9000": "8879.0", "Chữ Trung Quốc": "鵣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 18 | nét | 鵣 | lại | tượng hình | loài chim chưa xác định | 鵣 thuộc bộ 鳥 (điểu). Wiktionary chỉ ghi {{Han etym}} không có nội dung. Xử lý như tượng hình trong nhóm chim.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lại\": bộ 鳥 (chim) + âm lài — con chim \"lại\" bay về, như loài chim di cư. | Gương Hán-Việt | lại — liên hệ 来 (lại, đến); cùng âm | Mở khoá kiến thức | Biết 鵣 (lại) giúp nhận nhóm chim hiếm với bộ 鳥 trong văn bản điểu học cổ.", "Tự nguyên_Xie": "Wiktionary xác nhận 鵣 thuộc bộ 鳥, âm lài. Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cám", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "束 + 鳥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鳥", "Unihan_Simplified (Chữ Giản thể)": "鵣", "Unihan_Traditional (Chữ Phồn thể)": "鵣", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thư tịch cổ để chỉ một loài chim nhỏ thuộc họ sẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盢', '{"9000": "8880.0", "Chữ Trung Quốc": "盢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 14 | nét | 盢 | tục | tượng hình | dụng cụ bằng kim loại (chưa xác định rõ) | 盢 thuộc bộ 皿 (mãnh, đồ đựng). Không có dữ liệu Wiktionary. Bộ 皿 xác nhận liên quan đến đồ đựng. Xử lý như tượng hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tục\": bộ 皿 (đồ đựng) + âm xù — chiếc bình \"tục\" lệ truyền từ đời này sang đời khác. | Gương Hán-Việt | tục — liên hệ 俗 (tục lệ, phong tục); cùng âm | Mở khoá kiến thức | Biết 盢 (tục) giúp nhận bộ 皿 trong các chữ đồ đựng cổ điển.", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary glyph-origin cho 盢. Bộ 皿 gợi ý đồ đựng hoặc dụng cụ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "碢", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "畎 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱畎皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盢", "Unihan_Traditional (Chữ Phồn thể)": "盢", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại đồ đựng hoặc dụng cụ bằng đá thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眘', '{"9000": "8881.0", "Chữ Trung Quốc": "眘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 10 | nét | 眘 | thận | tượng hình | thận trọng; dùng làm tên người | 眘 thuộc bộ 目 (mục, mắt). Không có dữ liệu Wiktionary. Bộ 目 gợi ý liên quan đến mắt hoặc quan sát thận trọng. Có hình tiểu triện từ nguồn hanziyuan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thận\": bộ 目 (mắt) + âm shèn — đôi mắt \"thận\" trọng quan sát cẩn thận từng chi tiết. | Gương Hán-Việt | thận — liên hệ 慎 (thận trọng), 腎 (thận tạng); cùng âm | Mở khoá kiến thức | Biết 眘 (thận) giúp nhận nhóm chữ thận trọng và quan sát trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Chưa có nguồn Wiktionary glyph-origin cho 眘. Bộ 目 gợi ý liên quan đến quan sát, cẩn thận. Nghĩa: thận trọng; dùng làm tên người. Có hình tiểu triện. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thận (dùng làm tên người)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "𡗜 + 目", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𡗜目", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡗜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眘", "Unihan_Traditional (Chữ Phồn thể)": "眘", "Pinyin_Xie": "shèn", "Âm Hán Việt_Xie": "thận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để chỉ thái độ cẩn trọng hoặc làm tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('礿', '{"9000": "8882.0", "Chữ Trung Quốc": "礿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 7 | nét | 礿 | thược | tượng hình | tế lễ tổ tiên mùa xuân (thời Hạ/Thương) hoặc mùa hè (thời Chu) | 礿 thuộc bộ 示 (thị, thần linh, tế lễ). Wiktionary xác nhận nghĩa rõ ràng. Bộ 示 xác nhận liên quan đến tế lễ. Có hình kim văn, đại triện và tiểu triện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thược\": bộ 示 (tế lễ) + âm yuè — nghi lễ \"thược\" dâng lên thần linh mỗi mùa xuân. | Gương Hán-Việt | thược — ít dùng trong tiếng Việt; liên hệ 禴祭 (lễ tế mùa xuân) | Mở khoá kiến thức | Biết 礿 (thược) giúp đọc văn bản lễ nghi triều đình nhà Hạ, Thương, Chu.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Wiktionary xác nhận 礿 thuộc bộ 示, âm yuè. Nghĩa: tế lễ tổ tiên dâng triều đình — mùa xuân thời Hạ/Thương, mùa hè thời Chu. Có hình kim văn, đại triện, tiểu triện xác nhận nguồn gốc cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tế tổ tiên triều đình mùa xuân", "Hạng Tần Suất (Jun Da)": "8882.0", "Tần Suất % (Jun Da)": "99.9999617579", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 勺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻勺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "礿", "Unihan_Traditional (Chữ Phồn thể)": "礿", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "dược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ nghi lễ cúng tế tổ tiên vào mùa xuân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祩', '{"9000": "8883.0", "Chữ Trung Quốc": "祩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祩 | chú | tượng hình | chữ thuộc bộ thị, nghĩa chưa xác định | 祩 thuộc bộ 示 (thị, thần linh, tế lễ). Wiktionary không cung cấp định nghĩa (rfdef). Xử lý như tượng hình trong nhóm tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chú\": bộ 示 (thần linh) + âm zhù — \"chú\" như lời chú nguyện, khấn vái thần linh. | Gương Hán-Việt | chú — liên hệ 咒 (chú, thần chú), 祝 (chúc, cầu phúc); cùng nhóm tế lễ | Mở khoá kiến thức | Biết 祩 (chú) giúp nhận nhóm tế lễ và thần chú trong bộ 示.", "Tự nguyên_Xie": "Wiktionary xác nhận 祩 thuộc bộ 示, âm zhù. Nghĩa chưa được xác định (rfdef). Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "祩", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祩", "Unihan_Traditional (Chữ Phồn thể)": "祩", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ hành động cầu khấn hoặc nguyền rủa thần linh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禨', '{"9000": "8884.0", "Chữ Trung Quốc": "禨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 16 | nét | 禨 | ky | tượng hình | cầu phúc thần linh; điềm lành dữ | 禨 thuộc bộ 示 (thị, thần linh). Wiktionary chỉ ghi {{Han etym}} không có nội dung. Nghĩa: cầu phúc, xem điềm lành dữ. Bộ 示 xác nhận liên quan tế lễ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ky\": bộ 示 (thần linh) + âm jī — \"ky\" như cầu ký nguyện, xin thần linh ban phúc. | Gương Hán-Việt | ky — ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 禨 (ky) giúp đọc văn bản bói toán và tế lễ cầu phúc trong văn ngôn.", "Tự nguyên_Xie": "Wiktionary xác nhận 禨 thuộc bộ 示, âm jī. Nghĩa: cầu xin phúc lành từ thần linh; xem điềm lành dữ. Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quỷ thần", "Hạng Tần Suất (Jun Da)": "8884.0", "Tần Suất % (Jun Da)": "99.9999627915", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 幾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻幾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "禨", "Unihan_Traditional (Chữ Phồn thể)": "禨", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ quỷ thần hoặc các điềm báo cát hung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秺', '{"9000": "8885.0", "Chữ Trung Quốc": "秺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秺 | đổ | tượng hình | chữ thuộc bộ hòa, nghĩa chưa xác định | 秺 thuộc bộ 禾 (hòa, lúa). Wiktionary không cung cấp định nghĩa rõ (rfdef). Bộ 禾 xác nhận liên quan đến lúa, nông nghiệp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đổ\": bộ 禾 (lúa) + âm dù — \"đổ\" như lúa mạ đổ nghiêng trong gió mùa. | Gương Hán-Việt | đổ — liên hệ 度 (đổ, đo lường); cùng âm dù | Mở khoá kiến thức | Biết 秺 (đổ) giúp nhận bộ 禾 trong các chữ nông nghiệp cổ điển.", "Tự nguyên_Xie": "Wiktionary xác nhận 秺 thuộc bộ 禾, âm dù. Nghĩa chưa xác định (rfdef). Theo từ điển VHN: \"秧\" (mạ). Chưa có glyph-origin học thuật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "秧", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 宅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾宅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秺", "Unihan_Traditional (Chữ Phồn thể)": "秺", "Pinyin_Xie": "dù", "Âm Hán Việt_Xie": "đổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh cổ hoặc danh từ chỉ cây mạ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穟', '{"9000": "8886.0", "Chữ Trung Quốc": "穟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 穟 | tuệ | tượng hình | bông lúa chín | 穟 là chữ độc thể, thuộc bộ 禾 (hòa, lúa). Chữ tạo muộn, chưa thấy cấu trúc phân tích rõ ràng trong giáp cốt hay kim văn. Có thể xem như tượng hình bông lúa chín rủ xuống. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": hình ảnh bông lúa 禾 chín rủ xuống — lúa chín là tuệ, sáng suốt như mùa gặt. | Gương Hán-Việt | tuệ trong nghĩa bông lúa chín; ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 穟 mở khoá nhóm từ chỉ lúa chín, bông lúa trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 穟 thuộc bộ 禾 (lúa), mang nghĩa bông lúa chín, lúa trĩu hạt. Chữ tạo muộn, chỉ thấy trong tiểu triện (hanziyuan). Chưa có phân tích nguồn gốc chính thức từ Wiktionary. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông", "Hạng Tần Suất (Jun Da)": "8886.0", "Tần Suất % (Jun Da)": "99.999963825", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穟", "Unihan_Traditional (Chữ Phồn thể)": "穟", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "toại, tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ bông lúa hoặc tính từ tả vẻ đẹp sum suê. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窫', '{"9000": "8887.0", "Chữ Trung Quốc": "窫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 14 | nét | 窫 | ách | tượng hình | tên sinh vật thần thoại (窫窳) | 窫 là chữ độc thể thuộc bộ 穴 (huyệt, hang). Wiktionary ghi nhận chữ này chỉ xuất hiện trong tổ hợp 窫窳 (sinh vật thần thoại trong Sơn Hải Kinh), không phân tích cấu trúc thành phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": chữ 穴 (hang) ẩn chứa sinh vật 窫窳 đáng sợ — ách tắc, nguy hiểm rình rập trong bóng tối. | Gương Hán-Việt | ách trong 窫窳 (ách dũ) — tên sinh vật thần thoại Trung Hoa cổ đại | Mở khoá kiến thức | Biết 窫 mở khoá điển tích 窫窳 trong Sơn Hải Kinh và văn học cổ điển Trung Hoa.", "Tự nguyên_Xie": "窫 chỉ dùng trong tổ hợp 窫窳 (ách dũ), tên một sinh vật thần thoại trong Sơn Hải Kinh — hình người, tiếng như trẻ khóc, ăn thịt người. Wiktionary không cung cấp phân tích glyph origin cho chữ này; chỉ ghi ''Han etym''. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Thiệu", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窫", "Unihan_Traditional (Chữ Phồn thể)": "窫", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ trong tên gọi loài ác thú thần thoại hoặc tính từ chỉ sự lõm xuống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笎', '{"9000": "8888.0", "Chữ Trung Quốc": "笎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 笎 | viên | tượng hình | loại tre, dụng cụ bằng tre | 笎 là chữ thuộc bộ 竹 (trúc, tre). Không có phân tích thành phần rõ ràng trong Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": bộ 竹 gợi tre vót tròn thành vòng — viên tròn như ống tre. | Gương Hán-Việt | viên trong nghĩa đồ vật tre tròn; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 笎 mở khoá nhóm từ chỉ đồ dùng bằng tre trong văn ngôn cổ điển.", "Tự nguyên_Xie": "笎 thuộc bộ 竹 (tre), mang nghĩa liên quan đến đồ vật bằng tre. Wiktionary không cung cấp glyph origin hay phân tích cấu trúc cho chữ này. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tre với những mảng đen", "Hạng Tần Suất (Jun Da)": "8888.0", "Tần Suất % (Jun Da)": "99.9999648586", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笎", "Unihan_Traditional (Chữ Phồn thể)": "笎", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ một giống tre đặc biệt có đốm đen trên thân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篨', '{"9000": "8889.0", "Chữ Trung Quốc": "篨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 15 | nét | 篨 | trừ | tượng hình | loại chiếu tre, vật liệu bằng tre | 篨 là chữ thuộc bộ 竹 (trúc, tre). Wiktionary ghi nhận chữ này xuất hiện trong tổ hợp 籧篨, chỉ loại chiếu thô bằng tre. Không có phân tích glyph origin chi tiết. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trừ\": bộ 竹 gợi những thanh tre đan thành chiếu — trừ đi sự tinh tế, chỉ còn lại chiếu thô. | Gương Hán-Việt | trừ trong 籧篨 (cự trừ) — chiếu tre thô; ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 篨 mở khoá điển tích 籧篨 và các từ chỉ đồ đan tre trong văn ngôn cổ điển.", "Tự nguyên_Xie": "篨 thuộc bộ 竹 (tre), xuất hiện trong tổ hợp 籧篨 (cự trừ) — loại chiếu thô đan bằng tre dùng trong tang lễ hoặc sinh hoạt đồng áng thời cổ. Wiktionary không cung cấp phân tích cấu trúc chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiếu trúc", "Hạng Tần Suất (Jun Da)": "8889.0", "Tần Suất % (Jun Da)": "99.9999653754", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 除", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮除", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "除", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篨", "Unihan_Traditional (Chữ Phồn thể)": "篨", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại chiếu hoặc mành làm bằng tre trúc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籋', '{"9000": "8890.0", "Chữ Trung Quốc": "籋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 20 | nét | 籋 | nhiếp | tượng hình | kẹp, cái nhíp bằng tre | 籋 là chữ thuộc bộ 竹 (trúc, tre). Wiktionary ghi nhận chữ này nhưng không cung cấp phân tích glyph origin chi tiết, chỉ có phiên âm. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\": bộ 竹 gợi thanh tre uốn cong kẹp chặt — nhiếp phục, kẹp giữ chắc như nhíp tre. | Gương Hán-Việt | nhiếp trong nghĩa kẹp, nhíp; liên hệ 攝 (nhiếp) trong 摄影 (nhiếp ảnh) | Mở khoá kiến thức | Biết 籋 mở khoá nhóm từ chỉ dụng cụ kẹp, nhíp trong văn ngôn và thủ công nghệ cổ.", "Tự nguyên_Xie": "籋 thuộc bộ 竹 (tre), có khả năng chỉ loại kẹp hay nhíp làm bằng tre. Wiktionary chỉ ghi phiên âm (niè, Quảng: nip6) mà không phân tích cấu trúc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhíp; cái nhíp; cái kẹp", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 爾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮爾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "籋", "Unihan_Traditional (Chữ Phồn thể)": "籋", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "nhiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ dụng cụ gắp hoặc động từ chỉ hành động kẹp, gắp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緤', '{"9000": "8891.0", "Chữ Trung Quốc": "緤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緤 | tiết | tượng hình | dây buộc súc vật | 緤 là chữ thuộc bộ 糸 (mịch, sợi). Wiktionary không cung cấp phân tích glyph origin chi tiết ngoài phiên âm. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": bộ 糸 (sợi) gợi sợi dây thắt nút — tiết chế, buộc lại như dây xích súc vật. | Gương Hán-Việt | tiết trong nghĩa dây buộc; liên hệ 節 (tiết) trong 节制 (tiết chế) | Mở khoá kiến thức | Biết 緤 mở khoá nhóm từ bộ 糸 chỉ dây, thừng, ràng buộc trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 緤 thuộc bộ 糸 (sợi dây), mang nghĩa dây thừng dùng để buộc súc vật. Chữ tạo muộn, thấy trong tiểu triện và liushutong (hanziyuan). Wiktionary không cung cấp glyph origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cương ngựa", "Hạng Tần Suất (Jun Da)": "8891.0", "Tần Suất % (Jun Da)": "99.999966409", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "緤", "Unihan_Traditional (Chữ Phồn thể)": "緤", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ dây buộc hoặc động từ với nghĩa trói buộc, dắt bằng dây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('緵', '{"9000": "8892.0", "Chữ Trung Quốc": "緵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 緵 | tông | tượng hình | loại vải thô, vải đơn sợi | 緵 là chữ thuộc bộ 糸 (mịch, sợi). Wiktionary chỉ ghi ''Han etym'' không có phân tích glyph origin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\": bộ 糸 gợi sợi chỉ — tông màu của vải thô, mộc mạc như sợi chưa nhuộm. | Gương Hán-Việt | tông trong nghĩa vải thô sợi đơn; liên hệ 宗 (tông) trong 宗族 (tông tộc) | Mở khoá kiến thức | Biết 緵 mở khoá nhóm từ bộ 糸 chỉ loại vải trong nghề dệt truyền thống.", "Tự nguyên_Xie": "緵 thuộc bộ 糸 (sợi), mang nghĩa vải dệt thô từ sợi đơn. Wiktionary không cung cấp phân tích nguồn gốc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "絵", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "緵", "Unihan_Traditional (Chữ Phồn thể)": "緵", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ sợi tơ hoặc lượng từ đếm số lần dệt sợi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縚', '{"9000": "8893.0", "Chữ Trung Quốc": "縚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 縚 | thao | tượng hình | dây thắt lưng, dây buộc | 縚 là chữ thuộc bộ 糸 (mịch, sợi). Wiktionary chỉ ghi ''Han etym'' không phân tích glyph origin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\": bộ 糸 gợi sợi dây — thao lược, sợi thao cuộn chắc như dây lưng võ tướng. | Gương Hán-Việt | thao trong 縚帶 (thao đới) — dây thắt lưng bằng tơ; liên hệ 韬 (thao) trong 韬略 (thao lược) | Mở khoá kiến thức | Biết 縚 mở khoá nhóm từ chỉ dây buộc trang phục và vũ khí trong văn ngôn cổ điển.", "Tự nguyên_Xie": "縚 thuộc bộ 糸 (sợi dây), mang nghĩa dây thắt lưng hay dây buộc bằng sợi. Âm Hán-Việt ''thao'' xuất phát từ Trung cổ âm *thaw. Wiktionary không cung cấp phân tích nguồn gốc chữ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây bằng sợi tơ", "Hạng Tần Suất (Jun Da)": "8893.0", "Tần Suất % (Jun Da)": "99.9999674425", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縚", "Unihan_Traditional (Chữ Phồn thể)": "縚", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại dây đeo, dây trang trí làm bằng tơ bện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('繿', '{"9000": "8894.0", "Chữ Trung Quốc": "繿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 繿 | lam | tượng hình | vải rách, quần áo rách tả tơi | 繿 là chữ thuộc bộ 糸 (mịch, sợi). Không có phân tích glyph origin trong Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": bộ 糸 gợi sợi vải — lam lũ, vải tơi tả như người nghèo khổ lam lũ. | Gương Hán-Việt | lam trong 繿縷 (lam lũ) — vải rách tả tơi; liên hệ từ ''lam lũ'' trong tiếng Việt | Mở khoá kiến thức | Biết 繿 mở khoá nhóm từ bộ 糸 chỉ vải rách, quần áo tơi tả trong văn ngôn.", "Tự nguyên_Xie": "繿 thuộc bộ 糸 (sợi), mang nghĩa vải rách, quần áo tơi tả. Âm Hán-Việt ''lam'' xuất phát từ Trung cổ âm. Wiktionary không cung cấp glyph origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 監", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹監", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "監", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "繿", "Unihan_Traditional (Chữ Phồn thể)": "繿", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường xuất hiện trong từ ghép để chỉ trang phục rách rưới hoặc cũ nát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羙', '{"9000": "8895.0", "Chữ Trung Quốc": "羙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 10 | nét | 羊 | dương | biểu nghĩa | dê, cừu — gợi vẻ đẹp, sự phồn thịnh | 大 | đại | biểu nghĩa | lớn, vĩ đại | 羙 là chữ hội ý (tượng ý): 羊 (dương, cừu) bên trên + 大 (đại, lớn) bên dưới. Cừu to béo = đẹp, ngon, sung túc. Đây là dạng cổ của chữ 美 (mỹ). Chưa có nguồn học thuật chính thức về riêng chữ 羙.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mỹ\": 羊 (cừu) to béo + 大 (lớn) = mỹ mãn — cừu lớn là đẹp, no đủ, mỹ vị. | Gương Hán-Việt | mỹ trong 美丽 (mỹ lệ), 美好 (mỹ hảo) — đẹp đẽ, tốt lành | Mở khoá kiến thức | Biết 羙/美 mở khoá hàng chục từ Hán-Việt: mỹ lệ, mỹ thuật, mỹ vị, mỹ nhân, hoàn mỹ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 羙 là dạng cổ của 美 (mỹ, đẹp), cấu tạo từ 羊 (cừu) và 大 (lớn): con cừu to béo = sung túc, đẹp đẽ. Chữ xuất hiện rất nhiều trong giáp cốt văn (oracle bone) và kim văn. Nghĩa gốc: đẹp, ngon, tốt lành. Chưa có nguồn học thuật riêng biệt cho dạng 羙 (phân biệt với 美). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "羙", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羙", "Unihan_Traditional (Chữ Phồn thể)": "羙", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "mỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Là biến thể chữ viết của chữ Mỹ, dùng làm tính từ miêu tả vẻ đẹp hoặc sự tốt lành. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘂', '{"9000": "8896.0", "Chữ Trung Quốc": "蘂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘂 | nhị | tượng hình | nhị hoa, nhụy hoa | 蘂 là chữ thuộc bộ 艸 (thảo, cỏ/hoa). Là dạng cổ/phồn thể của 蕊 (nhị hoa). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": bộ 艸 gợi hoa cỏ — nhị hoa rung rinh trong gió, mỏng manh như sợi chỉ vàng. | Gương Hán-Việt | nhị trong 花蘂 (hoa nhị) — nhị hoa; liên hệ ''nhị hoa'' trong tiếng Việt | Mở khoá kiến thức | Biết 蘂/蕊 mở khoá từ chỉ nhị hoa, phấn hoa trong thơ ca và thực vật học cổ điển.", "Tự nguyên_Xie": "蘂 là dạng cổ của 蕊 (nhị, ruǐ), thuộc bộ 艸 (cỏ hoa), mang nghĩa nhị hoa, nhụy hoa. Hán-Việt ''nhị'' gần với tiếng Việt ''nhị hoa'' hay ''nhụy''. Wiktionary không cung cấp glyph origin riêng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhị hoa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 橤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹橤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "橤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘂", "Unihan_Traditional (Chữ Phồn thể)": "蘂", "Pinyin_Xie": "ruǐ", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ bộ phận sinh sản của hoa hoặc phần trung tâm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜼', '{"9000": "8897.0", "Chữ Trung Quốc": "蜼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật bò | 隹 | chuy | biểu âm | chim đuôi ngắn (biểu âm) | 蜼 là chữ hình thanh (psc): 虫 (trùng, biểu nghĩa: sinh vật bò) + 隹 (chuy, biểu âm). Wiktionary ghi rõ ls=psc, c1=s (虫 biểu nghĩa), c2=p (隹 biểu âm). Chữ chỉ loài khỉ đuôi dài sống ở núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\": 虫 (sinh vật) + 隹 (chim, biểu âm) = vị — con khỉ linh hoạt như chim trên cây, vị trí độc đáo trong rừng núi. | Gương Hán-Việt | vị trong 蜼 — loài khỉ đuôi dài; ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 蜼 mở khoá nhóm từ cổ chỉ thú vật rừng núi trong thơ ca và bản đồ tự nhiên cổ.", "Tự nguyên_Xie": "Tiểu triện | 蜼 = 虫 (trùng, biểu nghĩa: sinh vật) + 隹 (chuy, biểu âm). Chữ hình thanh rõ ràng theo Wiktionary (ls=psc). 蜼 chỉ loài khỉ đuôi dài hay sinh vật leo trèo trong núi rừng thời cổ. Âm Hán-Việt ''vị'' từ Trung cổ âm *wjɨjH. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con khỉ đuôi dài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜼", "Unihan_Traditional (Chữ Phồn thể)": "蜼", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn ngôn để chỉ một loài khỉ lớn có đuôi dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襘', '{"9000": "8898.0", "Chữ Trung Quốc": "襘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 18 | nét | 襘 | cổi | tượng hình | giao nhau của vạt áo, nơi hai cạnh cổ áo chéo nhau | 襘 là chữ thuộc bộ 衣 (y, quần áo). Wiktionary mô tả nghĩa (chỗ giao nhau của cổ áo) nhưng không phân tích glyph origin thành phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổi\": bộ 衣 gợi vải áo — cổi áo chéo đan vào nhau tại điểm 襘, như hai dòng sông gặp nhau. | Gương Hán-Việt | cổi trong 襘 — chỗ giao nhau của vạt áo; liên hệ ''cổ áo'' trong tiếng Việt | Mở khoá kiến thức | Biết 襘 mở khoá từ chỉ cấu tạo trang phục truyền thống Trung Hoa cổ đại.", "Tự nguyên_Xie": "襘 thuộc bộ 衣 (quần áo), chỉ điểm giao nhau của hai vạt áo, nơi mép cổ áo chéo đè lên nhau. Wiktionary ghi nhận hai nghĩa: (1) chỗ chéo nhau của cổ áo; (2) điểm tiếp xúc giữa các miếng vải. Không có phân tích glyph origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(đầu cổ áo)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 會", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤會", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "會", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襘", "Unihan_Traditional (Chữ Phồn thể)": "襘", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ phần giao nhau của cổ áo hoặc nếp gấp trên trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('訞', '{"9000": "8899.0", "Chữ Trung Quốc": "訞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 訞 | yêu | tượng hình | điềm xấu, lời nói xấu xa yêu ma | 訞 là chữ thuộc bộ 言 (ngôn, lời nói). Wiktionary ghi nhận nhưng không có glyph origin hay phân tích thành phần rõ ràng. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêu\": bộ 言 gợi lời nói — yêu quái thốt lời mê hoặc, nói những điều yêu tà. | Gương Hán-Việt | yêu trong 訞 — lời nói ma quái, điềm xấu; liên hệ 妖 (yêu) trong 妖怪 (yêu quái) | Mở khoá kiến thức | Biết 訞 mở khoá nhóm từ chỉ điềm xấu, lời sấm ngữ trong văn học cổ điển.", "Tự nguyên_Xie": "訞 thuộc bộ 言 (lời nói), mang nghĩa lời nói xấu xa, điềm dữ, liên quan đến ma quái. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''yêu'' từ Trung cổ âm *ʔjiew. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "螞", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "言 + 夭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰言夭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "言", "Unihan_Simplified (Chữ Giản thể)": "訞", "Unihan_Traditional (Chữ Phồn thể)": "訞", "Pinyin_Xie": "yāo", "Âm Hán Việt_Xie": "yêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Dùng làm tính từ chỉ sự kỳ quái hoặc động từ chỉ việc dùng lời ma mị để lừa dối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谼', '{"9000": "8900.0", "Chữ Trung Quốc": "谼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 谷 | Số nét | 13 | nét | 谼 | hống | tượng hình | tiếng vang dội, tiếng lớn trong hang | 谼 là chữ thuộc bộ 谷 (cốc, khe núi/hang). Wiktionary chỉ ghi ''Han etym'' không có phân tích thành phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hống\": bộ 谷 (khe núi) gợi tiếng vang — hống hách, tiếng vang dội trong khe núi sâu thẳm. | Gương Hán-Việt | hống trong 谼谷 (hống cốc) — khe núi vang âm; liên hệ ''hống hách'' trong tiếng Việt | Mở khoá kiến thức | Biết 谼 mở khoá nhóm từ chỉ âm thanh vang dội, khe núi trong thơ ca cổ điển.", "Tự nguyên_Xie": "谼 thuộc bộ 谷 (khe núi, hang), mang nghĩa tiếng vang dội trong khe hang, âm thanh lớn. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''hống'' từ Trung cổ âm *ɣəwŋ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "谼", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "谷 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰谷共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "谷", "Unihan_Simplified (Chữ Giản thể)": "谼", "Unihan_Traditional (Chữ Phồn thể)": "谼", "Pinyin_Xie": "hóng", "Âm Hán Việt_Xie": "hống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong văn học cổ để miêu tả địa hình khe núi sâu thẳm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躭', '{"9000": "8901.0", "Chữ Trung Quốc": "躭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 身 | Số nét | 11 | nét | 身 | thân | biểu nghĩa | thân thể, mình | 冘 | đem | biểu âm | đi, di chuyển (biểu âm) | 躭 là chữ hình thanh (psc): 身 (thân, biểu nghĩa: thân thể) + 冘 (đem, biểu âm). Wiktionary ghi rõ ls=psc, c1=s (身 biểu nghĩa), c2=p (冘 biểu âm). Đây là dạng cổ của 耽 (đam mê, chìm đắm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": 身 (thân) + 冘 (đi) — toàn thân đắm chìm trong đam mê, không thể rời bước. | Gương Hán-Việt | đam trong 耽/躭 — đam mê, chìm đắm; liên hệ ''đam mê'' trong tiếng Việt | Mở khoá kiến thức | Biết 躭/耽 mở khoá từ 耽誤 (đam ngộ — chậm trễ), 耽溺 (đam nịch — đắm chìm) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 躭 = 身 (thân, biểu nghĩa) + 冘 (đem, biểu âm). Chữ hình thanh theo Wiktionary (ls=psc). 躭 là dạng cổ/dị thể của 耽, nghĩa là đắm chìm, mê đắm, trì hoãn. Âm Hán-Việt ''đam'' từ Trung cổ âm *tɑm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mê mải, đắm đuối", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "身 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰身冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "身", "Unihan_Simplified (Chữ Giản thể)": "躭", "Unihan_Traditional (Chữ Phồn thể)": "躭", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ thể hiện sự ham mê quá độ hoặc làm chậm trễ công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迍', '{"9000": "8902.0", "Chữ Trung Quốc": "迍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 7 | nét | 迍 | dọn | tượng hình | vấp váp, khó khăn trên đường | 迍 là chữ thuộc bộ 辶 (xước, di chuyển). Wiktionary chỉ ghi ''Han etym'' không cung cấp phân tích thành phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dọn\": bộ 辶 gợi bước đi — dọn dẹp chướng ngại, vấp váp trên đường đời gian truân. | Gương Hán-Việt | dọn trong 迍邅 (dọn chiên) — gian truân; liên hệ ''dọn đường'' trong tiếng Việt | Mở khoá kiến thức | Biết 迍 mở khoá điển tích 迍邅 và nhóm từ chỉ gian nan, hoạn nạn trong thơ ca cổ điển.", "Tự nguyên_Xie": "迍 thuộc bộ 辶 (di chuyển), mang nghĩa vấp váp, đi khó khăn, không thuận lợi. Thường gặp trong tổ hợp 迍邅 (dọn chiên) — gặp hoạn nạn, đường đời gian truân. Wiktionary không cung cấp glyph origin. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khó khăn, gian nan, truân chuyên", "Hạng Tần Suất (Jun Da)": "8902.0", "Tần Suất % (Jun Da)": "99.9999731272", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迍", "Unihan_Traditional (Chữ Phồn thể)": "迍", "Pinyin_Xie": "zhūn", "Âm Hán Việt_Xie": "truân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để mô tả hoàn cảnh khó khăn, gập ghềnh trong cuộc sống. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釿', '{"9000": "8903.0", "Chữ Trung Quốc": "釿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 釿 | cân | tượng hình | rìu, búa nhỏ bằng kim loại | 釿 là chữ thuộc bộ 金 (kim, kim loại). Wiktionary xác nhận nghĩa là rìu/búa. Không có phân tích glyph origin thành phần chi tiết từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cân\": bộ 金 gợi kim loại — cân nhắc từng nhát rìu 釿, đẽo gọt cẩn thận từng miếng gỗ. | Gương Hán-Việt | cân trong 釿 — rìu chặt gỗ; liên hệ 斤 (cân) là đơn vị cân nặng, đồng hình với rìu cổ | Mở khoá kiến thức | Biết 釿 mở khoá nhóm từ bộ 金 chỉ dụng cụ chặt đẽo trong nghề thủ công cổ đại.", "Tự nguyên_Xie": "Tiểu triện | 釿 thuộc bộ 金 (kim loại), mang nghĩa rìu nhỏ, công cụ chặt đẽo bằng kim loại. Wiktionary ghi nhận nghĩa ''axe'' và tổ hợp 釿鍔. Có tiểu triện (hanziyuan). Âm Hán-Việt ''cân'' từ Trung cổ âm *kɨn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Yi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "釿", "Unihan_Traditional (Chữ Phồn thể)": "釿", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "cân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ chỉ dụng cụ chặt gỗ hoặc làm lượng từ đo lường thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鏸', '{"9000": "8904.0", "Chữ Trung Quốc": "鏸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 20 | nét | 鏸 | tuệ | tượng hình | sắc bén, mũi nhọn của kim loại | 鏸 là chữ thuộc bộ 金 (kim, kim loại). Wiktionary ghi nhận nhưng không cung cấp phân tích glyph origin (chỉ rfdef). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": bộ 金 gợi kim loại sắc — tuệ sắc như lưỡi dao bén, cắt đứt mọi nghi hoặc. | Gương Hán-Việt | tuệ trong 鏸 — sắc bén; liên hệ 慧 (tuệ) trong 智慧 (trí tuệ) | Mở khoá kiến thức | Biết 鏸 mở khoá nhóm từ bộ 金 chỉ công cụ sắc bén trong văn ngôn và luyện kim cổ.", "Tự nguyên_Xie": "鏸 thuộc bộ 金 (kim loại), có thể mang nghĩa sắc bén, nhọn. Wiktionary ghi phiên âm huì/suì/ruì (Quan thoại) và wai6/jeoi6/seoi6 (Quảng). Không có định nghĩa rõ ràng. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(được sử dụng trong các tên nhất định); giáo ba cạnh", "Hạng Tần Suất (Jun Da)": "8904.0", "Tần Suất % (Jun Da)": "99.9999741607", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鏸", "Unihan_Traditional (Chữ Phồn thể)": "鏸", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "huệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một loại binh khí cổ hoặc làm tính từ trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餟', '{"9000": "8905.0", "Chữ Trung Quốc": "餟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 16 | nét | 餟 | chuyết | tượng hình | tế lễ, rót rượu cúng tế | 餟 là chữ thuộc bộ 食 (thực, ăn uống). Wiktionary ghi nhận ba nghĩa: (1) lập bàn thờ dâng lễ; (2) dị thể của 醊 (rót rượu cúng); (3) dị thể của 啜 (uống, nhấp). Không có phân tích glyph origin. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyết\": bộ 食 gợi thức ăn — chuyết chế lễ vật dâng thần, rót rượu cúng tổ tiên. | Gương Hán-Việt | chuyết trong 餟祭 (chuyết tế) — cúng tế; liên hệ 啜 (xuyết) trong 啜泣 (xuyết khấp) | Mở khoá kiến thức | Biết 餟 mở khoá nhóm từ chỉ cúng tế, lễ nghi thờ phụng trong văn ngôn cổ điển.", "Tự nguyên_Xie": "餟 thuộc bộ 食 (ăn uống), mang nghĩa lập đàn dâng lễ vật cúng tế. Cũng là dị thể của 醊 (rót rượu cúng) và 啜 (uống nhấp). Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''chuyết'' từ Trung cổ âm *tɕuɪt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cúng tế; rưới rượu xuống đất lúc tế lễ", "Hạng Tần Suất (Jun Da)": "8905.0", "Tần Suất % (Jun Da)": "99.9999751943", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餟", "Unihan_Traditional (Chữ Phồn thể)": "餟", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "chuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ nghi thức rưới rượu xuống đất khi cúng tế thần linh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('餫', '{"9000": "8906.0", "Chữ Trung Quốc": "餫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 17 | nét | 餫 | vận | tượng hình | vận chuyển lương thực, cung cấp thực phẩm | 餫 là chữ thuộc bộ 食 (thực, ăn uống). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vận\": bộ 食 (ăn) + vận chuyển — vận lương thực ra tiền tuyến, nuôi quân bách chiến. | Gương Hán-Việt | vận trong 餫輸 (vận thâu) — vận chuyển lương thực; liên hệ 運 (vận) trong 運輸 (vận tải) | Mở khoá kiến thức | Biết 餫 mở khoá nhóm từ chỉ cung ứng lương thực, hậu cần quân sự trong văn ngôn cổ điển.", "Tự nguyên_Xie": "Tiểu triện | 餫 thuộc bộ 食 (ăn uống), mang nghĩa vận chuyển lương thực, cung cấp thực phẩm cho quân đội hoặc nhân dân. Có tiểu triện (wikimedia). Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''vận'' từ Trung cổ âm *wɨnH. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến thể của 餛", "Hạng Tần Suất (Jun Da)": "8906.0", "Tần Suất % (Jun Da)": "99.9999757111", "GavinGrover_Once (Chiết tự trực tiếp)": "飠 + 軍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰飠軍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "軍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "飠", "Unihan_Simplified (Chữ Giản thể)": "餫", "Unihan_Traditional (Chữ Phồn thể)": "餫", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "hồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ một loại bánh bột hấp hoặc bánh vằn thắn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驆', '{"9000": "8907.0", "Chữ Trung Quốc": "驆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 20 | nét | 驆 | bích | tượng hình | ngựa chạy nhanh, tên ngựa | 驆 là chữ thuộc bộ 馬 (mã, ngựa). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": bộ 馬 gợi ngựa — bích ngọc như sắc ngựa quý, chạy nhanh như tia chớp. | Gương Hán-Việt | bích trong 驆 — ngựa chạy nhanh; liên hệ 碧 (bích) trong 碧玉 (bích ngọc) | Mở khoá kiến thức | Biết 驆 mở khoá nhóm từ bộ 馬 chỉ loại ngựa và cách chạy trong văn ngôn cổ điển.", "Tự nguyên_Xie": "驆 thuộc bộ 馬 (ngựa), mang nghĩa liên quan đến ngựa chạy hoặc tên ngựa đặc biệt. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''bích'' từ Trung cổ âm *pɨk. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nương náu, trú", "Hạng Tần Suất (Jun Da)": "8907.0", "Tần Suất % (Jun Da)": "99.9999767447", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 畢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬畢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驆", "Unihan_Traditional (Chữ Phồn thể)": "驆", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động tìm nơi trú ẩn hoặc lánh nạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬳', '{"9000": "8908.0", "Chữ Trung Quốc": "鬳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬲 | Số nét | 16 | nét | 虍 | hổ | biểu âm | hổ (biểu âm) | 鬲 | lịch | biểu nghĩa | nồi ba chân cổ đại (cauldron) | 鬳 là chữ hình thanh (psc): 鬲 (lịch, biểu nghĩa: nồi ba chân cổ) + 虍 (hổ, biểu âm). Wiktionary ghi rõ ls=psc, c2=s (鬲 biểu nghĩa), c1=p (虍 biểu âm). Chữ chỉ loại nồi đặc biệt, là dạng gốc của 甗.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạn\": 鬲 (nồi ba chân) + 虍 (hổ) — ngạn ngữ xưa: chiếc nồi hấp mạnh như hổ, hơi nước bốc lên ngùn ngụt. | Gương Hán-Việt | ngạn trong 鬳 — nồi hấp cổ; liên hệ 甗 (ngạn) trong đồ đồng thời cổ đại | Mở khoá kiến thức | Biết 鬳/甗 mở khoá nhóm từ chỉ đồ đồng cổ đại và kỹ thuật nấu hơi trong khảo cổ học.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 鬳 = 虍 (hổ, biểu âm) + 鬲 (lịch, biểu nghĩa: nồi ba chân). Chữ hình thanh theo Wiktionary (ls=psc). Chỉ loại nồi hơi (甗) dùng để hấp thức ăn. Wiktionary ghi 鬳 là dạng gốc của 甗. Giáp cốt văn và kim văn đều có hình nồi ba chân với phần hơi nước trên. Âm Hán-Việt ''ngạn'' từ Trung cổ âm *ŋɨɑnH. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鬳", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虍 + 鬲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴虍鬲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虍", "Unihan_Simplified (Chữ Giản thể)": "鬳", "Unihan_Traditional (Chữ Phồn thể)": "鬳", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "ngạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại dụng cụ nấu nướng bằng đất nung thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魒', '{"9000": "8909.0", "Chữ Trung Quốc": "魒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鬼 | Số nét | 20 | nét | 魒 | phiêu | tượng hình | hồn ma, bóng ma đơn độc | 魒 là chữ thuộc bộ 鬼 (quỷ, ma quái). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": bộ 鬼 gợi ma quái — phiêu bạt như hồn ma không nơi nương tựa, lang thang nơi tăm tối. | Gương Hán-Việt | phiêu trong 魒 — hồn ma phiêu bạt; liên hệ 飄 (phiêu) trong 漂泊 (phiêu bạt) | Mở khoá kiến thức | Biết 魒 mở khoá nhóm từ bộ 鬼 chỉ linh hồn, ma quái trong văn học và tín ngưỡng dân gian.", "Tự nguyên_Xie": "魒 thuộc bộ 鬼 (ma quái), mang nghĩa hồn ma đơn độc, bóng ma không nơi nương tựa. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''phiêu'' từ Trung cổ âm *pʰjew. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "鬼 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬼票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬼", "Unihan_Simplified (Chữ Giản thể)": "魒", "Unihan_Traditional (Chữ Phồn thể)": "魒", "Pinyin_Xie": "piāo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong thiên văn cổ để chỉ các ngôi sao thuộc chòm sao Bắc Đẩu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盉', '{"9000": "8910.0", "Chữ Trung Quốc": "盉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 10 | nét | 盉 | hòa | tượng hình | bình pha rượu cổ đại, đồ đồng thời Thương Chu | 盉 là chữ độc thể thuộc bộ 皿 (mãnh, đồ đựng). Là tên một loại đồ đồng dùng để pha rượu và nước, phổ biến thời Thương và Chu. Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hòa\": bộ 皿 gợi bình đựng — hòa rượu với nước, pha trộn hài hòa như triết lý trung dung. | Gương Hán-Việt | hòa trong 盉 — bình pha rượu; liên hệ 和 (hòa) trong 和谐 (hài hòa) | Mở khoá kiến thức | Biết 盉 mở khoá nhóm từ chỉ đồ đồng nghi lễ và thuật ngữ khảo cổ thời Thương Chu.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 盉 thuộc bộ 皿 (đồ đựng), chỉ loại bình đồng cổ đại dùng để pha trộn rượu và nước trước khi dâng lễ. Có nhiều mẫu kim văn (hanziyuan), chứng tỏ đây là từ quan trọng trong lễ nghi thời Thương Chu. Wiktionary không cung cấp glyph origin chi tiết. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ấm đồng (hâm nóng rượu)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱禾皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "盉", "Unihan_Traditional (Chữ Phồn thể)": "盉", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hoà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bình đựng rượu bằng đồng thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睱', '{"9000": "8911.0", "Chữ Trung Quốc": "睱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 睱 | hạ | tượng hình | nhìn chằm chằm, mắt trợn lên | 睱 là chữ thuộc bộ 目 (mục, mắt). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạ\": bộ 目 gợi con mắt — hạ xuống nhìn chằm chằm, mắt trợn đỏ như mặt hổ. | Gương Hán-Việt | hạ trong 睱 — mắt trợn nhìn; liên hệ 瞎 (hạ) trong nghĩa mù mắt | Mở khoá kiến thức | Biết 睱 mở khoá nhóm từ bộ 目 chỉ các trạng thái của mắt trong văn ngôn.", "Tự nguyên_Xie": "睱 thuộc bộ 目 (mắt), mang nghĩa nhìn chằm chằm, trợn mắt. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''hạ'' từ Trung cổ âm *ɣˠɛH. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "睱", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睱", "Unihan_Traditional (Chữ Phồn thể)": "睱", "Pinyin_Xie": "xià", "Âm Hán Việt_Xie": "hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động nhìn hoặc liếc mắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睻', '{"9000": "8912.0", "Chữ Trung Quốc": "睻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 睻 | huyên | tượng hình | mắt liếc ngang, nhìn nghiêng | 睻 là chữ thuộc bộ 目 (mục, mắt). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": bộ 目 gợi con mắt — huyên náo xung quanh nhưng mắt liếc ngang quan sát tất cả. | Gương Hán-Việt | huyên trong 睻 — liếc nhìn; liên hệ 宣 (tuyên/huyên) trong 宣告 (tuyên cáo) | Mở khoá kiến thức | Biết 睻 mở khoá nhóm từ bộ 目 chỉ các kiểu nhìn đặc biệt trong văn ngôn cổ điển.", "Tự nguyên_Xie": "睻 thuộc bộ 目 (mắt), mang nghĩa liếc mắt ngang, nhìn nghiêng. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''huyên'' từ Trung cổ âm *xwɛn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "绝", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睻", "Unihan_Traditional (Chữ Phồn thể)": "睻", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả vẻ đẹp của đôi mắt hoặc động từ chỉ việc nhìn rõ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磠', '{"9000": "8913.0", "Chữ Trung Quốc": "磠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 磠 | lỗ | tượng hình | nham thạch thô, đá sạn | 磠 là chữ thuộc bộ 石 (thạch, đá). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": bộ 石 gợi đá — lỗ chỗ như mặt đất đá sạn thô ráp, không bằng phẳng. | Gương Hán-Việt | lỗ trong 磠砟 — đá sỏi thô; liên hệ 鹵 (lỗ) trong 卤水 (nước muối) | Mở khoá kiến thức | Biết 磠 mở khoá nhóm từ bộ 石 chỉ loại đá và khoáng vật trong văn ngôn cổ điển.", "Tự nguyên_Xie": "磠 thuộc bộ 石 (đá), mang nghĩa đất đá thô ráp, sỏi đá. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''lỗ'' từ Trung cổ âm *luX. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "amoniac", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 鹵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石鹵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硵", "Unihan_Traditional (Chữ Phồn thể)": "磠", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi các loại khoáng vật hoặc muối mỏ tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絣', '{"9000": "8914.0", "Chữ Trung Quốc": "絣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 絣 | bính | tượng hình | vải dệt hoa văn sọc, sợi bện | 絣 là chữ thuộc bộ 糸 (mịch, sợi). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": bộ 糸 gợi sợi — bính sợi chặt như bím tóc, dệt thành vải sọc đẹp. | Gương Hán-Việt | bính trong 絣布 (bính bố) — vải dệt sọc; liên hệ 丙 (bính) trong can chi Thiên Can | Mở khoá kiến thức | Biết 絣 mở khoá nhóm từ bộ 糸 chỉ kỹ thuật dệt vải truyền thống trong văn ngôn.", "Tự nguyên_Xie": "絣 thuộc bộ 糸 (sợi), mang nghĩa vải dệt sọc hoặc sợi bện chắc. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''bính'' từ Trung cổ âm *pˠeŋ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thừng; dây thừng; tiếp tục; kéo dài; bện; đan; trói; buộc; ràng; kéo; căng", "Hạng Tần Suất (Jun Da)": "8914.0", "Tần Suất % (Jun Da)": "99.999980879", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "絣", "Unihan_Traditional (Chữ Phồn thể)": "絣", "Pinyin_Xie": "bēng", "Âm Hán Việt_Xie": "băng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động căng dây, buộc chặt hoặc làm danh từ chỉ dây thừng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('縀', '{"9000": "8915.0", "Chữ Trung Quốc": "縀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 縀 | hà | tượng hình | loại vải lụa có hoa văn | 縀 là chữ thuộc bộ 糸 (mịch, sợi). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": bộ 糸 gợi sợi tơ — hà sa lụa mỏng, vải hoa văn óng ánh như ánh mặt trời buổi sáng. | Gương Hán-Việt | hà trong 縀 — vải lụa hoa văn; liên hệ 霞 (hà) trong 晚霞 (ráng chiều) | Mở khoá kiến thức | Biết 縀 mở khoá nhóm từ chỉ các loại vải quý trong văn học và lịch sử trang phục cổ đại.", "Tự nguyên_Xie": "縀 thuộc bộ 糸 (sợi), mang nghĩa loại vải lụa có hoa văn, chất liệu dệt sang trọng. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''hà'' từ Trung cổ âm *ɣˠɛ. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "縀", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "糹 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰糹叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糹", "Unihan_Simplified (Chữ Giản thể)": "縀", "Unihan_Traditional (Chữ Phồn thể)": "縀", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại dây buộc hoặc dải lụa dùng để trang trí, thắt nút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荙', '{"9000": "8916.0", "Chữ Trung Quốc": "荙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荙 | đáp | tượng hình | tên loại cây cỏ | 荙 là chữ thuộc bộ 艸 (thảo, cỏ). Không có phân tích glyph origin từ Wiktionary. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": bộ 艸 gợi cỏ cây — đáp xuống như cây cỏ mọc sát đất, lá xanh đậm lầm lũi. | Gương Hán-Việt | đáp trong 荙 — cây cỏ; liên hệ 答 (đáp) trong 回答 (hồi đáp) | Mở khoá kiến thức | Biết 荙 mở khoá nhóm từ bộ 艸 chỉ các loài cỏ cây trong thực vật học cổ điển.", "Tự nguyên_Xie": "荙 thuộc bộ 艸 (cỏ cây), mang nghĩa tên một loài cây. Wiktionary không cung cấp glyph origin. Âm Hán-Việt ''đáp'' từ Trung cổ âm *dˠɑp. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau điềm", "Hạng Tần Suất (Jun Da)": "8916.0", "Tần Suất % (Jun Da)": "99.9999829461", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荙", "Unihan_Traditional (Chữ Phồn thể)": "薘", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng trong tên gọi của một số loài thực vật thân thảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莕', '{"9000": "8917.0", "Chữ Trung Quốc": "莕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháu | biểu nghĩa | cỏ cây | 杏 | hạnh | biểu âm | cây hạnh nhân (biểu âm) | 莕 là chữ hình thanh (psc): 艸 (tháu, biểu nghĩa: cỏ cây) + 杏 (hạnh, biểu âm). Wiktionary ghi rõ ls=psc. Đây là dạng cổ/dị thể của 荇 (hạnh thái — rau cỏ dưới nước).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạnh\": 艸 (cỏ) + 杏 (hạnh nhân, biểu âm) — hạnh thái xanh mướt trên mặt nước, rau cỏ thơm trong Kinh Thi. | Gương Hán-Việt | hạnh trong 莕菜 (hạnh thái) — rau hạnh dưới nước; 荇 (hạnh) trong Kinh Thi | Mở khoá kiến thức | Biết 莕/荇 mở khoá điển tích Kinh Thi (關雎 — Quan thư) và thực vật học thủy sinh cổ điển.", "Tự nguyên_Xie": "莕 = 艸 (tháu, biểu nghĩa: cỏ cây) + 杏 (hạnh, biểu âm). Wiktionary ghi ls=psc rõ ràng. Là dạng cổ của 荇 (xìng), chỉ cây rau dưới nước (荇菜 — rau hạnh). 荇菜 được nhắc đến trong Kinh Thi. Âm Hán-Việt ''hạnh'' từ Trung cổ âm *ɣˠæŋX. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Nymphoides peltatum", "Hạng Tần Suất (Jun Da)": "8917.0", "Tần Suất % (Jun Da)": "99.9999834629", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 杏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹杏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "杏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莕", "Unihan_Traditional (Chữ Phồn thể)": "莕", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cây sống dưới nước có lá giống lá sen nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('莙', '{"9000": "8918.0", "Chữ Trung Quốc": "莙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 莙 | quân | tượng hình | tên loài cây thủy sinh, rong biển | 莙 là chữ thuộc bộ 艸 (thảo, cỏ cây). Không có phân tích glyph origin từ Wiktionary. Có tiểu triện và liushutong (hanziyuan). Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": bộ 艸 gợi cỏ cây — quân tử như cây 莙 thủy sinh, mọc nơi trong sạch. | Gương Hán-Việt | quân trong 莙荙 — cây thủy sinh; liên hệ 君 (quân) trong 君子 (quân tử) | Mở khoá kiến thức | Biết 莙 mở khoá nhóm từ bộ 艸 chỉ cây thủy sinh trong thực vật học và y học cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 莙 thuộc bộ 艸 (cỏ cây), mang nghĩa tên một loài cây thủy sinh. Có tiểu triện và lục thư thông (hanziyuan). Wiktionary không cung cấp glyph origin chi tiết. Âm Hán-Việt ''quân'' từ Trung cổ âm *kʷɨn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "day quân (có lá xúm xít nhau)", "Hạng Tần Suất (Jun Da)": "8918.0", "Tần Suất % (Jun Da)": "99.9999839797", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 君", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹君", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "君", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "莙", "Unihan_Traditional (Chữ Phồn thể)": "莙", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại thực vật thủy sinh hoặc tảo nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螠', '{"9000": "8919.0", "Chữ Trung Quốc": "螠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螠 | ếch | tượng hình | giun tơ đuôi sống trong bùn cát đáy biển | 螠 là chữ độc thể, không phân tích được thành các thành phần rõ ràng qua nguồn CHISE. Chữ thuộc bộ 虫 (trùng), chỉ các loài sinh vật nhỏ. Dạng chữ phản ánh một loài giun biển đặc biệt, chưa có nguồn phân tích hình-âm rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ếch\": bộ 虫 (trùng) gợi sinh vật nhỏ dưới bùn — hình ảnh con giun tơ đuôi cuộn tròn trong cát biển. | Gương Hán-Việt | ếch trong ngữ cảnh Hán-Việt ít dùng, chủ yếu xuất hiện trong danh pháp sinh học | Mở khoá kiến thức | Biết 螠 mở khoá các từ chỉ động vật không xương sống biển trong văn bản sinh học cổ điển.", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận 螠 là tên phân loại học của lớp Echiura (giun thìa), hoặc dạng thay thế của 縊. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giun tơ đuôi (sống trong bùn cát dưới đáy biển, echiurus uniciuctus.)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螠", "Unihan_Traditional (Chữ Phồn thể)": "螠", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ một loài động vật biển thân mềm không đốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟧', '{"9000": "8920.0", "Chữ Trung Quốc": "蟧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 18 | nét | 虫 | trùng | biểu nghĩa | côn trùng, sinh vật nhỏ | 勞 | lao | biểu âm | 蟧 = 虫 (Trùng, biểu nghĩa: côn trùng) + 勞 (Lao, biểu âm); chữ hình thanh. Phần 虫 cho biết nghĩa liên quan đến sinh vật nhỏ, phần 勞 cho âm đọc gần với láo/lao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\" (theo âm Hán-Việt tương ứng 勞): bộ 虫 (trùng) + 勞 (vất vả) — con cua ẩn sĩ luôn vất vả mang nhà trên lưng đi khắp nơi. | Gương Hán-Việt | lao trong Hán-Việt chưa có từ ghép phổ biến với 蟧 | Mở khoá kiến thức | Biết 蟧 mở khoá từ 蠄蟧 (nhện lớn trong tiếng Quảng) và các từ cổ chỉ giáp xác.", "Tự nguyên_Xie": "Theo Wiktionary, 蟧 là chữ hình thanh: 虫 (biểu nghĩa: côn trùng) kết hợp với 勞 (biểu âm). Nghĩa cổ điển là cua ẩn sĩ (hermit crab) hoặc dạng thay thế của 蟟. Trong tiếng Quảng Đông, 蠄蟧 (kam4 lou4) chỉ con nhện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Gián", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 勞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫勞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟧", "Unihan_Traditional (Chữ Phồn thể)": "蟧", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ dùng để chỉ một số loài côn trùng như gián hoặc ve. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襌', '{"9000": "8921.0", "Chữ Trung Quốc": "襌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 17 | nét | 襌 | thiền | tượng hình | áo đơn, áo mỏng không lót | 襌 không có phân tích CHISE rõ ràng. Wiktionary không cung cấp cấu trúc hình-âm. Chữ thuộc bộ 衣 (y phục), liên quan đến trang phục. Có thể là biến thể cổ hoặc chữ độc lập chỉ áo đơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiền\": bộ 衣 (y phục) gợi tấm áo mỏng — người tu thiền mặc áo đơn giản, không lót vải bên trong, nhẹ nhàng như tâm thiền. | Gương Hán-Việt | thiền trong ''thiền y'' (áo thiền, áo của người tu hành) | Mở khoá kiến thức | Biết 襌 mở khoá từ 襌衣 (áo đơn) và liên hệ với 禅 (thiền định) trong văn bản cổ.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận 襌 nghĩa là áo không lót (unlined garment). Không có phân tích tự hình chi tiết. Dựa vào bộ 衣 (y phục), chữ liên quan đến trang phục nhẹ. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo mỏng; áo đơn", "Hạng Tần Suất (Jun Da)": "8921.0", "Tần Suất % (Jun Da)": "99.99998553", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 單", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襌", "Unihan_Traditional (Chữ Phồn thể)": "襌", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đơn, đan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ loại trang phục mỏng không có lớp lót bên trong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('襽', '{"9000": "8922.0", "Chữ Trung Quốc": "襽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 25 | nét | 襽 | lan | tượng hình | chữ hiếm, bộ 衣 | 襽 không có phân tích CHISE hay Wiktionary. Chữ thuộc bộ 衣 (y phục) với 25 nét, là dạng rất hiếm gặp. Cấu trúc chính xác chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\" (theo âm Hán-Việt phục nguyên từ âm đọc lan): bộ 衣 (y phục) — hình ảnh tấm áo cổ với 25 nét phức tạp, hiếm gặp như hoa lan. | Gương Hán-Việt | lan trong Hán-Việt chưa có từ ghép phổ biến với 襽 | Mở khoá kiến thức | Biết 襽 giúp nhận diện chữ hiếm trong bộ 衣 với cấu trúc phức tạp trong văn bản cổ điển.", "Tự nguyên_Xie": "Không có nguồn Wiktionary hay CHISE cho 襽. Dựa vào bộ 衣 (y phục) và âm đọc lan, đây có thể là một dạng chữ liên quan đến trang phục cổ, nhưng chưa có học thuật xác nhận. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "襽", "Hạng Tần Suất (Jun Da)": "8922.0", "Tần Suất % (Jun Da)": "99.9999860468", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 蘭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤蘭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蘭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "襽", "Unihan_Traditional (Chữ Phồn thể)": "襽", "Pinyin_Xie": "lan", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ phần vạt áo hoặc một loại áo khoác ngoài thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豰', '{"9000": "8923.0", "Chữ Trung Quốc": "豰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 17 | nét | 豰 | bặc | tượng hình | thú vật giống hổ hoặc báo, hoặc giống chó | 豰 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 豕 (lợn/heo), liên quan đến động vật. Wiktionary ghi nhận nghĩa là thú vật cổ giống hổ/báo hoặc con vật giống chó. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bặc\" (phục nguyên từ âm Trung cổ): bộ 豕 (lợn) gợi động vật bốn chân — con thú cổ xưa có bộ lông hai màu, hiếm như chữ 豰 trong từ điển. | Gương Hán-Việt | bặc trong Hán-Việt chưa có từ ghép phổ biến với 豰 | Mở khoá kiến thức | Biết 豰 giúp đọc hiểu các mô tả thú vật trong thư tịch cổ Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 豰 là thú vật cổ giống hổ hoặc báo, hoặc con vật giống chó có nửa trên màu vàng và nửa dưới màu đen. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "heo con; heo nhỏ; lợn con", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 豕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴豕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "豰", "Unihan_Traditional (Chữ Phồn thể)": "豰", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "hốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ dùng trong văn ngôn để chỉ con lợn mới đẻ hoặc còn nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賷', '{"9000": "8924.0", "Chữ Trung Quốc": "賷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 17 | nét | 賷 | tư | tượng hình | mang theo, tặng; dạng thay thế của 齎 | 賷 không có phân tích CHISE rõ ràng. Wiktionary ghi nhận đây là dạng xem thêm (see) của 齎. Chữ thuộc bộ 貝 (bối/tiền tệ). Cấu trúc tự hình chưa được phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\" (theo âm Hán-Việt của 齎): bộ 貝 (của cải) gợi hành động mang theo vật quý — tặng tiền bạc cho người cần. | Gương Hán-Việt | tư trong Hán-Việt chưa có từ ghép phổ biến với 賷 | Mở khoá kiến thức | Biết 賷 giúp nhận diện biến thể của 齎 trong văn bản cổ điển Trung Hoa.", "Tự nguyên_Xie": "Wiktionary ghi nhận 賷 là dạng biến thể/thay thế của 齎 (tư — mang theo, tặng). Thuộc bộ 貝 (tiền, vật quý). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Taki", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 貝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "賷", "Unihan_Traditional (Chữ Phồn thể)": "賷", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ này làm động từ thường đi kèm tân ngữ chỉ đồ vật được mang đi tặng hoặc gửi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鉽', '{"9000": "8925.0", "Chữ Trung Quốc": "鉽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 鉽 | thị | tượng hình | kim loại chưa xác định nghĩa rõ ràng | 鉽 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 金 (kim loại). Wiktionary không cung cấp định nghĩa rõ ràng (rfdef). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\" (phục nguyên từ âm Hán-Việt của shì): bộ 金 (kim loại) — một loại kim loại hoặc vật dụng kim loại chưa rõ danh tính trong từ điển. | Gương Hán-Việt | thị trong Hán-Việt chưa có từ ghép phổ biến với 鉽 | Mở khoá kiến thức | Biết 鉽 giúp nhận diện ký tự hiếm trong bộ 金 khi đọc văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鉽 đọc là shì, thuộc bộ 金 (kim loại), nhưng không có định nghĩa cụ thể (rfdef — cần bổ sung). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "鉽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 式", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金式", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "式", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鉽", "Unihan_Traditional (Chữ Phồn thể)": "鉽", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ dùng trong thuật ngữ hóa học cũ để chỉ nguyên tố Scandi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('錧', '{"9000": "8926.0", "Chữ Trung Quốc": "錧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 16 | nét | 錧 | quản | tượng hình | vật dụng kim loại, nghĩa chưa rõ | 錧 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 金 (kim loại). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quản\" (phục nguyên từ âm Hán-Việt của guǎn): bộ 金 (kim loại) — vật dụng kim loại dạng ống hoặc que, như một ống kim loại trong xưởng thợ. | Gương Hán-Việt | quản trong Hán-Việt chưa có từ ghép phổ biến với 錧 | Mở khoá kiến thức | Biết 錧 giúp nhận diện ký tự hiếm trong bộ 金 khi đọc văn bản kỹ thuật cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 錧 đọc là guǎn, thuộc bộ 金 (kim loại), nhưng không có định nghĩa cụ thể (rfdef — cần bổ sung). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "錌", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 官", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金官", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "官", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "錧", "Unihan_Traditional (Chữ Phồn thể)": "錧", "Pinyin_Xie": "guǎn", "Âm Hán Việt_Xie": "quản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ cái chốt sắt ở đầu trục bánh xe thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍚', '{"9000": "8927.0", "Chữ Trung Quốc": "鍚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 金 | kim | biểu nghĩa | kim loại | 昜 | dương | biểu âm | 鍚 = 金 (Kim, biểu nghĩa: kim loại) + 昜 (Dương, biểu âm); chữ hình thanh. Phần 金 cho biết nghĩa liên quan đến kim loại, phần 昜 cho âm đọc gần với yáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\" (theo âm 昜): 金 (kim loại) + 昜 (dương/ánh sáng) — tấm kim loại trán ngựa lấp lánh dưới ánh mặt trời như ánh dương. | Gương Hán-Việt | dương trong Hán-Việt chưa có từ ghép phổ biến với 鍚 | Mở khoá kiến thức | Biết 鍚 giúp đọc hiểu các mô tả trang bị ngựa chiến trong thư tịch cổ Trung Hoa.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 鍚 là chữ hình thanh: 金 (biểu nghĩa: kim loại) kết hợp với 昜 (biểu âm). Nghĩa là đồ trang trí trán ngựa (frontlet), một vật bằng kim loại gắn trên trán ngựa trong thời cổ đại. Chữ tạo muộn, chỉ thấy trong Lục thư thông (liushutong), chưa tìm thấy trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiếc", "Hạng Tần Suất (Jun Da)": "7538.0", "Tần Suất % (Jun Da)": "99.998602613", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 昜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金昜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "钖", "Unihan_Traditional (Chữ Phồn thể)": "鍚", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ vật trang trí phát ra âm thanh treo trên trán hoặc cổ ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鍱', '{"9000": "8928.0", "Chữ Trung Quốc": "鍱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 17 | nét | 鍱 | diệp | tượng hình | tấm kim loại mỏng | 鍱 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 金 (kim loại). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Theo nghĩa được ghi nhận, chữ liên quan đến tấm kim loại mỏng. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệp\" (phục nguyên từ âm yè — lá, tấm mỏng): bộ 金 (kim loại) — tấm kim loại mỏng như chiếc lá, dùng trong thủ công mỹ nghệ cổ đại. | Gương Hán-Việt | diệp trong Hán-Việt chưa có từ ghép phổ biến với 鍱 | Mở khoá kiến thức | Biết 鍱 giúp đọc hiểu các mô tả kỹ thuật kim loại trong văn bản cổ điển.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鍱 đọc là yè hoặc xié, thuộc bộ 金 (kim loại), nghĩa là tấm kim loại mỏng (thin plates of metal). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vòng; quặng đồng sắt", "Hạng Tần Suất (Jun Da)": "8928.0", "Tần Suất % (Jun Da)": "99.9999896643", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鍱", "Unihan_Traditional (Chữ Phồn thể)": "鍱", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "diệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ này làm danh từ chỉ các lá hoặc tấm kim loại mỏng như đồng, sắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骣', '{"9000": "8929.0", "Chữ Trung Quốc": "骣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 15 | nét | 骣 | sản | tượng hình | ngựa không có yên | 骣 không có phân tích CHISE hay Wiktionary. Chữ thuộc bộ 馬 (mã/ngựa). Không có anchor Wiktionary. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sản\" (phục nguyên từ âm chǎn): bộ 馬 (ngựa) — người kỵ sĩ can đảm cưỡi ngựa không yên, trực tiếp cảm nhận sức mạnh của con ngựa. | Gương Hán-Việt | sản trong Hán-Việt chưa có từ ghép phổ biến với 骣 | Mở khoá kiến thức | Biết 骣 giúp nhận diện thuật ngữ kỵ mã cổ điển trong văn học Trung Hoa.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 骣. Nghĩa ghi nhận là ngựa cưỡi không có yên. Dựa vào bộ 馬 (ngựa) và âm đọc chǎn, đây là chữ mô tả cách cưỡi ngựa bareback (không yên). Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa cưỡi không có yên", "Hạng Tần Suất (Jun Da)": "8929.0", "Tần Suất % (Jun Da)": "99.9999901811", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 孱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马孱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骣", "Unihan_Traditional (Chữ Phồn thể)": "驏", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "sạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Từ này làm tính từ miêu tả trạng thái ngựa không đóng yên hoặc động từ chỉ việc cưỡi ngựa trần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑪', '{"9000": "8930.0", "Chữ Trung Quốc": "鑪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 24 | nét | 金 | kim | biểu nghĩa | kim loại | 盧 | lư | biểu âm | 鑪 = 金 (Kim, biểu nghĩa: kim loại) + 盧 (Lư, biểu âm); chữ hình thanh. Phần 金 cho biết nghĩa liên quan đến kim loại/lò nung, phần 盧 cho âm đọc lú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\" (theo 盧): 金 (kim loại) + 盧 (lư) — lò luyện kim loại, nơi ngọn lửa biến quặng thô thành vàng thau. | Gương Hán-Việt | lư trong ''lư hỏa'' (lửa lò), ''lư đồng'' (lò đồng) | Mở khoá kiến thức | Biết 鑪 mở khoá các từ chỉ lò nung trong văn bản kỹ thuật và thơ cổ Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 鑪 là chữ hình thanh: 金 (biểu nghĩa: kim loại) kết hợp với 盧 (biểu âm). Nghĩa là lò sưởi, bếp lò, lò nung (fireplace, stove, oven, furnace). Có hình trong giáp cốt văn và kim văn, cho thấy đây là chữ cổ xưa liên quan đến kỹ thuật luyện kim. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lò nung", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "金 + 盧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰金盧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "𬬻", "Unihan_Traditional (Chữ Phồn thể)": "鑪", "Pinyin_Xie": "lú", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc làm hậu tố chỉ các loại lò đốt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靷', '{"9000": "8931.0", "Chữ Trung Quốc": "靷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 靷 | dẫn | tượng hình | dây da nối ngựa với xe | 靷 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 革 (da thuộc). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Nghĩa được ghi nhận là dây da nối ngựa với xe. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dẫn\" (phục nguyên từ âm yǐn — dẫn dắt): bộ 革 (da) — sợi dây da 靷 dẫn dắt, nối ngựa với xe, điều khiển hành trình. | Gương Hán-Việt | dẫn trong Hán-Việt chưa có từ ghép phổ biến với 靷 | Mở khoá kiến thức | Biết 靷 giúp đọc hiểu các mô tả trang bị xe ngựa trong thư tịch cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 靷 đọc là yǐn, thuộc bộ 革 (da thuộc), nghĩa là dây da nối ngựa với xe (leather belt connecting a horse with a cart). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây thắng đái", "Hạng Tần Suất (Jun Da)": "8931.0", "Tần Suất % (Jun Da)": "99.9999912147", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 引", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革引", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "引", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靷", "Unihan_Traditional (Chữ Phồn thể)": "靷", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "dẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận dây da nối xe với ngựa để kéo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('騊', '{"9000": "8932.0", "Chữ Trung Quốc": "騊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 18 | nét | 騊 | đào | tượng hình | ngựa hoang loài 騊駼 | 騊 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 馬 (mã/ngựa). Wiktionary chỉ ghi nhận dùng trong từ 騊駼. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đào\" (phục nguyên từ âm táo): bộ 馬 (ngựa) — con ngựa hoang phóng khoáng như đào hoa nở rộ, xuất hiện trong từ cổ 騊駼. | Gương Hán-Việt | đào trong Hán-Việt chưa có từ ghép phổ biến với 騊 | Mở khoá kiến thức | Biết 騊 giúp nhận diện tên loài ngựa hoang trong thư tịch cổ điển Trung Hoa.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary ghi nhận 騊 đọc là táo, thuộc bộ 馬 (ngựa), chỉ dùng trong từ ghép 騊駼 (một loài ngựa hoang). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Cái quạt", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "馬 + 匋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬匋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "騊", "Unihan_Traditional (Chữ Phồn thể)": "騊", "Pinyin_Xie": "táo", "Âm Hán Việt_Xie": "đào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong từ ghép đào đồ để chỉ giống ngựa cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骔', '{"9000": "8933.0", "Chữ Trung Quốc": "骔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 11 | nét | 骔 | tông | tượng hình | lông bờm ngựa; dạng giản thể của 騌 | 骔 là dạng giản thể của 騌 (theo Wiktionary: Han simp). Chữ thuộc bộ 馬 (ngựa). Không có phân tích hình-âm chi tiết qua CHISE. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tông\" (theo âm zōng): bộ 馬 (ngựa) — lông bờm ngựa mọc dọc theo cổ, như từ 鬃 (bờm) nhưng gắn với hình ảnh ngựa. | Gương Hán-Việt | tông trong ''mã tông'' (bờm ngựa), liên hệ với 鬃 (tông — lông bờm) | Mở khoá kiến thức | Biết 骔 mở khoá các từ mô tả ngoại hình ngựa và trang bị kỵ mã trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 骔 là dạng giản thể (Han simp) của 騌, trong đó thành phần 馬 được thay bằng 马. Nghĩa là lông bờm ngựa (mane). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông bờm ngựa", "Hạng Tần Suất (Jun Da)": "8933.0", "Tần Suất % (Jun Da)": "99.999992765", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 宗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马宗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骔", "Unihan_Traditional (Chữ Phồn thể)": "騌", "Pinyin_Xie": "zōng", "Âm Hán Việt_Xie": "tông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần lông dài mọc trên cổ ngựa hoặc bờm của động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魽', '{"9000": "8934.0", "Chữ Trung Quốc": "魽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魽 | hàm | tượng hình | cá hàm, dạng thay thế của 蚶 | 魽 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary ghi nhận là dạng thay thế của 蚶 (hàm — sò huyết). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\" (phục nguyên từ âm hān): bộ 魚 (cá) — con sò huyết miệng mở ra như cái hàm (hàm = hàm răng/miệng), dạng cổ của 蚶. | Gương Hán-Việt | hàm trong ''hàm hầu'' (sò huyết), liên hệ với 蚶 (hàm) | Mở khoá kiến thức | Biết 魽 giúp nhận diện dạng cổ của 蚶 trong văn bản hải sản và ẩm thực cổ đại.", "Tự nguyên_Xie": "Wiktionary ghi nhận 魽 là dạng cổ của 蚶 (hàm — sò huyết). Thuộc bộ 魚 (cá). Xuất hiện trong từ ghép 鰍魽. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "齽", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魽", "Unihan_Traditional (Chữ Phồn thể)": "魽", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài sò hoặc nghêu sò trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魿', '{"9000": "8935.0", "Chữ Trung Quốc": "魿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魿 | linh | tượng hình | loài cá, nghĩa chưa rõ | 魿 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\" (phục nguyên từ âm líng): bộ 魚 (cá) — một loài cá linh hoạt, nhanh nhẹn, hiếm gặp trong từ điển như loài cá trong truyền thuyết. | Gương Hán-Việt | linh trong ''linh ngư'' (cá linh), chưa có từ ghép phổ biến với 魿 | Mở khoá kiến thức | Biết 魿 giúp nhận diện ký tự hiếm trong bộ 魚 khi đọc thư tịch ngư nghiệp cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 魿 đọc là líng hoặc lín, thuộc bộ 魚 (cá), nhưng không có định nghĩa cụ thể (rfdef — cần bổ sung). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "魿", "Unihan_Traditional (Chữ Phồn thể)": "魿", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ dùng để gọi tên một loài cá nước ngọt nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮅', '{"9000": "8936.0", "Chữ Trung Quốc": "鮅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 魚 | ngư | biểu nghĩa | cá | 必 | tất | biểu âm | 鮅 = 魚 (Ngư, biểu nghĩa: cá) + 必 (Tất, biểu âm); chữ hình thanh. Phần 魚 cho biết nghĩa là loài cá, phần 必 cho âm đọc bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\" (theo 必): 魚 (cá) + 必 (nhất định) — con cá 鮅 nhất định sẽ xuất hiện trong ao hồ nước ngọt, thân bạc lấp lánh. | Gương Hán-Việt | tất trong Hán-Việt chưa có từ ghép phổ biến với 鮅 | Mở khoá kiến thức | Biết 鮅 mở khoá các từ chỉ loài cá nước ngọt trong thư tịch ngư nghiệp Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 鮅 là chữ hình thanh: 魚 (biểu nghĩa: cá) kết hợp với 必 (biểu âm, phiên âm bì). Nghĩa là cá chép mắt đỏ (barbel chub, Squaliobarbus curriculus), một loài cá nước ngọt thân dài, đầu tròn, màu xám bạc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cá, thân dài, phần đầu tròn, phần sau dẹp, màu xám bạc, là loài cá nước ngọt.)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 必", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚必", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "必", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮅", "Unihan_Traditional (Chữ Phồn thể)": "鮅", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại cá nước ngọt đầu tròn đuôi dẹt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮇', '{"9000": "8937.0", "Chữ Trung Quốc": "鮇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鮇 | vị | tượng hình | loài cá đầu tròn, vảy tròn nhỏ, da trơn | 鮇 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vị\" (phục nguyên từ âm wèi): bộ 魚 (cá) — loài cá da trơn mềm mại, trơn tuột như cảm giác vị ngon của cá nướng. | Gương Hán-Việt | vị trong Hán-Việt chưa có từ ghép phổ biến với 鮇 | Mở khoá kiến thức | Biết 鮇 giúp nhận diện ký tự hiếm trong bộ 魚 khi đọc thư tịch ngư nghiệp cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鮇 đọc là wèi, thuộc bộ 魚 (cá), nhưng không có định nghĩa cụ thể (rfdef). Nghĩa được ghi nhận là loài cá đầu tròn, vảy tròn nhỏ, da trơn. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại cá, đầu tròn, vảy tròn nhỏ, da trơn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 未", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚未", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "未", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮇", "Unihan_Traditional (Chữ Phồn thể)": "鮇", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt có vảy nhỏ và da trơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鮘', '{"9000": "8938.0", "Chữ Trung Quốc": "鮘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 16 | nét | 鮘 | đãi | tượng hình | loài cá, nghĩa chưa rõ | 鮘 không có phân tích CHISE hay Wiktionary. Chữ thuộc bộ 魚 (ngư/cá). Không có anchor Wiktionary. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\" (phục nguyên từ âm dai): bộ 魚 (cá) — loài cá hiếm, bí ẩn như người khách đang chờ đợi (đãi — chờ đợi), ẩn sâu trong nước. | Gương Hán-Việt | đãi trong Hán-Việt chưa có từ ghép phổ biến với 鮘 | Mở khoá kiến thức | Biết 鮘 giúp nhận diện ký tự cực hiếm trong bộ 魚 khi đọc thư tịch ngư nghiệp cổ.", "Tự nguyên_Xie": "Không có nguồn Wiktionary cho 鮘. Dựa vào bộ 魚 (cá) và âm đọc dai, đây có thể là một loài cá cụ thể trong thư tịch cổ, nhưng chưa có học thuật xác nhận. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Nguyễn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 代", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚代", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "代", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鮘", "Unihan_Traditional (Chữ Phồn thể)": "鮘", "Pinyin_Xie": "dai", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài cá nước ngọt trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鰿', '{"9000": "8939.0", "Chữ Trung Quốc": "鰿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 鰿 | tích | tượng hình | sò nhỏ; dạng thay thế của 鯽 (cá diếc) | 鰿 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary ghi nhận có hai nghĩa cổ điển: sò nhỏ (small cowrie shell) hoặc dạng thay thế của 鯽 (cá diếc). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\" (phục nguyên từ âm jī): bộ 魚 (cá) — dù là sò nhỏ hay cá diếc, 鰿 đều là sinh vật nước nhỏ bé tích lũy thành đàn. | Gương Hán-Việt | tích trong Hán-Việt chưa có từ ghép phổ biến với 鰿 | Mở khoá kiến thức | Biết 鰿 giúp nhận diện biến thể của 鯽 (cá diếc) và từ sò nhỏ trong văn bản cổ.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鰿 có hai nghĩa cổ điển: sò cowrie nhỏ (small cowrie shell) và dạng thay thế của 鯽 (cá diếc). Đọc là jī, jì hoặc jí. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trích; như \"cá trích\" (vhn)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 責", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚責", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "責", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鰿", "Unihan_Traditional (Chữ Phồn thể)": "鰿", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ loài cá trong thư tịch cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱀', '{"9000": "8940.0", "Chữ Trung Quốc": "鱀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 20 | nét | 鱀 | chí | tượng hình | cá heo không vây (finless porpoise) | 鱀 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary ghi nhận nghĩa là cá heo không vây (finless porpoise). Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\" (phục nguyên từ âm jì): bộ 魚 (cá) — con cá heo 白鱀豚 trắng muốt sông Dương Tử, tinh thần chí bền bỉ nhưng đã tuyệt chủng vì môi trường bị phá hủy. | Gương Hán-Việt | chí trong ''bạch chí đồn'' (白鱀豚 — cá heo trắng Dương Tử) | Mở khoá kiến thức | Biết 鱀 mở khoá từ 白鱀豚 và hiểu câu chuyện bảo tồn loài cá heo sông đã tuyệt chủng.", "Tự nguyên_Xie": "Wiktionary ghi nhận 鱀 đọc là jì, thuộc bộ 魚 (cá), nghĩa là cá heo không vây (finless porpoise). Đồng nghĩa với 鱁. Xuất hiện trong từ ghép 白鱀豚 (cá heo trắng sông Dương Tử, nay tuyệt chủng). Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Chí", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "既 + 魚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱既魚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "既", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "𬶨", "Unihan_Traditional (Chữ Phồn thể)": "鱀", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá heo nước ngọt quý hiếm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱄', '{"9000": "8941.0", "Chữ Trung Quốc": "鱄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 22 | nét | 魚 | ngư | biểu nghĩa | cá | 專 | chuyên | biểu âm | 鱄 = 魚 (Ngư, biểu nghĩa: cá) + 專 (Chuyên, biểu âm); chữ hình thanh. Phần 魚 cho biết nghĩa là loài cá, phần 專 cho âm đọc zhuān/chuyên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chuyên\" (theo 專): 魚 (cá) + 專 (chuyên tâm) — loài cá nhỏ 鱄 chuyên sống thành đàn dày đặc, như những chuyên gia trong cùng nghề. | Gương Hán-Việt | chuyên trong Hán-Việt chưa có từ ghép phổ biến với 鱄 | Mở khoá kiến thức | Biết 鱄 mở khoá các từ chỉ cá cơm và cá nhỏ trong thư tịch ngư nghiệp cổ Trung Hoa.", "Tự nguyên_Xie": "Theo Wiktionary, 鱄 là chữ hình thanh: 魚 (biểu nghĩa: cá) kết hợp với 專 (biểu âm). Nghĩa là cá cơm (anchovy) hoặc các loài cá sông nhỏ. Không có phân tích tự hình chi tiết ngoài cấu trúc hình thanh đã xác định. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá (biến nghĩa: cá thu, cá cơm, cá nước ngọt); họ Zhuan", "Hạng Tần Suất (Jun Da)": "8941.0", "Tần Suất % (Jun Da)": "99.9999984496", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 專", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚專", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "專", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鱄", "Unihan_Traditional (Chữ Phồn thể)": "鱄", "Pinyin_Xie": "zhuān", "Âm Hán Việt_Xie": "chuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này dùng làm danh từ chỉ loài cá hoặc làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鱓', '{"9000": "8942.0", "Chữ Trung Quốc": "鱓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 23 | nét | 鱓 | thiện | tượng hình | lươn (eel) | 鱓 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary chỉ ghi {{Han etym}} không có nội dung chi tiết. Có dạng tiểu triện. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\" (phục nguyên từ âm shàn): bộ 魚 (cá) — con lươn 鱓 trơn tuột, thiện (giỏi) trốn thoát khỏi tay người, uốn lượn trong bùn đất. | Gương Hán-Việt | thiện trong ''thiện ngư'' (lươn); liên hệ với 鱔 (lươn — dạng phồn thể phổ biến hơn) | Mở khoá kiến thức | Biết 鱓 mở khoá dạng biến thể của 鱔 (lươn) trong văn bản ẩm thực và y học cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi nhận 鱓 là một chữ thuộc bộ 魚, nghĩa là lươn (eel). Có dạng tiểu triện. Không có phân tích tự hình chi tiết. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "iridi", "Hạng Tần Suất (Jun Da)": "4577.0", "Tần Suất % (Jun Da)": "99.8716569286", "GavinGrover_Once (Chiết tự trực tiếp)": "魚 + 單", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰魚單", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "單", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鳝", "Unihan_Traditional (Chữ Phồn thể)": "鱓", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con lươn, thường dùng trong văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲖', '{"9000": "8943.0", "Chữ Trung Quốc": "鲖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 14 | nét | 鲖 | đồng | tượng hình | cá chuối, cá lóc (snakefish) | 鲖 không có phân tích CHISE rõ ràng. Chữ thuộc bộ 魚 (ngư/cá). Wiktionary không cung cấp định nghĩa cụ thể (rfdef). Có dạng tiểu triện. Cấu trúc tự hình chưa được xác định qua nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\" (phục nguyên từ âm tóng): bộ 魚 (cá) — con cá lóc đồng (đồng = cánh đồng), loài cá nước ngọt quen thuộc sống trong ao hồ đồng bằng. | Gương Hán-Việt | đồng trong ''đồng ngư'' (cá lóc đồng); liên hệ với cá lóc trong ẩm thực Việt Nam | Mở khoá kiến thức | Biết 鲖 giúp nhận diện từ cổ chỉ cá lóc trong thư tịch ngư nghiệp và ẩm thực Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 鲖 là dạng giản thể của 鮦, đọc là tóng, thuộc bộ 魚 (cá). Không có định nghĩa cụ thể trong Wiktionary. Nghĩa ghi nhận là cá chuối/cá lóc (snakefish). Có dạng tiểu triện. Chưa có nguồn học thuật xác nhận cấu trúc tự hình. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chuối, cá lóc", "Hạng Tần Suất (Jun Da)": "8943.0", "Tần Suất % (Jun Da)": "99.9999994832", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲖", "Unihan_Traditional (Chữ Phồn thể)": "鮦", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá quả hoặc dùng trong địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勹', '{"9000": "", "Chữ Trung Quốc": "勹", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình một người vươn cánh tay rất dài để bao bọc, ôm trùm lấy vật gì đó.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㇆㇒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇆", "Unihan_Simplified (Chữ Giản thể)": "勹", "Unihan_Traditional (Chữ Phồn thể)": "勹", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兒', '{"9000": "", "Chữ Trung Quốc": "兒", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Cữu (臼) ở trên, chữ Nhân đi (số 12) ở dưới. Đây là hình ảnh của một em bé sơ sinh (phía trên là cái đầu).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>臼儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "儿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "臼", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('見', '{"9000": "", "Chữ Trung Quốc": "見", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 7 | nét | 目 | mục | biểu nghĩa | mắt | 卩 | tiết | biểu nghĩa | người quỳ gối | 見 là chữ hội ý: 目 (Mục, mắt) + 卩 (Tiết, người quỳ gối). Wiktionary xác nhận ls=ic: ''a kneeling human figure with a large eye for a head''. Hình ảnh người quỳ gối với đôi mắt to — nhấn mạnh hành động nhìn, quan sát. Dạng phồn thể giữ nguyên cấu trúc gốc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 見 (jiàn) là chữ hội ý cổ: 目 (mắt) + 卩 (người quỳ). Wiktionary: hình tượng người quỳ gối với cái đầu là con mắt to — biểu thị hành động nhìn, thấy. Tương tự nhưng không liên quan đến 艮 hay 夏. Cũng đọc xiàn nghĩa ''xuất hiện, để thấy''. Dạng giản thể 见 đơn giản hóa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (54) Nhân (42)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mục (số 54) ở trên, chữ Nhân đi (số 12) ở dưới. Mắt người dùng để nhìn.", "Nghĩa Tiếng Việt_Xie": "tỏ rõ, hiện ra", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>目儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "儿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "见", "Unihan_Traditional (Chữ Phồn thể)": "見", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "kiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ việc nhìn thấy hoặc tiếp kiến ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('規', '{"9000": "", "Chữ Trung Quốc": "規", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 見 | Số nét | 11 | nét | 夫 | phu | biểu nghĩa | người đàn ông trưởng thành | 見 | kiến | biểu nghĩa | nhìn thấy | 規 nguyên gốc là tượng hình — hình ảnh cái compa đo đạc. Sau được phân tích lại thành 夫 (phu) + 見 (kiến), truyền thống coi là hội ý (người đàn ông dùng mắt đo đạc). Tuy nhiên Wiktionary ghi nhận khả năng 夫 là biến thể của âm phù 癸.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 規 nguyên là tượng hình: hình cái compa đo vẽ đường tròn. Về sau được tái phân tích thành 夫 (phu) + 見 (kiến), truyền thống coi là hội ý. Các học giả như Smith (2011) và Chen (2021) tranh luận về thành phần âm phù. Chữ chỉ compa, quy tắc, quy định. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phu (34) Kiến (56)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Phu (số 34) và chữ Kiến (số 56) . Cái nhìn của người đàn ông trưởng thành (phu) bao giờ cũng có phép tắc, hợp với pháp độ.", "Nghĩa Tiếng Việt_Xie": "quy định", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰夫見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ quy luật hoặc làm động từ với nghĩa khuyên răn, vạch định. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姦', '{"9000": "", "Chữ Trung Quốc": "姦", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Ghép bởi 3 chữ Nữ (số 60) . Theo quan niệm xưa, nhiều tính hư tật xấu tụ tập lại thành ra tính gian.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宀', '{"9000": "", "Chữ Trung Quốc": "宀", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Vẽ hình cái mái nhà.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴冖丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "宀", "Unihan_Traditional (Chữ Phồn thể)": "宀", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('習', '{"9000": "", "Chữ Trung Quốc": "習", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 羽 | Số nét | 11 | nét | 羽 | vu | biểu nghĩa | cánh, lông vũ | 日 | nhật | biểu nghĩa | mặt trời, ngày | 習 = 羽 (Vu: cánh) + 日 (Nhật: mặt trời). Chữ hội ý (ic): hình ảnh chim non tập vỗ cánh dưới ánh mặt trời — hành động luyện tập bay. Trong dạng hiện đại 白 thay 日, nhưng hội ý gốc vẫn là tập bay. Wiktionary cũng đề xuất khả năng hình thanh từ 彗 + 日.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary: 習 = 羽 (cánh, biểu nghĩa) + 日 (mặt trời) — hội ý: chim non học bay dưới ánh mặt trời. Trong dạng hiện tại, 日 đã biến thành 白 (trắng). Một giả thuyết khác là hình thanh từ 彗 (âm) + 日 (mặt trời). Có giáp cốt văn, đại triện và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (90) Bạch (88)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vũ (số 90) ở trên chữ Bạch (số 88 - biến thể của chữ Nhật) . Hàng ngày con chim đang vỗ cánh tập bay. Làm đi làm lại nhiều lần cho quen.", "Nghĩa Tiếng Việt_Xie": "học hỏi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>羽白", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "白", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "习", "Unihan_Traditional (Chữ Phồn thể)": "習", "Pinyin_Xie": "xí", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Tính từ | 形容词 | Thường làm động từ chỉ việc ôn luyện hoặc làm danh từ chỉ thói quen, tính từ chỉ sự quen thuộc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朿', '{"9000": "", "Chữ Trung Quốc": "朿", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng những cái gai từ thân cây (Mộc) tua tủa mọc ra.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴木冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "朿", "Unihan_Traditional (Chữ Phồn thể)": "朿", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('來', '{"9000": "", "Chữ Trung Quốc": "來", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Mộc (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có hai chữ Nhân (số 12) ở 2 bên chữ Mộc (số 108) . Cây to bóng mát có rất nhiều người đến ngồi nghỉ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴木从", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "来", "Unihan_Traditional (Chữ Phồn thể)": "來", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('東', '{"9000": "", "Chữ Trung Quốc": "東", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (80) Mộc (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhật (số 80) ở giữa chữ Mộc (số 108) . Phương đông là nơi buổi sáng sớm mặt trời mọc lấp ló sau ngọn cây.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴木日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "东", "Unihan_Traditional (Chữ Phồn thể)": "東", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囗', '{"9000": "", "Chữ Trung Quốc": "囗", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình 4 bức tường vây bọc kín mít. Thường dùng để chứa các chữ khác ở bên trong.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>冂一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "囗", "Unihan_Traditional (Chữ Phồn thể)": "囗", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('無', '{"9000": "", "Chữ Trung Quốc": "無", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (140)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hỏa táng thi thể (phần trên) đặt trên củi, dùng hỏa (4 chấm lửa ở dưới) đốt thành tro bụi, không còn gì cả.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "无", "Unihan_Traditional (Chữ Phồn thể)": "無", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('營', '{"9000": "", "Chữ Trung Quốc": "營", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (140)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Hỏa (số 140) ở trên. Doanh trại lính buổi tối xung quanh đốt lửa để ngăn thú dữ và soi sáng quân địch.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "营", "Unihan_Traditional (Chữ Phồn thể)": "營", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怳', '{"9000": "", "Chữ Trung Quốc": "怳", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Huynh (52)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148 - bộ tâm đứng) và chữ Huynh (số 52) . Tâm trí những đứa em nghịch ngợm rất sợ hãi khi thấy người anh nghiêm khắc.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄兄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恍", "Unihan_Traditional (Chữ Phồn thể)": "怳", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恆', '{"9000": "", "Chữ Trung Quốc": "恆", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Nhị (27) Nguyệt (95)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nguyệt (số 95) nằm giữa chữ Nhị (số 27) và chữ Tâm (số 148) . Tấm lòng như vầng trăng hiện hữu giữa trời đất tượng trưng sự lâu dài.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄亙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恒", "Unihan_Traditional (Chữ Phồn thể)": "恆", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隻', '{"9000": "", "Chữ Trung Quốc": "隻", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 隹 | Số nét | 10 | nét | 隹 | chuy | biểu nghĩa | chim đuôi ngắn | 又 | hựu | biểu nghĩa | bàn tay | 隻 = 隹 (Chuy: chim đuôi ngắn) + 又 (Hựu: bàn tay); chữ hội ý. Một bàn tay cầm một con chim — đó là một cái (chiếc lẻ). Khi cầm hai chim thì thành 雙 (song). Chữ có lịch sử phong phú từ giáp cốt văn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Tiểu triện | Theo Wiktionary, 隻 là chữ hội ý: 隹 (chim đuôi ngắn) + 又 (bàn tay). Cầm một con chim = một chiếc. Đối lập với 雙 (cầm hai chim = đôi). Chữ có mặt từ giáp cốt văn (giáp cốt khắc trên xương), rất nhiều dạng oracle bone. Chức năng hiện đại: lượng từ cho vật đơn chiếc hoặc động vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chuy (175) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chuy (số 175) trên chữ Hựu (số 159) . Bàn tay cầm một con chim giơ lên bảo đây là một con (lượng từ chỉ 1).", "Nghĩa Tiếng Việt_Xie": "chiếc, cái; đơn chiếc, lẻ loi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>隹又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "chiếc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Tính từ | 形容词 | Thường làm lượng từ đứng trước danh từ chỉ động vật hoặc đồ vật đi đôi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雙', '{"9000": "", "Chữ Trung Quốc": "雙", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 隹 | Số nét | 18 | nét | 雔 | biểu nghĩa | hai con chim | 又 | hựu | biểu nghĩa | bàn tay phải | 雙 = 雔 (hai con chim 隹) + 又 (Hựu — bàn tay). Chữ hội ý: hình ảnh hai con chim nằm trong lòng bàn tay — diễn tả ''một đôi''. Chữ hội ý (ic).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 雙 là chữ hội ý, gồm 雔 (hai con chim 隹) và 又 (bàn tay phải). Hình ảnh: hai con chim trong lòng bàn tay của một người — biểu thị ''đôi'', ''cặp''. Cấu trúc này rất trực quan và cổ xưa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chuy (175) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Chuy (số 175) trên chữ Hựu (số 159) . Bàn tay cầm hai con chim giơ lên bảo đây là một đôi (lượng từ chỉ 2).", "Nghĩa Tiếng Việt_Xie": "đôi", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>雔又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "又", "Unihan_Simplified (Chữ Giản thể)": "双", "Unihan_Traditional (Chữ Phồn thể)": "雙", "Pinyin_Xie": "shuāng", "Âm Hán Việt_Xie": "song", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Tính từ | 形容词 | Số từ | 数词 | Chữ này thường dùng làm lượng từ cho các vật đi liền thành cặp hoặc làm tính từ chỉ số chẵn. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聶', '{"9000": "", "Chữ Trung Quốc": "聶", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 耳 | Số nét | 18 | nét | 耳 | nhĩ | biểu nghĩa | tai — ba tai ghép lại | 耳 | nhĩ | biểu nghĩa | tai | 耳 | nhĩ | biểu nghĩa | tai | 聶 = ba chữ 耳 (Nhĩ) ghép lại; chữ hội ý. Ba cái tai tượng trưng cho hành động thì thầm vào tai nhau. Đây là cấu trúc tam thể đặc trưng của chữ Hán cổ.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Theo Wiktionary, 聶 là chữ hội ý: ba chữ 耳 (tai) ghép lại ({{zh-etym-triple|耳|ear}}). Ba tai gợi hình ảnh người thì thầm vào tai, nói chuyện kín. Nghĩa: thì thầm (vào tai), và dùng làm họ (họ Niếp). Nhạc sĩ Niếp Nhĩ (聶耳) nổi tiếng thời cận đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhĩ (186)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Ba chữ Nhĩ (số 186) xếp trồng lên nhau. Nhiều tai tụm kề nhau chú ý để nghe người khác nói nhỏ.", "Nghĩa Tiếng Việt_Xie": "nói thầm; thịt thái mỏng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "聂", "Unihan_Traditional (Chữ Phồn thể)": "聶", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động ghé sát tai nói nhỏ hoặc thì thầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恥', '{"9000": "", "Chữ Trung Quốc": "恥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhĩ (186) Tâm (148)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhĩ (số 186) và chữ Tâm (số 148) . Vành tai (nhĩ) bên ngoài nóng đỏ lên bởi trong lòng (tâm) có điều hổ thẹn.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "耻", "Unihan_Traditional (Chữ Phồn thể)": "恥", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('車', '{"9000": "", "Chữ Trung Quốc": "車", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 7 | nét | 車 | xa | tượng hình | xe — hình tượng xe nhìn từ trên xuống | 車 là chữ tượng hình độc thể — nhìn từ trên xuống thấy trục xe, hai bánh, và thùng xe. Không có thành phần biểu âm hay biểu nghĩa riêng biệt. Là bộ thủ của chính nó.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 車 là chữ tượng hình nổi tiếng: giáp cốt văn và kim văn vẽ hình xe từ trên nhìn xuống — hai bánh, một trục, một thùng xe. Là một trong những chữ cổ nhất tiếng Hán. Tiểu triện vuông hóa dần mất hình ban đầu. Wiktionary xác nhận đây là pictograph của xe ngựa thời cổ đại Trung Quốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Vẽ hình cái xe có bánh, thùng xe và càng xe thời cổ đại.", "Nghĩa Tiếng Việt_Xie": "cái xe", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "车", "Unihan_Traditional (Chữ Phồn thể)": "車", "Pinyin_Xie": "chē", "Âm Hán Việt_Xie": "xa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ phương tiện giao thông hoặc làm lượng từ để đếm số chuyến xe hàng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轟', '{"9000": "", "Chữ Trung Quốc": "轟", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 21 | nét | 車 | xa | tượng hình lặp | xe — ba xe chồng lên nhau biểu thị tiếng ầm | 轟 là chữ hội ý: ba chữ 車 (xa, xe) xếp chồng nhau, mô phỏng tiếng ầm ầm của nhiều xe lăn hoặc tiếng bom nổ. Không có bộ phận biểu âm riêng.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 轟 (huênh) được cấu tạo từ ba chữ 車 (xe) theo Wiktionary: {{zh-etym-triple|車|cart}}. Ba chiếc xe xếp chồng gợi tiếng động lớn, ầm vang — tiếng ầm của bánh xe lăn hay tiếng nổ. Đây là chữ hội ý tượng thanh đặc trưng, ghi nhận từ thời Trung Cổ (Middle Chinese). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (191)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Ba chữ Xa (số 191) xếp chồng lên nhau. Chỉ ý đoàn xe đang chạy ầm ầm vang dội.", "Nghĩa Tiếng Việt_Xie": "nổ (sấm); thuốc nổ; quát; vang lừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "轰", "Unihan_Traditional (Chữ Phồn thể)": "轟", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "huênh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng nổ lớn hoặc động từ chỉ hành động oanh tạc. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('軍', '{"9000": "", "Chữ Trung Quốc": "軍", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 車 | Số nét | 9 | nét | 車 | xa | biểu nghĩa | xe, chiến xa | 勹 | biểu âm | bao vây (âm gốc cổ) | 軍 là chữ hình thanh (liushu: psc theo Wiktionary, dù Thuyết Văn Giải Tự diễn giải là hội ý): 車 (xa — chiến xa) là phần biểu nghĩa; 勹 là phần biểu âm gốc (không phải 勹 hiện đại mà là dạng gốc của 螾). Shuowen diễn giải là hội ý (xe + bao vây) nhưng phân tích hiện đại xác nhận hình thanh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | Theo Wiktionary, 軍 là chữ hình thanh: 車 (xa — chiến xa, biểu nghĩa) + 勹 (biểu âm, vốn là dạng gốc của 螾 — cùng họ âm với 旬, 勻, 云). Thuyết Văn Giải Tự đọc là hội ý (xe + bao vây = quân đội), nhưng phân tích hiện đại xác nhận đây là hình thanh. Nghĩa gốc: quân đội, binh lính. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mịch Xa (191)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mịch (trùm lên) ở trên chữ Xa (số 191) . Quân đội thời xưa thường dùng chiến xa bao vây quân địch mà đánh.", "Nghĩa Tiếng Việt_Xie": "quân, binh lính", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>冖車", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "車", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "军", "Unihan_Traditional (Chữ Phồn thể)": "軍", "Pinyin_Xie": "jūn", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ lực lượng vũ trang hoặc làm định ngữ bổ nghĩa cho các danh từ liên quan đến quân sự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斬', '{"9000": "", "Chữ Trung Quốc": "斬", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xa (191) Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Xa (số 191) và chữ Cân (số 196) . Xưa tội phạm bị giết bằng xe cán nát hoặc rìu (cân) chặt đầu (trảm).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰車斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "車", "Unihan_Simplified (Chữ Giản thể)": "斩", "Unihan_Traditional (Chữ Phồn thể)": "斬", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('門', '{"9000": "", "Chữ Trung Quốc": "門", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 8 | nét | 門 | môn | tượng hình | cái cổng hai cánh | 門 là chữ tượng hình độc lập, mô tả hình dạng cái cổng hai cánh. So sánh với 戶 (hộ: một cánh cửa) — 門 là cổng hai cánh đầy đủ. Không phân tách thành bộ phận nhỏ hơn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | 門 là chữ tượng hình: hình vẽ cổng hai cánh. Wiktionary xác nhận 門 là pictograph (liushu: p). So sánh với 戶 là một cánh cửa đơn — 門 = hai cánh 戶 ghép lại. Giáp cốt văn đã có hình dạng cổng hai cánh rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh cái cánh cổng lớn (có 2 cánh).", "Nghĩa Tiếng Việt_Xie": "cái cửa; loài, loại, thứ, môn", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𠁣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "门", "Unihan_Traditional (Chữ Phồn thể)": "門", "Pinyin_Xie": "mén", "Âm Hán Việt_Xie": "môn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ lối ra vào hoặc làm lượng từ cho môn học, kỹ năng, pháo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('問', '{"9000": "", "Chữ Trung Quốc": "問", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Môn (199) Khẩu (6)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khẩu (số 6) nằm trong chữ Môn (số 199) . Đi tới cổng phải mở miệng hỏi to lên xem có ai ở nhà không (Vấn). Giải thích sự chuyển ý: Chữ Môn (cửa) chỉ âm, chữ Khẩu (miệng) chỉ ý. Người đứng ngoài cửa (Môn) dùng miệng (Khẩu) để gọi vào thăm hỏi, chất vấn (Vấn). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Môn và chữ Vấn có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Môn và Vấn).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰門口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "问", "Unihan_Traditional (Chữ Phồn thể)": "問", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('間', '{"9000": "", "Chữ Trung Quốc": "間", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 12 | nét | 門 | môn | biểu nghĩa | cửa | 日 | nhật | biểu nghĩa | mặt trời, ngày | 間 là chữ hội ý (ic): 門 (Môn, cửa) + 日 (Nhật, mặt trời). Ánh sáng mặt trời lọt qua khe cửa — hình ảnh gợi nghĩa kẽ hở, khoảng trống. Đây là biến thể của 閒 (nhàn/gian) với 月 (trăng) thay bằng 日 (mặt trời).", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Đại triện | Tiểu triện | 間 (gian) theo Wiktionary là biến thể của 閒, với 月 (trăng) thay bằng 日 (mặt trời): ''Variant form of 閒 with 月 replaced by 日.'' Cả hai đều miêu tả ánh sáng lọt qua khe cửa — ban đêm là ánh trăng (閒), ban ngày là ánh mặt trời (間). Nghĩa gốc là kẽ hở, khoảng trống; mở rộng thành chia rẽ, xen vào giữa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhật (80) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhật (số 80) ở trong chữ Môn (số 199) . Cửa đã khép mà ánh sáng (nhật) vẫn lọt vào, giữa hai cánh cửa có khe hở (gián/gian).", "Nghĩa Tiếng Việt_Xie": "kẽ hở, lỗ hổng; chia rẽ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "间", "Unihan_Traditional (Chữ Phồn thể)": "間", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "gián, gian, nhàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ không gian, từ chỉ phương vị hoặc lượng từ cho phòng ốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悶', '{"9000": "", "Chữ Trung Quốc": "悶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148) ở trong chữ Môn (số 199) . Tấm lòng (tâm) người mẹ tựa cửa (môn) ngóng đợi con trở về, chỉ sự buồn rầu. Giải thích sự chuyển ý: Chữ Môn (cửa) chỉ âm, chữ Tâm (lòng) chỉ ý. Lòng (Tâm) như bị giam lỏng, bức bối bên trong cánh cửa (Môn) sinh ra cảm giác buồn chán (Muộn). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Môn và chữ Muộn có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Môn và Muộn).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闷", "Unihan_Traditional (Chữ Phồn thể)": "悶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閏', '{"9000": "", "Chữ Trung Quốc": "閏", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 12 | nét | 門 | môn | cổng | 王 | vương | vua | 閏 = 門 (Môn, cổng) + 王 (Vương, vua); chữ hội ý. Vua ở lại trong cổng vào ngày nhuận — hình ảnh nhà vua nghỉ lại trong cung điện vào ngày dư thừa của âm lịch.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 閏 là chữ hội ý: 門 (môn, cổng) + 王 (vương, vua). Nghĩa gốc \"nhuận\" (tháng/ngày nhuận) xuất phát từ tập tục cổ đại: vua ở lại trong cung điện (không ra khỏi cổng) vào ngày dư thừa của âm lịch 364 ngày, vì ngày đó vượt quá chu kỳ thông thường. Từ đó mở rộng nghĩa \"thừa ra\", \"thêm vào\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vương (137) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vương (số 137) ở trong chữ Môn (số 199) . Tháng nhuận ông vua ở riêng một mình đóng kín cửa để tĩnh dưỡng. Giải thích sự chuyển ý: Chữ Vương (vua) chỉ âm, chữ Môn (cửa) chỉ ý. Ngày xưa vào tháng nhuận, vua (Vương) thường đứng ở cửa (Môn) minh đường để làm việc thay vì vào chính điện. *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Vương và chữ Nhuận có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Vương và Nhuận).*", "Nghĩa Tiếng Việt_Xie": "xen vào giữa, thừa ra; nhuận (lịch)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闰", "Unihan_Traditional (Chữ Phồn thể)": "閏", "Pinyin_Xie": "rùn", "Âm Hán Việt_Xie": "nhuận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ chỉ thời gian như năm hoặc tháng để chỉ sự dư thừa, nhuận. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聞', '{"9000": "", "Chữ Trung Quốc": "聞", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 耳 | Số nét | 14 | nét | 門 | môn | biểu âm | cho âm | 耳 | nhĩ | biểu nghĩa | tai | 聞 = 門 (Môn, biểu âm) + 耳 (Nhĩ, biểu nghĩa: tai); chữ hình thanh. 耳 xác định lớp nghĩa (liên quan đến tai — nghe), 門 cung cấp âm. Hình ảnh con tai đặt sau cánh cửa — lắng nghe qua cửa.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Tiểu triện | 聞 theo Wiktionary là chữ hình thanh: 門 biểu âm, 耳 biểu nghĩa. Hình ảnh gợi lên: cái tai (耳) sau khung cửa (門) — lắng nghe, nghe lén. Nghĩa gốc là nghe; mở rộng sang ngửi, tin tức, danh tiếng. Wiktionary cũng so sánh với 問 (hỏi) — cùng âm gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhĩ (186) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhĩ (số 186) ở trong chữ Môn (số 199) . Cái tai (nhĩ) đang ghé vào khe cửa (môn) để nghe chuyện của người khác.", "Nghĩa Tiếng Việt_Xie": "tiếng động tới, tiếng truyền tới", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闻", "Unihan_Traditional (Chữ Phồn thể)": "聞", "Pinyin_Xie": "wén", "Âm Hán Việt_Xie": "vấn, vặn, văn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc nghe hoặc ngửi, hoặc làm danh từ chỉ tin tức và tiếng tăm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閂', '{"9000": "", "Chữ Trung Quốc": "閂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (1) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có nét ngang (chữ Nhất - 1 ) ở trong chữ Môn (số 199) . Hình ảnh cái then cài ngang qua hai cánh cửa đã khép chặt.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "一", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闩", "Unihan_Traditional (Chữ Phồn thể)": "閂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廾', '{"9000": "", "Chữ Trung Quốc": "廾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh hai cánh tay đang chắp lại với nhau.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: msp", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "廾", "Unihan_Traditional (Chữ Phồn thể)": "廾", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('開', '{"9000": "", "Chữ Trung Quốc": "開", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 12 | nét | 門 | môn | biểu nghĩa | cửa | 一 | nhất | biểu nghĩa | thanh chốt cửa | 廾 | trấp | biểu nghĩa | hai bàn tay | 開 là chữ hội ý: 門 (Môn, cánh cửa) + 一 (Nhất, thanh chốt/then cài) + 廾 (Trấp, hai bàn tay). Wiktionary xác nhận ls=ic: ''a pair of hands opening a latched door''. Cảnh tượng hai bàn tay nhấc chốt cửa để mở ra. Từ tiểu triện, 一 và 廾 nhập thành 开. Dạng phồn thể giữ nguyên cấu trúc gốc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | 開 (kāi) là chữ hội ý cổ: 門 (cánh cửa) + 一 (thanh chốt) + 廾 (hai bàn tay). Wiktionary: hai bàn tay mở cánh cửa có chốt. Từ thời tiểu triện, 一 và 廾 nhập lại thành 开 trong giản thể. Dạng phồn thể 開 bảo tồn đầy đủ cấu tạo gốc. Đây là hội ý thuần túy, không có thành phần phonetic. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Môn (199) Củng (207) Nhất (1)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Môn , chữ Củng và nét Nhất (Xuyên). Đôi tay (củng) đang kéo mở cái then cài cửa (nhất) ở cánh cổng (môn).", "Nghĩa Tiếng Việt_Xie": "mở", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門开", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "开", "Unihan_Traditional (Chữ Phồn thể)": "開", "Pinyin_Xie": "kāi", "Âm Hán Việt_Xie": "khai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Trợ từ | 助词 | Chữ này thường làm động từ chỉ hành động mở ra, bắt đầu hoặc làm bổ ngữ xu hướng chỉ trạng thái mở rộng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('閉', '{"9000": "", "Chữ Trung Quốc": "閉", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 門 | Số nét | 11 | nét | 門 | môn | biểu nghĩa | cửa | 才 | tài | biểu nghĩa | cây gỗ, vật liệu (rút gọn của 材) | 閉 = 門 (Môn: cửa) + 才 (dạng rút gọn của 材, Tài: gỗ/vật liệu). Chữ hội ý (ic): cửa được chặn bằng thanh gỗ — hành động đóng cửa, ngăn lại. Có kim văn, tiểu triện và lục thư thông.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary: 閉 = 門 (cửa, biểu nghĩa) + 材 rút gọn (gỗ/vật liệu, biểu nghĩa). Hội ý: cửa được chèn bằng gỗ để khóa lại. Nghĩa gốc là đóng/khép cửa, mở rộng sang bít kín, tắc nghẽn. Có kim văn, tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tài (214) Môn (199)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tài (số 214) nằm trong chữ Môn (số 199) . Đưa tay (Tài ở đây mượn ý nghĩa bàn tay) đóng kín hai cánh cửa lại.", "Nghĩa Tiếng Việt_Xie": "đóng, khép (cửa); nhắm (mắt); ngậm; bế tắc, bí; che, đậy", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴門才", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "才", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "門", "Unihan_Simplified (Chữ Giản thể)": "闭", "Unihan_Traditional (Chữ Phồn thể)": "閉", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động đóng cửa, nhắm mắt hoặc làm tính từ chỉ trạng thái tắc nghẽn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亠', '{"9000": "", "Chữ Trung Quốc": "亠", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (1)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ chỉ sự, có dấu chấm ở trên chữ Nhất (số 1) , chỉ ý rằng đứng ở trên đỉnh đầu.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴一丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "亠", "Unihan_Traditional (Chữ Phồn thể)": "亠", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬥', '{"9000": "", "Chữ Trung Quốc": "鬥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vương (137)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Có hai chữ Vương (số 137) và hai nét sổ. Hai ông vua mỗi người cầm một gậy đánh nhau tranh giành đất đai, công lý.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴𩰋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬧', '{"9000": "", "Chữ Trung Quốc": "鬧", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鬥 | Số nét | 15 | nét | 鬥 | đấu | biểu nghĩa | đánh nhau, tranh đấu | 市 | thị | biểu nghĩa | chợ, thị trường | 鬧 = 鬥 (Đấu, biểu nghĩa: đánh nhau) + 市 (Thị, biểu nghĩa: chợ). Chữ hội ý (ic): cảnh chợ (市) ồn ào náo nhiệt như đánh nhau (鬥) — hợp nghĩa ''ồn ào, huyên náo''.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 鬧 là chữ hội ý (ic): 鬥 (đấu, đánh nhau) + 市 (thị, chợ). Wiktionary giải thích: chợ ồn ào như cảnh tranh đấu — noisy. Hán-Việt ''náo'' xuất phát từ Trung cổ âm *nˤaw-s. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thị (226) Đấu (228)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thị (số 226) ở trong chữ Đấu (số 228) . Chợ (thị) là nơi đông người, có đám đánh nhau (đấu) thì rất ồn ào náo nhiệt.", "Nghĩa Tiếng Việt_Xie": "ồn ào", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴鬥市", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "市", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鬥", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "nào", "Âm Hán Việt_Xie": "náo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ sự ồn ào hoặc làm động từ chỉ hành động gây rối, làm loạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掃', '{"9000": "", "Chữ Trung Quốc": "掃", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (189) Trửu (230)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủ (số 213 - bộ gảy tay 扌) và chữ Trửu (số 230) . Tay cầm cái chổi (trửu) để làm việc quét dọn. Giải thích sự chuyển ý: Chữ Trửu (cái chổi) chỉ âm, chữ Thủ (tay) chỉ ý. Tay (Thủ) cầm cái chổi (Trửu) để làm vệ sinh, quét dọn (Tảo). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Trửu và chữ Tảo có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Trửu và Tảo).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌帚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扫", "Unihan_Traditional (Chữ Phồn thể)": "掃", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婦', '{"9000": "", "Chữ Trung Quốc": "婦", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Trửu (230)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nữ (số 60) và chữ Trửu (số 230) . Người con gái tay cầm chổi quét nhà (việc gia đình) chỉ người đã có chồng. Giải thích sự chuyển ý: Chữ Trửu (cái chổi) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Hình ảnh người phụ nữ (Nữ) cầm chổi (Trửu) quét dọn nhà cửa, tượng trưng cho người vợ (Phụ). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Trửu và chữ Phụ có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Trửu và Phụ).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女帚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妇", "Unihan_Traditional (Chữ Phồn thể)": "婦", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('協', '{"9000": "", "Chữ Trung Quốc": "協", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thập (2) Lực (233)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thập (số 16) và ba chữ Lực (số 233) . Hợp sức của mười người (hay rất nhiều người) lại với nhau gọi là hiệp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰十劦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "协", "Unihan_Traditional (Chữ Phồn thể)": "協", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('動', '{"9000": "", "Chữ Trung Quốc": "動", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trọng (174) Lực (233)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trọng (số 192) và chữ Lực (số 233) . Dùng sức lực đẩy cái xe rất nặng (trọng) làm cho nó chuyển động. Giải thích sự chuyển ý: Chữ Trọng (nặng) chỉ âm, chữ Lực (sức mạnh) chỉ ý. Dùng sức lực (Lực) để nhấc một vật nặng (Trọng) làm cho nó di chuyển (Động). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Trọng và chữ Động có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Trọng và Động).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰重力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "动", "Unihan_Traditional (Chữ Phồn thể)": "動", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貝', '{"9000": "", "Chữ Trung Quốc": "貝", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 7 | nét | 貝 | buổi | tượng hình | vỏ sò — tiền tệ cổ đại | 貝 là tượng hình độc lập: hình vẽ vỏ sò cowrie (贝壳) — được dùng làm tiền tệ ở Trung Hoa cổ đại. Chữ tự thân là bộ thủ của hàng chục chữ liên quan đến tài chính và giá trị.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary ({{liushu|p}}): tượng hình vỏ sò cowrie dùng làm tiền tệ cổ đại Trung Hoa. Không liên quan đến dạng gốc của 則. Vỏ sò cowrie là hàng hóa tiền tệ phổ biến trước khi đúc tiền kim loại. Phồn thể 貝 tương ứng giản thể 贝. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình cái vỏ con trai, con sò. Người xưa dùng vỏ trai sò làm đơn vị tiền tệ nên Bối có nghĩa là tiền tài.", "Nghĩa Tiếng Việt_Xie": "con sò, hến; vật quý; tiền tệ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>目八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "八", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "贝", "Unihan_Traditional (Chữ Phồn thể)": "貝", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loài sò hoặc dùng làm bộ thủ liên quan đến tiền tài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貞', '{"9000": "", "Chữ Trung Quốc": "貞", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 9 | nét | 貞 | trinh | tượng hình | vạc đỉnh đồng, mượn âm chỉ sự trinh tiết/bói toán | 貞 là chữ tượng hình (liushu: p — pictograph): hình dạng ban đầu là chiếc đỉnh đồng (ding). Không phải chữ hội ý hay hình thanh. Về sau mượn âm để chỉ \"bói toán\" rồi \"trinh tiết\".", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 貞 ban đầu là hình vẽ một chiếc đỉnh đồng — cùng gốc với 鼎 trong giáp cốt văn và kim văn. Chữ được mượn âm để chỉ hành động \"bói toán\" (vì đỉnh đồng thường dùng trong nghi lễ bói). Sau đó phát sinh nghĩa phái sinh \"trung trinh, tiết hạnh\". Thêm bộ 卜 (bốc — bói) tạo chữ mới; dạng 貞 còn lại mang nghĩa đạo đức. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bốc (105) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bốc (số 105) ở trên chữ Bối (số 241) . Khi đi xem bói (bốc) thì phải dùng tiền bạc (bối) để gieo quẻ.", "Nghĩa Tiếng Việt_Xie": "trong trắng, tiết hạnh; trung thành", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>⺊貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺊", "Unihan_Simplified (Chữ Giản thể)": "贞", "Unihan_Traditional (Chữ Phồn thể)": "貞", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ phẩm chất trung trinh, tiết hạnh của con người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('員', '{"9000": "", "Chữ Trung Quốc": "員", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khẩu (số 6) ở trên chữ Bối (số 241) . Hình ảnh một đồng tiền (bối) có một cái lỗ (khẩu) để xâu dây. Dùng làm lượng từ đếm.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>口貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "员", "Unihan_Traditional (Chữ Phồn thể)": "員", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('賀', '{"9000": "", "Chữ Trung Quốc": "賀", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 12 | nét | 加 | gia | biểu âm | 貝 | bối | biểu nghĩa | vỏ sò, tiền, của quý | 賀 = 加 (Gia, biểu âm) + 貝 (Bối, biểu nghĩa: vỏ sò/tiền/của quý); chữ hình thanh. Phần 貝 gợi việc tặng quà có giá trị, phần 加 cho âm đọc gốc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Bạch thư | Tiểu triện | 賀 là chữ hình thanh: 加 (gia, biểu âm) + 貝 (bối, biểu nghĩa của quý/tiền). Ý gốc là tặng quà có giá trị để chúc mừng. Dạng kim văn, bạch thư và tiểu triện đều lưu lại. Kinh Thi đã dùng 賀 với nghĩa chúc mừng từ bốn phương. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Gia (73) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Gia (số 234) ở trên chữ Bối (số 241) . Đem thêm (gia) lễ vật, tiền bạc (bối) đến chúc mừng để làm tăng niềm vui. Giải thích sự chuyển ý: Chữ Gia (nhà) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Đem tiền bạc, quà cáp (Bối) đến nhà (Gia) người khác để chia vui, chúc mừng (Hạ). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Gia và chữ Hạ có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Gia và Hạ).*", "Nghĩa Tiếng Việt_Xie": "Chúc mừng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>加貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贺", "Unihan_Traditional (Chữ Phồn thể)": "賀", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ bày tỏ niềm vui, chúc mừng nhân dịp hỷ sự. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('實', '{"9000": "", "Chữ Trung Quốc": "實", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (68) Vô Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Miên (mái nhà) , chữ Vô (không) và chữ Bối (tiền) . Theo quan niệm xưa, kẻ sống đời liêm khiết thật thà thì trong nhà không có tiền của.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>宀貫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "实", "Unihan_Traditional (Chữ Phồn thể)": "實", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('質', '{"9000": "", "Chữ Trung Quốc": "質", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 15 | nét | 斦 | hai cái rìu | 貝 | bối | vỏ sò — tiền tệ cổ | 質 = 斦 (hai cái rìu) + 貝 (Bối: vỏ sò/tiền tệ cổ). Chữ hội ý (ic): hai rìu (斦) đặt lên đồ vật giá trị (貝) có thể hiểu là cầm cố, thế chấp. Học giả Chu Tuấn Thanh cũng gợi ý hình thanh (斦 biểu âm), nhưng thuyết hội ý phổ biến hơn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 質 là chữ hội ý: 斦 (hai cái rìu) + 貝 (vỏ sò — tiền tệ cổ). Nghĩa gốc: cầm cố, thế chấp (dùng hai rìu đặt bên tiền/vật quý để đảm bảo). Từ đó mở rộng sang: chất lượng, bản chất, vật chất, chất vấn. Chu Tuấn Thanh đề xuất cũng là hình thanh nhưng không được đồng thuận rộng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cân (196) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Cân (số 196) ở trên chữ Bối (số 241) . Hai cái rìu tượng trưng khí giới va chạm vì giành giật tiền bạc. Chất là chất vấn, nghi ngờ.", "Nghĩa Tiếng Việt_Xie": "chất lượng", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>斦貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "质", "Unihan_Traditional (Chữ Phồn thể)": "質", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm danh từ chỉ bản chất hoặc tính từ chỉ sự mộc mạc của sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畺', '{"9000": "", "Chữ Trung Quốc": "畺", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (247)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Điền (số 247) đặt giữa 3 nét ngang. 3 nét ngang tượng trưng những cái bờ phân chia mảnh ruộng (ranh giới đất đai).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴三畕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "三", "Unihan_Simplified (Chữ Giản thể)": "畺", "Unihan_Traditional (Chữ Phồn thể)": "畺", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奮', '{"9000": "", "Chữ Trung Quốc": "奮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đại (17) Chuy (175) Điền (247)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đại (17) , Chuy (175) và Điền (247) . Con chim (chuy) to gan lớn mật (đại) ra sức sà xuống mảnh ruộng (điền) nguy hiểm.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "奋", "Unihan_Traditional (Chữ Phồn thể)": "奮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畐', '{"9000": "", "Chữ Trung Quốc": "畐", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (1) Khẩu (6) Điền (247)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhất (1) , Khẩu (6) , Điền (247) . Những mảnh ruộng dài tới chân trời: xa là vệt ngang (nhất), hẹp (khẩu), gần (điền). Phúc là đầy đủ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('覔', '{"9000": "", "Chữ Trung Quốc": "覔", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bất (265) Kiến (56)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bất (số 265) ở trên chữ Kiến (số 110) . Bởi vì không (bất) nhìn thấy (kiến) cho nên mới phải đi tìm kiếm. Chữ chuẩn là 覓.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>不見", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "見", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屮', '{"9000": "", "Chữ Trung Quốc": "屮", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng một mầm cây cỏ non mới mọc nhú lên.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴丨凵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丨", "Unihan_Simplified (Chữ Giản thể)": "屮", "Unihan_Traditional (Chữ Phồn thể)": "屮", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甦', '{"9000": "", "Chữ Trung Quốc": "甦", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Canh (166) Sinh (272)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Canh (số 166 - sửa đổi) và chữ Sinh (số 272) . Nếu ta biết đem tâm ra tu sửa (canh) định mệnh sẽ được cải sinh, sống lại (tô) tốt đẹp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰更生", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "生", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芻', '{"9000": "", "Chữ Trung Quốc": "芻", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 艸 | Số nét | 10 | nét | 勹 | bao | biểu nghĩa | bàn tay cuộn lại | 屮 | triệt | biểu nghĩa | cỏ non mọc lên | 芻 = 勹 (bàn tay) + 屮 (cỏ non); chữ hội ý. Hình ảnh bàn tay cầm/nhổ cỏ — gợi hành động cắt cỏ cho gia súc ăn.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary: 芻 là chữ hội ý, gồm 勹 (bàn tay) và 屮 (cỏ), hình ảnh bàn tay nhổ cỏ. Giáp cốt văn, Kim văn, Bạch thư và Tiểu triện đều xác nhận cấu trúc này. Nghĩa gốc là cắt cỏ, cỏ khô; mở rộng sang gia súc, chăn nuôi, cỏ dùng làm thức ăn cho vật nuôi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (24) Triệt (269)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bao (số 20) và chữ Triệt (số 269) được viết hai lần. Hình những bó cỏ được cắt rồi đem về bao bọc lại cho gia súc ăn.", "Nghĩa Tiếng Việt_Xie": "nuôi (trâu, ngựa) bằng cỏ", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "刍", "Unihan_Traditional (Chữ Phồn thể)": "芻", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "so", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ cỏ khô làm thức ăn hoặc làm động từ chỉ hành động cắt cỏ chăn nuôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕪', '{"9000": "", "Chữ Trung Quốc": "蕪", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Vô", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 276) ở trên chữ Vô (không có) . Đất đai không có (vô) người chăm sóc nên cỏ (thảo) mọc bừa bãi lộn xộn, bỏ hoang. Giải thích sự chuyển ý: Chữ Vô (không có) chỉ âm, chữ Thảo (cỏ) chỉ ý. Vùng đất cỏ (Thảo) mọc um tùm, không có (Vô) dấu chân người qua lại gọi là hoang vu (Vu). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Vô và chữ Vu có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Vô và Vu).*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>艹無", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "無", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芜", "Unihan_Traditional (Chữ Phồn thể)": "蕪", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('並', '{"9000": "", "Chữ Trung Quốc": "並", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lập (284)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai chữ Lập (số 284) nối nét dưới. Hình ảnh hai người cùng đứng sánh vai nhau trên mặt đất, chỉ sự cùng nhau, sóng đôi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>䒑业", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "业", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "䒑", "Unihan_Simplified (Chữ Giản thể)": "并", "Unihan_Traditional (Chữ Phồn thể)": "並", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魚', '{"9000": "", "Chữ Trung Quốc": "魚", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 魚 | Số nét | 11 | nét | 魚 | ngư | tượng hình | hình con cá — đầu, thân, vây, đuôi | 魚 là chữ tượng hình: mô phỏng hình dạng con cá với đầu ở trên, thân giữa, đuôi ở dưới. Là bộ thủ độc lập (KangXi radical 195). Dạng cổ trong giáp cốt văn thể hiện rõ hình con cá.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 魚 (yú) là chữ tượng hình — liushu p (pictograph): vẽ hình con cá, có đầu, thân và đuôi. Wiktionary xác nhận liushu=p. Dạng bảo tồn 𤋳 còn giữ hình dạng gốc. Đây là một trong những chữ cổ nhất trong tiếng Hán, có đủ giáp cốt văn, kim văn, đại triện, tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng một con cá (có đầu, thân có vảy và cái đuôi).", "Nghĩa Tiếng Việt_Xie": "con cá", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鱼", "Unihan_Traditional (Chữ Phồn thể)": "魚", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ngư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ hoặc làm tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('魯', '{"9000": "", "Chữ Trung Quốc": "魯", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Ngư (288) Khẩu (6)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ngư (số 288) ở trên chữ Khẩu (số 6) . Kẻ ngu dốt giống như loài cá (ngư), có cái miệng (khẩu) mà không biết nói năng đối đáp.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>魚日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "魚", "Unihan_Simplified (Chữ Giản thể)": "鲁", "Unihan_Traditional (Chữ Phồn thể)": "魯", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳥', '{"9000": "", "Chữ Trung Quốc": "鳥", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng một con chim (có mỏ, mắt, lông cánh và chân).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鸟", "Unihan_Traditional (Chữ Phồn thể)": "鳥", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烏', '{"9000": "", "Chữ Trung Quốc": "烏", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (290)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chính là chữ Điểu (số 290) nhưng thiếu đi một nét ngang (con mắt). Con quạ toàn thân đen thui nên không nhìn thấy mắt nó đâu.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "乌", "Unihan_Traditional (Chữ Phồn thể)": "烏", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳴', '{"9000": "", "Chữ Trung Quốc": "鳴", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 鳥 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng, tiếng kêu | 鳥 | điểu | biểu nghĩa | chim | 鳴 = 口 (Khẩu, miệng) + 鳥 (Điểu, chim). Chữ hội ý: miệng của chim — tiếng chim hót, kêu.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt | Tiểu triện | Chữ hội ý gồm 口 (miệng) và 鳥 (chim) — miêu tả tiếng kêu của chim. Từ giáp cốt văn đã có hình dạng rõ ràng: một con chim há miệng cất tiếng. Ý nghĩa gốc là tiếng chim hót, mở rộng ra tiếng kêu của động vật nói chung, rồi đến nghĩa bóng là cất lên tiếng nói (鳴謝 — lên tiếng cảm ơn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Điểu (290)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khẩu (số 6) và chữ Điểu (số 290) . Hình ảnh con chim (điểu) đang mở miệng (khẩu) hót líu lo.", "Nghĩa Tiếng Việt_Xie": "hót (chim), gáy (gà)", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口鳥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鳥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "鸣", "Unihan_Traditional (Chữ Phồn thể)": "鳴", "Pinyin_Xie": "míng", "Âm Hán Việt_Xie": "minh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng sau chủ ngữ là chim muông hoặc nhạc cụ để chỉ việc phát ra âm thanh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馬', '{"9000": "", "Chữ Trung Quốc": "馬", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 馬 | Số nét | 10 | nét | 馬 | mã | tượng hình | con ngựa | 馬 là chữ tượng hình — hình vẽ con ngựa đứng thẳng, đầu quay trái, bờm tóc tung bay theo gió, đứng trên hai chân sau. Giáp cốt văn đã có dạng hình ngựa rõ ràng, trải qua kim văn, bạch thư, lệ thư đến khải thư ngày nay.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Giáp cốt văn | Kim văn | Bạch thư | Lệ thư | Khải thư | 馬 là chữ tượng hình (liushu=p): vẽ con ngựa đứng thẳng nhìn sang trái, bờm tóc bay, hai chân sau chống đỡ. Giáp cốt văn đã có dạng hình ngựa sinh động. Kim văn, bạch thư, lệ thư, khải thư đều lưu dạng tiến hóa rõ ràng từ hình ngựa cụ thể đến ký hiệu trừu tượng ngày nay. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng con ngựa (có bờm và 4 chân).", "Nghĩa Tiếng Việt_Xie": "con ngựa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "马", "Unihan_Traditional (Chữ Phồn thể)": "馬", "Pinyin_Xie": "mǎ", "Âm Hán Việt_Xie": "mã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm thành phần cấu tạo từ ghép chỉ các sự vật liên quan đến ngựa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馭', '{"9000": "", "Chữ Trung Quốc": "馭", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mã (293) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mã (số 293) và chữ Hựu (số 159 - bàn tay) . Bàn tay (hựu) cầm roi và dây cương để điều khiển con ngựa (mã).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰馬又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "馬", "Unihan_Simplified (Chữ Giản thể)": "驭", "Unihan_Traditional (Chữ Phồn thể)": "馭", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冖', '{"9000": "", "Chữ Trung Quốc": "冖", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng một vật (tấm khăn) đang úp lên phía trên để che đậy lại.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: msp", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "冖", "Unihan_Traditional (Chữ Phồn thể)": "冖", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夂', '{"9000": "", "Chữ Trung Quốc": "夂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ hai cái cẳng chân luôn đi từ phía sau đưa lên phía trước. Truy là đến từ phía sau.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴又㇒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "又", "Unihan_Simplified (Chữ Giản thể)": "夂", "Unihan_Traditional (Chữ Phồn thể)": "夂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冂', '{"9000": "", "Chữ Trung Quốc": "冂", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vòm không gian, chỉ vùng đất xa xôi ở biên giới của một ấp, một nước.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: me", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "冂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "冂", "Unihan_Traditional (Chữ Phồn thể)": "冂", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靈', '{"9000": "", "Chữ Trung Quốc": "靈", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 雨 | Số nét | 24 | nét | 霝 | linh | biểu âm | mưa nhỏ | 玉 | ngọc | biểu nghĩa | ngọc thạch | 靈 = 霝 (Linh, biểu âm) + 玉 (Ngọc, biểu nghĩa: ngọc thạch); chữ hình thanh theo Thuyết Văn. Tuy nhiên trong các dạng cổ (kim văn), bộ ngọc có thể được thay bằng 巫 (phù thuỷ), 心 (tim) hoặc 示 (bàn thờ) — chứng tỏ ý nghĩa \"linh\" liên quan đến phù thuỷ, tâm thần, thần linh.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 靈 theo Thuyết Văn là hình thanh: 霝 (linh, mưa nhỏ) biểu âm, 玉 (ngọc) biểu nghĩa. Theo Wiktionary, trong kim văn bộ ngọc có thể thay bằng 巫 (phù thuỷ), 心 (tim) hoặc 示 (bàn thờ). Điều này phản ánh nghĩa gốc: linh hồn, thần linh, hiệu nghiệm. Tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (90) Khẩu (6) Vu", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vũ (mưa) , 3 chữ Khẩu và chữ Vu (Công + 2 Nhân). Bàn thờ (công) đặt đồ cúng, nhiều miệng (khẩu) cầu mưa (vũ) và linh ứng. Giải thích sự chuyển ý: Chữ Lăng (gò mả) chỉ âm, chữ Vu (thầy cúng) chỉ ý. Thầy cúng (Vu) cầu mưa, giao tiếp với các thế lực siêu nhiên được coi là linh thiêng (Linh). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Lăng và chữ Linh có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Lăng và Linh).*", "Nghĩa Tiếng Việt_Xie": "tinh nhanh; linh hồn, tinh thần", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>雨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "灵", "Unihan_Traditional (Chữ Phồn thể)": "靈", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ phần tâm linh hoặc làm tính từ chỉ sự nhạy bén, hiệu nghiệm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貧', '{"9000": "", "Chữ Trung Quốc": "貧", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 11 | nét | 分 | phân | biểu âm | chia | 貝 | bối | biểu nghĩa | tiền bạc | 貧 = 分 (Phân, biểu âm) + 貝 (Bối, biểu nghĩa: tiền). Chữ hình thanh. 貝 chỉ ý nghĩa liên quan đến tiền của; 分 cho âm pín. Wiktionary gợi mnemonic: phân chia (分) tiền (貝) — chia nhỏ tiền ra là nghèo.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Lụa thư | Đại triện | Tiểu triện | Theo Wiktionary, 貧 là chữ hình thanh: 貝 (tiền/vỏ sò dùng làm tiền) biểu nghĩa, 分 biểu âm. Wiktionary còn nêu gợi ý: vì chữ 分 (phân chia) cũng mang nghĩa chia nhỏ, nên 貧 gợi hình ảnh tiền bị chia nhỏ đi = nghèo. Nghĩa hiện đại: nghèo túng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phân (326) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phân (số 326) ở trên chữ Bối (số 241) . Nếu cứ phân chia tiền bạc của cải (bối) ra mãi thì cuối cùng sẽ nghèo đi (bần). Giải thích sự chuyển ý: Chữ Phân (chia nhỏ) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Tiền bạc (Bối) mà cứ bị chia năm xẻ bảy (Phân) thì cuối cùng sẽ cạn kiệt, trở nên nghèo nàn (Bần). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Phân và chữ Bần có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Phân và Bần).*", "Nghĩa Tiếng Việt_Xie": "nghèo", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>分貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "贫", "Unihan_Traditional (Chữ Phồn thể)": "貧", "Pinyin_Xie": "pín", "Âm Hán Việt_Xie": "bần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ trong câu để chỉ sự nghèo khó. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('別', '{"9000": "", "Chữ Trung Quốc": "別", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Lánh (235) Đao (324)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lánh (số 235 - 另) và chữ Đao (số 324 - 刂) . Con dao (đao) cắt sự vật thành từng phần tách biệt, ở riêng ra (lánh).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "别", "Unihan_Traditional (Chữ Phồn thể)": "別", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戶', '{"9000": "", "Chữ Trung Quốc": "戶", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình vẽ mô phỏng một cánh cửa gỗ.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴⺁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "户", "Unihan_Traditional (Chữ Phồn thể)": "戶", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('爭', '{"9000": "", "Chữ Trung Quốc": "爭", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (340) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Trảo (số 340) , chữ Hựu (biến thể) và nét sổ. Hai bàn tay (trảo và hựu) đang tranh nhau một vật (nét sổ) ở giữa.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>爫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "争", "Unihan_Traditional (Chữ Phồn thể)": "爭", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愛', '{"9000": "", "Chữ Trung Quốc": "愛", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (340) Mịch (268) Tâm (148) Truy (316)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm Trảo (爫) , Mịch (冖) , Tâm (心) và Truy (夂) . Gà mẹ có tình yêu thương (tâm) luôn theo sát (truy) con, gặp ác điểu giương vuốt (trảo) thì xòe cánh che chở (mịch).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>夂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "爱", "Unihan_Traditional (Chữ Phồn thể)": "愛", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('島', '{"9000": "", "Chữ Trung Quốc": "島", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điểu (290) Sơn (44)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Điểu (số 290) ở trên chữ Sơn (số 46) . Đảo là những ngọn núi (sơn) mọc giữa biển, nơi chỉ có những loài chim (điểu) biển thường đậu lại nghỉ ngơi.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佈', '{"9000": "", "Chữ Trung Quốc": "佈", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Bố (227)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bố (số 227 - vải) chỉ âm, chữ Nhân (số 12 - nhân đứng) chỉ ý. Bố là người thông báo, công khai cho mọi người biết. Giải thích sự chuyển ý: Chữ Bố (vải) chỉ âm, chữ Nhân (người) chỉ ý. Người (Nhân) thời xưa hay dùng tấm vải (Bố) để viết cáo thị công khai cho mọi người biết (Bố cáo).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻布", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "布", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "布", "Unihan_Traditional (Chữ Phồn thể)": "佈", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偵', '{"9000": "", "Chữ Trung Quốc": "偵", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Trinh (242)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trinh (số 243) chỉ âm, chữ Nhân (số 12) chỉ ý. Trinh là người làm nhiệm vụ dò xét, điều tra, thăm dò (trinh sát). Giải thích sự chuyển ý: Chữ Trinh (bói toán) chỉ âm, chữ Nhân (người) chỉ ý. Người (Nhân) chuyên đi dò xét, bói toán (Trinh) để tìm ra sự thật gọi là trinh sát (Trinh).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻貞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侦", "Unihan_Traditional (Chữ Phồn thể)": "偵", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗚', '{"9000": "", "Chữ Trung Quốc": "嗚", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Ô (291)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Ô (số 291 - con quạ) chỉ âm, chữ Khẩu (số 6 - cái miệng) chỉ ý. Ô là lời than thở, tiếng kêu bày tỏ sự ngạc nhiên từ miệng. Giải thích sự chuyển ý: Chữ Ô (số 291) mô phỏng con quạ đen. Tiếng quạ kêu thường buồn bã, bi thương. Khi thêm bộ Khẩu (cái miệng), chữ này dùng để chỉ tiếng kêu than, tiếng nấc nghẹn ngào của con người.", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口烏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "烏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呜", "Unihan_Traditional (Chữ Phồn thể)": "嗚", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懾', '{"9000": "", "Chữ Trung Quốc": "懾", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Nhiếp", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148 - tâm đứng) và chữ Nhiếp (3 chữ Nhĩ) . Nhiếp là dùng uy lực làm cho người khác khiếp sợ. Giải thích sự chuyển ý: Chữ Nhiếp (nói nhỏ vào tai) chỉ âm, chữ Tâm (lòng) chỉ ý. Dùng lời nói uy hiếp, làm cho tâm trí (Tâm) người khác run sợ gọi là uy nhiếp (Nhiếp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄聶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('棟', '{"9000": "", "Chữ Trung Quốc": "棟", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Đông (126)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 79 - cây gỗ) và chữ Đông (số 256 - phương đông) . Cây gỗ lớn nằm ngang trên nóc nhà làm trụ cột gọi là đống (rường cột). Giải thích sự chuyển ý: Chữ Đông (phương đông) chỉ âm, chữ Mộc (gỗ) chỉ ý. Thanh gỗ (Mộc) to nhất, vững chắc nhất dùng làm rường cột cho căn nhà (Đống). *(Biến âm Hán Việt: Đông -> Đống)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木東", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "東", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栋", "Unihan_Traditional (Chữ Phồn thể)": "棟", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攝', '{"9000": "", "Chữ Trung Quốc": "攝", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (189) Nhiếp", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủ (số 64) và chữ Nhiếp (3 chữ Nhĩ) . Dùng tay (Thủ) để thu gom, thâu tóm mọi âm thanh từ các tai (Nhiếp) gọi là thu nhiếp, nhiếp ảnh. Giải thích sự chuyển ý: Chữ Nhiếp (nói nhỏ vào tai) chỉ âm, chữ Thủ (tay) chỉ ý. Dùng tay (Thủ) thâu tóm, thu thập (Nhiếp).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌聶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摄", "Unihan_Traditional (Chữ Phồn thể)": "攝", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泆', '{"9000": "", "Chữ Trung Quốc": "泆", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Thất (5)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76) và chữ Thất (số 343 - mất) . Nước (Thủy) chảy tràn ra ngoài làm mất đi (Thất) phần nước bên trong gọi là tràn dật. Giải thích sự chuyển ý: Chữ Thất (mất mát) chỉ âm, chữ Thủy (nước) chỉ ý. Nước (Thủy) chảy tràn lan ra ngoài (Dật). *(Biến âm Hán Việt: Thất -> Dật)*", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泆", "Unihan_Traditional (Chữ Phồn thể)": "泆", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('種', '{"9000": "", "Chữ Trung Quốc": "種", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 禾 | Số nét | 14 | nét | 禾 | hòa | biểu nghĩa | lúa, cây lương thực | 重 | trùng | biểu âm | nặng, nhiều lớp | 種 = 禾 (Hòa, biểu nghĩa: lúa/cây trồng) + 重 (Trùng, biểu âm). Chữ hình thanh — 禾 chỉ lĩnh vực nông nghiệp, 重 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary, 種 là chữ hình thanh: 禾 (lúa) biểu nghĩa, 重 biểu âm. Chữ chỉ hạt giống, giống loài hoặc hành động gieo trồng. Dạng tiểu triện đã có cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (117) Trọng (174)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hòa (số 115 - cây lúa) và chữ Trọng (số 166 - nặng) . Những hạt lúa (Hòa) hạt nào nặng (Trọng) và chắc khỏe thì được giữ lại làm hạt giống (Chủng) để đem đi gieo trồng. Giải thích sự chuyển ý: Chữ Trọng (nặng nề) chỉ âm, chữ Hòa (lúa) chỉ ý. Những hạt lúa (Hòa) mẩy, nặng được dùng làm hạt giống (Chủng) hoặc mang gieo xuống đất (Trúng). *(Biến âm Hán Việt: Trọng -> Chủng)*", "Nghĩa Tiếng Việt_Xie": "giống loài", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾重", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "种", "Unihan_Traditional (Chữ Phồn thể)": "種", "Pinyin_Xie": "zhǒng", "Âm Hán Việt_Xie": "chúng, chủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Động từ | 动词 | Chữ này làm danh từ chỉ chủng loại hoặc làm lượng từ đứng trước danh từ để phân loại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貢', '{"9000": "", "Chữ Trung Quốc": "貢", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 10 | nét | 工 | công | biểu âm | công việc, thợ | 貝 | bối | biểu nghĩa | vỏ sò, tiền bạc, của cải | 貢 = 工 (Công, biểu âm) + 貝 (Bối, biểu nghĩa: tiền/của cải). Chữ hình thanh (psc): bộ 貝 liên quan đến của cải vật chất, 工 cho âm gòng. Nghĩa là dâng cống phẩm, nộp của cải lên trên.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Theo Wiktionary: 貢 = 工 (biểu âm) + 貝 (vỏ sò/tiền bạc, biểu nghĩa). Nghĩa gốc là dâng của cải lên bề trên — cống phẩm, triều cống. Có tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Công (167) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Công (số 48 - người thợ) ở trên chữ Bối (số 154 - tiền bạc/vỏ sò) . Người thợ (Công) làm ra những vật phẩm có giá trị, tiền bạc (Bối) đem dâng lên bề trên gọi là triều cống, cống hiến. Giải thích sự chuyển ý: Chữ Công (thợ) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Dâng nạp tiền bạc, của cải (Bối) lên bề trên gọi là triều cống (Cống).", "Nghĩa Tiếng Việt_Xie": "cống phẩm", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>工貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "工", "Unihan_Simplified (Chữ Giản thể)": "贡", "Unihan_Traditional (Chữ Phồn thể)": "貢", "Pinyin_Xie": "gòng", "Âm Hán Việt_Xie": "cống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ chỉ hành động dâng nạp lễ vật hoặc làm danh từ chỉ chính vật phẩm đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('貨', '{"9000": "", "Chữ Trung Quốc": "貨", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 11 | nét | 化 | hoa | biểu âm | 貝 | bối | biểu nghĩa | vỏ sò, tiền tệ | 貨 = 化 (Hoa, biểu âm) + 貝 (Bối, biểu nghĩa: vỏ sò/tiền); chữ hình thanh. Phần 貝 cho biết liên quan tới hàng hoá có giá trị trao đổi, phần 化 cho âm đọc.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Bạch thư | Đại triện | Tiểu triện | 貨 là chữ hình thanh: 化 (hoa, biểu âm) + 貝 (bối, biểu nghĩa vỏ sò/tiền). Thời cổ vỏ sò là phương tiện trao đổi, nên bộ 貝 biểu thị hàng hoá giá trị. Dạng bạch thư, đại triện và tiểu triện đều lưu lại. Nghĩa: hàng hoá, sản phẩm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hóa (47) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hóa (số 44 - biến hóa) ở trên chữ Bối (số 154 - tiền bạc) . Tiền bạc của cải (Bối) có thể biến hóa (Hóa) trao đổi thành mọi thứ trên đời gọi là hàng hóa. Giải thích sự chuyển ý: Chữ Hóa (biến hóa) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Của cải, vật chất (Bối) dùng để trao đổi, mua bán gọi là hàng hóa (Hóa).", "Nghĩa Tiếng Việt_Xie": "hàng hóa", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>化貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "化", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "货", "Unihan_Traditional (Chữ Phồn thể)": "貨", "Pinyin_Xie": "huò", "Âm Hán Việt_Xie": "hoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này chủ yếu làm danh từ chỉ hàng hóa hoặc tiền tệ trong giao thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('資', '{"9000": "", "Chữ Trung Quốc": "資", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 13 | nét | 次 | thứ | biểu âm | 貝 | bối | biểu nghĩa | vỏ sò — tiền tệ cổ đại | 資 = 次 (Thứ, biểu âm) + 貝 (Bối, biểu nghĩa: vỏ sò dùng làm tiền); chữ hình thanh. Phần 貝 gợi tài sản, của cải; 次 cho âm zī.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Đại triện | Theo Wiktionary, 資 là chữ hình thanh: 次 (thứ, biểu âm) kết hợp với 貝 (bối, biểu nghĩa: vỏ sò — tiền tệ cổ). Nghĩa gốc: tài sản, nguồn lực giàu có. Mở rộng ra: vốn, chi phí, tư chất, điều kiện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thứ (30) Bối (241)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thứ (số 30 - thứ bậc/kế tiếp) ở trên chữ Bối (số 154 - tiền bạc) . Sau khi tiêu xài, phần tiền bạc (Bối) còn giữ lại để dành cho những lần tiếp theo (Thứ) gọi là vốn liếng, tư bản. Giải thích sự chuyển ý: Chữ Thứ (thứ bậc) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Tiền bạc của cải (Bối) dùng làm vốn liếng để kinh doanh gọi là tư bản (Tư).", "Nghĩa Tiếng Việt_Xie": "Thủ đô", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>次貝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "资", "Unihan_Traditional (Chữ Phồn thể)": "資", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ tiền tài, tư chất hoặc làm động từ với nghĩa cung cấp, giúp đỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('財', '{"9000": "", "Chữ Trung Quốc": "財", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 貝 | Số nét | 10 | nét | 貝 | bối | biểu nghĩa | vỏ sò, tiền | 才 | tài | biểu âm | tài năng | 財 = 貝 (Bối, biểu nghĩa: vỏ sò dùng làm tiền) + 才 (Tài, biểu âm); chữ hình thanh (psc). Bối (vỏ sò) là đơn vị tiền tệ cổ đại; 才 cho âm và gợi ý tài năng/khả năng tài chính.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | 財 (cái): chữ hình thanh, gồm 貝 (biểu nghĩa: vỏ sò/tiền) và 才 (Tài, biểu âm). 才 còn gợi đến năng lực, tài năng — tài sản vừa là tiền của vừa là khả năng tạo ra của cải. Chữ đã xuất hiện từ thời tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bối (241) Tài (214)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bối (số 154 - tiền bạc) và chữ Tài (số 75 - tài năng) . Người có tài năng (Tài) thì chắc chắn sẽ làm ra nhiều tiền bạc, của cải (Bối) gọi là tiền tài. Giải thích sự chuyển ý: Chữ Tài (tài năng) chỉ âm, chữ Bối (tiền bạc) chỉ ý. Tiền bạc, của cải vật chất (Bối) nói chung được gọi là tiền tài (Tài).", "Nghĩa Tiếng Việt_Xie": "sự giàu có", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰貝才", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "才", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "貝", "Unihan_Simplified (Chữ Giản thể)": "财", "Unihan_Traditional (Chữ Phồn thể)": "財", "Pinyin_Xie": "cái", "Âm Hán Việt_Xie": "tài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ sở hữu hoặc làm tân ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圓', '{"9000": "", "Chữ Trung Quốc": "圓", "Bộ thủ & thành phần_Xie": "", "Hán Việt_Xie": "", "Tự nguyên_Xie": "", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (132) Viên (243)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vi (số 31 - vây quanh) bao ngoài chữ Viên (số 30 - nhân viên) . Các nhân viên (Viên) đứng quây thành một vòng tròn bao quanh (Vi) gọi là viên mãn, hình tròn. Giải thích sự chuyển ý: Chữ Viên (nhân viên) chỉ âm, chữ Vi (vây quanh) chỉ ý. Hình khối khép kín vây quanh (Vi) không có góc cạnh gọi là hình tròn (Viên).", "Nghĩa Tiếng Việt_Xie": "", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗員", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "員", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圆", "Unihan_Traditional (Chữ Phồn thể)": "圓", "Pinyin_Xie": "", "Âm Hán Việt_Xie": "", "Loại từ & Cách dùng_Xie": "", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('製', '{"9000": "", "Chữ Trung Quốc": "製", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 衣 | Số nét | 14 | nét | 制 | chế | biểu âm | cắt ra, chế tạo | 衣 | y | biểu nghĩa | quần áo | 製 = 制 (Chế, biểu âm: cắt ra, chế tạo) + 衣 (Y, biểu nghĩa: quần áo); kết hợp hình thanh và hội ý. Nghĩa gốc là may cắt quần áo.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Tiểu triện | Lục thư thông | 製 kết hợp hình thanh và hội ý: 制 (chế/cắt) cho cả âm và nghĩa, 衣 (quần áo) cho nghĩa cụ thể. Nghĩa gốc là cắt may quần áo, mở rộng sang chế tạo, sản xuất nói chung. Có dạng tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chế (331) Y (295)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Chế (số 18 - dao cắt / hạn chế) ở trên chữ Y (số 145 - áo quần) . Dùng dao cắt (Chế) tạo ra một bộ quần áo (Y) mới gọi là chế tạo, may mặc. Giải thích sự chuyển ý: Chữ Chế (chế ngự/cắt đứt) chỉ âm, chữ Y (quần áo) chỉ ý. Cắt may áo quần (Y), tạo ra sản phẩm mới gọi là chế tạo (Chế).", "Nghĩa Tiếng Việt_Xie": "hệ thống", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "<ctrl42> (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "<ctrl42>制衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "制", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "", "Unihan_Traditional (Chữ Phồn thể)": "", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ đứng trước danh từ để chỉ hoạt động sản xuất, chế tạo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裏', '{"9000": "", "Chữ Trung Quốc": "裏", "Bộ thủ & thành phần_Xie": "Bộ thủ & thành phần | Bộ thủ | 衣 | Số nét | 13 | nét | 衣 | y | biểu nghĩa | quần áo, lớp vải bên ngoài | 里 | lý | biểu âm | bên trong, lý | 裏 = 衣 (Y, biểu nghĩa: quần áo) + 里 (Lý, biểu âm); chữ hình thanh. Phần 衣 gợi lớp vải, phần 里 vừa cho âm lǐ vừa gợi nghĩa bên trong.", "Hán Việt_Xie": "", "Tự nguyên_Xie": "Tự nguyên (nguồn gốc chữ) | Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 裏 là dạng truyền thống chuẩn của 裡 (theo Commonly Used Standard Chinese Characters của Trung Hoa đại lục). Chữ hình thanh: 衣 (y, quần áo) làm phần biểu nghĩa chỉ lớp lót/mặt trong của vải, 里 (lý) làm phần biểu âm. Kim văn ghi nhận nhiều biến thể hình dạng. Nghĩa gốc: mặt trong của quần áo, sau mở rộng thành bên trong nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (295) Lý (130)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Y (số 145 - áo quần) bọc ngoài chữ Lý (số 166 - làng xóm) . Làng xóm (Lý) được bao bọc, che chở trong lớp áo (Y) nghĩa là ở bên trong, nội lý. Giải thích sự chuyển ý: Chữ Lý (làng xóm) chỉ âm, chữ Y (quần áo) chỉ ý. Lớp lót ở bên trong áo quần (Y) mở rộng ra chỉ bên trong, nội lý (Lý).", "Nghĩa Tiếng Việt_Xie": "bên trong", "Hạng Tần Suất (Jun Da)": "", "Tần Suất % (Jun Da)": "", "GavinGrover_Once (Chiết tự trực tiếp)": "character | components", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "里", "Unihan_Traditional (Chữ Phồn thể)": "裏", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ chỉ phương vị | 方位词 | Danh từ | 名词 | Thường đứng sau danh từ khác để chỉ vị trí bên trong hoặc làm danh từ chỉ lớp lót áo. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
